#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Raspberry Pi 4 Model B - MLX91219 Hall-effect current sensor reader
 * via ADS1115 analog-to-digital converter (I2C).
 *
 * Wiring:
 *   MLX91219 VOUT -> ADS1115 AIN0
 *   ADS1115 SDA  -> Pi GPIO2 (I2C bus 1)
 *   ADS1115 SCL  -> Pi GPIO3 (I2C bus 1)
 *   ADS1115 ADDR -> GND  (I2C address 0x48)
 *
 * Build: gcc -Wall -Wextra -O2 -o mlx91219_reader mlx91219_reader.c -lpigpio -lrt
 * Run:   sudo ./mlx91219_reader
 */

#define I2C_BUS        1
#define ADS1115_ADDR   0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION  0x00
#define ADS1115_REG_CONFIG      0x01

/*
 * Config register (16-bit, big-endian on the bus):
 *   [15]    OS       = 1  (begin single conversion)
 *   [14:12] MUX      = 100 (AIN0 single-ended)
 *   [11:9]  PGA      = 001 (±4.096 V)
 *   [8]     MODE     = 1  (single-shot)
 *   [7:5]   DR       = 100 (128 SPS)
 *   [4]     COMP_MODE= 0
 *   [3]     COMP_POL = 0
 *   [2]     COMP_LAT = 0
 *   [1:0]   COMP_QUE = 11 (disable comparator)
 *
 * Binary: 1 100 001 1 100 0 0 0 11 -> 0xC283
 */
#define ADS1115_CONFIG 0xC283

/* MLX91219 parameters */
#define MLX91219_SENSITIVITY  0.040f   /* V/A */
#define MLX91219_ZERO_OFFSET  2.5f     /* V  -> mid-supply zero current */
#define ADS1115_PGA_RANGE     4.096f   /* V  */
#define ADS1115_MAX_COUNT     32767.0f /* 16-bit signed positive max */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a 16-bit value to an ADS1115 register.
 * pigpio's i2cWriteI2CBlockData sends the first byte as the register
 * pointer, followed by the payload bytes, so we must send them in
 * big-endian order to match the ADS1115's register-expectation.
 */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteI2CBlockData(handle, reg, buf + 1, 2) < 0) {
        fprintf(stderr, "Error: i2cWriteI2CBlockData failed for reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register.
 * pigpio's i2cReadI2CBlockData writes the register pointer, then reads
 * the requested number of bytes. We must read in big-endian order.
 */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *value)
{
    char buf[2];

    if (i2cReadI2CBlockData(handle, reg, buf, 2) < 0) {
        fprintf(stderr, "Error: i2cReadI2CBlockData failed for reg 0x%02X\n", reg);
        return -1;
    }

    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Trigger a single-shot conversion on AIN0 and read the result.
 * Returns 0 on success, -1 on I2C error.
 */
static int ads1115_read_ain0(int handle, int16_t *adc_value)
{
    uint16_t config = ADS1115_CONFIG;

    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) < 0)
        return -1;

    /*
     * Wait for the conversion to complete. At 128 SPS the conversion
     * takes ~8 ms; we poll the OS bit (bit 15) every 2 ms for up to
     * 50 ms.
     */
    for (int i = 0; i < 25; i++) {
        uint16_t cfg;
        if (ads1115_read_reg(handle, ADS1115_REG_CONFIG, &cfg) < 0)
            return -1;
        if (cfg & 0x8000) {
            uint16_t raw;
            if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &raw) < 0)
                return -1;
            *adc_value = (int16_t)raw;
            return 0;
        }
        gpioDelay(2000); /* 2 ms */
    }

    fprintf(stderr, "Error: ADS1115 conversion timeout\n");
    return -1;
}

static float adc_to_current(int16_t adc_value)
{
    float voltage = ((float)adc_value / ADS1115_MAX_COUNT) * ADS1115_PGA_RANGE;
    return (voltage - MLX91219_ZERO_OFFSET) / MLX91219_SENSITIVITY;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). "
                        "Check wiring and that the ADS1115 is present at 0x%02X.\n",
                        g_i2c_handle, ADS1115_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX91219 current sensor reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t adc_value;

        if (ads1115_read_ain0(g_i2c_handle, &adc_value) < 0) {
            fprintf(stderr, "Warning: sensor read failed; will retry next cycle.\n");
            gpioDelay(500000);
            continue;
        }

        float current = adc_to_current(adc_value);
        printf("Current: %.3f A\n", current);

        gpioDelay(500000); /* 500 ms */
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

