#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define FLAME_SENSOR_PIN    4       /* KY-026 digital out  -> GPIO4  (internal pull-up) */
#define BUZZER_PIN          27      /* Active HIGH buzzer   -> GPIO27 */
#define I2C_BUS             1       /* /dev/i2c-1 on RPi 3B+ */
#define ADS1115_ADDR        0x48    /* ADS1115 default I2C address (ADDR->GND) */
#define ADS1115_CONV_REG    0x00    /* Conversion register */
#define ADS1115_CONFIG_REG  0x01    /* Config register */
#define ADC_CHANNEL         0       /* AIN0 single-ended */
#define ADC_GAIN            4.096   /* ±4.096 V */
#define ADC_MAX_COUNT       32767.0 /* 16-bit signed, positive max */
#define ADC_VREF            3.3     /* RPi 3B+ 3.3 V rail */
#define TEMP_MIN            20.0    /* °C at 0 V */
#define TEMP_MAX            80.0    /* °C at 3.3 V */
#define TEMP_THRESHOLD      60.0    /* °C */
#define POLL_INTERVAL_US    100000  /* 100 ms */
#define FLAME_DEBOUNCE_US   50000   /* 50 ms */
#define BUZZER_DURATION_US  2000000 /* 2 s */

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_flame_event = 0;
static volatile uint32_t     g_last_flame_tick = 0;
static FILE                 *g_log_file = NULL;
static int                   g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void flame_isr(int gpio, int level, uint32_t tick, void *userdata);
static int  read_temperature(double *temp_c);
static void log_event(const char *msg);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- ISR --------------------------------------- */
static void flame_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 0) { /* falling edge: flame detected */
        uint32_t elapsed = tick - g_last_flame_tick;
        if (elapsed >= FLAME_DEBOUNCE_US) {
            g_flame_event = 1;
            g_last_flame_tick = tick;
        }
    }
}

/* ----------------------------- Temperature ------------------------------- */
static int read_temperature(double *temp_c)
{
    /*
     * ADS1115 config (16-bit, big-endian on the bus):
     *   Bit 15    OS       = 1  (begin single conversion)
     *   Bits14:12 MUX      = 100 (AIN0 single-ended)
     *   Bits11:9  PGA      = 001 (+/-4.096 V)
     *   Bit 8     MODE     = 1  (single-shot)
     *   Bits7:5   DR       = 100 (128 SPS)
     *   Bit 4     COMP_MODE= 0
     *   Bit 3     COMP_POL = 0
     *   Bit 2     COMP_LAT = 0
     *   Bits1:0   COMP_QUE = 11 (disable comparator)
     * => 0xC283
     */
    uint16_t config = 0xC283;
    char cfg[3] = {
        (char)(config >> 8),
        (char)(config & 0xFF),
        0x00  /* pointer byte: point to conversion register */
    };

    if (i2cWriteI2CBlockData(g_i2c_handle, ADS1115_CONFIG_REG, &cfg[1], 2) < 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config register\n");
        return -1;
    }

    /* Conversion takes ~8.5 ms at 128 SPS; wait 10 ms to be safe */
    gpioDelay(10000);

    char reg = (char)ADS1115_CONV_REG;
    char raw[2] = {0, 0};
    if (i2cWriteDevice(g_i2c_handle, &reg, 1) < 0) {
        fprintf(stderr, "Error: failed to set ADS1115 conversion register pointer\n");
        return -1;
    }
    if (i2cReadDevice(g_i2c_handle, raw, 2) != 2) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion register\n");
        return -1;
    }

    int16_t adc = (int16_t)(((uint16_t)(uint8_t)raw[0] << 8) | (uint8_t)raw[1]);
    double voltage = ((double)adc / ADC_MAX_COUNT) * ADC_VREF;
    *temp_c = TEMP_MIN + (voltage / ADC_VREF) * (TEMP_MAX - TEMP_MIN);
    return 0;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(const char *msg)
{
    if (!g_log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_file, "[%s] %s\n", ts, msg);
    fflush(g_log_file);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure buzzer is off before terminating pigpio */
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    /* Open log file */
    g_log_file = fopen("fire_log.txt", "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: cannot open fire_log.txt for appending\n");
        gpioTerminate();
        return 1;
    }

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: cannot open I2C bus %d at address 0x%02X\n",
                I2C_BUS, ADS1115_ADDR);
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        return 1;
    }

    /* Configure flame sensor pin: input with internal pull-up */
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set GPIO%d as input\n", FLAME_SENSOR_PIN);
        cleanup();
        return 1;
    }
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP);

    /* Configure buzzer pin: output, initially off */
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set GPIO%d as output\n", BUZZER_PIN);
        cleanup();
        return 1;
    }
    gpioWrite(BUZZER_PIN, 0);

    /* Register flame sensor ISR (falling edge) */
    if (gpioSetISRFuncEx(FLAME_SENSOR_PIN, FALLING_EDGE, 0, flame_isr, NULL) < 0) {
        fprintf(stderr, "Error: cannot register ISR on GPIO%d\n", FLAME_SENSOR_PIN);
        cleanup();
        return 1;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Fire detection system started. Press Ctrl+C to exit.\n");
    log_event("System started");

    while (g_running) {
        int flame = gpioRead(FLAME_SENSOR_PIN);
        int flame_event = g_flame_event;
        g_flame_event = 0;

        double temp = 0.0;
        int temp_ok = (read_temperature(&temp) == 0);

        if (flame_event && temp_ok && temp > TEMP_THRESHOLD) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "FIRE DETECTED: flame + temperature %.2f C > %.1f C",
                     temp, TEMP_THRESHOLD);
            log_event(msg);
            printf("%s\n", msg);

            gpioWrite(BUZZER_PIN, 1);
            gpioDelay(BUZZER_DURATION_US);
            gpioWrite(BUZZER_PIN, 0);
        } else if (flame_event) {
            log_event("Flame detected!");
            printf("Flame detected!\n");
        } else if (temp_ok && temp > TEMP_THRESHOLD) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Temperature: %.2f C (above threshold)", temp);
            log_event(msg);
            printf("%s\n", msg);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    log_event("System stopped");
    cleanup();
    return 0;
}

