/* Current conversion                                                  */
/* ------------------------------------------------------------------ */

static float adc_to_current(int adc_value, float sensitivity)
{
    /* MCP3008: 10-bit, VREF = 3.3 V  ->  3.3 V / 1023 */
    float voltage = (float)adc_value * (3.3f / 1023.0f);
    return voltage / sensitivity;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_current(FILE *fp, float current, int fan_state)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Current: %.3f A, Fan: %s\n",
            ts, current, fan_state ? "ON" : "OFF");
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    float sensitivity = DEFAULT_SENSITIVITY;
    float threshold   = DEFAULT_THRESHOLD;
    const char *log_file = DEFAULT_LOG_FILE;
    int opt;

    while ((opt = getopt(argc, argv, "s:t:l:")) != -1) {
        switch (opt) {
        case 's':
            sensitivity = (float)atof(optarg);
            if (sensitivity <= 0.0f) {
                fprintf(stderr, "Sensitivity must be positive\n");
                return EXIT_FAILURE;
            }
            break;
        case 't':
            threshold = (float)atof(optarg);
            if (threshold < 0.0f) {
                fprintf(stderr, "Threshold must be non-negative\n");
                return EXIT_FAILURE;
            }
            break;
        case 'l':
            log_file = optarg;
            break;
        default:
            fprintf(stderr, "Usage: %s [-s sensitivity] [-t threshold] [-l log_file]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    /* ---- signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- SPI ---- */
    int spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0)
        return EXIT_FAILURE;

    /* ---- GPIO (libgpiod) ---- */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        /* Fallback: try gpiochip0 */
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *fan_line = gpiod_chip_get_line(chip, FAN_GPIO_LINE);
    if (!fan_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", FAN_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(fan_line, "current_monitor", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    FILE *log_fp = fopen(log_file, "a");
    if (!log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", log_file, strerror(errno));
        gpiod_line_release(fan_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("MLX91219 Current Monitor (MCP3008 ADC, GPIO18 Fan)\n");
    printf("Sensitivity: %.3f V/A  Threshold: %.2f A  Log: %s\n",
           sensitivity, threshold, log_file);

    /* ---- Main loop ---- */
    while (g_running) {
        int adc = mcp3008_read(spi_fd, 0);
        if (adc < 0) {
            fprintf(stderr, "SPI read failed; retrying next cycle\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        /* Sensor-absent / bus-error heuristics */
        if (adc == 0 || adc == 1023) {
            fprintf(stderr, "Warning: ADC saturated (%d) — sensor absent or wiring fault\n", adc);
        }

        float current = adc_to_current(adc, sensitivity);
        int fan_state = (current > threshold) ? 1 : 0;

        if (gpiod_line_set_value(fan_line, fan_state) < 0) {
            fprintf(stderr, "gpiod_line_set_value: %s\n", strerror(errno));
        }

        log_current(log_fp, current, fan_state);
        printf("Current: %.3f A  Fan: %s\n", current, fan_state ? "ON" : "OFF");

        sleep(SAMPLE_INTERVAL_SEC);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpiod_line_set_value(fan_line, 0);
    gpiod_line_release(fan_line);
    gpiod_chip_close(chip);
    fclose(log_fp);
    close(spi_fd);

    return EXIT_SUCCESS;
}

