    // Config register: 0x01, 0xC3E3 (1100 0011 1110 0011)
    // Conversion register: 0x00
    char config[3] = {0x01, 0xC3, 0xE3};
    char read_buf[2];

    // Write config to start conversion
    if (i2cWriteDevice(handle, config, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion (128 SPS -> ~8ms, add margin)
    gpioDelay(10000); // 10ms

    // Read conversion result
    if (i2cReadI2CBlockData(handle, 0x00, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // Combine bytes (ADS1115 returns MSB first)
    *raw_value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Function to calculate CO concentration in PPM
float calculate_ppm(int raw_value) {
    // Convert raw ADC value to resistance
    float resistance = (ADC_RESOLUTION / (float)raw_value) * 10000.0; // Assuming 10k load resistor

    // Calculate PPM using logarithmic curve (example formula)
    float ppm = 100.0 * powf(resistance / ZERO_RESISTANCE, -SENSITIVITY);

    return ppm;
}

// Function to log data to file
int log_data(float ppm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s, %.2f PPM\n", timestamp, ppm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("CO monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int raw_value;
        if (read_sensor_data(i2c_handle, &raw_value) == 0) {
            float ppm = calculate_ppm(raw_value);
            if (log_data(ppm) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(SLEEP_INTERVAL);
    }

    // Cleanup
    cleanup();
    printf("CO monitoring stopped.\n");

    return 0;
}

