#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x1D // Default I2C address for MICS-4514
#define CO_THRESHOLD 25.0 // PPM
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define READ_INTERVAL 5 // seconds

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int handle, int *ox, int *red);
float calculate_co_ppm(int ox, int red);
int log_data(float co_ppm);
int log_alert(float co_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

// Function to read sensor data from the MICS-4514
int read_sensor_data(int handle, int *ox, int *red) {
    char buffer[4];
    int result;

    // Read 4 bytes from the sensor
    result = i2cReadDevice(handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Extract 16-bit ADC values (OX and RED)
    *ox = (buffer[0] << 8) | buffer[1];
    *red = (buffer[2] << 8) | buffer[3];

    return 0;
}

// Function to calculate CO level in PPM
float calculate_co_ppm(int ox, int red) {
    // Placeholder formula - replace with actual calibration data
    return (float)ox * 0.1f + (float)red * 0.05f;
}

// Function to log data to a file
int log_data(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f PPM\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    fclose(fp);
    return 0;
}

// Function to log alerts to a file
int log_alert(float co_ppm) {
    FILE *fp = fopen(ALERT_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alert log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, CO level exceeded threshold: %.2f PPM\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("CO Monitoring System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int ox, red;

        // Read sensor data
        if (read_sensor_data(i2c_handle, &ox, &red) == 0) {
            // Calculate CO level
            float co_ppm = calculate_co_ppm(ox, red);

            // Log data
            if (log_data(co_ppm) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            // Check for CO threshold violation
            if (co_ppm > CO_THRESHOLD) {
                if (log_alert(co_ppm) != 0) {
                    fprintf(stderr, "Error logging alert\n");
                }
            }

            printf("CO level: %.2f PPM\n", co_ppm);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 5 seconds
        gpioSleep(PI_TIME_RELATIVE, READ_INTERVAL, 0);
    }

    // Cleanup
    cleanup();
    printf("CO Monitoring System stopped.\n");

    return 0;
}

