#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49
#define REG 0x00
#define SAMPLE_INTERVAL_US 100000
#define MIC_SENSITIVITY_DB_V 38.0
#define REF_PRESSURE_PA 20e-6

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_microphone(int handle, int *out_raw) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, REG, buf, 2);
    if (rc != 2) {
        return -1;
    }
    *out_raw = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static double calculate_spl(int raw) {
    double voltage = (double)raw * 3.3 / 65535.0;
    double pressure = (voltage / 1000.0) * REF_PRESSURE_PA;
    if (pressure <= 0.0) {
        return -999.0;
    }
    return 20.0 * log10(pressure / REF_PRESSURE_PA);
}

static void log_data(double spl1, double spl2, double avg) {
    FILE *fp = fopen("audio_log.txt", "a");
    if (!fp) {
        perror("fopen");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, spl1, spl2, avg);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, MIC1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C for mic1 (0x%02X): %d\n", MIC1_ADDR, i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, MIC2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C for mic2 (0x%02X): %d\n", MIC2_ADDR, i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int raw1 = 0, raw2 = 0;
        int ok1 = read_microphone(i2c_handle1, &raw1);
        int ok2 = read_microphone(i2c_handle2, &raw2);

        double spl1 = (ok1 == 0) ? calculate_spl(raw1) : -999.0;
        double spl2 = (ok2 == 0) ? calculate_spl(raw2) : -999.0;

        double avg = (spl1 + spl2) / 2.0;
        if (spl1 == -999.0 || spl2 == -999.0) {
            avg = -999.0;
        }

        log_data(spl1, spl2, avg);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    gpioTerminate();
    return 0;
}

