#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0          // SPI0 CE0
#define SPI_SPEED 1000000      // 1 MHz
#define MCP3008_CHANNEL_1 0    // MCP3008 channel for mic 1
#define MCP3008_CHANNEL_2 1    // MCP3008 channel for mic 2
#define LED_GPIO 27
#define THRESHOLD 0.7          // RMS threshold (normalized 0-1)
#define SAMPLE_RATE 1000       // 1 kHz
#define SAMPLE_WINDOW_MS 100   // 100 ms
#define NUM_SAMPLES (SAMPLE_RATE * SAMPLE_WINDOW_MS / 1000) // 100 samples

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
double calculate_rms(int *samples, int num_samples);
void log_data(double rms1, double rms2);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format for single-ended mode:
    // Byte 0: 0x01 (Start bit)
    // Byte 1: (0x08 | channel) << 4 (Single-ended mode + channel selection)
    // Byte 2: 0x00 (Don't care)
    char tx_buffer[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx_buffer[3] = {0};

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate RMS value from an array of samples
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double normalized = (double)samples[i] / 1023.0; // Normalize to 0-1
        sum_of_squares += normalized * normalized;
    }
    return sqrt(sum_of_squares / num_samples);
}

// Function to log data to a CSV file
void log_data(double rms1, double rms2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f,%.4f\n", timestamp, rms1, rms2);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is initially off

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    }

    // Register signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int mic1_samples[NUM_SAMPLES];
        int mic2_samples[NUM_SAMPLES];

        // Sample audio from both microphones
        for (int i = 0; i < NUM_SAMPLES; i++) {
            mic1_samples[i] = read_mcp3008(MCP3008_CHANNEL_1);
            mic2_samples[i] = read_mcp3008(MCP3008_CHANNEL_2);
            gpioDelay(1000 / SAMPLE_RATE); // Delay to achieve desired sample rate
        }

        // Calculate RMS values
        double rms1 = calculate_rms(mic1_samples, NUM_SAMPLES);
        double rms2 = calculate_rms(mic2_samples, NUM_SAMPLES);

        // Log data
        log_data(rms1, rms2);

        // Check threshold and control LED
        if (rms1 > THRESHOLD || rms2 > THRESHOLD) {
            gpioWrite(LED_GPIO, 1); // Turn LED on
            gpioDelay(500000);      // Keep LED on for 500 ms
            gpioWrite(LED_GPIO, 0); // Turn LED off
        }

        gpioDelay(1000); // Small delay to prevent busy-waiting
    }

    // Cleanup
    cleanup();
    printf("Audio monitoring stopped.\n");
    return 0;
}

