#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17
#define OVERCURRENT_THRESHOLD 50.0 // Amperes
#define SAMPLE_RATE 10 // Hz
#define BUFFER_SIZE 100
#define VREF 5.0 // Reference voltage for ADC
#define ADC_MAX 32767.0 // 16-bit signed max for ADS1115
#define ADC_GAIN 4.096 // Gain for +/-4.096V range
#define MLX91204_MIN_V 0.5 // Minimum output voltage (V)
#define MLX91204_MAX_V 4.5 // Maximum output voltage (V)
#define MLX91204_MAX_CURRENT 100.0 // Maximum current (A)

// Global variables
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_ads1115(int handle, int channel, float *voltage);
float convert_to_current(float voltage);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void check_overcurrent(float average_current);
void cleanup();
void signal_handler(int signal);

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read voltage from ADS1115 via I2C
int read_ads1115(int handle, int channel, float *voltage) {
    // ADS1115 register addresses
    #define ADS1115_REG_CONVERSION 0x00
    #define ADS1115_REG_CONFIG 0x01

    // Config: AIN0 single-ended, +/-4.096V, 128 SPS, continuous
    uint16_t config = 0x4000 | (channel << 12) | 0x0200 | 0x0080 | 0x0003;
    uint8_t config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(handle, (char *)config_buf, 3) < 0) {
        fprintf(stderr, "Failed to write config to ADS1115\n");
        return -1;
    }

    // Wait for conversion (128 SPS -> ~7.8ms, use 10ms for safety)
    gpioDelay(10000);

    // Read conversion register
    uint8_t reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(handle, (char *)&reg, 1) < 0) {
        fprintf(stderr, "Failed to set read pointer\n");
        return -1;
    }

    uint8_t data[2];
    if (i2cReadDevice(handle, (char *)data, 2) < 0) {
        fprintf(stderr, "Failed to read conversion data\n");
        return -1;
    }

    int16_t raw = (data[0] << 8) | data[1];
    *voltage = (raw * ADC_GAIN) / ADC_MAX;
    return 0;
}

// Convert voltage to current
float convert_to_current(float voltage) {
    if (voltage < MLX91204_MIN_V) voltage = MLX91204_MIN_V;
    if (voltage > MLX91204_MAX_V) voltage = MLX91204_MAX_V;
    return ((voltage - MLX91204_MIN_V) / (MLX91204_MAX_V - MLX91204_MIN_V)) * MLX91204_MAX_CURRENT;
}

// Add value to circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate average of values in circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) return 0.0;
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Check for overcurrent condition
void check_overcurrent(float average_current) {
    if (average_current > OVERCURRENT_THRESHOLD) {
        printf("Overcurrent condition detected! Average current: %.2f A\n", average_current);
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int main() {
    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    // Initialize circular buffer
    CircularBuffer current_buffer = {0};

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting current monitoring...\n");

    // Main loop
    while (running) {
        float voltage = 0.0;
        if (read_ads1115(i2c_handle, 0, &voltage) == 0) {
            float current = convert_to_current(voltage);
            add_to_buffer(&current_buffer, current);
            float average_current = calculate_average(&current_buffer);
            check_overcurrent(average_current);
            printf("Current: %.2f A, Average: %.2f A\n", current, average_current);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        gpioDelay(1000000 / SAMPLE_RATE); // Delay to achieve desired sample rate
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

