#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A
#define TCS34725_CONTROL 0x0F
#define TCS34725_PON 0x01
#define TCS34725_AEN 0x02
#define TCS34725_GAIN_4X 0x01
#define TCS34725_INTEGRATION_2_4MS 0xFF
#define I2C_BUS 1
#define LOG_FILE "color_log.csv"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, TCS34725_COMMAND_BIT | reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out) {
    int rc = i2cReadWordData(handle, TCS34725_COMMAND_BIT | reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    /* pigpio returns little-endian word; swap to big-endian */
    *out = (uint16_t)(((rc & 0xFF) << 8) | ((rc >> 8) & 0xFF));
    return 0;
}

static int init_sensor(int handle) {
    uint16_t id = 0;
    if (i2c_read_word(handle, TCS34725_ID, &id) < 0) {
        fprintf(stderr, "Failed to read ID register\n");
        return -1;
    }
    if ((id & 0x0F) != 0x44) {
        fprintf(stderr, "Unexpected ID: 0x%04X (expected lower nibble 0x44)\n", id);
        return -1;
    }
    printf("TCS34725 detected (ID=0x%04X)\n", id);

    if (i2c_write_byte(handle, TCS34725_ENABLE, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, TCS34725_ATIME, TCS34725_INTEGRATION_2_4MS) < 0) return -1;
    if (i2c_write_byte(handle, TCS34725_CONTROL, TCS34725_GAIN_4X) < 0) return -1;
    if (i2c_write_byte(handle, TCS34725_ENABLE, TCS34725_PON | TCS34725_AEN) < 0) return -1;

    gpioDelay(3000); /* 3 ms power-on delay */
    return 0;
}

static int read_sensor_data(int handle, sensor_data_t *data) {
    if (i2c_read_word(handle, TCS34725_CDATA, &data->clear) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_RDATA, &data->red) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_GDATA, &data->green) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_BDATA, &data->blue) < 0) return -1;
    return 0;
}

static void log_data(FILE *fp, const sensor_data_t *data) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            data->clear, data->red, data->green, data->blue);
    fflush(fp);
}

static void cleanup(void) {
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, TCS34725_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, TCS34725_ADDRESS, g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(g_i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,clear,red,green,blue\n");
        fflush(g_log_file);
    }

    int consecutive_errors = 0;

    while (g_running) {
        sensor_data_t data;
        if (read_sensor_data(g_i2c_handle, &data) == 0) {
            consecutive_errors = 0;
            log_data(g_log_file, &data);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error (%d consecutive)\n", consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Max consecutive errors reached, exiting\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

