#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define PRESSURE_REG   0x00
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1.0   /* seconds */
#define MAX_CONSEC_ERR 10

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can clean up and exit.      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a CSV header row if the file is newly opened.                 */
/* ------------------------------------------------------------------ */
static int write_header_if_new(FILE *fp)
{
    long pos = ftell(fp);
    if (pos < 0) {
        perror("ftell");
        return -1;
    }
    if (pos == 0) {
        if (fprintf(fp, "timestamp,pressure_kPa\n") < 0) {
            perror("fprintf header");
            return -1;
        }
        if (fflush(fp) != 0) {
            perror("fflush header");
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 16-bit pressure value from the MLX90817.                       */
/* Returns 0 on success (stores raw in *out), -1 on error.             */
/* ------------------------------------------------------------------ */
static int read_pressure_raw(int handle, uint16_t *out)
{
    char buf[2];
    int  rc;

    rc = i2cReadI2CBlockData(handle, PRESSURE_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr,
                "I2C read error: reg=0x%02X, rc=%d (pigpio err %d)\n",
                PRESSURE_REG, rc, rc);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw 16-bit value to pressure in kPa.                        */
/* ------------------------------------------------------------------ */
static float convert_to_kPa(uint16_t raw)
{
    return ((float)raw / 65535.0f) * 500.0f;
}

/* ------------------------------------------------------------------ */
/* Append one CSV row: timestamp,pressure_kPa                          */
/* ------------------------------------------------------------------ */
static int log_pressure(FILE *fp, float pressure_kPa)
{
    time_t     now;
    struct tm  tm_utc;
    char       ts[32];

    time(&now);
    if (gmtime_r(&now, &tm_utc) == NULL) {
        perror("gmtime_r");
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, pressure_kPa) < 0) {
        perror("fprintf data");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush data");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t raw;
    float    pressure_kPa;
    int      consec_err = 0;

    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d (pigpio err %d)\n",
                g_i2c_handle, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file once ----------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen log");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (write_header_if_new(g_log_file) != 0) {
        fprintf(stderr, "Failed to write CSV header\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- signal handlers -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90817 pressure logger started.  Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        if (read_pressure_raw(g_i2c_handle, &raw) == 0) {
            pressure_kPa = convert_to_kPa(raw);
            if (log_pressure(g_log_file, pressure_kPa) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
            consec_err = 0;
        } else {
            consec_err++;
            if (consec_err >= MAX_CONSEC_ERR) {
                fprintf(stderr,
                        "Too many consecutive I2C errors (%d). "
                        "Sensor may be absent or bus fault.\n",
                        consec_err);
                break;
            }
        }
        time_sleep(SAMPLE_PERIOD);
    }

