#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ADS1115_ADDR   0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config: AIN0 single-ended, AIN1 single-ended, gain 2/3, 128 SPS, single-shot */
#define ADS1115_CONFIG_BASE 0x8000  /* MUX[14:12]=100 (AIN0), PGA[11:9]=001 (2/3) */
#define ADS1115_CONFIG_DR   0x0080  /* DR[7:5]=100 (128 SPS) */
#define ADS1115_CONFIG_MODE 0x0100  /* MODE[1:0]=11 (single-shot) */
#define ADS1115_CONFIG_OS   0x8000  /* OS[15]=1 (start conversion) */

#define ADS1115_PGA_2_3  0x0200
#define ADS1115_MUX_AIN0 0x4000
#define ADS1115_MUX_AIN1 0x5000

#define WARNING_LED_PIN 17
#define PRESSURE_THRESHOLD 105.0f
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_config(uint16_t config) {
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int read_conversion(uint16_t *raw) {
    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) return -1;
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) return -1;
    *raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int read_adc(uint16_t *raw) {
    uint16_t config = ADS1115_CONFIG_OS | ADS1115_CONFIG_MODE | ADS1115_PGA_2_3 | ADS1115_MUX_AIN0;
    if (write_config(config) < 0) return -1;
    gpioDelay(10000); /* 10 ms for 128 SPS conversion */
    return read_conversion(raw);
}

static float adc_to_pressure(uint16_t raw) {
    int16_t signed_raw = (int16_t)raw;
    float voltage = (signed_raw * 6.144f) / 32768.0f;
    return voltage * 80.0f;
}

static float adc_to_temperature(uint16_t raw) {
    int16_t signed_raw = (int16_t)raw;
    float voltage = (signed_raw * 6.144f) / 32768.0f;
    return (voltage - 1.0f) * 100.0f;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(WARNING_LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(WARNING_LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", WARNING_LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(WARNING_LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90834 Pressure & Temperature Monitor\n");
    printf("ADS1115 ADC: AIN0=Pressure, AIN1=Temperature\n");
    printf("Threshold: %.1f kPa | LED on GPIO%d\n", PRESSURE_THRESHOLD, WARNING_LED_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        uint16_t raw_pressure = 0, raw_temperature = 0;
        int pressure_ok = 0, temp_ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_adc(&raw_pressure) == 0) {
                pressure_ok = 1;
                break;
            }
            gpioDelay(100000);
        }

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            uint16_t cfg = ADS1115_CONFIG_OS | ADS1115_CONFIG_MODE | ADS1115_PGA_2_3 | ADS1115_MUX_AIN1;
            if (write_config(cfg) < 0) {
                gpioDelay(100000);
                continue;
            }
            gpioDelay(10000);
            if (read_conversion(&raw_temperature) == 0) {
                temp_ok = 1;
                break;
            }
            gpioDelay(100000);
        }

        if (pressure_ok && temp_ok) {
            float pressure = adc_to_pressure(raw_pressure);
            float temperature = adc_to_temperature(raw_temperature);
            printf("Pressure: %.2f kPa | Temperature: %.2f °C\n", pressure, temperature);
            gpioWrite(WARNING_LED_PIN, pressure > PRESSURE_THRESHOLD ? 1 : 0);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data after %d retries.\n", MAX_RETRIES);
            gpioWrite(WARNING_LED_PIN, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

