#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* Configuration */
#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */
#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE    1023       /* 10-bit ADC */
#define VREF             3.3        /* Reference voltage */
#define SENSOR_SENS      0.066      /* MLX91209 sensitivity: 66 mV/A */
#define SENSOR_ZERO_V    1.65       /* Vcc/2 = zero-current midpoint */
#define OVERCURRENT_THRESHOLD 10.0 /* Amperes */
#define SHUTDOWN_GPIO    27         /* Motor shutdown control */
#define SAMPLE_INTERVAL  100000     /* 100 ms in microseconds */
#define LOG_FILE         "current_log.txt"

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 10-bit value from MCP3008 (single-ended, channel 0-7)          */
/* Returns 0-1023 on success, -1 on error                              */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  -> SGL/DIFF=1, D2 D1 D0 = channel
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in upper nibble
     *   rx[2] = [b7 b6 b5 b4 b3 b2 b1 b0]
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC count to current (A)                                    */
/* ------------------------------------------------------------------ */
static double adc_to_current(int adc_value)
{
    double voltage = ((double)adc_value / (double)ADC_MAX_VALUE) * VREF;
    return (voltage - SENSOR_ZERO_V) / SENSOR_SENS;
}

/* ------------------------------------------------------------------ */
/* Log a reading with timestamp                                         */
/* ------------------------------------------------------------------ */
static void log_reading(double current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, Current: %.3f A\n", timestamp, current);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Log an overcurrent event                                            */
/* ------------------------------------------------------------------ */
static void log_overcurrent(double current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
