    fprintf(log_file, "%s, OVERCURRENT: %.3f A\n", timestamp, current);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure shutdown pin is LOW before terminating */
    gpioWrite(SHUTDOWN_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure shutdown GPIO as output, initially LOW */
    if (gpioSetMode(SHUTDOWN_GPIO, PI_OUTPUT) != 0) {
