    printf("Methane monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc < 0) {
            /* SPI error already reported; wait and retry. */
            gpioDelay(SAMPLE_US);
            continue;
        }

        double ppm = adc_to_ppm(adc);
        log_data(ppm);
        check_threshold(ppm);

        gpioDelay(SAMPLE_US);
    }

    /* --- Cleanup --- */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();

    printf("Methane monitoring stopped.\n");
    return EXIT_SUCCESS;
}

