#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_RATE 1.0 // Hz
#define SAMPLE_INTERVAL (1.0 / SAMPLE_RATE)
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 100.0
#define VOLTAGE_OFFSET 0.5 // V
#define VOLTAGE_SENSITIVITY 0.1 // V/kPa
#define ADC_RESOLUTION 32768.0 // 16-bit signed, positive range
#define ADC_VREF 4.096 // V (ADS1115 at 4.096V)
#define ADC_GAIN 1.0 // +/-4.096V range

// ADS1115 Registers
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

// ADS1115 Config: AIN0 single-ended, +/-4.096V, 128 SPS, continuous
#define ADS1115_CONFIG_BASE 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA 0x0200  // +/-4.096V
#define ADS1115_CONFIG_DR 0x0080   // 128 SPS
#define ADS1115_CONFIG_MODE 0x0000 // Continuous conversion
#define ADS1115_CONFIG_OS 0x8000   // Start single conversion

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_ads1115();
int read_ads1115(int16_t *raw_value);
double convert_to_pressure(int16_t raw_value);
int log_pressure(double pressure);
void signal_handler(int signal);
void cleanup();

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    if (init_ads1115() != 0) {
        fprintf(stderr, "ADS1115 initialisation failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int16_t raw_value;
        if (read_ads1115(&raw_value) == 0) {
            double pressure = convert_to_pressure(raw_value);
            if (pressure >= PRESSURE_MIN && pressure <= PRESSURE_MAX) {
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Error logging pressure data\n");
                }
            } else {
                fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Error reading pressure data\n");
        }

        time_sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    printf("Pressure monitoring stopped.\n");
    return 0;
}

int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

int init_ads1115() {
    // Write config to ADS1115 to start continuous conversion on AIN0
    uint16_t config = ADS1115_CONFIG_OS | ADS1115_CONFIG_BASE | ADS1115_CONFIG_PGA | ADS1115_CONFIG_DR | ADS1115_CONFIG_MODE;
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing ADS1115 config\n");
        return 1;
    }
    return 0;
}

int read_ads1115(int16_t *raw_value) {
    char reg = ADS1115_REG_CONVERSION;
    char buf[2];

    // Point to conversion register
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error setting ADS1115 conversion register\n");
        return 1;
    }

    // Read 2 bytes
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion data\n");
        return 1;
    }

    *raw_value = (buf[0] << 8) | buf[1];
    return 0;
}

double convert_to_pressure(int16_t raw_value) {
    double voltage = (raw_value / ADC_RESOLUTION) * ADC_VREF;
    double pressure = (voltage - VOLTAGE_OFFSET) / VOLTAGE_SENSITIVITY;
    return pressure;
}

int log_pressure(double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return 1;
    }
    fflush(log_file);
    return 0;
}

void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

