#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL_HUMIDITY 0
#define ADC_CHANNEL_TEMP 1
#define ADC_VREF 5.0
#define ADC_MAX_VALUE 4095
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"
#define EMAIL_SENDER "sender@example.com"
#define EMAIL_SUBJECT "Humidity Alert"
#define EMAIL_BODY "Humidity exceeds threshold!"
#define SSMTP_CONFIG "/etc/ssmtp/ssmtp.conf"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

float adc_to_voltage(int adc_value) {
    return (float)adc_value * ADC_VREF / ADC_MAX_VALUE;
}

float calculate_humidity(float voltage) {
    if (voltage < 0.4 || voltage > 3.0) return -1.0;
    return (voltage - 0.824) / 0.0315;
}

float calculate_temperature(float voltage) {
    if (voltage <= 0.0) return -1.0;
    float r_thermistor = (ADC_VREF - voltage) / voltage * 10000.0;
    float r0 = 10000.0;
    float beta = 3950.0;
    float t0 = 298.15;
    float t = t0 + (beta / (t0 * log(r_thermistor / r0)));
    return t - 273.15;
}

int log_data(float humidity, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen"); return -1; }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, humidity, temperature);
    fclose(fp);
    return 0;
}

int send_email_alert(float humidity) {
    char command[512];
    snprintf(command, sizeof(command),
        "echo \"Subject: %s\nHumidity: %.2f%%\" | ssmtp -s %s %s",
        EMAIL_SUBJECT, humidity, EMAIL_SENDER, EMAIL_RECIPIENT);
    return system(command);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed\n");
        gpioTerminate();
        return 1;
    }
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    while (running) {
        int adc_h = read_adc(ADC_CHANNEL_HUMIDITY);
        int adc_t = read_adc(ADC_CHANNEL_TEMP);
        if (adc_h < 0 || adc_t < 0) {
            fprintf(stderr, "SPI transfer error\n");
            sleep(1);
            continue;
        }
        float v_h = adc_to_voltage(adc_h);
        float v_t = adc_to_voltage(adc_t);
        float hum = calculate_humidity(v_h);
        float temp = calculate_temperature(v_t);
        if (hum < 0 || temp < 0) {
            fprintf(stderr, "Invalid sensor reading\n");
            sleep(1);
            continue;
        }
        if (log_data(hum, temp) != 0) fprintf(stderr, "Log failed\n");
        if (hum > HUMIDITY_THRESHOLD) {
            if (send_email_alert(hum) != 0) fprintf(stderr, "Email failed\n");
        }
        sleep(5);
    }
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

