#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

/* Configuration */
#define SPI_CHANNEL 0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED   1000000    /* 1 MHz */
#define SPI_FLAGS   0          /* Mode 0, active-low CS handled by pigpio */
#define ADC_CHANNELS 3
#define ADC_MAX     1023       /* 10-bit ADC */
#define VREF        3.3f
#define SENSITIVITY 0.3f       /* 300 mV/g */
#define ZERO_G      1.65f      /* 1.65V at 0g */
#define IMPACT_THRESHOLD 2.0f
#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define LOG_FILE "impact_log.txt"

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a single channel from MCP3008 via SPI.
 * Returns 0-1023 on success, -1 on error. */
static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer.
     * Byte 0: 0x01 (start bit)
     * Byte 1: (0x08 | channel) << 4  -> SGL/DIFF=1, D2 D1 D0 = channel
     * Byte 2: 0x00 (don't care, clocks out low 2 bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits). */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    if (adc_value < 0 || adc_value > ADC_MAX) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

/* Convert ADC count to acceleration in g */
static float adc_to_g(int adc_value) {
    float voltage = ((float)adc_value / (float)ADC_MAX) * VREF;
    return (voltage - ZERO_G) / SENSITIVITY;
}

/* Log one sample line */
static void log_sample(int x, int y, int z, float gx, float gy, float gz, float mag) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, x, y, z, gx, gy, gz, mag);
    fflush(log_file);
}

/* Log impact detection */
static void log_impact(float mag) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,IMPACT DETECTED,%.3f\n", timestamp, mag);
    fflush(log_file);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z,gX,gY,gZ,Mag\n");
        fflush(log_file);
    }

    /* Install signal handler */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (!terminate) {
        int x = read_adc(0);
        int y = read_adc(1);
        int z = read_adc(2);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float gx = adc_to_g(x);
        float gy = adc_to_g(y);
        float gz = adc_to_g(z);
        float mag = sqrtf(gx * gx + gy * gy + gz * gz);

        log_sample(x, y, z, gx, gy, gz, mag);

        if (mag > IMPACT_THRESHOLD) {
            log_impact(mag);
            printf("Impact detected: %.3f g\n", mag);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

