/*
 * Si1172-A30-GMR Optical Heart Rate Sensor reader for Raspberry Pi Zero W
 * Uses pigpio for I2C communication on bus 1, address 0x49.
 *
 * NOTE: The Si1172-A30-GMR is a proprietary optical heart-rate sensor.
 * This program reads raw 16-bit IR and RED ADC values from the FIFO
 * and logs them as proxy HR (bpm) and SpO2 (%) values. A full
 * HR/SpO2 calculation requires the sensor's proprietary firmware
 * and the Si1172's proprietary algorithm. This program demonstrates
 * basic I2C read and CSV logging; a production system must integrate
 * the sensor's firmware and algorithm.
 *
 * Build: gcc -Wall -o si1172_reader si1172_reader.c -lpigpio -lrt
 * Run:   sudo ./si1172_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x49
#define LOG_FILE       "biometric_log.csv"
#define SAMPLE_PERIOD  1.0   /* seconds */

/* Si1172 register addresses (command-based protocol) */
#define REG_COMMAND    0xC0
#define REG_FIFO_DATA  0xC1
#define REG_FIFO_COUNT 0xC2
#define REG_IR_DATA    0xC3
#define REG_RED_DATA   0xC4

/* Command register values */
#define CMD_RESET      0x01
#define CMD_START      0x02
#define CMD_READ_FIFO  0x03

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a command to the Si1172 command register                      */
/* ------------------------------------------------------------------ */
static int si1172_write_command(uint8_t cmd)
{
    int rc = i2cWriteByteData(g_i2c_handle, REG_COMMAND, cmd);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(REG_COMMAND, 0x%02X) failed: %d\n",
                cmd, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from a Si1172 register            */
/* ------------------------------------------------------------------ */
static int si1172_read_u16(uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(REG 0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }
    /* pigpio returns data as (msb << 8) | lsb; Si1172 is little-endian */
    *out = (uint16_t)((rc >> 8) | (rc << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read raw IR and RED ADC values from the Si1172 FIFO                 */
/* ------------------------------------------------------------------ */
static int si1172_read_raw_data(uint16_t *ir, uint16_t *red)
{
    if (si1172_write_command(CMD_READ_FIFO) < 0)
        return -1;

    if (si1172_read_u16(REG_IR_DATA,  ir)  < 0)
        return -1;
    if (si1172_read_u16(REG_RED_DATA, red) < 0)
        return -1;

    return 0;
}

