    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file (write header if new) --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    long pos = ftell(g_log_file);
    if (pos == 0) {
        fprintf(g_log_file, "timestamp,ir_adc,red_adc,error_flag\n");
        fflush(g_log_file);
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed\n");
    }

    /* --- Reset sensor --- */
    if (si1172_write_command(CMD_RESET) < 0) {
        fprintf(stderr, "[ERROR] Sensor reset failed; continuing anyway\n");
    }
    time_sleep(0.1);

    /* --- Start measurement --- */
    if (si1172_write_command(CMD_START) < 0) {
        fprintf(stderr, "[ERROR] Start measurement failed; continuing anyway\n");
    }
    time_sleep(0.1);

    printf("Si1172 reader started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t ir = 0, red = 0;
        int error_flag = 0;

        if (si1172_read_raw_data(&ir, &red) == 0) {
            if (log_data(ir, red, 0) != 0) {
