#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* Configuration */
#define SPI_CHANNEL 0       /* CE0 / GPIO8 */
#define SPI_BAUD    1000000 /* 1 MHz */
#define SPI_FLAGS   0       /* Mode 0, active-low CE */
#define ADC_CHANNEL 0       /* MCP3008 single-ended channel 0 */
#define VREF        3.3f    /* Reference voltage */
#define MAX_FLOW    5.0f    /* Maximum flow rate (L/min) */
#define LOG_FILE    "flow_log.csv"
#define SAMPLE_US   1000000 /* 1 second in microseconds */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read 10-bit value from MCP3008 single-ended channel */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 SPI protocol: 3 bytes
     * Byte 0: 0x01 (start bit)
     * Byte 1: (0x08 | channel) << 4  -> single-ended + channel select
     * Byte 2: 0x00 (don't care, clocked out for data)
     * Result: bits 9-8 in rx[1] (masked 0x03), bits 7-0 in rx[2]
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* Convert ADC value to flow rate (L/min) */
static float adc_to_flow(int adc_value) {
    float voltage = (float)adc_value / 1023.0f * VREF;
    return (voltage / VREF) * MAX_FLOW;
}

/* Log flow rate with microsecond timestamp */
static void log_flow_rate(float flow_rate) {
    struct timeval tv;
    struct tm tm_info;
    char timestamp[40];

    if (gettimeofday(&tv, NULL) != 0) {
        fprintf(stderr, "Error: gettimeofday failed: %s\n", strerror(errno));
        return;
    }

    localtime_r(&tv.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%06ld", (long)tv.tv_usec);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
    } else {
        fflush(log_file);
    }
}

/* Cleanup resources */
static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGTERM handler: %s\n",
                strerror(errno));
    }

    printf("Flow monitoring started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* Main loop */
    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        /* Sensor-absent / bus-error detection */
        if (adc_value == 0) {
            fprintf(stderr, "Warning: ADC reads 0 - sensor absent or wiring fault\n");
        } else if (adc_value == 1023) {
            fprintf(stderr, "Warning: ADC saturated - sensor disconnected or fault\n");
        }

        float flow_rate = adc_to_flow(adc_value);

        /* Validate plausible range */
        if (flow_rate < 0.0f || flow_rate > MAX_FLOW) {
            fprintf(stderr, "Warning: Flow rate %.2f L/min out of range [0, %.1f]\n",
                    flow_rate, MAX_FLOW);
        }

        log_flow_rate(flow_rate);
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

