#define LOG_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int fd, float *temperature, float *pressure) {
    if (i2c_write_cmd(fd, MEASURE_CMD) < 0) return -1;

    usleep(20000);

    uint8_t data[6];
    if (i2c_read_bytes(fd, data, 6) < 0) return -1;

    uint16_t raw_pressure = (data[0] << 8) | data[1];
    uint16_t raw_temperature = (data[2] << 8) | data[3];

    float t = (float)raw_temperature / 65535.0f;
    float p = (float)raw_pressure / 65535.0f;

    *temperature = -45.0f + 175.0f * t;
    *pressure = 100000.0f + 100000.0f * p;

    return 0;
}

static void log_data(FILE *fp, float temperature, float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(fp);
}

static void display_data(float temperature, float pressure) {
    printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP_10125_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ICP_10125_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float temperature, pressure;
        if (read_sensor_data(i2c_fd, &temperature, &pressure) == 0) {
            log_data(log_file, temperature, pressure);
            display_data(temperature, pressure);
        } else {
            fprintf(stderr, "Sensor read failed, retrying in %d seconds...\n", SAMPLE_INTERVAL);
        }
        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down gracefully...\n");
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

