#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define NUM_SAMPLES 100
#define ADC_CHANNEL_1 0
#define ADC_CHANNEL_2 1
#define DEFAULT_GAIN 1.0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

void noise_cancellation(int *audio1, int *audio2, int num_samples, double gain) {
    for (int i = 0; i < num_samples; i++) {
        int diff = (int)((audio1[i] - audio2[i]) * gain);
        if (diff > 32767) diff = 32767;
        if (diff < -32768) diff = -32768;
        audio1[i] = diff;
    }
}

void print_audio_data(int *audio1, int *audio2, int num_samples) {
    for (int i = 0; i < num_samples; i++) {
        printf("%d,%d\n", audio1[i], audio2[i]);
    }
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    double gain = DEFAULT_GAIN;

    if (argc > 1) {
        gain = atof(argv[1]);
        if (gain <= 0) {
            fprintf(stderr, "Error: Gain must be a positive number. Using default gain: %f\n", DEFAULT_GAIN);
            gain = DEFAULT_GAIN;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int *audio1 = (int *)malloc(NUM_SAMPLES * sizeof(int));
    int *audio2 = (int *)malloc(NUM_SAMPLES * sizeof(int));

    if (audio1 == NULL || audio2 == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        free(audio1);
        free(audio2);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Audio sampling and noise cancellation started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < NUM_SAMPLES; i++) {
            int val1 = read_adc(ADC_CHANNEL_1);
            int val2 = read_adc(ADC_CHANNEL_2);

            if (val1 < 0 || val2 < 0) {
                fprintf(stderr, "Error: ADC read failed, retrying...\n");
                i--;
                gpioDelay(1000);
                continue;
            }

            audio1[i] = val1;
            audio2[i] = val2;
            gpioDelay(1000);
        }

        noise_cancellation(audio1, audio2, NUM_SAMPLES, gain);
        print_audio_data(audio1, audio2, NUM_SAMPLES);
    }

    printf("\nExiting gracefully...\n");
    free(audio1);
    free(audio2);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

