#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define ADC_CHANNEL 0
#define LED_GPIO    17
#define WATER_HIGH  75.0f
#define WATER_LOW   70.0f
#define LOG_FILE    "water_levels.json"
#define SAMPLE_MS   5000
#define DELAY_MS    100

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret < 0) {
        pigpio_error(ret);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_percentage(int adc) {
    return (float)adc / 1023.0f * 100.0f;
}

static void log_water_level(float level) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char ts_buf[32];
    strftime(ts_buf, sizeof(ts_buf), "%Y-%m-%dT%H:%M:%S", &tm_info);
    long ms = ts.tv_nsec / 1000000L;
    fprintf(log_fp, "{\"timestamp\":\"%s.%03ld\",\"water_level\":%.2f},\n", ts_buf, ms, level);
    fflush(log_fp);
}

static void control_led(float level) {
    static int led_state = 0;
    if (level > WATER_HIGH && !led_state) {
        gpioWrite(LED_GPIO, 1);
        led_state = 1;
    } else if (level < WATER_LOW && led_state) {
        gpioWrite(LED_GPIO, 0);
        led_state = 0;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        pigpio_error(spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    log_fp = fopen(LOG_FILE, "w");
    if (!log_fp) {
        perror("fopen");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(log_fp, "[\n");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int adc = read_mcp3008(ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "SPI read error, skipping sample\n");
        } else {
            float level = adc_to_percentage(adc);
            log_water_level(level);
            control_led(level);
        }
        for (int i = 0; i < SAMPLE_MS / DELAY_MS && running; i++) {
            gpioDelay(DELAY_MS * 1000);
        }
    }

    fprintf(log_fp, "]\n");
    fclose(log_fp);
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    return 0;
}

