#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_RAW_VALUE 300
#define DEFAULT_MAX_RAW_VALUE 700
#define DEFAULT_MOISTURE_THRESHOLD 30
#define DEFAULT_LOGGING_FREQUENCY 60
#define DEFAULT_EMAIL_RECIPIENT "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG "/etc/msmtprc"
#define DEFAULT_LOG_FILE "plant_data.txt"
#define SPI_SPEED 500000
#define SPI_FLAGS 0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static int spi_channel = DEFAULT_SPI_CHANNEL;
static int adc_channel = DEFAULT_ADC_CHANNEL;
static int min_raw_value = DEFAULT_MIN_RAW_VALUE;
static int max_raw_value = DEFAULT_MAX_RAW_VALUE;
static int moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
static int logging_frequency = DEFAULT_LOGGING_FREQUENCY;
static char *email_recipient = DEFAULT_EMAIL_RECIPIENT;
static char *msmtp_config = DEFAULT_MSMTP_CONFIG;
static char *log_file = DEFAULT_LOG_FILE;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_moisture_percentage(int raw_value, int min_raw, int max_raw) {
    if (max_raw == min_raw) {
        fprintf(stderr, "Error: max_raw and min_raw are equal, cannot calculate moisture percentage\n");
        return -1.0f;
    }
    return 100.0f - ((float)(raw_value - min_raw) / (float)(max_raw - min_raw) * 100.0f);
}

static int log_data(const char *filename, float moisture_percentage) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", filename);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(fp);
    return 0;
}

static int send_email_alert(const char *recipient, const char *msmtp_config, float moisture_percentage) {
    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Plant Moisture Alert\n\nMoisture level is below threshold! Current moisture: %.2f%%\" | msmtp -C %s %s",
             moisture_percentage, msmtp_config, recipient);

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to execute msmtp command\n");
        return -1;
    }

    int status = pclose(fp);
    if (status != 0) {
        fprintf(stderr, "Error: msmtp exited with status %d\n", status);
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--spi_channel") == 0 && i + 1 < argc) spi_channel = atoi(argv[++i]);
        else if (strcmp(argv[i], "--adc_channel") == 0 && i + 1 < argc) adc_channel = atoi(argv[++i]);
        else if (strcmp(argv[i], "--min_raw_value") == 0 && i + 1 < argc) min_raw_value = atoi(argv[++i]);
        else if (strcmp(argv[i], "--max_raw_value") == 0 && i + 1 < argc) max_raw_value = atoi(argv[++i]);
        else if (strcmp(argv[i], "--moisture_threshold") == 0 && i + 1 < argc) moisture_threshold = atoi(argv[++i]);
        else if (strcmp(argv[i], "--logging_frequency") == 0 && i + 1 < argc) logging_frequency = atoi(argv[++i]);
        else if (strcmp(argv[i], "--email_recipient") == 0 && i + 1 < argc) {
            free(email_recipient);
            email_recipient = strdup(argv[++i]);
        }
        else if (strcmp(argv[i], "--msmtp_config") == 0 && i + 1 < argc) {
            free(msmtp_config);
            msmtp_config = strdup(argv[++i]);
        }
        else if (strcmp(argv[i], "--log_file") == 0 && i + 1 < argc) {
            free(log_file);
            log_file = strdup(argv[++i]);
        }
        else {
            fprintf(stderr, "Usage: %s [--spi_channel <0|1>] [--adc_channel <0-7>] [--min_raw_value <int>] [--max_raw_value <int>] [--moisture_threshold <int>] [--logging_frequency <seconds>] [--email_recipient <email>] [--msmtp_config <path>] [--log_file <path>]\n", argv[0]);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(spi_channel, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed on channel %d\n", spi_channel);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Plant monitoring started. Logging every %d seconds. Press Ctrl+C to exit.\n", logging_frequency);

    while (running) {
        int raw_value = read_mcp3008(adc_channel);
        if (raw_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n", logging_frequency);
            sleep(logging_frequency);
            continue;
        }

        float moisture_percentage = calculate_moisture_percentage(raw_value, min_raw_value, max_raw_value);
        if (moisture_percentage < 0.0f) {
            fprintf(stderr, "Error: Failed to calculate moisture percentage, retrying in %d seconds...\n", logging_frequency);
            sleep(logging_frequency);
            continue;
        }

        if (log_data(log_file, moisture_percentage) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        if (moisture_percentage < moisture_threshold) {
            if (send_email_alert(email_recipient, msmtp_config, moisture_percentage) != 0) {
                fprintf(stderr, "Error: Failed to send email alert\n");
            }
        }

        sleep(logging_frequency);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    free(email_recipient);
    free(msmtp_config);
    free(log_file);
    return 0;
}

