#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// MCP3008 SPI Configuration
#define SPI_CHANNEL 0       // CE0 (GPIO8)
#define SPI_SPEED 1000000   // 1 MHz
#define ADC_CHANNEL 0       // MCP3008 channel connected to MLX90823

// MLX90823 Voltage Range (V)
#define MIN_VOLTAGE 0.5
#define MAX_VOLTAGE 4.5

// Pressure Range (kPa)
#define MIN_PRESSURE 10.0
#define MAX_PRESSURE 150.0

// ADC Reference Voltage (V)
#define ADC_VREF 3.3

// Global flag for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format for single-ended mode
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel << 4
    // Byte 2: Don't care (0x00)
    char tx_buffer[3] = {0x01, (char)(0x80 | (channel << 4)), 0x00};
    char rx_buffer[3] = {0};

    int bytes_transferred = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (bytes_transferred != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", bytes_transferred);
        return -1;
    }

    // Extract 10-bit ADC value from response
    // rx_buffer[1] contains the two most significant bits
    // rx_buffer[2] contains the eight least significant bits
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | (rx_buffer[2] & 0xFF);
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (adc_value / 1023.0) * ADC_VREF;
}

// Function to convert voltage to pressure (kPa)
float voltage_to_pressure(float voltage) {
    if (voltage < MIN_VOLTAGE || voltage > MAX_VOLTAGE) {
        return -1.0; // Indicate out of range
    }
    return MIN_PRESSURE + ((voltage - MIN_VOLTAGE) / (MAX_VOLTAGE - MIN_VOLTAGE)) * (MAX_PRESSURE - MIN_PRESSURE);
}

// Function to log data with timestamp
void log_data(float pressure, float voltage, int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Pressure: %.2f kPa, Voltage: %.3f V, ADC: %d\n", timestamp, pressure, voltage, adc_value);
}

int main() {
    int spi_handle = -1;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90823 Pressure Sensor Reader started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int adc_value = read_mcp3008(spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            sleep(1);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float pressure = voltage_to_pressure(voltage);

        // Check for sensor-absent or out-of-range conditions
        if (pressure < 0) {
            fprintf(stderr, "Warning: Voltage out of range (%.3f V). Sensor absent or wiring fault.\n", voltage);
        } else if (voltage < 0.01 || voltage > 3.2) {
            fprintf(stderr, "Warning: Voltage at rail (%.3f V). Sensor absent or wiring fault.\n", voltage);
        } else {
            log_data(pressure, voltage, adc_value);
        }

        sleep(1); // Read every 1 second
    }

    // Clean up resources
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("\nProgram terminated gracefully.\n");
    return 0;
}

