#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

/* Configuration */
#define SPI_CHANNEL      0          /* CE0 on bus 0 */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */
#define PUMP_GPIO        17         /* Relay control pin (active-high) */
#define MOISTURE_CHANNEL 0          /* MCP3008 single-ended channel 0 */
#define MOISTURE_LOW     300        /* Turn pump ON below this (10-bit) */
#define MOISTURE_HIGH    600        /* Turn pump OFF above this (10-bit) */
#define SAMPLE_INTERVAL  5          /* Seconds between samples */
#define LOG_CAPACITY     20

/* Globals */
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

/* Circular log buffer */
typedef struct {
    time_t timestamp;
    int    moisture;
    int    pump_state;
} LogEntry;

static LogEntry log_buffer[LOG_CAPACITY];
static int      log_head = 0;   /* next write slot */
static int      log_count = 0;  /* entries currently stored */

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 10-bit value from MCP3008 (single-ended, 0–7)                  */
/* Returns 0–1023 on success, -1 on SPI error                          */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer, mode 0):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Control pump with hysteresis                                        */
/* ------------------------------------------------------------------ */
static void control_pump(int moisture)
{
    static int pump_on = 0;

    if (moisture < MOISTURE_LOW && !pump_on) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            pump_on = 1;
            printf("Pump ON  (moisture=%d)\n", moisture);
        } else {
            fprintf(stderr, "Failed to set PUMP_GPIO high\n");
        }
    } else if (moisture > MOISTURE_HIGH && pump_on) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            pump_on = 0;
            printf("Pump OFF (moisture=%d)\n", moisture);
        } else {
            fprintf(stderr, "Failed to set PUMP_GPIO low\n");
        }
    }
}

/* ------------------------------------------------------------------ */
/* Append a log entry to the circular buffer                           */
/* ------------------------------------------------------------------ */
static void log_data(int moisture, int pump_state)
{
    log_buffer[log_head].timestamp  = time(NULL);
    log_buffer[log_head].moisture   = moisture;
    log_buffer[log_head].pump_state = pump_state;

    log_head = (log_head + 1) % LOG_CAPACITY;
    if (log_count < LOG_CAPACITY)
        log_count++;
}

/* ------------------------------------------------------------------ */
/* Print the full circular log buffer                                  */
/* ------------------------------------------------------------------ */
static void print_log(void)
{
    printf("\n--- Moisture Log (%d entries) ---\n", log_count);
    for (int i = 0; i < log_count; i++) {
        int idx = (log_head - log_count + i + LOG_CAPACITY) % LOG_CAPACITY;
        char ts[32];
        struct tm tm_info;
        localtime_r(&log_buffer[idx].timestamp, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] Moisture: %4d  Pump: %s\n",
               ts,
               log_buffer[idx].moisture,
               log_buffer[idx].pump_state ? "ON" : "OFF");
    }
    printf("----------------------------------\n");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* pigpio timer callback — runs every SAMPLE_INTERVAL seconds          */
/* ------------------------------------------------------------------ */
static void sample_timer_cb(void *userdata)
{
    (void)userdata;

    int moisture = read_mcp3008(MOISTURE_CHANNEL);
    if (moisture < 0) {
        fprintf(stderr, "Sensor read error — skipping cycle\n");
        return;
    }

    control_pump(moisture);

    int pump_state = gpioRead(PUMP_GPIO);
    if (pump_state < 0) {
        fprintf(stderr, "Warning: gpioRead(PUMP_GPIO) failed\n");
        pump_state = -1;
    }

    log_data(moisture, pump_state);
    print_log();
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Turn pump off first for safety */
    if (spi_handle >= 0) {
        gpioWrite(PUMP_GPIO, 0);
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pump GPIO */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);  /* Pump off at startup */

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Start 5-second timer */
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL * 1000, sample_timer_cb, NULL) != 0) {
        fprintf(stderr, "Failed to set timer\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitor running. Press Ctrl+C to exit.\n");
    printf("SPI channel %d, MCP3008 ch %d, pump GPIO %d\n",
           SPI_CHANNEL, MOISTURE_CHANNEL, PUMP_GPIO);

    /* Main loop — sleep until signal */
    while (running)
        sleep(1);

    /* Graceful shutdown */
    gpioSetTimerFuncEx(0, 0, NULL, NULL);  /* stop timer */
    cleanup();
    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

