#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

#define I2C_BUS 1
#define MAX30102_ADDR 0x57
#define LOG_FILE "health_log.txt"

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_STATUS_2 0x01
#define REG_INTR_ENABLE_1 0x02
#define REG_INTR_ENABLE_2 0x03
#define REG_FIFO_WR_PTR 0x04
#define REG_OVF_COUNTER 0x05
#define REG_FIFO_RD_PTR 0x06
#define REG_FIFO_DATA 0x07
#define REG_FIFO_CONFIG 0x08
#define REG_MODE_CONFIG 0x09
#define REG_SPO2_CONFIG 0x0A
#define REG_LED1_PA 0x0C
#define REG_LED2_PA 0x0D
#define REG_PART_ID 0xFF

#define EXPECTED_PART_ID 0x15
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n", reg, val, rc);
    }
    return rc;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_read_burst(uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C burst read failed: reg=0x%02X, expected=%u, got=%d\n", reg, len, rc);
        return -1;
    }
    return 0;
}

static int init_max30102(void) {
    uint8_t part_id;
    if (i2c_read_reg(REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read Part ID - sensor absent or bus error\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("MAX30102 detected (Part ID 0x%02X)\n", part_id);

    if (i2c_write_reg(REG_MODE_CONFIG, 0x40) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(REG_INTR_ENABLE_1, 0x00) < 0) return -1;
    if (i2c_write_reg(REG_INTR_ENABLE_2, 0x00) < 0) return -1;
    if (i2c_write_reg(REG_FIFO_WR_PTR, 0x00) < 0) return -1;
    if (i2c_write_reg(REG_OVF_COUNTER, 0x00) < 0) return -1;
    if (i2c_write_reg(REG_FIFO_RD_PTR, 0x00) < 0) return -1;
    if (i2c_write_reg(REG_FIFO_CONFIG, 0x0F) < 0) return -1;
    if (i2c_write_reg(REG_MODE_CONFIG, 0x03) < 0) return -1;
    if (i2c_write_reg(REG_SPO2_CONFIG, 0x27) < 0) return -1;
    if (i2c_write_reg(REG_LED1_PA, 0x24) < 0) return -1;
    if (i2c_write_reg(REG_LED2_PA, 0x24) < 0) return -1;

    gpioDelay(100000);
    return 0;
}

static int read_fifo_sample(uint32_t *red, uint32_t *ir) {
    uint8_t buf[6];
    if (i2c_read_burst(REG_FIFO_DATA, buf, 6) < 0) return -1;
    *red = ((uint32_t)(buf[0] & 0x03) << 16) | ((uint32_t)buf[1] << 8) | buf[2];
    *ir  = ((uint32_t)(buf[3] & 0x03) << 16) | ((uint32_t)buf[4] << 8) | buf[5];
    return 0;
}

static int compute_spo2(const uint32_t *red, const uint32_t *ir, int n, float *spo2) {
    if (n < 10) return -1;
    float r_mean = 0.0f, i_mean = 0.0f;
    for (int i = 0; i < n; i++) { r_mean += red[i]; i_mean += ir[i]; }
    r_mean /= n; i_mean /= n;
    float r_var = 0.0f, i_var = 0.0f;
    for (int i = 0; i < n; i++) {
        float dr = red[i] - r_mean; float di = ir[i] - i_mean;
        r_var += dr * dr; i_var += di * di;
    }
    r_var /= n; i_var /= n;
    if (r_var < 1e-6f || i_var < 1e-6f) return -1;
    float rms_r = sqrtf(r_var); float rms_i = sqrtf(i_var);
    if (rms_r < 1e-6f || rms_i < 1e-6f) return -1;
    float ratio = (rms_r / rms_i) - 1.0f;
    if (ratio < 0.0f) ratio = 0.0f;
    *spo2 = 110.0f - 25.0f * ratio;
    if (*spo2 < 0.0f) *spo2 = 0.0f;
    if (*spo2 > 100.0f) *spo2 = 100.0f;
    return 0;
}

static int detect_peak(const uint32_t *ir, int n, int *peak_count) {
    int count = 0;
    for (int i = 1; i < n - 1; i++) {
        if (ir[i] > ir[i-1] && ir[i] > ir[i+1]) {
            count++;
        }
    }
    *peak_count = count;
    return 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen log"); return; }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s - %s\n", ts, msg);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_max30102() < 0) {
        fprintf(stderr, "MAX30102 init failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring SpO2 and HR (Ctrl+C to exit)...\n");

    while (!terminate) {
        uint32_t red[32], ir[32];
        int n = 0;
        for (int i = 0; i < 32 && !terminate; i++) {
            if (read_fifo_sample(&red[i], &ir[i]) < 0) {
                fprintf(stderr, "FIFO read error\n");
                break;
            }
            n++;
            gpioDelay(10000);
        }
        if (n < 10) {
            fprintf(stderr, "Insufficient samples (%d)\n", n);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float spo2;
        if (compute_spo2(red, ir, n, &spo2) < 0) {
            fprintf(stderr, "SpO2 computation failed\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        int peak_count;
        detect_peak(ir, n, &peak_count);
        float hr = (float)peak_count * 60.0f;

        printf("SpO2: %.1f%%, HR: %.1f BPM\n", spo2, hr);

        if (spo2 < 95.0f) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Low SpO2: %.1f%%", spo2);
            log_event(msg);
        }
        if (hr > 100.0f) {
            char msg[128];
            snprintf(msg, sizeof(msg), "High HR: %.1f BPM", hr);
            log_event(msg);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

