#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CFG  0x01

#define RELAY_PIN      17
#define REED_PIN       27

#define LOG_FILE       "/var/log/door_events.log"
#define NUM_BASELINE   10
#define BASELINE_DELAY_MS 50
#define POLL_DELAY_MS   200
#define RELAY_HOLD_MS   3000
#define THRESHOLD_PCT   80

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *reed_line = NULL;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[64];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    struct i2c_msg msg = { .addr = ADS1115_ADDR, .flags = 0, .len = 3, .buf = buf };
    struct i2c_rdwr_ioctl_data data = { .msgs = &msg, .nmsgs = 1 };
    if (ioctl(fd, I2C_RDWR, &data) < 0) return -1;
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t wbuf[1] = { reg };
    struct i2c_msg wmsg = { .addr = ADS1115_ADDR, .flags = 0, .len = 1, .buf = wbuf };
    struct i2c_msg rmsg = { .addr = ADS1115_ADDR, .flags = I2C_M_RD, .len = 2, .buf = (uint8_t *)out };
    struct i2c_rdwr_ioctl_data data = { .msgs = &wmsg, .nmsgs = 2 };
    if (ioctl(fd, I2C_RDWR, &data) < 0) return -1;
    return 0;
}

static int read_ads1115(int fd) {
    uint16_t cfg = 0xC083; /* A0 single-ended, 4.096V, 128 SPS, continuous */
    if (i2c_write16(fd, ADS1115_REG_CFG, cfg) < 0) return -1;
    usleep(10000);
    uint16_t raw;
    if (i2c_read16(fd, ADS1115_REG_CONV, &raw) < 0) return -1;
    return (int16_t)raw;
}

static int read_distance(int fd) {
    int v = read_ads1115(fd);
    if (v < 0) return -1;
    /* GP2Y0A21YK0F: higher voltage = closer. 16-bit signed, 0V=0, 3.3V=32767 */
    return (v + 32768) / 65536;
}

static int calibrate(int fd) {
    int sum = 0;
    for (int i = 0; i < NUM_BASELINE; i++) {
        int d = read_distance(fd);
        if (d < 0) {
            log_event("calibration: ADC read failed");
            return -1;
        }
        sum += d;
        usleep(BASELINE_DELAY_MS * 1000);
    }
    int avg = sum / NUM_BASELINE;
    return (avg * THRESHOLD_PCT) / 100;
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (reed_line) gpiod_line_release(reed_line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
}

int main(void) {
    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        return 1;
    }
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    reed_line = gpiod_chip_get_line(chip, REED_PIN);
    if (!relay_line || !reed_line) {
        fprintf(stderr, "gpiod get_line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(relay_line, "door_relay", 0) < 0) {
        fprintf(stderr, "relay request: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_input(reed_line, "door_reed") < 0) {
        fprintf(stderr, "reed request: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    int threshold = calibrate(i2c_fd);
    if (threshold < 0) {
        log_event("calibration failed");
        cleanup();
        return 1;
    }
    char m[128];
    snprintf(m, sizeof(m), "calibrated threshold=%d", threshold);
    log_event(m);

    while (running) {
        int d = read_distance(i2c_fd);
        if (d < 0) {
            log_event("ADC read failed");
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }
        if (d < threshold) {
            log_event("proximity detected");
            if (gpiod_line_set_value(relay_line, 1) < 0) {
                log_event("relay set high failed");
            } else {
                log_event("relay energized");
            }
            usleep(RELAY_HOLD_MS * 1000);
            if (gpiod_line_set_value(relay_line, 0) < 0) {
                log_event("relay set low failed");
            } else {
                log_event("relay de-energized");
            }
            int r = gpiod_line_get_value(reed_line);
            if (r < 0) {
                log_event("reed read failed");
            } else if (r == 0) {
                log_event("door opened");
            } else {
                log_event("door not opened");
            }
        }
        usleep(POLL_DELAY_MS * 1000);
    }

    log_event("shutdown");
    cleanup();
    return 0;
}

