    int cs_pins[NUM_SENSORS] = { CS0_PIN, CS1_PIN, CS2_PIN };
    for (int i = 0; i < NUM_SENSORS; i++) {
        cs_lines[i] = gpiod_chip_get_line(chip, cs_pins[i]);
        if (!cs_lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%d) failed\n", cs_pins[i]);
            for (int j = 0; j < i; j++) gpiod_line_release(cs_lines[j]);
            gpiod_chip_close(chip);
            return 1;
        }
        if (gpiod_line_request_output(cs_lines[i], "mcp3008-cs", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%d) failed\n", cs_pins[i]);
            for (int j = 0; j < i; j++) gpiod_line_release(cs_lines[j]);
            gpiod_chip_close(chip);
            return 1;
        }
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open spidev");
        for (int i = 0; i < NUM_SENSORS; i++) gpiod_line_release(cs_lines[i]);
        gpiod_chip_close(chip);
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        goto cleanup;
    }

    printf("Soil Moisture Monitoring Started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int s1 = read_mcp3008(spi_fd, cs_lines[0], 0);
        int s2 = read_mcp3008(spi_fd, cs_lines[1], 0);
        int s3 = read_mcp3008(spi_fd, cs_lines[2], 0);

        if (log_data(LOG_FILE, s1, s2, s3) < 0) {
            fprintf(stderr, "Logging failed\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

cleanup:
    close(spi_fd);
    for (int i = 0; i < NUM_SENSORS; i++) gpiod_line_release(cs_lines[i]);
    gpiod_chip_close(chip);
    printf("\nExiting gracefully.\n");
    return 0;
}

