#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_RETRIES 3
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define DRY_RAW 200
#define WET_RAW 800

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    for (int attempt = 0; attempt < SPI_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %d\n", attempt + 1, SPI_RETRIES, ret);
        gpioDelay(10000);
    }
    return -1;
}

static float calculate_moisture(int raw) {
    if (raw < 0) return -1.0f;
    float pct = 100.0f - ((float)(raw - DRY_RAW) / (float)(WET_RAW - DRY_RAW) * 100.0f);
    if (pct < 0.0f) pct = 0.0f;
    if (pct > 100.0f) pct = 100.0f;
    return pct;
}

static void log_event(const char *msg) {
    FILE *fp = fopen("irrigation.log", "a");
    if (!fp) {
        perror("fopen irrigation.log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fclose(fp);
}

static void control_pump(int on) {
    if (gpioWrite(PUMP_GPIO, on ? 1 : 0) < 0) {
        fprintf(stderr, "Failed to write GPIO%d\n", PUMP_GPIO);
        return;
    }
    char buf[128];
    snprintf(buf, sizeof(buf), "Pump %s", on ? "activated" : "deactivated");
    log_event(buf);
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    int duration = DEFAULT_DURATION;
    int sleep_interval = DEFAULT_SLEEP_INTERVAL;

    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't': threshold = atoi(optarg); break;
            case 'd': duration = atoi(optarg); break;
            case 's': sleep_interval = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (threshold < 0 || threshold > 100) {
        fprintf(stderr, "Threshold must be 0-100\n");
        return EXIT_FAILURE;
    }
    if (duration <= 0 || sleep_interval <= 0) {
        fprintf(stderr, "Duration and sleep must be positive\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioWrite(PUMP_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Irrigation controller started");

    while (running) {
        int raw = read_mcp3008(0);
        if (raw < 0) {
            log_event("Error: SPI read failed after retries, skipping cycle");
            for (int i = 0; i < sleep_interval && running; i++) {
                gpioDelay(1000000);
            }
            continue;
        }

        float moisture = calculate_moisture(raw);
        char msg[160];
        snprintf(msg, sizeof(msg), "Raw ADC: %d, Moisture: %.1f%%", raw, moisture);
        log_event(msg);

        if (moisture < threshold) {
            control_pump(1);
            for (int i = 0; i < duration && running; i++) {
                gpioDelay(1000000);
            }
            control_pump(0);
        }

        for (int i = 0; i < sleep_interval && running; i++) {
            gpioDelay(1000000);
        }
    }

    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    log_event("Irrigation controller stopped");
    return EXIT_SUCCESS;
}

