#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x48
#define SAMPLE_MS      100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t *byte)
{
    if (read(fd, byte, 1) != 1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /*
     * PCF8591 control byte (write):
     *   bit 7: 0  (no auto-increment)
     *   bit 6: 0  (no analog output)
     *   bit 5: 0  (no four-wire interface)
     *   bit 4: 1  (single-ended mode)
     *   bit 3: 0  (channel 0)
     *   bit 2: 0
     *   bit 1: 0
     *   bit 0: 0
     * => 0x40
     */
    if (i2c_write_byte(fd, 0x40) < 0) {
        goto cleanup;
    }

    /*
     * PCF8591 returns the result of the *previous* conversion on the
     * next read.  A dummy read discards that stale byte so the
     * following read returns the current sample.
     */
    uint8_t dummy;
    if (i2c_read_byte(fd, &dummy) < 0) {
        goto cleanup;
    }

    while (g_running) {
        uint8_t sample;
        if (i2c_read_byte(fd, &sample) < 0) {
            goto cleanup;
        }
        printf("AIN0: %u\n", (unsigned)sample);
        fflush(stdout);
        usleep(SAMPLE_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

