#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define ADC_CHANNEL    0x4000  /* AIN0 single-ended, MUX bits 14:12 = 100 */
#define ADC_CONFIG     0x8000  /* OS bit 15 = start conversion */
#define ADC_PGA_4_096  0x0200  /* PGA = 4.096 V */
#define ADC_MODE_SS    0x0100  /* Single-shot mode */
#define ADC_DR_128     0x0080  /* 128 SPS */
#define ADC_CQUE_NONE  0x0003  /* Disable comparator */
#define ADC_RES_16BIT  0x0000  /* 16-bit result */

#define MOTOR_SHUTDOWN_PIN 27
#define BUFFER_SIZE       10
#define SAMPLE_PERIOD_US  1000000  /* 1 Hz */
#define THRESHOLD_GAUSS   500.0f
#define VREF              3.3f
#define SS49E_ZERO_V      2.5f
#define SS49E_SENS_V_G    0.0014f  /* 1.4 mV/Gauss */

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cb_init(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float cb_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/* Read raw 16-bit ADC value from ADS1115 single-ended channel */
static int read_adc_raw(int handle, uint8_t channel) {
    uint16_t config = ADC_CONFIG | ADC_MODE_SS | ADC_DR_128 |
                      ADC_PGA_4_096 | ADC_CQUE_NONE | ADC_RES_16BIT |
                      (channel & 0x07);

    char cfg[3];
    cfg[0] = 0x01;
    cfg[1] = (config >> 8) & 0xFF;
    cfg[2] = config & 0xFF;

    if (i2cWriteDevice(handle, cfg, 3) < 0) {
        syslog(LOG_ERR, "I2C write config failed");
        return -1;
    }

    /* Wait for conversion (~8 ms at 128 SPS, poll OS bit) */
    for (int i = 0; i < 20; i++) {
        char reg[1] = {0x01};
        if (i2cWriteDevice(handle, reg, 1) < 0) {
            syslog(LOG_ERR, "I2C write reg select failed");
            return -1;
        }
        char val[2];
        if (i2cReadDevice(handle, val, 2) < 0) {
            syslog(LOG_ERR, "I2C read config failed");
            return -1;
        }
        if (val[0] & 0x80) break;
        gpioDelay(1000);
    }

    char reg[1] = {0x00};
    if (i2cWriteDevice(handle, reg, 1) < 0) {
        syslog(LOG_ERR, "I2C write reg select failed");
        return -1;
    }
    char val[2];
    if (i2cReadDevice(handle, val, 2) < 0) {
        syslog(LOG_ERR, "I2C read conversion failed");
        return -1;
    }
    return (val[0] << 8) | val[1];
}

static float raw_to_voltage(int raw) {
    int16_t signed_raw = (int16_t)raw;
    return (float)signed_raw * VREF / 32768.0f;
}

static float voltage_to_gauss(float v) {
    return (v - SS49E_ZERO_V) / SS49E_SENS_V_G;
}

static void control_motor(float avg_gauss) {
    if (avg_gauss > THRESHOLD_GAUSS) {
        if (gpioRead(MOTOR_SHUTDOWN_PIN) == 0) {
            if (gpioWrite(MOTOR_SHUTDOWN_PIN, 1) == 0) {
                syslog(LOG_WARNING, "Threshold exceeded (%.2f G), motor shutdown -> HIGH", avg_gauss);
            } else {
                syslog(LOG_ERR, "Failed to set motor shutdown pin HIGH");
            }
        }
    } else {
        if (gpioRead(MOTOR_SHUTDOWN_PIN) == 1) {
            if (gpioWrite(MOTOR_SHUTDOWN_PIN, 0) == 0) {
                syslog(LOG_INFO, "Field below threshold (%.2f G), motor shutdown -> LOW", avg_gauss);
            } else {
                syslog(LOG_ERR, "Failed to set motor shutdown pin LOW");
            }
        }
    }
}

int main(void) {
    openlog("hall_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %d addr 0x%02X: %d", I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", MOTOR_SHUTDOWN_PIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(MOTOR_SHUTDOWN_PIN, 0);

    CircularBuffer mag_buffer;
    cb_init(&mag_buffer);

    syslog(LOG_INFO, "Monitoring SS49E Hall sensor via ADS1115 (I2C 0x%02X, ch0). Threshold %.1f G",
           I2C_ADDR, THRESHOLD_GAUSS);

    while (running) {
        int raw = read_adc_raw(i2c_handle, ADC_CHANNEL);
        if (raw < 0) {
            syslog(LOG_ERR, "ADC read failed, skipping sample");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float voltage = raw_to_voltage(raw);
        if (voltage < 0.0f || voltage > VREF) {
            syslog(LOG_ERR, "Invalid voltage %.3f V (raw=%d), skipping sample", voltage, raw);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float gauss = voltage_to_gauss(voltage);
        cb_add(&mag_buffer, gauss);
        float avg = cb_average(&mag_buffer);

        syslog(LOG_INFO, "Raw=%d  V=%.3f  B=%.2f G  avg=%.2f G", raw, voltage, gauss, avg);
        control_motor(avg);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    syslog(LOG_INFO, "Shutting down");
    gpioWrite(MOTOR_SHUTDOWN_PIN, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

