#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* mode 0, active-low CE */
#define PWM_PIN     18
#define PWM_FREQ    1000     /* 1 kHz */
#define PWM_RANGE   1023     /* 10-bit resolution */
#define ADC_CHANNEL 0
#define SAMPLE_US   100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel (0-7) from the MCP3008.
 * Returns 0-1023 on success, -1 on SPI error.
 */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read: 3-byte transfer.
     * tx[0] = 0x01  start bit
     * tx[1] = (0x08 | channel) << 4  single-ended + channel, upper nibble
     * tx[2] = 0x00  don't-care
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
