#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17
#define SAMPLE_INTERVAL_US 100000
#define BLINK_DURATION_US 1000000
#define BLINK_HALF_PERIOD_US 50000

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

/* Config: single-shot, AIN0 single-ended, PGA=4.096V, 128 SPS, no comparator */
#define ADS1115_CONFIG_BASE 0x8000  /* OS bit */
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_CONFIG_DEFAULT (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 | \
                               ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_DR_128SPS | \
                               ADS1115_CONFIG_CQUE_NONE)

/* SS49E: 1.65 V at zero gauss, 1 mV/Gauss = 0.001 V/Gauss */
#define SS49E_ZERO_GAUSS_V 1.65f
#define SS49E_SENSITIVITY_V_PER_GAUSS 0.001f
#define SS49E_VREF 4.096f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t read_ads1115(int handle) {
    char config[3];
    char reg[1] = { ADS1115_REG_CONFIG };
    char data[2];
    int16_t raw;

    /* Write config to start a single-shot conversion */
    config[0] = (ADS1115_CONFIG_DEFAULT >> 8) & 0xFF;
    config[1] = ADS1115_CONFIG_DEFAULT & 0xFF;
    if (i2cWriteI2CBlockData(handle, ADS1115_REG_CONFIG, config, 2) < 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config\n");
        return -1;
    }

    /* Wait for conversion (~8 ms at 128 SPS) */
    gpioDelay(10000);

    /* Read conversion register */
    if (i2cReadI2CBlockData(handle, ADS1115_REG_CONVERSION, data, 2) < 0) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion\n");
        return -1;
    }

    raw = (int16_t)((data[0] << 8) | data[1]);
    return raw;
}

static float raw_to_gauss(int16_t raw) {
    float voltage = (raw / 32767.0f) * SS49E_VREF;
    float gauss = (voltage - SS49E_ZERO_GAUSS_V) / SS49E_SENSITIVITY_V_PER_GAUSS;
    return gauss;
}

static void blink_led(int gpio, int duration_us) {
    uint32_t start = gpioTick();
    while (running && (gpioTick() - start) < duration_us) {
        gpioWrite(gpio, 1);
        gpioDelay(BLINK_HALF_PERIOD_US);
        gpioWrite(gpio, 0);
        gpioDelay(BLINK_HALF_PERIOD_US);
    }
}

int main(int argc, char *argv[]) {
    float threshold = 100.0f;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Error: threshold must be positive\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_gauss]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X\n",
                I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring SS49E Hall sensor on ADS1115 (I2C 0x%02X, AIN0).\n", ADS1115_ADDR);
    printf("Threshold: %.2f Gauss. Press Ctrl+C to exit.\n", threshold);

    while (running) {
        int16_t raw = read_ads1115(i2c_handle);
        if (raw < 0) {
            fprintf(stderr, "Warning: ADC read failed, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float gauss = raw_to_gauss(raw);
        printf("Magnetic Field: %.2f Gauss\n", gauss);

        if (gauss > threshold) {
            printf("Threshold exceeded! Blinking LED.\n");
            blink_led(LED_GPIO, BLINK_DURATION_US);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

