#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000
#define MCP3008_CHANNEL  0
#define RELAY_GPIO       17
#define MOISTURE_THRESHOLD_LOW  30.0f
#define MOISTURE_THRESHOLD_HIGH 35.0f
#define MQTT_HOST        "localhost"
#define MQTT_PORT        1883
#define MQTT_TOPIC_SOIL  "soil_moisture"
#define MQTT_TOPIC_PUMP  "pump_control"
#define SAMPLE_INTERVAL  60

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static struct mosquitto *mosq = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float read_soil_moisture(void) {
    int adc = read_mcp3008(MCP3008_CHANNEL);
    if (adc < 0) return -1.0f;
    if (adc < 10 || adc > 1000) {
        syslog(LOG_WARNING, "ADC out of range: %d (sensor absent?)", adc);
        return -1.0f;
    }
    return 100.0f - ((float)adc / 1023.0f) * 100.0f;
}

static int control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write relay GPIO %d", RELAY_GPIO);
        return -1;
    }
    syslog(LOG_INFO, "Relay %s", state ? "ON" : "OFF");
    return 0;
}

static void on_connect(struct mosquitto *m, void *ud, int rc) {
    (void)ud;
    if (rc == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected");
        if (mosquitto_subscribe(m, NULL, MQTT_TOPIC_PUMP, 0) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Subscribe failed: %s", mosquitto_strerror(mosquitto_errno(m)));
        }
    } else {
        syslog(LOG_ERR, "MQTT connect error: %s", mosquitto_strerror(rc));
    }
}

static void on_message(struct mosquitto *m, void *ud, const struct mosquitto_message *msg) {
    (void)m; (void)ud;
    if (!msg || !msg->payload || msg->payloadlen <= 0) return;
    if (strcmp((const char *)msg->topic, MQTT_TOPIC_PUMP) != 0) return;
    if (strcmp((const char *)msg->payload, "pump_on") == 0) {
        control_relay(1);
    } else if (strcmp((const char *)msg->payload, "pump_off") == 0) {
        control_relay(0);
    } else {
        syslog(LOG_WARNING, "Unknown pump command: %.*s", msg->payloadlen, (char *)msg->payload);
    }
}

static void on_disconnect(struct mosquitto *m, void *ud, int rc) {
    (void)m; (void)ud;
    syslog(LOG_INFO, "MQTT disconnected (rc=%d)", rc);
}

int main(void) {
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa = { .sa_handler = signal_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio init failed");
        closelog();
        return 1;
    }
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set relay GPIO %d as output", RELAY_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %d", spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "mosquitto_new failed");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }
    mosquitto_loop_start(mosq);

    int pump_active = 0;
    while (running) {
        float moisture = read_soil_moisture();
        if (moisture < 0.0f) {
            syslog(LOG_ERR, "Sensor read failed; skipping cycle");
        } else {
            syslog(LOG_INFO, "Moisture: %.2f%%", moisture);
            if (mosquitto_publish(mosq, NULL, MQTT_TOPIC_SOIL,
                                  (int)strlen(MQTT_TOPIC_SOIL),
                                  MQTT_TOPIC_SOIL, 0, false) != MOSQ_ERR_SUCCESS) {
                syslog(LOG_ERR, "MQTT publish failed");
            }
            if (moisture < MOISTURE_THRESHOLD_LOW && !pump_active) {
