#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <math.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES_MODE_2 0x11
#define BH1750_MEASUREMENT_DELAY_MS 180
#define LOG_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL_SEC 5
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define ADC_CHANNEL 0
#define ADC_MAX_VALUE 1023
#define ADC_VREF 3.3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) return -1;
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {0};
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = 8;
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_bh1750(int fd) {
    uint8_t cmd = BH1750_CONT_HIGH_RES_MODE_2;
    if (write(fd, &cmd, 1) != 1) return -1;
    usleep(BH1750_MEASUREMENT_DELAY_MS * 1000);
    uint8_t buf[2] = {0};
    if (read(fd, buf, 2) != 2) return -1;
    return (buf[0] << 8) | buf[1];
}

static float calculate_sound_level(int adc_value) {
    if (adc_value <= 0) return -100.0f;
    float voltage = (float)adc_value / (float)ADC_MAX_VALUE * ADC_VREF;
    if (voltage < 0.001f) return -100.0f;
    return 20.0f * log10f(voltage);
}

static int log_data(FILE *fp, float sound_level, int light_level, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return -1;
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%d,%d\n", ts, sound_level, light_level, error_code) < 0) return -1;
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) { perror("open SPI"); return 1; }
    uint8_t mode = SPI_MODE_0, bits = 8;
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI config"); close(spi_fd); return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) { perror("open I2C"); close(spi_fd); return 1; }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("I2C slave"); close(i2c_fd); close(spi_fd); return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) { perror("fopen"); close(i2c_fd); close(spi_fd); return 1; }
    fseek(log_fp, 0, SEEK_END);
    if (ftell(log_fp) == 0) fprintf(log_fp, "timestamp,sound_level_db,light_level_lux,error_code\n");

    while (running) {
        int adc = read_mcp3008(spi_fd, ADC_CHANNEL);
        int light = read_bh1750(i2c_fd);
        float sound = (adc >= 0) ? calculate_sound_level(adc) : -100.0f;
        int lvl = (light >= 0) ? light : -1;
        int err = (adc < 0 || light < 0) ? 1 : 0;
        if (log_data(log_fp, sound, lvl, err) < 0) {
            fprintf(stderr, "Log write failed\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    if (spi_fd >= 0) close(spi_fd);
    return 0;
}

