            sleep(DEBOUNCE_DELAY_S);
            relay_set(0);
            log_event("Door closed");
            printf("Door closed\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
