#include <string.h>
#include <unistd.h>

#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL 5
#define NUM_SENSORS 3

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_sensors(int *values) {
    int valid = 0;
    for (int i = 0; i < NUM_SENSORS; i++) {
        int v = read_mcp3008(i);
        if (v >= 0) {
            values[valid] = v;
            valid++;
        } else {
            fprintf(stderr, "Sensor %d read failed\n", i);
        }
    }
    return valid;
}

static int average_sensor(const int *values, int count) {
    if (count <= 0) return 0;
    long sum = 0;
    for (int i = 0; i < count; i++) sum += values[i];
    return (int)(sum / count);
}

static int map_sensor_to_valve(int sensor_value) {
    if (sensor_value < 0) sensor_value = 0;
    if (sensor_value > 1023) sensor_value = 1023;
    return 100 - (int)((float)sensor_value / 1023.0f * 100.0f);
}

static void set_valve_position(int position) {
    if (position < 0) position = 0;
    if (position > 100) position = 100;
    gpioPWM(VALVE_GPIO, position);
}

static void log_data(const int *sensor_values, int avg, int valve_pos) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, %d, %d, %d, %d\n", ts, sensor_values[0], sensor_values[1], sensor_values[2], valve_pos);
    fflush(log_file);
}

