    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);
    gpioPWM(VALVE_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Cannot open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int sensor_values[NUM_SENSORS] = {0};

    while (running) {
        int valid = read_sensors(sensor_values);
        if (valid == 0) {
            fprintf(stderr, "All sensor reads failed; skipping cycle\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }
        int avg = average_sensor(sensor_values, valid);
        int valve_pos = map_sensor_to_valve(avg);
        set_valve_position(valve_pos);
        log_data(sensor_values, avg, valve_pos);
        sleep(SAMPLE_INTERVAL);
    }

    gpioPWM(VALVE_GPIO, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

