#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0 (GPIO8)
#define SPI_SPEED 1000000   // 1 MHz
#define MCP3008_CHANNEL 0   // CH0
#define LOG_FILE "soil_data.txt"
#define SLEEP_INTERVAL 5    // seconds
#define MAX_RETRIES 5
#define RETRY_DELAY_MS 100  // base delay in ms

// Global variables
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_moisture(int adc_value);
void log_data(float moisture_level);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

// Function to read from MCP3008 ADC with retry logic
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];
    int adc_value = -1;
    int retries = 0;
    int delay_ms = RETRY_DELAY_MS;

    // MCP3008 SPI command: start bit (1), single-ended mode (1), channel select (3 bits)
    tx_buffer[0] = 0x01;  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;  // Single-ended mode + channel
    tx_buffer[2] = 0x00;  // Don't care

    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 3) {
            // Extract 10-bit ADC value: bits 1-2 of rx_buffer[1] and all of rx_buffer[2]
            adc_value = ((rx_buffer[1] & 0x03) << 8) | (rx_buffer[2] & 0xFF);
            if (adc_value >= 0 && adc_value <= 1023) {
                return adc_value;
            } else {
                fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
                return -1;
            }
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(delay_ms * 1000);  // pigpio delay is in microseconds
            delay_ms *= 2;  // Exponential backoff
        }
    }

    fprintf(stderr, "Error: SPI communication failed after %d retries\n", MAX_RETRIES);
    return -1;
}

// Function to convert ADC value to moisture level (percentage)
float convert_to_moisture(int adc_value) {
    // YL-69 sensor: higher voltage = drier soil. 
    // Assuming 0V = 0% moisture, 3.3V = 100% moisture.
    // Linear mapping: moisture = (adc_value / 1023.0) * 100.0
    return (adc_value / 1023.0f) * 100.0f;
}

// Function to log data to file
void log_data(float moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_level);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel (Mode 0, active low CS)
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            float moisture_level = convert_to_moisture(adc_value);
            log_data(moisture_level);
            printf("Moisture level: %.2f%%\n", moisture_level);
        } else {
            fprintf(stderr, "Error: Failed to read soil moisture. Skipping logging.\n");
        }

        // Sleep for the specified interval, checking for termination
        for (int i = 0; i < SLEEP_INTERVAL && !terminate; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);  // Sleep 1 second
        }
    }

    // Cleanup
    cleanup();
    printf("Soil moisture monitoring stopped.\n");

    return 0;
}

