#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <gpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPI_DEVICE "/dev/spidev0.0"
#define CONFIG_FILE "theremin_config.txt"

#define MIN_FREQUENCY 220.0
#define MAX_FREQUENCY 880.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define PWM_PERIOD_NS 1000000
#define SAMPLE_RATE 100
#define TIMEOUT_US 30000

volatile sig_atomic_t program_running = 1;

struct gpiod_chip *chip = NULL;
struct gpiod_line *trig_line = NULL;
struct gpiod_line *echo_line = NULL;
int spi_fd = -1;

float min_distance = MIN_DISTANCE;
float max_distance = MAX_DISTANCE;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig_line || !echo_line) {
        perror("gpiod_chip_get_line");
        return -1;
    }

    if (gpiod_line_request_output(trig_line, "theremin", 0) < 0) {
        perror("gpiod_line_request_output (trig)");
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "theremin") < 0) {
        perror("gpiod_line_request_input (echo)");
        return -1;
    }

    return 0;
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI");
        return -1;
    }

    int mode = 0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        return -1;
    }

    int bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl SPI_IOC_WR_BITS_PER_WORD");
        return -1;
    }

    int speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        return -1;
    }

    return 0;
}

int init_pwm() {
    int fd = open("/sys/class/pwm/pwmchip0/export", O_WRONLY);
    if (fd < 0) {
        if (errno != EBUSY) {
            perror("open pwm export");
            return -1;
        }
    } else {
        const char *pwm_num = "0";
        if (write(fd, pwm_num, strlen(pwm_num)) < 0) {
            perror("write pwm export");
            close(fd);
            return -1;
        }
        close(fd);
    }

    usleep(100000);

    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/period");
    int pfd = open(path, O_WRONLY);
    if (pfd < 0) {
        perror("open period");
        return -1;
    }
    char buf[16];
    snprintf(buf, sizeof(buf), "%d", PWM_PERIOD_NS);
    if (write(pfd, buf, strlen(buf)) < 0) {
        perror("write period");
        close(pfd);
        return -1;
    }
    close(pfd);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    pfd = open(path, O_WRONLY);
    if (pfd < 0) {
        perror("open duty_cycle");
        return -1;
    }
    snprintf(buf, sizeof(buf), "0");
    if (write(pfd, buf, strlen(buf)) < 0) {
        perror("write duty_cycle");
        close(pfd);
        return -1;
    }
    close(pfd);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm0/enable");
    pfd = open(path, O_WRONLY);
    if (pfd < 0) {
        perror("open enable");
        return -1;
    }
    const char *en = "1";
    if (write(pfd, en, strlen(en)) < 0) {
        perror("write enable");
        close(pfd);
        return -1;
    }
    close(pfd);

    return 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;

    unsigned char tx[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
