#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define AQI_THRESHOLD 100
#define LOG_FILE "air_quality.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 1000
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calculate_aqi(int adc_value) {
    if (adc_value < 0) return -1;
    return (int)(((float)adc_value / 1023.0f) * 500.0f);
}

static void control_fan(int aqi) {
    if (aqi > AQI_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1);
        printf("AQI %d > %d: Fan ON\n", aqi, AQI_THRESHOLD);
    } else {
        gpioWrite(FAN_GPIO, 0);
        printf("AQI %d <= %d: Fan OFF\n", aqi, AQI_THRESHOLD);
    }
}

static void log_data(int aqi) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, AQI: %d\n", timestamp, aqi);
    fflush(log_file);
}

static int initialize_spi(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && running) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value >= 0) break;
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "SPI read failed, retry %d/%d\n", retries, MAX_RETRIES);
                gpioDelay(RETRY_DELAY_MS * 1000);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "SPI read failed after %d retries. Re-initializing SPI.\n", MAX_RETRIES);
            if (initialize_spi() != 0) {
                fprintf(stderr, "SPI re-init failed. Exiting.\n");
                break;
            }
            continue;
        }

        int aqi = calculate_aqi(adc_value);
        if (aqi < 0) {
            fprintf(stderr, "AQI calculation error\n");
            continue;
        }

        control_fan(aqi);
        log_data(aqi);

        for (int i = 0; i < SAMPLE_INTERVAL_S && running; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

