#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 18
#define MOISTURE_THRESHOLD 300 // 10-bit ADC value (0-1023)
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL 60 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void log_data(int moisture_level, int pump_state);
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // MCP3008 SPI command format for single-ended mode:
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel << 4
    // Byte 2: Don't care (0x00)
    tx_buf[0] = 0x01;
    tx_buf[1] = 0x80 | (channel << 4);
    tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract 10-bit ADC value from response
    // rx_buf[1] contains the two most significant bits in its lower 2 bits
    // rx_buf[2] contains the 8 least significant bits
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
}

// Function to log data to file
void log_data(int moisture_level, int pump_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - Moisture: %d, Pump: %s\n",
            timestamp, moisture_level, pump_state ? "ON" : "OFF");
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    control_pump(0); // Turn off the pump
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    control_pump(0); // Ensure pump is off initially

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read moisture level from channel 0
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Failed to read moisture level\n");
            log_data(-1, 0); // Log error with invalid moisture level
        } else {
            // Determine pump state based on threshold
            int pump_state = (moisture_level < MOISTURE_THRESHOLD) ? 1 : 0;
            control_pump(pump_state);
            log_data(moisture_level, pump_state);
        }

        // Wait for the next sample interval
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

