// Motor 1
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Potentiometer ADC channels
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// Speed limits
#define MIN_SPEED 50
#define MAX_SPEED 255

// Global variables for cleanup
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_potentiometer(int channel);
float calculate_speed_factor(int pot_value);
void set_motor_speed(int enable_pin, int direction_pin, int speed);
void move_motor(int enable_pin, int direction_pin, int speed);
void motion_profile();
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read the value from the MCP3008 ADC
int read_potentiometer(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message for MCP3008
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate the speed factor based on the potentiometer value
float calculate_speed_factor(int pot_value) {
    if (pot_value < 0 || pot_value > 1023) {
        fprintf(stderr, "Invalid potentiometer value: %d\n", pot_value);
        return 0.0;
    }

    // Normalize the potentiometer value to a range of 0 to 1
    float normalized_value = (float)pot_value / 1023.0;

    // Apply a logarithmic scaling function for finer control
    float speed_factor = 1.0 + (log10(normalized_value + 0.1) * 9.0);

    // Clamp the speed factor to a reasonable range
    if (speed_factor < 0.1) speed_factor = 0.1;
    if (speed_factor > 10.0) speed_factor = 10.0;

    return speed_factor;
}

// Function to set the speed of a motor using PWM
void set_motor_speed(int enable_pin, int direction_pin, int speed) {
    if (speed < 0 || speed > 255) {
        fprintf(stderr, "Invalid speed value: %d\n", speed);
        return;
    }

