        pot1_value = read_potentiometer(POT1_CHANNEL);
        pot2_value = read_potentiometer(POT2_CHANNEL);

        if (pot1_value == -1 || pot2_value == -1) {
            fprintf(stderr, "Error reading potentiometers, retrying...\n");
            gpioDelay(1000000); // 1 second delay before retrying
            continue;
