        // Calculate speed factors
        speed_factor1 = calculate_speed_factor(pot1_value);
        speed_factor2 = calculate_speed_factor(pot2_value);

        // Calculate motor speeds
        motor1_speed = (int)(MIN_SPEED + (speed_factor1 * (MAX_SPEED - MIN_SPEED)));
        motor2_speed = (int)(MIN_SPEED + (speed_factor2 * (MAX_SPEED - MIN_SPEED)));

        // Move Motor 1 forward
        move_motor(MOTOR1_ENABLE, MOTOR1_DIRECTION, motor1_speed);

        // Move Motor 2 backward
        move_motor(MOTOR2_ENABLE, MOTOR2_DIRECTION, motor2_speed);

