        gpioDelay(2000000);

        // Decelerate to MIN_SPEED
        while (motor1_speed > MIN_SPEED && motor2_speed > MIN_SPEED && !terminate) {
            motor1_speed -= 10;
            motor2_speed -= 10;
            if (motor1_speed < MIN_SPEED) motor1_speed = MIN_SPEED;
            if (motor2_speed < MIN_SPEED) motor2_speed = MIN_SPEED;

