            set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, motor2_speed);
            gpioDelay(50000); // 50ms delay for smooth deceleration
        }

        // Pause for 5 seconds
        gpioDelay(5000000);

        // Reverse directions
        gpioWrite(MOTOR1_DIRECTION, 0); // Backward direction
        gpioWrite(MOTOR2_DIRECTION, 1); // Forward direction

        // Accelerate back to MAX_SPEED
        while (motor1_speed < MAX_SPEED && motor2_speed < MAX_SPEED && !terminate) {
            motor1_speed += 10;
            motor2_speed += 10;
            if (motor1_speed > MAX_SPEED) motor1_speed = MAX_SPEED;
            if (motor2_speed > MAX_SPEED) motor2_speed = MAX_SPEED;

            set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, motor1_speed);
            set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, motor2_speed);
            gpioDelay(50000); // 50ms delay for smooth acceleration
        }

        // Hold position for 2 seconds
        gpioDelay(2000000);
    }
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    gpioPWM(MOTOR1_ENABLE, 0);
    gpioPWM(MOTOR2_ENABLE, 0);
    gpioWrite(MOTOR1_DIRECTION, 0);
    gpioWrite(MOTOR2_DIRECTION, 0);

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    gpioTerminate();
}

