#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define CALIBRATION_TIME 5
#define DEBOUNCE_DELAY_MS 10
#define SAMPLE_DELAY_US 10000
#define NOISE_THRESHOLD_PERCENT 10

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int calibrate_ambient_level(int duration_seconds) {
    printf("Calibrating ambient sound level for %d seconds...\n", duration_seconds);
    long sum = 0;
    int count = 0;
    time_t start = time(NULL);

    while (time(NULL) - start < duration_seconds && running) {
        int level = read_mcp3008(MCP3008_CHANNEL);
        if (level < 0) {
            fprintf(stderr, "Error reading MCP3008 during calibration\n");
            return -1;
        }
        sum += level;
        count++;
        gpioDelay(SAMPLE_DELAY_US);
    }

    if (!running) {
        return -1;
    }

    if (count == 0) {
        fprintf(stderr, "No samples taken during calibration\n");
        return -1;
    }

    return (int)(sum / count);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int ambient_level = calibrate_ambient_level(CALIBRATION_TIME);
    if (ambient_level < 0) {
        fprintf(stderr, "Calibration failed or interrupted\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    int threshold = ambient_level + (ambient_level * NOISE_THRESHOLD_PERCENT / 100);
    printf("Ambient level: %d, Threshold: %d\n", ambient_level, threshold);

    int led_state = 0;
    time_t last_toggle = 0;

    while (running) {
        int level = read_mcp3008(MCP3008_CHANNEL);
        if (level < 0) {
            fprintf(stderr, "Error reading MCP3008\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        if (level > threshold) {
            time_t now = time(NULL);
            if (now - last_toggle > DEBOUNCE_DELAY_MS / 1000.0) {
                if (!led_state) {
                    gpioWrite(LED_PIN, 1);
                    led_state = 1;
                    last_toggle = now;
                    printf("Noise detected! Level: %d\n", level);
                }
            }
        } else {
            if (led_state) {
                gpioWrite(LED_PIN, 0);
                led_state = 0;
            }
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

