            time_t now = time(NULL);
            if (now - last_toggle > DEBOUNCE_DELAY_MS / 1000.0) {
                if (!led_state) {
                    gpioWrite(LED_PIN, 1);
                    led_state = 1;
                    last_toggle = now;
