                }
            }
        } else {
            if (led_state) {
                gpioWrite(LED_PIN, 0);
                led_state = 0;
            }
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

