// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0     // MCP3008 channel 0
#define VREF 3.3          // Reference voltage for MCP3008
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "airflow_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float voltage_to_airflow(int adc_value);
void log_airflow(float airflow);
void log_error(const char *message);
void timer_callback(void *user_data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // MCP3008 SPI command: start bit (1), single-ended mode (1), channel select (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode + channel
    tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to airflow (SLPM)
float voltage_to_airflow(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    // Linear mapping: 0.5V -> 0 SLPM, 4.5V -> 200 SLPM
    float airflow = (voltage - 0.5) / (4.5 - 0.5) * 200.0;
    return airflow;
}

// Function to log airflow data to file
void log_airflow(float airflow) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Airflow: %.2f SLPM\n", timestamp, airflow);
    fflush(log_file);
}

// Function to log errors to file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

// Timer callback function
void timer_callback(void *user_data) {
    (void)user_data; // Suppress unused parameter warning
    int adc_value = read_mcp3008(ADC_CHANNEL);
    if (adc_value >= 0) {
        float airflow = voltage_to_airflow(adc_value);
        log_airflow(airflow);
    } else {
        log_error("ADC read failed");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up timer
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, timer_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set timer\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop (wait for termination signal)
    while (!terminate) {
        sleep(1);
    }

    // Cleanup
    gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, NULL, NULL); // Disable timer
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Airflow monitoring stopped.\n");
    return 0;
}

