#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_LINE_OFFSET  8
#define LOG_FILE        "audio_log.txt"
#define SAMPLE_RATE_HZ  1000
#define SAMPLE_PERIOD_NS (1000000000L / SAMPLE_RATE_HZ)

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int spi_open(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("open(spidev)");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }

    uint32_t speed = 1000000;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }

    return fd;
}

static int mcp3008_read(int spi_fd, struct gpiod_line *cs_line, uint8_t channel)
{
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("gpiod_line_set_value(CS low)");
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("gpiod_line_set_value(CS high)");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int log_sample(FILE *fp, long timestamp_ns, int adc_value)
{
    if (fprintf(fp, "%ld|%d\n", timestamp_ns, adc_value) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

int main(void)
{
    if (install_signal_handlers() < 0) {
        return EXIT_FAILURE;
    }

    int spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(log)");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct timespec next_sample;
    clock_gettime(CLOCK_MONOTONIC_RAW, &next_sample);

    while (g_running) {
        int adc_value = mcp3008_read(spi_fd, cs_line, 0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; continuing.\n");
        } else {
            struct timespec ts;
            if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) < 0) {
                perror("clock_gettime");
            } else {
                long ts_ns = (long)ts.tv_sec * 1000000000L + ts.tv_nsec;
                if (log_sample(log_fp, ts_ns, adc_value) < 0) {
                    fprintf(stderr, "Logging failed; continuing.\n");
                }
            }
        }

        next_sample.tv_nsec += SAMPLE_PERIOD_NS;
        if (next_sample.tv_nsec >= 1000000000L) {
            next_sample.tv_sec += 1;
            next_sample.tv_nsec -= 1000000000L;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC_RAW, &now);
        if (next_sample.tv_sec > now.tv_sec ||
            (next_sample.tv_sec == now.tv_sec && next_sample.tv_nsec > now.tv_nsec)) {
            struct timespec sleep_ts;
            sleep_ts.tv_sec = next_sample.tv_sec - now.tv_sec;
            sleep_ts.tv_nsec = next_sample.tv_nsec - now.tv_nsec;
            if (sleep_ts.tv_nsec < 0) {
                sleep_ts.tv_sec -= 1;
                sleep_ts.tv_nsec += 1000000000L;
            }
            if (sleep_ts.tv_sec > 0 || sleep_ts.tv_nsec > 0) {
                nanosleep(&sleep_ts, NULL);
            }
        } else {
            next_sample = now;
        }
    }

    fprintf(stderr, "Shutting down gracefully.\n");
    fclose(log_fp);
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    close(spi_fd);
    return EXIT_SUCCESS;
}

