#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MCP3008 SPI Configuration
#define MCP3008_CS_PIN 8
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// ADXL335 Sensitivity and Zero-G Bias
#define ADXL335_SENSITIVITY 0.300 // 300 mV/g
#define ADXL335_ZERO_G_BIAS 1.5   // 1.5V

// Kalman Filter Parameters
#define Q 0.001
#define R 0.01

// Global variables
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Kalman filter state
typedef struct {
    float x; // State estimate
    float P; // Estimate covariance
} kalman_state_t;

kalman_state_t kf_x = {0.0, 1.0};
kalman_state_t kf_y = {0.0, 1.0};
kalman_state_t kf_z = {0.0, 1.0};

// Function prototypes
int read_mcp3008(int channel);
float adxl335_to_g(int adc_value);
float kalman_filter(float measurement, kalman_state_t *state);
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message for MCP3008
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    gpioWrite(MCP3008_CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS_PIN, 1); // Deselect the MCP3008

    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to g-force
float adxl335_to_g(int adc_value) {
    float voltage = (adc_value / 1023.0) * 3.3; // Convert to voltage
    float voltage_zero_g = ADXL335_ZERO_G_BIAS;
    float voltage_sensitivity = ADXL335_SENSITIVITY;
    float voltage_difference = voltage - voltage_zero_g;
    return voltage_difference / voltage_sensitivity;
}

// Kalman filter function
float kalman_filter(float measurement, kalman_state_t *state) {
    // Prediction
    state->P = state->P + Q;

    // Update
    float K = state->P / (state->P + R);
    state->x = state->x + K * (measurement - state->x);
    state->P = (1 - K) * state->P;

    return state->x;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(MCP3008_CS_PIN, PI_OUTPUT);
    gpioWrite(MCP3008_CS_PIN, 1); // Deselect MCP3008 initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL335 Kalman Filter Test (via MCP3008 ADC)\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC values
        int x_adc = read_mcp3008(0);
        int y_adc = read_mcp3008(1);
        int z_adc = read_mcp3008(2);

        if (x_adc < 0 || y_adc < 0 || z_adc < 0) {
            fprintf(stderr, "Error: Failed to read ADC values. Retrying...\n");
            gpioDelay(100000); // 100ms delay before retry
            continue;
        }

        // Convert ADC values to g-force
        float x_g = adxl335_to_g(x_adc);
        float y_g = adxl335_to_g(y_adc);
        float z_g = adxl335_to_g(z_adc);

        // Apply Kalman filter
        float x_filtered = kalman_filter(x_g, &kf_x);
        float y_filtered = kalman_filter(y_g, &kf_y);
        float z_filtered = kalman_filter(z_g, &kf_z);

        // Print filtered values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x_filtered, y_filtered, z_filtered);

        // Delay for 100ms (10 Hz sampling rate)
        gpioDelay(100000);
    }

    // Cleanup
    cleanup();
    printf("\nProgram terminated.\n");
    return 0;
}

