#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

#define VCC 3.3f
#define V_QUIESCENT (VCC / 2.0f)
#define SENSITIVITY 0.025f
#define MIN_MAGNETIC_FIELD -100.0f
#define MAX_MAGNETIC_FIELD 100.0f
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static float read_sensor(struct gpiod_line *line, int pin) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, strerror(errno));
        return -1.0f;
    }
    float voltage = (val == 1) ? VCC : 0.0f;
    return (voltage - V_QUIESCENT) / SENSITIVITY;
}

static void log_data(FILE *fp, float s1, float s2, float s3) {
    if (fprintf(fp, "%.2f,%.2f,%.2f\n", s1, s2, s3) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    } else {
        fflush(fp);
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    const int pins[3] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN};
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "drv5055_reader") < 0) {
            fprintf(stderr, "Failed to request GPIO %d as input: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    while (program_running) {
        float s1 = read_sensor(lines[0], SENSOR1_PIN);
        float s2 = read_sensor(lines[1], SENSOR2_PIN);
        float s3 = read_sensor(lines[2], SENSOR3_PIN);

        if (s1 < 0.0f || s2 < 0.0f || s3 < 0.0f) {
            fprintf(stderr, "Error reading sensor data, skipping log entry.\n");
        } else {
            log_data(fp, s1, s2, s3);
            if (s1 < MIN_MAGNETIC_FIELD || s1 > MAX_MAGNETIC_FIELD ||
                s2 < MIN_MAGNETIC_FIELD || s2 > MAX_MAGNETIC_FIELD ||
                s3 < MIN_MAGNETIC_FIELD || s3 > MAX_MAGNETIC_FIELD) {
                fprintf(stderr, "Warning: Magnetic field out of range (%.2f, %.2f, %.2f) mT\n", s1, s2, s3);
            }
        }

        struct timespec ts;
        ts.tv_sec = SAMPLE_INTERVAL_MS / 1000;
        ts.tv_nsec = (SAMPLE_INTERVAL_MS % 1000) * 1000000L;
        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    for (int i = 0; i < 3; i++) {
        if (lines[i]) gpiod_line_release(lines[i]);
    }
    if (chip) gpiod_chip_close(chip);
    return ret;
}

