#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30.0
#define LOG_FILE "watering.log"
#define ADC_CHANNEL 0
#define ADC_MAX_VALUE 1023.0
#define SAMPLE_INTERVAL 60

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(int state);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC (single-ended, channel 0-7)
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Error: Invalid ADC channel");
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // MCP3008 SPI command: start bit (1), single-ended mode (1), channel select (3 bits)
    tx_buf[0] = 0x01;  // Start bit
    tx_buf[1] = (0x08 | channel) << 4;  // Single-ended mode + channel
    tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        log_event("Error: SPI transfer failed");
        return -1;
    }

    // Extract 10-bit result: bits 1-2 of rx_buf[1] are MSB, rx_buf[2] is LSB
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to calculate moisture percentage from ADC value
float calculate_moisture(int adc_value) {
    if (adc_value < 0) return -1.0;
    return (float)adc_value / ADC_MAX_VALUE * 100.0;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    log_event(state ? "Pump turned ON" : "Pump turned OFF");
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "[%s] %s\n", timestamp, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received termination signal, shutting down...");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);  // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output and ensure it's off
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            log_event("Error reading ADC value");
        } else {
            float moisture = calculate_moisture(adc_value);
            char log_message[128];
            snprintf(log_message, sizeof(log_message), "Moisture level: %.2f%% (ADC: %d)", moisture, adc_value);
            log_event(log_message);

            if (moisture < MOISTURE_THRESHOLD) {
                control_pump(1);
            } else {
                control_pump(0);
            }
        }

        // Sleep for the sample interval, checking for termination
        for (int i = 0; i < SAMPLE_INTERVAL && !terminate; i++) {
            sleep(1);
        }
    }

    // Cleanup
    control_pump(0);  // Ensure pump is off
    spiClose(spi_handle);
    gpioTerminate();
    log_event("Program terminated");

    return 0;
}

