#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define LED_GPIO 17
#define MAX_RECONNECT_DELAY 60

static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;
static int reconnect_delay = 1;

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker\n");
        int rc = mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("Failed to subscribe to topic");
        }
    } else {
        log_error("Connection failed");
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc) {
    (void)m;
    (void)userdata;
    if (rc != 0) {
        log_error("Unexpected disconnect");
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;

    if (message->payloadlen <= 0) {
        log_error("Empty payload received");
        return;
    }

    char *payload = malloc(message->payloadlen + 1);
    if (!payload) {
        log_error("Memory allocation failed for payload");
        return;
    }
    memcpy(payload, message->payload, message->payloadlen);
    payload[message->payloadlen] = '\0';

    cJSON *json = cJSON_Parse(payload);
    free(payload);

    if (!json) {
        log_error("JSON parse error");
        return;
    }

    cJSON *led_state = cJSON_GetObjectItemCaseSensitive(json, "led_state");
    if (!cJSON_IsBool(led_state)) {
        log_error("Invalid or missing led_state field (expected boolean)");
        cJSON_Delete(json);
        return;
    }

    int rc = gpioWrite(LED_GPIO, led_state->valueint ? 1 : 0);
    if (rc != 0) {
        log_error("Failed to write to GPIO");
    }

    cJSON_Delete(json);
}

static int connect_mqtt(void) {
    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to MQTT broker");
        return -1;
    }
    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to start MQTT loop");
        mosquitto_disconnect(mosq);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_loop_stop(mosq, false);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create MQTT client");
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (connect_mqtt() != 0) {
        log_error("Initial MQTT connection failed");
    }

    while (running) {
        sleep(1);
        if (mosq) {
            int rc = mosquitto_loop(mosq, 1000, 1);
            if (rc != MOSQ_ERR_SUCCESS) {
                log_error("MQTT loop error, attempting reconnect");
                mosquitto_loop_stop(mosq, false);
                mosquitto_destroy(mosq);
                mosq = NULL;
                if (reconnect_delay <= MAX_RECONNECT_DELAY) {
                    sleep(reconnect_delay);
                    reconnect_delay *= 2;
                }
                mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
                if (mosq) {
                    mosquitto_connect_callback_set(mosq, on_connect);
                    mosquitto_disconnect_callback_set(mosq, on_disconnect);
                    mosquitto_message_callback_set(mosq, on_message);
                    if (connect_mqtt() != 0) {
                        log_error("Reconnect failed");
                    } else {
                        reconnect_delay = 1;
                    }
                } else {
                    log_error("Failed to recreate MQTT client");
                }
            }
        }
    }

    cleanup();
    return 0;
}

