#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define VREF 3.3f
#define LM35_MV_PER_C 10.0f
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"

static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_temperature(int adc_value) {
    float voltage = (adc_value * VREF) / 1024.0f;
    return voltage * (1000.0f / LM35_MV_PER_C);
}

static void log_temperature(float temperature) {
    printf("Temperature: %.2f °C\n", temperature);
}

static void log_to_file(const float *buffer, int size) {
    FILE *fp = fopen(LOG_FILE, "wb+");
    if (!fp) {
        fprintf(stderr, "Error opening %s for writing\n", LOG_FILE);
        return;
    }
    size_t written = fwrite(buffer, sizeof(float), (size_t)size, fp);
    if (written != (size_t)size) {
        fprintf(stderr, "Error writing %d floats to %s\n", size, LOG_FILE);
    }
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature_buffer[BUFFER_SIZE];
    int buffer_index = 0;

    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping cycle\n");
            sleep(5);
            continue;
        }

        float temperature = adc_to_temperature(adc_value);
        log_temperature(temperature);

        temperature_buffer[buffer_index] = temperature;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        if (buffer_index == 0) {
            log_to_file(temperature_buffer, BUFFER_SIZE);
        }

        sleep(5);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return 0;
}

