#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_BUS "/dev/i2c-1"
#define SPI_BUS "/dev/spidev0.0"
#define BH1750_ADDR 0x23
#define LOG_FILE "environmental_log.txt"
#define SAMPLE_INTERVAL 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int bh1750_read_lux(int fd, float *lux) {
    uint8_t buf[2];
    if (i2c_read_reg8(fd, 0x00, &buf[0]) < 0) return -1;
    if (i2c_read_reg8(fd, 0x00, &buf[1]) < 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2;
    return 0;
}

static int mcp3008_read_channel(int fd, uint8_t channel, uint16_t *value) {
    if (channel > 7) return -1;
    uint8_t tx[3] = {0x01, (uint8_t)(0x80 | (channel << 4)), 0x00};
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) return -1;
    *value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static int log_data(float light, uint16_t sound) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Light: %.2f, Sound: %u\n", ts, light, sound);
    fclose(fp);
    return 0;
}

