#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(int pin, int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%d,%d\n", timestamp, pin, state);
    fclose(fp);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line, "flame-sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        perror("gpiod_line_request_input_flags");
        goto cleanup;
    }

    printf("Flame sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        if (log_event(GPIO_PIN, value) < 0) {
            fprintf(stderr, "Failed to log event\n");
        }

        if (value == 1) {
            printf("ALARM: Flame detected on GPIO %d\n", GPIO_PIN);
        }

        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

