#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ---------------- Constants ---------------- */
#define SPI_CHANNEL    0          /* CE0 */
#define SPI_BAUD       500000     /* 500 kHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define I2C_BUS        1
#define I2C_ADDR       0x62       /* MCP4725 default address */
#define MCP4725_CMD    0x40       /* Write DAC register command */
#define VREF           3.3f
#define ADC_MAX        1023       /* 10-bit ADC */
#define TEMP_MIN_C     0.0f
#define TEMP_MAX_C     50.0f
#define DAC_MAX_V      3.3f
#define SAMPLE_US      500000     /* 0.5 s */
#define LOG_FILE       "temperature_log.txt"

/* ---------------- Globals ---------------- */
static int spi_handle = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ---------------- Prototypes ---------------- */
static int  read_mcp3008(int channel);
static float adc_to_celsius(int adc_value);
static int  set_mcp4725_dac(float voltage);
static int  log_data(int adc_value, float temperature, float dac_voltage);
static void signal_handler(int sig);
static void cleanup(void);

/* ---------------- MCP3008 read ---------------- */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n",
                ret, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ---------------- ADC -> Celsius ---------------- */
static float adc_to_celsius(int adc_value)
{
    if (adc_value < 0) adc_value = 0;
    if (adc_value > ADC_MAX) adc_value = ADC_MAX;

    float voltage = (float)adc_value * VREF / (float)ADC_MAX;
    float temperature = (voltage - 0.5f) * 100.0f;
    return temperature;
}

/* ---------------- MCP4725 DAC write ---------------- */
static int set_mcp4725_dac(float voltage)
{
    if (voltage < 0.0f) voltage = 0.0f;
    if (voltage > DAC_MAX_V) voltage = DAC_MAX_V;

    /*
     * MCP4725 write DAC register (2-byte transfer, no command byte):
     *   byte[0] = (voltage / VREF) * 4095  (12-bit value, lower 12 bits)
     *   byte[1] = 0x00                     (no EEPROM write, gain=1, power=1)
     * pigpio i2cWriteDevice sends the two bytes as-is.
     */
    uint16_t dac_value = (uint16_t)((voltage / DAC_MAX_V) * 4095.0f + 0.5f);
    char buf[2] = { (char)(dac_value >> 4), (char)(dac_value << 4) };

    int ret = i2cWriteDevice(i2c_handle, buf, 2);
    if (ret != 0) {
        fprintf(stderr, "I2C write to MCP4725 failed (returned %d): %s\n",
                ret, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---------------- Logging ---------------- */
static int log_data(int adc_value, float temperature, float dac_voltage)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s, ADC: %d, Temp: %.2f C, DAC: %.3f V\n",
                timestamp, adc_value, temperature, dac_voltage) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

/* ---------------- Signal handler ---------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---------------- Cleanup ---------------- */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ---------------- Main ---------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed (handle %d)\n", i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; retrying in 1 s...\n");
            gpioDelay(1000000);
            continue;
        }

        float temperature = adc_to_celsius(adc_value);
        float dac_voltage = (temperature - TEMP_MIN_C) *
                            (DAC_MAX_V / (TEMP_MAX_C - TEMP_MIN_C));
        if (dac_voltage < 0.0f) dac_voltage = 0.0f;
        if (dac_voltage > DAC_MAX_V) dac_voltage = DAC_MAX_V;

        if (set_mcp4725_dac(dac_voltage) != 0) {
            fprintf(stderr, "DAC write failed; continuing...\n");
        }

        if (log_data(adc_value, temperature, dac_voltage) != 0) {
            fprintf(stderr, "Logging failed; continuing...\n");
        }

        printf("ADC: %4d  Temp: %6.2f C  DAC: %5.3f V\n",
               adc_value, temperature, dac_voltage);

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

