    fflush(log_file);
    return 0;
}

/* ---------------- Signal handler ---------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---------------- Cleanup ---------------- */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ---------------- Main ---------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed (handle %d)\n", i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; retrying in 1 s...\n");
            gpioDelay(1000000);
            continue;
        }

        float temperature = adc_to_celsius(adc_value);
        float dac_voltage = (temperature - TEMP_MIN_C) *
                            (DAC_MAX_V / (TEMP_MAX_C - TEMP_MIN_C));
        if (dac_voltage < 0.0f) dac_voltage = 0.0f;
        if (dac_voltage > DAC_MAX_V) dac_voltage = DAC_MAX_V;

        if (set_mcp4725_dac(dac_voltage) != 0) {
            fprintf(stderr, "DAC write failed; continuing...\n");
        }

        if (log_data(adc_value, temperature, dac_voltage) != 0) {
            fprintf(stderr, "Logging failed; continuing...\n");
        }

        printf("ADC: %4d  Temp: %6.2f C  DAC: %5.3f V\n",
               adc_value, temperature, dac_voltage);

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

