/*
 * Light sequencer using four Songle SRD-05VDC-SL relays on a Raspberry Pi 3 Model B+.
 * Relays are driven via BCM GPIO pins 17, 22, 23, 24 (active-high modules).
 * Uses libgpiod for GPIO control.
 *
 * Build: gcc -O2 -Wall -Wextra -o light_seq light_seq.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define ACTIVE_HIGH 1
#define INACTIVE 0

/* BCM GPIO pin numbers for the four relays */
static const unsigned int relay_pins[NUM_RELAYS] = {17, 22, 23, 24};

/* libgpiod chip and line handles */
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS];
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can clean up and exit.      */
/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Release all GPIO resources: set lines low, release lines, close chip.*/
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], INACTIVE);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Initialize all relay lines as outputs, initially inactive.         */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int init_relays(void)
{
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", relay_pins[i]);
            cleanup();
            return -1;
        }

        if (gpiod_line_request_output(relay_lines[i], "light_seq", INACTIVE) < 0) {
            perror("gpiod_line_request_output");
            cleanup();
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Activate a relay for 1 second, then deactivate it.                 */
/* ------------------------------------------------------------------ */
static void activate_relay(int index)
{
    if (gpiod_line_set_value(relay_lines[index], ACTIVE_HIGH) < 0) {
        perror("gpiod_line_set_value (activate)");
        return;
    }
    sleep(1);
    if (gpiod_line_set_value(relay_lines[index], INACTIVE) < 0) {
        perror("gpiod_line_set_value (deactivate)");
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_relays() < 0) {
        return EXIT_FAILURE;
    }

    printf("Light sequencer started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < NUM_RELAYS && running; i++) {
            activate_relay(i);
            if (running) {
                sleep(1); /* 1-second gap between relays */
            }
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

