#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* GPIO pin assignments for L298N motor driver */
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

/* SPI configuration for MCP3008 ADC */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* mode 0, active-low CE */

/* Rain sensor channel on MCP3008 */
#define RAIN_SENSOR_CHANNEL 0

/* Rain level threshold (0-10) */
#define RAIN_THRESHOLD 5

/* Motor PWM range and duty for close/open */
#define MOTOR_PWM_RANGE 255
#define MOTOR_PWM_DUTY  150

/* Polling interval in microseconds */
#define POLL_INTERVAL_US 1000000

/* Global state */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int  read_rain_sensor(int channel);
static int  convert_to_rain_level(int adc_value);
static void control_motor(int direction, int duration_sec);
static void log_rain_level(int rain_level);
static void cleanup(void);
static void signal_handler(int sig);

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0-1023 on success, -1 on SPI transfer failure.
 */
static int read_rain_sensor(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1 + channel, then don't-care */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + all 8 bits of rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/*
 * Convert ADC value (0-1023) to rain level (0-10).
 * Sensor outputs higher voltage when dry, so 1023 -> 0 (dry), 0 -> 10 (heaviest).
 */
static int convert_to_rain_level(int adc_value) {
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    return 10 - (adc_value * 10 / 1023);
}

/*
 * Drive the motor for the given duration in seconds.
 * direction: 1 = forward (close window), -1 = reverse (open window), 0 = stop.
 */
static void control_motor(int direction, int duration_sec) {
    if (direction == 1) {
        /* Close window: forward */
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
        gpioPWM(MOTOR_ENA, MOTOR_PWM_DUTY);
    } else if (direction == -1) {
        /* Open window: reverse */
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 1);
        gpioPWM(MOTOR_ENA, MOTOR_PWM_DUTY);
    } else {
        /* Stop */
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 0);
        gpioPWM(MOTOR_ENA, 0);
        return;
    }

    /* Sleep in small increments so we can respond to signals */
    for (int i = 0; i < duration_sec && program_running; i++) {
        gpioDelay(1000000); /* 1 second */
    }

    /* Ensure motor is stopped after duration */
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, 0);
}

/*
 * Log a rain level reading with a timestamp.
 */
static void log_rain_level(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
    } else {
        fflush(log_file);
    }
}

/*
 * Release all resources.
 */
static void cleanup(void) {
    /* Stop motor first */
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, 0);

    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
}

/*
 * Signal handler for graceful shutdown.
 */
static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor GPIO pins */
    if (gpioSetMode(MOTOR_IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_ENA, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set motor GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range for ENA */
    gpioSetPWMrange(MOTOR_ENA, MOTOR_PWM_RANGE);

    /* Open SPI for MCP3008 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open rain_log.txt for appending\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Initial state: window open (motor stopped) */
    int window_open = 1;
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, 0);

    /* Main polling loop */
    while (program_running) {
        int adc_value = read_rain_sensor(RAIN_SENSOR_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Warning: failed to read rain sensor, retrying...\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        int rain_level = convert_to_rain_level(adc_value);
        log_rain_level(rain_level);

        if (rain_level >= RAIN_THRESHOLD && window_open) {
            printf("Rain detected (level %d >= %d). Closing window...\n",
                   rain_level, RAIN_THRESHOLD);
            control_motor(1, 3);  /* close for 3 s */
            window_open = 0;
        } else if (rain_level < RAIN_THRESHOLD && !window_open) {
            printf("Rain cleared (level %d < %d). Opening window...\n",
                   rain_level, RAIN_THRESHOLD);
            control_motor(-1, 3); /* open for 3 s */
            window_open = 1;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

