/*
 * Clap Detector for Raspberry Pi 4 Model B
 * Sensor: MAX9814 electret microphone amplifier (AGC)
 * ADC:   pigpio bit-banged ADC on GPIO26 (10-bit, 0-1023)
 * LED:   GPIO16 (active-high)
 *
 * Build: gcc -Wall -Wextra -O2 -o clap_detector clap_detector.c -lpigpio -lrt
 * Run:   sudo ./clap_detector
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define CLAP_GPIO          26
#define LED_GPIO           16

/*
 * Threshold for clap detection.
 * MAX9814 output is ~0.7 x VDD at 0 dB SPL.
 * 3.3 V supply -> 2.31 V threshold.
 * 10-bit ADC -> ~700 out of 1023.
 */
#define CLAP_THRESHOLD     700

#define DEBOUNCE_MS        50
#define LED_ON_MS          500
#define SAMPLE_DELAY_US    1000   /* 1 ms between samples */
#define ADC_READS_PER_SAMPLE 100  /* 100 samples per ADC reading */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*
 * Read the 10-bit ADC value on CLAP_GPIO using bit-banging.
 * Returns 0-1023 on success, -1 on error.
 */
static int read_adc(void)
{
    int value = 0;

    for (int i = 0; i < 10; i++) {
        if (gpioWrite(CLAP_GPIO, 1) < 0)
            return -1;
        gpioDelay(1);                       /* t_sta */

        if (gpioWrite(CLAP_GPIO, 0) < 0)
            return -1;
        gpioDelay(1);                       /* t_conv */

        int bit = gpioRead(CLAP_GPIO);
        if (bit < 0)
            return -1;

        value = (value << 1) | bit;
        gpioDelay(1);                       /* t_smpl */
    }

    return value;
}

/* ------------------------------------------------------------------ */
static void log_clap(int adc_value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Clap detected! ADC value: %d\n", timestamp, adc_value);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO modes --- */
    if (gpioSetMode(CLAP_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", CLAP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off at start */
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize LED state on GPIO%d.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Clap detector running. Press Ctrl+C to exit.\n");
    printf("  Clap GPIO : GPIO%d (10-bit ADC, 0-1023)\n", CLAP_GPIO);
    printf("  LED GPIO  : GPIO%d\n", LED_GPIO);
    printf("  Threshold : %d (%.2f V at 3.3 V supply)\n",
           CLAP_THRESHOLD,
           (CLAP_THRESHOLD / 1023.0) * 3.3);
    fflush(stdout);

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = 0;
        int valid_reads = 0;

        /*
         * Take multiple samples to reduce noise and improve reliability.
         * A single glitch can read a spurious value.
         */
        for (int i = 0; i < ADC_READS_PER_SAMPLE && g_running; i++) {
            int v = read_adc();
            if (v < 0) {
                fprintf(stderr, "Error: ADC read failed on GPIO%d.\n", CLAP_GPIO);
                gpioDelay(100000);  /* 100 ms backoff before retry */
                break;
            }
            adc_value += v;
            valid_reads++;
            gpioDelay(SAMPLE_DELAY_US);
        }

        if (valid_reads == 0) {
            /* No valid reads this cycle; skip to next iteration */
            continue;
        }

        adc_value /= valid_reads;

        /* --- Clap detection --- */
        if (adc_value > CLAP_THRESHOLD) {
            log_clap(adc_value);

            /* Turn LED on */
            if (gpioWrite(LED_GPIO, 1) != 0) {
                fprintf(stderr, "Warning: failed to turn on LED on GPIO%d.\n", LED_GPIO);
            }

            /* Keep LED on for LED_ON_MS, checking for shutdown */
            uint32_t elapsed = 0;
            while (g_running && elapsed < LED_ON_MS) {
                gpioDelay(10000);  /* 10 ms slices */
                elapsed += 10;
            }

            /* Turn LED off */
            if (gpioWrite(LED_GPIO, 0) != 0) {
                fprintf(stderr, "Warning: failed to turn off LED on GPIO%d.\n", LED_GPIO);
            }

            /* Debounce: ignore triggers for DEBOUNCE_MS */
            uint32_t debounce_elapsed = 0;
            while (g_running && debounce_elapsed < DEBOUNCE_MS) {
                gpioDelay(10000);
                debounce_elapsed += 10;
            }
        }
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

