#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio"
#define LOG_FILE "distance_log.txt"
#define PROXIMITY_THRESHOLD 200.0f
#define A 26.0f
#define B -6.0f

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int gpio_export(int pin) {
    char path[64];
    int fd;
    snprintf(path, sizeof(path), "%s/gpio%d", GPIO_PATH, pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        if (errno != EBUSY) {
            fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
            return -1;
        }
        return 0;
    }
    if (write(fd, "1", 1) < 0) {
        fprintf(stderr, "Error exporting GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(int pin) {
    char path[64];
    int fd;
    snprintf(path, sizeof(path), "%s/gpio%d", GPIO_PATH, pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        if (errno != ENOENT) {
            fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
            return -1;
        }
        return 0;
    }
    if (write(fd, "0", 1) < 0) {
        fprintf(stderr, "Error unexporting GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(int pin, const char *dir) {
    char path[64];
    int fd;
    snprintf(path, sizeof(path), "%s/gpio%d/direction", GPIO_PATH, pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, dir, strlen(dir)) < 0) {
        fprintf(stderr, "Error setting direction on GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_read_value(int pin) {
    char path[64];
    int fd;
    char val;
    snprintf(path, sizeof(path), "%s/gpio%d/value", GPIO_PATH, pin);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (read(fd, &val, 1) < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return (val == '1') ? 1 : 0;
}

static float voltage_to_distance(float voltage) {
    return A / voltage + B;
}

static void log_distance(float distance) {
    FILE *fp;
    time_t t;
    struct tm *tm_info;
    char timestamp[64];

    t = time(NULL);
    tm_info = localtime(&t);
    if (tm_info == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    fprintf(fp, "%s, Distance: %.2f mm\n", timestamp, distance);
    fclose(fp);
}

int main(void) {
    int ret;

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT)");
        return 1;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM)");
        return 1;
    }

    if (gpio_export(GPIO_PIN) < 0) {
        return 1;
    }
    if (gpio_set_direction(GPIO_PIN, "in") < 0) {
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    printf("Pet feeder control started. Press Ctrl+C to exit.\n");

    while (running) {
        int val = gpio_read_value(GPIO_PIN);
        if (val < 0) {
            sleep(1);
            continue;
        }

        float voltage = (val == 1) ? 3.3f : 0.0f;
        float distance = voltage_to_distance(voltage);

        log_distance(distance);

        if (distance < PROXIMITY_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1);
    }

    gpio_unexport(GPIO_PIN);
    printf("Pet feeder control stopped.\n");
    return 0;
}

