#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* Configuration */
#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO 8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */
#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0 */
#define LED_GPIO         21
#define FIELD_THRESHOLD  10.0       /* mT */
#define VCC              3.3        /* Sensor supply voltage */
#define SENSITIVITY_MV_PER_MT 1.65 /* DRV5055VA ratiometric: 2.5 mV/mT at 3.3 V */
#define LOG_FILE         "magnetic_log.txt"
#define SAMPLE_DELAY_US  100000     /* 100 ms */

/* Globals for cleanup */
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read 10-bit value from MCP3008 single-ended channel (0-7) */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 SPI protocol: 3 bytes
     * Byte 0: 0x01 (start bit)
     * Byte 1: (0x08 | channel) << 4  -> single-ended + channel select
     * Byte 2: 0x00 (don't care, clocked out for low byte)
     * Result: bits 9-2 in rx[1] (lower 2 bits), bits 1-0 in rx[2] (upper 2 bits)
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;  /* 0-1023 */
}

/* Convert ADC count to voltage */
static float adc_to_voltage(int adc_value) {
    return (float)adc_value * VCC / 1023.0f;
}

/* Convert voltage to magnetic field strength in mT */
static float voltage_to_field_mt(float voltage) {
    /* DRV5055VA ratiometric: output = VCC/2 at zero field,
     * sensitivity = 2.5 mV/mT at 3.3 V -> 1.65 mV/mT
     */
    float field_mv = (voltage - (VCC / 2.0f)) * 1000.0f;
    return field_mv / SENSITIVITY_MV_PER_MT;
}

/* Log timestamped field strength to file */
static int log_field_strength(float field_mt) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s, Field: %.2f mT\n", timestamp, field_mt);
    fclose(fp);
    return 0;
}

/* Control LED based on field strength threshold */
static void control_led(float field_mt) {
    gpioWrite(LED_GPIO, (field_mt > FIELD_THRESHOLD) ? 1 : 0);
}

