/*
 * Raspberry Pi Zero W – MLX91211 current sensor reader via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> Pi 5V (pin 2 or 4)
 *   MCP3008 VREF -> Pi 5V
 *   MCP3008 AGND -> Pi GND
 *   MCP3008 DGND -> Pi GND
 *   MCP3008 CLK  -> Pi GPIO11 (SCLK)
 *   MCP3008 DOUT -> Pi GPIO9  (MISO)
 *   MCP3008 DIN  -> Pi GPIO10 (MOSI)
 *   MCP3008 CS   -> Pi GPIO8  (CE0)
 *   MCP3008 CH0  -> MLX91211 analog output
 *   MLX91211 VDD -> Pi 5V
 *   MLX91211 GND -> Pi GND
 *
 * MLX91211 ratiometric transfer:
 *   0V  -> 0A
 *   2.5V -> 25A
 *   5.0V -> 50A
 *
 * Build:  gcc -Wall -Wextra -O2 -o current_monitor current_monitor.c -lpigpio -lrt
 * Run:    sudo ./current_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz – well within MCP3008 3.3V/5V limit */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC */
#define VREF           5.0        /* MCP3008 VREF tied to Pi 5V */
#define LOG_FILE       "current_log.txt"
#define SAMPLE_US      100000     /* 100 ms between samples */

/* MLX91211 ratiometric transfer function */
#define V_SUPPLY       5.0        /* MLX91211 VDD = 5V */
#define V_ZERO_CURRENT 2.5        /* 2.5V at 0A */
#define V_FULL_SCALE   5.0        /* 5.0V at 50A */
#define FULL_SCALE_A   50.0       /* 50A at 5.0V */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ MCP3008 read ----------------------------- */
/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0 on success (code stored in *out_code), -1 on SPI error.
 */
static int mcp3008_read(int channel, int *out_code)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    if (out_code == NULL) {
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   tx[0] = 0x01                       – start bit
     *   tx[1] = 0x80 | (channel << 4)      – single-ended + channel select
     *   tx[2] = 0x00                       – don't-care (clocks out low 2 bits)
     * Result: ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[3] = { 0x01, (char)(0x80 | (channel << 4)), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    *out_code = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return 0;
}

/* ------------------------------ Current calc ----------------------------- */
static double calculate_current(int adc_code)
{
    double voltage = (double)adc_code / (double)ADC_MAX_VALUE * VREF;

    if (voltage < 0.0 || voltage > V_SUPPLY) {
        fprintf(stderr,
                "Warning: voltage %.3f V out of range [0, %.1f V] – skipping sample\n",
                voltage, V_SUPPLY);
        return 0.0;
    }

    /* Ratiometric: 2.5V -> 0A, 5.0V -> 50A */
    return (voltage - V_ZERO_CURRENT) * (FULL_SCALE_A / (V_FULL_SCALE - V_ZERO_CURRENT));
}

/* ------------------------------- Logging --------------------------------- */
static int log_current(double current)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        fclose(g_log_file);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX91211 current monitor started. Press Ctrl+C to stop.\n");
    printf("Logging to %s every 100 ms.\n", LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_code = 0;

        if (mcp3008_read(ADC_CHANNEL, &adc_code) != 0) {
            fprintf(stderr, "ADC read error – skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        double current = calculate_current(adc_code);

        if (log_current(current) != 0) {
            fprintf(stderr, "Logging failed – continuing\n");
        }

        gpioDelay(SAMPLE_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    gpioTerminate();

    printf("Done.\n");
    return EXIT_SUCCESS;
}

