#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/wait.h>
#include <sys/stat.h>
#include <errno.h>
#include <pigpio.h>

#define PIR_GPIO          17
#define DEBOUNCE_MS       200
#define POLL_INTERVAL_US  50000
#define IMAGE_WIDTH       1280
#define IMAGE_HEIGHT      720
#define IMAGE_QUALITY     85
#define IMAGE_DIR         "/home/pi/security_cam/"
#define MAX_PATH_LEN      512

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int ensure_directory(const char *path)
{
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        syslog(LOG_ERR, "Target '%s' exists but is not a directory", path);
        return -1;
    }
    if (errno != ENOENT) {
        syslog(LOG_ERR, "stat('%s'): %s", path, strerror(errno));
        return -1;
    }
    if (mkdir(path, 0755) != 0 && errno != EEXIST) {
        syslog(LOG_ERR, "mkdir('%s'): %s", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename)
{
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork() failed: %s", strerror(errno));
        return -1;
    }
    if (pid == 0) {
        char width_str[16], height_str[16], quality_str[16];
        snprintf(width_str,  sizeof(width_str),  "%d", IMAGE_WIDTH);
        snprintf(height_str, sizeof(height_str), "%d", IMAGE_HEIGHT);
        snprintf(quality_str, sizeof(quality_str), "%d", IMAGE_QUALITY);

        char *argv[] = {
            "libcamera-still",
            "--width", width_str,
            "--height", height_str,
            "--quality", quality_str,
            "--nopreview",
            "-o", (char *)filename,
            NULL
        };
        execvp("libcamera-still", argv);
        _exit(127);
    }

    int status = 0;
    if (waitpid(pid, &status, 0) < 0) {
        syslog(LOG_ERR, "waitpid() failed: %s", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) == 0)
        return 0;

    syslog(LOG_ERR, "libcamera-still exited with status %d",
           WIFEXITED(status) ? WEXITSTATUS(status) : -1);
    return -1;
}

int main(void)
{
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction() failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_INPUT) failed", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (ensure_directory(IMAGE_DIR) != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Security camera started (PIR on BCM GPIO%d)", PIR_GPIO);

    int last_state = gpioRead(PIR_GPIO);
    if (last_state < 0) {
        syslog(LOG_ERR, "gpioRead(%d) initial failed", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int current_state = gpioRead(PIR_GPIO);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpioRead(%d) failed", PIR_GPIO);
            break;
        }

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_MS * 1000);
            int confirmed = gpioRead(PIR_GPIO);
            if (confirmed < 0) {
                syslog(LOG_ERR, "gpioRead(%d) confirm failed", PIR_GPIO);
                break;
            }
            if (confirmed == current_state) {
                if (current_state == 1) {
                    syslog(LOG_INFO, "Motion detected on GPIO%d", PIR_GPIO);

                    time_t rawtime;
                    struct tm timeinfo;
                    char filename[MAX_PATH_LEN];

                    time(&rawtime);
                    localtime_r(&rawtime, &timeinfo);
                    strftime(filename, sizeof(filename),
                             IMAGE_DIR "%Y-%m-%d_%H-%M-%S.jpg", &timeinfo);

                    if (capture_image(filename) == 0)
                        syslog(LOG_INFO, "Image captured: %s", filename);
                    else
                        syslog(LOG_ERR, "Failed to capture image");
                }
                last_state = confirmed;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Security camera stopped");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

