/*
 * CSI camera -> UDP stream for Raspberry Pi (BCM2711 / Pi 4)
 *
 * Captures video from /dev/video0 via V4L2 MMAP streaming, then sends
 * each frame as a series of UDP datagrams to <server_ip>:<server_port>.
 *
 * Each datagram carries a 16-byte header (frame_idx, frag_idx, frag_count,
 * payload_size) followed by the raw frame data.  The receiver can
 * reassemble frames by collecting all fragments for a given frame_idx.
 *
 * Build:  gcc -O2 -Wall -o csi_udp csi_udp.c
 * Run:    ./csi_udp <server_ip> <server_port>
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/videodev2.h>

#define DEVICE_NAME      "/dev/video0"
#define FRAME_WIDTH      640
#define FRAME_HEIGHT     480
#define FRAME_BYTES      (FRAME_WIDTH * FRAME_HEIGHT * 2)   /* YUYV */
#define FRAGMENT_SIZE    65000
#define NUM_BUFFERS      4
#define MAX_FRAGMENTS    (FRAME_BYTES + FRAGMENT_SIZE - 1) / FRAGMENT_SIZE

/* ---- V4L2 helpers ---- */

static int xioctl(int fd, unsigned long request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd_out)
{
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("open(" DEVICE_NAME ")");
        return -1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        goto fail;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto fail;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        goto fail;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width       = FRAME_WIDTH;
    fmt.fmt.pix.height      = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field       = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        goto fail;
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Driver did not accept YUYV format\n");
        goto fail;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count  = NUM_BUFFERS;
    req.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        goto fail;
    }
    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto fail;
    }

    for (unsigned int i = 0; i < req.count; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index  = i;
        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            goto fail;
        }
        buf.m.userptr = (unsigned long)mmap(NULL, buf.length,
                                            PROT_READ | PROT_WRITE,
                                            MAP_SHARED, fd, buf.m.offset);
        if (buf.m.userptr == (unsigned long)-1) {
            perror("mmap");
            goto fail;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        goto fail;
    }

    *fd_out = fd;
    return 0;

fail:
    close(fd);
    return -1;
}

static void uninit_camera(int fd)
{
    if (fd < 0) return;
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    xioctl(fd, VIDIOC_STREAMOFF, &type);
    /* munmap is done in the loop below */
    close(fd);
}

static int capture_frame(int fd, unsigned char **out, size_t *out_len)
{
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    *out_len = buf.bytesused;
    *out     = (unsigned char *)buf.m.userptr;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        return -1;
    }
    return 0;
}

/* ---- UDP helpers ---- */

static int send_fragment(int sockfd, const struct sockaddr_in *dest,
                         unsigned int frame_idx, unsigned int frag_idx,
                         unsigned int frag_count,
                         const unsigned char *data, size_t len)
{
    struct {
        unsigned int frame_idx;
        unsigned int frag_idx;
        unsigned int frag_count;
        unsigned int payload_size;
    } __attribute__((packed)) header = {
        frame_idx, frag_idx, frag_count, (unsigned int)len
    };

    size_t total = sizeof(header) + len;
    unsigned char *packet = malloc(total);
    if (!packet) {
        perror("malloc");
        return -1;
    }
    memcpy(packet, &header, sizeof(header));
    memcpy(packet + sizeof(header), data, len);

    ssize_t sent = sendto(sockfd, packet, total, 0,
                          (const struct sockaddr *)dest,
                          sizeof(*dest));
    free(packet);

    if (sent < 0) {
        perror("sendto");
        return -1;
    }
    if ((size_t)sent != total) {
        fprintf(stderr, "Partial send: %zd of %zu bytes\n", sent, total);
        return -1;
    }
    return 0;
}

static int send_frame(int sockfd, const struct sockaddr_in *dest,
                      unsigned int frame_idx,
                      const unsigned char *data, size_t len)
{
    unsigned int frag_count = (len + FRAGMENT_SIZE - 1) / FRAGMENT_SIZE;
    if (frag_count > MAX_FRAGMENTS) {
        fprintf(stderr, "Frame too large (%zu bytes) for %u fragments\n",
                len, frag_count);
        return -1;
    }

    for (unsigned int i = 0; i < frag_count; ++i) {
        size_t off = i * FRAGMENT_SIZE;
        size_t frag_len = (len - off < FRAGMENT_SIZE) ? (len - off) : FRAGMENT_SIZE;
        if (send_fragment(sockfd, dest, frame_idx, i, frag_count,
                          data + off, frag_len) < 0)
            return -1;
    }
    return 0;
}

/* ---- Signal handling ---- */

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig)
{
    (void)sig;
    g_stop = 1;
}

/* ---- Main ---- */

int main(int argc, char *argv[])
{
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);
    if (server_port <= 0 || server_port > 65535) {
        fprintf(stderr, "Invalid port: %s\n", argv[2]);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = -1;
    if (init_camera(&fd) < 0)
        return EXIT_FAILURE;

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        uninit_camera(fd);
        return EXIT_FAILURE;
    }

    struct sockaddr_in dest;
    memset(&dest, 0, sizeof(dest));
    dest.sin_family = AF_INET;
    dest.sin_port   = htons((unsigned short)server_port);
    if (inet_pton(AF_INET, server_ip, &dest.sin_addr) <= 0) {
        fprintf(stderr, "Invalid IP address: %s\n", server_ip);
        close(sockfd);
        uninit_camera(fd);
        return EXIT_FAILURE;
    }

    unsigned int frame_idx = 0;
    int rc = EXIT_SUCCESS;

    while (!g_stop) {
        unsigned char *frame = NULL;
        size_t frame_len = 0;

        if (capture_frame(fd, &frame, &frame_len) < 0) {
            fprintf(stderr, "Capture failed; aborting\n");
            rc = EXIT_FAILURE;
            break;
        }

        if (send_frame(sockfd, &dest, frame_idx, frame, frame_len) < 0) {
            fprintf(stderr, "Send failed; aborting\n");
            rc = EXIT_FAILURE;
            break;
        }

        frame_idx++;
    }

    /* Clean shutdown */
    uninit_camera(fd);
    close(sockfd);

    if (g_stop)
        printf("\nShutdown complete.\n");
    return rc;
}

