#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define PAN_SERVO_PIN  4
#define TILT_SERVO_PIN 5
#define BUTTON_UP_PIN  6
#define BUTTON_DOWN_PIN 7
#define BUTTON_LEFT_PIN 8
#define BUTTON_RIGHT_PIN 9

#define SERVO_MIN_PULSE_US 1000
#define SERVO_MAX_PULSE_US 2000
#define SERVO_MID_PULSE_US 1500
#define SERVO_MIN_DUTY 50
#define SERVO_MAX_DUTY 100
#define SERVO_MID_DUTY 75
#define SERVO_STEP 5
#define SERVO_RANGE 100
#define SERVO_PERIOD_US 20000
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulse(struct gpiod_line *line, int duty) {
    if (duty < SERVO_MIN_DUTY || duty > SERVO_MAX_DUTY) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty);
        return -1;
    }
    int pulse_us = SERVO_MIN_PULSE_US +
                   (int)((long)(duty - SERVO_MIN_DUTY) *
                         (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US) /
                         SERVO_RANGE);
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Failed to set line high");
        return -1;
    }
    usleep(pulse_us);
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to set line low");
        return -1;
    }
    usleep(SERVO_PERIOD_US - pulse_us);
    return 0;
}

static int move_servo(struct gpiod_line *line, int *position, int step) {
    *position += step;
    if (*position < 25) *position = 25;
    if (*position > 125) *position = 125;
    return set_servo_pulse(line, *position);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    struct gpiod_line *pan_line = gpiod_chip_get_line(chip, PAN_SERVO_PIN);
    struct gpiod_line *tilt_line = gpiod_chip_get_line(chip, TILT_SERVO_PIN);
    struct gpiod_line *up_line = gpiod_chip_get_line(chip, BUTTON_UP_PIN);
    struct gpiod_line *down_line = gpiod_chip_get_line(chip, BUTTON_DOWN_PIN);
    struct gpiod_line *left_line = gpiod_chip_get_line(chip, BUTTON_LEFT_PIN);
    struct gpiod_line *right_line = gpiod_chip_get_line(chip, BUTTON_RIGHT_PIN);

    if (!pan_line || !tilt_line || !up_line || !down_line || !left_line || !right_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(pan_line, "pan_servo", 0) < 0) {
        perror("Failed to request pan servo line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(tilt_line, "tilt_servo", 0) < 0) {
        perror("Failed to request tilt servo line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input_flags(up_line, "button_up",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to request up button line as input with pull-up");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input_flags(down_line, "button_down",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to request down button line as input with pull-up");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input_flags(left_line, "button_left",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to request left button line as input with pull-up");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input_flags(right_line, "button_right",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to request right button line as input with pull-up");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int pan_position = SERVO_MID_DUTY;
    int tilt_position = SERVO_MID_DUTY;

    if (set_servo_pulse(pan_line, pan_position) < 0 ||
        set_servo_pulse(tilt_line, tilt_position) < 0) {
        fprintf(stderr, "Failed to initialize servos\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        int up_val = gpiod_line_get_value(up_line);
        int down_val = gpiod_line_get_value(down_line);
        int left_val = gpiod_line_get_value(left_line);
        int right_val = gpiod_line_get_value(right_line);

        if (up_val < 0 || down_val < 0 || left_val < 0 || right_val < 0) {
            fprintf(stderr, "Failed to read button values\n");
            break;
        }

        if (up_val == 0) {
            if (move_servo(tilt_line, &tilt_position, -SERVO_STEP) < 0) break;
        }
        if (down_val == 0) {
            if (move_servo(tilt_line, &tilt_position, SERVO_STEP) < 0) break;
        }
        if (left_val == 0) {
            if (move_servo(pan_line, &pan_position, -SERVO_STEP) < 0) break;
        }
        if (right_val == 0) {
            if (move_servo(pan_line, &pan_position, SERVO_STEP) < 0) break;
        }

        usleep(POLL_INTERVAL_US);
    }

    gpiod_line_release(pan_line);
    gpiod_line_release(tilt_line);
    gpiod_line_release(up_line);
    gpiod_line_release(down_line);
    gpiod_line_release(left_line);
    gpiod_line_release(right_line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

