    if (gpiod_line_request_output(tilt_line, "tilt_servo", 0) < 0) {
        perror("Failed to request tilt servo line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input_flags(up_line, "button_up",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to request up button line as input with pull-up");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input_flags(down_line, "button_down",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to request down button line as input with pull-up");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input_flags(left_line, "button_left",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to request left button line as input with pull-up");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input_flags(right_line, "button_right",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to request right button line as input with pull-up");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int pan_position = SERVO_MID_DUTY;
    int tilt_position = SERVO_MID_DUTY;

    if (set_servo_pulse(pan_line, pan_position) < 0 ||
        set_servo_pulse(tilt_line, tilt_position) < 0) {
        fprintf(stderr, "Failed to initialize servos\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        int up_val = gpiod_line_get_value(up_line);
        int down_val = gpiod_line_get_value(down_line);
        int left_val = gpiod_line_get_value(left_line);
        int right_val = gpiod_line_get_value(right_line);

        if (up_val < 0 || down_val < 0 || left_val < 0 || right_val < 0) {
            fprintf(stderr, "Failed to read button values\n");
            break;
        }

        if (up_val == 0) {
            if (move_servo(tilt_line, &tilt_position, -SERVO_STEP) < 0) break;
        }
        if (down_val == 0) {
            if (move_servo(tilt_line, &tilt_position, SERVO_STEP) < 0) break;
        }
        if (left_val == 0) {
            if (move_servo(pan_line, &pan_position, -SERVO_STEP) < 0) break;
        }
        if (right_val == 0) {
            if (move_servo(pan_line, &pan_position, SERVO_STEP) < 0) break;
        }

        usleep(POLL_INTERVAL_US);
    }

    gpiod_line_release(pan_line);
    gpiod_line_release(tilt_line);
    gpiod_line_release(up_line);
    gpiod_line_release(down_line);
    gpiod_line_release(left_line);
    gpiod_line_release(right_line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

