#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>
#include <signal.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define NUM_BUFFERS 4
#define BLUR_RADIUS 2
#define JPEG_QUALITY 75
#define SELECT_TIMEOUT_SEC 2

static volatile sig_atomic_t stop_flag = 0;

static void sigint_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

struct buffer {
    void   *start;
    size_t  length;
};

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd, struct buffer *buffers) {
    *fd = open(DEVICE_NAME, O_RDWR);
    if (*fd < 0) {
        perror("open");
        return -1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(*fd);
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(*fd);
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(*fd);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(*fd);
        return -1;
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Camera does not support YUYV format\n");
        close(*fd);
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        close(*fd);
        return -1;
    }
    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(*fd);
        return -1;
    }

    for (unsigned int i = 0; i < req.count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            close(*fd);
            return -1;
        }
        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset);
        if (buffers[i].start == MAP_FAILED) {
            perror("mmap");
            close(*fd);
            return -1;
        }
    }
    return 0;
}

static int start_capturing(int fd, struct buffer *buffers) {
    for (unsigned int i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            return -1;
        }
    }
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        return -1;
    }
    return 0;
}

static int capture_frame(int fd, struct buffer *buffers, unsigned char **out_yuv, size_t *out_len) {
    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = SELECT_TIMEOUT_SEC;
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return -1;
        perror("select");
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    *out_len = buf.bytesused;
    *out_yuv = malloc(*out_len);
    if (!*out_yuv) {
        perror("malloc");
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }
    memcpy(*out_yuv, buffers[buf.index].start, buf.bytesused);

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        free(*out_yuv);
        *out_yuv = NULL;
        return -1;
    }
    return 0;
}

static void stop_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    xioctl(fd, VIDIOC_STREAMOFF, &type);
}

static void uninit_camera(int fd, struct buffer *buffers) {
    for (unsigned int i = 0; i < NUM_BUFFERS; i++) {
        if (buffers[i].start && buffers[i].start != MAP_FAILED) {
            munmap(buffers[i].start, buffers[i].length);
        }
    }
    if (fd >= 0) close(fd);
}

static void yuyv_to_rgb24(const unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x += 2) {
            int idx = (y * width + x) * 2;
            int r = yuyv[idx];
            int g = (yuyv[idx] + yuyv[idx + 2]) / 2;
            int b = yuyv[idx + 2];
            int rgb_idx = (y * width + x) * 3;
            rgb[rgb_idx]     = r;
            rgb[rgb_idx + 1] = g;
            rgb[rgb_idx + 2] = b;
        }
    }
}

static void box_blur(const unsigned char *src, unsigned char *dst, int width, int height, int radius) {
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int r_sum = 0, g_sum = 0, b_sum = 0;
            int count = 0;
            for (int dy = -radius; dy <= radius; dy++) {
                for (int dx = -radius; dx <= radius; dx++) {
                    int nx = x + dx;
                    int ny = y + dy;
                    if (nx < 0) nx = 0;
                    if (nx >= width) nx = width - 1;
                    if (ny < 0) ny = 0;
                    if (ny >= height) ny = height - 1;
                    int src_idx = (ny * width + nx) * 3;
                    r_sum += src[src_idx];
                    g_sum += src[src_idx + 1];
                    b_sum += src[src_idx + 2];
                    count++;
                }
            }
            int dst_idx = (y * width + x) * 3;
            dst[dst_idx]     = r_sum / count;
            dst[dst_idx + 1] = g_sum / count;
            dst[dst_idx + 2] = b_sum / count;
        }
    }
}

static int write_jpeg(const unsigned char *rgb, int width, int height, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    FILE *outfile = fopen(filename, "wb");
    if (!outfile) {
        perror("fopen");
        jpeg_destroy_compress(&cinfo);
        return -1;
    }
    jpeg_stdio_dest(&cinfo, outfile);
    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;
    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);
    jpeg_start_compress(&cinfo, TRUE);
    while (cinfo.next_scanline < cinfo.image_height) {
        JSAMPROW row = (JSAMPROW)(rgb + cinfo.next_scanline * width * 3);
        jpeg_write_scanlines(&cinfo, &row, 1);
    }
    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = -1;
    struct buffer buffers[NUM_BUFFERS];
    memset(buffers, 0, sizeof(buffers));

    if (init_camera(&fd, buffers) < 0) {
        fprintf(stderr, "Camera init failed\n");
        return 1;
    }
    if (start_capturing(fd, buffers) < 0) {
        fprintf(stderr, "Failed to start capturing\n");
        uninit_camera(fd, buffers);
        return 1;
    }

    unsigned char *yuyv = NULL;
    size_t yuyv_len = 0;
    if (capture_frame(fd, buffers, &yuyv, &yuyv_len) < 0) {
        if (stop_flag) fprintf(stderr, "Interrupted by signal\n");
        else fprintf(stderr, "Frame capture failed\n");
        stop_capturing(fd);
        uninit_camera(fd, buffers);
        return 1;
    }

    stop_capturing(fd);
    uninit_camera(fd, buffers);

    int rgb_size = WIDTH * HEIGHT * 3;
    unsigned char *rgb = malloc(rgb_size);
    if (!rgb) {
        perror("malloc rgb");
        free(yuyv);
        return 1;
    }
    yuyv_to_rgb24(yuyv, rgb, WIDTH, HEIGHT);
    free(yuyv);

    unsigned char *blurred = malloc(rgb_size);
    if (!blurred) {
        perror("malloc blurred");
        free(rgb);
        return 1;
    }
    box_blur(rgb, blurred, WIDTH, HEIGHT, BLUR_RADIUS);
    free(rgb);

    time_t rawtime;
    struct tm *timeinfo;
    char filename[64];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

    if (write_jpeg(blurred, WIDTH, HEIGHT, filename) < 0) {
        fprintf(stderr, "Failed to write JPEG\n");
        free(blurred);
        return 1;
    }
    free(blurred);
    printf("Saved %s\n", filename);
    return 0;
}

