#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"

static void print_frmsize(const struct v4l2_frmsizeenum *f)
{
    printf("    %ux%u", f->width, f->height);
    if (f->stepwise)
        printf(" (stepwise)");
    printf("\n");
}

static void print_frmival(const struct v4l2_frmivalenum *f)
{
    printf("        %u/%u fps\n", f->discrete.width, f->discrete.height);
}

static int has_autofocus(int fd)
{
    struct v4l2_queryctrl qc;
    memset(&qc, 0, sizeof(qc));
    qc.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &qc) < 0) {
        if (errno == EINVAL)
            return 0;
        fprintf(stderr, "VIDIOC_QUERYCTRL (focus) failed: %s\n", strerror(errno));
        return -1;
    }
    return (qc.flags & V4L2_CTRL_FLAG_DISABLED) ? 0 : 1;
}

int main(void)
{
    int fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", VIDEO_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Camera: %s\n", cap.card);
    printf("Driver: %s\n", cap.driver);
    printf("Bus info: %s\n", cap.bus_info);

    int autofocus = has_autofocus(fd);
    if (autofocus < 0) {
        close(fd);
        return EXIT_FAILURE;
    }
    printf("Autofocus: %s\n", autofocus ? "supported" : "not supported");

    printf("Supported resolutions:\n");

    for (unsigned int idx = 0; ; idx++) {
        struct v4l2_frmsizeenum fsz;
        memset(&fsz, 0, sizeof(fsz));
        fsz.index = idx;

        if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fsz) < 0) {
            if (errno == EINVAL)
                break;
            fprintf(stderr, "VIDIOC_ENUM_FRAMESIZES failed: %s\n", strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        if (fsz.type == V4L2_FRMSIZE_TYPE_DISCRETE ||
            fsz.type == V4L2_FRMSIZE_TYPE_STEPWISE) {
            printf("  %s:\n", fsz.type == V4L2_FRMSIZE_TYPE_DISCRETE ? "discrete" : "stepwise");
            print_frmsize(&fsz);

            for (unsigned int i = 0; ; i++) {
                struct v4l2_frmivalenum fiv;
                memset(&fiv, 0, sizeof(fiv));
                fiv.index = i;
                fiv.pixel_format = fsz.pixel_format;
                fiv.width = fsz.min_width;
                fiv.height = fsz.min_height;

                if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &fiv) < 0) {
                    if (errno == EINVAL)
                        break;
                    fprintf(stderr, "VIDIOC_ENUM_FRAMEINTERVALS failed: %s\n", strerror(errno));
                    close(fd);
                    return EXIT_FAILURE;
                }
                print_frmival(&fiv);
            }
        }
    }

    close(fd);
    return EXIT_SUCCESS;
}

