#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define PAN_SERVO_PIN    4
#define TILT_SERVO_PIN   5
#define BUTTON_UP_PIN    6
#define BUTTON_DOWN_PIN  7
#define BUTTON_LEFT_PIN  8
#define BUTTON_RIGHT_PIN 9

/* ---- Servo parameters ---- */
#define SERVO_MIN_PULSE  1000   /* microseconds (left)  */
#define SERVO_MAX_PULSE  2000   /* microseconds (right) */
#define SERVO_CENTER     1500   /* microseconds (center)*/
#define SERVO_STEP       10     /* microseconds per step*/
#define LOOP_DELAY_US    50000  /* 50 ms                */

/* ---- Button state ---- */
typedef struct {
    int up;
    int down;
    int left;
    int right;
} ButtonState;

/* ---- Global flag for signal handling ---- */
static volatile sig_atomic_t g_running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Read a button: returns 1 if pressed (active-low) ---- */
static int read_button(int pin)
{
    return (gpioRead(pin) == 0) ? 1 : 0;
}

/* ---- Set servo pulse width, clamped to valid range ---- */
static void set_servo(int pin, int pulse)
{
    if (pulse < SERVO_MIN_PULSE) pulse = SERVO_MIN_PULSE;
    if (pulse > SERVO_MAX_PULSE) pulse = SERVO_MAX_PULSE;
    gpioServo(pin, pulse);
}

/* ---- Update a servo based on button state ---- */
static void update_servo(int pin, int *position, int button_pin,
                         const char *name)
{
    if (read_button(button_pin)) {
        *position += SERVO_STEP;
        set_servo(pin, *position);
        printf("%s moved to %d us\n", name, *position);
    }
}

/* ---- Cleanup: stop PWM and terminate pigpio ---- */
static void cleanup(void)
{
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure button pins as inputs with pull-ups ---- */
    int button_pins[] = {BUTTON_UP_PIN, BUTTON_DOWN_PIN,
                         BUTTON_LEFT_PIN, BUTTON_RIGHT_PIN};
    for (size_t i = 0; i < sizeof(button_pins) / sizeof(button_pins[0]); i++) {
        gpioSetMode(button_pins[i], PI_INPUT);
        gpioSetPullUpDown(button_pins[i], PI_PUD_UP);
    }

    /* ---- Configure servo pins as outputs ---- */
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    /* ---- Initialize servos to center position ---- */
    int pan_position  = SERVO_CENTER;
    int tilt_position = SERVO_CENTER;
    set_servo(PAN_SERVO_PIN, pan_position);
    set_servo(TILT_SERVO_PIN, tilt_position);

    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Pan-tilt control started.\n");
    printf("Pan servo : GPIO%d (center %d us)\n", PAN_SERVO_PIN, pan_position);
    printf("Tilt servo: GPIO%d (center %d us)\n", TILT_SERVO_PIN, tilt_position);
    printf("Buttons  : UP=%d, DOWN=%d, LEFT=%d, RIGHT=%d (active-low)\n",
           BUTTON_UP_PIN, BUTTON_DOWN_PIN, BUTTON_LEFT_PIN, BUTTON_RIGHT_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main control loop ---- */
    while (g_running) {
        update_servo(PAN_SERVO_PIN,  &pan_position,  BUTTON_LEFT_PIN,  "Pan");
        update_servo(PAN_SERVO_PIN,  &pan_position,  BUTTON_RIGHT_PIN, "Pan");
        update_servo(TILT_SERVO_PIN, &tilt_position, BUTTON_UP_PIN,    "Tilt");
        update_servo(TILT_SERVO_PIN, &tilt_position, BUTTON_DOWN_PIN,  "Tilt");
        gpioDelay(LOOP_DELAY_US);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

