#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>
#include <curl/curl.h>

#define PIR_GPIO 17
#define DEBOUNCE_SEC 2
#define POLL_INTERVAL_US 100000
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_QUALITY 85
#define CAPTURE_DIR "motion_captures"
#define MAX_FILENAME_LEN 256
#define MAX_TIMESTAMP_LEN 64
#define MAX_JSON_LEN 512
#define MAX_RESPONSE_LEN 1024

static volatile sig_atomic_t program_running = 1;
static const char *server_ip = NULL;
static int server_port = 0;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int ensure_capture_dir(void) {
    struct stat st;
    if (stat(CAPTURE_DIR, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", CAPTURE_DIR);
        return -1;
    }
    if (mkdir(CAPTURE_DIR, 0755) != 0) {
        perror("mkdir(" CAPTURE_DIR ")");
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[MAX_FILENAME_LEN + 256];
    int ret = snprintf(command, sizeof(command),
        "libcamera-still -o %s/%s -w %d -h %d -q %d --nopreview 2>/dev/null",
        CAPTURE_DIR, filename, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: filename too long\n");
        return -1;
    }
    int status = system(command);
    if (status == -1) {
        perror("system()");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: libcamera-still failed (status=%d)\n", status);
        return -1;
    }
    return 0;
}

static int format_json(char *buf, size_t buflen, const char *filename,
                       const char *timestamp, int motion_status, int gpio_pin) {
    int ret = snprintf(buf, buflen,
        "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion_status\":%d,\"gpio_pin\":%d}",
        filename, timestamp, motion_status, gpio_pin);
    if (ret < 0 || (size_t)ret >= buflen) {
        fprintf(stderr, "Error: JSON buffer too small\n");
        return -1;
    }
    return 0;
}

static int send_http_request(const char *json_data) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error: curl_easy_init() failed\n");
        return -1;
    }

    char url[MAX_FILENAME_LEN + 16];
    int ret = snprintf(url, sizeof(url), "http://%s:%d/upload", server_ip, server_port);
    if (ret < 0 || (size_t)ret >= sizeof(url)) {
        fprintf(stderr, "Error: URL too long\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "Error: curl_slist_append() failed\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    int rc = 0;
    if (res != CURLE_OK) {
        fprintf(stderr, "Error: curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        rc = -1;
    } else {
        long http_code = 0;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
        if (http_code < 200 || http_code >= 300) {
            fprintf(stderr, "Error: HTTP request failed with code %ld\n", http_code);
            rc = -1;
        }
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return rc;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }
    server_ip = argv[1];
    server_port = atoi(argv[2]);
    if (server_port <= 0 || server_port > 65535) {
        fprintf(stderr, "Error: invalid port %s\n", argv[2]);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (ensure_capture_dir() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
