static int ensure_capture_dir(void) {
    struct stat st;
    if (stat(CAPTURE_DIR, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", CAPTURE_DIR);
        return -1;
    }
    if (mkdir(CAPTURE_DIR, 0755) != 0) {
        perror("mkdir(" CAPTURE_DIR ")");
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[MAX_FILENAME_LEN + 256];
    int ret = snprintf(command, sizeof(command),
        "libcamera-still -o %s/%s -w %d -h %d -q %d --nopreview 2>/dev/null",
        CAPTURE_DIR, filename, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: filename too long\n");
        return -1;
    }
    int status = system(command);
    if (status == -1) {
        perror("system()");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: libcamera-still failed (status=%d)\n", status);
        return -1;
    }
    return 0;
}

static int format_json(char *buf, size_t buflen, const char *filename,
                       const char *timestamp, int motion_status, int gpio_pin) {
    int ret = snprintf(buf, buflen,
        "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion_status\":%d,\"gpio_pin\":%d}",
        filename, timestamp, motion_status, gpio_pin);
    if (ret < 0 || (size_t)ret >= buflen) {
        fprintf(stderr, "Error: JSON buffer too small\n");
        return -1;
    }
    return 0;
}

static int send_http_request(const char *json_data) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error: curl_easy_init() failed\n");
        return -1;
    }

    char url[MAX_FILENAME_LEN + 16];
    int ret = snprintf(url, sizeof(url), "http://%s:%d/upload", server_ip, server_port);
    if (ret < 0 || (size_t)ret >= sizeof(url)) {
        fprintf(stderr, "Error: URL too long\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "Error: curl_slist_append() failed\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
