/*
 * motion_capture.c — Raspberry Pi Zero W
 * PIR motion sensor (HC-SR501) on BCM GPIO17 (physical pin 11)
 * Camera module v2 via libcamera-still (CLI)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o motion_capture motion_capture.c -lgpiod
 *
 * Run:
 *   ./motion_capture
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME      "gpiochip0"
#define GPIO_LINE_OFFSET    17          /* BCM 17, physical pin 11 */
#define IMAGE_DIR           "/home/pi/images"
#define LOG_FILE            "/home/pi/motion_capture.log"
#define DEBOUNCE_MS         50
#define POLL_TIMEOUT_MS     1000
#define IMAGE_WIDTH         640
#define IMAGE_HEIGHT        480
#define IMAGE_QUALITY       85
#define CAPTURE_TIMEOUT_MS  2000

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[unknown time] %s\n", msg);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
static void generate_filename(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        snprintf(buf, len, "unknown_000000_000.jpg");
        return;
    }
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        ts.tv_nsec = 0;
    }
    snprintf(buf, len, "%04d%02d%02d_%02d%02d%02d_%03ld.jpg",
             tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
             tm.tm_hour, tm.tm_min, tm.tm_sec, ts.tv_nsec / 1000000L);
}

/* ------------------------------------------------------------------ */
static int capture_image(const char *filename)
{
    char cmd[1024];
    int n = snprintf(cmd, sizeof(cmd),
                     "libcamera-still -o '%s' --width %d --height %d "
                     "-q %d --timeout %d --nopreview 2>>'%s'",
                     filename, IMAGE_WIDTH, IMAGE_HEIGHT,
                     IMAGE_QUALITY, CAPTURE_TIMEOUT_MS, LOG_FILE);
    if (n < 0 || (size_t)n >= sizeof(cmd)) {
        log_event("Command buffer overflow");
        return -1;
    }

    int status = system(cmd);
    if (status == -1) {
        log_event("system() failed to launch libcamera-still");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        char msg[256];
        snprintf(msg, sizeof(msg),
                 "libcamera-still failed (status=0x%04x)", status);
        log_event(msg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        log_event("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        log_event("Failed to get GPIO line 17");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request line as input with falling-edge event detection */
    if (gpiod_line_request_falling_edge_events(line, "motion_capture") < 0) {
        perror("gpiod_line_request_falling_edge_events");
        log_event("Failed to request falling-edge events on GPIO17");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_event("Motion capture service started");

    /* Main loop */
    while (g_running) {
        /* Block up to POLL_TIMEOUT_MS waiting for a falling edge */
        int ret = gpiod_line_event_wait(line, &(struct timespec){
            .tv_sec  = POLL_TIMEOUT_MS / 1000,
            .tv_nsec = (POLL_TIMEOUT_MS % 1000) * 1000000L
        });

        if (ret < 0) {
            if (errno == EINTR) {
                continue;  /* Signal received — check g_running */
            }
            perror("gpiod_line_event_wait");
            log_event("GPIO event wait error");
            break;
        }
        if (ret == 0) {
            continue;      /* Timeout — no event */
        }

        /* Event detected — read it to clear the queue */
        struct gpiod_line_event ev;
        if (gpiod_line_event_read(line, &ev) < 0) {
            perror("gpiod_line_event_read");
            log_event("Failed to read GPIO event");
            continue;
        }

        /* Debounce: wait for stable low for DEBOUNCE_MS */
        struct timespec debounce_ts = {
            .tv_sec  = DEBOUNCE_MS / 1000,
            .tv_nsec = (DEBOUNCE_MS % 1000) * 1000000L
        };
        nanosleep(&debounce_ts, NULL);

        /* Re-read — if still low, confirm motion */
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            log_event("Failed to read GPIO value after debounce");
            continue;
        }
        if (val != 0) {
            continue;  /* Line went high again — not motion */
        }

        /* Motion confirmed — generate filename and capture */
        char filename[256];
        generate_filename(filename, sizeof(filename));

        char filepath[512];
        snprintf(filepath, sizeof(filepath), "%s/%s", IMAGE_DIR, filename);

        if (capture_image(filepath) == 0) {
            char msg[512];
            snprintf(msg, sizeof(msg), "Motion detected — saved %s", filepath);
            log_event(msg);
        } else {
            log_event("Image capture failed");
        }
    }

    /* Cleanup */
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    log_event("Motion capture service stopped");
    return EXIT_SUCCESS;
}

