#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define OUTPUT_FILE "cropped.yuv"
#define WIDTH 640
#define HEIGHT 480
#define CROP_X 100
#define CROP_Y 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define FRAME_TIMEOUT_SEC 2

struct buffer {
    void   *start;
    size_t  length;
};

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static void cleanup(int fd, struct buffer *buf, int n_buffers) {
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1)
            perror("VIDIOC_STREAMOFF");
    }
    if (buf) {
        for (int i = 0; i < n_buffers; i++) {
            if (buf[i].start && buf[i].start != MAP_FAILED)
                munmap(buf[i].start, buf[i].length);
        }
        free(buf);
    }
    if (fd >= 0)
        close(fd);
}

static void sig_handler(int sig) {
    (void)sig;
    _exit(EXIT_FAILURE);
}

int main(void) {
    int fd = -1;
    struct buffer *buf = NULL;
    int n_buffers = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("open(" DEVICE_NAME ")");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        goto out;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        goto out;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        goto out;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        goto out;
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Camera does not support YUYV format\n");
        goto out;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto out;
    }
    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto out;
    }

    buf = calloc(req.count, sizeof(*buf));
    if (!buf) {
        perror("calloc");
        goto out;
    }

    for (n_buffers = 0; n_buffers < req.count; n_buffers++) {
        struct v4l2_buffer buf_query;
        memset(&buf_query, 0, sizeof(buf_query));
        buf_query.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf_query.memory = V4L2_MEMORY_MMAP;
        buf_query.index = n_buffers;
        if (xioctl(fd, VIDIOC_QUERYBUF, &buf_query) == -1) {
            perror("VIDIOC_QUERYBUF");
            goto out;
        }
        buf[n_buffers].length = buf_query.length;
        buf[n_buffers].start = mmap(NULL, buf_query.length,
                                    PROT_READ | PROT_WRITE,
                                    MAP_SHARED, fd, buf_query.m.offset);
        if (buf[n_buffers].start == MAP_FAILED) {
            perror("mmap");
            buf[n_buffers].start = NULL;
            goto out;
        }
    }

    for (int i = 0; i < n_buffers; i++) {
        struct v4l2_buffer buf_fill;
        memset(&buf_fill, 0, sizeof(buf_fill));
        buf_fill.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf_fill.memory = V4L2_MEMORY_MMAP;
        buf_fill.index = i;
        if (xioctl(fd, VIDIOC_QBUF, &buf_fill) == -1) {
            perror("VIDIOC_QBUF");
            goto out;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        goto out;
    }

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = FRAME_TIMEOUT_SEC;
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) {
            fprintf(stderr, "Interrupted by signal\n");
            goto out;
        }
        perror("select");
        goto out;
    }
    if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        goto out;
    }

    struct v4l2_buffer buf_deq;
    memset(&buf_deq, 0, sizeof(buf_deq));
    buf_deq.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf_deq.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_DQBUF, &buf_deq) == -1) {
        perror("VIDIOC_DQBUF");
        goto out;
    }

    if (buf_deq.bytesused < 1) {
        fprintf(stderr, "No data captured\n");
        goto out;
    }
    if (buf_deq.index >= n_buffers) {
        fprintf(stderr, "Invalid buffer index %u\n", buf_deq.index);
        goto out;
    }

    if (buf_deq.width != WIDTH || buf_deq.height != HEIGHT) {
        fprintf(stderr, "Captured frame size %ux%u does not match requested %ux%u\n",
                buf_deq.width, buf_deq.height, WIDTH, HEIGHT);
        goto out;
    }

    unsigned char *yuyv = (unsigned char *)buf[buf_deq.index].start;
    size_t yuyv_len = buf[buf_deq.index].length;
    size_t need = (size_t)WIDTH * HEIGHT * 2;
    if (yuyv_len < need) {
        fprintf(stderr, "Buffer too small: %zu bytes, need %zu\n", yuyv_len, need);
        goto out;
    }

    unsigned char *cropped = malloc((size_t)CROP_WIDTH * CROP_HEIGHT * 2);
    if (!cropped) {
        perror("malloc");
        goto out;
    }

    for (int y = 0; y < CROP_HEIGHT; y++) {
        for (int x = 0; x < CROP_WIDTH; x++) {
            int src_x = CROP_X + x;
            int src_y = CROP_Y + y;
            if (src_x >= WIDTH || src_y >= HEIGHT) {
                fprintf(stderr, "Crop region exceeds frame bounds\n");
                free(cropped);
                goto out;
            }
            size_t src_idx = (size_t)src_y * WIDTH * 2 + (size_t)src_x * 2;
            size_t dst_idx = (size_t)y * CROP_WIDTH * 2 + (size_t)x * 2;
            cropped[dst_idx]     = yuyv[src_idx];
            cropped[dst_idx + 1] = yuyv[src_idx + 1];
            cropped[dst_idx + 2] = yuyv[src_idx + 2];
            cropped[dst_idx + 3] = yuyv[src_idx + 3];
        }
    }

    FILE *fp = fopen(OUTPUT_FILE, "wb");
    if (!fp) {
        perror("fopen(" OUTPUT_FILE ")");
        free(cropped);
        goto out;
    }
    size_t to_write = (size_t)CROP_WIDTH * CROP_HEIGHT * 2;
    if (fwrite(cropped, 1, to_write, fp) != to_write) {
        perror("fwrite");
        fclose(fp);
        free(cropped);
        goto out;
    }
    if (fclose(fp) == EOF) {
        perror("fclose");
        free(cropped);
        goto out;
    }
    free(cropped);

    printf("Cropped YUYV frame saved to %s (%dx%d)\n", OUTPUT_FILE, CROP_WIDTH, CROP_HEIGHT);
    ret = EXIT_SUCCESS;

out:
    cleanup(fd, buf, n_buffers);
    return ret;
}

