#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_GPIO 17
#define TILT_GPIO 18
#define NEUTRAL_ANGLE 90
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define STEP_SIZE 5
#define DELAY_MS 100

static volatile int running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int angle_to_pulse(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d out of range [%d, %d]\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    return MIN_PULSE_WIDTH + (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / (MAX_ANGLE - MIN_ANGLE));
}

static int set_servo_angle(int gpio, int angle) {
    int pulse = angle_to_pulse(angle);
    if (pulse < 0) return -1;
    if (gpioServo(gpio, pulse) != 0) {
        fprintf(stderr, "Error: gpioServo(%d, %d) failed\n", gpio, pulse);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    set_servo_angle(PAN_GPIO, NEUTRAL_ANGLE);
    set_servo_angle(TILT_GPIO, NEUTRAL_ANGLE);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    int pan_angle = NEUTRAL_ANGLE;
    int tilt_angle = NEUTRAL_ANGLE;

    if (set_servo_angle(PAN_GPIO, pan_angle) != 0 ||
        set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
        cleanup();
        return 1;
    }

    printf("Pan-Tilt Camera Mount Control\n");
    printf("Use arrow keys (W/A/S/D) to move. Press 'q' to quit.\n");

    while (running) {
        int c = getchar();
        if (c == EOF) break;

        switch (c) {
            case 'w':
            case 'W':
                if (tilt_angle + STEP_SIZE <= MAX_ANGLE) {
                    tilt_angle += STEP_SIZE;
                    if (set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
                        cleanup();
                        return 1;
                    }
                }
                break;
            case 's':
            case 'S':
                if (tilt_angle - STEP_SIZE >= MIN_ANGLE) {
                    tilt_angle -= STEP_SIZE;
                    if (set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
                        cleanup();
                        return 1;
                    }
                }
                break;
            case 'a':
            case 'A':
                if (pan_angle - STEP_SIZE >= MIN_ANGLE) {
                    pan_angle -= STEP_SIZE;
                    if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
                        cleanup();
                        return 1;
                    }
                }
                break;
            case 'd':
            case 'D':
                if (pan_angle + STEP_SIZE <= MAX_ANGLE) {
                    pan_angle += STEP_SIZE;
                    if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
                        cleanup();
                        return 1;
                    }
                }
                break;
            case 'q':
            case 'Q':
                running = 0;
                break;
            default:
                break;
        }
        usleep(DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

