#define OLED_I2C_ADDR 0x3C
#define OLED_I2C_BUS 1

#define SSD1306_COMMAND 0x00
#define SSD1306_DATA 0x40

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int oled_command(unsigned char cmd) {
    char buf[2] = {SSD1306_COMMAND, (char)cmd};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "I2C write error (command 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int oled_init(void) {
    if (oled_command(0xAE) < 0) return -1; // Display off
    oled_command(0xD5); oled_command(0x80); // Display clock divide
    oled_command(0xA8); oled_command(0x3F); // Multiplex ratio
    oled_command(0xD3); oled_command(0x00); // Display offset
    oled_command(0x40); // Start line
    oled_command(0x8D); oled_command(0x14); // Charge pump
    oled_command(0x20); oled_command(0x00); // Memory addressing mode
    oled_command(0xA1); // Segment remap
    oled_command(0xC8); // COM scan direction
    oled_command(0xDA); oled_command(0x12); // COM pins
    oled_command(0x81); oled_command(0xCF); // Contrast
    oled_command(0xD9); oled_command(0xF1); // Pre-charge period
    oled_command(0xDB); oled_command(0x40); // VCOMH deselect
    oled_command(0xA4); // Normal display
    oled_command(0xA6); // Normal display (not inverted)
    oled_command(0xAF); // Display on
    return 0;
}

static int oled_clear(void) {
    char buf[1 + OLED_WIDTH];
    buf[0] = SSD1306_DATA;
    memset(buf + 1, 0x00, OLED_WIDTH);
    for (int i = 0; i < OLED_HEIGHT / 8; i++) {
        if (i2cWriteDevice(i2c_handle, buf, sizeof(buf)) != 0) {
            fprintf(stderr, "I2C write error during clear: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

static int oled_set_cursor(int page, int col) {
    if (oled_command(0xB0 + page) < 0) return -1;
    if (oled_command(0x00 + (col & 0x0F)) < 0) return -1;
    if (oled_command(0x10 + ((col >> 4) & 0x0F)) < 0) return -1;
    return 0;
}

static int oled_write_buffer(const unsigned char *data, int len) {
    char buf[1 + OLED_WIDTH];
    buf[0] = SSD1306_DATA;
    if (len > OLED_WIDTH) len = OLED_WIDTH;
    memcpy(buf + 1, data, len);
    if (i2cWriteDevice(i2c_handle, buf, len + 1) != 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

