static int get_cpu_temp(void) {
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) {
        fprintf(stderr, "Error opening CPU temperature file: %s\n", strerror(errno));
        return -1;
    }
    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading CPU temperature\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp;
}

static int get_cpu_usage(void) {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1;
    }
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error parsing /proc/stat\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    static unsigned long long prev_user = 0, prev_system = 0, prev_idle = 0;
    unsigned long long user_delta = user - prev_user;
    unsigned long long system_delta = system - prev_system;
    unsigned long long idle_delta = idle + iowait + steal - prev_idle;
    prev_user = user;
    prev_system = system;
    prev_idle = idle + iowait + steal;
    unsigned long long total_delta = user_delta + system_delta + idle_delta;
    if (total_delta == 0) return 0;
    return (int)((user_delta + system_delta) * 100 / total_delta);
}

static void display_text(const char *text, int page, int col) {
    if (oled_set_cursor(page, col) < 0) return;
    unsigned char buf[OLED_WIDTH];
    int idx = 0;
    while (text[idx] != '\0' && idx < OLED_WIDTH) {
        unsigned char c = (unsigned char)text[idx];
        if (c < 32 || c > 126) c = ' ';
        int font_idx = c - 32;
        if (font_idx < 0 || font_idx >= 95) font_idx = 0;
        buf[idx] = font5x7[font_idx][0];
        buf[idx + 1] = font5x7[font_idx][1];
        buf[idx + 2] = font5x7[font_idx][2];
        buf[idx + 3] = font5x7[font_idx][3];
        buf[idx + 4] = font5x7[font_idx][4];
        idx += 5;
    }
    for (int i = idx; i < OLED_WIDTH; i++) buf[i] = 0x00;
    oled_write_buffer(buf, OLED_WIDTH);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(OLED_I2C_BUS, OLED_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (oled_init() < 0) {
        fprintf(stderr, "OLED initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (oled_clear() < 0) {
        fprintf(stderr, "OLED clear failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    while (running) {
        int temp = get_cpu_temp();
        int usage = get_cpu_usage();
        char temp_str[16];
        char usage_str[16];
        if (temp < 0) {
            snprintf(temp_str, sizeof(temp_str), "Temp: ERROR");
        } else {
            snprintf(temp_str, sizeof(temp_str), "Temp: %.1f C", temp / 1000.0);
        }
        if (usage < 0) {
            snprintf(usage_str, sizeof(usage_str), "Usage: ERROR");
        } else {
            snprintf(usage_str, sizeof(usage_str), "Usage: %d%%", usage);
        }
        oled_clear();
        display_text(temp_str, 0, 0);
        display_text(usage_str, 2, 0);
        sleep(1);
    }
    oled_clear();
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

