#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450.0
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04

static volatile sig_atomic_t running = 1;
static volatile int pulse_count = 0;
static volatile double accumulated_volume = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)tick; (void)userdata;
    if (level == 1) {
        pulse_count++;
    }
}

static void lcd_strobe(int data) {
    int handle = *(int *)userdata;
    if (i2cWriteByteData(handle, ENABLE | LCD_BACKLIGHT, data) < 0) {
        fprintf(stderr, "I2C write error during strobe (high)\n");
        return;
    }
    gpioDelay(2000);
    if (i2cWriteByteData(handle, ~ENABLE | LCD_BACKLIGHT, data) < 0) {
        fprintf(stderr, "I2C write error during strobe (low)\n");
        return;
    }
    gpioDelay(2000);
}

static void lcd_byte(int bits, int mode, int handle) {
    int high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    int low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;
    if (i2cWriteByteData(handle, high, 0) < 0) {
        fprintf(stderr, "I2C write error (high nibble)\n");
        return;
    }
    lcd_strobe(high);
    if (i2cWriteByteData(handle, low, 0) < 0) {
        fprintf(stderr, "I2C write error (low nibble)\n");
        return;
    }
    lcd_strobe(low);
}

static void lcd_string(const char *s, int handle) {
    while (*s) {
        lcd_byte((int)*s++, LCD_CHR, handle);
    }
}

static void lcd_clear(int handle) {
    lcd_byte(0x01, LCD_CMD, handle);
    gpioDelay(2000);
}

static void lcd_init(int handle) {
    gpioDelay(50000);
    lcd_byte(0x33, LCD_CMD, handle);
    lcd_byte(0x32, LCD_CMD, handle);
    lcd_byte(0x28, LCD_CMD, handle);
    lcd_byte(0x0C, LCD_CMD, handle);
    lcd_byte(0x06, LCD_CMD, handle);
    lcd_byte(0x01, LCD_CMD, handle);
    gpioDelay(2000);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function on GPIO %d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    int i2c_handle = i2cOpen(1, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X\n", LCD_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    lcd_init(i2c_handle);
    lcd_clear(i2c_handle);

    while (running) {
        int local_pulse_count = 0;
        for (int i = 0; i < 10 && running; i++) {
            gpioDelay(1000000);
        }
        if (!running) break;

        local_pulse_count = pulse_count;
        pulse_count = 0;

        double flow_rate = (double)local_pulse_count / PULSES_PER_LITER * 60.0;
        accumulated_volume += (double)local_pulse_count / PULSES_PER_LITER;

        printf("Flow Rate: %.2f L/min, Accumulated Volume: %.2f L\n", flow_rate, accumulated_volume);

        char line1[LCD_WIDTH + 1];
        char line2[LCD_WIDTH + 1];
        snprintf(line1, sizeof(line1), "Flow: %.2f L/min", flow_rate);
        snprintf(line2, sizeof(line2), "Vol: %.2f L", accumulated_volume);

        lcd_clear(i2c_handle);
        lcd_byte(LCD_LINE_1, LCD_CMD, i2c_handle);
        lcd_string(line1, i2c_handle);
        lcd_byte(LCD_LINE_2, LCD_CMD, i2c_handle);
        lcd_string(line2, i2c_handle);
    }

    lcd_clear(i2c_handle);
    lcd_string("Shutting down...", i2c_handle);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

