#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define LCD_ADDR        0x27
#define LCD_WIDTH       16
#define LCD_CHR         1
#define LCD_CMD         0
#define LCD_BACKLIGHT   0x08
#define LCD_ENABLE      0x04

#define ANEMOMETER_GPIO 17
#define SPI_BUS         0
#define SPI_CS          0
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        0
#define SPI_BITS        8

#define SAMPLE_MS       500
#define PULSES_PER_M_S  0.5f

static volatile int g_pulse_count = 0;
static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void anemometer_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    g_pulse_count++;
}

static int lcd_write_byte(int handle, uint8_t val) {
    char buf[4];
    buf[0] = val | LCD_BACKLIGHT;
    buf[1] = (val | LCD_BACKLIGHT) | LCD_ENABLE;
    buf[2] = val | LCD_BACKLIGHT;
    buf[3] = (val | LCD_BACKLIGHT) & ~LCD_ENABLE;
    if (i2cWriteDevice(handle, buf, 4) != 4) {
        fprintf(stderr, "LCD I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int lcd_init(int handle) {
    gpioDelay(50000);
    if (lcd_write_byte(handle, 0x33) < 0) return -1;
    gpioDelay(5000);
    if (lcd_write_byte(handle, 0x32) < 0) return -1;
    gpioDelay(5000);
    if (lcd_write_byte(handle, 0x28) < 0) return -1;
    if (lcd_write_byte(handle, 0x0C) < 0) return -1;
    if (lcd_write_byte(handle, 0x06) < 0) return -1;
    if (lcd_write_byte(handle, 0x01) < 0) return -1;
    gpioDelay(2000);
    return 0;
}

static int lcd_clear(int handle) {
    if (lcd_write_byte(handle, 0x01) < 0) return -1;
    gpioDelay(2000);
    return 0;
}

static int lcd_print(int handle, int row, const char *text) {
    if (row != 0 && row != 1) return -1;
    uint8_t addr = (uint8_t)(0x80 + (row * 0x40));
    if (lcd_write_byte(handle, addr) < 0) return -1;
    for (int i = 0; i < LCD_WIDTH; i++) {
        if (text[i] == '\0') break;
        if (lcd_write_byte(handle, (uint8_t)text[i]) < 0) return -1;
    }
    return 0;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) return -1;
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {0};
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    if (ioctl(spi_handle, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int map_adc_to_degrees(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) return -1;
    if (adc_value < 100) return 0;
    if (adc_value < 200) return 45;
    if (adc_value < 300) return 90;
    if (adc_value < 400) return 135;
    if (adc_value < 500) return 180;
    if (adc_value < 600) return 225;
    if (adc_value < 700) return 270;
    if (adc_value < 800) return 315;
    return 360;
}

int main(void) {
    int i2c_handle = -1, spi_handle = -1;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %s\n", LCD_ADDR, strerror(errno));
        goto cleanup_gpio;
    }

    if (lcd_init(i2c_handle) < 0) {
        fprintf(stderr, "LCD initialisation failed\n");
        goto cleanup_i2c;
    }

    spi_handle = spiOpen(SPI_BUS, SPI_CS, SPI_SPEED_HZ);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI bus %d, CS %d: %s\n", SPI_BUS, SPI_CS, strerror(errno));
        goto cleanup_i2c;
    }

    if (gpioSetMode(ANEMOMETER_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", ANEMOMETER_GPIO);
        goto cleanup_spi;
