static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void flow_alert(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    if (level == 1) {
        pulse_count++;
    }
}

static void lcd_strobe(int data) {
    if (i2c_fd < 0) return;
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) return;
    int rs = (data & 0x01) ? LCD_CHR : LCD_CMD;
    int hi = rs | (data & 0xF0) | LCD_BACKLIGHT;
    int lo = rs | ((data & 0xF0) << 4) | LCD_BACKLIGHT;
    char buf[4];
    buf[0] = hi | ENABLE;
    buf[1] = hi;
    buf[2] = lo | ENABLE;
    buf[3] = lo;
    if (write(i2c_fd, buf, 4) != 4) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
    }
}

static void lcd_byte(int bits, int mode) {
    int data = bits | mode;
    lcd_strobe(data);
}

static void lcd_string(const char *s) {
    while (*s) {
        lcd_byte(*s++, LCD_CHR);
    }
}

static void lcd_clear(void) {
    lcd_byte(0x01, LCD_CMD);
    gpioDelay(2000);
}

static void lcd_init(void) {
    if (i2c_fd < 0) return;
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) return;
