    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    lcd_init();

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLOW_SENSOR_GPIO);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", FLOW_SENSOR_GPIO);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(FLOW_SENSOR_GPIO, flow_alert) != 0) {
        fprintf(stderr, "Failed to set alert function on GPIO %d\n", FLOW_SENSOR_GPIO);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    int zero_pulse_count = 0;
    const int zero_pulse_threshold = 10;

    while (running) {
        pulse_count = 0;
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);

        int pulses = pulse_count;
        float flow_rate = (float)pulses / PULSES_PER_LITER * 60.0;

        if (pulses == 0) {
            zero_pulse_count++;
            if (zero_pulse_count >= zero_pulse_threshold) {
                fprintf(stderr, "Warning: No flow detected for %d samples. Sensor may be absent or disconnected.\n", zero_pulse_count);
                zero_pulse_count = 0;
            }
        } else {
            zero_pulse_count = 0;
        }

