        printf("Flow Rate: %.2f L/min (Pulses: %d)\n", flow_rate, pulses);
    }

    printf("\nShutting down...\n");
    lcd_clear();
    lcd_string("Shutting down");
    gpioDelay(1000000);
    lcd_clear();

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    gpioTerminate();
    return 0;
}

