/*
 * VL53L3CX Multi-Target Time-of-Flight Sensor Reader
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (I2C)
 * Bus:     I2C bus 1, address 0x29
 *
 * NOTE: The VL53L3CX contains proprietary firmware that must be loaded
 *       via I2C before the sensor can be used.  This program stubs the
 *       firmware download with a descriptive comment and implements the
 *       standard ULD register-level flow for configuration and data
 *       acquisition.  A production-ready implementation requires the
 *       official ST Ultra Lite Driver (ULD) binary and the accompanying
 *       platform-specific initialization sequence.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L3CX I2C address ---- */
#define VL53L3CX_ADDR 0x29

/* ---- VL53L3CX register map (standard ULD) ---- */
#define VL53L3CX_REG_SOFT_RESET          0x000B
#define VL53L3CX_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L3CX_REG_SYSTEM_MODE_START   0x0000
#define VL53L3CX_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L3CX_REG_RESULT_DISTANCE     0x0096
#define VL53L3CX_REG_RESULT_SPAD_NB      0x0098
#define VL53L3CX_REG_RESULT_PEAK_SIGNAL_COUNT_RATE 0x009A
#define VL53L3CX_REG_RESULT_AMBIENT_COUNT_RATE 0x009C
#define VL53L3CX_REG_RESULT_SIGMA 0x009E
#define VL53L3CX_REG_RESULT_TEMP_COMP 0x00A0
#define VL53L3CX_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L3CX_REG_SYSTEM_INTERRUPT_STATUS 0x0084
#define VL53L3CX_REG_SYSTEM_THRESH_HIGH 0x008A
#define VL53L3CX_REG_SYSTEM_THRESH_LOW  0x008C
#define VL53L3CX_REG_SYSTEM_GROUPED_PARAMETER_HOLD 0x008E
#define VL53L3CX_REG_SYSTEM_GROUPED_PARAMETER_UPDATE 0x008F

/* ---- Expected model ID ---- */
#define VL53L3CX_EXPECTED_MODEL_ID 0xEA

/* ---- Globals ---- */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* ---- Sensor initialization ---- */
static int vl53l3cx_init(int handle)
{
    uint8_t model_id = 0;

    /* 1. Soft reset */
    if (i2c_write_reg16(handle, VL53L3CX_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write soft reset.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* 2. Verify model ID */
    if (i2c_read_reg16(handle, VL53L3CX_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: failed to read model ID.\n");
        return -1;
    }
    if (model_id != VL53L3CX_EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X).\n",
                model_id, VL53L3CX_EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L3CX detected (model ID 0x%02X).\n", model_id);

    /*
     * 3. Stubbed firmware download.
     *    In a production environment, the official ST Ultra Lite Driver
     *    (ULD) binary must be loaded via I2C using the standard
     *    firmware-download sequence.  This sequence involves writing
     *    the firmware data to specific ULD registers and issuing a
     *    start command.
     */
    printf("Loading VL53L3CX firmware (stubbed - production ULD required)...\n");
    gpioDelay(50000); /* 50 ms */

    /* 4. Configure standard ULD registers */
    if (i2c_write_reg16(handle, VL53L3CX_REG_SYSTEM_MODE_START, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set system mode.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* 5. Start continuous ranging */
    if (i2c_write_reg16(handle, VL53L3CX_REG_SYSTEM_MODE_START, 0x40) < 0) {
        fprintf(stderr, "Error: failed to start ranging.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    printf("VL53L3CX initialized and ranging started.\n");
    return 0;
}

/* ---- Read a single target's distance ---- */
static int vl53l3cx_read_target(int handle, uint8_t target_num, uint16_t *distance)
{
    uint8_t status = 0;
    uint8_t dist_buf[2] = {0};

    /* Poll for data ready (interrupt status bit 0) */
    for (int i = 0; i < 50; i++) {
        if (i2c_read_reg16(handle, VL53L3CX_REG_SYSTEM_INTERRUPT_STATUS, &status, 1) < 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(2000); /* 2 ms */
    }
    if (!(status & 0x01)) {
        fprintf(stderr, "Warning: target %u data not ready.\n", target_num);
        return -1;
    }

    /* Read distance (16-bit, big-endian) */
    if (i2c_read_reg16(handle, VL53L3CX_REG_RESULT_DISTANCE, dist_buf, 2) < 0)
        return -1;

    *distance = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];

    /* Clear interrupt */
    if (i2c_write_reg16(handle, VL53L3CX_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    return 0;
}

/* ---- Log a timestamped distance reading ---- */
static void log_distance(uint8_t target_num, uint16_t distance)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("%s - Target %u: Distance = %u mm\n", timestamp, target_num, distance);
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x29 */
    i2c_handle = i2cOpen(1, VL53L3CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l3cx_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Reading distances every 100 ms. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        uint16_t distance;

        if (vl53l3cx_read_target(i2c_handle, 0, &distance) == 0) {
            log_distance(0, distance);
        } else {
            fprintf(stderr, "Error: failed to read target 0.\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    i2c_write_reg16(i2c_handle, VL53L3CX_REG_SYSTEM_MODE_START, 0x00);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

