#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1145_ADDR        0x60
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY  0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_IRQ_ENABLE 0x0F
#define SI1145_REG_IRQ_STATUS 0x13
#define SI1145_REG_COMMAND  0x18
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_ALS_IR_DATA0  0x24
#define SI1145_REG_ALS_IR_DATA1  0x25

#define SI1145_PART_ID      0x45
#define SI1145_HW_KEY_VAL   0x17
#define SI1145_CMD_RESET    0x01
#define SI1145_CMD_ALS_FORCE 0x06

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, val, rc);
        return -1;
    }
    return 0;
}

static int si1145_init(int handle)
{
    uint8_t part_id;
    if (i2c_read_reg(handle, SI1145_REG_PART_ID, &part_id) != 0)
        return -1;
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }

    if (i2c_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    if (i2c_write_reg(handle, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) != 0)
        return -1;

    if (i2c_write_reg(handle, SI1145_REG_MEAS_RATE0, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, SI1145_REG_MEAS_RATE1, 0x00) != 0)
        return -1;

    if (i2c_write_reg(handle, SI1145_REG_IRQ_ENABLE, 0x00) != 0)
        return -1;
    if (i2c_write_reg(handle, SI1145_REG_IRQ_STATUS, 0xFF) != 0)
        return -1;

    return 0;
}

static int read_sensor_data(int handle, uint16_t *proximity, uint16_t *ambient_light)
{
    if (i2c_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    uint8_t vis_lo, vis_hi, ir_lo, ir_hi;
    if (i2c_read_reg(handle, SI1145_REG_ALS_VIS_DATA0, &vis_lo) != 0)
        return -1;
    if (i2c_read_reg(handle, SI1145_REG_ALS_VIS_DATA1, &vis_hi) != 0)
        return -1;
    if (i2c_read_reg(handle, SI1145_REG_ALS_IR_DATA0, &ir_lo) != 0)
        return -1;
    if (i2c_read_reg(handle, SI1145_REG_ALS_IR_DATA1, &ir_hi) != 0)
        return -1;

    *ambient_light = (uint16_t)((vis_hi << 8) | vis_lo);
    *proximity     = (uint16_t)((ir_hi  << 8) | ir_lo);
    return 0;
}

static void log_data(FILE *fp, uint16_t proximity, uint16_t ambient_light)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(fp, "%s, Proximity: %u, Ambient Light: %u\n",
            timestamp, proximity, ambient_light);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at addr 0x%02X: %d\n", SI1145_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (si1145_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("biometric_log.txt", "a");
    if (g_log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

