#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR_PIN  4   /* GPIO 4  (physical pin 7)  - E18-D50NK OUT */
#define LED_PIN     17  /* GPIO 17 (physical pin 11) - LED anode */
#define LOG_FILE    "proximity.log"
#define POLL_MS     100
#define BLINK_MS    100

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_utc;
    char ts[32];
    if (gmtime_r(&t, &tm_utc)) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    } else {
        strncpy(ts, "1970-01-01T00:00:00Z", sizeof(ts));
    }

    fprintf(fp, "%s %s\n", ts, msg);
    fclose(fp);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor = NULL;
    struct gpiod_line *led = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* On Raspberry Pi 5 the main GPIO controller is gpiochip4. */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        /* Fallback: older kernels use gpiochip0. */
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    sensor = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor) {
        fprintf(stderr, "get_line(%d): %s\n", SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "get_line(%d): %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor, "e18-d50nk") < 0) {
        fprintf(stderr, "request_input(%d): %s\n", SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led, "e18-d50nk-led", 0) < 0) {
        fprintf(stderr, "request_output(%d): %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Proximity detection started (GPIO %d sensor, GPIO %d LED). Ctrl+C to exit.\n",
           SENSOR_PIN, LED_PIN);

    int prev = 1;  /* assume no object at startup (HIGH) */

    while (running) {
        int val = gpiod_line_get_value(sensor);
        if (val < 0) {
            fprintf(stderr, "get_value(%d): %s\n", SENSOR_PIN, strerror(errno));
            break;
        }

        /* Log only on HIGH -> LOW transition (object entering range). */
        if (prev == 1 && val == 0) {
            log_event("Object detected");
        }
        prev = val;

        /* Blink LED if object is detected. */
        if (val == 0) {
            if (gpiod_line_set_value(led, 1) < 0) {
                fprintf(stderr, "set_value(%d,1): %s\n", LED_PIN, strerror(errno));
                break;
            }
            usleep(BLINK_MS * 1000);
            if (gpiod_line_set_value(led, 0) < 0) {
                fprintf(stderr, "set_value(%d,0): %s\n", LED_PIN, strerror(errno));
                break;
            }
        }

        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led) gpiod_line_release(led);
    if (sensor) gpiod_line_release(sensor);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

