#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SI1145_ADDR 0x60
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_PS1_DATA0 0x18
#define SI1145_REG_PS1_DATA1 0x19
#define SI1145_REG_COMMAND 0x30
#define SI1145_REG_CH_LIST 0x4F
#define SI1145_PART_ID 0x45
#define SI1145_HW_KEY_VAL 0x17
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PS_FORCE 0x07

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int si1145_write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n", reg, val, rc);
    }
    return rc;
}

static int si1145_read_reg(uint8_t reg) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", reg, rc);
    }
    return rc;
}

static int si1145_read_word(uint8_t reg_low, uint16_t *out) {
    int lo = si1145_read_reg(reg_low);
    if (lo < 0) return -1;
    int hi = si1145_read_reg(reg_low + 1);
    if (hi < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int si1145_init(void) {
    int part_id = si1145_read_reg(SI1145_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor may be absent\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }
    if (si1145_write_reg(SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) return -1;
    if (si1145_write_reg(SI1145_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (si1145_write_reg(SI1145_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (si1145_write_reg(SI1145_REG_CH_LIST, 0x03) < 0) return -1;
    return 0;
}

static int si1145_read_data(uint16_t *proximity, uint16_t *ambient_light) {
    if (si1145_write_reg(SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) return -1;
    if (si1145_write_reg(SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE) < 0) return -1;
    gpioDelay(10000);
    if (si1145_read_word(SI1145_REG_PS1_DATA0, proximity) < 0) return -1;
    if (si1145_read_word(SI1145_REG_ALS_VIS_DATA0, ambient_light) < 0) return -1;
    return 0;
}

static void log_data(uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];
    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);
    fprintf(log_file, "%s,%u,%u\n", timestamp, proximity, ambient_light);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (si1145_init() < 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    log_file = fopen("biometric_data.log", "a");
    if (!log_file) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    while (!terminate) {
        uint16_t proximity, ambient_light;
        if (si1145_read_data(&proximity, &ambient_light) == 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(1);
    }
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

