    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }
    if (si1145_write_reg(SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) return -1;
    if (si1145_write_reg(SI1145_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (si1145_write_reg(SI1145_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (si1145_write_reg(SI1145_REG_CH_LIST, 0x03) < 0) return -1;
    return 0;
}

static int si1145_read_data(uint16_t *proximity, uint16_t *ambient_light) {
    if (si1145_write_reg(SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) return -1;
    if (si1145_write_reg(SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE) < 0) return -1;
    gpioDelay(10000);
    if (si1145_read_word(SI1145_REG_PS1_DATA0, proximity) < 0) return -1;
    if (si1145_read_word(SI1145_REG_ALS_VIS_DATA0, ambient_light) < 0) return -1;
    return 0;
}

static void log_data(uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];
    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);
    fprintf(log_file, "%s,%u,%u\n", timestamp, proximity, ambient_light);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (si1145_init() < 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    log_file = fopen("biometric_data.log", "a");
    if (!log_file) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    while (!terminate) {
        uint16_t proximity, ambient_light;
        if (si1145_read_data(&proximity, &ambient_light) == 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(1);
    }
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

