/*
 * Proximity-based plant watering reminder using an HC-SR04 ultrasonic
 * sensor on a Raspberry Pi Zero W.  Uses libgpiod for GPIO access.
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO 17 (BCM)
 *   HC-SR04 ECHO -> GPIO 27 (BCM) via 1k/2k voltage divider (5V -> 3.3V)
 *   HC-SR04 VCC  -> 5V, GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o plant_water plant_water.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27
#define CONSUMER         "plant_water"
#define LOG_FILE         "distance_log.txt"

#define SPEED_OF_SOUND   34300.0   /* cm/s at ~20 C */
#define WATER_THRESHOLD  15.0      /* cm */
#define MIN_DISTANCE     2.0       /* cm */
#define MAX_DISTANCE     400.0     /* cm */
#define TRIGGER_PULSE_US 10
#define TIMEOUT_MS       30
#define POLL_INTERVAL_S  60

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/*
 * Measure the echo pulse width in microseconds using libgpiod edge events.
 * Returns the pulse width in microseconds, or -1 on timeout / error.
 */
static long measure_echo_us(struct gpiod_line *echo_line)
{
    struct timespec ts_start, ts_now;
    struct gpiod_line_event event;
    int ret;

    /* Wait for echo to rise (timeout if sensor absent) */
    ret = gpiod_line_event_wait(echo_line, &(struct timespec){0, TIMEOUT_MS * 1000000L});
    if (ret < 0) {
        perror("gpiod_line_event_wait (rising)");
        return -1;
    }
    if (ret == 0) {
        return -1; /* timeout: no echo rising */
    }

    ret = gpiod_line_event_read(echo_line, &event);
    if (ret < 0) {
        perror("gpiod_line_event_read (rising)");
        return -1;
    }
    if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
        return -1;
    }
    ts_start = event.ts;

    /* Wait for echo to fall (timeout if echo stuck high) */
    ret = gpiod_line_event_wait(echo_line, &(struct timespec){0, TIMEOUT_MS * 1000000L});
    if (ret < 0) {
        perror("gpiod_line_event_wait (falling)");
        return -1;
    }
    if (ret == 0) {
        return -1; /* timeout: echo stuck high */
    }

    ret = gpiod_line_event_read(echo_line, &event);
    if (ret < 0) {
        perror("gpiod_line_event_read (falling)");
        return -1;
    }
    if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) {
        return -1;
    }
    ts_now = event.ts;

    long elapsed_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L
                    + (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;
    return elapsed_us;
}

static double calculate_distance_cm(long pulse_us)
{
    if (pulse_us <= 0)
        return -1.0;
    return (pulse_us / 1000000.0) * SPEED_OF_SOUND / 2.0;
}

static void log_reading(FILE *log_fp, double distance_cm, const char *status)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (distance_cm >= 0.0) {
        fprintf(log_fp, "%s Distance: %.2f cm, Status: %s\n", ts, distance_cm, status);
    } else {
        fprintf(log_fp, "%s Distance: ERROR, Status: %s\n", ts, status);
    }
    fflush(log_fp);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger_line = NULL;
    struct gpiod_line *echo_line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    install_signal_handlers();

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }

    if (gpiod_line_request_both_edges_events(echo_line, CONSUMER) < 0) {
        perror("gpiod_line_request_both_edges_events(echo)");
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(log)");
        goto cleanup;
    }

    printf("Plant watering reminder started. Press Ctrl+C to exit.\n");

    while (g_running) {
        /* Ensure trigger is low before starting */
        if (gpiod_line_set_value(trigger_line, 0) < 0) {
            perror("gpiod_line_set_value(trigger low)");
            break;
        }
        usleep(5);

        /* 10 us trigger pulse */
        if (gpiod_line_set_value(trigger_line, 1) < 0) {
            perror("gpiod_line_set_value(trigger high)");
            break;
        }
        usleep(TRIGGER_PULSE_US);
        if (gpiod_line_set_value(trigger_line, 0) < 0) {
            perror("gpiod_line_set_value(trigger low)");
            break;
        }

        long pulse_us = measure_echo_us(echo_line);
        double distance_cm = calculate_distance_cm(pulse_us);

        if (pulse_us < 0) {
            log_reading(log_fp, -1.0, "TIMEOUT/SENSOR_ERROR");
            printf("Error: timeout or sensor absent.\n");
        } else if (distance_cm < MIN_DISTANCE || distance_cm > MAX_DISTANCE) {
            log_reading(log_fp, distance_cm, "OUT_OF_RANGE");
            printf("Warning: distance %.2f cm out of range.\n", distance_cm);
        } else {
            log_reading(log_fp, distance_cm, "OK");
            printf("Distance: %.2f cm\n", distance_cm);
            if (distance_cm < WATER_THRESHOLD) {
                printf("Time to water the plant!\n");
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp)
        fclose(log_fp);
    if (trigger_line)
        gpiod_line_release(trigger_line);
    if (echo_line)
        gpiod_line_release(echo_line);
    if (chip)
        gpiod_chip_close(chip);

    printf("Exiting.\n");
    return ret;
}

