#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define APDS9960_I2C_ADDR 0x39
#define I2C_BUS 1

#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90
#define APDS9960_ID 0x92
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATA 0x9C

#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(handle, reg, val) < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, pigpio_error(i2cWriteByteData(handle, reg, val)));
        return -1;
    }
    return 0;
}

static int read_reg(int handle, uint8_t reg, uint8_t *val) {
    int r = i2cReadByteData(handle, reg);
    if (r < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, pigpio_error(r));
        return -1;
    }
    *val = (uint8_t)r;
    return 0;
}

static int init_apds9960(int handle) {
    uint8_t id;
    if (read_reg(handle, APDS9960_ID, &id) < 0) return -1;
    if (id != 0xAB) {
        fprintf(stderr, "Unexpected sensor ID: 0x%02X (expected 0xAB)\n", id);
        return -1;
    }

    if (write_reg(handle, APDS9960_ENABLE, 0x00) < 0) return -1;
    if (write_reg(handle, APDS9960_ATIME, 0xDB) < 0) return -1;
    if (write_reg(handle, APDS9960_WTIME, 0xF6) < 0) return -1;
    if (write_reg(handle, APDS9960_PPULSE, 0x87) < 0) return -1;
    if (write_reg(handle, APDS9960_CONTROL, 0x03) < 0) return -1;
    if (write_reg(handle, APDS9960_CONFIG2, 0x01) < 0) return -1;
    if (write_reg(handle, APDS9960_ENABLE, 0x03) < 0) return -1;

    return 0;
}

static int read_color_data(int handle, uint16_t *r, uint16_t *g, uint16_t *b) {
    uint8_t rl, rh, gl, gh, bl, bh;
    if (read_reg(handle, APDS9960_RDATAL, &rl) < 0) return -1;
    if (read_reg(handle, APDS9960_RDATAH, &rh) < 0) return -1;
    if (read_reg(handle, APDS9960_GDATAL, &gl) < 0) return -1;
    if (read_reg(handle, APDS9960_GDATAH, &gh) < 0) return -1;
    if (read_reg(handle, APDS9960_BDATAL, &bl) < 0) return -1;
    if (read_reg(handle, APDS9960_BDATAH, &bh) < 0) return -1;
    *r = ((uint16_t)rh << 8) | rl;
    *g = ((uint16_t)gh << 8) | gl;
    *b = ((uint16_t)bh << 8) | bl;
    return 0;
}

static int read_proximity(int handle, uint8_t *prox) {
    return read_reg(handle, APDS9960_PDATA, prox);
}

static void log_data(FILE *fp, uint16_t r, uint16_t g, uint16_t b, uint8_t prox) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, r, g, b, prox);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    if (init_apds9960(i2c_handle) < 0) {
        fprintf(stderr, "APDS9960 initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
