static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *csv_fp = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (i2c_smbus_read_byte_data(fd, reg) < 0)
        return -1;
    *val = (uint8_t)i2c_smbus_read_byte_data(fd, reg);
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    if (i2c_smbus_write_byte_data(fd, reg, val) < 0)
        return -1;
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg_lo, uint16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg_lo, &lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, reg_lo + 1, &hi) < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int init_sensor(void)
{
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                SI1182_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    uint8_t part_id = 0;
    if (i2c_read_reg8(i2c_fd, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART_ID: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "PART_ID mismatch: got 0x%02X, expected 0x%02X\n",
                part_id, EXPECTED_PART_ID);
