        fprintf(stderr, "Failed to write MEAS_RATE0: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    if (i2c_write_reg8(i2c_fd, REG_COMMAND, CMD_RESET) < 0) {
        fprintf(stderr, "Failed to reset sensor: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    usleep(10000);

    if (i2c_write_reg8(i2c_fd, REG_COMMAND, CMD_START) < 0) {
        fprintf(stderr, "Failed to start measurement: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

