    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return 1;
    }

    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        return 1;
    }

    csv_fp = fopen("heartrate.csv", "a");
    if (!csv_fp) {
        fprintf(stderr, "fopen(heartrate.csv): %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return 1;
    }

    while (running) {
        uint16_t prox = 0;
        if (read_proximity(&prox) < 0) {
            fprintf(stderr, "Warning: proximity read failed: %s\n",
                    strerror(errno));
            usleep(100000);
            continue;
        }

        float bpm = calculate_bpm(prox);
        log_data(bpm);
        usleep(100000);
    }

    if (csv_fp) {
        fclose(csv_fp);
        csv_fp = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    printf("\nExiting cleanly.\n");
    return 0;
}

