#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"
#define MEAS_TIMEOUT_MS 100

/* VL53L0X register addresses */
#define REG_SYSRANGE_START          0x00
#define REG_RESULT_INTERRUPT_STATUS 0x13
#define REG_RESULT_RANGE_STATUS     0x14
#define REG_SYSTEM_INTERRUPT_CLEAR  0x0B

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X, len %u): %s\n",
                reg, len, strerror(errno));
    }
    return rc;
}

static int init_sensor(int handle) {
    /* Verify sensor presence by reading the model ID register (0x010F) */
    int model_id = i2cReadByteData(handle, 0x010F);
    if (model_id < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X: %s\n",
                VL53L0X_ADDR, strerror(errno));
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Unexpected model ID 0x%02X (expected 0xEA)\n", model_id);
        return -1;
    }

    /* Data init: write 0x00 to SYSRANGE_START to stop any ongoing measurement */
    if (i2c_write_byte(handle, REG_SYSRANGE_START, 0x00) < 0)
        return -1;

    /* Optional: set I2C standard mode (0x00) and disable MSRC (0x00) */
    if (i2c_write_byte(handle, 0x88, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, 0x80, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, 0xFF, 0x01) < 0) return -1;
    if (i2c_write_byte(handle, 0x00, 0x00) < 0) return -1;

    return 0;
}

