#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define CH101_ADDR 0x45
#define I2C_BUS 1
#define LOG_FILE "distance_log.txt"
#define SAMPLE_INTERVAL_US 200000
#define MEASURE_DELAY_US 50000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, CH101_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_distance(int *distance_mm) {
    char cmd = 0x00;
    char buf[2];
    int rc;

    rc = i2cWriteDevice(i2c_handle, &cmd, 1);
    if (rc < 0) {
        fprintf(stderr, "I2C write error (trigger): %d\n", rc);
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    rc = i2cReadDevice(i2c_handle, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C read error: %d\n", rc);
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "Short read: got %d bytes, expected 2\n", rc);
        return -1;
    }

    *distance_mm = ((unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    return 0;
}

static int log_distance(int distance_mm) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[20];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(log_fp, "%s, %d\n", timestamp, distance_mm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("CH101 distance logger started. Press Ctrl-C to stop.\n");

    while (running) {
        int distance_mm;
        if (read_distance(&distance_mm) == 0) {
            if (log_distance(distance_mm) == 0) {
                printf("%d mm\n", distance_mm);
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_fp) fclose(log_fp);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

