#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define LED_GPIO 17
#define DISTANCE_THRESHOLD 20.0f
#define LOG_FILE "distance_log.txt"
#define POLL_DELAY_US 100000

/* ICU-20201 register addresses (16-bit registers, big-endian on bus) */
#define REG_DISTANCE_HIGH 0x00
#define REG_DISTANCE_LOW  0x01
#define REG_STATUS        0x02
#define REG_RESET         0x03

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    return i2cWriteDevice(handle, buf, 2);
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *out) {
    char reg_buf[1] = { (char)reg };
    char data[2] = {0, 0};

    if (i2cWriteDevice(handle, reg_buf, 1) < 0)
        return -1;
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int read_distance(int handle, float *distance) {
    uint16_t raw_high, raw_low;
    uint16_t status;

    if (i2c_read_reg16(handle, REG_STATUS, &status) < 0) {
        fprintf(stderr, "Error: Failed to read status register.\n");
        return -1;
    }

    if (status & 0x0001) {
        fprintf(stderr, "Warning: Sensor data not ready (status=0x%04X).\n", status);
        return -1;
    }

    if (i2c_read_reg16(handle, REG_DISTANCE_HIGH, &raw_high) < 0) {
        fprintf(stderr, "Error: Failed to read distance high byte.\n");
        return -1;
    }
    if (i2c_read_reg16(handle, REG_DISTANCE_LOW, &raw_low) < 0) {
        fprintf(stderr, "Error: Failed to read distance low byte.\n");
        return -1;
    }

    uint16_t raw_distance = (raw_high << 8) | raw_low;
    *distance = (float)raw_distance / 10.0f;
    return 0;
}

static int log_distance(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

