        fprintf(stderr, "Error: I2C open failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    if (i2c_write_reg8(g_i2c_handle, REG_RESET, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(100000);

    while (g_running) {
        float distance;
        if (read_distance(g_i2c_handle, &distance) == 0) {
            if (log_distance(distance) < 0) {
                fprintf(stderr, "Warning: Failed to log distance.\n");
            }
            control_led(LED_GPIO, distance);
        } else {
            fprintf(stderr, "Warning: Failed to read distance.\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(LED_GPIO, 0);
    i2cClose(g_i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

