/* Configuration */
#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define LED_GPIO 17
#define LOG_FILE "tof_log.txt"
#define SAMPLE_INTERVAL_US 50000 /* 50 ms */

/* ICU-20201 register addresses */
#define REG_WHO_AM_I 0x00
#define REG_DISTANCE 0x10
#define WHO_AM_I_EXPECTED 0x6A

/* Global variables for cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

/* Function prototypes */
static int init_i2c(void);
static int init_gpio(void);
static int read_distance(uint16_t *distance);
static void log_data(uint16_t distance);
static void control_led(uint16_t distance, int threshold);
static void signal_handler(int signal);
static void cleanup(void);

int main(int argc, char *argv[]) {
    int threshold = 100; /* Default threshold in mm */

    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Error: Threshold must be a positive integer.\n");
            return 1;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        fprintf(stderr, "Error: I2C initialisation failed.\n");
        gpioTerminate();
        return 1;
    }

    /* Initialize GPIO */
    if (init_gpio() != 0) {
        fprintf(stderr, "Error: GPIO initialisation failed.\n");
        cleanup();
        return 1;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to set SIGINT handler.\n");
    }

    printf("Starting distance measurements. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        uint16_t distance = 0;

        /* Read distance */
        if (read_distance(&distance) == 0) {
            /* Log data */
            log_data(distance);

            /* Control LED */
            control_led(distance, threshold);
        } else {
            fprintf(stderr, "Error: Failed to read distance.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

/* Initialize I2C communication */
static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device (handle=%d).\n", i2c_handle);
        return 1;
    }

    /* Verify sensor identity */
    int who_am_i = i2cReadByteData(i2c_handle, REG_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register (I2C error %d).\n", who_am_i);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return 1;
    }
    if (who_am_i != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X). Sensor not present?\n",
                who_am_i, WHO_AM_I_EXPECTED);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return 1;
    }

    printf("I2C initialised successfully (WHO_AM_I=0x%02X).\n", who_am_i);
    return 0;
