static void log_data(uint16_t distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s'.\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Distance: %u mm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    fclose(fp);
}

/* Control the LED based on distance */
static void control_led(uint16_t distance, int threshold) {
    if (distance < threshold) {
        gpioWrite(LED_GPIO, 1); /* Turn LED on */
    } else {
        gpioWrite(LED_GPIO, 0); /* Turn LED off */
    }
