#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define B5L_ADDR       0x50
#define INTRUSION_THRESHOLD 1000  /* mm */
#define SAMPLE_COUNT   10
#define MEAS_DELAY_MS  10
#define CYCLE_DELAY_MS 100
#define RESP_LEN       15
#define CMD_LEN        4

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void msleep(unsigned ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

/*
 * Request a distance measurement from the B5L.
 * Command frame: {0x50, 0x0A, 0x00, 0x01}
 * Response frame: 15 bytes, header[0]=0x50, distance at bytes[11:12].
 */
static int request_distance(int fd, uint16_t *distance_mm) {
    uint8_t cmd[CMD_LEN] = {0x50, 0x0A, 0x00, 0x01};
    uint8_t resp[RESP_LEN];

    if (write(fd, cmd, CMD_LEN) != CMD_LEN) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    msleep(MEAS_DELAY_MS);

    ssize_t n = read(fd, resp, RESP_LEN);
    if (n != RESP_LEN) {
        if (n < 0)
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        else
            fprintf(stderr, "I2C read short: got %zd of %d bytes\n", n, RESP_LEN);
        return -1;
    }

    if (resp[0] != 0x50) {
        fprintf(stderr, "Unexpected response header: 0x%02X\n", resp[0]);
        return -1;
    }

    *distance_mm = ((uint16_t)resp[11] << 8) | resp[12];
    return 0;
}

static float calculate_average_distance(int fd, int num_samples) {
    long sum = 0;
    int valid = 0;

    for (int i = 0; i < num_samples; i++) {
        uint16_t dist;
        if (request_distance(fd, &dist) == 0) {
            sum += dist;
            valid++;
        } else {
            fprintf(stderr, "Sample %d failed\n", i + 1);
        }
    }

    if (valid == 0)
        return -1.0f;
    return (float)sum / (float)valid;
}

static void log_intrusion(float avg_distance) {
    FILE *fp = fopen("intrusion_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s - Intrusion detected! Average distance: %.2f mm\n", ts, avg_distance);
    } else {
        fprintf(fp, "<unknown time> - Intrusion detected! Average distance: %.2f mm\n", avg_distance);
    }

    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, B5L_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", B5L_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("B5L intrusion detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float avg = calculate_average_distance(g_i2c_fd, SAMPLE_COUNT);

        if (avg < 0.0f) {
            fprintf(stderr, "All samples failed; retrying next cycle.\n");
        } else if (avg < INTRUSION_THRESHOLD) {
            log_intrusion(avg);
            printf("Intrusion detected! Average distance: %.2f mm\n", avg);
        } else {
            printf("No intrusion. Average distance: %.2f mm\n", avg);
        }

        msleep(CYCLE_DELAY_MS);
    }

    printf("\nExiting gracefully.\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return 0;
}

