#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L0X_ADDR   0x29
#define MODEL_ID_REG   0xC0
#define EXPECTED_ID    0xEE
#define SYSRANGE_START 0x00
#define RESULT_INT_ST  0x13
#define RESULT_RANGE   0x14
#define SYS_INT_CLEAR  0x0B
#define POLL_TIMEOUT_MS 100
#define LOOP_DELAY_US  500000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *out) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *out) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read word failed (reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* pigpio returns data as (high_byte << 8) | low_byte */
    *out = (uint16_t)rc;
    return 0;
}

static int init_sensor(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_byte(handle, MODEL_ID_REG, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID register\n");
        return -1;
    }
    if (model_id != EXPECTED_ID) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x%02X)\n",
                model_id, EXPECTED_ID);
        return -1;
    }
    printf("VL53L0X detected (model ID 0x%02X)\n", model_id);
    return 0;
}

static int read_distance(int handle, uint16_t *distance_mm) {
    if (i2c_write_byte(handle, SYSRANGE_START, 0x01) != 0)
        return -1;

    uint8_t int_status = 0;
    int waited = 0;
    while (waited < POLL_TIMEOUT_MS) {
        if (i2c_read_byte(handle, RESULT_INT_ST, &int_status) != 0)
            return -1;
        if (int_status & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
        waited++;
    }
    if (waited >= POLL_TIMEOUT_MS) {
        fprintf(stderr, "Timeout waiting for ranging interrupt\n");
        return -1;
    }

    if (i2c_read_word(handle, RESULT_RANGE, distance_mm) != 0)
        return -1;

    if (i2c_write_byte(handle, SYS_INT_CLEAR, 0x01) != 0)
        return -1;

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, VL53L0X_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (init_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting distance readings (Ctrl+C to stop)...\n");

    while (g_running) {
        uint16_t distance = 0;
        if (read_distance(g_i2c_handle, &distance) == 0) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s Distance: %u mm\n", timestamp, distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: distance read failed, continuing...\n");
        }
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return 0;
}

