        }
        if (irq & 0x01) {
            break;
        }
        usleep(10000); /* 10 ms */
    }

    if (!(irq & 0x01)) {
        fprintf(stderr, "Proximity data not ready (IRQ=0x%02X)\n", irq);
        return -1;
    }

    lsb = read_reg(handle, SI1182_REG_PS1_LSB);
    if (lsb < 0) {
        return -1;
    }

    msb = read_reg(handle, SI1182_REG_PS1_MSB);
    if (msb < 0) {
        return -1;
    }

    *prox = (uint16_t)((msb << 8) | lsb);
    return 0;
}

