        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(SI1182_BUS, SI1182_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                SI1182_BUS, SI1182_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed (sensor may be absent)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1182 proximity sensor ready. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t prox;
        if (read_proximity(g_i2c_handle, &prox) == 0) {
            printf("Proximity: %u\n", prox);
        } else {
            fprintf(stderr, "Failed to read proximity data\n");
        }
        usleep(500000); /* 500 ms */
    }

    printf("\nExiting...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

