#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x4C
#define DIST_REG       0x00
#define SCALE_MM       0.125f
#define POLL_MS        500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE (0x%02X) failed: %s\n",
                MLX75030_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Quick presence check: try reading the distance register. */
    uint16_t raw = 0;
    if (i2c_read_reg16(fd, DIST_REG, &raw) != 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X on %s\n",
                MLX75030_ADDR, I2C_BUS);
        goto cleanup;
    }

    printf("MLX75030 detected at 0x%02X on %s. Starting distance readings...\n",
           MLX75030_ADDR, I2C_BUS);

    struct timespec sleep_ts = { 0, POLL_MS * 1000000L };

    while (g_running) {
        uint16_t raw = 0;
        if (i2c_read_reg16(fd, DIST_REG, &raw) == 0) {
            float distance_mm = (float)raw * SCALE_MM;
            printf("Distance: %.2f mm\n", distance_mm);
            fflush(stdout);
        } else {
            fprintf(stderr, "Read failed; will retry next cycle.\n");
        }
        nanosleep(&sleep_ts, NULL);
    }

    printf("\nExiting cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

