#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// OPT3101 I2C address
#define OPT3101_ADDR 0x44

// OPT3101 Register Addresses
#define REG_DEVICE_CONFIG 0x00
#define REG_SYSTEM_CONFIG 0x01
#define REG_FRAME_CONFIG 0x02
#define REG_RESULT_CONFIG 0x03
#define REG_RESULT_READY 0x04
#define REG_DISTANCE_CH0 0x05
#define REG_AMBIENT_LIGHT 0x06
#define REG_ERROR_FLAGS 0x07

// Configuration values
#define DEVICE_CONFIG_VAL 0x0001
#define SYSTEM_CONFIG_VAL 0x0001
#define FRAME_CONFIG_VAL 0x0001
#define RESULT_CONFIG_VAL 0x0001

// Error flags
#define ERROR_FLAG_I2C 0x01
#define ERROR_FLAG_SENSOR 0x02

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t distance;
    uint16_t ambient_light;
    uint16_t error_flags;
} sensor_data_t;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, OPT3101_ADDR, 0); // Bus 1, address 0x44, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the OPT3101 sensor
int configure_sensor() {
    // Write configuration values to the sensor registers
    if (i2cWriteWordData(i2c_handle, REG_DEVICE_CONFIG, DEVICE_CONFIG_VAL) < 0) {
        fprintf(stderr, "Error writing to DEVICE_CONFIG register\n");
        return -1;
    }
    if (i2cWriteWordData(i2c_handle, REG_SYSTEM_CONFIG, SYSTEM_CONFIG_VAL) < 0) {
        fprintf(stderr, "Error writing to SYSTEM_CONFIG register\n");
        return -1;
    }
    if (i2cWriteWordData(i2c_handle, REG_FRAME_CONFIG, FRAME_CONFIG_VAL) < 0) {
        fprintf(stderr, "Error writing to FRAME_CONFIG register\n");
        return -1;
    }
    if (i2cWriteWordData(i2c_handle, REG_RESULT_CONFIG, RESULT_CONFIG_VAL) < 0) {
        fprintf(stderr, "Error writing to RESULT_CONFIG register\n");
        return -1;
    }
    return 0;
}

// Read data from the OPT3101 sensor
int read_sensor_data(sensor_data_t *data) {
    int result;

    // Read distance data from channel 0
    result = i2cReadWordData(i2c_handle, REG_DISTANCE_CH0);
    if (result < 0) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        data->distance = 0;
        data->error_flags |= ERROR_FLAG_I2C;
        return -1;
    }
    data->distance = (uint16_t)result;

    // Read ambient light data
    result = i2cReadWordData(i2c_handle, REG_AMBIENT_LIGHT);
    if (result < 0) {
        fprintf(stderr, "Error reading ambient light data: %d\n", result);
        data->ambient_light = 0;
        data->error_flags |= ERROR_FLAG_I2C;
        return -1;
    }
    data->ambient_light = (uint16_t)result;

    // Read error flags
    result = i2cReadWordData(i2c_handle, REG_ERROR_FLAGS);
    if (result < 0) {
        fprintf(stderr, "Error reading error flags: %d\n", result);
        data->error_flags |= ERROR_FLAG_I2C;
        return -1;
    }
    data->error_flags = (uint16_t)result;

    return 0;
}

// Log the sensor data to the console
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Distance: %u mm, Ambient Light: %u, Error Flags: 0x%04X\n",
           timestamp, data.distance, data.ambient_light, data.error_flags);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log the data
