/*
 * HC-SR04 Ultrasonic Distance Sensor - Raspberry Pi 3 Model B+
 * Library: pigpio (modern, actively maintained)
 * Trigger: GPIO 17 (BCM)
 * Echo:    GPIO 18 (BCM)
 *
 * NOTE: The HC-SR04 module is 5V tolerant and requires a 1k Ohm resistor
 *       in series with the echo pin to protect the 3.3V Pi GPIO.
 *
 * NOTE: gpioTick() returns a monotonically increasing microsecond counter
 *       (32-bit, wraps every ~71.6 minutes). The subtraction (b - a)
 *       handles the wrap correctly for unsigned arithmetic in C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define TRIGGER_PULSE_US  10          /* HC-SR04 trigger pulse width */
#define ECHO_TIMEOUT_US   200000      /* 200 ms max echo wait        */
#define SETTLE_DELAY_US   50000       /* 50 ms settle time           */
#define LOOP_DELAY_US     1000000     /* 1 s between readings        */
#define MAX_PULSE_US      38000       /* HC-SR04 max range ~5 m      */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (SIGINT / SIGTERM)            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Send a 10 us trigger pulse to the HC-SR04                           */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, PI_HIGH);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, PI_LOW);
}

/* ------------------------------------------------------------------ */
/* Measure the echo pulse width in microseconds                        */
/* Returns:                                                            */
/*   > 0  : pulse duration in microseconds                             */
/*   -1   : timeout waiting for echo rising edge                       */
/*   -2   : timeout waiting for echo falling edge                      */
/*   -3   : invalid pulse duration (<= 0 or > MAX_PULSE_US)            */
/* ------------------------------------------------------------------ */
static long measure_echo_pulse(void)
{
    uint32_t start_tick = 0;
    uint32_t end_tick   = 0;
    uint32_t timeout_start;

    /* Wait for echo rising edge (start of pulse) */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == PI_LOW) {
        if ((gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            return -1;  /* echo never went high */
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (end of pulse) */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == PI_HIGH) {
        if ((gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            return -2;  /* echo stuck high (sensor absent or wiring fault) */
        }
    }
    end_tick = gpioTick();

    long pulse_us = (long)(end_tick - start_tick);

    if (pulse_us <= 0 || pulse_us > MAX_PULSE_US) {
        return -3;  /* out of valid range */
    }

    return pulse_us;
}

/* ------------------------------------------------------------------ */
/* Convert pulse duration (us) to distance (cm)                        */
/* Formula: distance_cm = (pulse_us * 0.0343) / 2                      */
/* ------------------------------------------------------------------ */
static float calculate_distance(long pulse_us)
{
    return (float)pulse_us * 0.0343f / 2.0f;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        fprintf(stderr, "       Ensure pigpiod is not running and you have root privileges.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, PI_LOW);
    gpioDelay(SETTLE_DELAY_US);

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance sensor started.\n");
    printf("Trigger: GPIO %d | Echo: GPIO %d\n", TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main measurement loop */
    while (g_running) {
        trigger_sensor();
        gpioDelay(SETTLE_DELAY_US);  /* let echo settle */

        long pulse_us = measure_echo_pulse();

        if (pulse_us > 0) {
            float distance = calculate_distance(pulse_us);
            time_t now = time(NULL);
            char time_buf[32];
            strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S",
                     localtime(&now));
            printf("[%s] Distance: %.2f cm (pulse: %ld us)\n",
                   time_buf, distance, pulse_us);
        } else {
            time_t now = time(NULL);
            char time_buf[32];
            strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S",
                     localtime(&now));
            fprintf(stderr, "[%s] Error: ", time_buf);
            if (pulse_us == -1) {
                fprintf(stderr, "Timeout waiting for echo rising edge.\n");
            } else if (pulse_us == -2) {
                fprintf(stderr, "Timeout waiting for echo falling edge.\n");
            } else if (pulse_us == -3) {
                fprintf(stderr, "Invalid pulse duration (out of range).\n");
            }
        }

        /* Sleep 1 s between readings; check g_running every 100 ms */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    /* Cleanup */
    gpioWrite(TRIGGER_PIN, PI_LOW);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

