#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define UART_PORT "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_LED 17
#define INTRUSION_THRESHOLD 1.0f
#define RANGE_RESOLUTION 0.0486f
#define NUM_RANGE_BINS 64
#define DATA_FRAME_SIZE (8 + (NUM_RANGE_BINS * 2))
#define MAGIC_WORD_SIZE 8
#define MAGIC_WORD_BYTE 0x07

static const uint8_t MAGIC_WORD[MAGIC_WORD_SIZE] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};

static volatile sig_atomic_t program_running = 1;
static int uart_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_uart(const char *port, speed_t baud) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_uart_frame(int fd, uint8_t *buffer, size_t size) {
    size_t total_read = 0;
    while (total_read < size) {
        ssize_t bytes = read(fd, buffer + total_read, size - total_read);
        if (bytes < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            perror("Error reading from UART");
            return -1;
        } else if (bytes == 0) {
            return 0;
        }
        total_read += (size_t)bytes;
    }
    return (int)total_read;
}

static int find_magic_word(const uint8_t *data, size_t len, size_t *offset) {
    for (size_t i = 0; i <= len - MAGIC_WORD_SIZE; i++) {
        if (memcmp(data + i, MAGIC_WORD, MAGIC_WORD_SIZE) == 0) {
            *offset = i;
            return 0;
        }
    }
    return -1;
}

static float process_range_profile(const uint8_t *data) {
    int16_t range_profile[NUM_RANGE_BINS];
    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        range_profile[i] = (int16_t)((data[8 + (i * 2)] << 8) | data[9 + (i * 2)]);
    }

    float min_distance = 100.0f;
    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        float distance = (float)range_profile[i] * RANGE_RESOLUTION;
        if (distance > 0.0f && distance < min_distance) {
            min_distance = distance;
        }
    }
    return min_distance;
}

static void trigger_alert(float distance) {
    printf("Intrusion detected! Distance: %.2f meters\n", distance);
    gpioWrite(GPIO_LED, 1);
    gpioDelay(2000000);
    gpioWrite(GPIO_LED, 0);
}

static void log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_PORT, BAUD_RATE);
    if (uart_fd == -1) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    uint8_t buffer[DATA_FRAME_SIZE];
    uint8_t read_buffer[256];

    printf("Starting intrusion detection...\n");

    while (program_running) {
        int bytes_read = read_uart_frame(uart_fd, read_buffer, sizeof(read_buffer));
        if (bytes_read < 0) {
            fprintf(stderr, "UART read error, exiting.\n");
            break;
        } else if (bytes_read == 0) {
            continue;
        }

        size_t magic_offset = 0;
        if (find_magic_word(read_buffer, (size_t)bytes_read, &magic_offset) != 0) {
            continue;
