#include <gpiod.h>

#define SENSOR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "obstacle_log.txt"
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, message) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("gpiod_chip_get_line sensor");
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line buzzer");
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor_line, "e18-d80nk-sensor") < 0) {
        perror("gpiod_line_request_input sensor");
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer_line, "e18-d80nk-buzzer", 0) < 0) {
        perror("gpiod_line_request_output buzzer");
        goto cleanup;
    }

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    int last_state = -1;

    while (program_running) {
        int val = gpiod_line_get_value(sensor_line);
        if (val < 0) {
            perror("gpiod_line_get_value sensor");
            log_event("Error reading sensor value");
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (val != last_state) {
            if (val == 0) {
                printf("Obstacle detected!\n");
                if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                    perror("gpiod_line_set_value buzzer on");
                    log_event("Error activating buzzer");
                } else {
                    log_event("Obstacle detected");
                }
            } else {
                printf("Obstacle cleared.\n");
                if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                    perror("gpiod_line_set_value buzzer off");
                    log_event("Error deactivating buzzer");
                } else {
                    log_event("Obstacle cleared");
                }
            }
            last_state = val;
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

