#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x69
#define DIST_HIGH_REG  0x31
#define DIST_LOW_REG   0x32
#define ALERT_PIN      17
#define DIST_THRESHOLD 10.0f
#define LOG_FILE       "distance_log.txt"
#define SAMPLE_US      100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_distance(int handle, float *distance) {
    int high = i2cReadByteData(handle, DIST_HIGH_REG);
    if (high < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", DIST_HIGH_REG, high);
        return -1;
    }
    int low = i2cReadByteData(handle, DIST_LOW_REG);
    if (low < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", DIST_LOW_REG, low);
        return -1;
    }
    uint16_t raw = ((uint16_t)high << 8) | (uint16_t)low;
    *distance = (float)raw;
    return 0;
}

static int log_distance(FILE *fp, float distance) {
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time");
        return -1;
    }
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s, Distance: %.2f cm\n", ts, distance) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static void alert_callback(int gpio, int level, uint32_t tick) {
    (void)gpio; (void)tick;
    if (level == 1) {
        printf("Alert triggered!\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", ALERT_PIN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(ALERT_PIN, 0);

    if (gpioSetAlertFunc(ALERT_PIN, alert_callback) != 0) {
        fprintf(stderr, "gpioSetAlertFunc failed for pin %d\n", ALERT_PIN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting distance monitoring (Ctrl+C to stop)...\n");

    while (g_running) {
        float distance;
        if (read_distance(g_i2c_handle, &distance) == 0) {
            if (log_distance(fp, distance) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
            if (distance < DIST_THRESHOLD) {
                gpioWrite(ALERT_PIN, 1);
                gpioDelay(500000);
                gpioWrite(ALERT_PIN, 0);
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(ALERT_PIN, 0);
    if (fclose(fp) != 0) {
        perror("fclose");
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return 0;
}

