    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", ALERT_PIN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(ALERT_PIN, 0);

    if (gpioSetAlertFunc(ALERT_PIN, alert_callback) != 0) {
        fprintf(stderr, "gpioSetAlertFunc failed for pin %d\n", ALERT_PIN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
