    }

    printf("\nShutting down...\n");
    gpioWrite(ALERT_PIN, 0);
    if (fclose(fp) != 0) {
        perror("fclose");
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return 0;
}

