#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define LOG_FILE "distance_log.csv"

#define REG_MODEL_ID 0x010F
#define EXPECTED_MODEL_ID 0xEA
#define REG_SOFT_RESET 0x0000
#define REG_SYSTEM_MODE_START 0x007
#define REG_SYSRANGE_START 0x000
#define REG_RESULT_INT_STATUS 0x013
#define REG_RESULT_RANGE_STATUS 0x078
#define REG_SYSTEM_INT_CLEAR 0x014

#define STOP_THRESHOLD 300
#define APPROACH_THRESHOLD 600
#define SLOW_THRESHOLD 1200

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(uint8_t reg_hi, uint8_t reg_lo, uint8_t value) {
    char buf[3] = { (char)reg_hi, (char)reg_lo, (char)value };
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int i2c_read_reg16(uint8_t reg_hi, uint8_t reg_lo, uint8_t *buf, uint32_t len) {
    char reg[2] = { (char)reg_hi, (char)reg_lo };
    if (i2cWriteDevice(i2c_handle, reg, 2) < 0) return -1;
    return i2cReadDevice(i2c_handle, (char *)buf, len);
}

static int vl53l1x_write8(uint16_t reg, uint8_t value) {
    return i2c_write_reg16((reg >> 8) & 0xFF, reg & 0xFF, value);
}

static int vl53l1x_read8(uint16_t reg, uint8_t *value) {
    return i2c_read_reg16((reg >> 8) & 0xFF, reg & 0xFF, value, 1);
}

static int vl53l1x_read16(uint16_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (i2c_read_reg16((reg >> 8) & 0xFF, reg & 0xFF, buf, 2) < 0) return -1;
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int init_vl53l1x(void) {
    uint8_t model_id = 0;
    if (vl53l1x_read8(REG_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error: Failed to read model ID register.\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: Unexpected model ID 0x%02X (expected 0x%02X).\n", model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    if (vl53l1x_write8(REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset.\n");
        return -1;
    }
    gpioDelay(2000);

    if (vl53l1x_write8(REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }

    uint8_t status = 0;
    int timeout = 100;
    do {
        if (vl53l1x_read8(REG_SYSRANGE_START, &status) < 0) {
            fprintf(stderr, "Error: Failed to read ranging status.\n");
            return -1;
        }
        if (status & 0x01) break;
        gpioDelay(1000);
        timeout--;
    } while (timeout > 0);

    if (timeout == 0) {
        fprintf(stderr, "Error: Ranging start timeout.\n");
        return -1;
    }

    return 0;
}

static int read_distance(uint16_t *distance) {
    uint8_t int_status = 0;
    if (vl53l1x_read8(REG_RESULT_INT_STATUS, &int_status) < 0) return -1;
    if (!(int_status & 0x01)) return 1;

    uint16_t range = 0;
    if (vl53l1x_read16(REG_RESULT_RANGE_STATUS + 10, &range) < 0) return -1;

    if (vl53l1x_write8(REG_SYSTEM_INT_CLEAR, 0x01) < 0) return -1;

    *distance = range;
    return 0;
}

static void log_distance(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u\n", timestamp, distance);
    fflush(log_file);
}

static void print_guidance(uint16_t distance) {
    if (distance < STOP_THRESHOLD) {
        printf("Parking Guidance: STOP\n");
    } else if (distance < APPROACH_THRESHOLD) {
        printf("Parking Guidance: APPROACH\n");
    } else if (distance < SLOW_THRESHOLD) {
        printf("Parking Guidance: SLOW\n");
    } else {
        printf("Parking Guidance: CLEAR\n");
    }
    fflush(stdout);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_vl53l1x() < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
        fflush(log_file);
    }

    printf("Parking Assistance System started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance = 0;
        int rc = read_distance(&distance);
        if (rc == 0) {
            log_distance(distance);
            print_guidance(distance);
        } else if (rc < 0) {
            fprintf(stderr, "Error: I2C read error.\n");
        }
        gpioDelay(100000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

