                reg, attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* Read a 16-bit register address, then a 16-bit data value. */
static int ch201_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char addr_buf[2];
    char data_buf[2];

    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, addr_buf, 2);
        if (rc != 0) {
            fprintf(stderr, "I2C write (addr) for reg 0x%04X failed (attempt %d/%d): rc=%d\n",
                    reg, attempt + 1, MAX_RETRIES, rc);
            if (attempt < MAX_RETRIES - 1)
                gpioDelay(RETRY_DELAY_US);
            continue;
        }

        rc = i2cReadDevice(handle, data_buf, 2);
        if (rc == 2) {
            *out = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
            return 0;
        }
        fprintf(stderr, "I2C read from reg 0x%04X failed (attempt %d/%d): rc=%d\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int ch201_init(int handle)
{
    uint16_t product_id = 0;
    if (ch201_read_reg16(handle, REG_PRODUCT_ID, &product_id) != 0) {
        fprintf(stderr, "Failed to read CH201 product ID — sensor may be absent or bus error.\n");
        return -1;
    }
    printf("CH201 detected (product ID: 0x%04X)\n", product_id);
    return 0;
}

static int ch201_read_distance(int handle, uint16_t *distance_mm)
{
    return ch201_read_reg16(handle, REG_DISTANCE, distance_mm);
}

static float distance_to_frequency(uint16_t distance_mm)
{
    if (distance_mm <= 50)
        return 10.0f;
    if (distance_mm >= 500)
        return 1.0f;
    return 10.0f - (float)(distance_mm - 50) * 9.0f / 450.0f;
}

static void blink_led(int gpio, float frequency_hz, uint32_t half_period_us)
{
    if (frequency_hz <= 0.0f)
        return;

    uint32_t on_us  = half_period_us;
    uint32_t off_us = (uint32_t)(500000.0f / frequency_hz) - on_us;

    if (gpioWrite(gpio, 1) != 0)
        fprintf(stderr, "Warning: failed to set LED GPIO %d high\n", gpio);
    gpioDelay(on_us);
    if (gpioWrite(gpio, 0) != 0)
        fprintf(stderr, "Warning: failed to set LED GPIO %d low\n", gpio);
    gpioDelay(off_us);
}

static void log_data(uint16_t distance_mm, float frequency_hz)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("%s - Distance: %u mm, Blink Frequency: %.2f Hz\n",
           timestamp, distance_mm, frequency_hz);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: handle=%d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ch201_init(g_i2c_handle) != 0) {
        fprintf(stderr, "CH201 initialisation failed — check wiring and sensor presence.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    printf("CH201 distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance_mm = 0;
        if (ch201_read_distance(g_i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "Failed to read distance — continuing.\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float frequency_hz = distance_to_frequency(distance_mm);
        uint32_t half_period_us = (uint32_t)(500000.0f / (2.0f * frequency_hz));

        blink_led(LED_GPIO, frequency_hz, half_period_us);
        log_data(distance_mm, frequency_hz);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

