        return -1;
    }
    return 0;
}

static int read_distance(uint16_t *distance_cm) {
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteByte(i2c_handle, MEASURE_CMD) < 0) {
