#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define POLL_DELAY_US 10000   /* 10 ms */
#define DEBOUNCE_US   50000   /* 50 ms */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Read a sensor with debounce.
 * Returns 0 (obstacle detected / LOW) or 1 (clear / HIGH).
 * Returns -1 on read error.
 */
static int read_sensor(int gpio)
{
    int v = gpioRead(gpio);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", gpio, pigpio_error(v));
        return -1;
    }

    gpioDelay(DEBOUNCE_US);

    v = gpioRead(gpio);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", gpio, pigpio_error(v));
        return -1;
    }
    return v;
}

/*
 * Log a state transition with an ISO-8601 UTC timestamp.
 * Returns 0 on success, -1 on error.
 */
static int log_event(int sensor_id, const char *event)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Sensor %d - %s\n", ts, sensor_id, event) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    int init_ret = gpioInitialise();
    if (init_ret < 0) {
        fprintf(stderr, "gpioInitialise() failed: %s\n", pigpio_error(init_ret));
        return EXIT_FAILURE;
    }

    /* --- Configure sensor GPIOs as inputs --- */
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file in append mode --- */
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "fopen(\"proximity_log.txt\") failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    /* --- Track previous states to detect transitions --- */
    int prev1 = read_sensor(SENSOR_1_GPIO);
    int prev2 = read_sensor(SENSOR_2_GPIO);

    if (prev1 < 0 || prev2 < 0) {
        fprintf(stderr, "Initial sensor read failed.\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Log initial states */
    if (log_event(1, prev1 == 0 ? "DETECTED" : "CLEARED") != 0) {
        fprintf(stderr, "Failed to log initial state for sensor 1.\n");
    }
    if (log_event(2, prev2 == 0 ? "DETECTED" : "CLEARED") != 0) {
        fprintf(stderr, "Failed to log initial state for sensor 2.\n");
    }

    /* --- Main polling loop --- */
    while (running) {
        int cur1 = read_sensor(SENSOR_1_GPIO);
        int cur2 = read_sensor(SENSOR_2_GPIO);

        if (cur1 < 0 || cur2 < 0) {
            fprintf(stderr, "Sensor read error, continuing...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (cur1 != prev1) {
            if (log_event(1, cur1 == 0 ? "DETECTED" : "CLEARED") != 0) {
                fprintf(stderr, "Failed to log event for sensor 1.\n");
            }
            prev1 = cur1;
        }

        if (cur2 != prev2) {
            if (log_event(2, cur2 == 0 ? "DETECTED" : "CLEARED") != 0) {
                fprintf(stderr, "Failed to log event for sensor 2.\n");
            }
            prev2 = cur2;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Graceful cleanup --- */
    printf("\nShutting down...\n");

    if (fclose(log_file) != 0) {
        fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
    }
    log_file = NULL;

    gpioTerminate();
    return EXIT_SUCCESS;
}

