#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x49
#define CSV_FILE       "distance_log.csv"
#define SAMPLE_MS      500
#define MEAS_TIMEOUT_MS 50

/* CH-101 register addresses */
#define REG_MEAS_TRIGGER 0x04
#define REG_MEAS_STATUS  0x06
#define REG_DIST_HIGH    0x08
#define REG_DIST_LOW     0x09

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv   = NULL;

static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to an 8-bit register using a combined write-then-read transaction. */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, value, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* Read one byte from an 8-bit register using a combined write-then-read transaction. */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* Trigger a single measurement and wait for data-ready. Returns distance in mm or -1. */
static int ch101_read_distance(int fd)
{
    if (i2c_write_reg8(fd, REG_MEAS_TRIGGER, 0x01) < 0)
        return -1;

    for (int elapsed = 0; elapsed < MEAS_TIMEOUT_MS; elapsed += 5) {
        uint8_t status = 0;
        if (i2c_read_reg8(fd, REG_MEAS_STATUS, &status) < 0)
            return -1;
        if (status & 0x01)
            break;
        usleep(5000);
    }

    uint8_t hi = 0, lo = 0;
    if (i2c_read_reg8(fd, REG_DIST_HIGH, &hi) < 0)
        return -1;
    if (i2c_read_reg8(fd, REG_DIST_LOW, &lo) < 0)
        return -1;

    return (hi << 8) | lo;
}

static void log_data(FILE *fp, int distance)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%d\n", ts, distance);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                CH101_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_csv = fopen(CSV_FILE, "a");
    if (!g_csv) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_csv) == 0)
        fprintf(g_csv, "timestamp,distance_mm\n");

    while (g_running) {
        int distance = ch101_read_distance(g_i2c_fd);
        if (distance >= 0) {
            log_data(g_csv, distance);
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Sensor read failed; skipping sample.\n");
        }
        usleep(SAMPLE_MS * 1000);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (g_csv) {
        fflush(g_csv);
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

