#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x4C
#define MEASUREMENT_REG 0x00
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_distance(int handle, int *distance) {
    char buf[2];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(handle, MEASUREMENT_REG, buf, 2);
        if (result == 2) {
            *distance = (buf[0] << 8) | buf[1];
            return 0;
        }
        fprintf(stderr, "I2C read error (attempt %d/%d): %s\n", retries + 1, MAX_RETRIES, strerror(errno));
        retries++;
        if (retries < MAX_RETRIES) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    return -1;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d, address 0x%02X: %s\n", I2C_BUS, MLX75030_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("MLX75030 Distance Sensor Reader\n");
    printf("I2C Bus: %d, Address: 0x%02X\n", I2C_BUS, MLX75030_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        int distance;
        struct timespec ts;
        char timestamp[32];

        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        snprintf(timestamp, sizeof(timestamp), "%ld.%03ld", ts.tv_sec, ts.tv_nsec / 1000000);

        if (read_distance(i2c_handle, &distance) == 0) {
            printf("[%s] Distance: %d mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "[%s] Failed to read distance after %d retries.\n", timestamp, MAX_RETRIES);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

