#include <string.h>

/* VL53L4CX I2C default address (7-bit) */
#define VL53L4CX_ADDR 0x29

/* VL53L4CX register addresses (16-bit, sent MSB first) */
#define VL53L4CX_REG_SOFT_RESET       0x7FFF
#define VL53L4CX_REG_SYSTEM_START     0x0009
#define VL53L4CX_REG_INT_STATUS       0x0046
#define VL53L4CX_REG_DISTANCE_HIGH    0x0096
#define VL53L4CX_REG_DISTANCE_LOW     0x0097

#define I2C_BUS 1
#define POLL_DELAY_US 500000  /* 500 ms */
#define MAX_INIT_RETRIES 10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address followed by a data byte             */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int vl53l4cx_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register address and return the data byte             */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int vl53l4cx_read_reg8(int handle, uint16_t reg, uint8_t *value)
{
    char addr_buf[2];
    char data_buf[1];

    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr_buf, 2) != 2) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *value = (uint8_t)data_buf[0];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the VL53L4CX sensor                                      */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int vl53l4cx_init(int handle)
{
    int retries = 0;

    /* Soft reset: write 0x00 to register 0x7FFF */
    if (vl53l4cx_write_reg8(handle, VL53L4CX_REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Soft reset write failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Start ranging: write 0x00 to register 0x0009 */
    if (vl53l4cx_write_reg8(handle, VL53L4CX_REG_SYSTEM_START, 0x00) != 0) {
        fprintf(stderr, "System start write failed\n");
        return -1;
    }

    /* Allow sensor to settle after ranging begins */
    gpioDelay(10000); /* 10 ms */

    /* Verify sensor is responding by reading back the start register */
    uint8_t start_val = 0;
    while (retries < MAX_INIT_RETRIES) {
        if (vl53l4cx_read_reg8(handle, VL53L4CX_REG_SYSTEM_START, &start_val) == 0) {
            break;
        }
        fprintf(stderr, "Init read failed, retrying (%d/%d)...\n",
                retries + 1, MAX_INIT_RETRIES);
        gpioDelay(10000);
        retries++;
    }

    if (retries >= MAX_INIT_RETRIES) {
        fprintf(stderr, "Sensor not responding after %d retries\n", MAX_INIT_RETRIES);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance from the VL53L4CX sensor                              */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int vl53l4cx_read_distance(int handle, uint16_t *distance)
{
    uint8_t int_status = 0;
    uint8_t dist_high = 0;
    uint8_t dist_low  = 0;

    /* Poll interrupt status register (bit 0 = new data ready) */
    if (vl53l4cx_read_reg8(handle, VL53L4CX_REG_INT_STATUS, &int_status) != 0) {
        return -1;
    }

    if ((int_status & 0x01) == 0) {
        /* No new data ready yet */
        return 1;
    }

    /* Read distance: high byte at 0x0096, low byte at 0x0097 */
    if (vl53l4cx_read_reg8(handle, VL53L4CX_REG_DISTANCE_HIGH, &dist_high) != 0) {
        return -1;
    }
    if (vl53l4cx_read_reg8(handle, VL53L4CX_REG_DISTANCE_LOW, &dist_low) != 0) {
        return -1;
    }

    *distance = ((uint16_t)dist_high << 8) | dist_low;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log distance with microsecond timestamp                             */
/* ------------------------------------------------------------------ */
static void log_distance(uint16_t distance)
{
    struct timeval tv;
    struct tm tm_info;
    char timestamp[40];

    gettimeofday(&tv, NULL);
    localtime_r(&tv.tv_sec, &tm_info);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%06ld", (long)tv.tv_usec);

    printf("Timestamp: %s, Distance: %u mm\n", timestamp, distance);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x29 */
