#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   17

#define SPEED_OF_SOUND 343.0
#define MIN_DISTANCE   2.0
#define MAX_DISTANCE   400.0
#define MIN_ANGLE      -90
#define MAX_ANGLE      90
#define TIMEOUT_US     50000
#define LOG_FILE       "sensor_data.log"
#define LOOP_DELAY_US  200000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(float distance, int angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm, Angle: %d degrees\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance, angle);
    }
    fclose(fp);
}

static float measure_distance(void) {
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1.0;
    gpioDelay(2);
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1.0;
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1.0;

    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline = gpioTick() + TIMEOUT_US;

    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() > deadline) return -1.0;
    }
    start_tick = gpioTick();

    deadline = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() > deadline) return -1.0;
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (diff / 1000000.0) * SPEED_OF_SOUND / 2.0;
    return distance;
}

static int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d out of range [%d, %d]\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    int pulse_width = 1000 + (angle * 1000) / 180;
