#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <mqueue.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100
#define POLL_DELAY_US 50000
#define MAX_RETRIES 3

#define REG_SOFT_RESET 0x0000
#define REG_MODEL_ID 0x010F
#define REG_SYSTEM_START 0x0080
#define REG_SYSTEM_INTERRUPT 0x0089
#define REG_RESULT_DISTANCE 0x0096
#define REG_TIMING_BUDGET 0x0080

static int i2c_handle = -1;
static mqd_t mq = (mqd_t)-1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(uint8_t reg_hi, uint8_t reg_lo, uint8_t value) {
    char buf[3] = {reg_hi, reg_lo, value};
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int i2c_read_reg16(uint8_t reg_hi, uint8_t reg_lo, uint8_t *buf, uint8_t len) {
    char reg[2] = {reg_hi, reg_lo};
    if (i2cWriteDevice(i2c_handle, reg, 2) < 0) return -1;
    return i2cReadDevice(i2c_handle, (char *)buf, len);
}

static int vl53l1x_write8(uint16_t reg, uint8_t value) {
    return i2c_write_reg16((reg >> 8) & 0xFF, reg & 0xFF, value);
}

static int vl53l1x_read8(uint16_t reg, uint8_t *value) {
    return i2c_read_reg16((reg >> 8) & 0xFF, reg & 0xFF, value, 1);
}

static int vl53l1x_read16(uint16_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (i2c_read_reg16((reg >> 8) & 0xFF, reg & 0xFF, buf, 2) < 0) return -1;
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

static int init_vl53l1x(void) {
    uint8_t model_id = 0;
    if (vl53l1x_read8(REG_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error: Failed to read model ID (I2C error).\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X (expected 0xEA).\n", model_id);
        return -1;
    }
    printf("VL53L1X detected (Model ID: 0x%02X).\n", model_id);

    if (vl53l1x_write8(REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Software reset failed.\n");
        return -1;
    }
    gpioDelay(1000);
    if (vl53l1x_write8(REG_SOFT_RESET, 0x01) < 0) {
        fprintf(stderr, "Error: Software reset release failed.\n");
        return -1;
    }
    gpioDelay(1000);

    if (vl53l1x_write8(REG_TIMING_BUDGET, 0x32) < 0) {
        fprintf(stderr, "Error: Failed to set timing budget.\n");
        return -1;
    }
    printf("VL53L1X initialized successfully.\n");
    return 0;
}

static int read_distance(uint16_t *distance) {
    uint8_t int_status = 0;
    if (vl53l1x_read8(REG_SYSTEM_INTERRUPT, &int_status) < 0) return -1;
    if (!(int_status & 0x01)) return 1;

    if (vl53l1x_read16(REG_RESULT_DISTANCE, distance) < 0) return -1;

    if (vl53l1x_write8(REG_SYSTEM_INTERRUPT, 0x01) < 0) return -1;
    return 0;
}

static void control_buzzer(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_GPIO, 1);
        gpioDelay(100000);
        gpioWrite(BUZZER_GPIO, 0);
    }
}

static void log_distance(uint16_t distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[32];
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    char message[128];
    snprintf(message, sizeof(message), "%s, Distance: %u mm", timestamp, distance);

    if (mq_send(mq, message, strlen(message) + 1, 0) == -1) {
        perror("mq_send failed");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_write8(REG_SYSTEM_START, 0x01) < 0) {
        fprintf(stderr, "Error starting ranging.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    struct mq_attr attr;
    attr.mq_flags = 0;
    attr.mq_maxmsg = 10;
    attr.mq_msgsize = 128;
    attr.mq_curmsgs = 0;
    mq = mq_open("/distance_queue", O_CREAT | O_RDWR, 0666, &attr);
    if (mq == (mqd_t)-1) {
        perror("mq_open failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting distance monitoring...\n");
    while (running) {
        uint16_t distance = 0;
        int ret = read_distance(&distance);
        if (ret == 0) {
            control_buzzer(distance);
            log_distance(distance);
        } else if (ret < 0) {
            fprintf(stderr, "I2C read error during ranging.\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nCleaning up...\n");
    if (mq != (mqd_t)-1) mq_close(mq);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
    return 0;
}

