#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define MIN_DISTANCE_CM         2.0
#define MAX_DISTANCE_CM         400.0
#define THRESHOLD_DISTANCE_CM   30.0
#define TIMEOUT_US              30000   /* 30 ms max echo wait */
#define POLL_DELAY_US           100000  /* 100 ms display interval */
#define TRIGGER_PULSE_US        10

static volatile sig_atomic_t g_running = 1;

/* Shared state between alert callback and main thread */
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile int      g_echo_state = 0;   /* 0=idle, 1=rising seen, 2=falling seen */
static volatile int      g_reading_valid = 0;
static volatile int      g_sensor_timeout = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * pigpio alert callback for the echo pin.
 * level: 0 = LOW, 1 = HIGH, 2 = watchdog timeout (we ignore timeouts here).
 * tick:  32-bit microsecond counter that wraps every ~71.6 min.
 */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_start_tick  = tick;
        g_echo_state  = 1;
        g_sensor_timeout = 0;
    } else if (level == 0 && g_echo_state == 1) {
        /* Falling edge: echo pulse ends */
        g_end_tick    = tick;
        g_echo_state  = 2;
        g_reading_valid = 1;
    }
    /* level == 2 (timeout) is ignored here; handled in main loop */
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/*
 * Compute distance from the pigpio tick difference, handling 32-bit wraparound.
 * Returns -1.0 on invalid reading.
 */
static double calculate_distance(uint32_t start, uint32_t end)
{
    uint32_t diff;
    if (end >= start) {
        diff = end - start;
    } else {
        diff = (0xFFFFFFFFu - start) + end + 1u;
    }

    double time_s = (double)diff / 1000000.0;
    double distance = (time_s * SPEED_OF_SOUND_CM_PER_S) / 2.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1.0;
    }
    return distance;
}

static void control_buzzer(double distance)
{
    if (distance >= 0.0 && distance < THRESHOLD_DISTANCE_CM) {
        gpioWrite(BUZZER_PIN, 1);
    } else {
        gpioWrite(BUZZER_PIN, 0);
    }
}

