/*
 * HC-SR04 Ultrasonic Distance Measurement on Raspberry Pi 4 Model B
 * Library: pigpio (modern API, no wiringPi)
 *
 * Wiring:
 *   TRIG -> GPIO 23 (physical pin 16, BCM)
 *   ECHO -> GPIO 24 (physical pin 18, BCM) via 5V->3.3V voltage divider
 *
 * NOTE: The HC-SR04 ECHO output is 5V. A voltage divider (e.g., 1k/2k
 * resistor pair) or a logic-level converter (e.g., 74HC4060) is REQUIRED
 * to bring the signal within the Pi's 3.3V input tolerance.
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24

#define TRIGGER_PULSE_US 10          /* HC-SR04 trigger pulse width (us) */
#define MEASURE_PERIOD_US 200000     /* 5 Hz measurement rate (us)       */
#define ECHO_TIMEOUT_US   60000      /* 60 ms max echo wait (us)          */
#define MIN_PULSE_US      100        /* reject noise below 100 us         */
#define MAX_PULSE_US      30000      /* reject timeout above 30000 us     */
#define SPEED_OF_SOUND_CM_PER_US 0.0343  /* 343 m/s in cm/us, round-trip     */

/* ------------------------------------------------------------------ */
/* Shared state between callback and main thread                       */
/* ------------------------------------------------------------------ */
static volatile uint32_t g_rising_tick  = 0;
static volatile uint32_t g_falling_tick = 0;
static volatile bool     g_echo_seen     = false;

static FILE *g_log_file = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback for ECHO pin edge transitions                 */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_rising_tick  = tick;
        g_echo_seen    = false;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        g_falling_tick = tick;
        g_echo_seen    = true;
    }
    /* level == 2 indicates a watchdog timeout; ignored here */
}

/* ------------------------------------------------------------------ */
/* Compute (b - a) with 32-bit tick wraparound handling                */
/* ------------------------------------------------------------------ */
static uint32_t tick_diff(uint32_t a, uint32_t b)
{
    return b - a;  /* correct for unsigned wraparound */
}

/* ------------------------------------------------------------------ */
/* Trigger a 10 us pulse on the TRIG pin                               */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Log a reading with an ISO 8601 timestamp                            */
/* ------------------------------------------------------------------ */
static void log_reading(float distance_cm, bool valid)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    }

    if (valid) {
        printf("[%s] Distance: %.2f cm\n", ts, distance_cm);
        fprintf(g_log_file, "%s,%.2f\n", ts, distance_cm);
    } else {
        printf("[%s] Invalid reading (timeout or out of range)\n", ts);
        fprintf(g_log_file, "%s,INVALID\n", ts);
    }
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on ECHO_PIN %d.\n", ECHO_PIN);
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000);  /* 1 ms settle */

    /* ---- Register alert callback ---- */
    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) != 0) {
        fprintf(stderr, "Error: failed to register alert on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("distance_log.txt", "a");
    if (g_log_file == NULL) {
        perror("Error opening distance_log.txt");
        gpioSetAlertFunc(ECHO_PIN, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error installing signal handlers");
        fclose(g_log_file);
        gpioSetAlertFunc(ECHO_PIN, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d\n", TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main measurement loop ---- */
    while (g_running) {
        /* Reset state before triggering */
        g_rising_tick  = 0;
        g_falling_tick = 0;
        g_echo_seen    = false;

        trigger_sensor();

        /* Wait for echo with timeout (poll every 1 ms) */
        uint32_t wait_start = gpioTick();
        while (!g_echo_seen && (gpioTick() - wait_start) < ECHO_TIMEOUT_US) {
            gpioDelay(1000);
        }

        if (!g_echo_seen) {
            /* No echo received within timeout */
            log_reading(0.0f, false);
        } else {
            uint32_t pulse_us = tick_diff(g_rising_tick, g_falling_tick);

            if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
                /* Out of valid range: noise, timeout, or sensor absent */
                log_reading(0.0f, false);
            } else {
                float distance_cm = (float)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;
                log_reading(distance_cm, true);
            }
        }

        /* Sleep until next measurement period */
        uint32_t elapsed = gpioTick() - wait_start;
        if (elapsed < MEASURE_PERIOD_US) {
            gpioDelay(MEASURE_PERIOD_US - elapsed);
        }
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioSetAlertFunc(ECHO_PIN, NULL);
    gpioWrite(TRIGGER_PIN, 0);
    fclose(g_log_file);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

