static int vl53l1x_write16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int vl53l1x_read16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    if (vl53l1x_write16(handle, REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (vl53l1x_write16(handle, REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(1000);
    return 0;
}

static int vl53l1x_read_distance(int handle) {
    uint8_t status = 0;
    int retries = 0;
