        }
        gpioDelay(5000);
    }

    uint8_t dist_buf[2];
    if (vl53l1x_read16(handle, REG_RESULT_DISTANCE, dist_buf, 2) < 0) return -1;

    uint16_t distance = (dist_buf[0] << 8) | dist_buf[1];
    return (int)distance;
}

