    (void)gpio; (void)level; (void)tick; (void)userdata;
    int distance = vl53l1x_read_distance(i2c_handle);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance\n");
        motor_stop();
        return;
    }
    printf("Distance: %d mm\n", distance);
    if (distance < DISTANCE_THRESHOLD_CLOSE) {
        motor_forward();
        printf("Motor: FORWARD\n");
    } else if (distance > DISTANCE_THRESHOLD_FAR) {
        motor_backward();
        printf("Motor: BACKWARD\n");
    } else {
        motor_stop();
        printf("Motor: STOP\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
