        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(GPIO_MOTOR_BACKWARD, PI_OUTPUT);
    motor_stop();

    gpioSetMode(GPIO_TRIGGER, PI_INPUT);
    gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_DOWN);

    if (gpioSetISRFuncEx(GPIO_TRIGGER, RISING_EDGE, 0, trigger_callback, NULL) < 0) {
        fprintf(stderr, "Error setting ISR\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Program running. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nCleaning up...\n");
    motor_stop();
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

