#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define MPR121_ADDR 0x5A
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "proximity_log.txt"

#define REG_TOUCHSTATUS_L 0x00
#define REG_TOUCHSTATUS_H 0x01
#define REG_ELECONFIG0 0x5E
#define REG_MHDR 0x2B
#define REG_NHDR 0x2C
#define REG_NCLR 0x2D
#define REG_FDLR 0x2E
#define REG_NHDAR 0x2F
#define REG_NCLRAR 0x30
#define REG_FDLAR 0x31
#define REG_E0TTH 0x41
#define REG_E0RTH 0x42
#define REG_DEBOUNCE 0x5B
#define REG_CONFIG1 0x5C
#define REG_CONFIG2 0x5D
#define REG_SOFTRESET 0x80

#define REG_VERIFY 0x5A
#define VERIFY_VALUE 0xC8

#define GPIO_CHIP "gpiochip0"
#define LED1 17
#define LED2 18
#define LED3 27
#define LED4 22

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_lines[4] = {NULL};
static const int led_pins[4] = {LED1, LED2, LED3, LED4};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    if (i2c_write_reg(REG_SOFTRESET, 0x63) < 0) return -1;
    usleep(10000);

    uint8_t verify = 0;
    if (i2c_read_reg(REG_VERIFY, &verify) < 0) return -1;
    if (verify != VERIFY_VALUE) {
        fprintf(stderr, "MPR121 verification failed (got 0x%02X, expected 0x%02X)\n", verify, VERIFY_VALUE);
        return -1;
    }

    if (i2c_write_reg(REG_ELECONFIG0, 0x00) < 0) return -1;
    if (i2c_write_reg(REG_MHDR, 0x01) < 0) return -1;
    if (i2c_write_reg(REG_NHDR, 0x01) < 0) return -1;
    if (i2c_write_reg(REG_NCLR, 0x0E) < 0) return -1;
    if (i2c_write_reg(REG_FDLR, 0x00) < 0) return -1;
    if (i2c_write_reg(REG_NHDAR, 0x01) < 0) return -1;
    if (i2c_write_reg(REG_NCLRAR, 0x01) < 0) return -1;
    if (i2c_write_reg(REG_FDLAR, 0x00) < 0) return -1;
    if (i2c_write_reg(REG_DEBOUNCE, 0x00) < 0) return -1;
    if (i2c_write_reg(REG_CONFIG1, 0x10) < 0) return -1;
    if (i2c_write_reg(REG_CONFIG2, 0x20) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (i2c_write_reg(REG_E0TTH + i * 2, 0x0B) < 0) return -1;
        if (i2c_write_reg(REG_E0RTH + i * 2, 0xC8) < 0) return -1;
    }

    if (i2c_write_reg(REG_ELECONFIG0, 0x0C) < 0) return -1;
    return 0;
}

static int read_touch_status(uint16_t *status) {
    uint8_t lo = 0, hi = 0;
    if (i2c_read_reg(REG_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (i2c_read_reg(REG_TOUCHSTATUS_H, &hi) < 0) return -1;
    *status = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void set_led_pattern(uint8_t pattern) {
    for (int i = 0; i < 4; i++) {
        if (led_lines[i]) {
            gpiod_line_set_value(led_lines[i], (pattern >> i) & 1);
        }
    }
}

static void log_event(uint16_t status) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_fp, "%s - Touch Status: 0x%04X\n", ts, status);
    fflush(log_fp);
}

static void cleanup(void) {
    for (int i = 0; i < 4; i++) {
        if (led_lines[i]) {
            gpiod_line_set_value(led_lines[i], 0);
            gpiod_line_release(led_lines[i]);
            led_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        fclose(log_fp);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPR121_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_chip_get_line(chip, led_pins[i]);
        if (!led_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(led_lines[i], "mpr121_art", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    printf("Proximity-based art installation started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t status = 0;
        if (read_touch_status(&status) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            usleep(50000);
            continue;
        }

        uint8_t pattern = 0;
        for (int i = 0; i < 12; i++) {
            if (status & (1 << i)) {
                pattern = (uint8_t)(1 << (i % 4));
                break;
            }
        }

        set_led_pattern(pattern);
        log_event(status);
        usleep(50000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

