#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define TIMEOUT_US 30000
#define TRIGGER_PULSE_US 10
#define ECHO_SETTLE_US 100
#define LOOP_DELAY_US 1000000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_error(FILE *log, const char *msg) {
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];
    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(log, "%s, ERROR: %s\n", ts, msg);
    fflush(log);
}

static void log_reading(FILE *log, float distance) {
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];
    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(log, "%s, Distance: %.2f cm\n", ts, distance);
    fflush(log);
}

static long long elapsed_us(const struct timespec *start, const struct timespec *end) {
    return (long long)(end->tv_sec - start->tv_sec) * 1000000LL +
           (end->tv_nsec - start->tv_nsec) / 1000LL;
}

static int wait_for_level(struct gpiod_line *line, int level, long long timeout_us) {
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);
    for (;;) {
        int val = gpiod_line_get_value(line);
        if (val < 0) return -1;
        if (val == level) return 0;
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (elapsed_us(&start, &now) > timeout_us) return 1;
    }
}

static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo, float *out) {
    struct timespec ts;

    /* Ensure trigger is low */
    if (gpiod_line_set_value(trig, 0) < 0) return -1;
    usleep(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) return -1;
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trig, 0) < 0) return -1;

    /* Wait for echo rising edge (sensor absent / timeout) */
    if (wait_for_level(echo, 1, TIMEOUT_US) != 0) return 1;

    /* Wait for echo falling edge (end of pulse) */
    if (wait_for_level(echo, 0, TIMEOUT_US) != 0) return 1;

    /* Measure pulse width */
    clock_gettime(CLOCK_MONOTONIC, &ts);
    long long start_us = ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;

    if (wait_for_level(echo, 1, TIMEOUT_US) != 0) return 1;

    clock_gettime(CLOCK_MONOTONIC, &ts);
    long long end_us = ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;

    long long pulse_us = end_us - start_us;
    *out = (float)(pulse_us * 0.0343) / 2.0f;
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    FILE *log = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("fopen log");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line trigger");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line echo");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output trig");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input echo");
        goto cleanup;
    }

    /* Allow sensor to settle */
    usleep(ECHO_SETTLE_US);

    while (program_running) {
        float distance;
        int rc = measure_distance(trig, echo, &distance);

        if (rc == 0) {
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                log_reading(log, distance);
            } else {
                char msg[128];
                snprintf(msg, sizeof(msg), "Out of range: %.2f cm", distance);
                log_error(log, msg);
            }
        } else if (rc == 1) {
            log_error(log, "Timeout waiting for echo");
        } else {
            log_error(log, "GPIO read/write error");
        }

        usleep(LOOP_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    if (log) fclose(log);
    return ret;
}

