#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define TRIGGER_PULSE_US 10
#define SAMPLE_PERIOD_US 1000000  /* 1 second */
#define ECHO_TIMEOUT_US  25000     /* 25 ms max echo wait */
#define MIN_PULSE_US     58        /* ~1 cm */
#define MAX_PULSE_US     25000     /* ~4 m */

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile int      g_echo_state = 0;   /* 0=idle, 1=rising seen, 2=both edges */
static volatile int      g_pulse_us   = 0;
static volatile int      g_pulse_valid = 0;
static FILE             *g_log_fp     = NULL;
static volatile sig_atomic_t g_running = 1;

static void echo_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_start_tick = tick;
        g_echo_state = 1;
    } else if (level == 0 && g_echo_state == 1) {
        g_end_tick   = tick;
        g_echo_state = 2;
        /* pigpio ticks are 32-bit microseconds; handle wrap-around */
        uint32_t diff = tick - g_start_tick;
        if (diff >= MIN_PULSE_US && diff <= MAX_PULSE_US) {
            g_pulse_us   = (int)diff;
            g_pulse_valid = 1;
        } else {
            g_pulse_valid = 0;
        }
    }
}

static void trigger_pulse(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static void log_distance(int pulse_us)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    double distance = (double)pulse_us * 343.0 / 2000000.0;
    fprintf(g_log_fp, "%s, Distance: %.2f m (pulse: %d us)\n", ts, distance, pulse_us);
    fflush(g_log_fp);
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle */

    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("distance_log.txt", "a");
    if (g_log_fp == NULL) {
        perror("Error opening distance_log.txt");
        gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HC-SR04 distance measurement started. Press Ctrl+C to stop.\n");

    while (g_running) {
        g_echo_state   = 0;
        g_pulse_valid  = 0;
        g_pulse_us     = 0;

        trigger_pulse();

        /* Wait for echo with timeout */
        uint32_t wait_start = gpioTick();
        while (g_echo_state < 2 && g_running) {
            if ((gpioTick() - wait_start) > ECHO_TIMEOUT_US) {
                break;
            }
            gpioDelay(100);
        }

        if (g_pulse_valid) {
            log_distance(g_pulse_us);
        } else {
            fprintf(g_log_fp, "No valid echo received within timeout.\n");
            fflush(g_log_fp);
        }

        /* Sleep remainder of the 1-second period */
        uint32_t elapsed = gpioTick() - wait_start;
        if (elapsed < SAMPLE_PERIOD_US) {
            gpioDelay(SAMPLE_PERIOD_US - elapsed);
        }
    }

    /* Cleanup */
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioWrite(TRIGGER_PIN, 0);
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();

    printf("\nClean shutdown complete.\n");
    return EXIT_SUCCESS;
}

