#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define XSHUT_PIN 27

#define REG_SOFT_RESET 0x0018
#define REG_SYSTEM_MODE 0x0019
#define REG_RANGE_START 0x0020
#define REG_DISTANCE 0x0014
#define REG_STATUS 0x0016

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int vl53l1x_write16(uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int vl53l1x_read16(uint16_t reg, uint8_t *buf, uint8_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(i2c_handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(i2c_handle, (char *)buf, len);
}

static int vl53l1x_init(void) {
    if (vl53l1x_write16(REG_SOFT_RESET, 0x00) < 0) return -1;
    if (vl53l1x_write16(REG_SOFT_RESET, 0x00) < 0) return -1;
    if (vl53l1x_write16(REG_SOFT_RESET, 0x01) < 0) return -1;
    if (vl53l1x_write16(REG_SYSTEM_MODE, 0x00) < 0) return -1;
    if (vl53l1x_write16(REG_RANGE_START, 0x01) < 0) return -1;
    return 0;
}

static int read_distance(uint16_t *distance, uint8_t *status) {
    uint8_t buf[3];
    if (vl53l1x_read16(REG_DISTANCE, buf, 2) < 0) return -1;
    *distance = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    if (vl53l1x_read16(REG_STATUS, buf, 1) < 0) return -1;
    *status = buf[0];
    return 0;
}

int main(void) {
    openlog("vl53l1x_logger", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install signal handlers: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(XSHUT_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set XSHUT pin mode");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioWrite(XSHUT_PIN, 1) < 0) {
        syslog(LOG_ERR, "Failed to enable sensor via XSHUT");
        gpioTerminate();
        closelog();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device at 0x%02X: %s", VL53L1X_ADDR, strerror(errno));
        gpioWrite(XSHUT_PIN, 0);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (vl53l1x_init() < 0) {
        syslog(LOG_ERR, "VL53L1X initialisation failed");
        i2cClose(i2c_handle);
        gpioWrite(XSHUT_PIN, 0);
        gpioTerminate();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "VL53L1X logger started");

    while (running) {
        uint16_t distance = 0;
        uint8_t status = 0;

        if (read_distance(&distance, &status) == 0) {
            time_t now = time(NULL);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
            syslog(LOG_INFO, "%s - Distance: %u mm, Status: 0x%02X", ts, distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read distance: %s", strerror(errno));
        }

        gpioDelay(100000);
    }

    syslog(LOG_INFO, "Shutting down");
    i2cClose(i2c_handle);
    gpioWrite(XSHUT_PIN, 0);
    gpioTerminate();
    closelog();
    return 0;
}

