#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD_CM 20.0f
#define POLL_DELAY_US 100000
#define LOG_FILE "gate_log.txt"

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START_STOP 0x0015
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT 0x001B
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG 0x0021
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(log_file);
}

static int i2c_write_reg8(int handle, uint16_t reg, uint8_t value) {
    char buf[3] = { (char)(reg >> 8), (char)(reg & 0xFF), (char)value };
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg8(int handle, uint16_t reg, uint8_t *value) {
    char buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, (char *)value, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) return -1;
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int init_vl53l1x(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg8(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) < 0) {
        log_message("Error: Failed to read model ID from VL53L1X.");
        return -1;
    }
    if (model_id != 0xEA) {
        char msg[64];
        snprintf(msg, sizeof(msg), "Error: Invalid model ID 0x%02X (expected 0xEA).", model_id);
        log_message(msg);
        return -1;
    }
    log_message("VL53L1X detected (model ID 0xEA).");

    if (i2c_write_reg8(handle, VL53L1X_REG_SYSTEM_MODE_START_STOP, 0x00) < 0) {
        log_message("Error: Failed to stop VL53L1X.");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_reg8(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG, 0x00) < 0) {
        log_message("Error: Failed to set short ranging mode.");
        return -1;
    }

    if (i2c_write_reg8(handle, VL53L1X_REG_SYSTEM_INTERMEASUREMENT, 0x00) < 0) {
        log_message("Error: Failed to set intermeasurement period.");
        return -1;
    }

    if (i2c_write_reg8(handle, VL53L1X_REG_SYSTEM_MODE_START_STOP, 0x01) < 0) {
        log_message("Error: Failed to start VL53L1X.");
        return -1;
    }
    gpioDelay(10000);

    log_message("VL53L1X initialized successfully.");
    return 0;
}

static int read_distance_cm(int handle, float *distance_cm) {
    uint16_t raw = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, &raw) < 0) {
        log_message("Error: Failed to read distance register.");
        return -1;
    }
    *distance_cm = (float)raw / 10.0f;
    return 0;
}

static void control_gate(int gpio, float distance) {
    static int gate_open = 0;
    int new_state = (distance < DISTANCE_THRESHOLD_CM) ? 1 : 0;
    if (new_state != gate_open) {
        gpioWrite(gpio, new_state);
        gate_open = new_state;
        char msg[64];
        snprintf(msg, sizeof(msg), "Gate %s (distance: %.1f cm)",
                 gate_open ? "opened" : "closed", distance);
        log_message(msg);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        log_message("Program terminated.");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Error: Failed to open I2C bus.");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_vl53l1x(i2c_handle) < 0) {
        log_message("Error: VL53L1X initialization failed.");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0);
    log_message("Gate initialized to closed state.");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        float distance = 0.0f;
        if (read_distance_cm(i2c_handle, &distance) == 0) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Distance: %.1f cm", distance);
            log_message(msg);
            control_gate(GATE_GPIO, distance);
        } else {
            log_message("Error: Failed to read distance.");
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

