#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <string.h>
#include <stdint.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE   2.0
#define MAX_DISTANCE   400.0
#define SERVO_MIN_PW   500
#define SERVO_MAX_PW   2500
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000
#define TRIGGER_INTERVAL_US 100000
#define MOVING_AVG_SIZE 5
#define LOG_FILE "distance_log.csv"

static volatile sig_atomic_t running = 1;
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int pulse_ready = 0;

static double distance_buffer[MOVING_AVG_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        start_tick = tick;
        echo_received = 0;
    } else if (level == 0) {
        end_tick = tick;
        echo_received = 1;
        pulse_ready = 1;
    }
}

static double calculate_distance(uint32_t pulse_width_us) {
    double distance = (pulse_width_us * SPEED_OF_SOUND) / 2000000.0;
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0;
    }
    return distance;
}

static int map_distance_to_angle(double distance) {
    if (distance < 0) return 90;
    double normalized = log10(distance / MIN_DISTANCE + 1.0);
    double range = log10(MAX_DISTANCE / MIN_DISTANCE + 1.0);
    double angle = (normalized / range) * (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) + SERVO_MIN_ANGLE;
    if (angle < SERVO_MIN_ANGLE) angle = SERVO_MIN_ANGLE;
    if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;
    return (int)angle;
}

static int set_servo_angle(int angle) {
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
        fprintf(stderr, "Error: Invalid servo angle %d\n", angle);
        return -1;
    }
    int pulse_width = SERVO_MIN_PW + (int)((float)(angle - SERVO_MIN_ANGLE) /
        (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) * (SERVO_MAX_PW - SERVO_MIN_PW));
    int rc = gpioServo(SERVO_PIN, pulse_width);
    if (rc < 0) {
        fprintf(stderr, "Error: gpioServo failed for angle %d (rc=%d)\n", angle, rc);
        return -1;
    }
    return 0;
}

static double moving_average(double new_value) {
    distance_buffer[buffer_index] = new_value;
    buffer_index = (buffer_index + 1) % MOVING_AVG_SIZE;
    if (buffer_count < MOVING_AVG_SIZE) buffer_count++;
    double sum = 0.0;
    for (int i = 0; i < buffer_count; i++) sum += distance_buffer[i];
    return sum / buffer_count;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SERVO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: gpioSetPullUpDown(ECHO_PIN) failed\n");
    }

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFunc(ECHO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(50000);

    FILE *fp = fopen(LOG_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Cannot open %s for writing\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(fp, "Timestamp,Distance_cm,Servo_Angle_deg\n");
    fflush(fp);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    printf("HC-SR04 ranging with SG90 servo tracking. Press Ctrl+C to exit.\n");

    while (running) {
        echo_received = 0;
        pulse_ready = 0;

        if (gpioWrite(TRIGGER_PIN, 1) < 0) {
            fprintf(stderr, "Error: gpioWrite(TRIGGER_PIN, 1) failed\n");
            break;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) < 0) {
            fprintf(stderr, "Error: gpioWrite(TRIGGER_PIN, 0) failed\n");
            break;
        }

        uint32_t start_wait = gpioTick();
        while (!pulse_ready && running) {
            if ((gpioTick() - start_wait) > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Warning: Echo timeout (no object detected or out of range)\n");
                break;
            }
            gpioDelay(100);
        }

        double distance = -1.0;
        if (pulse_ready) {
            uint32_t pulse_width = end_tick - start_tick;
            distance = calculate_distance(pulse_width);
            if (distance < 0) {
                fprintf(stderr, "Warning: Distance out of range (%.2f cm)\n", pulse_width / 58.0);
            }
        }

        double avg_distance = moving_average(distance);
        int angle = map_distance_to_angle(avg_distance);

        if (set_servo_angle(angle) < 0) {
            fprintf(stderr, "Error: Failed to set servo angle\n");
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(fp, "%s,%.2f,%d\n", timestamp, avg_distance, angle);
        fflush(fp);

        printf("%s  Distance: %.2f cm  Angle: %d deg\n", timestamp, avg_distance, angle);

        gpioDelay(TRIGGER_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    fclose(fp);
    gpioTerminate();
    return EXIT_SUCCESS;
}

