#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 200
#define BUFFER_SIZE 10
#define POLL_DELAY_US 50000

/* VL53L1X register addresses */
#define VL53L1X_REG_SOFT_RESET 0x000B
#define VL53L1X_REG_VHV_CONFIG_TIMEOUT_MACROP_LOOP_BOUND 0x0008
#define VL53L1X_REG_MSRC_CONFIG_CONTROL 0x0060
#define VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN_LIMIT 0x0044
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT_PERIOD 0x0004
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_SYSTEM_MODE_START 0x0087
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg16(uint8_t reg, uint8_t value) {
    char buf[3] = { (char)(reg >> 8), (char)(reg & 0xFF), (char)value };
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int i2c_read_reg16(uint8_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    if (i2cWriteDevice(i2c_handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(i2c_handle, (char *)buf, len);
}

static int vl53l1x_init(void) {
    if (i2c_write_reg16(VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(VL53L1X_REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg16(VL53L1X_REG_VHV_CONFIG_TIMEOUT_MACROP_LOOP_BOUND, 0x09) < 0) return -1;
    if (i2c_write_reg16(VL53L1X_REG_MSRC_CONFIG_CONTROL, 0x00) < 0) return -1;
    if (i2c_write_reg16(VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN_LIMIT, 0x00) < 0) return -1;
    if (i2c_write_reg16(VL53L1X_REG_SYSTEM_INTERMEASUREMENT_PERIOD, 0x00) < 0) return -1;
    if (i2c_write_reg16(VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) return -1;
    if (i2c_write_reg16(VL53L1X_REG_SYSTEM_MODE_START, 0x40) < 0) return -1;

    return 0;
}

static int vl53l1x_read_distance(uint16_t *distance) {
    uint8_t status = 0;
    uint8_t data[2];
    int retries = 10;

    while (retries-- > 0) {
        if (i2c_read_reg16(VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) return -1;
        if ((status & 0x01) == 0) break;
        gpioDelay(10000);
    }
    if (retries < 0) return -1;

    if (i2c_read_reg16(VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) < 0) return -1;
    *distance = (uint16_t)((data[0] << 8) | data[1]);

    if (i2c_write_reg16(VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) return -1;
    return 0;
}

int main(void) {
    uint16_t distance;
    uint16_t buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_count = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init() < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        if (vl53l1x_read_distance(&distance) == 0) {
            buffer[buffer_index] = distance;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            if (buffer_count < BUFFER_SIZE) buffer_count++;

            printf("Distance: %u mm\n", distance);

            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(GPIO_LED, 1);
            } else {
                gpioWrite(GPIO_LED, 0);
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(GPIO_LED, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

