#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define PWM_PIN     18

#define MIN_FREQUENCY 200.0
#define MAX_FREQUENCY 2000.0
#define MIN_DISTANCE  2.0
#define MAX_DISTANCE  200.0
#define SOUND_SPEED   34300.0
#define TIMEOUT_US    200000
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set PWM pin mode\n");
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) != 0) return -1;
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) return -1;
    return 0;
}

static long long measure_echo(void) {
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > TIMEOUT_US) return -1;
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - start_tick) > TIMEOUT_US) return -1;
    }
    end_tick = gpioTick();

    return (long long)(end_tick - start_tick);
}

static double calculate_distance(long long pulse_duration) {
    if (pulse_duration < 0) return -1.0;
    return (double)pulse_duration * SOUND_SPEED / 2000000.0;
}

static double map_distance_to_frequency(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) return -1.0;
    return MIN_FREQUENCY * exp(distance / 50.0);
}

static int set_tone_frequency(double frequency) {
    if (frequency < MIN_FREQUENCY || frequency > MAX_FREQUENCY) return -1;

    int pwm_range = 1000;
    int pwm_duty = pwm_range / 2;

    if (gpioSetPWMrange(PWM_PIN, pwm_range) != 0) return -1;
    if (gpioSetPWMfrequency(PWM_PIN, (int)frequency) != 0) return -1;
    if (gpioPWM(PWM_PIN, pwm_duty) != 0) return -1;

    return 0;
}

static void cleanup(void) {
    gpioPWM(PWM_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    double current_frequency = MIN_FREQUENCY;
    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        if (trigger_sensor() != 0) {
            fprintf(stderr, "Warning: trigger failed, skipping cycle\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        long long pulse_duration = measure_echo();
        double distance = calculate_distance(pulse_duration);

        if (distance < 0) {
            fprintf(stderr, "Warning: echo timeout or invalid pulse, holding frequency\n");
        } else {
            double new_freq = map_distance_to_frequency(distance);
            if (new_freq >= 0) {
                current_frequency = new_freq;
            } else {
                fprintf(stderr, "Warning: distance out of range, holding frequency\n");
            }
        }

        if (set_tone_frequency(current_frequency) != 0) {
            fprintf(stderr, "Error: failed to set tone frequency\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

