        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode.\n");
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode.\n");
        return -1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: failed to set pull-down on echo pin.\n");
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low.\n");
        return -1;
    }
    gpioDelay(5);
    return 0;
}

static float read_distance(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high.\n");
        return -1.0f;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low.\n");
        return -1.0f;
    }

    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > TIMEOUT_US) {
            fprintf(stderr, "Error: echo pin stuck low (timeout).\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - start_tick) > TIMEOUT_US) {
