#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define TIMEOUT_US  50000   /* 50 ms timeout for echo pulse */
#define MIN_DIST_CM 2.0
#define MAX_DIST_CM 400.0
#define TOO_CLOSE_CM 10.0
#define SAMPLE_PERIOD_US 500000  /* 500 ms between measurements */

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns the pulse width in microseconds, or -1 on timeout.
 */
static long measure_echo_pulse(void)
{
    uint32_t start_tick, end_tick;
    uint32_t deadline;

    /* Wait for echo to go high (start of pulse) */
    deadline = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0)
            return -1;  /* timeout */
    }
    start_tick = gpioTick();

    /* Wait for echo to go low (end of pulse) */
    deadline = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0)
            return -1;  /* timeout */
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Register SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not register SIGINT handler.\n");
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000);  /* 1 ms settle */

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        /* Send 10 us trigger pulse */
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);  /* 10 us */
        gpioWrite(TRIGGER_PIN, 0);

        long pulse_width = measure_echo_pulse();

        if (pulse_width < 0) {
            printf("Invalid reading (timeout).\n");
        } else {
            double distance = (double)pulse_width / 2.0 / 29.1;
            if (distance < MIN_DIST_CM || distance > MAX_DIST_CM) {
                printf("Invalid reading (%.2f cm out of range).\n", distance);
            } else {
                printf("Distance: %.2f cm", distance);
                if (distance < TOO_CLOSE_CM) {
                    printf(" - Too close!");
                }
                printf("\n");
            }
        }

        /* Wait 500 ms before next measurement */
        gpioDelay(SAMPLE_PERIOD_US);
    }

