#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define CS_PIN 8

#define REG_MODE 0x01
#define REG_RANGE 0x02
#define REG_TRIGGER 0x00
#define REG_DIST_L 0x0C
#define REG_DIST_H 0x0D

#define MEASUREMENT_DELAY_US 100000
#define LOOP_DELAY_US 100000

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_write_reg(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = {0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write failed for reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int spi_read_reg(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = {0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read failed for reg 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

static int init_sensor(void) {
    if (spi_write_reg(REG_MODE, 0x01) != 0) return -1;
    if (spi_write_reg(REG_RANGE, 0x00) != 0) return -1;
    if (spi_write_reg(REG_TRIGGER, 0x01) != 0) return -1;
    gpioDelay(MEASUREMENT_DELAY_US);
    return 0;
}

static int read_distance(uint16_t *distance) {
    uint8_t low = 0, high = 0;
    if (spi_read_reg(REG_DIST_L, &low) != 0) return -1;
    if (spi_read_reg(REG_DIST_H, &high) != 0) return -1;
    *distance = ((uint16_t)high << 8) | low;
    return 0;
}

static void log_data(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%u\n", timestamp, distance);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("distance_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        uint16_t distance = 0;
        if (read_distance(&distance) == 0) {
            log_data(distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        gpioDelay(LOOP_DELAY_US);
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

