#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_ADDR 0x60
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23
#define LOG_FILE "proximity_log.csv"
#define I2C_BUS "/dev/i2c-1"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

static int read_als_visible(int fd, uint16_t *als_visible) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, SI1175_REG_ALS_VIS_DATA0, &lo) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, SI1175_REG_ALS_VIS_DATA1, &hi) < 0) {
        return -1;
    }
    *als_visible = (uint16_t)((hi << 8) | lo);
    return 0;
}

static void log_data(FILE *fp, uint16_t als_visible) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%u\n", timestamp, als_visible);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fseek(log_fp, 0, SEEK_END);
    long file_size = ftell(log_fp);
    if (file_size == 0) {
        fprintf(log_fp, "timestamp,als_visible\n");
        fflush(log_fp);
    }

    printf("Si1175 proximity logger started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t als_visible = 0;

        if (read_als_visible(i2c_fd, &als_visible) == 0) {
            log_data(log_fp, als_visible);
            printf("ALS Visible: %u\n", als_visible);
        } else {
            fprintf(stderr, "Error reading ALS visible value: %s\n", strerror(errno));
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");

    if (log_fp != NULL) {
        fclose(log_fp);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
}

