#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1120_ADDR        0x60
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_RESET   0x30
#define SI1120_REG_ALS_LSB 0x22
#define SI1120_REG_ALS_MSB 0x23
#define SI1120_REG_PS1_LSB 0x18
#define SI1120_REG_PS1_MSB 0x19
#define SI1120_PART_ID     0x41
#define I2C_BUS            1
#define LOG_FILE           "si1120_log.txt"
#define SAMPLE_PERIOD_US   500000
#define MAX_RETRIES        3
#define RETRY_DELAY_US     10000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed for register 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed for register 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_word(int handle, uint8_t lsb_reg, uint8_t msb_reg, uint16_t *out)
{
    uint8_t lsb, msb;
    if (read_register(handle, lsb_reg, &lsb) != 0)
        return -1;
    if (read_register(handle, msb_reg, &msb) != 0)
        return -1;
    *out = (uint16_t)((msb << 8) | lsb);
    return 0;
}

static int initialize_sensor(int handle)
{
    uint8_t part_id = 0;
    if (write_register(handle, SI1120_REG_RESET, 0x01) != 0) {
        fprintf(stderr, "Failed to reset Si1120\n");
        return -1;
    }
    gpioDelay(10000);

    if (read_register(handle, SI1120_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read part ID\n");
        return -1;
    }
    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Unexpected part ID: 0x%02X (expected 0x%02X)\n", part_id, SI1120_PART_ID);
        return -1;
    }
    printf("Si1120 initialized (part ID 0x%02X)\n", part_id);
    return 0;
}

static int read_sensor_data(int handle, uint16_t *als, uint16_t *proximity)
{
    if (read_word(handle, SI1120_REG_ALS_LSB, SI1120_REG_ALS_MSB, als) != 0) {
        fprintf(stderr, "Failed to read ALS data\n");
        return -1;
    }
    if (read_word(handle, SI1120_REG_PS1_LSB, SI1120_REG_PS1_MSB, proximity) != 0) {
        fprintf(stderr, "Failed to read proximity data\n");
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, uint16_t als, uint16_t proximity)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, ALS: %u, Proximity: %u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, als, proximity);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
