#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1182_I2C_ADDR 0x39
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "biometric_log.txt"

#define REG_PART_ID 0x00
#define REG_MEAS_RATE 0x08
#define REG_ALS_DATA_0 0x22
#define REG_ALS_DATA_1 0x23
#define REG_PS1_DATA_0 0x24
#define REG_PS1_DATA_1 0x25

#define EXPECTED_PART_ID 0x82
#define MEAS_RATE_100MS 0x07

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_sensor(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read part ID - sensor may be absent or bus error.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected part ID: 0x%02X (expected 0x%02X). Wrong sensor?\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("Si1182 detected (part ID 0x%02X).\n", part_id);

    if (i2c_write_reg8(fd, REG_MEAS_RATE, MEAS_RATE_100MS) != 0) {
        fprintf(stderr, "Failed to set measurement rate.\n");
        return -1;
    }
    printf("Measurement rate set to 100 ms.\n");
    return 0;
}

static void get_timestamp(char *buf, size_t len) {
    struct timespec ts;
    struct tm tm_info;
    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%03ld", ts.tv_nsec / 1000000);
}

static void log_data(FILE *fp, const char *timestamp, float lux, uint16_t proximity) {
    fprintf(fp, "%s,%.2f,%u\n", timestamp, lux, proximity);
    fflush(fp);
}

static void cleanup(void) {
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen " LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (running) {
        uint16_t als_raw, ps_raw;
        char timestamp[32];

        if (i2c_read_reg16_le(i2c_fd, REG_ALS_DATA_0, &als_raw) != 0 ||
            i2c_read_reg16_le(i2c_fd, REG_PS1_DATA_0, &ps_raw) != 0) {
            fprintf(stderr, "Sensor read error - skipping sample.\n");
            usleep(100000);
            continue;
        }

        get_timestamp(timestamp, sizeof(timestamp));
        float lux = als_raw * 0.1f;
        log_data(log_fp, timestamp, lux, ps_raw);
        printf("%s, Lux: %.2f, Proximity: %u\n", timestamp, lux, ps_raw);

        usleep(100000);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

