#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define BUZZER_PIN  27

#define SPEED_OF_SOUND 0.0343  /* cm/us */
#define THRESHOLD_CM   20.0
#define TRIGGER_US     10
#define LOOP_DELAY_US  1000000 /* 1 second */

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick   = 0;
static volatile int      echo_done  = 0;

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        start_tick = tick;
    } else if (level == 0) {
        end_tick   = tick;
        echo_done  = 1;
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    fprintf(stderr, "\nCaught SIGINT, cleaning up and exiting...\n");
    gpioTerminate();
    exit(0);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not register SIGINT handler.\n");
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to set alert function on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise BUZZER_PIN %d low.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (1) {
        echo_done = 0;
        start_tick = 0;
        end_tick   = 0;

        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set TRIGGER_PIN high.\n");
            break;
        }
        gpioDelay(TRIGGER_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set TRIGGER_PIN low.\n");
            break;
        }

        uint32_t wait_start = gpioTick();
        while (!echo_done) {
            if (gpioTick() - wait_start > 100000) { /* 100 ms timeout */
                fprintf(stderr, "Warning: echo timeout (sensor absent or not responding).\n");
                echo_done = 1;
                break;
            }
            gpioDelay(100);
        }

        if (echo_done && start_tick != 0 && end_tick != 0) {
            uint32_t diff = end_tick - start_tick;
            double distance = (double)diff * SPEED_OF_SOUND / 2.0;

            printf("Distance: %.2f cm\n", distance);

            if (distance < THRESHOLD_CM) {
                if (gpioWrite(BUZZER_PIN, 1) != 0) {
                    fprintf(stderr, "Error: failed to set BUZZER_PIN high.\n");
                }
            } else {
                if (gpioWrite(BUZZER_PIN, 0) != 0) {
                    fprintf(stderr, "Error: failed to set BUZZER_PIN low.\n");
                }
            }
        } else {
            if (gpioWrite(BUZZER_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to set BUZZER_PIN low on error.\n");
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

