#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define SPEED_OF_SOUND 34300.0
#define MAX_DISTANCE 200.0
#define MIN_DISTANCE 20.0
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define ECHO_TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static float measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    start_tick = gpioTick();
    timeout_tick = start_tick + ECHO_TIMEOUT_US;

    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo pin stuck low (timeout).\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo pin stuck high (timeout).\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    float distance = (float)pulse_width * SPEED_OF_SOUND / 2000000.0;

    if (distance < 2.0 || distance > 400.0) {
        fprintf(stderr, "Warning: Distance out of range (%.2f cm).\n", distance);
        return -1.0;
    }
    return distance;
}

static void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse_width = SERVO_MIN_PULSE + (angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE)) / 180;
    gpioServo(SERVO_PIN, pulse_width);
}

static int map_distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;
    int angle = 180 - (int)(((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * 180.0);
    return angle;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance();
        if (distance < 0.0) {
            fprintf(stderr, "Error: Distance measurement failed. Retrying...\n");
            gpioDelay(100000);
            continue;
        }

        int angle = map_distance_to_angle(distance);
        set_servo_angle(angle);

        printf("Distance: %.2f cm, Servo Angle: %d degrees\n", distance, angle);
        gpioDelay(100000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nParking Assist System stopped.\n");
    return EXIT_SUCCESS;
}

