#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

#define SPEED_OF_SOUND 0.0343  /* cm/us */
#define MIN_DISTANCE 2.0       /* cm */
#define MAX_DISTANCE 400.0     /* cm */
#define MIN_ANGLE 0.0          /* degrees */
#define MAX_ANGLE 180.0        /* degrees */
#define SERVO_MIN_PULSE 500    /* us for 0 degrees */
#define SERVO_MAX_PULSE 2500   /* us for 180 degrees */
#define TRIGGER_PULSE_US 10    /* 10 us trigger pulse */
#define ECHO_TIMEOUT_US 50000  /* 50 ms timeout for echo */
#define LOOP_DELAY_US 100000   /* 100 ms between measurements */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure distance using HC-SR04.
 * Returns distance in cm, or -1.0 on timeout/error.
 */
static float measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger is low before starting */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0;
    }
    gpioDelay(5);  /* settle */

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo rising edge timeout\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo falling edge timeout\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (float)pulse_us * SPEED_OF_SOUND / 2.0f;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Warning: Distance %.2f cm out of range [%.1f, %.1f]\n",
                distance, MIN_DISTANCE, MAX_DISTANCE);
        return -1.0;
    }
    return distance;
}

/*
 * Map distance to servo angle (0-180 degrees).
 * Returns -1.0 if distance is invalid.
 */
static float distance_to_angle(float distance) {
    if (distance < 0.0f) {
        return -1.0f;
    }
    float angle = (distance - MIN_DISTANCE) *
                  (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE) + MIN_ANGLE;
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return angle;
}

/*
 * Set servo angle (0-180 degrees) using gpioServo.
 * Returns 0 on success, -1 on error.
 */
static int set_servo_angle(float angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %.2f out of range [%.1f, %.1f]\n",
                angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    int pulse_width = (int)(SERVO_MIN_PULSE +
                            (angle / MAX_ANGLE) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE));
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo(%d, %d) failed\n", SERVO_PIN, pulse_width);
        return -1;
    }
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SERVO, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) initial failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");
    printf("Trigger: GPIO%d, Echo: GPIO%d, Servo: GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, SERVO_PIN);

    while (running) {
        float distance = measure_distance();
        if (distance < 0.0f) {
            fprintf(stderr, "Error: Distance measurement failed, skipping cycle\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        float angle = distance_to_angle(distance);
        if (angle < 0.0f) {
            fprintf(stderr, "Error: Angle calculation failed, skipping cycle\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (set_servo_angle(angle) < 0) {
            fprintf(stderr, "Error: Failed to set servo angle\n");
        }

        printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);
        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);  /* stop servo signal */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("Parking Assist System stopped.\n");
    return EXIT_SUCCESS;
}

