#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUMID_REG 0x02
#define CONFIG_VALUE 0x00
#define SAMPLE_INTERVAL_US 2000000
#define CONVERSION_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 0) {
        fprintf(stderr, "Error selecting register 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

static int read_temperature(int handle, float *temperature) {
    uint8_t raw;
    if (read_register(handle, TEMP_REG, &raw) != 0) return -1;
    *temperature = (175.72f * (float)raw) / 65536.0f - 46.85f;
    return 0;
}

static int read_humidity(int handle, float *humidity) {
    uint8_t raw;
    if (read_register(handle, HUMID_REG, &raw) != 0) return -1;
    *humidity = (125.0f * (float)raw) / 65536.0f - 6.0f;
    if (*humidity < 0.0f) *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;
    return 0;
}

static int initialize_sensor(int handle) {
    if (write_register(handle, CONFIG_REG, CONFIG_VALUE) != 0) return -1;
    gpioDelay(CONVERSION_DELAY_US);
    return 0;
}

static int open_i2c(void) {
    int handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, SI7005_ADDR, handle);
        return -1;
    }
    return handle;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    i2c_handle = open_i2c();
    if (i2c_handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        float temperature, humidity;

        if (read_temperature(i2c_handle, &temperature) != 0 ||
            read_humidity(i2c_handle, &humidity) != 0) {
            fprintf(stderr, "Read error, attempting I2C recovery...\n");
            i2cClose(i2c_handle);
            i2c_handle = open_i2c();
            if (i2c_handle < 0) {
                fprintf(stderr, "I2C recovery failed, exiting\n");
                break;
            }
            if (initialize_sensor(i2c_handle) != 0) {
                fprintf(stderr, "Sensor re-initialization failed, exiting\n");
                break;
            }
            continue;
        }

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        fflush(stdout);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

