#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define WHO_AM_I     0x75
#define PWR_MGMT_1   0x6B
#define SMPLRT_DIV   0x19
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG  0x1B
#define ACCEL_XOUT_H 0x3B

#define EXPECTED_WHO_AM_I 0x68
#define I2C_BUS 1
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can clean up and exit.      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian register pair.                             */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_reg16(int handle, uint8_t reg, int16_t *out)
{
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read error at reg 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    *out = (int16_t)(((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the MPU-6050: verify identity, reset, configure ranges.  */
/* ------------------------------------------------------------------ */
static int init_mpu6050(int handle)
{
    int who = i2cReadByteData(handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I (rc=%d)\n", who);
        return -1;
    }
    if (who != EXPECTED_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, EXPECTED_WHO_AM_I);
        return -1;
    }
    printf("MPU-6050 detected (WHO_AM_I = 0x%02X)\n", who);

    /* Wake up: clear SLEEP bit (bit 6) in PWR_MGMT_1 */
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to write PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(100000);  /* 100 ms settle after wake */

    /* Sample rate divider = 7  ->  1 kHz / (1 + 7) = 125 Hz */
    if (i2cWriteByteData(handle, SMPLRT_DIV, 7) < 0) {
        fprintf(stderr, "Failed to write SMPLRT_DIV\n");
        return -1;
    }

    /* Accel range ±2 g  (AFS_SEL = 0) */
    if (i2cWriteByteData(handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to write ACCEL_CONFIG\n");
        return -1;
    }

    /* Gyro range ±250 °/s (FS_SEL = 0) */
    if (i2cWriteByteData(handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to write GYRO_CONFIG\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read and print one 14-byte sample block.                            */
/* ------------------------------------------------------------------ */
static int read_and_print(int handle)
{
    char buf[14];
    int rc = i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buf, 14);
    if (rc != 14) {
        fprintf(stderr, "I2C block read error (rc=%d)\n", rc);
        return -1;
    }

    int16_t ax = (int16_t)(((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    int16_t ay = (int16_t)(((uint8_t)buf[2] << 8) | (uint8_t)buf[3]);
    int16_t az = (int16_t)(((uint8_t)buf[4] << 8) | (uint8_t)buf[5]);
    /* buf[6..7] = temperature (skipped) */
    int16_t gx = (int16_t)(((uint8_t)buf[8]  << 8) | (uint8_t)buf[9]);
    int16_t gy = (int16_t)(((uint8_t)buf[10] << 8) | (uint8_t)buf[11]);
    int16_t gz = (int16_t)(((uint8_t)buf[12] << 8) | (uint8_t)buf[13]);

    printf("Accel: X=%6d Y=%6d Z=%6d  |  Gyro: X=%6d Y=%6d Z=%6d\n",
           ax, ay, az, gx, gy, gz);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed on bus %d addr 0x%02X (rc=%d)\n",
                I2C_BUS, MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_mpu6050(g_i2c_handle) != 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 logging started (125 Hz, 100 ms period). Ctrl-C to stop.\n");

    while (g_running) {
        if (read_and_print(g_i2c_handle) != 0) {
            /* Transient I2C error — keep running unless signal received */
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

