#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SHT40_ADDR        0x44
#define SHT40_CMD_HIGHREP 0xFD
#define I2C_BUS           1
#define SAMPLE_PERIOD_S   5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR */
static uint8_t sht40_crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int sht40_read(int handle, float *temperature, float *humidity)
{
    uint8_t cmd = SHT40_CMD_HIGHREP;
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed (cmd 0x%02X)\n", cmd);
        return -1;
    }

    gpioDelay(10000); /* 10 ms measurement time */

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: i2cReadDevice failed (expected 6 bytes)\n");
        return -1;
    }

    if (sht40_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -1;
    }
    if (sht40_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t h_raw = (uint16_t)((buf[3] << 8) | buf[4]);

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = -6.0f  + 125.0f * (float)h_raw / 65535.0f;

    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

static int open_i2c(void)
{
    int h = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (h < 0) {
        fprintf(stderr, "Error: i2cOpen failed on bus %d addr 0x%02X (pigpio err %d)\n",
                I2C_BUS, SHT40_ADDR, h);
        return -1;
    }
    return h;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = open_i2c();
    if (g_i2c_handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temperature, humidity;

        if (sht40_read(g_i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: sensor read failed, re-opening I2C bus\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            gpioDelay(1000000); /* 1 s back-off before retry */
            g_i2c_handle = open_i2c();
            if (g_i2c_handle < 0) {
                fprintf(stderr, "Error: re-open failed, exiting\n");
                break;
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

