#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "temperature_log.csv"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, float *out) {
    uint8_t buf[3];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        return -1;
    }

    if (read(fd, buf, 3) != 3) {
        return -1;
    }

    int16_t raw = (int16_t)((buf[1] << 8) | buf[0]);
    *out = (float)raw * 0.02f - 273.15f;
    return 0;
}

static int log_temperature(float ambient, float object) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, ambient, object) < 0) {
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MLX90614_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Starting temperature monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        float ambient = 0.0f, object = 0.0f;
        int amb_ok = i2c_read_reg16(i2c_fd, AMBIENT_TEMP_REG, &ambient);
        int obj_ok = i2c_read_reg16(i2c_fd, OBJECT_TEMP_REG, &object);

        if (amb_ok == 0 && obj_ok == 0) {
            if (log_temperature(ambient, object) != 0) {
                fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            } else {
                printf("Ambient: %.2f C, Object: %.2f C\n", ambient, object);
            }
        } else {
            fprintf(stderr, "Error reading temperature data (ambient=%d, object=%d): %s\n", amb_ok, obj_ok, strerror(errno));
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nCleaning up...\n");
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return EXIT_SUCCESS;
}

