    printf("\nCleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (error_log_file) {
        fclose(error_log_file);
    }
    gpioTerminate();

    return 0;
}

