#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP31_ADDR 0x28
#define LOG_FILE "airflow.log"
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3
#define TRIGGER_CMD_LEN 2
#define READ_LEN 6

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int sdp31_trigger(void) {
    char cmd[TRIGGER_CMD_LEN] = {0x21, 0x96};
    int retries = 0;
    int delay_us = 1000;

    while (retries < MAX_RETRIES) {
        int rc = i2cWriteDevice(i2c_handle, cmd, TRIGGER_CMD_LEN);
        if (rc == 0) return 0;
        fprintf(stderr, "I2C write trigger failed (attempt %d/%d): rc=%d\n",
                retries + 1, MAX_RETRIES, rc);
        retries++;
        gpioDelay(delay_us);
        delay_us *= 2;
    }
    return -1;
}

static int sdp31_read(float *pressure, float *temperature) {
    char buf[READ_LEN];
    int retries = 0;
    int delay_us = 1000;

    while (retries < MAX_RETRIES) {
        int rc = i2cReadDevice(i2c_handle, buf, READ_LEN);
        if (rc == READ_LEN) {
            int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
            int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
            *pressure = (float)raw_pressure / 60.0f;
            *temperature = (float)raw_temperature / 200.0f;
            return 0;
        }
        fprintf(stderr, "I2C read failed (attempt %d/%d): rc=%d\n",
                retries + 1, MAX_RETRIES, rc);
        retries++;
        gpioDelay(delay_us);
        delay_us *= 2;
    }
    return -1;
}

static int log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
