#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define SI7015_ADDR 0x40
#define CMD_TEMP_NO_HOLD 0xF3
#define CMD_HUM_NO_HOLD 0xF5
#define MEASURE_DELAY_US 20000
#define SAMPLE_INTERVAL_US 5000000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_si7015(int handle, unsigned char cmd, float *out) {
    char buf[2];
    int rc;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cWriteByte(handle, cmd);
        if (rc < 0) {
            fprintf(stderr, "I2C write failed (cmd 0x%02X), attempt %d: %s\n",
                    cmd, attempt + 1, pigpio_error(rc));
            gpioDelay(100000);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        rc = i2cReadDevice(handle, buf, 2);
        if (rc < 0) {
            fprintf(stderr, "I2C read failed (cmd 0x%02X), attempt %d: %s\n",
                    cmd, attempt + 1, pigpio_error(rc));
            gpioDelay(100000);
            continue;
        }

        if (rc != 2) {
            fprintf(stderr, "I2C read short (cmd 0x%02X), got %d bytes, attempt %d\n",
                    cmd, rc, attempt + 1);
            gpioDelay(100000);
            continue;
        }

        unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) |
                           (unsigned int)(unsigned char)buf[1];

        if (cmd == CMD_TEMP_NO_HOLD) {
            *out = (175.72f * raw / 65536.0f) - 46.85f;
        } else {
            *out = (125.0f * raw / 65536.0f) - 6.0f;
            if (*out < 0.0f) *out = 0.0f;
            if (*out > 100.0f) *out = 100.0f;
        }
        return 0;
    }

    fprintf(stderr, "Failed to read sensor after %d attempts (cmd 0x%02X)\n",
            MAX_RETRIES, cmd);
    return -1;
}

static int log_data(float temp, float hum) {
    FILE *fp = fopen("sensor_data.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening sensor_data.txt: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Humidity: %.2f %%RH\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp, hum);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing sensor_data.txt: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, SI7015_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }

    printf("Si7015 sensor logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float temp, hum;

        if (read_si7015(i2c_handle, CMD_TEMP_NO_HOLD, &temp) != 0) {
            fprintf(stderr, "Temperature read failed; continuing.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (read_si7015(i2c_handle, CMD_HUM_NO_HOLD, &hum) != 0) {
            fprintf(stderr, "Humidity read failed; continuing.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (log_data(temp, hum) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        printf("Temperature: %.2f C, Humidity: %.2f %%RH\n", temp, hum);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

