#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define FAN_GPIO       18
#define TEMP_THRESHOLD 28.0f
#define TEMP_HYSTERESIS 27.0f
#define BUFFER_SIZE    60
#define I2C_RETRIES    3
#define MEASURE_DELAY_US 10000  /* 10 ms */
#define LOOP_DELAY_US   2000000 /* 2 s  */

typedef struct {
    time_t timestamp;
    float  temperature;
    float  humidity;
} Reading;

static Reading  buffer[BUFFER_SIZE];
static int      buffer_index = 0;
static int      i2c_handle   = -1;
static volatile sig_atomic_t running = 1;

/* ---- prototypes ---- */
static int  init_i2c(void);
static int  read_sensor(float *temperature, float *humidity);
static void add_to_buffer(float temperature, float humidity);
static void print_buffer(void);
static void control_fan(float temperature);
static void cleanup(void);
static void signal_handler(int sig);

/* ---- I2C helpers ---- */
static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, SI7021_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

/*
 * Trigger a Hold Master measurement and read the 2-byte result.
 * Returns 0 on success, -1 on failure.
 */
static int read_measurement(uint8_t cmd, uint16_t *raw) {
    int rc;

    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        rc = i2cWriteByte(i2c_handle, cmd);
        if (rc < 0) {
            fprintf(stderr, "I2C write cmd 0x%02X failed (attempt %d/%d): %d\n",
                    cmd, attempt + 1, I2C_RETRIES, rc);
            gpioDelay(MEASURE_DELAY_US);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        char data[2];
        rc = i2cReadDevice(i2c_handle, data, 2);
        if (rc == 2) {
            *raw = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
            return 0;
        }

        fprintf(stderr, "I2C read cmd 0x%02X failed (attempt %d/%d): %d\n",
                cmd, attempt + 1, I2C_RETRIES, rc);
        gpioDelay(MEASURE_DELAY_US);
    }
    return -1;
}

static int read_sensor(float *temperature, float *humidity) {
    uint16_t raw_temperature, raw_humidity;

    if (read_measurement(0xE3, &raw_temperature) != 0) {
        fprintf(stderr, "Failed to read temperature after %d retries\n", I2C_RETRIES);
        return -1;
    }

    if (read_measurement(0xE5, &raw_humidity) != 0) {
        fprintf(stderr, "Failed to read humidity after %d retries\n", I2C_RETRIES);
        return -1;
    }

    *temperature = (175.72f * (float)raw_temperature / 65536.0f) - 46.85f;
    *humidity    = (125.0f  * (float)raw_humidity  / 65536.0f) - 6.0f;

    /* Clamp humidity to physical range */
    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

/* ---- buffer & logging ---- */
static void add_to_buffer(float temperature, float humidity) {
    buffer[buffer_index].timestamp   = time(NULL);
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].humidity    = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_buffer(void) {
    int start = (buffer_index == 0) ? BUFFER_SIZE - 1 : buffer_index - 1;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        localtime_r(&buffer[idx].timestamp, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] Temp: %.2f C  Hum: %.2f %%RH\n",
               ts, buffer[idx].temperature, buffer[idx].humidity);
    }
    fflush(stdout);
}

/* ---- fan control ---- */
static void control_fan(float temperature) {
    static int fan_on = 0;

    if (temperature > TEMP_THRESHOLD && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON  (temp %.2f C > %.1f C)\n", temperature, TEMP_THRESHOLD);
        } else {
            fprintf(stderr, "Warning: failed to set fan GPIO high\n");
        }
    } else if (temperature < TEMP_HYSTERESIS && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (temp %.2f C < %.1f C)\n", temperature, TEMP_HYSTERESIS);
        } else {
            fprintf(stderr, "Warning: failed to set fan GPIO low\n");
        }
    }
}

/* ---- cleanup & signals ---- */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* ---- main ---- */
int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si7021 fan controller started.  I2C bus %d, addr 0x%02X, fan GPIO %d.\n",
           I2C_BUS, SI7021_ADDR, FAN_GPIO);
    printf("Threshold ON  > %.1f C, OFF < %.1f C.  Ctrl+C to exit.\n",
           TEMP_THRESHOLD, TEMP_HYSTERESIS);

    while (running) {
        float temperature, humidity;

        if (read_sensor(&temperature, &humidity) == 0) {
            add_to_buffer(temperature, humidity);
            print_buffer();
            control_fan(temperature);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 20 && running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

