#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TMP05_GPIO 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds */
#define EDGE_TIMEOUT_US 50000        /* 50 ms */
#define MIN_TEMP -40.0
#define MAX_TEMP 150.0

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure the high-time (TH) and total-cycle-time (TL) of the TMP05 PWM output.
 * Returns 0 on success, -1 on timeout or I/O error.
 */
static int measure_pulse_widths(unsigned int *th, unsigned int *tl) {
    int level;
    unsigned int start_tick, end_tick;

    /* Wait for the line to go LOW (end of a full cycle) */
    start_tick = gpioTick();
    do {
        level = gpioRead(TMP05_GPIO);
        if (level < 0) return -1;
        if ((gpioTick() - start_tick) > EDGE_TIMEOUT_US) return -1;
    } while (level == 1);
    end_tick = gpioTick();
