#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD_HIGH_REP 0x2400
#define MEASUREMENT_DELAY_US 15000
#define RETRY_COUNT 3
#define RETRY_DELAY_US 1000000
#define LOG_INTERVAL_US 5000000
#define SIMULATION_PERIOD_SEC 3600

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht35(float *temperature, float *humidity) {
    uint8_t cmd[2] = { (MEASURE_CMD_HIGH_REP >> 8) & 0xFF, MEASURE_CMD_HIGH_REP & 0xFF };
    uint8_t buf[6];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d/%d)\n", retries + 1, RETRY_COUNT);
            retries++;
            if (retries < RETRY_COUNT) gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(i2c_handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d/%d)\n", retries + 1, RETRY_COUNT);
            retries++;
            if (retries < RETRY_COUNT) gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d/%d)\n", retries + 1, RETRY_COUNT);
            retries++;
            if (retries < RETRY_COUNT) gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch (attempt %d/%d)\n", retries + 1, RETRY_COUNT);
            retries++;
            if (retries < RETRY_COUNT) gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t raw_t = (buf[0] << 8) | buf[1];
        uint16_t raw_h = (buf[3] << 8) | buf[4];
        *temperature = -45.0f + (175.0f * raw_t) / 65535.0f;
        *humidity = 100.0f * raw_h / 65535.0f;
        return 0;
    }
    return -1;
}

static void simulate_offset(float *temperature, float *humidity, time_t start_time) {
    double elapsed = difftime(time(NULL), start_time);
    double phase = 2.0 * M_PI * elapsed / SIMULATION_PERIOD_SEC;
    *temperature += 2.0f * sin(phase);
    *humidity += 5.0f * sin(phase);
}

static void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(log_file, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    time_t start_time = time(NULL);
    float temperature, humidity;

    while (!terminate) {
        if (read_sht35(&temperature, &humidity) == 0) {
            simulate_offset(&temperature, &humidity, start_time);
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed after %d retries; logging NaN\n", RETRY_COUNT);
            log_data(NAN, NAN);
        }
        gpioDelay(LOG_INTERVAL_US);
    }

    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

