        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (cmd >> 8) & 0xFF, cmd & 0xFF };
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

int i2c_read_data(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

int read_sdp810(int fd, float *pressure, float *temperature) {
    uint8_t data[9];

    if (i2c_write_cmd(fd, MEASURE_CMD) < 0) {
        fprintf(stderr, "Error: Failed to send measurement command.\n");
        return -1;
    }

    usleep(CONVERSION_DELAY_MS * 1000);

    if (i2c_read_data(fd, data, 9) < 0) {
        fprintf(stderr, "Error: Failed to read data from sensor.\n");
        return -1;
    }

    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch.\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "Error: Scale factor CRC mismatch.\n");
        return -1;
    }

    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t scale_factor = (data[6] << 8) | data[7];

    if (scale_factor == 0) {
        fprintf(stderr, "Error: Invalid scale factor (0).\n");
        return -1;
    }

    *pressure = (float)raw_pressure / scale_factor;
    *temperature = (float)raw_temperature / 200.0;

    return 0;
}

int log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        fprintf(stderr, "Error: Failed to write to CSV file.\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        perror("Error: Failed to acquire I2C bus access");
        close(i2c_fd);
        return 1;
    }

    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        perror("Error: Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float pressure, temperature;
        if (read_sdp810(i2c_fd, &pressure, &temperature) == 0) {
            if (log_data(fp, pressure, temperature) != 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }
        sleep(1);
    }

    if (fp) fclose(fp);
    if (i2c_fd >= 0) close(i2c_fd);

    printf("\nExiting gracefully.\n");
    return 0;
}

