#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT35_ADDR     0x44
#define MEASURE_CMD    0x2400   /* single-shot, high repeatability, no clock stretching */
#define MEASURE_DELAY  15000    /* microseconds (15 ms) */
#define SAMPLE_PERIOD  5        /* seconds */
#define CSV_FILE       "environment.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Read temperature (°C) and humidity (%RH) ---- */
static int read_sht35(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[2] = {
        (uint8_t)((MEASURE_CMD >> 8) & 0xFF),
        (uint8_t)(MEASURE_CMD & 0xFF)
    };
    uint8_t data[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed\n");
        return -1;
    }

    gpioDelay(MEASURE_DELAY);

    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed\n");
        return -1;
    }

    if (sht35_crc8(data, 2) != data[2]) {
        fprintf(stderr, "[ERROR] temperature CRC mismatch\n");
        return -1;
    }
    if (sht35_crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "[ERROR] humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

/* ---- Append a CSV row; write header if file is new/empty ---- */
static int log_data(const char *filename, float temperature, float humidity)
{
    int need_header = 0;

    /* Check whether file exists and is non-empty */
    FILE *chk = fopen(filename, "r");
    if (chk == NULL)
        need_header = 1;
    else {
        fseek(chk, 0, SEEK_END);
        if (ftell(chk) == 0)
            need_header = 1;
        fclose(chk);
    }

    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "[ERROR] cannot open %s for append\n", filename);
        return -1;
    }

    if (need_header)
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, SHT35_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHT35-DIS-B reader started (I2C bus %d, addr 0x%02X).\n", I2C_BUS, SHT35_ADDR);
    printf("Logging to %s every %d s. Press Ctrl+C to stop.\n", CSV_FILE, SAMPLE_PERIOD);

    while (g_running) {
        float temperature, humidity;

        if (read_sht35(g_i2c_handle, &temperature, &humidity) == 0) {
            printf("T = %.2f °C  RH = %.2f %%\n", temperature, humidity);
            if (log_data(CSV_FILE, temperature, humidity) != 0)
                fprintf(stderr, "[WARN] logging failed for this sample\n");
        } else {
            fprintf(stderr, "[WARN] sensor read failed; will retry next cycle\n");
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

