#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define POLL_TIMEOUT_MS 100
#define SAMPLE_INTERVAL_S 5

/* Si7021 commands */
#define CMD_MEASURE_HUMID_NOHOLD  0xF5
#define CMD_MEASURE_TEMP_NOHOLD   0xF3
#define CMD_READ_PREV_TEMP        0xE0
#define CMD_RESET                 0xFE

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, init 0x00 (Si7021 datasheet) */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* Write a single command byte to the Si7021 */
static int si7021_write_cmd(uint8_t cmd)
{
    if (write(g_i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write cmd 0x%02X failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read `len` bytes from the Si7021 (previous measurement result) */
static int si7021_read_data(uint8_t *buf, size_t len)
{
    ssize_t n = read(g_i2c_fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed (got %zd of %zu): %s\n", n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* Trigger a no-hold measurement and wait for completion */
static int si7021_measure(uint8_t cmd, uint16_t *raw)
{
    if (si7021_write_cmd(cmd) < 0)
        return -1;

    /* Poll until the master is ready (read returns 3 bytes: MSB, LSB, CRC) */
    uint8_t buf[3];
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (si7021_read_data(buf, 3) == 0) {
            if (crc8(buf, 2) != buf[2]) {
                fprintf(stderr, "CRC mismatch on measurement 0x%02X\n", cmd);
                return -1;
            }
            *raw = (uint16_t)((buf[0] << 8) | buf[1]);
            return 0;
        }
        usleep(1000); /* 1 ms */
    }
    fprintf(stderr, "Timeout waiting for measurement 0x%02X\n", cmd);
    return -1;
}

/* Read temperature and humidity using the paired-reading command 0xE0 */
static int si7021_read_combined(float *temp_c, float *hum_pct)
{
    uint16_t raw_h, raw_t;

    /* 0xE0 returns humidity then temperature (3 bytes each) */
    if (si7021_write_cmd(CMD_READ_PREV_TEMP) < 0)
        return -1;

    uint8_t buf[6];
    if (si7021_read_data(buf, 6) < 0)
        return -1;

    /* Verify CRC for both measurements */
    if (crc8(buf, 2) != buf[2] || crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on combined read\n");
        return -1;
    }

    raw_h = (uint16_t)((buf[0] << 8) | buf[1]);
    raw_t = (uint16_t)((buf[3] << 8) | buf[4]);

    *hum_pct = 125.0f * raw_h / 65536.0f - 6.0f;
    *temp_c  = 175.72f * raw_t / 65536.0f - 46.85f;

    /* Clamp humidity to valid range */
    if (*hum_pct < 0.0f)   *hum_pct = 0.0f;
    if (*hum_pct > 100.0f) *hum_pct = 100.0f;

    return 0;
}

static int si7021_reset(void)
{
    if (si7021_write_cmd(CMD_RESET) < 0)
        return -1;
    usleep(15000); /* 15 ms reset recovery */
    return 0;
}

static void log_data(float temp_c, float hum_pct, int ok)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        if (ok)
            fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, hum_pct);
        else
            fprintf(fp, "%s,ERROR,ERROR\n", ts);
    } else {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
    }
    fclose(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is new/empty */
    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (fp) {
            fprintf(fp, "timestamp,temperature_C,humidity_percent\n");
            fclose(fp);
        }
    } else {
        fseek(fp, 0, SEEK_END);
        if (ftell(fp) == 0) {
            fseek(fp, 0, SEEK_SET);
            fprintf(fp, "timestamp,temperature_C,humidity_percent\n");
        }
        fclose(fp);
    }

    printf("Si7021 greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);

    while (g_running) {
        float temp_c = 0.0f, hum_pct = 0.0f;
        int ok = 0;

        if (si7021_read_combined(&temp_c, &hum_pct) == 0) {
            ok = 1;
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp_c, hum_pct);
        } else {
            fprintf(stderr, "Sensor read failed; resetting Si7021...\n");
            if (si7021_reset() < 0)
                fprintf(stderr, "Reset failed; will retry next cycle.\n");
        }

        log_data(temp_c, hum_pct, ok);

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            usleep(100000);
    }

    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

