    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP800 pressure logger started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float pressure;
        if (read_sdp800(i2c_handle, &pressure) == 0) {
            log_pressure(log_file, pressure);
            printf("Pressure: %.2f Pa\n", pressure);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping log entry\n");
        }
        sleep(LOG_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

