#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* LPS33HW I2C address (SA0 tied to GND) */
#define LPS33HW_ADDR 0x5D

/* LPS33HW register addresses */
#define WHO_AM_I      0x0F
#define CTRL_REG1     0x10
#define PRESS_OUT_XL  0x28
#define PRESS_OUT_L   0x29
#define PRESS_OUT_H   0x2A
#define TEMP_OUT_L    0x2B
#define TEMP_OUT_H    0x2C

/* Expected chip ID */
#define LPS33HW_WHO_AM_I 0xB1

/* CTRL_REG1: BDU=1, ODR=10 Hz (0x10), active mode (0xB0) */
#define CTRL_REG1_VAL 0xB0

/* Globals for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped error line to stderr and the log file          */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(stderr, "%s, ERROR: %s (errno=%d: %s)\n",
            ts, msg, errno, strerror(errno));
    if (log_file) {
        fprintf(log_file, "%s, ERROR: %s (errno=%d: %s)\n",
                ts, msg, errno, strerror(errno));
        fflush(log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Read a single byte register; returns 0 on success, -1 on failure   */
/* ------------------------------------------------------------------ */
static int read_reg(uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        log_error("I2C read failed");
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte register; returns 0 on success, -1 on failure  */
/* ------------------------------------------------------------------ */
static int write_reg(uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 24-bit two's-complement value from three consecutive regs    */
/* ------------------------------------------------------------------ */
static int read_24bit(uint8_t reg_l, uint8_t reg_m, uint8_t reg_h,
                      int32_t *out)
{
    uint8_t xl, l, h;
    if (read_reg(reg_l, &xl) < 0) return -1;
    if (read_reg(reg_m, &l)  < 0) return -1;
    if (read_reg(reg_h, &h)  < 0) return -1;

    /* Assemble 24-bit two's-complement */
    int32_t raw = ((int32_t)h << 16) | ((int32_t)l << 8) | (int32_t)xl;
    if (raw & 0x00800000) raw |= 0xFF000000;  /* sign-extend */
    *out = raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit two's-complement value from two consecutive regs     */
/* ------------------------------------------------------------------ */
static int read_16bit(uint8_t reg_l, uint8_t reg_h, int16_t *out)
{
    uint8_t l, h;
    if (read_reg(reg_l, &l) < 0) return -1;
    if (read_reg(reg_h, &h) < 0) return -1;

    /* Assemble 16-bit two's-complement */
    int16_t raw = (int16_t)(((uint16_t)h << 8) | (uint16_t)l);
    *out = raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read pressure in hPa; returns 0 on success, -1 on failure          */
/* ------------------------------------------------------------------ */
static int read_pressure(float *pressure)
{
    int32_t raw;
    if (read_24bit(PRESS_OUT_XL, PRESS_OUT_L, PRESS_OUT_H, &raw) < 0)
        return -1;
    *pressure = (float)raw / 4096.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature in °C; returns 0 on success, -1 on failure        */
/* ------------------------------------------------------------------ */
static int read_temperature(float *temperature)
{
    int16_t raw;
    if (read_16bit(TEMP_OUT_L, TEMP_OUT_H, &raw) < 0)
        return -1;
    *temperature = 42.5f + (float)raw / 480.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a reading to the file                                           */
/* ------------------------------------------------------------------ */
static void log_data(float pressure, float temperature)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n",
            ts, pressure, temperature);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the LPS33HW address */
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n",
                LPS33HW_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify chip identity */
    uint8_t who_am_i = 0;
    if (read_reg(WHO_AM_I, &who_am_i) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    if (who_am_i != LPS33HW_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, LPS33HW_WHO_AM_I);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure sensor: BDU=1, ODR=10 Hz, active mode */
    if (write_reg(CTRL_REG1, CTRL_REG1_VAL) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_error("sigaction(SIGINT) failed");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        log_error("sigaction(SIGTERM) failed");
    }

    printf("LPS33HW environmental monitor started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (program_running) {
        float pressure, temperature;

        if (read_pressure(&pressure) == 0 &&
            read_temperature(&temperature) == 0) {
            log_data(pressure, temperature);
            printf("Pressure: %.2f hPa, Temperature: %.2f °C\n",
                   pressure, temperature);
        } else {
            log_error("Sensor read failed — skipping sample");
        }

        /* Sleep 1 second (microseconds) */
        gpioDelay(1000000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

