#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define TEMP_REG       0x00
#define LED_GPIO       17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f
#define POLL_DELAY_US  1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read temperature from the STLM75.
 * Returns 0 on success and stores the temperature in *out_temp.
 * Returns -1 on I2C error.
 */
static int read_temperature(float *out_temp)
{
    int raw = i2cReadWordData(g_i2c_handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", TEMP_REG, raw);
        return -1;
    }

    /*
     * pigpio returns the two I2C bytes in the host's native byte order
     * (little-endian on ARM).  The STLM75 sends the most-significant
     * byte first, so swap the bytes.
     */
    uint16_t swapped = (uint16_t)(((raw & 0xFF) << 8) | ((raw >> 8) & 0xFF));

    /*
     * 16-bit two's-complement, 9-bit resolution:
     *   bit 15 = sign
     *   bits 14..7 = temperature data (8 bits)
     *   bits 6..0  = always 0
     * Right-shift by 7 and divide by 2 to get degrees Celsius.
     */
    int16_t signed_val = (int16_t)swapped;
    *out_temp = (float)(signed_val >> 7) / 2.0f;
    return 0;
}

static float calculate_average(const float *buf, int size)
{
    float sum = 0.0f;
    for (int i = 0; i < size; i++)
        sum += buf[i];
    return sum / (float)size;
}

static void control_led(float avg_temp)
{
    if (avg_temp > TEMP_THRESHOLD)
        gpioWrite(LED_GPIO, 1);
    else
        gpioWrite(LED_GPIO, 0);
}

int main(void)
{
    float temperature_buffer[BUFFER_SIZE];
    int   buffer_index = 0;
    int   buffer_count = 0;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("STLM75 temperature monitor started (I2C bus %d, addr 0x%02X, LED GPIO %d)\n",
           I2C_BUS, I2C_ADDR, LED_GPIO);

    /* --- Main loop --- */
    while (g_running) {
        float temperature;

        if (read_temperature(&temperature) == 0) {
            temperature_buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            if (buffer_count < BUFFER_SIZE)
                buffer_count++;

            float avg = calculate_average(temperature_buffer, buffer_count);
            control_led(avg);

            printf("Temperature: %.2f C | Average: %.2f C | LED: %s\n",
                   temperature, avg,
                   (avg > TEMP_THRESHOLD) ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Read failed; skipping this sample\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

