static int scd30_read_command_with_crc(uint16_t cmd, uint8_t *buf, size_t len) {
    if (scd30_write_command(cmd) != 0)
        return -1;
    if (i2cReadDevice(i2c_handle, (char *)buf, (int)len) != (int)len) {
        fprintf(stderr, "Error: I2C read command 0x%04X with CRC failed\n", cmd);
        return -1;
    }
    /* Verify CRC for each 2-byte data word */
    for (size_t i = 0; i < len; i += 3) {
        if (scd30_crc8(&buf[i], 2) != buf[i + 2]) {
            fprintf(stderr, "Error: CRC mismatch at offset %zu\n", i);
            return -1;
        }
    }
    return 0;
}

static int scd30_start_periodic_measurement(int ambient_pressure_comp) {
    return scd30_write_command_with_args(0x0010, (uint16_t)ambient_pressure_comp);
}

static int scd30_stop_periodic_measurement(void) {
    return scd30_write_command(0x0104);
}

static int scd30_set_measurement_interval(uint16_t interval) {
    return scd30_write_command_with_args(0x4600, interval);
}

static int scd30_data_ready(uint8_t *ready) {
    uint8_t buf[3];
    if (scd30_read_command_with_crc(0x0202, buf, 3) != 0)
        return -1;
    *ready = (buf[0] << 8) | buf[1];
    return 0;
}

static int scd30_read_measurement(uint16_t *co2, float *temp, float *rh) {
    uint8_t buf[18];
    if (scd30_read_command_with_crc(0x0300, buf, 18) != 0)
        return -1;
    *co2 = (buf[0] << 8) | buf[1];
    uint16_t t_raw = (buf[6] << 8) | buf[7];
    uint16_t rh_raw = (buf[12] << 8) | buf[13];
    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh = 100.0f * (float)rh_raw / 65535.0f;
    return 0;
}

static void log_data(uint16_t co2, float temp, float rh) {
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(log_file, "%s,%u,%.2f,%.2f\n", ts, co2, temp, rh);
    fflush(log_file);
}

static void control_ventilation(uint16_t co2) {
    if (co2 < CO2_THRESHOLD_LOW) {
        printf("Ventilation: OFF (CO2=%u ppm)\n", co2);
    } else if (co2 < CO2_THRESHOLD_HIGH) {
        printf("Ventilation: LOW (CO2=%u ppm)\n", co2);
    } else {
        printf("Ventilation: HIGH (CO2=%u ppm)\n", co2);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        scd30_stop_periodic_measurement();
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error: fopen log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (scd30_set_measurement_interval(MEASUREMENT_INTERVAL_SEC) != 0) {
        fprintf(stderr, "Error: Failed to set measurement interval\n");
        cleanup();
        return 1;
    }

    if (scd30_start_periodic_measurement(0) != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement\n");
        cleanup();
        return 1;
    }

    printf("SCD30 monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint8_t ready = 0;
        if (scd30_data_ready(&ready) != 0) {
            fprintf(stderr, "Warning: data-ready poll failed, retrying...\n");
            sleep(1);
            continue;
        }
        if (!ready) {
            sleep(1);
            continue;
        }

        uint16_t co2;
        float temp, rh;
        if (scd30_read_measurement(&co2, &temp, &rh) != 0) {
            fprintf(stderr, "Warning: measurement read failed, retrying...\n");
            sleep(1);
            continue;
        }

        log_data(co2, temp, rh);
        control_ventilation(co2);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

