#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SDP32_ADDR 0x21
#define I2C_BUS 1
#define SDP32_CMD_CONT_MEAS 0x362F
#define SDP32_READ_LEN 9
#define DEFAULT_SAMPLING_INTERVAL_MS 1000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int sdp32_start_continuous(int handle) {
    uint8_t cmd[2] = { (SDP32_CMD_CONT_MEAS >> 8) & 0xFF, SDP32_CMD_CONT_MEAS & 0xFF };
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send continuous measurement command to SDP32.\n");
        return -1;
    }
    return 0;
}

static int sdp32_read_data(int handle, float *pressure, float *temperature) {
    uint8_t buffer[9];
    int bytes_read = i2cReadDevice(handle, (char *)buffer, SDP32_READ_LEN);
    if (bytes_read != SDP32_READ_LEN) {
        fprintf(stderr, "Error: I2C read failed (expected %d bytes, got %d).\n", SDP32_READ_LEN, bytes_read);
        return -1;
    }

    if (crc8(&buffer[0], 2) != buffer[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch.\n");
        return -1;
    }
    if (crc8(&buffer[3], 2) != buffer[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }
    if (crc8(&buffer[6], 2) != buffer[8]) {
        fprintf(stderr, "Error: Scale factor CRC mismatch.\n");
        return -1;
    }

    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];
    int16_t scale_factor = (buffer[6] << 8) | buffer[7];

    if (scale_factor == 0) {
        fprintf(stderr, "Error: Invalid scale factor (0).\n");
        return -1;
    }

    *pressure = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temperature / (float)scale_factor;

    return 0;
}

static void log_data(float pressure, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Pressure: %.2f Pa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    int sampling_interval_ms = DEFAULT_SAMPLING_INTERVAL_MS;

    if (argc > 1) {
        sampling_interval_ms = atoi(argv[1]);
        if (sampling_interval_ms <= 0) {
            fprintf(stderr, "Error: Sampling interval must be a positive integer.\n");
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X on bus %d (code %d).\n", SDP32_ADDR, I2C_BUS, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (sdp32_start_continuous(i2c_handle) != 0) {
        fprintf(stderr, "Error: Could not start continuous measurement on SDP32.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float pressure, temperature;
    while (running) {
        if (sdp32_read_data(i2c_handle, &pressure, &temperature) == 0) {
            log_data(pressure, temperature);
        } else {
            fprintf(stderr, "Error: Failed to read data from SDP32. Exiting.\n");
            break;
        }
        gpioDelay(sampling_interval_ms * 1000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

