/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int sdp810_read(int handle, float *pressure, float *temperature) {
    uint8_t cmd[2] = { MEASURE_CMD_MSB, MEASURE_CMD_LSB };
    uint8_t buf[9];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed (cmd 0x3615)\n");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    int bytes = i2cReadDevice(handle, (char *)buf, 9);
    if (bytes != 9) {
        fprintf(stderr, "Error: I2C read failed (got %d bytes, expected 9)\n", bytes);
        return -1;
    }

