    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "Error: CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    uint16_t scale_factor_pressure = (uint16_t)((buf[6] << 8) | buf[7]);
    uint16_t scale_factor_temperature = (uint16_t)((buf[8] << 8) | buf[9]);

    if (scale_factor_pressure == 0 || scale_factor_temperature == 0) {
        fprintf(stderr, "Error: Invalid scale factor (pressure=%u, temp=%u)\n",
                scale_factor_pressure, scale_factor_temperature);
        return -1;
    }

    *pressure = (float)raw_pressure / (float)scale_factor_pressure;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

