#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

/*
 * MLX90833 Absolute Pressure Sensor Reader
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (I2C bus 1)
 * Sensor:  Melexis MLX90833 (7-bit I2C address 0x60)
 *
 * The MLX90833 is a 32-bit absolute pressure sensor with a default
 * 7-bit I2C address of 0x60.  It supports a continuous read of the
 * pressure data register (0x00) which returns a 32-bit big-endian
 * value in Pa.
 */

#define I2C_BUS        1
#define MLX90833_ADDR  0x60
#define PRESSURE_REG   0x00
#define READ_INTERVAL  500000   /* microseconds (500 ms) */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (SIGINT / SIGTERM)            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 32-bit pressure data from the MLX90833                         */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_pressure(int handle, int32_t *pressure_out)
{
    char buf[4];
    int  bytes_read;

    /*
     * Point to the pressure data register (0x00) and read 4 bytes.
     * The MLX90833 returns a 32-bit big-endian value in Pa.
     */
    bytes_read = i2cReadI2CBlockData(handle, PRESSURE_REG, buf, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "I2C read error: expected 4 bytes, got %d (errno: %s)\n",
                bytes_read, strerror(errno));
        return -1;
    }

    /* Assemble big-endian 32-bit value */
    *pressure_out = ((int32_t)(uint8_t)buf[0] << 24) |
                    ((int32_t)(uint8_t)buf[1] << 16) |
                    ((int32_t)(uint8_t)buf[2] <<  8) |
                    ((int32_t)(uint8_t)buf[3]);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a pressure reading with a timestamp                              */
/* ------------------------------------------------------------------ */
static void log_pressure(int32_t pressure)
{
    time_t     rawtime;
    struct tm *timeinfo;
    char       timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime() failed: %s\n", strerror(errno));
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Pressure: %d Pa\n", timestamp, pressure);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to the MLX90833 */
    g_i2c_handle = i2cOpen(I2C_BUS, MLX90833_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, MLX90833_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90833 Pressure Sensor Reader\n");
    printf("I2C bus %d, address 0x%02X, reading every %d ms\n",
           I2C_BUS, MLX90833_ADDR, READ_INTERVAL / 1000);
    printf("Press Ctrl+C to exit.\n\n");
    fflush(stdout);

    /* Main acquisition loop */
    while (g_running) {
        int32_t pressure;

        if (read_pressure(g_i2c_handle, &pressure) == 0) {
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /*
         * Sleep in small increments so signals are caught promptly.
         * gpioDelay is a busy-wait delay; it is acceptable here
         * because the MLX90833 is a fast sensor and the loop
         * interval is 500 ms.
         */
        int remaining = READ_INTERVAL;
        while (remaining > 0 && g_running) {
            int chunk = (remaining > 100000) ? 100000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

