#define CMD_READ_CALIB 0x50
#define CMD_MEASURE_HP 0x40
#define MEASURE_DELAY_US 7000

#define READ_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

typedef struct {
    uint16_t c0;
    uint16_t c1;
    uint16_t c01;
    uint16_t c11;
    uint16_t c21;
    uint16_t c31;
} icp10101_calib_t;

static int read_calibration(int handle, icp10101_calib_t *cal) {
    char cmd = CMD_READ_CALIB;
    char buf[8];

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write calibration read command\n");
        return -1;
    }
    gpioDelay(1000);

    int n = i2cReadDevice(handle, buf, 8);
    if (n != 8) {
        fprintf(stderr, "Error: calibration read returned %d bytes (expected 8)\n", n);
        return -1;
    }

    cal->c0  = (uint16_t)((buf[0] << 8) | buf[1]);
    cal->c1  = (uint16_t)((buf[2] << 8) | buf[3]);
    cal->c01 = (uint16_t)((buf[4] << 8) | buf[5]);
    cal->c11 = (uint16_t)((buf[6] << 8) | buf[7]);

    /* Read second half of calibration coefficients (c21, c31) */
    cmd = 0x51;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write second calibration read command\n");
        return -1;
    }
    gpioDelay(1000);

    n = i2cReadDevice(handle, buf, 4);
    if (n != 4) {
        fprintf(stderr, "Error: second calibration read returned %d bytes (expected 4)\n", n);
        return -1;
    }

    cal->c21 = (uint16_t)((buf[0] << 8) | buf[1]);
    cal->c31 = (uint16_t)((buf[2] << 8) | buf[3]);

    return 0;
}

static int read_raw(int handle, uint16_t *raw_t, uint32_t *raw_p) {
    char cmd = CMD_MEASURE_HP;
    char buf[6];

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write measurement command\n");
        return -1;
    }
    gpioDelay(MEASURE_DELAY_US);

    int n = i2cReadDevice(handle, buf, 6);
    if (n != 6) {
        fprintf(stderr, "Error: measurement read returned %d bytes (expected 6)\n", n);
        return -1;
    }

    /* Check for sensor-absent / bus error: all 0xFF or all 0x00 */
    int all_ff = 1, all_zero = 1;
    for (int i = 0; i < 6; i++) {
        if (buf[i] != 0xFF) all_ff = 0;
        if (buf[i] != 0x00) all_zero = 0;
    }
    if (all_ff || all_zero) {
        fprintf(stderr, "Error: sensor returned all 0x%02X (absent or bus error)\n",
                all_ff ? 0xFF : 0x00);
        return -1;
    }

    *raw_t = (uint16_t)((buf[0] << 8) | buf[1]);
    *raw_p = (uint32_t)((buf[2] << 16) | (buf[3] << 8) | buf[4]);
    return 0;
}

static void compute_compensated(const icp10101_calib_t *cal,
                                uint16_t raw_t, uint32_t raw_p,
                                float *temp_c, float *press_pa) {
    /* Scale factors per datasheet */
    float scale_t = 1.0f;
    float scale_p = 1.0f;

    /* Temperature compensation */
    float t = (float)raw_t / 65535.0f;
    float t_comp = (float)cal->c0 * 0.5f + (float)cal->c1 * t;

    /* Pressure compensation */
    float p = (float)raw_p / 65535.0f;
    float p_comp = (float)cal->c01 + p * (float)cal->c11 +
                   p * p * (float)cal->c21 + p * p * p * (float)cal->c31;

    *temp_c = t_comp * scale_t;
    *press_pa = p_comp * scale_p;
}

static void log_reading(float temp_c, float press_pa) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        strncpy(ts, "UNKNOWN", sizeof(ts));
    }

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", ts, temp_c, press_pa);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, ICP_10101_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    icp10101_calib_t cal;
    if (read_calibration(handle, &cal) != 0) {
        fprintf(stderr, "Error: failed to read calibration data\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ICP-10101 calibration loaded. Starting periodic readings every %d s...\n",
           READ_INTERVAL_S);
    fflush(stdout);

    while (g_running) {
        uint16_t raw_t;
        uint32_t raw_p;

        if (read_raw(handle, &raw_t, &raw_p) == 0) {
            float temp_c, press_pa;
            compute_compensated(&cal, raw_t, raw_p, &temp_c, &press_pa);
            log_reading(temp_c, press_pa);
        } else {
            fprintf(stderr, "Warning: read failed, will retry next cycle\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

