static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *val) {
    if (i2c_write_byte(fd, reg) < 0)
        return -1;
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_pressure(int fd, float *pressure_kpa) {
    uint8_t msb, lsb;

    if (i2c_read_byte(fd, PRESSURE_MSB, &msb) < 0)
        return -1;
    if (i2c_read_byte(fd, PRESSURE_LSB, &lsb) < 0)
        return -1;

    uint16_t raw = ((uint16_t)msb << 8) | lsb;
    *pressure_kpa = (float)raw * SCALE_FACTOR;
    return 0;
}

