#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define PRESSURE_REG   0x00
#define PRESSURE_SCALE 0.01f
#define MIN_PRESSURE   200.0f
#define MAX_PRESSURE   250.0f
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_US      1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int initialize_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure_out)
{
    char buf[2];
    int  bytes;

    bytes = i2cReadI2CBlockData(g_i2c_handle, PRESSURE_REG, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "I2C read error (reg 0x%02X): got %d bytes\n",
                PRESSURE_REG, bytes);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *pressure_out = (float)raw * PRESSURE_SCALE;
    return 0;
}

static int log_pressure(float pressure)
{
    time_t     rawtime;
    struct tm  utc;
    char       timestamp[32];

    time(&rawtime);
    gmtime_r(&rawtime, &utc);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &utc);

    if (fprintf(g_log_file, "%s,%.2f\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(g_log_file);
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (initialize_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    if (fseek(g_log_file, 0, SEEK_END) == 0) {
        long sz = ftell(g_log_file);
        if (sz == 0) {
            fprintf(g_log_file, "timestamp,pressure_kPa\n");
            fflush(g_log_file);
        }
    }

    while (g_running) {
        float pressure;

        if (read_pressure(&pressure) != 0) {
            fprintf(stderr, "Read failed; attempting I2C reopen...\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            if (initialize_i2c() != 0) {
                fprintf(stderr, "I2C reopen failed; continuing to retry...\n");
            } else {
                if (read_pressure(&pressure) != 0) {
                    fprintf(stderr, "Second read attempt failed; skipping cycle\n");
                }
            }
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (log_pressure(pressure) != 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
            fprintf(stderr,
                    "WARNING: Tire pressure %.2f kPa outside safe range [%.0f-%.0f kPa]\n",
                    pressure, MIN_PRESSURE, MAX_PRESSURE);
        }

        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

