                if (read_pressure(&pressure) != 0) {
                    fprintf(stderr, "Second read attempt failed; skipping cycle\n");
                }
            }
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (log_pressure(pressure) != 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
            fprintf(stderr,
                    "WARNING: Tire pressure %.2f kPa outside safe range [%.0f-%.0f kPa]\n",
                    pressure, MIN_PRESSURE, MAX_PRESSURE);
        }

        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

