#include <unistd.h>
#include <pigpio.h>

#define HIH6130_ADDR 0x27
#define I2C_BUS 1
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576
#define SAMPLE_INTERVAL_SEC 5
#define MEASUREMENT_DELAY_US 40000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hih6130(int handle, float *temperature, float *humidity) {
    char buf[4];
    int result;

    /* Trigger a measurement by writing 0x00 to the sensor */
    result = i2cWriteByte(handle, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    /* Wait for the measurement to complete (typical 36.65 ms, max 40 ms) */
    gpioDelay(MEASUREMENT_DELAY_US);

    /* Read 4 bytes of data */
    result = i2cReadDevice(handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading data: expected 4 bytes, got %d\n", result);
        return -1;
    }

    /* Check status bits (bits 7 and 6 of the first byte) */
    if ((buf[0] & 0xC0) != 0x00) {
        fprintf(stderr, "Sensor status error: 0x%02X\n", buf[0] & 0xC0);
        return -1;
    }

    /* Convert raw data to temperature and humidity */
    uint16_t raw_temperature = ((uint16_t)(buf[0] & 0x3F) << 8) | (uint8_t)buf[1];
    uint16_t raw_humidity = ((uint16_t)buf[2] << 6) | ((uint16_t)buf[3] >> 2);

    *temperature = (raw_temperature * 165.0f) / 16383.0f - 40.0f;
    *humidity = (raw_humidity * 100.0f) / 16383.0f;

    return 0;
}

static void log_data(float temperature, float humidity) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    long file_size;

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fclose(fp);

    /* Check file size and rotate if necessary */
    fp = fopen(LOG_FILE, "r");
    if (fp != NULL) {
        fseek(fp, 0, SEEK_END);
        file_size = ftell(fp);
        fclose(fp);

        if (file_size > LOG_FILE_SIZE_LIMIT) {
            remove(LOG_FILE);
        }
    }
}

int main(void) {
    float temperature, humidity;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting environmental monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_hih6130(i2c_handle, &temperature, &humidity) == 0) {
            log_data(temperature, humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        /* Sleep for the sample interval, checking running flag every second */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    /* Clean up */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

