#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENT_GPIO 4
#define TICK_US 3
#define SYNC_TICKS 56
#define NIBBLE_MIN_TICKS 12
#define NIBBLE_MAX_TICKS 271
#define STATUS_NIBBLES 1
#define DATA_NIBBLES 3
#define CHECKSUM_NIBBLES 1
#define TOTAL_NIBBLES (STATUS_NIBBLES + DATA_NIBBLES + CHECKSUM_NIBBLES)
#define LOG_FILE "pressure_log.txt"
#define READ_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sent_nibble(int gpio, int *nibble) {
    int start_tick, end_tick, width;
    int level;

    level = gpioRead(gpio);
    if (level < 0) return -1;

    start_tick = gpioTick();
    while (gpioRead(gpio) == level) {
        if (gpioTick() - start_tick > READ_TIMEOUT_MS * 1000) return -2;
    }
    end_tick = gpioTick();
    width = end_tick - start_tick;

    if (width < NIBBLE_MIN_TICKS * TICK_US || width > NIBBLE_MAX_TICKS * TICK_US) return -3;

    *nibble = (width - NIBBLE_MIN_TICKS * TICK_US) / (TICK_US * 12);
    return 0;
}

static int read_sent_frame(int gpio, int *nibbles) {
    int level, start_tick, end_tick, width;
    int i;

    level = gpioRead(gpio);
    if (level < 0) return -1;

    start_tick = gpioTick();
    while (gpioRead(gpio) == level) {
        if (gpioTick() - start_tick > READ_TIMEOUT_MS * 1000) return -2;
    }
    end_tick = gpioTick();
    width = end_tick - start_tick;

    if (width < SYNC_TICKS * TICK_US || width > (SYNC_TICKS + 1) * TICK_US) return -3;

    for (i = 0; i < TOTAL_NIBBLES; i++) {
        if (read_sent_nibble(gpio, &nibbles[i]) != 0) return -4;
    }
    return 0;
}

static int validate_checksum(int *nibbles) {
    int sum = 0;
    for (int i = 0; i < TOTAL_NIBBLES - 1; i++) {
        sum += nibbles[i];
    }
    return (sum % 16 == nibbles[TOTAL_NIBBLES - 1]) ? 0 : -1;
}

static float convert_to_pressure(int *nibbles) {
    int raw = (nibbles[1] << 8) | (nibbles[2] << 4) | nibbles[3];
    return (float)raw * 0.1f + 100.0f;
}

static void log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Pressure: %.2f Pa\n", s, pressure);
    fclose(fp);
}

int main() {
    int nibbles[TOTAL_NIBBLES];
    float pressure;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENT_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENT_GPIO, PI_PUD_UP);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int ret = read_sent_frame(SENT_GPIO, nibbles);
        if (ret == 0) {
            if (validate_checksum(nibbles) == 0) {
                pressure = convert_to_pressure(nibbles);
                log_pressure(pressure);
            } else {
                fprintf(stderr, "SENT checksum error\n");
            }
        } else if (ret == -2) {
            fprintf(stderr, "SENT timeout: sensor absent or bus error\n");
        } else if (ret == -3) {
            fprintf(stderr, "SENT sync pulse width error\n");
        } else {
            fprintf(stderr, "SENT read error: %d\n", ret);
        }
        gpioDelay(100000);
    }

    gpioTerminate();
    return 0;
}

