#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define DEVICE_ID_REG 0x0F
#define EXPECTED_DEVICE_ID 0x0117
#define LOG_FILE "greenhouse_temps.dat"
#define SAMPLE_INTERVAL_SEC 60

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_device_id(int handle, uint16_t *device_id) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, DEVICE_ID_REG, buf, 2) != 2) {
        return -1;
    }
    *device_id = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int read_temperature(int handle, float *temperature) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, TEMP_REG, buf, 2) != 2) {
        return -1;
    }
    int16_t raw = (int16_t)((buf[1] << 8) | buf[0]);
    *temperature = (float)raw * 0.0078125f;
    return 0;
}

static int log_temperature(FILE *fp, float temperature) {
    if (fwrite(&temperature, sizeof(float), 1, fp) != 1) {
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", TMP117_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t device_id = 0;
    if (read_device_id(i2c_handle, &device_id) != 0) {
        fprintf(stderr, "Failed to read device ID from TMP117\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (device_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%04X (expected 0x%04X)\n", device_id, EXPECTED_DEVICE_ID);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("TMP117 detected (device ID: 0x%04X)\n", device_id);

    log_file = fopen(LOG_FILE, "ab");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Logging temperature readings to %s every %d seconds...\n", LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (!terminate) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
            if (log_temperature(log_file, temperature) != 0) {
                fprintf(stderr, "Failed to write temperature to log file\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature from TMP117\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

