#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 100
#define LOG_FILE "temperature_log.dat"
#define SAMPLE_INTERVAL_SEC 5

typedef struct {
    time_t timestamp;
    float temperature;
} TemperatureReading;

static TemperatureReading temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_temperature(int handle, float *temperature) {
    char reg = (char)TEMP_REG;
    char buf[2];

    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: Failed to write register address 0x%02X\n", TEMP_REG);
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read 2 bytes from temperature register\n");
        return -1;
    }

    int16_t raw_temp = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    *temperature = (float)raw_temp * 0.0078125f;
    return 0;
}

static void add_reading(float temperature) {
    temperature_buffer[buffer_index].timestamp = time(NULL);
    temperature_buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static int write_buffer_to_file(const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t written = fwrite(temperature_buffer, sizeof(TemperatureReading), (size_t)buffer_count, fp);
    if (written != (size_t)buffer_count) {
        fprintf(stderr, "Error: Only wrote %zu of %d readings to file\n", written, buffer_count);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing file");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at bus %d, address 0x%02X\n", I2C_BUS, TMP117_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGINT handler");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGTERM handler");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("TMP117 temperature logger started. Sampling every %d seconds. Press Ctrl+C to exit.\n", SAMPLE_INTERVAL_SEC);

    while (!terminate) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) == 0) {
            add_reading(temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Warning: Skipping sample due to read error\n");
        }

        if (write_buffer_to_file(LOG_FILE) != 0) {
            fprintf(stderr, "Warning: Failed to write buffer to file\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && !terminate; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (write_buffer_to_file(LOG_FILE) != 0) {
        fprintf(stderr, "Error: Failed to write final buffer to file\n");
    }
    cleanup();
    printf("Temperature logger stopped.\n");
    return EXIT_SUCCESS;
}

