        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SHTC3_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed for bus 1, addr 0x%02X: %s\n",
                SHTC3_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }

    float temperature, humidity;

    while (running) {
        if (read_shtc3(i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Warning: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, will retry next cycle\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            gpioDelay(1000000);
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

