        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
