#define TMP117_ADDR 0x48
#define TMP117_TEMP_REG 0x00
#define TMP117_RESOLUTION 0.0078125f
#define LOG_FILE "temperature_log.txt"
#define I2C_BUS 1
#define MAX_REINIT_ATTEMPTS 3
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d (pigpio error %d)\n",
                TMP117_ADDR, I2C_BUS, i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_temperature(float *temperature) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TMP117_TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: I2C read failed (returned %d)\n", result);
        return -1;
    }

    int16_t raw_temp = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (float)raw_temp * TMP117_RESOLUTION;

    return 0;
}

static int log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Temperature: %.2f C\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_i2c() != 0) {
        return 1;
    }

    int reinit_attempts = 0;

    while (running) {
        float temperature;

        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Warning: Failed to log temperature\n");
            }
            reinit_attempts = 0;
        } else {
            fprintf(stderr, "Error: Failed to read temperature. Reinitializing I2C...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioTerminate();

            reinit_attempts++;
            if (reinit_attempts > MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Error: Max reinitialization attempts (%d) reached. Exiting.\n", MAX_REINIT_ATTEMPTS);
                break;
            }

            if (initialize_i2c() != 0) {
                fprintf(stderr, "Error: I2C reinitialization failed. Exiting.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

