#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define DHT11_GPIO 4
#define LOG_FILE "dht11_readings.txt"
#define SAMPLE_INTERVAL_US 2000000
#define MAX_RETRIES 3

#define DHT11_START_LOW_US 20000
#define DHT11_START_HIGH_US 40
#define DHT11_RESP_LOW_US 80
#define DHT11_RESP_HIGH_US 80
#define DHT11_BIT_LOW_US 50
#define DHT11_TIMEOUT_US 200

#define DHT11_OK 0
#define DHT11_ERR_TIMEOUT 1
#define DHT11_ERR_CHECKSUM 2
#define DHT11_ERR_SENSOR_ABSENT 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(int code, const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,ERROR,%d,%s\n", ts, code, msg);
    fclose(fp);
}

static void log_reading(int humidity, int temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%d\n", ts, humidity, temperature);
    fclose(fp);
}

static int wait_for_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

static int read_dht11(int *humidity, int *temperature) {
    uint8_t data[5] = {0};
    int i;

    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioWrite(DHT11_GPIO, 0);
    gpioDelay(DHT11_START_LOW_US);
    gpioWrite(DHT11_GPIO, 1);
    gpioDelay(DHT11_START_HIGH_US);
    gpioSetMode(DHT11_GPIO, PI_INPUT);

    if (wait_for_level(DHT11_GPIO, 0, DHT11_TIMEOUT_US) < 0) return DHT11_ERR_TIMEOUT;
    if (wait_for_level(DHT11_GPIO, 1, DHT11_TIMEOUT_US) < 0) return DHT11_ERR_TIMEOUT;
    if (wait_for_level(DHT11_GPIO, 0, DHT11_TIMEOUT_US) < 0) return DHT11_ERR_TIMEOUT;

    for (i = 0; i < 40; i++) {
        if (wait_for_level(DHT11_GPIO, 1, DHT11_TIMEOUT_US) < 0) return DHT11_ERR_TIMEOUT;
        uint32_t start = gpioTick();
        if (wait_for_level(DHT11_GPIO, 0, DHT11_TIMEOUT_US) < 0) return DHT11_ERR_TIMEOUT;
        uint32_t duration = gpioTick() - start;
        data[i / 8] <<= 1;
        if (duration > DHT11_BIT_LOW_US) data[i / 8] |= 1;
    }

    if (wait_for_level(DHT11_GPIO, 1, DHT11_TIMEOUT_US) < 0) return DHT11_ERR_TIMEOUT;

    uint8_t checksum = (uint8_t)((data[0] + data[1] + data[2] + data[3]) & 0xFF);
    if (checksum != data[4]) return DHT11_ERR_CHECKSUM;

    *humidity = data[0];
    *temperature = data[2];
    return DHT11_OK;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    while (running) {
        int humidity, temperature;
        int result = read_dht11(&humidity, &temperature);

        if (result == DHT11_OK) {
            log_reading(humidity, temperature);
        } else {
            const char *msg;
            switch (result) {
                case DHT11_ERR_TIMEOUT: msg = "Timeout during DHT11 read"; break;
                case DHT11_ERR_CHECKSUM: msg = "Checksum mismatch"; break;
                case DHT11_ERR_SENSOR_ABSENT: msg = "Sensor absent (line stuck)"; break;
                default: msg = "Unknown DHT11 error"; break;
            }
            log_error(result, msg);
        }

        if (running) gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioTerminate();
    return 0;
}

