#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SHT31D_ADDR 0x44
#define MEASURE_CMD 0x2C06
#define LOG_FILE "sht31d_data.log"
#define I2C_BUS 1
#define READ_INTERVAL_SEC 5
#define MAX_RETRIES 3
#define MEASURE_DELAY_US 20000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht31d(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = { (MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF };
    uint8_t buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            retries++;
            gpioDelay(10000);
            continue;
        }
        gpioDelay(MEASURE_DELAY_US);
        if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
            retries++;
            gpioDelay(10000);
            continue;
        }
        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch\n");
            retries++;
            gpioDelay(10000);
            continue;
        }
        if (crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch\n");
            retries++;
            gpioDelay(10000);
            continue;
        }
        uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];
        *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
        *humidity = 100.0f * (float)h_raw / 65535.0f;
        return 0;
    }
    return -1;
}

static void log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, humidity);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,ERROR,%s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT31D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", SHT31D_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;

    while (!terminate) {
        if (read_sht31d(i2c_handle, &temperature, &humidity) == 0) {
            log_data(log_file, temperature, humidity);
        } else {
            log_error(log_file, "Sensor read failed after retries");
        }
        sleep(READ_INTERVAL_SEC);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

