#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x64
#define SENSOR2_ADDR 0x65
#define DEVICE_ID_REG 0x00
#define EXPECTED_DEVICE_ID 0x2A
#define RED_DATA_REG 0x64
#define GREEN_DATA_REG 0x66
#define BLUE_DATA_REG 0x68
#define LOG_FILE "cct_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "Error reading block from 0x%02X: %d\n", reg, rc);
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "Short read from 0x%02X: got %d, expected %u\n", reg, rc, len);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buf[6];
    if (read_block(handle, RED_DATA_REG, buf, 6) != 0) {
        return -1;
    }
    *red   = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    *green = (uint16_t)buf[2] | ((uint16_t)buf[3] << 8);
    *blue  = (uint16_t)buf[4] | ((uint16_t)buf[5] << 8);
    return 0;
}

static double calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    double x = (double)red / 65535.0;
    double y = (double)green / 65535.0;
    double z = (double)blue / 65535.0;
    double sum = x + y + z;
    if (sum < 1e-6) return 0.0;
    x /= sum; y /= sum; z /= sum;
    double n = (x - 0.3320) / (0.1858 - y);
    double cct = 449.0 * pow(n, 3) + 3525.0 * pow(n, 2) + 6823.3 * n + 5520.33;
    return cct;
}

static int log_cct(double cct) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(log_file, "%s,%.2f\n", ts, cct) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) { i2cClose(i2c_handle1); i2c_handle1 = -1; }
    if (i2c_handle2 >= 0) { i2cClose(i2c_handle2); i2c_handle2 = -1; }
    if (log_file) { fclose(log_file); log_file = NULL; }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 1 (0x%02X): %d\n", SENSOR1_ADDR, i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 2 (0x%02X): %d\n", SENSOR2_ADDR, i2c_handle2);
        i2cClose(i2c_handle1); i2c_handle1 = -1;
        gpioTerminate();
        return 1;
    }

    uint8_t id1, id2;
    if (read_register(i2c_handle1, DEVICE_ID_REG, &id1) != 0 || id1 != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Sensor 1 (0x%02X) not detected or wrong ID: 0x%02X\n", SENSOR1_ADDR, id1);
        cleanup();
        return 1;
    }
    if (read_register(i2c_handle2, DEVICE_ID_REG, &id2) != 0 || id2 != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Sensor 2 (0x%02X) not detected or wrong ID: 0x%02X\n", SENSOR2_ADDR, id2);
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
        fflush(log_file);
    }

    while (running) {
        uint16_t r1, g1, b1, r2, g2, b2;
        int ok1 = (read_sensor_data(i2c_handle1, &r1, &g1, &b1) == 0);
        int ok2 = (read_sensor_data(i2c_handle2, &r2, &g2, &b2) == 0);

        if (ok1 && ok2) {
            double cct1 = calculate_cct(r1, g1, b1);
            double cct2 = calculate_cct(r2, g2, b2);
            double avg = (cct1 + cct2) / 2.0;
            if (log_cct(avg) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
        } else {
            fprintf(stderr, "Sensor read error — skipping log entry\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

