#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define MLX90824_ADDR 0x60
#define PRESSURE_REG 0x0A2C
#define TEMPERATURE_REG 0x0A2E
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_SEC 2

/* Calibration constants (adjust per datasheet for your specific sensor) */
#define PRESSURE_MIN_KPA 0.0f
#define PRESSURE_MAX_KPA 800.0f
#define PRESSURE_OUTPUT_MIN 0.0f
#define PRESSURE_OUTPUT_MAX 32768.0f
#define TEMP_OUTPUT_MIN -40.0f
#define TEMP_OUTPUT_MAX 125.0f
#define TEMP_SCALE 0.01f
#define TEMP_OFFSET 40.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
}

static int read_register16(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    char data_buf[2];
    int result;

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    result = i2cWriteDevice(handle, reg_buf, 2);
    if (result != 0) {
        return -1;
    }

    result = i2cReadDevice(handle, data_buf, 2);
    if (result != 2) {
        return -1;
    }

    *value = ((uint16_t)(data_buf[0] & 0xFF) << 8) | (uint16_t)(data_buf[1] & 0xFF);
    return 0;
}

static float convert_pressure(uint16_t raw) {
    return PRESSURE_MIN_KPA +
           ((float)raw - PRESSURE_OUTPUT_MIN) *
           (PRESSURE_MAX_KPA - PRESSURE_MIN_KPA) /
           (PRESSURE_OUTPUT_MAX - PRESSURE_OUTPUT_MIN);
}

static float convert_temperature(uint16_t raw) {
    return (float)raw * TEMP_SCALE - TEMP_OFFSET;
}

static void log_data(float pressure, float temperature) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(log_file, "%s, Pressure: %.2f kPa, Temperature: %.2f C\n",
            ts, pressure, temperature);
    fflush(log_file);
}

static void log_error(const char *message) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(log_file, "%s, ERROR: %s\n", ts, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %d\n",
                I2C_BUS, MLX90824_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tire Pressure Monitoring System started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t raw_pressure = 0;
        uint16_t raw_temperature = 0;
        float pressure = 0.0f;
        float temperature = 0.0f;
        int read_ok = 1;

        if (read_register16(i2c_handle, PRESSURE_REG, &raw_pressure) != 0) {
            log_error("Failed to read pressure register");
            read_ok = 0;
        }

        if (read_ok && read_register16(i2c_handle, TEMPERATURE_REG, &raw_temperature) != 0) {
            log_error("Failed to read temperature register");
            read_ok = 0;
        }

        if (read_ok) {
            pressure = convert_pressure(raw_pressure);
            temperature = convert_temperature(raw_temperature);
            log_data(pressure, temperature);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

