#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LM75B_ADDR     0x48
#define TEMP_REG       0x00
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD_HIGH  28.0f
#define TEMP_THRESHOLD_LOW   26.0f
#define SAMPLE_INTERVAL_US   1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* Circular buffer of temperature readings (Celsius) */
static float g_temp_buffer[BUFFER_SIZE];
static int   g_buffer_index = 0;
static int   g_buffer_count = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature from LM75B.                                       */
/* Returns 0 on success (temp stored in *out), -1 on error.            */
/* ------------------------------------------------------------------ */
static int read_temperature(float *out)
{
    char reg = (char)TEMP_REG;
    char data[2];

    /* Point to the temperature register */
    if (i2cWriteDevice(g_i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice (reg select) failed\n");
        return -1;
    }

    /* Read 2 bytes of temperature data */
    if (i2cReadDevice(g_i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error: i2cReadDevice (temperature) failed\n");
        return -1;
    }

    /*
     * LM75B signed 9-bit format (0.5 °C resolution):
     *   bits 15..9  = sign bit + 8 data bits
     *   bits 8..0   = always 0
     * Combine into a 16-bit word, then shift right 7 to get the
     * signed 9-bit value, then scale by 0.5.
     */
    int16_t raw = (int16_t)(((uint16_t)data[0] << 8) | (uint8_t)data[1]);
    int16_t temp_code = raw >> 7;
    *out = (float)temp_code * 0.5f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Store temperature in the circular buffer.                           */
/* ------------------------------------------------------------------ */
static void store_temperature(float temp)
{
    g_temp_buffer[g_buffer_index] = temp;
    g_buffer_index = (g_buffer_index + 1) % BUFFER_SIZE;
    if (g_buffer_count < BUFFER_SIZE) {
        g_buffer_count++;
    }
}

/* ------------------------------------------------------------------ */
/* Compute the running average of the buffered readings.               */
/* ------------------------------------------------------------------ */
static float calculate_average(void)
{
    if (g_buffer_count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < g_buffer_count; i++) {
        sum += g_temp_buffer[i];
    }
    return sum / (float)g_buffer_count;
}

/* ------------------------------------------------------------------ */
/* Control the cooling fan with hysteresis.                            */
/* ------------------------------------------------------------------ */
static void control_fan(float avg_temp)
{
    static int fan_on = 0;

    if (avg_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON  (avg %.2f C)\n", avg_temp);
        } else {
            fprintf(stderr, "Error: gpioWrite(FAN_GPIO, 1) failed\n");
        }
    } else if (avg_temp < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (avg %.2f C)\n", avg_temp);
        } else {
            fprintf(stderr, "Error: gpioWrite(FAN_GPIO, 0) failed\n");
        }
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path.                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    /* Ensure fan is off before terminating pigpio */
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to LM75B */
    g_i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, LM75B_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure fan GPIO as output, initially off */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(FAN_GPIO=%d) failed\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(FAN_GPIO=%d, 0) failed\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LM75B temperature monitor started. Sampling every 1 s.\n");
    printf("Fan GPIO %d | High threshold %.1f C | Low threshold %.1f C\n",
           FAN_GPIO, TEMP_THRESHOLD_HIGH, TEMP_THRESHOLD_LOW);

    while (g_running) {
        float temperature;

        if (read_temperature(&temperature) == 0) {
            store_temperature(temperature);
            float avg = calculate_average();
            control_fan(avg);
            printf("Temperature: %.2f C | Average: %.2f C\n", temperature, avg);
        } else {
            fprintf(stderr, "Warning: temperature read failed, will retry next cycle\n");
        }

        /* Sleep 1 s, but wake early if a signal arrives */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

