    if (!led) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led, "stts2004-led", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("STTS2004 temperature monitor started (I2C 0x%02X, LED BCM %d).\n",
           STTS2004_ADDR, LED_PIN);

    while (g_running) {
        int16_t raw = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (i2c_read_reg16(fd, TEMP_REG, &raw) == 0) {
                ok = 1;
                break;
            }
            usleep(100000);
        }

        if (!ok) {
            fprintf(stderr, "Max I2C retries reached; exiting.\n");
            goto cleanup;
        }

        int16_t temp_code = raw >> 4;
        float temperature = (float)temp_code * 0.0625f;

        printf("Temperature: %.2f C\n", temperature);

        if (temperature > TEMP_THRESHOLD) {
            if (gpiod_line_set_value(led, 1) < 0) {
                fprintf(stderr, "Failed to set LED high: %s\n",
                        strerror(errno));
                goto cleanup;
            }
        } else if (temperature < TEMP_HYSTERESIS) {
            if (gpiod_line_set_value(led, 0) < 0) {
                fprintf(stderr, "Failed to set LED low: %s\n",
                        strerror(errno));
                goto cleanup;
            }
        }

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led) {
        gpiod_line_set_value(led, 0);
        gpiod_line_release(led);
    }
    if (chip)
        gpiod_chip_close(chip);
    if (fd >= 0)
        close(fd);

    printf("Exiting cleanly.\n");
    return ret;
}

