#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define MEASUREMENT_DELAY_US 45000
#define LOG_FILE "flow_data.txt"

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sdp800(int handle, float *pressure, float *temperature) {
    uint8_t cmd[2] = { (MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF };
    uint8_t buf[9];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to write measurement command to I2C device.\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "Error: Failed to read 9 bytes from I2C device.\n");
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch for differential pressure.\n");
        return -1;
    }

    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: CRC mismatch for temperature.\n");
        return -1;
    }

    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    int16_t raw_temperature = (buf[3] << 8) | buf[4];
    int16_t scale_factor = (buf[6] << 8) | buf[7];

    if (scale_factor == 0) {
        fprintf(stderr, "Error: Invalid scale factor (0).\n");
        return -1;
    }

    *pressure = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

static void log_data(float pressure, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s.\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Pressure: %.2f Pa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X on bus %d.\n", SDP800_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float pressure, temperature;

    while (!terminate) {
        if (read_sdp800(i2c_handle, &pressure, &temperature) == 0) {
            log_data(pressure, temperature);
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }
        gpioDelay(1000000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("\nProgram terminated gracefully.\n");
    return 0;
}

