#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define SAMPLE_SEC     60
#define MAX_RETRIES    3
#define MEASURE_DELAY  20000  /* microseconds */

/* Si7021 command bytes (no register addressing) */
#define CMD_MEASURE_RH_NOHOLD  0xF5
#define CMD_MEASURE_TEMP_NOHOLD 0xF3
#define CMD_READ_TEMP_PREV     0xE0
#define CMD_READ_ID_1B         0xFA  /* read electronic ID byte 1 */
#define CMD_READ_ID_2B         0x0F  /* read electronic ID byte 2 */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single command byte to the Si7021 */
static int si7021_write_cmd(int handle, uint8_t cmd)
{
    char buf[1] = { (char)cmd };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(handle, buf, 1) == 0)
            return 0;
        gpioDelay(10000);  /* 10 ms backoff */
    }
    return -1;
}

/* Read a 2-byte big-endian result from the Si7021 */
static int si7021_read_16bit(int handle, uint16_t *out)
{
    char buf[2];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cReadDevice(handle, buf, 2) == 2) {
            *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        gpioDelay(10000);
    }
    return -1;
}

/* Read temperature from the previous RH measurement (no-hold) */
static int si7021_read_temp_prev(int handle, float *temp_c)
{
    if (si7021_write_cmd(handle, CMD_READ_TEMP_PREV) != 0)
        return -1;
    gpioDelay(MEASURE_DELAY);
    uint16_t raw;
    if (si7021_read_16bit(handle, &raw) != 0)
        return -1;
    *temp_c = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

/* Read humidity + temperature (RH then TEMP from previous RH) */
static int si7021_read_humidity_temp(int handle, float *humidity, float *temp_c)
{
    /* Measure RH, no-hold */
    if (si7021_write_cmd(handle, CMD_MEASURE_RH_NOHOLD) != 0)
        return -1;
    gpioDelay(MEASURE_DELAY);

    uint16_t raw_hum;
    if (si7021_read_16bit(handle, &raw_hum) != 0)
        return -1;

    *humidity = (125.0f * (float)raw_hum / 65536.0f) - 6.0f;
    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    /* Read temperature from the previous RH measurement */
    return si7021_read_temp_prev(handle, temp_c);
}

/* Verify sensor presence by reading electronic ID byte 1 */
static int si7021_verify(int handle)
{
    if (si7021_write_cmd(handle, CMD_READ_ID_1B) != 0)
        return -1;
    gpioDelay(10000);
    char buf[1];
    if (i2cReadDevice(handle, buf, 1) != 1)
        return -1;
    uint8_t id1 = (uint8_t)buf[0];
    /* Si7021 returns 0x0D or 0x14 for electronic ID byte 1 */
    if (id1 != 0x0D && id1 != 0x14) {
        fprintf(stderr, "Si7021 not detected (ID byte 1 = 0x%02X)\n", id1);
        return -1;
    }
    return 0;
}

static void log_line(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s\n", msg);
        fflush(fp);
        fclose(fp);
    }
    printf("%s\n", msg);
}

static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    char full[256];
    snprintf(full, sizeof(full), "%s ERROR: %s", ts, msg);
    log_line(full);
    fprintf(stderr, "%s\n", full);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, SI7021_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (si7021_verify(g_i2c_handle) != 0) {
        log_error("Si7021 sensor not detected on I2C bus");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7021 sensor detected. Logging to %s every %d seconds.\n",
           LOG_FILE, SAMPLE_SEC);

    while (g_running) {
        float humidity = 0.0f, temp_c = 0.0f;

        if (si7021_read_humidity_temp(g_i2c_handle, &humidity, &temp_c) == 0) {
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

            char line[128];
            snprintf(line, sizeof(line), "%s,%.2f,%.2f", ts, temp_c, humidity);
            log_line(line);
        } else {
            log_error("Failed to read Si7021 sensor data");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_SEC && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

