#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HDC1080_ADDR 0x40
#define TEMP_REG 0x00
#define CONFIG_REG 0x02
#define LOG_FILE "enviro_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define CONVERSION_DELAY_US 20000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_hdc1080(int handle) {
    /*
     * Configuration register (0x02):
     *   Bit 12 (0x1000) = 1 -> Temperature resolution = 14-bit
     *   Bit 13 (0x2000) = 1 -> Humidity resolution = 14-bit
     *   Bit 14 (0x4000) = 1 -> Acquisition mode = Temperature then Humidity
     *   Bit 15 (0x8000) = 1 -> Heater off
     * Value = 0x7000
     */
    if (i2cWriteWordData(handle, CONFIG_REG, 0x7000) < 0) {
        fprintf(stderr, "Error writing configuration register\n");
        return -1;
    }
    return 0;
}

static int read_hdc1080(int handle, float *temperature, float *humidity) {
    char buf[4];
    uint16_t raw_temp, raw_humidity;

    /* Trigger a single measurement by writing pointer to temperature register */
    if (i2cWriteByte(handle, TEMP_REG) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    /* Wait for conversion to complete (14-bit temp + 14-bit humidity) */
    gpioDelay(CONVERSION_DELAY_US);

    /* Read 4 bytes: 2 bytes temperature, 2 bytes humidity */
    if (i2cReadDevice(handle, buf, 4) != 4) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    raw_temp = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    raw_humidity = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_humidity / 65536.0f) * 100.0f;

    return 0;
}

static void log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
}

int main(void) {
    float temperature, humidity;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at HDC1080 address */
    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize HDC1080 sensor */
    if (init_hdc1080(i2c_handle) < 0) {
        fprintf(stderr, "HDC1080 initialization failed (sensor may be absent)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("HDC1080 sensor initialized. Logging to %s every %d seconds.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);

    /* Main loop */
    while (running) {
        if (read_hdc1080(i2c_handle, &temperature, &humidity) == 0) {
            log_data(temperature, humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Skipping log entry.\n");
        }

        /* Sleep in 1-second increments to allow signal handler to interrupt promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

