#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define STS40_ADDR          0x44
#define I2C_BUS             "/dev/i2c-1"
#define LOG_FILE            "temperature_log.txt"
#define MEASURE_CMD_HIGH    0x2C
#define MEASURE_CMD_LOW     0xE0
#define CONVERSION_DELAY_MS 10
#define SAMPLE_INTERVAL_S   5

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;
static FILE *g_log = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd_high, uint8_t cmd_low) {
    uint8_t buf[2] = { cmd_high, cmd_low };
    ssize_t n = write(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C write failed: %s (wrote %zd bytes)\n",
                strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, int len) {
    ssize_t n = read(fd, buf, len);
    if (n != len) {
        fprintf(stderr, "I2C read failed: %s (got %zd of %d bytes)\n",
                strerror(errno), n, len);
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temp_c) {
    if (i2c_write_cmd(fd, MEASURE_CMD_HIGH, MEASURE_CMD_LOW) != 0)
        return -1;

    usleep(CONVERSION_DELAY_MS * 1000);

    uint8_t data[3];
    if (i2c_read_data(fd, data, 3) != 0)
        return -1;

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }

    uint16_t raw = (uint16_t)((data[0] << 8) | data[1]);
    *temp_c = -45.0f + 175.0f * (float)raw / 65535.0f;
    return 0;
}

static void log_temperature(FILE *log, float temp_c) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(log, "%s,%.2f\n", ts, temp_c);
    fflush(log);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return 1;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_fd, I2C_SLAVE, STS40_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                STS40_ADDR, strerror(errno));
        close(g_fd);
        return 1;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_fd);
        return 1;
    }

    while (g_running) {
        float temp_c;
        if (read_temperature(g_fd, &temp_c) == 0) {
            log_temperature(g_log, temp_c);
            printf("Temperature: %.2f C\n", temp_c);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    fprintf(stderr, "\nShutting down cleanly.\n");
    if (g_log) fclose(g_log);
    if (g_fd >= 0) close(g_fd);
    return 0;
}

