#define I2C_BUS        1
#define I2C_ADDR       0x25
#define LOG_FILE       "hvac_pressure_log.txt"
#define SAMPLE_US      1000000   /* 1 second */
#define MEASURE_US     50000     /* 50 ms  */

/* SDP810 continuous-measurement command */
static const uint8_t CMD_CONT_MEAS[2] = {0x36, 0x15};

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Timestamp helper ---- */
static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    localtime_r(&t, &tmv);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tmv);
}

/* ---- Read one sample from SDP810 ----
 * Returns 0 on success, -1 on I2C error, -2 on CRC error.
 */
static int read_sdp810(float *pressure, float *temperature)
{
    uint8_t buf[9];

    /* Send continuous-measurement command */
    if (i2cWriteDevice(g_i2c_handle, (char *)CMD_CONT_MEAS, 2) != 0) {
        fprintf(stderr, "I2C write failed\n");
        return -1;
    }

    gpioDelay(MEASURE_US);

    /* Read 9 bytes: pressure(2)+crc, temperature(2)+crc, scale(3) */
    if (i2cReadDevice(g_i2c_handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "I2C read failed\n");
        return -1;
    }

    /* CRC checks */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -2;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -2;
    }
    /* Scale factor CRC covers bytes 6-8 */
    if (crc8(&buf[6], 3) != buf[8]) {
        fprintf(stderr, "Scale-factor CRC mismatch\n");
        return -2;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);
    uint16_t scale       = (uint16_t)((buf[6] << 8) | buf[7]);

    if (scale == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -2;
    }

    *pressure    = (float)raw_pressure / (float)scale;
    *temperature = (float)raw_temp / 200.0f;

    return 0;
}

/* ---- Log a reading or error ---- */
static void log_data(float pressure, float temperature, int rc)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (rc == 0)
        fprintf(g_log_file, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    else
        fprintf(g_log_file, "%s,ERROR,%d\n", ts, rc);

    fflush(g_log_file);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen log");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring SDP810 at 0x%02X on bus %d. Press Ctrl+C to stop.\n",
           I2C_ADDR, I2C_BUS);

    while (g_running) {
        float pressure, temperature;
        int rc = read_sdp810(&pressure, &temperature);
        log_data(pressure, temperature, rc);
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

