#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <sys/types.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data/"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"

#define CMD_START_PERIODIC 0x21B1
#define CMD_STOP_PERIODIC 0x3F86
#define CMD_READ_MEASUREMENT 0xE000

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t running = 1;
static pthread_t logging_thread;

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("fopen error log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int result = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (result != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write cmd 0x%04X failed: %d", cmd, result);
        log_error(msg);
        return -1;
    }
    return 0;
}

static int i2c_read_data(uint8_t *data, int len) {
    int result = i2cReadDevice(i2c_handle, (char *)data, len);
    if (result != len) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C read failed: expected %d, got %d", len, result);
        log_error(msg);
        return -1;
    }
    return 0;
}

static int init_scd40(void) {
    if (i2c_write_cmd(CMD_START_PERIODIC) != 0) {
        log_error("Failed to start periodic measurement");
        return -1;
    }
    gpioDelay(1000000);
    return 0;
}

static int read_scd40_data(uint16_t *co2, float *temperature, float *humidity) {
    if (i2c_write_cmd(CMD_READ_MEASUREMENT) != 0)
        return -1;

    gpioDelay(10000);

    uint8_t data[9];
    if (i2c_read_data(data, 9) != 0)
        return -1;

    if (crc8(&data[0], 2) != data[2]) {
        log_error("CRC check failed for CO2");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        log_error("CRC check failed for temperature");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        log_error("CRC check failed for humidity");
        return -1;
    }

    *co2 = (data[0] << 8) | data[1];
    uint16_t temp_raw = (data[3] << 8) | data[4];
    uint16_t hum_raw = (data[6] << 8) | data[7];

    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity = 100.0f * (float)hum_raw / 65535.0f;

    return 0;
}

static void buffer_init(circular_buffer_t *buf) {
    buf->head = 0;
    buf->tail = 0;
    buf->count = 0;
    pthread_mutex_init(&buf->mutex, NULL);
}

static void buffer_add(circular_buffer_t *buf, sensor_data_t data) {
    pthread_mutex_lock(&buf->mutex);
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count == BUFFER_SIZE) {
        buf->tail = (buf->tail + 1) % BUFFER_SIZE;
    } else {
        buf->count++;
    }
    pthread_mutex_unlock(&buf->mutex);
}

static void buffer_get_all(circular_buffer_t *buf, sensor_data_t *out, int *out_count) {
    pthread_mutex_lock(&buf->mutex);
    *out_count = buf->count;
    int idx = buf->tail;
    for (int i = 0; i < buf->count; i++) {
        out[i] = buf->data[idx];
        idx = (idx + 1) % BUFFER_SIZE;
    }
    pthread_mutex_unlock(&buf->mutex);
}

static void *logging_thread_func(void *arg) {
    (void)arg;
    while (running) {
        sleep(60);
        if (!running) break;

        sensor_data_t data[BUFFER_SIZE];
        int count;
        buffer_get_all(&buffer, data, &count);

        if (count == 0) continue;

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char filename[256];
        snprintf(filename, sizeof(filename), "%sdata_%d-%02d-%02d_%02d-%02d-%02d.csv",
                 LOG_DIR, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                 tm.tm_hour, tm.tm_min, tm.tm_sec);

        struct stat st;
        if (stat(LOG_DIR, &st) == -1) {
            if (mkdir(LOG_DIR, 0755) == -1) {
                log_error("Failed to create log directory");
                continue;
            }
        }

        FILE *fp = fopen(filename, "w");
        if (!fp) {
            log_error("Failed to open log file");
            continue;
        }

        fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%)\n");
        for (int i = 0; i < count; i++) {
            struct tm *lt = localtime(&data[i].timestamp);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", lt);
            fprintf(fp, "%s,%u,%.2f,%.2f\n", ts, data[i].co2, data[i].temperature, data[i].humidity);
        }
        fclose(fp);
    }
    return NULL;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2c_write_cmd(CMD_STOP_PERIODIC);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    pthread_mutex_destroy(&buffer.mutex);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_scd40() != 0) {
        fprintf(stderr, "SCD40 initialisation failed\n");
        cleanup();
        return 1;
    }

    buffer_init(&buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        log_error("Failed to create logging thread");
        cleanup();
        return 1;
    }

    while (running) {
        uint16_t co2;
        float temperature, humidity;

        if (read_scd40_data(&co2, &temperature, &humidity) == 0) {
            sensor_data_t data;
            data.timestamp = time(NULL);
            data.co2 = co2;
            data.temperature = temperature;
            data.humidity = humidity;
            buffer_add(&buffer, data);
        }

        sleep(5);
    }

    pthread_join(logging_thread, NULL);

    sensor_data_t data[BUFFER_SIZE];
    int count;
    buffer_get_all(&buffer, data, &count);

    if (count > 0) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char filename[256];
        snprintf(filename, sizeof(filename), "%sdata_%d-%02d-%02d_%02d-%02d-%02d.csv",
                 LOG_DIR, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                 tm.tm_hour, tm.tm_min, tm.tm_sec);

        FILE *fp = fopen(filename, "w");
        if (fp) {
            fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%)\n");
            for (int i = 0; i < count; i++) {
                struct tm *lt = localtime(&data[i].timestamp);
                char ts[32];
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", lt);
                fprintf(fp, "%s,%u,%.2f,%.2f\n", ts, data[i].co2, data[i].temperature, data[i].humidity);
            }
            fclose(fp);
        } else {
            log_error("Failed to open final log file");
        }
    }

    cleanup();
    return 0;
}

