#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define ICP_10110_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define WHO_AM_I_VAL 0x08
#define CALIB_REG 0x05
#define CALIB_LEN 4
#define MEAS_REG 0x00
#define MEAS_LEN 6
#define SAMPLE_INTERVAL 5

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_calibration(int handle, uint16_t cal[4]) {
    char buf[CALIB_LEN];
    if (i2cReadI2CBlockData(handle, CALIB_REG, buf, CALIB_LEN) != CALIB_LEN) {
        fprintf(stderr, "Error: failed to read calibration coefficients\n");
        return -1;
    }
    for (int i = 0; i < 4; i++) {
        cal[i] = ((uint16_t)(uint8_t)buf[i] << 8) | (uint8_t)buf[i + 4];
    }
    return 0;
}

static int read_sensor_data(int handle, uint16_t cal[4], float *pressure, float *temperature) {
    char buf[MEAS_LEN];
    if (i2cWriteByteData(handle, MEAS_REG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(10000);
    if (i2cReadI2CBlockData(handle, MEAS_REG, buf, MEAS_LEN) != MEAS_LEN) {
        fprintf(stderr, "Error: failed to read sensor data\n");
        return -1;
    }
    uint32_t raw_p = ((uint32_t)(uint8_t)buf[0] << 16) |
                     ((uint32_t)(uint8_t)buf[1] << 8)  |
                     (uint32_t)(uint8_t)buf[2];
    uint32_t raw_t = ((uint32_t)(uint8_t)buf[3] << 16) |
                     ((uint32_t)(uint8_t)buf[4] << 8)  |
                     (uint32_t)(uint8_t)buf[5];
    float p_comp = (float)raw_p / 1048576.0f;
    float t_comp = (float)raw_t / 1048576.0f;
    *pressure = (cal[0] * 0.5f) + (cal[1] * p_comp) + (cal[2] * t_comp) + cal[3];
    *temperature = (cal[0] * 0.5f) + (cal[1] * t_comp) + (cal[2] * p_comp) + cal[3];
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, ICP_10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    int who = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n", who, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    uint16_t cal[4];
    if (read_calibration(i2c_handle, cal) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    printf("Weather station started. Press Ctrl+C to exit.\n");
    while (!terminate) {
        float pressure, temperature;
        if (read_sensor_data(i2c_handle, cal, &pressure, &temperature) == 0) {
            log_data(log_file, pressure, temperature);
            printf("Pressure: %.2f hPa, Temperature: %.2f C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Warning: sensor read failed, skipping sample\n");
        }
        for (int i = 0; i < SAMPLE_INTERVAL && !terminate; i++) {
            sleep(1);
        }
    }
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

