#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define ICP10125_ADDR        0x63
#define ICP10125_REG_OTP     0x66
#define ICP10125_CMD_MEASURE 0x4011
#define ICP10125_MEAS_DELAY  20000  /* microseconds */
#define ICP10125_POLL_DELAY  1000000 /* microseconds */

#define LED_PIN              17
#define PRESSURE_THRESHOLD   95000.0f
#define BLINK_HIGH_FREQ_MS   500
#define BLINK_LOW_FREQ_MS    100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

/* CRC-4 polynomial 0x03, init 0x04 — matches ICP-10125 datasheet */
static uint8_t crc4(const uint8_t *data, size_t len) {
    uint8_t crc = 0x04;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x08)
                crc = (crc << 1) ^ 0x03;
            else
                crc <<= 1;
        }
    }
    return crc & 0x0F;
}

static int i2c_write16(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write16 failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_calibration(int fd, uint16_t cal[4]) {
    uint8_t buf[8];
    if (i2c_write16(fd, ICP10125_REG_OTP) < 0)
        return -1;
    if (i2c_read_bytes(fd, buf, 8) < 0)
        return -1;
    for (int i = 0; i < 4; i++)
        cal[i] = (uint16_t)((buf[2 * i] << 8) | buf[2 * i + 1]);
    return 0;
}

static int read_sensor(int fd, const uint16_t cal[4],
                       float *pressure, float *temperature) {
    if (i2c_write16(fd, ICP10125_CMD_MEASURE) < 0)
        return -1;
    usleep(ICP10125_MEAS_DELAY);

    uint8_t buf[6];
    if (i2c_read_bytes(fd, buf, 6) < 0)
        return -1;

    if (crc4(&buf[0], 2) != (buf[2] & 0x0F)) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc4(&buf[3], 2) != (buf[5] & 0x0F)) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    uint16_t raw_p = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t raw_t = (uint16_t)((buf[3] << 8) | buf[4]);

    /* InvenSense ICP-10125 conversion formulas (datasheet) */
    float p_comp = (float)raw_p - 32768.0f;
    float t_comp = (float)raw_t - 32768.0f;

    float p_lut = (float)cal[0] + (float)cal[1] * p_comp +
                  (float)cal[2] * p_comp * p_comp +
                  (float)cal[3] * p_comp * p_comp * p_comp;
    float t_lut = (float)cal[0] + (float)cal[1] * t_comp +
                  (float)cal[2] * t_comp * t_comp +
                  (float)cal[3] * t_comp * t_comp * t_comp;

    *pressure = p_lut * 100.0f;
    *temperature = t_lut * 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                ICP10125_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    uint16_t cal[4];
    if (read_calibration(fd, cal) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Cannot open gpiochip4: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    if (gpiod_line_request_output(led, "icp10125-led", 0) < 0) {
        fprintf(stderr, "Cannot request LED line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    int led_state = 0;
    int high_freq = 0;

    while (running) {
        float pressure, temperature;
        if (read_sensor(fd, cal, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
                   pressure, temperature);

            if (pressure < PRESSURE_THRESHOLD) {
                if (!high_freq) {
                    high_freq = 1;
                    led_state = 0;
                }
                usleep(BLINK_LOW_FREQ_MS * 1000);
                if (led_state == 0) {
                    gpiod_line_set_value(led, 1);
                    led_state = 1;
                } else {
                    gpiod_line_set_value(led, 0);
                    led_state = 0;
                }
                usleep(BLINK_LOW_FREQ_MS * 1000);
            } else {
                if (high_freq) {
                    high_freq = 0;
                    led_state = 0;
                }
                usleep(BLINK_HIGH_FREQ_MS * 1000);
                if (led_state == 0) {
                    gpiod_line_set_value(led, 1);
                    led_state = 1;
                } else {
                    gpiod_line_set_value(led, 0);
                    led_state = 0;
                }
                usleep(BLINK_HIGH_FREQ_MS * 1000);
            }
        } else {
            fprintf(stderr, "Sensor read error — blinking LED off\n");
            gpiod_line_set_value(led, 0);
            usleep(ICP10125_POLL_DELAY);
        }
    }

    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(fd);
    return 0;
}

