#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS        1
#define MLX90614_ADDR  0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO       18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW  28.0
#define LOG_FILE       "temperature_log.txt"
#define POLL_INTERVAL  2
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, uint8_t reg, float *temp_c) {
    int raw;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        raw = i2cReadWordData(handle, reg);
        if (raw >= 0) {
            int16_t signed_raw = (int16_t)raw;
            *temp_c = (float)signed_raw * 0.02f - 273.15f;
            return 0;
        }
        fprintf(stderr, "I2C read error (reg 0x%02X): %s. Retry %d/%d\n",
                reg, strerror(errno), retries + 1, MAX_RETRIES);
        retries++;
        if (retries < MAX_RETRIES) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    fprintf(stderr, "Failed to read temperature from register 0x%02X after %d retries.\n",
            reg, MAX_RETRIES);
    return -1;
}

static void log_temperature(float ambient, float object) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Ambient: %.2f C, Object: %.2f C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            ambient, object);
    fclose(fp);
}

static void control_fan(float object_temp) {
    static int fan_on = 0;

    if (object_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON (Object temp: %.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Failed to turn fan ON: %s\n", strerror(errno));
        }
    } else if (object_temp < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (Object temp: %.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Failed to turn fan OFF: %s\n", strerror(errno));
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, MLX90614_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", FAN_GPIO, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO %d to LOW: %s\n", FAN_GPIO, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float ambient_temp = 0.0f;
        float object_temp = 0.0f;

        if (read_temperature(i2c_handle, AMBIENT_TEMP_REG, &ambient_temp) != 0) {
            fprintf(stderr, "Skipping log due to ambient temperature read failure.\n");
        } else if (read_temperature(i2c_handle, OBJECT_TEMP_REG, &object_temp) != 0) {
            fprintf(stderr, "Skipping log due to object temperature read failure.\n");
        } else {
            log_temperature(ambient_temp, object_temp);
            control_fan(object_temp);
        }

        sleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

