#include <arpa/inet.h>
#include <pigpio.h>

#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define I2C_BUS 1
#define PORT 8080
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 10000
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int server_fd = -1;

typedef struct {
    float temperature;
    float humidity;
    int valid;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n", I2C_BUS, SHT40_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static sensor_data_t read_sensor_data(void) {
    sensor_data_t data = {0.0f, 0.0f, 0};
    unsigned char cmd = MEASURE_CMD;
    unsigned char buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, (char *)&cmd, 1) != 0) {
            fprintf(stderr, "I2C write error (attempt %d/%d): %s\n", retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            gpioDelay(100000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(i2c_handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read error (attempt %d/%d): %s\n", retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            gpioDelay(100000);
            continue;
        }

        unsigned int t_raw = ((unsigned int)buf[0] << 8) | buf[1];
        unsigned int rh_raw = ((unsigned int)buf[3] << 8) | buf[4];

        data.temperature = -45.0f + 175.0f * ((float)t_raw / 65535.0f);
        data.humidity = -6.0f + 125.0f * ((float)rh_raw / 65535.0f);

        if (data.humidity < 0.0f) data.humidity = 0.0f;
        if (data.humidity > 100.0f) data.humidity = 100.0f;

        data.valid = 1;
        return data;
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return data;
}

static void handle_client(int client_socket, sensor_data_t data) {
    char response[512];
    int len = snprintf(response, sizeof(response),
        "HTTP/1.1 200 OK\r\n"
        "Content-Type: text/html\r\n"
        "Connection: close\r\n"
        "\r\n"
        "<!DOCTYPE html>\n"
        "<html lang=\"en\">\n"
        "<head>\n"
