        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);

        if (client_socket < 0) {
            if (errno == EINTR && !running) break;
            perror("accept");
            continue;
        }

        sensor_data_t sensor_data = read_sensor_data();

        if (sensor_data.valid) {
            handle_client(client_socket, sensor_data);
        } else {
            const char *err_html =
                "HTTP/1.1 500 Internal Server Error\r\n"
                "Content-Type: text/html\r\n"
                "Connection: close\r\n"
                "\r\n"
                "<!DOCTYPE html>\n"
                "<html><body><h1>Error: Sensor read failed</h1></body></html>\n";
            send(client_socket, err_html, strlen(err_html), 0);
            close(client_socket);
        }
    }

    cleanup();
    return 0;
}

