#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define TMP102_ADDR 0x48
#define TEMP_REG 0x00
#define LOG_FILE "temperature_log.csv"
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temperature) {
    int raw = i2cReadWordData(handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature register: %d\n", raw);
        return -1;
    }

    /* TMP102 returns data left-justified in 16 bits; shift right 4 to get 12-bit value */
    int16_t temp_raw = (int16_t)((raw << 8) >> 8);

    /* Sign-extend 12-bit two's complement to 16-bit */
    if (temp_raw & 0x0800) {
        temp_raw |= 0xF000;
    }

    *temperature = (float)temp_raw * 0.0625f;
    return 0;
}

static int log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d, addr 0x%02X: %d\n",
                I2C_BUS, TMP102_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Smart Greenhouse Climate Monitor started. Logging to %s every %d seconds.\n",
           LOG_FILE, READ_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) == 0) {
            printf("Temperature: %.2f C\n", temperature);
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Warning: failed to log temperature reading.\n");
            }
        } else {
            fprintf(stderr, "Warning: temperature read failed, skipping log entry.\n");
        }

        /* Sleep in 1-second increments so SIGINT is caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    printf("\nShutting down...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

