#define HDC2010_ADDR        0x40
#define REG_TEMP_LOW        0x00
#define REG_TEMP_HIGH       0x01
#define REG_HUM_LOW         0x02
#define REG_HUM_HIGH        0x03
#define REG_MEAS_CONFIG     0x0E
#define REG_CONFIG          0x0F

#define MEAS_TRIGGER        0x01
#define MEAS_BUSY_MASK      0x01
#define MAX_RETRIES         3
#define POLL_TIMEOUT_US     500000
#define POLL_STEP_US        10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int write_reg(uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, val, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int read_word(uint8_t low_reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (read_reg(low_reg, &lo) < 0) return -1;
    if (read_reg(low_reg + 1, &hi) < 0) return -1;
    *out = ((uint16_t)hi << 8) | lo;
    return 0;
}

static int trigger_measurement(void)
{
    if (write_reg(REG_MEAS_CONFIG, MEAS_TRIGGER) < 0) return -1;
    return 0;
}

static int wait_measurement_done(void)
{
    uint8_t cfg;
    int elapsed = 0;
    while (elapsed < POLL_TIMEOUT_US) {
        if (read_reg(REG_MEAS_CONFIG, &cfg) < 0) return -1;
        if ((cfg & MEAS_BUSY_MASK) == 0) return 0;
        gpioDelay(POLL_STEP_US);
        elapsed += POLL_STEP_US;
    }
    fprintf(stderr, "Measurement timeout (sensor may be absent or unresponsive)\n");
    return -1;
}

static int read_sensor(float *temperature, float *humidity)
{
    if (trigger_measurement() < 0) return -1;
    if (wait_measurement_done() < 0) return -1;

    uint16_t raw_temp, raw_hum;
    if (read_word(REG_TEMP_LOW, &raw_temp) < 0) return -1;
    if (read_word(REG_HUM_LOW, &raw_hum) < 0) return -1;

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_hum  / 65536.0f) * 100.0f;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at addr 0x%02X: %d\n", HDC2010_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure: heater disabled, 14-bit resolution (default) */
    if (write_reg(REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure HDC2010\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temperature, humidity;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_sensor(&temperature, &humidity) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(100000); /* 100 ms backoff before retry */
        }

        if (ok) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor after %d attempts\n", MAX_RETRIES);
        }

        /* Sleep 5 s in 100 ms slices so SIGINT is caught promptly */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

