#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define PROFILE_FILE "profile.txt"
#define LOG_FILE "reflow_log.csv"
#define SPI_SPEED_HZ 1000000
#define SPI_BITS_PER_WORD 8
#define SPI_MODE 0
#define MAX_PROFILE_ENTRIES 100
#define SAMPLE_INTERVAL_SEC 1
#define MAX_SPI_RETRIES 3

typedef struct {
    int time_seconds;
    float target_temperature;
} ProfileEntry;

static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static FILE *log_file = NULL;
static ProfileEntry profile[MAX_PROFILE_ENTRIES];
static int profile_size = 0;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_profile(const char *filename, ProfileEntry *profile, int max_entries) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening profile file: %s\n", strerror(errno));
        return -1;
    }

    int count = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp) && count < max_entries) {
        if (line[0] == '#' || line[0] == '\n' || line[0] == '\0') continue;
        if (sscanf(line, "%d %f", &profile[count].time_seconds, &profile[count].target_temperature) != 2) {
            fprintf(stderr, "Error parsing profile line %d: %s", count + 1, line);
            fclose(fp);
            return -1;
        }
        count++;
    }
    fclose(fp);
    return count;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    int speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    relay_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!relay_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip); chip = NULL; return -1;
    }

    if (gpiod_line_request_output(relay_line, "reflow_oven", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip); chip = NULL; relay_line = NULL; return -1;
    }

    return 0;
}

static int read_temperature(float *temperature) {
    unsigned char tx[2] = {0x00, 0x00};
    unsigned char rx[2] = {0x00, 0x00};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
