#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <dirent.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define RELAY_PIN 17
#define PWM_PIN 18
#define TEMP_SENSOR_DIR "/sys/bus/w1/devices/"
#define LOG_FILE "greenhouse.log"
#define SAMPLE_INTERVAL 5
#define MAX_SENSORS 10

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *pwm_line = NULL;

typedef struct {
    float Kp, Ki, Kd;
    float setpoint;
    float integral, previous_error;
} PIDController;

static PIDController pid = {1.0, 0.1, 0.01, 25.0, 0.0, 0.0};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0;
    for (int i = 0; i < len; i++) {
        unsigned char byte = data[i];
        for (int j = 0; j < 8; j++) {
            unsigned char mix = (crc ^ byte) & 0x01;
            crc >>= 1;
            if (mix) crc ^= 0x8C;
            byte >>= 1;
        }
    }
    return crc;
}

static int read_temperature(const char *sensor_id, float *temp_out) {
    char path[256];
    snprintf(path, sizeof(path), "%s%s/w1_slave", TEMP_SENSOR_DIR, sensor_id);

    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    char line1[256], line2[256];
    if (!fgets(line1, sizeof(line1), fp) || !fgets(line2, sizeof(line2), fp)) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for sensor %s\n", sensor_id);
        return -1;
    }

    char *t = strstr(line2, "t=");
    if (!t) {
        fprintf(stderr, "Temperature data not found for sensor %s\n", sensor_id);
        return -1;
    }

    long raw = strtol(t + 2, NULL, 10);
    *temp_out = (float)raw / 1000.0;
    return 0;
}

static float calculate_pid(float current_temp) {
    float error = pid.setpoint - current_temp;
    pid.integral += error;
    float derivative = error - pid.previous_error;
    float output = pid.Kp * error + pid.Ki * pid.integral + pid.Kd * derivative;
    pid.previous_error = error;
    return output;
}

static void set_pwm_duty(float duty) {
    if (duty < 0.0) duty = 0.0;
    if (duty > 1.0) duty = 1.0;
    int val = (int)(duty * 255);
    if (gpiod_line_set_value(pwm_line, val) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(errno));
    }
}

static void control_heater(float pid_output) {
    if (pid_output > 0.0) {
        if (gpiod_line_set_value(relay_line, 1) < 0) {
            fprintf(stderr, "Failed to enable relay: %s\n", strerror(errno));
        }
        set_pwm_duty(pid_output);
    } else {
        if (gpiod_line_set_value(relay_line, 0) < 0) {
            fprintf(stderr, "Failed to disable relay: %s\n", strerror(errno));
        }
        set_pwm_duty(0.0);
    }
}

static void log_data(float avg_temp, float setpoint, float pid_output, float duty) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", ts, avg_temp, setpoint, pid_output, duty);
    fflush(log_file);
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (pwm_line) {
        gpiod_line_set_value(pwm_line, 0);
        gpiod_line_release(pwm_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    pid.setpoint = atof(argv[1]);
    pid.Kp = atof(argv[2]);
    pid.Ki = atof(argv[3]);
    pid.Kd = atof(argv[4]);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        fclose(log_file);
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    pwm_line = gpiod_chip_get_line(chip, PWM_PIN);
    if (!relay_line || !pwm_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "greenhouse", 0) < 0 ||
        gpiod_line_request_output(pwm_line, "greenhouse", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    DIR *dir = opendir(TEMP_SENSOR_DIR);
    if (!dir) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_SENSOR_DIR, strerror(errno));
        cleanup();
        return 1;
    }

    char *sensor_ids[MAX_SENSORS];
    int num_sensors = 0;
    struct dirent *ent;
    while ((ent = readdir(dir)) != NULL && num_sensors < MAX_SENSORS) {
        if (strstr(ent->d_name, "28-") == ent->d_name) {
            sensor_ids[num_sensors] = strdup(ent->d_name);
            num_sensors++;
        }
    }
    closedir(dir);

    if (num_sensors == 0) {
        fprintf(stderr, "No DS18B20 sensors found. Ensure w1-gpio and w1-therm are loaded.\n");
        cleanup();
        return 1;
    }

    printf("Greenhouse heater control started. %d sensor(s) found.\n", num_sensors);

    while (running) {
        float temps[MAX_SENSORS];
        int valid_readings = 0;
        float sum = 0.0;

        for (int i = 0; i < num_sensors; i++) {
            if (read_temperature(sensor_ids[i], &temps[i]) == 0) {
                sum += temps[i];
                valid_readings++;
            } else {
                fprintf(stderr, "Sensor %s read failed.\n", sensor_ids[i]);
            }
        }

        if (valid_readings == 0) {
            fprintf(stderr, "All sensors failed. Skipping cycle.\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float avg_temp = sum / valid_readings;
        float pid_output = calculate_pid(avg_temp);
        control_heater(pid_output);
        log_data(avg_temp, pid.setpoint, pid_output, pid_output);

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    for (int i = 0; i < num_sensors; i++) free(sensor_ids[i]);
    return 0;
}

