#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <syslog.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>

#define I2C_DEVICE      "/dev/i2c-1"
#define HTU21D_ADDR     0x40
#define API_ENDPOINT    "api.example.com"
#define API_PORT        80
#define POLL_INTERVAL   60
#define MAX_RETRIES     3

#define HTU21D_CMD_HUMIDITY_HOLD  0xE5
#define HTU21D_CMD_TEMP_HOLD      0xE3
#define HTU21D_CMD_SOFT_RESET     0xFE

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        syslog(LOG_ERR, "I2C write cmd 0x%02X failed: %s", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_humidity(int fd, float *humidity) {
    uint8_t buf[3];

    if (i2c_write_cmd(fd, HTU21D_CMD_HUMIDITY_HOLD) < 0)
        return -1;

    usleep(50000);

    if (i2c_read_data(fd, buf, 3) < 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        syslog(LOG_ERR, "Humidity CRC mismatch");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    raw &= 0xFFFC;
    *humidity = -6.0f + 125.0f * (float)raw / 65536.0f;

    if (*humidity < 0.0f || *humidity > 100.0f) {
        syslog(LOG_ERR, "Humidity out of range: %.2f", *humidity);
        return -1;
    }

    return 0;
}

static int post_data(const char *endpoint, int port, float humidity) {
    char json[128];
    snprintf(json, sizeof(json), "{\"humidity\": %.2f}", humidity);

    struct addrinfo hints = {0};
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    struct addrinfo *res = NULL;
    int ret = getaddrinfo(endpoint, NULL, &hints, &res);
    if (ret != 0) {
        syslog(LOG_ERR, "getaddrinfo failed: %s", gai_strerror(ret));
        return -1;
    }

    struct sockaddr_in addr;
    memcpy(&addr, res->ai_addr, res->ai_addrlen);
    addr.sin_port = htons(port);

    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        syslog(LOG_ERR, "socket failed: %s", strerror(errno));
        freeaddrinfo(res);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        syslog(LOG_ERR, "connect failed: %s", strerror(errno));
        close(sock);
        freeaddrinfo(res);
        return -1;
    }

    char request[256];
    snprintf(request, sizeof(request),
             "POST /humidity HTTP/1.1\r\n"
             "Host: %s\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: %zu\r\n"
             "Connection: close\r\n"
             "\r\n"
             "%s", endpoint, strlen(json), json);

    size_t total = strlen(request);
    size_t sent = 0;
    while (sent < total) {
        ssize_t w = write(sock, request + sent, total - sent);
        if (w < 0) {
            if (errno == EINTR) continue;
            syslog(LOG_ERR, "HTTP write failed: %s", strerror(errno));
            close(sock);
            freeaddrinfo(res);
            return -1;
        }
        sent += (size_t)w;
    }

    char resp[1024];
    ssize_t r = read(sock, resp, sizeof(resp) - 1);
    if (r < 0) {
        syslog(LOG_ERR, "HTTP read failed: %s", strerror(errno));
        close(sock);
        freeaddrinfo(res);
        return -1;
    }
    resp[r] = '\0';

    int status = 0;
    if (sscanf(resp, "HTTP/%*d.%*d %d", &status) != 1) {
        syslog(LOG_ERR, "HTTP parse failed");
        close(sock);
        freeaddrinfo(res);
        return -1;
    }

    close(sock);
    freeaddrinfo(res);

    if (status < 200 || status >= 300) {
        syslog(LOG_ERR, "HTTP POST failed: %d", status);
        return -1;
    }

    syslog(LOG_INFO, "Humidity %.2f%% posted successfully", humidity);
    return 0;
}

int main(void) {
    openlog("htu21d_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Cannot open %s: %s", I2C_DEVICE, strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Cannot set I2C slave 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(fd);
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "HTU21D monitor started (addr 0x%02X)", HTU21D_ADDR);

    while (g_running) {
        float humidity = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_humidity(fd, &humidity) == 0) {
