            usleep(100000);
        }

        if (ok) {
            if (post_data(API_ENDPOINT, API_PORT, humidity) != 0) {
                syslog(LOG_ERR, "POST failed for humidity %.2f", humidity);
            }
        } else {
            syslog(LOG_ERR, "All humidity read attempts failed");
        }

        for (int i = 0; i < POLL_INTERVAL && g_running; i++)
            sleep(1);
    }

    syslog(LOG_INFO, "Shutting down");
    close(fd);
    closelog();
    return 0;
}

