#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_CALIB 0x88
#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_CMD 0xB6
#define PRESSURE_THRESHOLD_HIGH 1020.0
#define PRESSURE_THRESHOLD_LOW 980.0
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 2000000
#define CONVERSION_DELAY_US 10000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

static bmp280_calib_data calib;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(int handle, bmp280_calib_data *c) {
    uint8_t buf[24];
    if (i2cReadI2CBlockData(handle, BMP280_REG_CALIB, (char *)buf, 24) != 24) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    c->dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    c->dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    c->dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    c->dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    c->dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    c->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    c->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    c->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    c->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    c->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    c->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    c->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int32_t compensate_temperature(int32_t adc_T) {
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)calib.dig_T1 << 1))) * ((int32_t)calib.dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)calib.dig_T1)) * ((adc_T >> 4) - ((int32_t)calib.dig_T1))) >> 12) * ((int32_t)calib.dig_T3)) >> 14;
    t_fine = var1 + var2;
    return (t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_pressure(int32_t adc_P) {
    int32_t var1, var2;
    uint32_t p;
    var1 = ((int32_t)t_fine >> 1) - 64000;
    var2 = (((var1 >> 2) * (var1 >> 2)) >> 11) * ((int32_t)calib.dig_P6);
    var2 = var2 + ((var1 * ((int32_t)calib.dig_P5)) << 1);
    var2 = (var2 >> 2) + (((int32_t)calib.dig_P4) << 16);
    var1 = (((((var1 >> 2) * (var1 >> 2)) >> 13) * ((int32_t)calib.dig_P3)) >> 3) + ((((int32_t)calib.dig_P2) * var1) >> 1);
    var1 = (var1 >> 18) + (((int32_t)calib.dig_P1) << 11);
    if (var1 == 0) return 0;
    p = (((uint32_t)(((1 << 31) - adc_P) - (var2 >> 12))) * 6250) / (uint32_t)var1;
    var1 = (((int32_t)calib.dig_P9) * (int32_t)((p >> 3) * (p >> 3))) >> 12;
    var2 = (((int32_t)(p >> 2)) * ((int32_t)calib.dig_P8)) >> 13;
    p = (uint32_t)((int32_t)p + ((var1 + var2 + calib.dig_P7) >> 4));
    return p;
}

static int read_bmp280(int handle, float *pressure) {
    uint8_t cmd = 0x01;
    uint8_t data[6];
    int32_t adc_T, adc_P;

    if (i2cWriteI2CBlockData(handle, BMP280_REG_CTRL_MEAS, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);

    if (i2cReadI2CBlockData(handle, BMP280_REG_PRESS_MSB, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read pressure data\n");
        return -1;
    }

    adc_P = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
    adc_T = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | (data[5] >> 4);

    int32_t temp = compensate_temperature(adc_T);
    uint32_t press = compensate_pressure(adc_P);
    *pressure = (float)press / 100.0f;
    (void)temp;
    return 0;
}

static int log_pressure_breach(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open log file\n");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Pressure: %.2f hPa\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

static int initialize_bmp280(int handle) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int id = i2cReadByteData(handle, BMP280_REG_ID);
        if (id < 0) {
            fprintf(stderr, "Error: Failed to read chip ID (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }
        if (id != BMP280_CHIP_ID) {
            fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X)\n", id, BMP280_CHIP_ID);
            retries++;
            gpioDelay(100000);
            continue;
        }
        if (i2cWriteByteData(handle, BMP280_REG_RESET, BMP280_RESET_CMD) < 0) {
            fprintf(stderr, "Error: Failed to reset sensor (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }
        gpioDelay(2000);
        if (read_calibration_data(handle, &calib) != 0) {
            retries++;
            gpioDelay(100000);
            continue;
        }
        return 0;
    }
    return -1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (initialize_bmp280(i2c_handle) != 0) {
        fprintf(stderr, "Error: BMP280 initialization failed after %d retries\n", MAX_RETRIES);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("BMP280 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float pressure;
        if (read_bmp280(i2c_handle, &pressure) == 0) {
            printf("Pressure: %.2f hPa\n", pressure);
            if (pressure > PRESSURE_THRESHOLD_HIGH || pressure < PRESSURE_THRESHOLD_LOW) {
                if (log_pressure_breach(pressure) != 0) {
                    fprintf(stderr, "Warning: Failed to log pressure breach\n");
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read BMP280 data\n");
            if (i2c_handle >= 0) i2cClose(i2c_handle);
            i2c_handle = -1;
            int retries = 0;
            while (running && retries < MAX_RETRIES) {
                gpioDelay(1000000);
                i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
                if (i2c_handle >= 0) {
                    if (initialize_bmp280(i2c_handle) == 0) break;
                    i2cClose(i2c_handle);
                    i2c_handle = -1;
                }
                retries++;
            }
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: I2C re-initialization failed after %d retries\n", MAX_RETRIES);
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

