/*
 * Raspberry Pi 4B - Sensor Data Logger
 * TMP117 (I2C 0x48), AHT20 (I2C 0x38), PIR on GPIO 17
 * Daily CSV logging with libgpiod + Linux I2C ioctl.
 * Build: gcc -o logger logger.c -lgpiod -lrt
 */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define TMP117_ADDR        0x48
#define TMP117_TEMP_REG    0x00
#define TMP117_LSB         0.0078125f

#define AHT20_ADDR         0x38
#define AHT20_INIT_CMD     0xBE
#define AHT20_MEASURE_CMD  0xAC
#define AHT20_MEASURE_ARG  0x33
#define AHT20_BUSY_BIT     0x80

#define PIR_GPIO_CHIP      "gpiochip4"
#define PIR_GPIO_LINE      17

#define I2C_DEV            "/dev/i2c-1"
#define LOG_DIR            "./logs"
#define SAMPLE_INTERVAL_S  1
#define I2C_RETRIES        3
#define I2C_RETRY_DELAY_MS 10

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void msleep(unsigned ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

/* ---------- I2C helpers ---------- */
static int i2c_write(int fd, const uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) return -1;
    return 0;
}

/* ---------- TMP117 ---------- */
static int tmp117_read(int fd, float *temp_c) {
    uint8_t reg = TMP117_TEMP_REG;
    uint8_t data[2];

    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (i2c_write(fd, &reg, 1) < 0) { msleep(I2C_RETRY_DELAY_MS); continue; }
        if (i2c_read(fd, data, 2) < 0) { msleep(I2C_RETRY_DELAY_MS); continue; }
        int16_t raw = (int16_t)((data[0] << 8) | data[1]);
        *temp_c = raw * TMP117_LSB;
        return 0;
    }
    return -1;
}

/* ---------- AHT20 ---------- */
static int aht20_read(int fd, float *humidity) {
    uint8_t init_cmd[3] = { AHT20_INIT_CMD, 0x08, 0x00 };
    uint8_t measure_cmd[3] = { AHT20_MEASURE_CMD, AHT20_MEASURE_ARG, 0x00 };
    uint8_t data[7];

    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (i2c_write(fd, init_cmd, 3) < 0) { msleep(I2C_RETRY_DELAY_MS); continue; }
        msleep(20);

        if (i2c_write(fd, measure_cmd, 3) < 0) { msleep(I2C_RETRY_DELAY_MS); continue; }

        for (int i = 0; i < 10; i++) {
            if (i2c_read(fd, data, 7) < 0) { msleep(I2C_RETRY_DELAY_MS); break; }
            if (!(data[0] & AHT20_BUSY_BIT)) break;
            msleep(10);
            if (i == 9) return -1;
        }

        uint32_t hum_raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
        *humidity = ((float)hum_raw / 1048576.0f) * 100.0f;
        return 0;
    }
    return -1;
}

/* ---------- Logging ---------- */
static int open_log_file(FILE **fp) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char date[16];
    strftime(date, sizeof(date), "%Y-%m-%d", tm);

    char path[256];
    snprintf(path, sizeof(path), "%s/%s.csv", LOG_DIR, date);

    int need_header = (access(path, F_OK) != 0);
    *fp = fopen(path, "a");
    if (!*fp) { perror("fopen"); return -1; }
    if (need_header) {
        fprintf(*fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
        fflush(*fp);
    }
    return 0;
}

static void log_data(FILE *fp, float temp, float hum, int motion) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, temp, hum, motion);
    fflush(fp);
}

int main(void) {
    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (mkdir(LOG_DIR, 0755) == -1 && errno != EEXIST) {
        perror("mkdir");
        return 1;
    }

    /* Open I2C bus */
    int i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) { perror("open i2c"); return 1; }

    /* Open GPIO chip and request PIR line */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(PIR_GPIO_CHIP);
    if (!chip) { perror("gpiod_chip_open"); close(i2c_fd); return 1; }
    struct gpiod_line *pir = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!pir) { perror("gpiod_chip_get_line"); gpiod_chip_close(chip); close(i2c_fd); return 1; }
    if (gpiod_line_request_input(pir, "pir-sensor") < 0) {
        perror("gpiod_line_request_input");
        gpiod_chip_close(chip); close(i2c_fd); return 1;
    }

    FILE *log_fp = NULL;
    if (open_log_file(&log_fp) < 0) {
        gpiod_line_release(pir); gpiod_chip_close(chip); close(i2c_fd); return 1;
    }

    printf("Logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char new_date[16];
        strftime(new_date, sizeof(new_date), "%Y-%m-%d", tm);

        char cur_path[256];
        snprintf(cur_path, sizeof(cur_path), "%s/%s.csv", LOG_DIR, new_date);

        /* Reopen on day boundary to avoid stale file handle */
        if (access(cur_path, F_OK) == 0) {
            fclose(log_fp);
            if (open_log_file(&log_fp) < 0) break;
        }

        /* TMP117 */
        if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
            perror("ioctl TMP117");
        } else {
            float temp;
            if (tmp117_read(i2c_fd, &temp) < 0) {
                fprintf(stderr, "TMP117 read failed\n");
            } else {
                /* AHT20 */
                if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
                    perror("ioctl AHT20");
                } else {
                    float hum;
                    if (aht20_read(i2c_fd, &hum) < 0) {
                        fprintf(stderr, "AHT20 read failed\n");
                        hum = -1.0f;
                    }
                    log_data(log_fp, temp, hum, 0);
                    continue;
                }
            }
        }

        /* Fallback: log with sentinels */
        log_data(log_fp, -999.0f, -1.0f, 0);
        msleep(SAMPLE_INTERVAL_S * 1000);
    }

    /* Cleanup */
    fclose(log_fp);
    gpiod_line_release(pir);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("\nExiting gracefully.\n");
    return 0;
}

