#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_RANGE 255
#define SAMPLE_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read /proc/stat and return user + system CPU time in seconds. */
static double get_cpu_time(void)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("fopen(/proc/stat)");
        return 0.0;
    }

    char line[256];
    double user = 0.0, nice = 0.0, sys = 0.0, idle = 0.0;

    if (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "cpu ", 4) == 0) {
            if (sscanf(line, "cpu  %lf %lf %lf %lf", &user, &nice, &sys, &idle) == 4) {
                fclose(fp);
                return user + nice + sys + idle;
            }
        }
    }

    fclose(fp);
    return 0.0;
}

/* Map CPU load (0.0 = idle, 1.0 = 100% busy) to a color gradient. */
static void load_to_color(double load, int *r, int *g, int *b)
{
    if (load < 0.0) load = 0.0;
    if (load > 1.0) load = 1.0;

    if (load < 0.5) {
        *r = 0;
        *g = (int)(255.0 * load * 2.0);
        *b = 0;
    } else {
        *r = (int)(255.0 * (load - 0.5) * 2.0);
        *g = (int)(255.0 * (1.0 - (load - 0.5) * 2.0));
        *b = 0;
    }
}

/* Set PWM duty cycle for a channel, clamping to 0-255. */
static void set_channel(int pin, int value)
{
    if (value < 0) value = 0;
    if (value > PWM_RANGE) value = PWM_RANGE;
    gpioPWM(pin, value);
}

/* Turn LED off (full off for common-anode). */
static void led_off(void)
{
    set_channel(RED_PIN, 0);
    set_channel(GREEN_PIN, 0);
    set_channel(BLUE_PIN, 0);
}

int main(void)
{
    /* Install signal handlers for clean shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    /* Configure PWM pins. */
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    /* Ensure LED starts off. */
    led_off();

    double prev_cpu = get_cpu_time();
    if (prev_cpu < 0.0) {
        fprintf(stderr, "Initial CPU sample failed; exiting\n");
        led_off();
        gpioTerminate();
        return 1;
    }

    while (g_running) {
        double cpu = get_cpu_time();
        if (cpu < 0.0) {
            fprintf(stderr, "CPU sample failed; continuing\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double delta = cpu - prev_cpu;
        double load = delta;  /* seconds elapsed = load (idle delta is 0, busy delta is positive) */
        prev_cpu = cpu;

        int r, g, b;
        load_to_color(load, &r, &g, &b);

        set_channel(RED_PIN, r);
        set_channel(GREEN_PIN, g);
        set_channel(BLUE_PIN, b);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown: LED off, pigpio terminate. */
    led_off();
    gpioTerminate();
    return 0;
}

