    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

static bmp280_calib_data calib;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(int handle, bmp280_calib_data *c) {
    char buf[24];
    if (i2cReadI2CBlockData(handle, BMP280_REG_CALIB, buf, 24) != 24) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    c->dig_T1 = (uint16_t)((buf[1] << 8) | buf[0]);
    c->dig_T2 = (int16_t)((buf[3] << 8) | buf[2]);
    c->dig_T3 = (int16_t)((buf[5] << 8) | buf[4]);
    c->dig_P1 = (uint16_t)((buf[7] << 8) | buf[6]);
    c->dig_P2 = (int16_t)((buf[9] << 8) | buf[8]);
    c->dig_P3 = (int16_t)((buf[11] << 8) | buf[10]);
    c->dig_P4 = (int16_t)((buf[13] << 8) | buf[12]);
    c->dig_P5 = (int16_t)((buf[15] << 8) | buf[14]);
    c->dig_P6 = (int16_t)((buf[17] << 8) | buf[16]);
    c->dig_P7 = (int16_t)((buf[19] << 8) | buf[18]);
    c->dig_P8 = (int16_t)((buf[21] << 8) | buf[20]);
    c->dig_P9 = (int16_t)((buf[23] << 8) | buf[22]);
    return 0;
}

static int32_t compensate_temperature(int32_t adc_T) {
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)calib.dig_T1 << 1))) * ((int32_t)calib.dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)calib.dig_T1)) * ((adc_T >> 4) - ((int32_t)calib.dig_T1))) >> 12) * ((int32_t)calib.dig_T3)) >> 14;
    t_fine = var1 + var2;
    return (t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_pressure(int32_t adc_P) {
    int64_t var1, var2, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)calib.dig_P6;
    var2 = var2 + ((var1 * (int64_t)calib.dig_P5) << 17);
    var2 = var2 + (((int64_t)calib.dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)calib.dig_P3) >> 8) + ((var1 * (int64_t)calib.dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)calib.dig_P1) >> 33;
    if (var1 == 0) return 0;
    p = 1048576 - adc_P;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)calib.dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)calib.dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)calib.dig_P7) << 4);
    return (uint32_t)p;
}

static int read_bmp280(int handle, float *temperature, float *pressure) {
    char buf[6];
    int32_t adc_T, adc_P;

    if (i2cWriteByteData(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_MEAS\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2cReadI2CBlockData(handle, BMP280_REG_PRESS_MSB, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read data registers\n");
        return -1;
    }

    adc_P = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | ((int32_t)buf[2] >> 4);
    adc_T = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | ((int32_t)buf[5] >> 4);

    int32_t temp = compensate_temperature(adc_T);
    uint32_t pres = compensate_pressure(adc_P);

    *temperature = (float)temp / 100.0f;
    *pressure = (float)pres / 100.0f;
    return 0;
}

static int send_udp_data(const char *json_string, const char *ip, int port) {
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Error: Invalid address %s\n", ip);
        return -1;
    }

    if (sendto(udp_socket, json_string, strlen(json_string), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error: sendto failed");
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_ID);
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_calibration_data(i2c_handle, &calib) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error: socket creation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float temperature, pressure;
        if (read_bmp280(i2c_handle, &temperature, &pressure) == 0) {
            char json_string[128];
            snprintf(json_string, sizeof(json_string), "{\"temperature\": %.2f, \"pressure\": %.2f}", temperature, pressure);
            if (send_udp_data(json_string, UDP_SERVER_IP, UDP_SERVER_PORT) != 0) {
                fprintf(stderr, "Warning: UDP send failed\n");
            }
        } else {
            fprintf(stderr, "Warning: BMP280 read failed\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (udp_socket >= 0) close(udp_socket);
    gpioTerminate();
    return 0;
}

