#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define FAN_GPIO        18
#define SPI_CHANNEL     0
#define SPI_SPEED       500000
#define SPI_FLAGS       0
#define PWM_FREQUENCY   1000
#define PWM_RANGE       255
#define BUFFER_SIZE     20
#define SAMPLE_PERIOD   1.0

#define TEMP_MIN        25.0
#define TEMP_MID        40.0
#define TEMP_MAX        60.0

#define FAULT_OC        0x01
#define FAULT_SC        0x02
#define FAULT_GLITCH    0x04

typedef struct {
    time_t timestamp;
    float  temperature;
    int    duty;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int      buffer_index = 0;
static int      buffer_count = 0;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void add_to_buffer(float temp, int duty) {
    log_buffer[buffer_index].timestamp  = time(NULL);
    log_buffer[buffer_index].temperature = temp;
    log_buffer[buffer_index].duty        = duty;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("\n--- Log Buffer (%d entries) ---\n", buffer_count);
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm = localtime(&log_buffer[idx].timestamp);
        if (tm) strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
        else    snprintf(ts, sizeof(ts), "<unknown>");
        printf("[%s] Temp: %.2f C, Duty: %d\n", ts, log_buffer[idx].temperature, log_buffer[idx].duty);
    }
    printf("-------------------------------\n");
}

static int read_max31855(int handle, float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault detected (bit 16 set)\n");
        if (raw & FAULT_OC)  fprintf(stderr, "  Open circuit\n");
        if (raw & FAULT_SC)  fprintf(stderr, "  Short to GND\n");
        if (raw & FAULT_GLITCH) fprintf(stderr, "  Glitch filter\n");
        return -1;
    }

    int16_t temp_raw = (int16_t)(raw >> 18);
    *temperature = temp_raw * 0.25f;
    return 0;
}

static int calculate_duty(float temp) {
    if (temp < TEMP_MIN) return 0;
    if (temp < TEMP_MID) return (int)((temp - TEMP_MIN) / (TEMP_MID - TEMP_MIN) * 50.0f);
    if (temp < TEMP_MAX) return (int)(50.0f + (temp - TEMP_MID) / (TEMP_MAX - TEMP_MID) * 150.0f);
    return 255;
}

static int set_fan_speed(int duty) {
    if (duty < 0)   duty = 0;
    if (duty > 255) duty = 255;
    if (gpioPWM(FAN_GPIO, duty) != 0) {
        fprintf(stderr, "gpioPWM failed for duty %d\n", duty);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_max31855(spi_handle, &temperature) == 0) {
            int duty = calculate_duty(temperature);
            if (set_fan_speed(duty) == 0) {
                add_to_buffer(temperature, duty);
            }
        }
        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    set_fan_speed(0);
    spiClose(spi_handle);
    print_buffer();
    gpioTerminate();
    return EXIT_SUCCESS;
}

