#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define OSS 3

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_word(int handle, uint8_t reg, int16_t *value) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, (char *)value, 1) != 1) return -1;
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    return (i2cWriteDevice(handle, buf, 2) == 2) ? 0 : -1;
}

static int read_calibration_data(int handle) {
    if (i2c_read_word(handle, BMP180_REG_CAL_AC1, &ac1) < 0) return -1;
    if (i2c_read_word(handle, BMP180_REG_CAL_AC2, &ac2) < 0) return -1;
    if (i2c_read_word(handle, BMP180_REG_CAL_AC3, &ac3) < 0) return -1;
    if (i2c_read_word(handle, BMP180_REG_CAL_AC4, (int16_t *)&ac4) < 0) return -1;
    if (i2c_read_word(handle, BMP180_REG_CAL_AC5, (int16_t *)&ac5) < 0) return -1;
    if (i2c_read_word(handle, BMP180_REG_CAL_AC6, (int16_t *)&ac6) < 0) return -1;
    if (i2c_read_word(handle, BMP180_REG_CAL_B1, &b1) < 0) return -1;
    if (i2c_read_word(handle, BMP180_REG_CAL_B2, &b2) < 0) return -1;
    if (i2c_read_word(handle, BMP180_REG_CAL_MB, &mb) < 0) return -1;
    if (i2c_read_word(handle, BMP180_REG_CAL_MC, &mc) < 0) return -1;
    if (i2c_read_word(handle, BMP180_REG_CAL_MD, &md) < 0) return -1;
    return 0;
}

static int read_raw_temperature(int handle, int32_t *ut) {
    if (i2c_write_byte(handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    uint8_t msb, lsb;
    if (i2c_read_byte(handle, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_byte(handle, BMP180_REG_LSB, &lsb) < 0) return -1;
    *ut = (int32_t)((msb << 8) | lsb);
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    if (i2c_write_byte(handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)) < 0) return -1;
    gpioDelay(2000 + (3000 << OSS));
    uint8_t msb, lsb, xlsb;
    if (i2c_read_byte(handle, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_byte(handle, BMP180_REG_LSB, &lsb) < 0) return -1;
    if (i2c_read_byte(handle, BMP180_REG_XLSB, &xlsb) < 0) return -1;
    *up = ((int32_t)msb << 16 | (int32_t)lsb << 8 | (int32_t)xlsb) >> (8 - OSS);
    return 0;
}

static int calculate_temperature(int32_t ut, int32_t *b5_out) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    *b5_out = b5;
    return (b5 + 8) >> 4;
}

static int calculate_pressure(int32_t up, int32_t b5) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
