static int i2c_read_word(int handle, uint8_t reg, int16_t *value) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, (char *)value, 1) != 1) return -1;
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    return (i2cWriteDevice(handle, buf, 2) == 2) ? 0 : -1;
}

