#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip4"
#define CS_PIN 8
#define LOG_FILE "rtd_log.csv"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0
#define SAMPLE_INTERVAL 5
#define RREF 4300.0
#define RTD_NOMINAL 100.0
#define ALPHA 0.0039083

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_line *cs_line = NULL;
static struct gpiod_chip *chip = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

int cs_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        perror("Failed to get CS line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "max31865-cs", 1) < 0) {
        perror("Failed to request CS line as output");
        gpiod_chip_close(chip);
        chip = NULL;
        cs_line = NULL;
        return -1;
    }

    return 0;
}

int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

int read_max31865(uint16_t *rtd_raw, uint8_t *fault) {
    uint8_t tx[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx[4] = {0};

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Failed to assert CS");
        return -1;
    }

    if (spi_transfer(tx, rx, 4) < 0) {
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Failed to deassert CS");
        return -1;
    }

    *rtd_raw = ((uint16_t)rx[0] << 8) | rx[1];
    *fault = rx[3] & 0x07;

    return 0;
}

double calculate_temperature(uint16_t rtd_raw) {
    double rtd_resistance = (double)rtd_raw * RREF / 32768.0;
    double a = ALPHA;
    double r0 = RTD_NOMINAL;
    double rtd = rtd_resistance;

    double z1 = -a;
    double z2 = a * a - (4 * a) / r0;
    double z3 = (4 * a) / (r0 * r0);
    double z4 = 2 * a;

    double temp = (z2 + sqrt(z2 * z2 - 4 * z1 * (z3 - rtd))) / (2 * z1);
    return temp;
}

int log_data(double temperature, const char *error_msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return -1;
        }
        fprintf(log_file, "Timestamp,Temperature (C),Error\n");
    }

    if (error_msg != NULL) {
        fprintf(log_file, "%s,,%s\n", timestamp, error_msg);
    } else {
        fprintf(log_file, "%s,%.2f,\n", timestamp, temperature);
    }
    fflush(log_file);
    return 0;
}

void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    if (cs_init() < 0) {
        fprintf(stderr, "CS initialization failed\n");
        cleanup();
        return 1;
    }

    printf("MAX31865 RTD Logger started. Logging to %s every %d seconds.\n", LOG_FILE, SAMPLE_INTERVAL);

    while (running) {
        uint16_t rtd_raw = 0;
        uint8_t fault = 0;
        double temperature = 0.0;
        const char *error_msg = NULL;

        if (read_max31865(&rtd_raw, &fault) < 0) {
            error_msg = "SPI read error";
        } else if (fault != 0) {
            char fault_str[64];
            snprintf(fault_str, sizeof(fault_str), "RTD fault detected: 0x%02X", fault);
            error_msg = fault_str;
        } else {
            temperature = calculate_temperature(rtd_raw);
        }

        if (log_data(temperature, error_msg) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

