        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    fseek(log_fp, 0, SEEK_END);
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "timestamp,temperature_C,humidity_percent,pressure_hPa\n");
    }
    while (running) {
        float temp, hum, press;
        if (bme280_read_data(i2c_fd, &cal, &temp, &hum, &press) == 0) {
            log_data(log_fp, temp, hum, press);
        } else {
            fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        }
        for (int i = 0; i < LOG_INTERVAL && running; i++) {
            sleep(1);
        }
    }
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

