    if (val < 0) return -1;
    ac2 = (int16_t)val;
    val = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC3);
    if (val < 0) return -1;
    ac3 = (int16_t)val;
    val = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC4);
    if (val < 0) return -1;
    ac4 = (uint16_t)val;
    val = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC5);
    if (val < 0) return -1;
    ac5 = (uint16_t)val;
    val = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC6);
    if (val < 0) return -1;
    ac6 = (uint16_t)val;
    val = i2cReadWordData(i2c_handle, BMP180_REG_CAL_B1);
    if (val < 0) return -1;
    b1 = (int16_t)val;
    val = i2cReadWordData(i2c_handle, BMP180_REG_CAL_B2);
    if (val < 0) return -1;
    b2 = (int16_t)val;
    val = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MB);
    if (val < 0) return -1;
    mb = (int16_t)val;
    val = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MC);
    if (val < 0) return -1;
    mc = (int16_t)val;
    val = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MD);
    if (val < 0) return -1;
    md = (int16_t)val;
    return 0;
