    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p / 100.0;
}

static void add_to_buffer(float pressure) {
    time(&circular_buffer[buffer_index].timestamp);
    circular_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static float calculate_average(void) {
    if (buffer_count == 0) return 0.0;
    float sum = 0.0;
    for (int i = 0; i < buffer_count; i++) sum += circular_buffer[i].pressure;
    return sum / buffer_count;
}

static void check_alert(float pressure) {
    float avg = calculate_average();
    if (fabsf(pressure - avg) > ALERT_THRESHOLD) {
        gpioWrite(ALERT_GPIO, 1);
        fprintf(stderr, "ALERT: Pressure deviation %.2f hPa from average %.2f hPa\n", pressure, avg);
    } else {
        gpioWrite(ALERT_GPIO, 0);
    }
}

static void timer_callback(void *userdata) {
    (void)userdata;
    int32_t ut, up;
    if (read_raw_temperature(&ut) < 0) {
        fprintf(stderr, "Error reading temperature\n");
        return;
    }
    if (read_raw_pressure(&up) < 0) {
        fprintf(stderr, "Error reading pressure\n");
        return;
    }
    float pressure = calculate_pressure(ut, up);
    add_to_buffer(pressure);
    check_alert(pressure);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data() < 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, timer_callback, NULL) < 0) {
        fprintf(stderr, "Error setting timer\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    while (running) gpioDelay(100000);
    gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, NULL, NULL);
    gpioWrite(ALERT_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

