static int read_calibration(void) {
    int16_t *fields[] = {&cal.ac1, &cal.ac2, &cal.ac3, &cal.b1, &cal.b2, &cal.mb, &cal.mc, &cal.md};
    uint16_t *u_fields[] = {&cal.ac4, &cal.ac5, &cal.ac6};
    int regs[] = {BMP180_REG_CAL_AC1, BMP180_REG_CAL_AC2, BMP180_REG_CAL_AC3, BMP180_REG_CAL_B1, BMP180_REG_CAL_B2, BMP180_REG_CAL_MB, BMP180_REG_CAL_MC, BMP180_REG_CAL_MD};
