#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_ADDR_1 0x76
#define BMP280_ADDR_2 0x77
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "weather_data.txt"
#define LOG_INTERVAL_SEC 5
#define MEAS_TIMEOUT_MS 50

#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_STATUS 0xF3
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB 0x88

#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_CMD 0xB6

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_t;

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int bmp280_init(int fd, bmp280_calib_t *cal) {
    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_CHIP_ID, &id, 1) < 0) {
        fprintf(stderr, "Error: Failed to read chip ID.\n");
        return -1;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X).\n", id, BMP280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg(fd, BMP280_REG_RESET, BMP280_RESET_CMD) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor.\n");
        return -1;
    }
    usleep(2000);

    uint8_t c[24];
    if (i2c_read_reg(fd, BMP280_REG_CALIB, c, 24) < 0) {
        fprintf(stderr, "Error: Failed to read calibration data.\n");
        return -1;
    }
    cal->dig_T1 = (uint16_t)(c[0] | (c[1] << 8));
    cal->dig_T2 = (int16_t)(c[2] | (c[3] << 8));
    cal->dig_T3 = (int16_t)(c[4] | (c[5] << 8));
    cal->dig_P1 = (uint16_t)(c[6] | (c[7] << 8));
    cal->dig_P2 = (int16_t)(c[8] | (c[9] << 8));
    cal->dig_P3 = (int16_t)(c[10] | (c[11] << 8));
    cal->dig_P4 = (int16_t)(c[12] | (c[13] << 8));
    cal->dig_P5 = (int16_t)(c[14] | (c[15] << 8));
    cal->dig_P6 = (int16_t)(c[16] | (c[17] << 8));
    cal->dig_P7 = (int16_t)(c[18] | (c[19] << 8));
    cal->dig_P8 = (int16_t)(c[20] | (c[21] << 8));
    cal->dig_P9 = (int16_t)(c[22] | (c[23] << 8));

    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    return 0;
}

static int bmp280_read_raw(int fd, int32_t *raw_t, int32_t *raw_p) {
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) return -1;

    uint8_t status;
    for (int i = 0; i < MEAS_TIMEOUT_MS; i++) {
        if (i2c_read_reg(fd, BMP280_REG_STATUS, &status, 1) < 0) return -1;
        if ((status & 0x08) == 0) break;
        usleep(1000);
        if (i == MEAS_TIMEOUT_MS - 1) {
            fprintf(stderr, "Error: Measurement timeout.\n");
            return -1;
        }
    }

    uint8_t d[6];
    if (i2c_read_reg(fd, BMP280_REG_PRESS_MSB, d, 6) < 0) return -1;
    *raw_p = ((int32_t)d[0] << 12) | ((int32_t)d[1] << 4) | (d[2] >> 4);
    *raw_t = ((int32_t)d[3] << 12) | ((int32_t)d[4] << 4) | (d[5] >> 4);
    return 0;
}

static double bmp280_compensate_temp(int32_t raw, const bmp280_calib_t *c, int32_t *t_fine) {
    int32_t v1 = ((((raw >> 3) - ((int32_t)c->dig_T1 << 1))) * ((int32_t)c->dig_T2)) >> 11;
    int32_t v2 = (((((raw >> 4) - ((int32_t)c->dig_T1)) * ((raw >> 4) - ((int32_t)c->dig_T1))) >> 12) * ((int32_t)c->dig_T3)) >> 14;
    *t_fine = v1 + v2;
    return (*t_fine * 5 + 128) >> 8;
