#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <pthread.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define LM75_ADDR      0x48
#define LM75_TEMP_REG  0x00
#define LED_PIN        18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD 28.0f
#define POLL_INTERVAL  1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
    pthread_mutex_t mutex;
} CircularBuffer;

static void cb_init(CircularBuffer *cb) {
    memset(cb->buffer, 0, sizeof(cb->buffer));
    cb->head  = 0;
    cb->count = 0;
    pthread_mutex_init(&cb->mutex, NULL);
}

static void cb_push(CircularBuffer *cb, float value) {
    pthread_mutex_lock(&cb->mutex);
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
    pthread_mutex_unlock(&cb->mutex);
}

static float cb_average(const CircularBuffer *cb) {
    pthread_mutex_lock(&cb->mutex);
    float sum = 0.0f;
    int n = cb->count;
    for (int i = 0; i < n; i++) sum += cb->buffer[i];
    pthread_mutex_unlock(&cb->mutex);
    return (n > 0) ? (sum / n) : 0.0f;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) return -1;
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_temperature(int fd, float *temp_out) {
    int16_t raw;
    if (i2c_read_reg16(fd, LM75_TEMP_REG, &raw) < 0) return -1;
    *temp_out = (float)raw / 256.0f;
    return 0;
}

static void *data_acquisition_thread(void *arg) {
    int fd = *(int *)arg;
    CircularBuffer *cb = (CircularBuffer *)arg + 1;
    while (g_running) {
        float temp;
        if (read_temperature(fd, &temp) == 0) {
            cb_push(cb, temp);
        } else {
            fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        }
        sleep(POLL_INTERVAL);
    }
    return NULL;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(led, "lm75_led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LM75_ADDR, strerror(errno));
        close(fd);
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        return 1;
    }

    CircularBuffer cb;
    cb_init(&cb);

    int fd_local = fd;
    pthread_t tid;
    if (pthread_create(&tid, NULL, data_acquisition_thread, &fd_local) != 0) {
        fprintf(stderr, "Failed to create data acquisition thread: %s\n", strerror(errno));
        close(fd);
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        pthread_mutex_destroy(&cb.mutex);
        return 1;
    }

    while (g_running) {
        float avg = cb_average(&cb);
        printf("Average Temperature: %.2f C\n", avg);
        if (avg > TEMP_THRESHOLD) {
            gpiod_line_set_value(led, 1);
        } else {
            gpiod_line_set_value(led, 0);
        }
        sleep(POLL_INTERVAL);
    }

    g_running = 0;
    pthread_join(tid, NULL);
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(fd);
    pthread_mutex_destroy(&cb.mutex);
    printf("\nExiting cleanly.\n");
    return 0;
}

