#define MAX31865_CONFIG_REG 0x80
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x07
#define R_REF 430.0
#define R0 100.0
#define ALPHA 0.00385
#define BETA 0.000045
#define TARGET_TEMP 25.0
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define MAX_TEMP 80.0
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31865_reg(int handle, uint8_t reg, uint8_t *val) {
    char tx[2] = { (char)(reg & 0x7F), 0x00 };
    char rx[2] = { 0, 0 };
    if (spiXfer(handle, tx, rx, 2) != 2) return -1;
    *val = (uint8_t)rx[1];
    return 0;
}

static int write_max31865_reg(int handle, uint8_t reg, uint8_t val) {
    char tx[2] = { (char)(reg | 0x80), (char)val };
    char rx[2] = { 0, 0 };
    if (spiXfer(handle, tx, rx, 2) != 2) return -1;
    return 0;
}

static int init_max31865(int handle) {
    if (write_max31865_reg(handle, MAX31865_CONFIG_REG, 0xC1) != 0) {
        fprintf(stderr, "Error: Failed to write MAX31865 config register.\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_rtd_code(int handle, uint16_t *code) {
    uint8_t msb, lsb;
    if (read_max31865_reg(handle, MAX31865_RTD_MSB_REG, &msb) != 0) return -1;
    if (read_max31865_reg(handle, MAX31865_RTD_LSB_REG, &lsb) != 0) return -1;
    *code = ((uint16_t)(msb & 0xFF) << 7) | ((uint16_t)(lsb >> 1) & 0x7F);
    return 0;
}

static int read_fault_status(int handle, uint8_t *fault) {
    return read_max31865_reg(handle, MAX31865_FAULT_REG, fault);
}

static double rtd_to_temperature(uint16_t code) {
    if (code == 0) return -273.15;
    double rtd_resistance = ((double)code / 32768.0) * R_REF;
    double a = ALPHA;
    double b = BETA;
    double t = (-a + sqrt(a * a - 4 * b * (1.0 - rtd_resistance / R0))) / (2 * b);
    return t;
}

static double pid_control(double setpoint, double actual, double *integral, double *prev_error, double dt) {
    double error = setpoint - actual;
    *integral += error * dt;
    double derivative = (dt > 0.0) ? (error - *prev_error) / dt : 0.0;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *prev_error = error;
    if (output < 0.0) output = 0.0;
    if (output > 100.0) output = 100.0;
    return output;
}

static void set_heater_pwm(double duty_cycle) {
    int pwm_value = (int)(duty_cycle * (PWM_RANGE / 100.0));
    if (gpioPWM(HEATER_GPIO, pwm_value) != 0) {
        fprintf(stderr, "Error: Failed to set PWM on GPIO%d.\n", HEATER_GPIO);
    }
}

static void cleanup(void) {
    set_heater_pwm(0.0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    double target_temperature = TARGET_TEMP;
    double kp = KP, ki = KI, kd = KD;
    double integral = 0.0, prev_error = 0.0;
    double dt = 0.1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO%d.\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO%d.\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }

    set_heater_pwm(0.0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 0) | (SPI_MODE << 1));
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d, speed %d).\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return 1;
    }

    if (init_max31865(spi_handle) != 0) {
        fprintf(stderr, "Error: MAX31865 initialization failed.\n");
        cleanup();
        return 1;
    }

    json_t *config = json_load_file("config.json", 0, NULL);
    if (!config) {
        fprintf(stderr, "Warning: Could not load config.json; using defaults.\n");
    } else {
        json_t *t = json_object_get(config, "target_temperature");
        if (json_is_number(t)) target_temperature = json_number_value(t);
        json_t *p = json_object_get(config, "kp");
        if (json_is_number(p)) kp = json_number_value(p);
        json_t *i = json_object_get(config, "ki");
        if (json_is_number(i)) ki = json_number_value(i);
        json_t *d = json_object_get(config, "kd");
        if (json_is_number(d)) kd = json_number_value(d);
        json_decref(config);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting temperature control loop. Target: %.2f°C\n", target_temperature);

    while (running) {
        uint16_t rtd_code = 0;
        if (read_rtd_code(spi_handle, &rtd_code) != 0) {
            fprintf(stderr, "Error: SPI read failed.\n");
            set_heater_pwm(0.0);
            break;
        }

        uint8_t fault = 0;
        if (read_fault_status(spi_handle, &fault) != 0) {
            fprintf(stderr, "Error: Failed to read fault status.\n");
            set_heater_pwm(0.0);
            break;
        }

        if (fault & 0x01) {
            fprintf(stderr, "Error: MAX31865 fault detected (0x%02X).\n", fault);
            set_heater_pwm(0.0);
            break;
        }

        double temperature = rtd_to_temperature(rtd_code);
        if (temperature < -100.0) {
            fprintf(stderr, "Error: Invalid temperature reading (%.2f).\n", temperature);
            set_heater_pwm(0.0);
            break;
        }

        if (temperature > MAX_TEMP) {
            fprintf(stderr, "Error: Temperature exceeds maximum safe limit (%.2f > %.2f).\n", temperature, MAX_TEMP);
            set_heater_pwm(0.0);
            break;
        }

        double duty_cycle = pid_control(target_temperature, temperature, &integral, &prev_error, dt);
        set_heater_pwm(duty_cycle);

        printf("Temp: %.2f°C, Duty: %.2f%%\n", temperature, duty_cycle);
        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return 0;
}

