#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_CALIB_START  0xAA
#define BMP180_CMD_TEMP         0x2E
#define BMP180_CMD_PRESSURE     0x34
#define FAN_GPIO                18
#define BUFFER_SIZE             60
#define SAMPLE_INTERVAL_US      500000
#define TEMP_THRESHOLD          30.0f

typedef struct {
    int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_calib_t;

typedef struct {
    time_t timestamp;
    float  temperature;
    float  pressure;
} sensor_data_t;

static sensor_data_t  data_buffer[BUFFER_SIZE];
static int            buffer_index = 0;
static int            buffer_count = 0;
static int            i2c_handle   = -1;
static volatile sig_atomic_t running = 1;
static bmp180_calib_t cal;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int read_calibration(int handle, bmp180_calib_t *c) {
    uint8_t buf[22];
    if (i2c_read_block(handle, BMP180_REG_CALIB_START, buf, sizeof(buf)) != 0) {
        fprintf(stderr, "Error: failed to read BMP180 calibration data\n");
        return -1;
    }
    c->ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    c->ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    c->ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    c->ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    c->ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    c->ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    c->b1  = (int16_t)((buf[12] << 8) | buf[13]);
    c->b2  = (int16_t)((buf[14] << 8) | buf[15]);
    c->mb  = (int16_t)((buf[16] << 8) | buf[17]);
    c->mc  = (int16_t)((buf[18] << 8) | buf[19]);
    c->md  = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int handle, int32_t *ut) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(handle, BMP180_REG_MSB + 1);
    if (msb < 0 || lsb < 0) return -1;
    *ut = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE) < 0) return -1;
    gpioDelay(5000);
    uint8_t buf[3];
    if (i2c_read_block(handle, BMP180_REG_MSB, buf, 3) != 0) return -1;
    *up = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> 8;
    return 0;
}

static int32_t compute_b5(int32_t ut, const bmp180_calib_t *c) {
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    return x1 + x2;
}

static float calculate_temperature(int32_t ut, const bmp180_calib_t *c) {
    int32_t b5 = compute_b5(ut, c);
    return ((b5 + 8) >> 4) / 10.0f;
}

static float calculate_pressure(int32_t up, int32_t ut, const bmp180_calib_t *c) {
    int32_t b5 = compute_b5(ut, c);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)c->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)c->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)c->ac1 * 4 + x3) << 0) + 2) >> 2);
    x1 = ((int32_t)c->ac3 * b6) >> 13;
    x2 = ((int32_t)c->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)c->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000UL) p = (b7 * 2) / b4;
    else                  p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (float)p;
}

static void timer_callback(void *userdata) {
    (void)userdata;
    int32_t ut, up;
    if (read_raw_temperature(i2c_handle, &ut) != 0) {
        fprintf(stderr, "Warning: temperature read failed, skipping sample\n");
        return;
    }
    if (read_raw_pressure(i2c_handle, &up) != 0) {
        fprintf(stderr, "Warning: pressure read failed, skipping sample\n");
        return;
    }
    float temp = calculate_temperature(ut, &cal);
    float pres = calculate_pressure(up, ut, &cal);
    time_t now = time(NULL);
    data_buffer[buffer_index].timestamp  = now;
    data_buffer[buffer_index].temperature = temp;
    data_buffer[buffer_index].pressure    = pres;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
    if (temp > TEMP_THRESHOLD) gpioWrite(FAN_GPIO, 1);
    else                       gpioWrite(FAN_GPIO, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (read_calibration(i2c_handle, &cal) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetTimerFuncEx failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    while (running) gpioDelay(100000);
    gpioWrite(FAN_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

