    if (read_raw_temperature(i2c_handle, &ut) != 0) {
        fprintf(stderr, "Warning: temperature read failed, skipping sample\n");
        return;
    }
    if (read_raw_pressure(i2c_handle, &up) != 0) {
        fprintf(stderr, "Warning: pressure read failed, skipping sample\n");
        return;
    }
    float temp = calculate_temperature(ut, &cal);
    float pres = calculate_pressure(up, ut, &cal);
    time_t now = time(NULL);
    data_buffer[buffer_index].timestamp  = now;
    data_buffer[buffer_index].temperature = temp;
    data_buffer[buffer_index].pressure    = pres;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
    if (temp > TEMP_THRESHOLD) gpioWrite(FAN_GPIO, 1);
    else                       gpioWrite(FAN_GPIO, 0);
}

