#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define PWM_RANGE 1000
#define MAX_DUTY_CYCLE 800
#define LOG_FILE "heater_log.csv"
#define DEFAULT_TARGET_TEMP 25.0
#define SAMPLE_INTERVAL_US 100000
#define SPI_READ_RETRIES 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31855(int spi_handle, double *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    for (int attempt = 0; attempt < SPI_READ_RETRIES; attempt++) {
        int result = spiXfer(spi_handle, tx, rx, 4);
        if (result == 4) {
            uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                           ((uint32_t)(uint8_t)rx[1] << 16) |
                           ((uint32_t)(uint8_t)rx[2] << 8)  |
                           ((uint32_t)(uint8_t)rx[3]);

            if (raw & 0x00010000) {
                fprintf(stderr, "MAX31855 fault detected (raw=0x%08X)\n", raw);
                if (raw & 0x00000001) fprintf(stderr, "  Open circuit\n");
                if (raw & 0x00000002) fprintf(stderr, "  Short to GND\n");
                if (raw & 0x00000004) fprintf(stderr, "  Short to VCC\n");
                return -1;
            }

            int16_t thermocouple_data = (int16_t)(raw >> 18);
            *temperature = thermocouple_data * 0.25;
            return 0;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d, result=%d)\n",
                attempt + 1, SPI_READ_RETRIES, result);
        gpioDelay(10000);
    }
    return -1;
}

static int set_heater_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;
    if (gpioPWM(HEATER_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO%d\n", HEATER_GPIO);
        return -1;
    }
    return 0;
}

static void log_data(double temperature, int duty_cycle) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    double target_temperature = DEFAULT_TARGET_TEMP;
    double current_temperature = 0.0;
    double integral = 0.0;
    double Kp = 1.0;
    double Ki = 0.1;
    int duty_cycle = 0;
    int error_code = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", HEATER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", HEATER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel=%d, speed=%d)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature,Cycle\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Heater control started. Target: %.2f°C. Press Ctrl+C to exit.\n", target_temperature);

    while (running) {
        error_code = read_max31855(spi_handle, &current_temperature);

        if (error_code == 0) {
            double error = target_temperature - current_temperature;
            integral += error;

            if (integral > 100.0) integral = 100.0;
            if (integral < -100.0) integral = -100.0;

            duty_cycle = (int)(Kp * error + Ki * integral);

            if (duty_cycle < 0) duty_cycle = 0;
            if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;

            if (set_heater_duty_cycle(duty_cycle) != 0) {
                fprintf(stderr, "Heater control failed\n");
            }

            log_data(current_temperature, duty_cycle);
            printf("Temp: %.2f°C, Duty: %d%%\n", current_temperature, duty_cycle);
        } else {
            fprintf(stderr, "Sensor read failed. Setting heater to 0%% for safety.\n");
            if (set_heater_duty_cycle(0) != 0) {
                fprintf(stderr, "Failed to turn off heater during error state\n");
            }
            log_data(-999.0, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    set_heater_duty_cycle(0);
    cleanup();
    return EXIT_SUCCESS;
}

