#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"

#define TEMP_LOW   40000
#define TEMP_MED   60000

#define PWM_RANGE 255

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Common-anode LED: fully off = duty 255, fully on = duty 0 */
static void set_led_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN,   PWM_RANGE - red);
    gpioPWM(GREEN_PIN, PWM_RANGE - green);
    gpioPWM(BLUE_PIN,  PWM_RANGE - blue);
}

static void all_off(void)
{
    set_led_color(0, 0, 0);
}

static int read_cpu_temp(void)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen temperature file");
        return -1;
    }

    int temp = -1;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Failed to read temperature from %s\n", TEMP_FILE);
        temp = -1;
    }

    if (fclose(fp) != 0)
        perror("fclose temperature file");

    return temp;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    all_off();

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        all_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int temp = read_cpu_temp();

        if (temp < 0) {
            fprintf(stderr, "Temperature read failed; skipping update.\n");
        } else {
            int red, green, blue;

            if (temp < TEMP_LOW) {
                red   = 0;
                green = 0;
                blue  = 255;
            } else if (temp < TEMP_MED) {
                red   = 0;
                green = 255;
                blue  = 0;
            } else {
                red   = 255;
                green = 0;
                blue  = 0;
            }

            set_led_color(red, green, blue);
            printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temp, red, green, blue);
            fflush(stdout);
        }

        time_sleep(0.5);
    }

    all_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

