#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define SERVER_URL "http://yourserver.com/api/humidity"

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    float temperature;
    float humidity;
    int error;
} DHT22Data;

DHT22Data read_dht22(int gpio) {
    DHT22Data data = {0.0f, 0.0f, 1};
    int bits[40] = {0};
    int i;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 1);
    gpioDelay(500000); // 500ms high
    gpioWrite(gpio, 0);
    gpioDelay(2000);   // 2ms low (>=1ms per datasheet)
    gpioWrite(gpio, 1);
    gpioDelay(30);     // 30us high

    gpioSetMode(gpio, PI_INPUT);

    // Wait for sensor response (low then high)
    int timeout = 0;
    while (gpioRead(gpio) == 1 && timeout < 100) {
        gpioDelay(1);
        timeout++;
    }
    if (timeout >= 100) return data;

    timeout = 0;
    while (gpioRead(gpio) == 0 && timeout < 100) {
        gpioDelay(1);
        timeout++;
    }
    if (timeout >= 100) return data;

    timeout = 0;
    while (gpioRead(gpio) == 1 && timeout < 100) {
        gpioDelay(1);
        timeout++;
    }
    if (timeout >= 100) return data;

    // Read 40 bits
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(gpio) == 0 && timeout < 100) {
            gpioDelay(1);
            timeout++;
        }
        if (timeout >= 100) return data;

        int high_time = 0;
        while (gpioRead(gpio) == 1 && high_time < 100) {
            gpioDelay(1);
            high_time++;
        }
        if (high_time >= 100) return data;

        bits[i] = (high_time > 40) ? 1 : 0;
    }

    // Parse data
    int humidity_raw = (bits[0] << 11) | (bits[1] << 10) | (bits[2] << 9) |
                       (bits[3] << 8) | (bits[4] << 7) | (bits[5] << 6) |
                       (bits[6] << 5) | (bits[7] << 4) | (bits[8] << 3) |
                       (bits[9] << 2) | (bits[10] << 1) | bits[11];

    int temperature_raw = (bits[12] << 11) | (bits[13] << 10) | (bits[14] << 9) |
                          (bits[15] << 8) | (bits[16] << 7) | (bits[17] << 6) |
                          (bits[18] << 5) | (bits[19] << 4) | (bits[20] << 3) |
                          (bits[21] << 2) | (bits[22] << 1) | bits[23];

    int checksum = bits[24] | (bits[25] << 1) | (bits[26] << 2) |
                   (bits[27] << 3) | (bits[28] << 4) | (bits[29] << 5) |
                   (bits[30] << 6) | (bits[31] << 7) | (bits[32] << 8) |
                   (bits[33] << 9) | (bits[34] << 10) | (bits[35] << 11) |
                   (bits[36] << 12) | (bits[37] << 13) | (bits[38] << 14) |
                   (bits[39] << 15);

    int calculated_checksum = (humidity_raw >> 8) + (humidity_raw & 0xFF) +
                              (temperature_raw >> 8) + (temperature_raw & 0xFF);

    if (checksum != calculated_checksum) {
        return data;
    }

    data.humidity = (float)humidity_raw / 10.0f;
    data.temperature = (float)temperature_raw / 10.0f;
    data.error = 0;
    return data;
}

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    (void)contents;
    (void)userp;
    return size * nmemb;
}

int send_data(float temperature, float humidity) {
    CURL *curl;
    CURLcode res;
    int retries = 0;
    int success = 0;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error: curl_easy_init() failed\n");
        curl_global_cleanup();
        return 1;
    }

    char json_string[128];
    snprintf(json_string, sizeof(json_string),
             "{\"temperature\": %.2f, \"humidity\": %.2f}",
             temperature, humidity);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");

    while (retries < MAX_RETRIES && !success) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
        curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "Error: curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            retries++;
            if (retries < MAX_RETRIES) {
                sleep(2);
            }
        } else {
            long http_code = 0;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
            if (http_code == 200) {
                success = 1;
            } else {
                fprintf(stderr, "Error: HTTP response code: %ld\n", http_code);
                retries++;
                if (retries < MAX_RETRIES) {
                    sleep(2);
                }
            }
        }
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    curl_global_cleanup();

    if (!success) {
        fprintf(stderr, "Error: Failed to send data after %d retries\n", MAX_RETRIES);
        return 1;
    }

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    while (running) {
        DHT22Data dht22_data = read_dht22(DHT22_GPIO);

        if (dht22_data.error == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   dht22_data.temperature, dht22_data.humidity);

            if (send_data(dht22_data.temperature, dht22_data.humidity) != 0) {
                fprintf(stderr, "Error: Failed to send data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read DHT22 sensor\n");
        }

        sleep(5);
    }

    gpioTerminate();
    return 0;
}

