                              (temperature_raw >> 8) + (temperature_raw & 0xFF);

    if (checksum != calculated_checksum) {
        return data;
    }

    data.humidity = (float)humidity_raw / 10.0f;
    data.temperature = (float)temperature_raw / 10.0f;
    data.error = 0;
    return data;
}

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    (void)contents;
    (void)userp;
    return size * nmemb;
}

int send_data(float temperature, float humidity) {
    CURL *curl;
    CURLcode res;
    int retries = 0;
    int success = 0;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error: curl_easy_init() failed\n");
        curl_global_cleanup();
        return 1;
    }

    char json_string[128];
    snprintf(json_string, sizeof(json_string),
             "{\"temperature\": %.2f, \"humidity\": %.2f}",
             temperature, humidity);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");

    while (retries < MAX_RETRIES && !success) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
        curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "Error: curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            retries++;
            if (retries < MAX_RETRIES) {
                sleep(2);
            }
        } else {
            long http_code = 0;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
            if (http_code == 200) {
                success = 1;
            } else {
                fprintf(stderr, "Error: HTTP response code: %ld\n", http_code);
                retries++;
                if (retries < MAX_RETRIES) {
                    sleep(2);
                }
            }
        }
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    curl_global_cleanup();

    if (!success) {
        fprintf(stderr, "Error: Failed to send data after %d retries\n", MAX_RETRIES);
        return 1;
    }

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    while (running) {
        DHT22Data dht22_data = read_dht22(DHT22_GPIO);

        if (dht22_data.error == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   dht22_data.temperature, dht22_data.humidity);

            if (send_data(dht22_data.temperature, dht22_data.humidity) != 0) {
                fprintf(stderr, "Error: Failed to send data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read DHT22 sensor\n");
        }

        sleep(5);
    }

    gpioTerminate();
    return 0;
}

