#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR        0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB     0xF6
#define BMP180_REG_LSB     0xF7
#define BMP180_REG_XLSB    0xF8
#define BMP180_REG_CALIB   0xAA

#define BMP180_CMD_TEMP    0x2E
#define BMP180_CMD_PRESS   0x34
#define OSS                3
#define DEBOUNCE_US        200000
#define SAMPLE_PERIOD_US   2000000
#define CONV_DELAY_US      26000

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static volatile uint32_t last_isr_tick = 0;

static int i2c_handle = -1;

static int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(void) {
    uint8_t buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CALIB, (char *)buf, 22) != 22) {
        fprintf(stderr, "Error: failed to read 22-byte calibration block\n");
        return -1;
    }
    ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1  = (int16_t)((buf[12] << 8) | buf[13]);
    b2  = (int16_t)((buf[14] << 8) | buf[15]);
    mb  = (int16_t)((buf[16] << 8) | buf[17]);
    mc  = (int16_t)((buf[18] << 8) | buf[19]);
    md  = (int16_t)((buf[20] << 8) | buf[21]);
    if (ac1 == 0 && ac2 == 0 && ac3 == 0 && ac4 == 0 && ac5 == 0 && ac6 == 0) {
        fprintf(stderr, "Error: calibration coefficients all zero - sensor not present?\n");
        return -1;
    }
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) {
        fprintf(stderr, "Error: failed to write temperature command\n");
        return -1;
    }
    gpioDelay(CONV_DELAY_US);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (msb < 0 || lsb < 0) {
        fprintf(stderr, "Error: failed to read temperature data\n");
        return -1;
    }
    *ut = (int32_t)((msb << 8) | lsb);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    uint8_t cmd = BMP180_CMD_PRESS | (OSS << 6);
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, cmd) < 0) {
        fprintf(stderr, "Error: failed to write pressure command\n");
        return -1;
    }
    gpioDelay(CONV_DELAY_US);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);
    if (msb < 0 || lsb < 0 || xlsb < 0) {
        fprintf(stderr, "Error: failed to read pressure data\n");
        return -1;
    }
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int32_t b5) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << OSS) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000UL) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    uint32_t diff = tick - last_isr_tick;
    if (diff > DEBOUNCE_US) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        fflush(stdout);
        last_isr_tick = tick;
    }
}

static void log_pressure(int32_t pressure_pa) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open pressure_log.txt for appending\n");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %d hPa\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, pressure_pa);
    } else {
        fprintf(fp, "<timestamp error>, %d hPa\n", pressure_pa);
    }
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (read_calibration() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(4, PI_INPUT);
    gpioSetPullUpDown(4, PI_PUD_UP);
    if (gpioSetISRFuncEx(4, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to set ISR on GPIO4\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    printf("BMP180 logging ready. Press button on GPIO4 to toggle. Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        if (logging_enabled) {
            int32_t ut, up;
            if (read_raw_temperature(&ut) == 0 && read_raw_pressure(&up) == 0) {
                int32_t b5 = compute_b5(ut);
                int32_t pressure_pa = compute_pressure(up, b5);
                log_pressure(pressure_pa);
            } else {
                fprintf(stderr, "Error: sensor read failed, skipping log\n");
            }
        } else {
            printf("Logging disabled, waiting for button press...\n");
            fflush(stdout);
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    gpioSetISRFuncEx(4, FALLING_EDGE, 0, NULL, NULL);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

