#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <curl/curl.h>
#include <getopt.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY 2
#define READ_INTERVAL 10
#define DHT_TIMEOUT_US 200
#define DHT_START_LOW_US 1000
#define DHT_START_HIGH_US 30
#define DHT_RESP_LOW_US 80
#define DHT_RESP_HIGH_US 80
#define DHT_BIT_LOW_US 50
#define DHT_BIT_HIGH_US 70

static volatile sig_atomic_t running = 1;
static char *server_url = "http://your-server.com/api/humidity";

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

static int read_dht22(float *humidity) {
    uint8_t data[5] = {0};
    int i;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(DHT_START_LOW_US);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(DHT_START_HIGH_US);
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    if (wait_for_level(DHT22_GPIO, 0, DHT_TIMEOUT_US) < 0) return -1;
    if (wait_for_level(DHT22_GPIO, 1, DHT_TIMEOUT_US) < 0) return -1;
    if (wait_for_level(DHT22_GPIO, 0, DHT_TIMEOUT_US) < 0) return -1;

    for (i = 0; i < 40; i++) {
        if (wait_for_level(DHT22_GPIO, 1, DHT_TIMEOUT_US) < 0) return -1;
        uint32_t start = gpioTick();
        if (wait_for_level(DHT22_GPIO, 0, DHT_TIMEOUT_US) < 0) return -1;
        uint32_t duration = gpioTick() - start;
        data[i / 8] <<= 1;
        if (duration > DHT_BIT_HIGH_US) data[i / 8] |= 1;
    }

    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) return -2;

    *humidity = (float)(((uint16_t)data[0] << 8) | data[1]) / 10.0f;
    return 0;
}

static size_t write_cb(char *ptr, size_t size, size_t nmemb, void *userdata) {
    (void)ptr; (void)userdata;
    return size * nmemb;
}

static int post_humidity(float humidity) {
    CURL *curl = curl_easy_init();
    if (!curl) { syslog(LOG_ERR, "curl_easy_init() failed"); return -1; }

    char json[64];
