#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5
#define TEMP_THRESHOLD_1 45000
#define TEMP_THRESHOLD_2 55000
#define TEMP_THRESHOLD_3 65000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_cpu_temp(int *temp_millideg) {
    FILE *fp = fopen(CPU_TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", CPU_TEMP_FILE, strerror(errno));
        return -1;
    }

    char buffer[16];
    if (!fgets(buffer, sizeof(buffer), fp)) {
        fprintf(stderr, "Error reading %s: %s\n", CPU_TEMP_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *endptr;
    long val = strtol(buffer, &endptr, 10);
    if (endptr == buffer) {
        fprintf(stderr, "Error parsing temperature value: %s\n", buffer);
        return -1;
    }

    *temp_millideg = (int)val;
    return 0;
}

static int read_fan_max_state(int *max_state) {
    FILE *fp = fopen(FAN_STATE_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_STATE_FILE, strerror(errno));
        return -1;
    }

    char buffer[16];
    if (!fgets(buffer, sizeof(buffer), fp)) {
        fprintf(stderr, "Error reading %s: %s\n", FAN_STATE_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *endptr;
    long val = strtol(buffer, &endptr, 10);
    if (endptr == buffer) {
        fprintf(stderr, "Error parsing fan state: %s\n", buffer);
        return -1;
    }

    *max_state = (int)val;
    return 0;
}

static int write_fan_state(int state) {
    FILE *fp = fopen(FAN_STATE_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_STATE_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%d", state) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", FAN_STATE_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", FAN_STATE_FILE, strerror(errno));
        return -1;
    }

    return 0;
}

static int determine_fan_speed(int temp_millideg, int max_state) {
    if (temp_millideg < TEMP_THRESHOLD_1) {
        return 0;
    } else if (temp_millideg < TEMP_THRESHOLD_2) {
        return 1;
    } else if (temp_millideg < TEMP_THRESHOLD_3) {
        return 2;
    } else {
        return (max_state > 0) ? max_state : 3;
    }
}

static int log_fan_speed_change(int speed) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d Fan speed set to: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, speed);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int max_state = 0;
    if (read_fan_max_state(&max_state) != 0) {
        fprintf(stderr, "Failed to read fan max state. Exiting.\n");
        return 1;
    }

    int current_fan_speed = -1;

    while (program_running) {
        int temp_millideg = 0;
        if (read_cpu_temp(&temp_millideg) != 0) {
            fprintf(stderr, "Failed to read CPU temperature. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int new_fan_speed = determine_fan_speed(temp_millideg, max_state);

        if (new_fan_speed != current_fan_speed) {
            if (write_fan_state(new_fan_speed) == 0) {
                current_fan_speed = new_fan_speed;
                if (log_fan_speed_change(new_fan_speed) != 0) {
                    fprintf(stderr, "Failed to log fan speed change.\n");
                }
            } else {
                fprintf(stderr, "Failed to write fan state. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    if (write_fan_state(0) == 0) {
        printf("Fan stopped. Exiting.\n");
        if (log_fan_speed_change(0) != 0) {
            fprintf(stderr, "Failed to log shutdown.\n");
        }
    } else {
        fprintf(stderr, "Failed to stop fan during shutdown.\n");
    }

    return 0;
}

