#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("Error opening temperature file");
        return -1;
    }

    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp_milli;
}

static int calculate_duty_cycle(int temp_milli) {
    if (temp_milli <= 40000) {
        return 0;
    } else if (temp_milli >= 70000) {
        return 100;
    } else {
        return (int)(((float)(temp_milli - 40000) / 30000.0f) * 100.0f);
    }
}

static int set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
        return -1;
    }

    int pwm_value = (duty_cycle * 255) / 100;
    if (gpioPWM(FAN_GPIO, pwm_value) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

static int log_data(int temp_milli, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    float temp_c = (float)temp_milli / 1000.0f;
    fprintf(fp, "%s,%.2f,%d\n", timestamp, temp_c, duty_cycle);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error setting PWM frequency to %d Hz\n", PWM_FREQUENCY);
        gpioTerminate();
        return 1;
    }

    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing PWM to 0\n");
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (!fp) {
            perror("Error creating log file");
            gpioPWM(FAN_GPIO, 0);
            gpioTerminate();
            return 1;
        }
        fprintf(fp, "Timestamp,Temperature(C),DutyCycle(%%)\n");
        fclose(fp);
    } else {
        fclose(fp);
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        int temp_milli = read_cpu_temp();
        if (temp_milli < 0) {
            fprintf(stderr, "Error reading temperature, retrying in %d seconds...\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int duty_cycle = calculate_duty_cycle(temp_milli);

        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Error setting fan speed, retrying in %d seconds...\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (log_data(temp_milli, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        printf("Temperature: %.2f C, Duty Cycle: %d%%\n", (float)temp_milli / 1000.0f, duty_cycle);
        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    printf("Fan control stopped.\n");
    return 0;
}

