#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR1 0x08
#define SENSOR_ADDR2 0x09
#define FLOW_LOG_FILE "flow_log.txt"
#define POLL_INTERVAL_US 1000000
#define MAX_RETRIES 3
#define MEASUREMENT_CMD 0x3608
#define MEASUREMENT_DELAY_US 20000
#define FLOW_SCALE_FACTOR 0.01f

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t cmd[2] = { (MEASUREMENT_CMD >> 8) & 0xFF, MEASUREMENT_CMD & 0xFF };
    uint8_t buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "Error writing measurement command to handle %d (retry %d)\n", handle, retries + 1);
            retries++;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        int bytes_read = i2cReadDevice(handle, (char *)buf, 3);
        if (bytes_read != 3) {
            fprintf(stderr, "Error reading from handle %d: expected 3 bytes, got %d (retry %d)\n", handle, bytes_read, retries + 1);
            retries++;
            gpioDelay(10000);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "CRC mismatch on handle %d (retry %d)\n", handle, retries + 1);
            retries++;
            gpioDelay(10000);
            continue;
        }

        int16_t raw = (buf[0] << 8) | buf[1];
        *flow_rate = (float)raw * FLOW_SCALE_FACTOR;
        return 0;
    }

    return -1;
}

static int log_flow_rates(float flow1, float flow2) {
    FILE *fp = fopen(FLOW_LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

