#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the encoder
#define ENCODER_A_PIN 17
#define ENCODER_B_PIN 18

// Define the number of pulses per revolution (360 degrees)
#define PULSES_PER_REVOLUTION 360

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_encoder();
double calculate_angle(int pulses);
int log_data(double angle);
void signal_handler(int signal);

// Structure to hold encoder state
typedef struct {
    int last_a;
    int last_b;
    int pulses;
} EncoderState;

EncoderState encoder_state = {0, 0, 0};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as inputs
    if (gpioSetMode(ENCODER_A_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", ENCODER_A_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ENCODER_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", ENCODER_B_PIN);
        gpioTerminate();
        return -1;
    }

    // Enable internal pull-up resistors (TMAG5110A1 has open-drain output)
    if (gpioSetPullUpDown(ENCODER_A_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", ENCODER_A_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(ENCODER_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", ENCODER_B_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the current state of the encoder
int read_encoder() {
    int a = gpioRead(ENCODER_A_PIN);
    int b = gpioRead(ENCODER_B_PIN);

    if (a < 0 || b < 0) {
        fprintf(stderr, "Error reading GPIO pins\n");
        return -1;
    }

    return (a << 1) | b;
}

// Function to calculate the angle based on the number of pulses
double calculate_angle(int pulses) {
    return ((double)pulses / PULSES_PER_REVOLUTION) * 360.0;
}

// Function to log data to a file
int log_data(double angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Angle: %.2f\n", timestamp, angle) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int main() {
    // Register signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("encoder_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        int current_state = read_encoder();
        if (current_state < 0) {
            break;
        }

        // 2-bit quadrature decoding
        if (current_state != encoder_state.last_a) {
            if (current_state == 0 && encoder_state.last_a == 1) {
                if (encoder_state.last_b == 0) {
                    encoder_state.pulses++;
                } else {
                    encoder_state.pulses--;
                }
            } else if (current_state == 1 && encoder_state.last_a == 0) {
                if (encoder_state.last_b == 0) {
                    encoder_state.pulses--;
                } else {
                    encoder_state.pulses++;
                }
            } else if (current_state == 2 && encoder_state.last_a == 1) {
                if (encoder_state.last_b == 1) {
                    encoder_state.pulses++;
                } else {
                    encoder_state.pulses--;
                }
            } else if (current_state == 3 && encoder_state.last_a == 0) {
                if (encoder_state.last_b == 1) {
                    encoder_state.pulses--;
                } else {
                    encoder_state.pulses++;
                }
            }

            encoder_state.last_a = current_state;
        }

        // Log data
        double angle = calculate_angle(encoder_state.pulses);
        if (log_data(angle) != 0) {
            break;
        }

        gpioDelay(1000); // Delay for 1 millisecond
    }

    // Cleanup
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

