        if (!red_ok || !ir_ok) {
            fprintf(stderr, "I2C read error: red=%d ir=%d (%s)\n", red_ok, ir_ok, strerror(errno));
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%u,%u\n", ts, red_val, ir_val);
        fflush(log_file);

        if (ir_val > IR_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

