#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define AUDIO_PIN 17
#define GAIN_PIN 18
#define LOG_FILE "audio_log.txt"
#define POLL_INTERVAL_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(int level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s %d\n", timestamp, level) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *audio_line = NULL;
    struct gpiod_line *gain_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    audio_line = gpiod_chip_get_line(chip, AUDIO_PIN);
    if (!audio_line) {
        perror("gpiod_chip_get_line (audio)");
        goto cleanup;
    }

    gain_line = gpiod_chip_get_line(chip, GAIN_PIN);
    if (!gain_line) {
        perror("gpiod_chip_get_line (gain)");
        goto cleanup;
    }

    if (gpiod_line_request_input(audio_line, "audio_sampler") < 0) {
        perror("gpiod_line_request_input");
        goto cleanup;
    }

    if (gpiod_line_request_output(gain_line, "audio_sampler", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("Audio sampling started. Press Ctrl+C to exit.\n");

    int prev_audio = gpiod_line_get_value(audio_line);
    if (prev_audio < 0) {
        perror("gpiod_line_get_value (initial)");
        goto cleanup;
    }

    while (running) {
        int audio_val = gpiod_line_get_value(audio_line);
        if (audio_val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (audio_val == 1 && prev_audio == 0) {
            if (log_event(1) < 0) {
                fprintf(stderr, "Failed to log event\n");
            }
        }

        prev_audio = audio_val;
        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (audio_line) {
        gpiod_line_release(audio_line);
    }
    if (gain_line) {
        gpiod_line_release(gain_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Audio sampling stopped.\n");
    return ret;
}

