#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x70
#define LOG_FILE       "air_quality_log.csv"
#define READ_INTERVAL  5
#define SENSOR_STATE_LEN 7
#define TVOC_REG       0x01
#define ECO2_REG       0x05

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, uint8_t *buf) {
    if (i2cWriteByte(handle, TVOC_REG) < 0) {
        fprintf(stderr, "Error: failed to set TVOC register pointer\n");
        return -1;
    }
    int n = i2cReadDevice(handle, (char *)buf, SENSOR_STATE_LEN);
    if (n != SENSOR_STATE_LEN) {
        fprintf(stderr, "Error: I2C read returned %d bytes (expected %d)\n", n, SENSOR_STATE_LEN);
        return -1;
    }
    return 0;
}

static int extract_values(const uint8_t *buf, uint16_t *tvoc, uint16_t *eco2) {
    *tvoc = ((uint16_t)buf[1] << 8) | buf[0];
    *eco2 = ((uint16_t)buf[6] << 8) | buf[5];
    return 0;
}

static int calculate_iaq(uint16_t tvoc, uint16_t eco2, int *iaq) {
    float tvoc_score = (float)tvoc / 10.0f;
    float eco2_score = ((float)eco2 - 400.0f) / 50.0f;
    float score = 100.0f - tvoc_score - eco2_score;
    if (score < 0.0f) score = 0.0f;
    if (score > 100.0f) score = 100.0f;
    *iaq = (int)score;
    return 0;
}

static int log_data(FILE *fp, int iaq, uint16_t tvoc, uint16_t eco2) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%d,%u,%u\n", ts, iaq, tvoc, eco2) < 0) {
        fprintf(stderr, "Error: fprintf to log failed\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open %s for appending\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    uint8_t buf[SENSOR_STATE_LEN];
    uint16_t tvoc = 0, eco2 = 0;
    int iaq = 0;

    while (running) {
        if (read_sensor_data(i2c_handle, buf) == 0) {
            extract_values(buf, &tvoc, &eco2);
            calculate_iaq(tvoc, eco2, &iaq);
            if (log_data(log_file, iaq, tvoc, eco2) != 0) {
                fprintf(stderr, "Warning: log write failed\n");
            }
        } else {
            fprintf(stderr, "Warning: sensor read failed, skipping log entry\n");
        }
        sleep(READ_INTERVAL);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

