    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%d,%u,%u\n", ts, iaq, tvoc, eco2) < 0) {
        fprintf(stderr, "Error: fprintf to log failed\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open %s for appending\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    uint8_t buf[SENSOR_STATE_LEN];
    uint16_t tvoc = 0, eco2 = 0;
    int iaq = 0;

    while (running) {
        if (read_sensor_data(i2c_handle, buf) == 0) {
            extract_values(buf, &tvoc, &eco2);
            calculate_iaq(tvoc, eco2, &iaq);
            if (log_data(log_file, iaq, tvoc, eco2) != 0) {
                fprintf(stderr, "Warning: log write failed\n");
            }
        } else {
            fprintf(stderr, "Warning: sensor read failed, skipping log entry\n");
        }
        sleep(READ_INTERVAL);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

