#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define INTRUSION_THRESHOLD_SEC 5
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct timespec last_touch_ts;
    struct timespec now_ts;
    int ret;
    int last_value = -1;
    int first_read = 1;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip by name */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for the touch sensor */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as input with the consumer label */
    ret = gpiod_line_request_input(line, "ttp223_tamper");
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Monitoring TTP223B touch sensor on GPIO %d (chip %s).\n",
           GPIO_LINE_OFFSET, GPIO_CHIP_NAME);
    printf("Intrusion alert after %d seconds of continuous touch.\n",
           INTRUSION_THRESHOLD_SEC);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Initialize the last-touch timestamp to now */
    clock_gettime(CLOCK_MONOTONIC, &last_touch_ts);

    while (g_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            break;
        }

        /* Detect rising edge (touch) or falling edge (release) */
        if (value != last_value) {
            if (value == 1) {
                /* Touch detected */
                printf("Touch detected on GPIO %d\n", GPIO_LINE_OFFSET);
                fflush(stdout);
                clock_gettime(CLOCK_MONOTONIC, &last_touch_ts);
            } else {
                /* Touch released */
                printf("Touch released on GPIO %d\n", GPIO_LINE_OFFSET);
                fflush(stdout);
                clock_gettime(CLOCK_MONOTONIC, &last_touch_ts);
            }
            last_value = value;
            first_read = 0;
        }

        /* Check if intrusion threshold is exceeded */
        if (!first_read && value == 1) {
            clock_gettime(CLOCK_MONOTONIC, &now_ts);
            double elapsed = (now_ts.tv_sec - last_touch_ts.tv_sec)
                           + (now_ts.tv_nsec - last_touch_ts.tv_nsec) / 1e9;
            if (elapsed >= INTRUSION_THRESHOLD_SEC) {
                printf("INTRUSION DETECTED: GPIO %d touched for %.2f seconds!\n",
                       GPIO_LINE_OFFSET, elapsed);
                fflush(stdout);
                /* Reset the timer to avoid repeated alerts */
                clock_gettime(CLOCK_MONOTONIC, &last_touch_ts);
            }
        }

        /* Sleep for the poll interval */
        struct timespec sleep_ts;
        sleep_ts.tv_sec = POLL_INTERVAL_MS / 1000;
        sleep_ts.tv_nsec = (POLL_INTERVAL_MS % 1000) * 1000000L;
        nanosleep(&sleep_ts, NULL);
    }

    /* Clean up resources on all exit paths */
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

