#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <gpiod.h>

#define PCM_DEVICE "/dev/dsp"
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define SAMPLE_RATE 16000
#define BITS_PER_SAMPLE 16
#define NUM_CHANNELS 1
#define FRAME_BITS 32
#define FRAME_BYTES (FRAME_BITS / 8)
#define BUFFER_SIZE 4096

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_alsa(int *fd) {
    int format = AFMT_S16_LE;
    int channels = NUM_CHANNELS;
    int rate = SAMPLE_RATE;

    *fd = open(PCM_DEVICE, O_RDONLY);
    if (*fd < 0) {
        perror("Error opening PCM device");
        return -1;
    }

    if (ioctl(*fd, SNDCTL_DSP_SETFMT, &format) == -1) {
        perror("Error setting PCM format");
        close(*fd);
        return -1;
    }

    if (ioctl(*fd, SNDCTL_DSP_CHANNELS, &channels) == -1) {
        perror("Error setting PCM channels");
        close(*fd);
        return -1;
    }

    if (ioctl(*fd, SNDCTL_DSP_SPEED, &rate) == -1) {
        perror("Error setting PCM sample rate");
        close(*fd);
        return -1;
    }

    return 0;
}

static int init_gpio(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!*chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, GPIO_LINE);
    if (!*line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*line, "inmp441_lr_select", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

static int select_left_channel(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO line low");
        return -1;
    }
    return 0;
}

static int select_right_channel(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting GPIO line high");
        return -1;
    }
    return 0;
}

static int read_audio_data(int fd, int16_t *buffer, int num_samples) {
    unsigned char raw[BUFFER_SIZE];
    int bytes_to_read = num_samples * FRAME_BYTES;
    int bytes_read = 0;

    while (bytes_read < bytes_to_read) {
        int remaining = bytes_to_read - bytes_read;
        int to_read = (remaining < (int)sizeof(raw)) ? remaining : (int)sizeof(raw);

        int n = read(fd, raw, to_read);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("Error reading from PCM device");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "End of PCM stream\n");
            return -1;
        }

        memcpy(buffer + (bytes_read / FRAME_BYTES), raw, n);
        bytes_read += n;
    }

    return 0;
}

static int write_to_file(const char *filename, const int16_t *buffer, int num_samples) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t written = fwrite(buffer, sizeof(int16_t), num_samples, fp);
    if (written != (size_t)num_samples) {
        fprintf(stderr, "Error writing to file: wrote %zu of %d samples\n", written, num_samples);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing file");
        return -1;
    }

    return 0;
}

int main(void) {
    int pcm_fd = -1;
    struct gpiod_chip *gpio_chip = NULL;
    struct gpiod_line *gpio_line = NULL;
    int16_t *audio_buffer = NULL;
    int num_samples = BUFFER_SIZE / FRAME_BYTES;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        return 1;
    }

    if (init_alsa(&pcm_fd) != 0) {
        goto cleanup;
    }

    if (init_gpio(&gpio_chip, &gpio_line) != 0) {
        goto cleanup;
    }

    if (select_left_channel(gpio_line) != 0) {
        goto cleanup;
    }

    audio_buffer = (int16_t *)malloc(num_samples * sizeof(int16_t));
    if (!audio_buffer) {
        perror("Error allocating memory for audio buffer");
        goto cleanup;
    }

    printf("Starting audio capture. Press Ctrl+C to stop.\n");

    while (running) {
        if (read_audio_data(pcm_fd, audio_buffer, num_samples) != 0) {
            fprintf(stderr, "Error reading audio data\n");
            break;
        }

        if (write_to_file("audio_capture.pcm", audio_buffer, num_samples) != 0) {
            fprintf(stderr, "Error writing audio data to file\n");
            break;
        }
    }

    ret = 0;

cleanup:
    if (audio_buffer) {
        free(audio_buffer);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (pcm_fd >= 0) {
        close(pcm_fd);
    }

    printf("Audio capture stopped.\n");
    return ret;
}

