#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_MODE    0

#define TRIGGER_PIN 23
#define DATA_READY_PIN 24

#define HEATMAP_SIZE 32768
#define FRAME_PERIOD_US 100000

#define MAGIC_NUMBER 0x52444144

typedef struct {
    uint32_t magic;
    uint64_t timestamp;
    uint32_t start_freq;
    uint32_t end_freq;
    uint16_t num_chirps;
    uint16_t num_samples;
    uint32_t frame_period_us;
} __attribute__((packed)) log_header_t;

typedef struct {
    uint64_t timestamp;
    uint32_t frame_number;
    uint8_t  data[HEATMAP_SIZE];
} __attribute__((packed)) log_frame_t;

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_gpio(void) {
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        return -1;
    }
    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set data-ready pin mode\n");
        return -1;
    }
    if (gpioSetPullUpDown(DATA_READY_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on data-ready pin\n");
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize trigger pin low\n");
        return -1;
    }
    return 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %d\n", SPI_CHANNEL, spi_handle);
        return -1;
    }
    return 0;
}

static int write_header(FILE *fp) {
    log_header_t hdr;
    hdr.magic = MAGIC_NUMBER;
    hdr.timestamp = (uint64_t)time(NULL);
    hdr.start_freq = 770000000;
    hdr.end_freq = 790000000;
    hdr.num_chirps = 64;
    hdr.num_samples = 256;
    hdr.frame_period_us = 100000;

    if (fwrite(&hdr, sizeof(hdr), 1, fp) != 1) {
        fprintf(stderr, "Failed to write header\n");
        return -1;
    }
    return 0;
}

static int write_frame(FILE *fp, const log_frame_t *frame) {
    if (fwrite(frame, sizeof(*frame), 1, fp) != 1) {
        fprintf(stderr, "Failed to write frame\n");
        return -1;
    }
    return 0;
}

static int read_heatmap(uint8_t *buf, int len) {
    char tx[len];
    char rx[len];
    memset(tx, 0, len);

    int ret = spiXfer(spi_handle, tx, rx, len);
    if (ret != len) {
        fprintf(stderr, "SPI transfer failed: expected %d, got %d\n", len, ret);
        return -1;
    }
    memcpy(buf, rx, len);
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (init_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen("radar_log.bin", "wb");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    if (write_header(log_file) != 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint32_t frame_number = 0;

    while (!terminate) {
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Failed to assert trigger\n");
            break;
        }
        gpioDelay(10);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Failed to deassert trigger\n");
            break;
        }

        uint32_t timeout = 0;
        while (gpioRead(DATA_READY_PIN) == 0) {
            gpioDelay(100);
            timeout += 100;
            if (timeout > 100000) {
                fprintf(stderr, "Timeout waiting for data-ready\n");
                break;
            }
            if (terminate) break;
        }
        if (terminate) break;

        log_frame_t frame;
        frame.timestamp = (uint64_t)time(NULL);
        frame.frame_number = frame_number++;

        if (read_heatmap(frame.data, HEATMAP_SIZE) != 0) {
            fprintf(stderr, "Failed to read heatmap\n");
            break;
        }

        if (write_frame(log_file, &frame) != 0) {
            break;
        }

        gpioDelay(FRAME_PERIOD_US - 1000);
    }

    cleanup();
    return 0;
}

