#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define OPT3001_ADDR 0x44
#define REG_RESULT 0x00
#define REG_CONFIG 0x01
#define CONFIG_CONTINUOUS_AUTO 0xC610
#define LOG_FILE "light_data.txt"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_config(int handle, uint16_t value) {
    char buf[2];
    buf[0] = (value >> 8) & 0xFF;
    buf[1] = value & 0xFF;
    if (i2cWriteI2CBlockData(handle, REG_CONFIG, buf, 2) < 0) {
        return -1;
    }
    return 0;
}

static int read_result(int handle, uint16_t *result) {
    char buf[2];
    int bytes = i2cReadI2CBlockData(handle, REG_RESULT, buf, 2);
    if (bytes != 2) {
        return -1;
    }
    *result = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint16_t)(buf[1] & 0xFF);
    return 0;
}

static float calculate_lux(uint16_t raw) {
    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    return 0.01f * (float)(1 << exponent) * (float)mantissa;
}

static int log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_config(i2c_handle, CONFIG_CONTINUOUS_AUTO) < 0) {
        fprintf(stderr, "Error configuring OPT3001\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("OPT3001 light sensor logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t raw = 0;
        int success = 0;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (read_result(i2c_handle, &raw) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "I2C read error (attempt %d/%d)\n", attempt + 1, MAX_RETRIES);
            gpioDelay(100000);
        }
        if (!success) {
            fprintf(stderr, "Failed to read sensor after %d attempts. Skipping sample.\n", MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        float lux = calculate_lux(raw);
        if (log_data(lux) < 0) {
            fprintf(stderr, "Error logging data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

