/*
 * Flame Detection Monitor using SainSmart IR Flame Sensor Module
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: SainSmart IR Flame Detection Sensor Module
 * Wiring: VCC -> 3.3V (Pin 1), GND -> GND (Pin 6), DOUT -> GPIO17 (Pin 11)
 * Logic:  DOUT is active-low: 0 = flame detected, 1 = no flame.
 *
 * Build:  gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[80];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        if (strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timeinfo) > 0) {
            printf("[%s] ", buffer);
            return;
        }
    }
    printf("[unknown-time] ");
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *line_settings = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct gpiod_line_request *line_req = NULL;
    int ret;

    /* Install signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure line settings: input direction, pull-up bias */
    line_settings = gpiod_line_settings_new();
    if (line_settings == NULL) {
        fprintf(stderr, "Error: Failed to allocate line settings: %s\n",
                strerror(errno));
        goto cleanup_chip;
    }

    ret = gpiod_line_settings_set_direction(line_settings,
                                            GPIOD_LINE_DIRECTION_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set line direction: %s\n",
                strerror(errno));
        goto cleanup_line_settings;
    }

    ret = gpiod_line_settings_set_bias(line_settings, GPIOD_LINE_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set pull-up bias: %s\n",
                strerror(errno));
        goto cleanup_line_settings;
    }

    /* Configure the specific GPIO line */
    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "Error: Failed to allocate line config: %s\n",
                strerror(errno));
        goto cleanup_line_settings;
    }

    ret = gpiod_line_config_add_line_settings(line_cfg,
                                              &(unsigned int){GPIO_LINE_OFFSET},
                                              1, line_settings);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to add line settings: %s\n",
                strerror(errno));
        goto cleanup_line_cfg;
    }

    /* Configure the request: consumer label */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "Error: Failed to allocate request config: %s\n",
                strerror(errno));
        goto cleanup_line_cfg;
    }

    gpiod_request_config_set_consumer(req_cfg, "flame-detect");

    /* Request the line from the chip */
    line_req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (line_req == NULL) {
        fprintf(stderr, "Error: Failed to request GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_req_cfg;
    }

    printf("Flame detection started on GPIO%d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    /* Main polling loop */
    while (program_running) {
        int value = gpiod_line_request_get_value(line_req, GPIO_LINE_OFFSET);
        if (value < 0) {
            fprintf(stderr, "Error: Failed to read GPIO line %d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            break;
        }

        print_timestamp();
        if (value == 0) {
            printf("Flame Detected: YES\n");
        } else {
            printf("Flame Detected: NO\n");
        }
        fflush(stdout);

        /* Sleep for the poll interval, interruptible by signals */
        for (int i = 0; i < POLL_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");

    /* Clean up resources in reverse order */
    gpiod_line_request_release(line_req);
cleanup_req_cfg:
    gpiod_request_config_free(req_cfg);
cleanup_line_cfg:
    gpiod_line_config_free(line_cfg);
cleanup_line_settings:
    gpiod_line_settings_free(line_settings);
cleanup_chip:
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

