    if (gpioSetMode(CENTER_SENSOR, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", CENTER_SENSOR);
        gpioTerminate();
        return EXIT_FAILURE;
