#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 100

static const unsigned int channel_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int ret;
    int i;

    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = NULL;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, channel_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", channel_pins[i]);
            goto cleanup;
        }

        ret = gpiod_line_request_input(lines[i], "ttp226-reader");
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input\n", channel_pins[i]);
            goto cleanup;
        }
    }

    printf("TTP226 8-Channel Touch Sensor Reader\n");
    printf("Pins: BCM %u, %u, %u, %u, %u, %u, %u, %u\n",
           channel_pins[0], channel_pins[1], channel_pins[2], channel_pins[3],
           channel_pins[4], channel_pins[5], channel_pins[6], channel_pins[7]);
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading GPIO line %u\n", channel_pins[i]);
                goto cleanup;
            }
            printf("Channel %d (BCM %u): %d\n", i + 1, channel_pins[i], val);
        }
        printf("---\n");
        fflush(stdout);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");

cleanup:
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return (program_running == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

