#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 100000  /* 100 ms */

/* TTP226 OUT1..OUT8 -> BCM GPIO 2..9 */
static const int sensor_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        int pin = sensor_pins[i];
        if (gpioSetMode(pin, PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", pin);
            return -1;
        }
        if (gpioSetPullUpDown(pin, PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d.\n", pin);
            return -1;
        }
    }
    return 0;
}

static void read_sensor_data(int *values)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        values[i] = gpioRead(sensor_pins[i]);
    }
}

static void log_sensor_data(const int *values)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    long elapsed_ms = (long)ts.tv_sec * 1000L + ts.tv_nsec / 1000000L;

    printf("[+%ld ms] ", elapsed_ms);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        printf("CH%d=%d ", i + 1, values[i]);
    }
    printf("\n");
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int sensor_values[NUM_CHANNELS];

    while (program_running) {
        read_sensor_data(sensor_values);
        log_sensor_data(sensor_values);
        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

