/*
 * TMAG5110 Hall-Effect Latch Sensor Reader
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio
 *
 * Wiring (BCM numbering):
 *   Sensor 1 OUT -> BCM GPIO 4 (with external pull-up to 3.3 V)
 *   Sensor 2 OUT -> BCM GPIO 5 (with external pull-up to 3.3 V)
 *
 * The TMAG5110 open-drain output is active-low:
 *   HIGH (1) = no magnet detected
 *   LOW  (0) = magnet detected
 *
 * Build: gcc -Wall -o hall_effect hall_effect.c -lpigpio -lrt
 * Run:   sudo ./hall_effect
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 5
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C)                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin and print its logical state                       */
/* ------------------------------------------------------------------ */
static void read_and_print_sensor(int gpio_pin, int sensor_id)
{
    int level = gpioRead(gpio_pin);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d (sensor %d)\n",
                gpio_pin, sensor_id);
        return;
    }

    /*
     * TMAG5110 open-drain: LOW  (0) = magnet detected
     *                      HIGH (1) = no magnet
     */
    const char *state_str = (level == 0) ? "MAGNET_DETECTED" : "NO_MAGNET";
    printf("Sensor %d (GPIO %d): %s\n", sensor_id, gpio_pin, state_str);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        fprintf(stderr, "       Run as root (sudo) and ensure pigpiod is not running.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins as inputs ------------------------------ */
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handler for graceful shutdown --------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMAG5110 Hall-Effect Sensor Reader\n");
    printf("Sensor 1: BCM GPIO %d | Sensor 2: BCM GPIO %d\n",
           SENSOR_1_GPIO, SENSOR_2_GPIO);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main polling loop ------------------------------------------ */
    while (g_running) {
        read_and_print_sensor(SENSOR_1_GPIO, 1);
        read_and_print_sensor(SENSOR_2_GPIO, 2);
        printf("---\n");
        fflush(stdout);

        /*
         * gpioDelay returns the actual delay; if it returns a negative
         * value, the delay was interrupted by a signal.
         */
        if (gpioDelay(POLL_INTERVAL_US) < 0) {
            /* Signal interrupted the delay; check g_running and retry */
            if (!g_running) {
                break;
            }
        }
    }

    /* --- Cleanup ---------------------------------------------------- */
    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

