#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SI1145_ADDR 0x60
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_CHLIST 0x01
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_UVINDEX0 0x2C
#define SI1145_REG_UVINDEX1 0x2D
#define SI1145_REG_COMMAND 0x30
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_PART_ID 0x45
#define SI1145_HW_KEY_VAL 0x17

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg) {
    int data = i2cReadByteData(handle, reg);
    if (data < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, data);
    }
    return data;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
    }
    return result;
}

static int initialize_sensor(int handle) {
    int part_id = read_register(handle, SI1145_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }
    printf("Si1145 detected (PART_ID: 0x%02X)\n", part_id);

    if (write_register(handle, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) return -1;
    if (write_register(handle, SI1145_REG_CHLIST, 0x03) < 0) return -1;

    return 0;
}

static int read_uv_index(int handle) {
    int low = read_register(handle, SI1145_REG_UVINDEX0);
    int high = read_register(handle, SI1145_REG_UVINDEX1);
    if (low < 0 || high < 0) return -1;
    return (high << 8) | low;
}

static int read_als_visible(int handle) {
    int low = read_register(handle, SI1145_REG_ALS_VIS_DATA0);
    int high = read_register(handle, SI1145_REG_ALS_VIS_DATA1);
    if (low < 0 || high < 0) return -1;
    return (high << 8) | low;
}

static void log_data(FILE *fp, int uv_index, int als_visible) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%d,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, uv_index, als_visible);
    fflush(fp);
}

static void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting data acquisition...\n");

    while (!terminate) {
        if (write_register(i2c_handle, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) {
            fprintf(stderr, "Error triggering ALS measurement\n");
            gpioDelay(1000000);
            continue;
        }
        gpioDelay(10000);

        int uv_index = read_uv_index(i2c_handle);
        int als_visible = read_als_visible(i2c_handle);

        if (uv_index >= 0 && als_visible >= 0) {
            printf("UV Index: %d, ALS Visible: %d\n", uv_index, als_visible);
            log_data(log_file, uv_index, als_visible);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(1000000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

