    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }
    struct gpiod_line *alarm = gpiod_chip_get_line(chip, ALARM_GPIO);
    if (!alarm) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", ALARM_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(alarm, "flow_alarm", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", ALARM_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int fd1 = open(I2C_BUS, O_RDWR);
    if (fd1 < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpiod_line_release(alarm);
        gpiod_chip_close(chip);
        return 1;
    }
    int fd2 = open(I2C_BUS, O_RDWR);
    if (fd2 < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        close(fd1);
        gpiod_line_release(alarm);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(fd1, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", SENSOR1_ADDR, strerror(errno));
        goto cleanup;
    }
    if (ioctl(fd2, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", SENSOR2_ADDR, strerror(errno));
        goto cleanup;
    }

    if (i2c_write_cmd(fd1, CMD_START_MEAS) < 0 ||
        i2c_write_cmd(fd2, CMD_START_MEAS) < 0) {
        fprintf(stderr, "Failed to start measurement on sensors\n");
        goto cleanup;
    }
    usleep(MEAS_DELAY_MS * 1000);

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    while (running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = (read_flow_rate(fd1, &f1) == 0);
        int ok2 = (read_flow_rate(fd2, &f2) == 0);

        if (!ok1) fprintf(stderr, "Sensor 1 read error\n");
        if (!ok2) fprintf(stderr, "Sensor 2 read error\n");

        float avg = 0.0f;
        if (ok1 && ok2) {
            avg = (f1 + f2) / 2.0f;
            log_flow_rate(fp, f1, f2, avg);
        } else if (ok1) {
