#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000  /* 50 ms */

/* Circular buffer entry */
typedef struct {
    time_t timestamp;
    int    reading;
} sensor_data_t;

static sensor_data_t buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t running = 1;

/* Signal handler for graceful shutdown (Ctrl+C) */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Initialize pigpio and configure the sensor pin */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to enable pull-up on GPIO %d\n", SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Read the sensor value (0 = obstacle detected, 1 = clear) */
static int read_sensor(void) {
    return gpioRead(SENSOR_PIN);
}

/* Add a reading to the circular buffer */
static void add_to_buffer(int reading) {
    buffer[buffer_index].timestamp = time(NULL);
    buffer[buffer_index].reading   = reading;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

/* Print the entire buffer contents in chronological order */
static void print_buffer(void) {
    printf("\n--- Obstacle Detection Log ---\n");

    /* Start from the oldest entry (overwritten when full) */
    int start = (buffer_count == BUFFER_SIZE) ? buffer_index : 0;

    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&buffer[idx].timestamp);

        if (tm_info != NULL) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "UNKNOWN", sizeof(time_str));
            time_str[sizeof(time_str) - 1] = '\0';
        }

        printf("[%s] Obstacle %s (reading=%d)\n",
               time_str,
               (buffer[idx].reading == 0) ? "DETECTED" : "CLEAR",
               buffer[idx].reading);
    }

    printf("--- End of Log ---\n\n");
    fflush(stdout);
}

int main(void) {
    /* Register signal handler for SIGINT */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Obstacle detection started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_PIN);
    fflush(stdout);

    while (running) {
        int reading = read_sensor();

        if (reading == 0) {
            add_to_buffer(reading);
            printf("Obstacle detected! (reading=%d)\n", reading);
            fflush(stdout);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    print_buffer();

    gpioTerminate();
    return EXIT_SUCCESS;
}

