#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x55
#define REG_MODE_CTRL  0x1D
#define REG_OP_STATUS  0x1B
#define REG_X_LSB      0x2A
#define REG_X_MSB      0x2B
#define REG_Y_LSB      0x2C
#define REG_Y_MSB      0x2D
#define REG_Z_LSB      0x2E
#define REG_Z_MSB      0x2F
#define ACTIVE_MODE    0x10
#define STATUS_ACTIVE  0x01
#define SCALE_FACTOR   0.0009765625f
#define SAMPLE_MS      500
#define MAX_INIT_MS    1000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv   = NULL;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg_lsb, int16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg_lsb, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, reg_lsb + 1, &hi) < 0) return -1;
    *out = (int16_t)((uint16_t)hi << 8 | (uint16_t)lo);
    return 0;
}

static int init_sensor(int fd)
