        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-ups so the sensors read HIGH when clear */
    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Conveyor belt stall detection started.\n");
    printf("  Sensor 1: GPIO %d\n", SENSOR_1_GPIO);
    printf("  Sensor 2: GPIO %d\n", SENSOR_2_GPIO);
    printf("  Stall duration: %d seconds\n", STALL_DURATION_SEC);
    printf("  Log file: %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    time_t stall_start_time = 0;
    int stall_confirmed = 0;

    while (running) {
        int s1 = gpioRead(SENSOR_1_GPIO);
        int s2 = gpioRead(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error reading sensor GPIO (s1=%d, s2=%d)\n", s1, s2);
