                    }
                    stall_confirmed = 0;
                }
            }
        } else {
            stall_confirmed = 0;
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
