#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* TMAG5170-Q1 I2C address (A0=A1=0) */
#define TMAG5170_ADDR 0x0E

/* TMAG5170-Q1 register addresses */
#define REG_DEVICE_ID  0x00
#define REG_CONFIG_1   0x01
#define REG_CONFIG_2   0x02
#define REG_X_MSB      0x03
#define REG_X_LSB      0x04
#define REG_Y_MSB      0x05
#define REG_Y_LSB      0x06
#define REG_Z_MSB      0x07
#define REG_Z_LSB      0x08

/* Expected device ID for TMAG5170-Q1 */
#define TMAG5170_DEVICE_ID 0x8D

/* Configuration values */
#define CONFIG_1_CONT_CONV 0x00  /* Continuous conversion mode */
#define CONFIG_1_MAG_CH_EN 0x07  /* X, Y, Z channels enabled */
#define CONFIG_2_50MT_RANGE 0x00 /* 50 mT range */

/* LSB scale factor for 50 mT range: 1.32 mT per LSB */
#define LSB_TO_MT 1.32f

/* Global variables for signal handler */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a 16-bit value to a 16-bit TMAG5170 register (MSB first) */
static int write_reg16(int handle, uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);
    buf[2] = (char)(value & 0xFF);
    return i2cWriteDevice(handle, buf, 3);
}

/* Read a 16-bit value from a 16-bit TMAG5170 register (MSB first) */
static int read_reg16(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* Initialize the TMAG5170 sensor */
static int init_tmag5170(int handle) {
    uint16_t device_id;

    /* Verify device ID */
    if (read_reg16(handle, REG_DEVICE_ID, &device_id) != 0) {
        fprintf(stderr, "Error: Failed to read device ID register.\n");
        return -1;
    }
    if (device_id != TMAG5170_DEVICE_ID) {
        fprintf(stderr, "Error: Incorrect device ID (0x%04X). Expected 0x%02X.\n",
                device_id, TMAG5170_DEVICE_ID);
        return -1;
    }

    /* Configure CONFIG_1: continuous conversion, all channels enabled */
    if (write_reg16(handle, REG_CONFIG_1, CONFIG_1_CONT_CONV | CONFIG_1_MAG_CH_EN) != 0) {
        fprintf(stderr, "Error: Failed to write CONFIG_1.\n");
        return -1;
    }

    /* Configure CONFIG_2: 50 mT range */
    if (write_reg16(handle, REG_CONFIG_2, CONFIG_2_50MT_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to write CONFIG_2.\n");
        return -1;
    }

    return 0;
}

/* Read magnetic field data from the sensor */
static int read_magnetic_data(int handle, float *x, float *y, float *z) {
    uint16_t x_raw, y_raw, z_raw;

    if (read_reg16(handle, REG_X_MSB, &x_raw) != 0) {
        fprintf(stderr, "Error: Failed to read X axis data.\n");
        return -1;
    }
    if (read_reg16(handle, REG_Y_MSB, &y_raw) != 0) {
        fprintf(stderr, "Error: Failed to read Y axis data.\n");
        return -1;
    }
    if (read_reg16(handle, REG_Z_MSB, &z_raw) != 0) {
        fprintf(stderr, "Error: Failed to read Z axis data.\n");
        return -1;
    }

    /* Convert raw 16-bit two's-complement to signed 16-bit */
    int16_t x_signed = (int16_t)x_raw;
    int16_t y_signed = (int16_t)y_raw;
    int16_t z_signed = (int16_t)z_raw;

    /* Convert to mT using LSB scale factor */
    *x = (float)x_signed * LSB_TO_MT;
    *y = (float)y_signed * LSB_TO_MT;
    *z = (float)z_signed * LSB_TO_MT;

    return 0;
}

/* Log data to CSV file */
static void log_data(FILE *fp, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(fp);
}

int main(void) {
    float x, y, z;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at TMAG5170 address */
    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (init_tmag5170(i2c_handle) != 0) {
        fprintf(stderr, "Error: TMAG5170 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open magnetic_log.csv for writing.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if the file is newly created */
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_mT,Y_mT,Z_mT\n");
        fflush(log_file);
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("TMAG5170 logging started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        if (read_magnetic_data(i2c_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Warning: Failed to read sensor data. Retrying...\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

