#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27
#define LOG_FILE "rotation_log.txt"

/* Quadrature state machine: two bits from A and B */
typedef enum {
    QUAD_STATE_00 = 0,
    QUAD_STATE_01 = 1,
    QUAD_STATE_11 = 2,
    QUAD_STATE_10 = 3
} quad_state_t;

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

/* Shared state between ISR and main loop */
static volatile int prev_a = 0, prev_b = 0;
static volatile quad_state_t prev_quad = QUAD_STATE_00;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * pigpio alert callback runs in a pigpio thread.
 * Keep it minimal: only update volatile state and signal the main loop.
 */
static void rotation_alert(int gpio, int level, uint32_t tick) {
    (void)tick;
    if (gpio == SENSOR_A_GPIO) {
        prev_a = level;
    } else if (gpio == SENSOR_B_GPIO) {
        prev_b = level;
    }
    /* Re-evaluate direction in main loop to protect shared state */
}

static quad_state_t get_quad_state(int a, int b) {
    return (quad_state_t)((a << 1) | b);
}

static const char *determine_direction(quad_state_t current, quad_state_t previous) {
    /* Quadrature direction: one step per quadrature cycle */
    switch (previous) {
        case QUAD_STATE_00:
            return (current == QUAD_STATE_01) ? "CW" : "CCW";
        case QUAD_STATE_01:
            return (current == QUAD_STATE_11) ? "CW" : "CCW";
        case QUAD_STATE_11:
            return (current == QUAD_STATE_10) ? "CW" : "CCW";
        case QUAD_STATE_10:
            return (current == QUAD_STATE_00) ? "CW" : "CCW";
        default:
            return "UNKNOWN";
    }
}

static void log_rotation(const char *direction) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[40];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%03ld", ts.tv_nsec / 1000000);

    pthread_mutex_lock(&log_mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, direction);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    pthread_mutex_unlock(&log_mutex);
}

int main(void) {
    struct sigaction sa;
    int ret;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as inputs with pull-up resistors */
    if (gpioSetMode(SENSOR_A_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_A_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_B_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_A_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register alert callbacks for edge-triggered interrupts */
    if (gpioSetAlertFunc(SENSOR_A_GPIO, rotation_alert) != 0) {
        fprintf(stderr, "Failed to set alert on GPIO %d\n", SENSOR_A_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFunc(SENSOR_B_GPIO, rotation_alert) != 0) {
        fprintf(stderr, "Failed to set alert on GPIO %d\n", SENSOR_B_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    /* Main loop: process queued events and detect direction */
    while (running) {
        int a = prev_a;
        int b = prev_b;
        quad_state_t current = get_quad_state(a, b);

        if (current != prev_quad) {
            const char *direction = determine_direction(current, prev_quad);
            log_rotation(direction);
            prev_quad = current;
        }

        /* Sleep briefly to avoid busy-waiting; pigpio alerts wake us */
        gpioDelay(1000); /* 1 ms */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioSetAlertFunc(SENSOR_A_GPIO, NULL);
    gpioSetAlertFunc(SENSOR_B_GPIO, NULL);

    pthread_mutex_lock(&log_mutex);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_unlock(&log_mutex);

    gpioTerminate();
    return EXIT_SUCCESS;
}

