#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define TOUCH_GPIO 17
#define LED_GPIO   18
#define DEBOUNCE_MS 50

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_ms(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_GPIO);
    if (!touch_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", TOUCH_GPIO, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", LED_GPIO, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_rising_edge_events(touch_line, "ttp223b-touch") < 0) {
        fprintf(stderr, "gpiod_line_request_rising_edge_events: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "ttp223b-led", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Touch sensor on GPIO %d, LED on GPIO %d. Press Ctrl+C to exit.\n",
           TOUCH_GPIO, LED_GPIO);

    int led_state = 0;
    long long last_event_ms = 0;

    while (running) {
        struct timespec ts = { 1, 0 }; /* 1 s timeout so we can re-check running */
        int ev = gpiod_line_event_wait(touch_line, &ts);
        if (ev < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "gpiod_line_event_wait: %s\n", strerror(errno));
            goto cleanup;
        }
        if (ev == 0) {
            continue; /* timeout, loop back to check running */
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(touch_line, &event) < 0) {
            fprintf(stderr, "gpiod_line_event_read: %s\n", strerror(errno));
            goto cleanup;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
            continue;
        }

        long long now = now_ms();
        if (now - last_event_ms < DEBOUNCE_MS) {
            continue;
        }
        last_event_ms = now;

        led_state = !led_state;
        if (gpiod_line_set_value(led_line, led_state) < 0) {
            fprintf(stderr, "gpiod_line_set_value: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("Touch detected, LED toggled to %s\n", led_state ? "ON" : "OFF");
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

