#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN    27
#define LED_2_PIN    22
#define BUFFER_SIZE  100
#define POLL_DELAY_US 50000  /* 50 ms */

typedef struct {
    int    sensor_pin;
    time_t timestamp;
    int    state;
} Event;

static Event event_buffer[BUFFER_SIZE];
static int   buffer_index = 0;
static int   buffer_overflow_count = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_1_PIN);
        return -1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_2_PIN);
        return -1;
    }

    /* Start with LEDs off */
    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d.\n", LED_1_PIN);
        return -1;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d.\n", LED_2_PIN);
        return -1;
    }

    return 0;
}

static void log_event(int sensor_pin, int state) {
    event_buffer[buffer_index].sensor_pin = sensor_pin;
    event_buffer[buffer_index].timestamp  = time(NULL);
    event_buffer[buffer_index].state      = state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_index == 0) {
        buffer_overflow_count++;
    }
}

static void print_buffer(void) {
    printf("\n--- Event Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        printf("  [%3d] Sensor: %d, Timestamp: %ld, State: %d\n",
               i,
               event_buffer[idx].sensor_pin,
               (long)event_buffer[idx].timestamp,
               event_buffer[idx].state);
    }
    printf("Buffer overflow count: %d\n", buffer_overflow_count);
}

static void cleanup(void) {
    /* Ensure LEDs are off before terminating */
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int prev_s1 = 0, prev_s2 = 0;

    while (running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0) {
            fprintf(stderr, "Warning: gpioRead failed on sensor 1 (GPIO %d).\n", SENSOR_1_PIN);
        } else if (s1 != prev_s1) {
            if (gpioWrite(LED_1_PIN, s1) != 0) {
                fprintf(stderr, "Warning: gpioWrite failed on LED 1 (GPIO %d).\n", LED_1_PIN);
            }
            log_event(SENSOR_1_PIN, s1);
            prev_s1 = s1;
        }

        if (s2 < 0) {
            fprintf(stderr, "Warning: gpioRead failed on sensor 2 (GPIO %d).\n", SENSOR_2_PIN);
        } else if (s2 != prev_s2) {
            if (gpioWrite(LED_2_PIN, s2) != 0) {
                fprintf(stderr, "Warning: gpioWrite failed on LED 2 (GPIO %d).\n", LED_2_PIN);
            }
            log_event(SENSOR_2_PIN, s2);
            prev_s2 = s2;
        }

        gpioDelay(POLL_DELAY_US);
    }

    print_buffer();
    cleanup();
    return EXIT_SUCCESS;
}

