#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define DEBOUNCE_US 5000  // 5 ms debounce in microseconds
#define PULSES_PER_REV 2

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int read_sensor(int gpio) {
    return gpioRead(gpio);
}

void log_data(FILE *fp, int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(fp, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
    fflush(fp);
}

int main() {
    FILE *fp = NULL;
    int sensor1_state, sensor2_state;
    int last_sensor1_state = -1;
    int last_sensor2_state = -1;
    uint32_t last_pulse_time1 = 0;
    uint32_t last_pulse_time2 = 0;
    int pulses1 = 0;
    int pulses2 = 0;
    double rpm1 = 0.0;
    double rpm2 = 0.0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    fp = fopen("shaft_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    printf("Monitoring shaft RPM. Press Ctrl+C to exit.\n");

    while (program_running) {
        sensor1_state = read_sensor(SENSOR1_GPIO);
        sensor2_state = read_sensor(SENSOR2_GPIO);

        if (sensor1_state != last_sensor1_state) {
            uint32_t now = gpioTick();
            if (now - last_pulse_time1 > DEBOUNCE_US) {
                log_data(fp, sensor1_state, sensor2_state);
                last_pulse_time1 = now;
                if (sensor1_state == 1) {
                    pulses1++;
                }
            }
            last_sensor1_state = sensor1_state;
        }

        if (sensor2_state != last_sensor2_state) {
            uint32_t now = gpioTick();
            if (now - last_pulse_time2 > DEBOUNCE_US) {
                log_data(fp, sensor1_state, sensor2_state);
                last_pulse_time2 = now;
                if (sensor2_state == 1) {
                    pulses2++;
                }
            }
            last_sensor2_state = sensor2_state;
        }

        gpioDelay(1000); // 1 ms delay to reduce CPU usage
    }

    // Calculate RPM over the last 1 second window
    uint32_t elapsed_us = gpioTick();
    if (elapsed_us > 0) {
        rpm1 = (pulses1 * 60000000.0) / (elapsed_us * PULSES_PER_REV);
        rpm2 = (pulses2 * 60000000.0) / (elapsed_us * PULSES_PER_REV);
    }

    printf("Sensor 1 RPM: %.2f\n", rpm1);
    printf("Sensor 2 RPM: %.2f\n", rpm2);

    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();

    return 0;
}

