#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x28
#define PART_ID_REG 0x00
#define HEART_RATE_REG 0x02
#define SPO2_REG 0x04
#define CONFIG_REG 0x30
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_heart_rate(int handle, int *heart_rate) {
    uint8_t value;
    if (read_register(handle, HEART_RATE_REG, &value) != 0) {
        return -1;
    }
    *heart_rate = (int)value;
    return 0;
}

static int read_spo2(int handle, int *spo2) {
    uint8_t value;
    if (read_register(handle, SPO2_REG, &value) != 0) {
        return -1;
    }
    *spo2 = (int)value;
    return 0;
}

static int log_data(FILE *fp, int heart_rate, int spo2) {
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time\n");
        return -1;
    }
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error converting time\n");
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }
    if (fprintf(fp, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t part_id;
    if (read_register(i2c_handle, PART_ID_REG, &part_id) != 0) {
        fprintf(stderr, "Sensor not detected at address 0x%02X\n", SI1182_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }
    printf("Si1182 detected, PART_ID: 0x%02X\n", part_id);

    if (write_register(i2c_handle, CONFIG_REG, 0x01) != 0) {
        fprintf(stderr, "Error configuring sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting data acquisition...\n");

    while (!terminate) {
        int heart_rate, spo2;

        if (read_heart_rate(i2c_handle, &heart_rate) != 0) {
            fprintf(stderr, "Error reading heart rate\n");
        } else if (read_spo2(i2c_handle, &spo2) != 0) {
            fprintf(stderr, "Error reading SpO2\n");
        } else {
            if (log_data(log_file, heart_rate, spo2) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

