code:
/*
 * Seismic monitor using an Omron D7S-A0011 sensor on a Raspberry Pi 3 B+.
 *
 * Wiring:
 *   D7S SDA  -> GPIO 2 (I2C bus 1 SDA)
 *   D7S SCL  -> GPIO 3 (I2C bus 1 SCL)
 *   D7S VDD  -> 3.3 V
 *   D7S GND  -> GND
 *   LED +    -> GPIO 17 (with ~330 ohm series resistor)
 *   LED -    -> GND
 *
 * Build: gcc -O2 -Wall -o seismic seismic.c -lpigpio -lm -lrt
 * Run:   sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS            1
#define I2C_ADDR           0x1D          /* D7S default 7-bit address */
#define LED_GPIO           17
#define THRESHOLD          500.0f        /* Vibration magnitude threshold */
#define POLL_INTERVAL_US   100000        /* 100 ms */
#define LED_ON_TIME_US     1000000       /* 1 s */
#define MAX_RETRIES        3
#define LOG_FILE           "seismic_events.log"

/* D7S register addresses */
#define REG_CTRL1          0x1F
#define REG_CTRL2          0x20
#define REG_CTRL3          0x21
#define REG_CTRL4          0x22
#define REG_CTRL5          0x23
#define REG_OUT_T_L        0x28          /* X-axis low byte  */
#define REG_OUT_T_H        0x29          /* X-axis high byte */
#define REG_OUT_R_L        0x2A          /* Y-axis low byte  */
#define REG_OUT_R_H        0x2B          /* Y-axis high byte */
#define REG_OUT_P_L        0x2C          /* Z-axis low byte  */
#define REG_OUT_P_H        0x2D          /* Z-axis high byte */

/* ---- Globals for cleanup ---- */
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;
static volatile sig_atomic_t g_running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */

/*
 * Write a single byte to a register.
 * Returns 0 on success, -1 on failure.
 */
static int d7s_write_reg(uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(g_i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X, val=0x%02X) failed\n",
                reg, value);
        return -1;
    }
    return 0;
}

/*
 * Read `len` bytes starting at `reg` using a combined SMBus-style
 * write-address + read-block transfer.
 * Returns 0 on success, -1 on failure.
 */
static int d7s_read_block(uint8_t reg, uint8_t *buf, uint8_t len)
{
    char addr = (char)reg;
    if (i2cWriteDevice(g_i2c_handle, &addr, 1) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(g_i2c_handle, (char *)buf, len) != len) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X, len=%u) failed\n",
                reg, len);
        return -1;
    }
    return 0;
}

/* ---- Sensor initialization ---- */
static int d7s_init(void)
{
    /* Verify sensor presence by reading CTRL1 */
    uint8_t ctrl1 = 0;
    if (d7s_read_block(REG_CTRL1, &ctrl1, 1) != 0) {
        fprintf(stderr, "[ERROR] Sensor not responding on I2C addr 0x%02X\n",
                I2C_ADDR);
        return -1;
    }
    printf("[INFO] D7S detected (CTRL1=0x%02X)\n", ctrl1);

    /* Clear power-down bit in CTRL1 to enable sensor */
    if (d7s_write_reg(REG_CTRL1, ctrl1 & 0x7F) != 0) {
        fprintf(stderr, "[ERROR] Failed to clear power-down bit\n");
        return -1;
    }

    /* Allow sensor to settle after enabling */
    gpioDelay(50000); /* 50 ms */
    return 0;
}

/* ---- Read 3-axis acceleration (6 bytes, little-endian) ---- */
static int d7s_read_accel(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (d7s_read_block(REG_OUT_T_L, buf, 6) != 0)
        return -1;

    *x = (int16_t)((uint16_t)buf[1] << 8 | buf[0]);
    *y = (int16_t)((uint16_t)buf[3] << 8 | buf[2]);
    *z = (int16_t)((uint16_t)buf[5] << 8 | buf[4]);
    return 0;
}

/* ---- Vibration magnitude ---- */
static float calc_magnitude(int16_t x, int16_t y, int16_t z)
{
    return sqrtf((float)(x * x + y * y + z * z));
}

/* ---- LED control ---- */
static void led_on(void)
{
    gpioWrite(LED_GPIO, 1);
}

static void led_off(void)
{
    gpioWrite(LED_GPIO, 0);
}

/* ---- Logging ---- */
static void log_event(float magnitude)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(g_log_file, "%s - Vibration magnitude: %.2f\n", ts, magnitude);
    fflush(g_log_file);
    printf("[EVENT] %s - Vibration magnitude: %.2f\n", ts, magnitude);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    led_off();
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (d7s_init() != 0) {
        fprintf(stderr, "[FATAL] D7S initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    led_off();

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Seismic monitor running. Threshold=%.1f, LED=GPIO%d\n",
           THRESHOLD, LED_GPIO);
    printf("[INFO] Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        int16_t x = 0, y = 0, z = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (d7s_read_accel(&x, &y, &z) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(10000); /* 10 ms backoff */
        }

        if (!ok) {
            fprintf(stderr, "[WARN] Acceleration read failed after %d attempts\n",
                    MAX_RETRIES);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        float mag = calc_magnitude(x, y, z);

        if (mag > THRESHOLD) {
            led_on();
            log_event(mag);
            /* Keep LED on for 1 s, checking for shutdown */
            for (int i = 0; i < 10 && g_running; ++i)
                gpioDelay(100000);
            led_off();
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

