    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Seismic monitor running. Threshold=%.1f, LED=GPIO%d\n",
           THRESHOLD, LED_GPIO);
    printf("[INFO] Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        int16_t x = 0, y = 0, z = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (d7s_read_accel(&x, &y, &z) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(10000); /* 10 ms backoff */
        }

        if (!ok) {
            fprintf(stderr, "[WARN] Acceleration read failed after %d attempts\n",
                    MAX_RETRIES);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        float mag = calc_magnitude(x, y, z);

        if (mag > THRESHOLD) {
            led_on();
            log_event(mag);
            /* Keep LED on for 1 s, checking for shutdown */
            for (int i = 0; i < 10 && g_running; ++i)
                gpioDelay(100000);
            led_off();
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

