#define LED_PIN 18
#define POLL_INTERVAL_US 50000

static const unsigned int sensor_pins[NUM_SENSORS] = {4, 17, 27, 22};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_lines[NUM_SENSORS];
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_SENSORS; i++)
        sensor_lines[i] = NULL;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip4 on Raspberry Pi 5) */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get and request sensor lines as inputs */
    for (int i = 0; i < NUM_SENSORS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!sensor_lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(sensor_lines[i], "ky032_sensor") < 0) {
            fprintf(stderr, "gpiod_line_request_input failed for pin %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Get and request LED line as output, initial value LOW */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "gpiod_chip_get_line failed for LED pin %d: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(led_line, "ky032_led", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed for LED pin %d: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Obstacle detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        bool object_detected = false;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(sensor_lines[i]);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_get_value failed for pin %u: %s\n",
                        sensor_pins[i], strerror(errno));
                goto cleanup;
            }
            /* KY-032 OUT is active-low: 0 means object detected */
            if (val == 0) {
                object_detected = true;
                break;
            }
        }

        if (gpiod_line_set_value(led_line, object_detected ? 1 : 0) < 0) {
            fprintf(stderr, "gpiod_line_set_value failed for LED pin %d: %s\n",
                    LED_PIN, strerror(errno));
            goto cleanup;
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure LED is turned off on exit */
    if (led_line)
        gpiod_line_set_value(led_line, 0);

    /* Release all lines */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensor_lines[i])
            gpiod_line_release(sensor_lines[i]);
    }
    if (led_line)
        gpiod_line_release(led_line);

    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");

    return ret;
}

