/*
 * Flame sensor monitor for Raspberry Pi 3 Model B+
 * 5 x Keyes KY-026 flame sensors on BCM GPIO 2, 3, 4, 17, 27
 *   (physical pins 3, 5, 7, 11, 13)
 * Digital output: LOW  = flame detected
 *                 HIGH = no flame
 * Logs rising-edge flame events to /var/log/flame_events.log
 *
 * Build: gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS      5
#define LOG_FILE         "/var/log/flame_events.log"
#define DEBOUNCE_MS      50
#define POLL_INTERVAL_S  1
#define TIMESTAMP_LEN    32
#define LINE_BUF_LEN     128

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Format current UTC time as ISO 8601 (YYYY-MM-DDTHH:MM:SSZ).
 * Returns 0 on success, -1 on failure.
 */
static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_utc;

    if (time(&rawtime) == (time_t)-1) {
        syslog(LOG_ERR, "time() failed: %s", strerror(errno));
        return -1;
    }
    if (gmtime_r(&rawtime, &tm_utc) == NULL) {
        syslog(LOG_ERR, "gmtime_r() failed");
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime() failed");
        return -1;
    }
    return 0;
}

/*
 * Append a flame event line to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_flame_event(unsigned int pin)
{
    char ts[TIMESTAMP_LEN];
    char line[LINE_BUF_LEN];
    FILE *fp;
    int fd;

    if (get_iso8601_timestamp(ts, sizeof(ts)) != 0)
        return -1;

    snprintf(line, sizeof(line),
             "%s - Sensor ID: %u (GPIO %u) - Flame Detected\n",
             ts, pin, pin);

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "fopen(%s): %s", LOG_FILE, strerror(errno));
        return -1;
    }

    fd = fileno(fp);
    if (fd < 0) {
        syslog(LOG_ERR, "fileno() failed: %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (flock(fd, LOCK_EX) == -1) {
        syslog(LOG_WARNING, "flock(LOCK_EX) failed: %s", strerror(errno));
        /* non-fatal: continue without locking */
    }

    if (fprintf(fp, "%s", line) < 0) {
        syslog(LOG_ERR, "fprintf() failed: %s", strerror(errno));
        flock(fd, LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        syslog(LOG_ERR, "fflush() failed: %s", strerror(errno));
        flock(fd, LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (flock(fd, LOCK_UN) == -1) {
        syslog(LOG_WARNING, "flock(LOCK_UN) failed: %s", strerror(errno));
    }

    if (fclose(fp) != 0) {
        syslog(LOG_ERR, "fclose() failed: %s", strerror(errno));
        return -1;
    }

    return 0;
}

/*
 * Read a single GPIO line.
 * Returns 0 or 1 on success, -1 on error.
 */
static int read_line(struct gpiod_line *line)
{
    int val = gpiod_line_get_value(line);
    if (val < 0)
        syslog(LOG_ERR, "gpiod_line_get_value() failed: %s", strerror(errno));
    return val;
}

/*
 * Debounce: read the line DEBOUNCE_MS apart and confirm both reads agree.
 * Returns 0 or 1 on success, -1 on error.
 */
static int debounce_read(struct gpiod_line *line)
{
    int v1 = read_line(line);
    if (v1 < 0)
        return -1;

    usleep(DEBOUNCE_MS * 1000);

    int v2 = read_line(line);
    if (v2 < 0)
        return -1;

    return (v1 == v2) ? v1 : -1;  /* -1 = unstable */
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int prev_state[NUM_SENSORS];
    int ret = EXIT_FAILURE;

    /* Initialize line pointers to NULL for safe cleanup */
    for (int i = 0; i < NUM_SENSORS; i++)
        lines[i] = NULL;

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open syslog ---- */
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(\"gpiochip0\"): %s",
               strerror(errno));
        goto cleanup;
    }

    /* ---- Acquire and request each line ---- */
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        /* Seed previous state */
        int v = read_line(lines[i]);
        prev_state[i] = (v < 0) ? 1 : v;  /* assume no-flame on read error */
    }

    syslog(LOG_INFO, "Flame monitor started (%d sensors on GPIO %u, %u, %u, %u, %u)",
           NUM_SENSORS, sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    /* ---- Main polling loop ---- */
    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = debounce_read(lines[i]);
            if (val < 0) {
                /* Read error or unstable debounce — log and continue */
                syslog(LOG_ERR, "Sensor %u (GPIO %u) read error",
                       sensor_pins[i], sensor_pins[i]);
                continue;
            }

            /* Rising edge: no-flame (1) -> flame (0) */
            if (val == 0 && prev_state[i] == 1) {
                if (log_flame_event(sensor_pins[i]) == 0) {
                    syslog(LOG_INFO, "Flame detected on sensor %u (GPIO %u)",
                           sensor_pins[i], sensor_pins[i]);
                } else {
                    syslog(LOG_ERR, "Failed to log event for sensor %u (GPIO %u)",
                           sensor_pins[i], sensor_pins[i]);
                }
            }
            prev_state[i] = val;
        }
        sleep(POLL_INTERVAL_S);
    }

    syslog(LOG_INFO, "Flame monitor shutting down");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release all requested lines */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
    closelog();
    return ret;
}

