    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open syslog ---- */
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(\"gpiochip0\"): %s",
               strerror(errno));
        goto cleanup;
    }

    /* ---- Acquire and request each line ---- */
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        /* Seed previous state */
        int v = read_line(lines[i]);
        prev_state[i] = (v < 0) ? 1 : v;  /* assume no-flame on read error */
    }

    syslog(LOG_INFO, "Flame monitor started (%d sensors on GPIO %u, %u, %u, %u, %u)",
           NUM_SENSORS, sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    /* ---- Main polling loop ---- */
    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = debounce_read(lines[i]);
            if (val < 0) {
                /* Read error or unstable debounce — log and continue */
                syslog(LOG_ERR, "Sensor %u (GPIO %u) read error",
                       sensor_pins[i], sensor_pins[i]);
                continue;
            }

            /* Rising edge: no-flame (1) -> flame (0) */
            if (val == 0 && prev_state[i] == 1) {
                if (log_flame_event(sensor_pins[i]) == 0) {
                    syslog(LOG_INFO, "Flame detected on sensor %u (GPIO %u)",
                           sensor_pins[i], sensor_pins[i]);
                } else {
                    syslog(LOG_ERR, "Failed to log event for sensor %u (GPIO %u)",
                           sensor_pins[i], sensor_pins[i]);
                }
            }
            prev_state[i] = val;
        }
        sleep(POLL_INTERVAL_S);
    }

    syslog(LOG_INFO, "Flame monitor shutting down");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release all requested lines */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
    closelog();
    return ret;
}

