#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_SENSORS 8
#define POLL_INTERVAL_MS 50

/* BCM GPIO pin numbers for TTP226 OUT0-OUT7 */
static const unsigned int sensor_pins[NUM_SENSORS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", &timeinfo);
        printf("[%s] ", buffer);
    } else {
        printf("[unknown-time] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    struct gpiod_line_bulk bulk;
    int prev_states[NUM_SENSORS];
    int ret;
    int i;

    /* Initialize line pointers to NULL for safe cleanup */
    for (i = 0; i < NUM_SENSORS; i++)
        lines[i] = NULL;

    /* Initialize previous states to -1 (unknown) */
    for (i = 0; i < NUM_SENSORS; i++)
        prev_states[i] = -1;

    /* Register signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open gpiochip0: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Resolve each line individually and add to bulk for bulk request */
    for (i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error: Failed to get GPIO line %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    gpiod_line_bulk_init(&bulk);
    for (i = 0; i < NUM_SENSORS; i++)
        gpiod_line_bulk_add(&bulk, lines[i]);

    /* Request all lines as inputs */
    ret = gpiod_line_request_bulk_input(&bulk, "ttp226-touch");
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to request GPIO lines as input: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("TTP226 touch sensor monitoring started.\n");
    printf("Pins: BCM %u, %u, %u, %u, %u, %u, %u, %u\n",
           sensor_pins[0], sensor_pins[1], sensor_pins[2], sensor_pins[3],
           sensor_pins[4], sensor_pins[5], sensor_pins[6], sensor_pins[7]);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main polling loop */
    while (program_running) {
        int values[NUM_SENSORS];
        int read_failed = 0;

        ret = gpiod_line_get_value_bulk(&bulk, values);
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to read GPIO values: %s\n",
                    strerror(errno));
            read_failed = 1;
        }

        if (!read_failed) {
            for (i = 0; i < NUM_SENSORS; i++) {
                if (values[i] != prev_states[i]) {
                    print_timestamp();
                    printf("Sensor %d (BCM %u): %s\n",
                           i, sensor_pins[i],
                           values[i] ? "TOUCHED" : "RELEASED");
                    fflush(stdout);
                    prev_states[i] = values[i];
                }
            }
        }

        /* Sleep for POLL_INTERVAL_MS, checking program_running every 10 ms */
        for (i = 0; i < POLL_INTERVAL_MS && program_running; i += 10)
            usleep(10000);
    }

    printf("\nExiting gracefully...\n");

cleanup:
    /* Release lines and close chip on all exit paths */
    for (i = 0; i < NUM_SENSORS; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    return (read_failed) ? EXIT_FAILURE : EXIT_SUCCESS;
}

