#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VEML7700_ADDR        0x10
#define VEML7700_REG_CONFIG  0x00
#define VEML7700_REG_ALS     0x04

#define LED_GPIO             18
#define PWM_FREQ             1000
#define PWM_RANGE            100

#define LUX_THRESHOLD_1      100
#define LUX_THRESHOLD_2      500
#define LUX_THRESHOLD_3      1000

#define SAMPLE_INTERVAL_US   1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int veml7700_write_config(int handle, uint16_t config) {
    char buf[2];
    buf[0] = (char)(config & 0xFF);
    buf[1] = (char)((config >> 8) & 0xFF);
    if (i2cWriteI2CBlockData(handle, VEML7700_REG_CONFIG, buf, 2) < 0) {
        return -1;
    }
    return 0;
}

static int veml7700_read_als(int handle, uint16_t *als) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, VEML7700_REG_ALS, buf, 2) < 0) {
        return -1;
    }
    *als = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

static int set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    if (gpioPWM(LED_GPIO, brightness) < 0) {
        return -1;
    }
    return 0;
}

static int log_data(FILE *fp, float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%d,%d\n", timestamp, lux, brightness, error_code) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", VEML7700_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t config = 0x0000;
    if (veml7700_write_config(i2c_handle, config) < 0) {
        fprintf(stderr, "Failed to configure VEML7700\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Adaptive Grow Light System started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t raw_als = 0;
        int error_code = 0;

        if (veml7700_read_als(i2c_handle, &raw_als) < 0) {
            error_code = -1;
            fprintf(stderr, "Error reading ALS data\n");
        } else {
            float lux = (float)raw_als * 0.0576f;
            int brightness = 0;

            if (lux < LUX_THRESHOLD_1) {
                brightness = PWM_RANGE;
            } else if (lux < LUX_THRESHOLD_2) {
                brightness = PWM_RANGE * 3 / 4;
            } else if (lux < LUX_THRESHOLD_3) {
                brightness = PWM_RANGE * 2 / 4;
            } else {
                brightness = PWM_RANGE / 4;
            }

            if (set_led_brightness(brightness) < 0) {
                fprintf(stderr, "Error setting LED brightness\n");
            }

            if (log_data(log_file, lux, brightness, error_code) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        if (error_code != 0) {
            if (log_data(log_file, 0.0f, 0, error_code) < 0) {
                fprintf(stderr, "Error logging error data\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    set_led_brightness(0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

