#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define NUM_CHANNELS 8
#define LED_GPIO 17
#define POLL_DELAY_US 50000  /* 50 ms */
#define DEBOUNCE_DELAY_US 200000  /* 200 ms */

static const int touch_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_touch_event(int channel) {
    FILE *fp = fopen("touch_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening touch_log.txt: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Channel %d Touched\n", timestamp, channel) < 0) {
        fprintf(stderr, "Error writing to touch_log.txt: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing touch_log.txt: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(touch_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", touch_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(touch_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down on GPIO %d\n", touch_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize LED state on GPIO %d\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int prev_state[NUM_CHANNELS];
    int curr_state[NUM_CHANNELS];
    int debounce_count[NUM_CHANNELS];

    for (int i = 0; i < NUM_CHANNELS; i++) {
        prev_state[i] = gpioRead(touch_pins[i]);
        curr_state[i] = prev_state[i];
        debounce_count[i] = 0;
    }

    int led_on = 0;

    while (program_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            curr_state[i] = gpioRead(touch_pins[i]);

            if (curr_state[i] != prev_state[i]) {
                debounce_count[i]++;
                if (debounce_count[i] >= 5) {
                    if (curr_state[i] == 1) {
                        if (log_touch_event(i + 1) != 0) {
                            fprintf(stderr, "Failed to log touch event for channel %d\n", i + 1);
                        }
                    }
                    prev_state[i] = curr_state[i];
                    debounce_count[i] = 0;
                }
            } else {
                debounce_count[i] = 0;
            }
        }

        int any_touched = 0;
        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (curr_state[i] == 1) {
                any_touched = 1;
                break;
            }
        }

        if (any_touched && !led_on) {
            if (gpioWrite(LED_GPIO, 1) != 0) {
                fprintf(stderr, "Failed to turn on LED\n");
            } else {
                led_on = 1;
            }
        } else if (!any_touched && led_on) {
            if (gpioWrite(LED_GPIO, 0) != 0) {
                fprintf(stderr, "Failed to turn off LED\n");
            } else {
                led_on = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

