#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define OPT3001_ADDR        0x44
#define REG_RESULT          0x00
#define REG_CONFIG          0x01
#define CONFIG_WORD         0xC810  /* RN=1100 (auto-range), CT=10 (100ms), M=1000, OVF=0, CR=11 (continuous) */
#define I2C_BUS             1
#define LOG_FILE            "light_data.txt"
#define SAMPLE_INTERVAL_US  1000000  /* 1 second */
#define CONV_TIME_US        100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* pigpio i2cReadWordData/i2cWriteWordData send/receive little-endian;
 * OPT3001 expects/reports big-endian (MSB first).  Swap bytes. */
static uint16_t swap16(uint16_t v)
{
    return (uint16_t)((v >> 8) | (v << 8));
}

static int opt3001_write_config(int handle, uint16_t config)
{
    int rc = i2cWriteWordData(handle, REG_CONFIG, swap16(config));
    if (rc < 0) {
        fprintf(stderr, "Error writing config register 0x%02X: pigpio error %d\n",
                REG_CONFIG, rc);
        return -1;
    }
    return 0;
}

static int opt3001_read_result(int handle, uint16_t *result)
{
    int rc = i2cReadWordData(handle, REG_RESULT);
    if (rc < 0) {
        fprintf(stderr, "Error reading result register 0x%02X: pigpio error %d\n",
                REG_RESULT, rc);
        return -1;
    }
    *result = swap16((uint16_t)rc);
    return 0;
}

static float opt3001_raw_to_lux(uint16_t raw)
{
    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    return (float)mantissa * 0.01f * (float)(1u << exponent);
}

static int log_data(float lux)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: pigpio error %d\n",
                I2C_BUS, OPT3001_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (opt3001_write_config(g_i2c_handle, CONFIG_WORD) != 0) {
        fprintf(stderr, "Failed to configure OPT3001\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow first conversion to complete before reading */
    gpioDelay(CONV_TIME_US);

    while (g_running) {
        uint16_t raw;
        if (opt3001_read_result(g_i2c_handle, &raw) != 0) {
            fprintf(stderr, "Sensor read error; skipping sample\n");
        } else {
            float lux = opt3001_raw_to_lux(raw);
            if (log_data(lux) != 0) {
                fprintf(stderr, "Logging error; continuing\n");
            }
            printf("Lux: %.2f\n", lux);
            fflush(stdout);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

