#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x08
#define LOG_FILE       "cooling_log.csv"
#define SAMPLE_US      1000000  /* 1 second */
#define MEASURE_DELAY  2000     /* 2 ms after start command */
#define FLOW_MIN       0.0f
#define FLOW_MAX       100.0f
#define RAW_TO_ML_MIN  90.0f

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Sensirion CRC-8: polynomial 0x31, init 0xFF */
static uint8_t sensirion_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int start_measurement(void) {
    uint8_t cmd[2] = {0x36, 0x08};
    int rc = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error sending start command: %d\n", rc);
        return -1;
    }
    gpioDelay(MEASURE_DELAY);
    return 0;
}

/*
 * Reads 3 bytes: 2 big-endian data bytes + 1 CRC byte.
 * Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.
 */
static int read_flow_rate(float *flow_rate, uint8_t *flags) {
    uint8_t buf[3];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (rc != 3) {
        fprintf(stderr, "I2C read returned %d (expected 3)\n", rc);
        return -1;
    }
    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n",
                sensirion_crc8(buf, 2), buf[2]);
        return -2;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flags = (uint8_t)(raw & 0x0003);
    *flow_rate = (float)raw / RAW_TO_ML_MIN;
    return 0;
}

static void log_data(float flow_rate, uint8_t flags, const char *status) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s,%.2f,%s\n", ts, flow_rate, status);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (start_measurement() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Coolant flow monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float flow_rate = 0.0f;
        uint8_t flags = 0;
        int rc = read_flow_rate(&flow_rate, &flags);

        if (rc == 0) {
            if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
                log_data(flow_rate, flags, "INVALID");
                printf("Invalid flow rate: %.2f ml/min (flags=0x%02X)\n",
                       flow_rate, flags);
            } else {
                log_data(flow_rate, flags, "OK");
                printf("Flow rate: %.2f ml/min (flags=0x%02X)\n",
                       flow_rate, flags);
            }
        } else if (rc == -2) {
            log_data(0.0f, flags, "ERROR");
            fprintf(stderr, "CRC error on flow reading\n");
        } else {
            log_data(0.0f, flags, "ERROR");
            fprintf(stderr, "I2C read error\n");
            if (init_i2c() != 0) {
                fprintf(stderr, "Re-initialization failed, exiting\n");
                break;
            }
            if (start_measurement() != 0) {
                fprintf(stderr, "Failed to restart measurement\n");
                break;
            }
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

