    middle_line = gpiod_chip_get_line(chip, MIDDLE_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    if (left_line == NULL || middle_line == NULL || right_line == NULL) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(left_line, "ky033-left") < 0) {
        fprintf(stderr, "Failed to request left line as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(middle_line, "ky033-middle") < 0) {
        fprintf(stderr, "Failed to request middle line as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(right_line, "ky033-right") < 0) {
        fprintf(stderr, "Failed to request right line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        goto cleanup;
    }

    while (program_running) {
        int left_val = gpiod_line_get_value(left_line);
        int middle_val = gpiod_line_get_value(middle_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || middle_val < 0 || right_val < 0) {
            fprintf(stderr, "Failed to read sensor values: %s\n", strerror(errno));
            break;
        }

        if (log_data(log_file, left_val, middle_val, right_val) != 0) {
            fprintf(stderr, "Failed to log data\n");
            break;
        }

        struct timespec ts;
        ts.tv_sec = POLL_INTERVAL_MS / 1000;
        ts.tv_nsec = (POLL_INTERVAL_MS % 1000) * 1000000L;
        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (left_line != NULL) {
        gpiod_line_release(left_line);
    }
    if (middle_line != NULL) {
        gpiod_line_release(middle_line);
    }
    if (right_line != NULL) {
        gpiod_line_release(right_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

