#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_OFFSET 4
#define LOG_FILE "flame_events.txt"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", timeinfo);
}

static void log_event(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    fprintf(fp, "%s: Flame detected\n", timestamp);
    fclose(fp);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line_event event;
    char timestamp[32];
    int ret;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_falling_edge_events(line, "flame_sensor");
    if (ret < 0) {
        perror("Failed to request falling edge events on GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    while (program_running) {
        ret = gpiod_line_event_wait(line, &(struct timespec){0, POLL_TIMEOUT_MS * 1000000L});
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("Error waiting for GPIO event");
            break;
        }
        if (ret == 0) {
            continue;
        }

        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("Error reading GPIO event");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            get_timestamp(timestamp, sizeof(timestamp));
            printf("Flame detected at: %s\n", timestamp);
            log_event(timestamp);
        }
    }

    printf("\nCleaning up and exiting...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

