        fprintf(stderr, "Failed to get touch line %d: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        fprintf(stderr, "Failed to get LED line %d: %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_rising_edge_events(touch_line, "ttp223-touch") < 0) {
        fprintf(stderr, "Failed to request rising edge events on touch line: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "ttp223-led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        struct timespec ts;
        ts.tv_sec = POLL_TIMEOUT_MS / 1000;
        ts.tv_nsec = (POLL_TIMEOUT_MS % 1000) * 1000000L;

        int event_ret = gpiod_line_event_wait(touch_line, &ts);
        if (event_ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n", strerror(errno));
            goto cleanup;
        }

        if (event_ret == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(touch_line, &event) < 0) {
            fprintf(stderr, "gpiod_line_event_read failed: %s\n", strerror(errno));
            continue;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            led_state = !led_state;
            if (gpiod_line_set_value(led_line, led_state) < 0) {
                fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
                goto cleanup;
            }

            if (log_touch_event(log_file, led_state) < 0) {
                fprintf(stderr, "Failed to log touch event\n");
            }

            printf("Touch detected! LED is now %s\n", led_state ? "ON" : "OFF");
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line != NULL) {
        gpiod_line_release(led_line);
    }
    if (touch_line != NULL) {
        gpiod_line_release(touch_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    if (ret == EXIT_SUCCESS) {
        printf("Exiting gracefully.\n");
    }

    return ret;
}

