#define BUZZER_PIN        18   /* GPIO18, physical pin 12 */
#define LOG_FILE          "alert_log.txt"
#define POLL_INTERVAL_MS  500
#define BUZZER_DURATION_MS 2000
#define CHIP_NAME         "gpiochip0"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(FILE *log, const char *message)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log, "[%s] %s\n", ts, message) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }
    if (fflush(log) != 0) {
        fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Buzzer control                                                      */
/* ------------------------------------------------------------------ */
static int buzzer_on(struct gpiod_line *line)
{
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set buzzer HIGH: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int buzzer_off(struct gpiod_line *line)
{
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set buzzer LOW: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    FILE *log = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                CHIP_NAME, strerror(errno));
        goto cleanup_log;
    }

    /* ---- Get lines ---- */
    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (flame_line == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                FLAME_SENSOR_PIN, strerror(errno));
        goto cleanup_chip;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (buzzer_line == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                BUZZER_PIN, strerror(errno));
        goto cleanup_chip;
    }

    /* ---- Request lines ---- */
    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        fprintf(stderr, "request_input(flame) failed: %s\n", strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "request_output(buzzer) failed: %s\n", strerror(errno));
        goto cleanup_flame;
    }

    /* ---- Log startup ---- */
    log_event(log, "System started");

    /* ---- Main loop (500 ms poll interval, 100 ms slices) ---- */
    int prev_flame = gpiod_line_get_value(flame_line);
    if (prev_flame < 0) {
        fprintf(stderr, "Initial flame sensor read failed: %s\n", strerror(errno));
        goto cleanup_buzzer;
    }

    while (g_running) {
        int cur_flame = gpiod_line_get_value(flame_line);
        if (cur_flame < 0) {
            fprintf(stderr, "flame sensor read failed: %s\n", strerror(errno));
            break;
        }

        /* High-to-low transition => flame detected */
        if (prev_flame == 1 && cur_flame == 0) {
            log_event(log, "Flame detected!");

            if (buzzer_on(buzzer_line) < 0) {
                break;
            }

            /* Keep buzzer on for 2 s (100 ms slices) */
            for (int ms = 0; ms < BUZZER_DURATION_MS && g_running; ms += 100) {
                usleep(100000);
            }

            if (buzzer_off(buzzer_line) < 0) {
                break;
            }
        }

        prev_flame = cur_flame;

        /* 500 ms poll interval (100 ms slices) */
        for (int ms = 0; ms < POLL_INTERVAL_MS && g_running; ms += 100) {
            usleep(100000);
        }
    }

    /* ---- Graceful shutdown ---- */
    log_event(log, "System stopped");
    ret = EXIT_SUCCESS;

cleanup_buzzer:
    buzzer_off(buzzer_line);
    gpiod_line_release(buzzer_line);

cleanup_flame:
    gpiod_line_release(flame_line);

cleanup_chip:
    gpiod_chip_close(chip);

cleanup_log:
    if (fclose(log) != 0) {
        fprintf(stderr, "fclose(log) failed: %s\n", strerror(errno));
    }

    return ret;
}

