#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TOUCH_SENSOR_PIN 4
#define LED_PIN 17
#define LOG_FILE "touch_log.txt"
#define POLL_DELAY_US 10000   /* 10 ms */
#define DEBOUNCE_US  200000   /* 200 ms */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int log_touch_event(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s: Touch detected\n", timestamp) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int led_state = 0;
    int last_touch_state = 0;
    uint32_t last_event_tick = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise LED state on GPIO%d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n",
                strerror(errno));
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Failed to read GPIO%d\n", TOUCH_SENSOR_PIN);
            break;
        }

        /* Detect rising edge: LOW -> HIGH */
        if (touch_state == 1 && last_touch_state == 0) {
            uint32_t now = gpioTick();
            if (now - last_event_tick >= DEBOUNCE_US) {
                led_state = !led_state;
                if (gpioWrite(LED_PIN, led_state) != 0) {
                    fprintf(stderr, "Failed to write to GPIO%d\n", LED_PIN);
                }

                if (log_touch_event() != 0) {
                    fprintf(stderr, "Logging failed; continuing.\n");
                }

                last_event_tick = now;
            }
        }

        last_touch_state = touch_state;
        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    gpioWrite(LED_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();

    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

