                    fprintf(stderr, "Failed to write to GPIO%d\n", LED_PIN);
                }

                if (log_touch_event() != 0) {
                    fprintf(stderr, "Logging failed; continuing.\n");
                }

                last_event_tick = now;
            }
        }

        last_touch_state = touch_state;
        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    gpioWrite(LED_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();

    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

