/*
 * TMAG5110A1 Hall-effect latch sensor monitor for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   Sensor 1 OUT -> GPIO4  (BCM)
 *   Sensor 2 OUT -> GPIO17 (BCM)
 *   Sensor 3 OUT -> GPIO27 (BCM)
 *   VCC -> 3.3 V, GND -> GND
 *
 * The TMAG5110A1 open-drain output is active-low:
 *   LOW  (0) = south pole present  -> magnet detected
 *   HIGH (1) = north pole present  -> magnet removed
 *
 * Build:  gcc -Wall -Wextra -O2 -o magnet_monitor magnet_monitor.c -lpigpio -lrt
 * Run:    sudo ./magnet_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27
#define LOG_FILE     "magnet_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging helpers                                                     */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_pin, int state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    const char *state_str = (state == 0) ? "MAGNET_DETECTED" : "MAGNET_REMOVED";

    if (g_log_fp) {
        fprintf(g_log_fp, "%s - Sensor %d: %s\n", ts, sensor_pin, state_str);
        fflush(g_log_fp);
    }
    printf("%s - Sensor %d: %s\n", ts, sensor_pin, state_str);
}

static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32] = "UNKNOWN";
    if (t) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    }
    fprintf(stderr, "%s - ERROR: %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_sensor(int pin)
{
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", pin);
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d) failed\n", pin);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    /* ---- initialize sensors ---- */
    int pins[] = {SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (init_sensor(pins[i]) != 0) {
            log_error("Sensor initialization failed");
            fclose(g_log_fp);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Monitoring TMAG5110A1 sensors on GPIO4, GPIO17, GPIO27. "
           "Press Ctrl+C to exit.\n");

    /* ---- initial state ---- */
    int prev_states[3];
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        int v = gpioRead(pins[i]);
        if (v < 0) {
            log_error("gpioRead failed for initial state");
            prev_states[i] = -1;
        } else {
            prev_states[i] = v;
        }
    }

    /* ---- main polling loop ---- */
    while (g_running) {
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
            int v = gpioRead(pins[i]);
            if (v < 0) {
                log_error("gpioRead failed");
                continue;
            }

            if (v != prev_states[i]) {
                log_event(pins[i], v);
                prev_states[i] = v;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    /* ---- cleanup ---- */
    printf("\nShutting down...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

