#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x4A

#define REG_PART_ID 0x00
#define REG_HW_REV 0x01
#define REG_LED_CURRENT 0x3F
#define REG_AVG 0x04
#define REG_ENABLE 0x01
#define REG_HR_DATA 0x2A

#define EXPECTED_PART_ID 0x02
#define EXPECTED_HW_REV 0x01
#define MOVING_AVG_SIZE 5
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n", reg, val, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int init_sensor(void) {
    uint8_t part_id, hw_rev;

    if (read_reg(REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor absent or bus error\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    if (read_reg(REG_HW_REV, &hw_rev) < 0) {
        fprintf(stderr, "Cannot read HW_REV\n");
        return -1;
    }
    if (hw_rev != EXPECTED_HW_REV) {
        fprintf(stderr, "Unexpected HW_REV: 0x%02X (expected 0x%02X)\n", hw_rev, EXPECTED_HW_REV);
        return -1;
    }

    if (write_reg(REG_LED_CURRENT, 0x3F) < 0) return -1;
    if (write_reg(REG_AVG, 0x04) < 0) return -1;
    if (write_reg(REG_ENABLE, 0x01) < 0) return -1;

    return 0;
}

static int read_heart_rate(uint16_t *raw) {
    int rc = i2cReadWordData(i2c_handle, REG_HR_DATA);
    if (rc < 0) {
        fprintf(stderr, "I2C read HR failed: rc=%d\n", rc);
        return -1;
    }
    *raw = (uint16_t)(rc & 0xFFFF);
    return 0;
}

static float moving_average(float new_value, float *buffer, int *index, int size) {
    buffer[*index] = new_value;
    *index = (*index + 1) % size;
    float sum = 0.0f;
    for (int i = 0; i < size; i++) sum += buffer[i];
    return sum / size;
}

static void log_data(float bpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file);
}

int main(void) {
    float hr_buffer[MOVING_AVG_SIZE] = {0.0f};
    int hr_index = 0;
    int consecutive_errors = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, SI1182_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open heart_rate.csv\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    printf("Heart rate monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t raw_hr;
        if (read_heart_rate(&raw_hr) == 0) {
            consecutive_errors = 0;
            float bpm = (float)raw_hr * 0.5f;
            float filtered = moving_average(bpm, hr_buffer, &hr_index, MOVING_AVG_SIZE);
            if (filtered >= 30.0f && filtered <= 220.0f) {
                log_data(filtered);
            } else {
                fprintf(stderr, "Out-of-range BPM: %.2f\n", filtered);
            }
        } else {
            consecutive_errors++;
            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, aborting\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Heart rate monitoring stopped.\n");
    return 0;
}

