/*
 * touch_counter.c — 8-channel TTP226 capacitive touch sensor counter
 *
 * Board:  Raspberry Pi Zero W
 * Library: libgpiod v2+ (bulk/config API)
 *
 * Wiring
 *   TTP226 OUT1..OUT8  ->  GPIO5, 6, 7, 8, 9, 10, 11, 12  (BCM)
 *   Counter bit0..bit7 ->  GPIO17..GPIO24 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define LOG_FILE     "touch_log.txt"
#define POLL_MS      10
#define STABILIZE_MS 200

static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int counter_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signals(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        if (!g_running)
            break;
    }
}

static void log_touch(int channel, int counter)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        perror("gmtime_r");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s, Channel: %d, Counter: %d\n", ts, channel, counter);
        fclose(fp);
    } else {
        fprintf(stderr, "Warning: cannot open %s: %s\n", LOG_FILE, strerror(errno));
    }

    printf("Touch on channel %d | Counter: %d\n", channel, counter);
    fflush(stdout);
}

static int set_counter_outputs(struct gpiod_line_request *req, int value)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int bit = (value >> i) & 1;
        if (gpiod_line_request_set_value(req, counter_pins[i], bit) < 0) {
            fprintf(stderr, "set_value failed on GPIO %u: %s\n",
                    counter_pins[i], strerror(errno));
            return -1;
        }
    }
    return 0;
}

static void reset_outputs(struct gpiod_line_request *req)
{
    for (int i = 0; i < NUM_CHANNELS; i++)
        (void)gpiod_line_request_set_value(req, counter_pins[i], 0);
}

int main(void)
{
    install_signals();

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line_config *line_cfg = gpiod_line_config_new();
    if (!line_cfg) {
        fprintf(stderr, "gpiod_line_config_new failed\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line_settings *settings = gpiod_line_settings_new();
    if (!settings) {
        fprintf(stderr, "gpiod_line_settings_new failed\n");
        gpiod_line_config_free(line_cfg);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_DOWN);

    if (gpiod_line_config_add_line_settings(line_cfg, sensor_pins,
            NUM_CHANNELS, settings) < 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings (sensor): %s\n",
                strerror(errno));
        gpiod_line_settings_free(settings);
        gpiod_line_config_free(line_cfg);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_settings_set_output_value(settings, GPIOD_LINE_VALUE_INACTIVE);

    if (gpiod_line_config_add_line_settings(line_cfg, counter_pins,
            NUM_CHANNELS, settings) < 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings (counter): %s\n",
                strerror(errno));
        gpiod_line_settings_free(settings);
        gpiod_line_config_free(line_cfg);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line_settings_free(settings);

    struct gpiod_request_config *req_cfg = gpiod_request_config_new();
    if (!req_cfg) {
        fprintf(stderr, "gpiod_request_config_new failed\n");
        gpiod_line_config_free(line_cfg);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    gpiod_request_config_set_consumer(req_cfg, "ttp226-counter");

    struct gpiod_line_request *req = gpiod_chip_request_lines(chip, req_cfg,
            line_cfg);
    gpiod_request_config_free(req_cfg);
    gpiod_line_config_free(line_cfg);

    if (!req) {
        fprintf(stderr, "gpiod_chip_request_lines failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    sleep_ms(STABILIZE_MS);

    int counter = 0;
    int prev[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++)
        prev[i] = 0;

    printf("Touch sensor counter started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int v = gpiod_line_request_get_value(req, sensor_pins[i]);
            if (v < 0) {
                fprintf(stderr, "get_value failed on GPIO %u: %s\n",
                        sensor_pins[i], strerror(errno));
                continue;
            }

            if (v == 1 && prev[i] == 0) {
                counter = (counter + 1) & 0xFF;
                if (set_counter_outputs(req, counter) < 0)
                    ;
                log_touch(i + 1, counter);
            }
            prev[i] = v;
        }
        sleep_ms(POLL_MS);
    }

    printf("\nShutting down...\n");
    reset_outputs(req);
    gpiod_line_request_release(req);
    gpiod_chip_close(chip);
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

