#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

#define MIC_GPIO 4
#define LED_GPIO 17
#define SAMPLE_PERIOD_US 125   /* 8 kHz sampling */
#define LED_ON_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    struct timeval tv;
    struct tm tm_info;
    char buf[32];

    if (gettimeofday(&tv, NULL) != 0) {
        perror("gettimeofday");
        return;
    }
    localtime_r(&tv.tv_sec, &tm_info);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("%s.%03ld", buf, (long)(tv.tv_usec / 1000));
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", MIC_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sampling ICS-40180 on GPIO%d, LED on GPIO%d. Press Ctrl+C to exit.\n",
           MIC_GPIO, LED_GPIO);
    fflush(stdout);

    while (program_running) {
        int level = gpioRead(MIC_GPIO);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", MIC_GPIO);
            break;
        }

        if (level == 1) {
            print_timestamp();
            printf("  Peak detected\n");
            fflush(stdout);

            if (gpioWrite(LED_GPIO, 1) != 0) {
                fprintf(stderr, "Error: failed to turn LED ON on GPIO%d.\n", LED_GPIO);
                break;
            }

            /*
             * gpioDelay is a busy-wait; use a loop to allow prompt
             * signal delivery even if the LED-on delay is long.
             */
            int remaining = LED_ON_MS;
            while (remaining > 0 && program_running) {
                int chunk = (remaining > 10) ? 10 : remaining;
                gpioDelay(chunk * 1000);
                remaining -= chunk;
            }

            if (gpioWrite(LED_GPIO, 0) != 0) {
                fprintf(stderr, "Error: failed to turn LED OFF on GPIO%d.\n", LED_GPIO);
                break;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

