#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define FADE_DURATION_SEC 5
#define FADE_STEPS        50
#define PWM_FREQ_HZ       1000
#define PWM_RANGE         255

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read a 32-bit random value from /dev/urandom; returns 0 on success, -1 on error. */
static int read_random_u32(uint32_t *out)
{
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "open(/dev/urandom): %s", strerror(errno));
        return -1;
    }

    uint32_t val = 0;
    ssize_t n = read(fd, &val, sizeof(val));
    if (n != (ssize_t)sizeof(val)) {
        syslog(LOG_ERR, "read(/dev/urandom): expected %zu bytes, got %zd (%s)",
               sizeof(val), n, n < 0 ? strerror(errno) : "short read");
        close(fd);
        return -1;
    }

    close(fd);
    *out = val;
    return 0;
}

/* Convert HSV (h in [0,360), s/v in [0,1]) to RGB (each in [0,255]). */
static void hsv_to_rgb(float h, float s, float v, int *r, int *g, int *b)
{
    if (s <= 0.0f) {
        int gray = (int)(v * 255.0f + 0.5f);
        if (gray < 0) gray = 0;
        if (gray > 255) gray = 255;
        *r = *g = *b = gray;
        return;
    }

    h = fmodf(h, 360.0f);
    if (h < 0.0f) h += 360.0f;

    float hh = h / 60.0f;
    int i = (int)hh;
    float ff = hh - (float)i;
    float p = v * (1.0f - s);
    float q = v * (1.0f - s * ff);
    float t = v * (1.0f - s * (1.0f - ff));

    float rf, gf, bf;
    switch (i) {
        case 0: rf = v; gf = t; bf = p; break;
        case 1: rf = q; gf = v; bf = p; break;
        case 2: rf = p; gf = v; bf = t; break;
        case 3: rf = p; gf = q; bf = v; break;
        case 4: rf = t; gf = p; bf = v; break;
        default: rf = v; gf = p; bf = q; break;
    }

    *r = (int)(rf * 255.0f + 0.5f);
    *g = (int)(gf * 255.0f + 0.5f);
    *b = (int)(bf * 255.0f + 0.5f);

    if (*r < 0) *r = 0; if (*r > 255) *r = 255;
    if (*g < 0) *g = 0; if (*g > 255) *g = 255;
    if (*b < 0) *b = 0; if (*b > 255) *b = 255;
}

/* Common-anode LED: invert duty cycle so 0 = full brightness, 255 = off. */
static int common_anode_duty(int color)
{
    return 255 - color;
}

static int set_led_color(int r, int g, int b)
{
    int rd = common_anode_duty(r);
    int gd = common_anode_duty(g);
    int bd = common_anode_duty(b);

    if (gpioPWM(RED_PIN,   rd) < 0) { syslog(LOG_ERR, "gpioPWM(RED): %s", pigpio_error(rd));   return -1; }
    if (gpioPWM(GREEN_PIN, gd) < 0) { syslog(LOG_ERR, "gpioPWM(GREEN): %s", pigpio_error(gd)); return -1; }
    if (gpioPWM(BLUE_PIN,  bd) < 0) { syslog(LOG_ERR, "gpioPWM(BLUE): %s", pigpio_error(bd));  return -1; }
    return 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise() failed");
        return -1;
    }

    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0) { syslog(LOG_ERR, "gpioSetMode(RED): %s", pigpio_error(RED_PIN));   return -1; }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) { syslog(LOG_ERR, "gpioSetMode(GREEN): %s", pigpio_error(GREEN_PIN)); return -1; }
    if (gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) { syslog(LOG_ERR, "gpioSetMode(BLUE): %s", pigpio_error(BLUE_PIN));  return -1; }

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ_HZ) < 0) { syslog(LOG_ERR, "gpioSetPWMfrequency(RED): %s", pigpio_error(RED_PIN));   return -1; }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ_HZ) < 0) { syslog(LOG_ERR, "gpioSetPWMfrequency(GREEN): %s", piggpio_error(GREEN_PIN)); return -1; }
    if (gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ_HZ) < 0) { syslog(LOG_ERR, "gpioSetPWMfrequency(BLUE): %s", pigpio_error(BLUE_PIN));  return -1; }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) < 0) { syslog(LOG_ERR, "gpioSetPWMrange(RED): %s", pigpio_error(RED_PIN));   return -1; }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) { syslog(LOG_ERR, "gpioSetPWMrange(GREEN): %s", pigpio_error(GREEN_PIN)); return -1; }
    if (gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) < 0) { syslog(LOG_ERR, "gpioSetPWMrange(BLUE): %s", pigpio_error(BLUE_PIN));  return -1; }

    /* Start with LED off (common-anode: full duty = off) */
    if (set_led_color(0, 0, 0) < 0) return -1;

    return 0;
}

static void cleanup_gpio(void)
{
    /* Turn off LED before releasing pigpio */
    gpioPWM(RED_PIN,   0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN,  0);
    gpioTerminate();
}

int main(void)
{
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Mood lamp started (R=%d G=%d B=%d @ %d Hz)",
           RED_PIN, GREEN_PIN, BLUE_PIN, PWM_FREQ_HZ);

    uint32_t hue1 = 0, hue2 = 0;
    if (read_random_u32(&hue1) < 0) {
        syslog(LOG_ERR, "Failed to seed initial hues; using 0");
        hue1 = 0;
    }
    hue2 = hue1;

    while (g_running) {
        if (read_random_u32(&hue2) < 0) {
            syslog(LOG_ERR, "Failed to read new hue; retrying next cycle");
            sleep(FADE_DURATION_SEC);
            continue;
        }

        int r1, g1, b1, r2, g2, b2;
        hsv_to_rgb((float)(hue1 % 360), 1.0f, 1.0f, &r1, &g1, &b1);
        hsv_to_rgb((float)(hue2 % 360), 1.0f, 1.0f, &r2, &g2, &b2);

        float dr = (float)(r2 - r1) / (float)FADE_STEPS;
        float dg = (float)(g2 - g1) / (float)FADE_STEPS;
        float db = (float)(b2 - b1) / (float)FADE_STEPS;

        float cr = (float)r1, cg = (float)g1, cb = (float)b1;
        int steps = FADE_STEPS;

        for (int i = 0; i <= steps && g_running; i++) {
            if (set_led_color((int)cr, (int)cg, (int)cb) < 0) {
