#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29

#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_ID      0x12
#define TCS34725_CDATAL  0x14
#define TCS34725_RDATAL  0x16
#define TCS34725_GDATAL  0x18
#define TCS34725_BDATAL  0x1A
#define TCS34725_CONTROL 0x8F

#define ENABLE_PON  0x01
#define ENABLE_AEN  0x02

#define RED_THRESHOLD   200
#define POLL_DELAY_MS   200

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16_le write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16_le read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id = 0;
    if (i2c_read_reg8(fd, TCS34725_ID, &id) < 0) return -1;
    if (id != 0x44) {
        fprintf(stderr, "TCS34725 not found (ID=0x%02X, expected 0x44)\n", id);
        return -1;
    }
    if (i2c_write_reg8(fd, TCS34725_ENABLE, ENABLE_PON) < 0) return -1;
    usleep(3000);
    if (i2c_write_reg8(fd, TCS34725_ATIME, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_CONTROL, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_ENABLE, ENABLE_PON | ENABLE_AEN) < 0) return -1;
    usleep(3000);
    return 0;
}

static int tcs34725_read(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    if (i2c_read_reg16_le(fd, TCS34725_CDATAL, c) < 0) return -1;
    if (i2c_read_reg16_le(fd, TCS34725_RDATAL, r) < 0) return -1;
    if (i2c_read_reg16_le(fd, TCS34725_GDATAL, g) < 0) return -1;
    if (i2c_read_reg16_le(fd, TCS34725_BDATAL, b) < 0) return -1;
    return 0;
}

static void calibrate(uint16_t r, uint16_t g, uint16_t b, uint16_t c,
                      int16_t *cr, int16_t *cg, int16_t *cb, int16_t *cc) {
    *cr = (int16_t)r - 100;
    *cg = (int16_t)g - 100;
    *cb = (int16_t)b - 100;
    *cc = (int16_t)c - 100;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                TCS34725_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        i2c_write_reg8(fd, TCS34725_ENABLE, 0x00);
        close(fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, 17);
    if (!led) {
        fprintf(stderr, "gpiod_chip_get_line(17) failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        i2c_write_reg8(fd, TCS34725_ENABLE, 0x00);
        close(fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led, "tcs34725_led", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        i2c_write_reg8(fd, TCS34725_ENABLE, 0x00);
        close(fd);
        return EXIT_FAILURE;
    }

    int rc = EXIT_SUCCESS;

    while (g_running) {
        uint16_t r, g, b, c;
        if (tcs34725_read(fd, &r, &g, &b, &c) < 0) {
            fprintf(stderr, "Read failed; re-initializing sensor...\n");
            i2c_write_reg8(fd, TCS34725_ENABLE, 0x00);
            usleep(10000);
            if (tcs34725_init(fd) < 0) {
                fprintf(stderr, "Re-init failed; retrying next cycle\n");
            }
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        int16_t cr, cg, cb, cc;
        calibrate(r, g, b, c, &cr, &cg, &cb, &cc);

        printf("R: %5d  G: %5d  B: %5d  C: %5d\n", cr, cg, cb, cc);

        int led_state = (cr > RED_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(led, led_state) < 0) {
            fprintf(stderr, "gpiod_line_set_value failed: %s\n", strerror(errno));
        }

        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    i2c_write_reg8(fd, TCS34725_ENABLE, 0x00);
    close(fd);
    return rc;
}

