#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define LED_GPIO 18
#define NUM_LEDS 10
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define BH1750_MEASUREMENT_DELAY_US 180000
#define I2C_BUS 1
#define MAX_LUX 1000.0f
#define PWM_RANGE 255
#define PWM_FREQ 800000
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_led_brightness(uint8_t brightness) {
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    gpioPWM(LED_GPIO, brightness);
}

static void generate_ws2812b_data(uint8_t *data, int num_leds) {
    for (int i = 0; i < num_leds; i++) {
        data[i * 3 + 0] = 0xE0 | (data[i * 3 + 0] >> 3);
        data[i * 3 + 1] = 0xE0 | (data[i * 3 + 1] >> 3);
        data[i * 3 + 2] = 0xE0 | (data[i * 3 + 2] >> 3);
    }
}

static void send_ws2812b_data(uint8_t *data, int num_leds) {
    int total_bits = num_leds * 24;
    int *wave = (int *)malloc(total_bits * sizeof(int));
    if (!wave) {
        fprintf(stderr, "Memory allocation failed for wave buffer\n");
        return;
    }

    int idx = 0;
    for (int i = 0; i < num_leds; i++) {
        for (int j = 0; j < 24; j++) {
            int bit = (data[i * 3 + (j / 8)] >> (7 - (j % 8))) & 1;
            if (bit) {
                wave[idx++] = 1;
                wave[idx++] = 0;
            } else {
                wave[idx++] = 0;
                wave[idx++] = 1;
            }
        }
    }

    gpioWaveClear();
    gpioWaveAddGeneric(total_bits, wave);
    int wave_id = gpioWaveCreate();
    if (wave_id >= 0) {
        gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT);
        while (gpioWaveTxBusy()) {
            gpioDelay(100);
        }
        gpioWaveDelete(wave_id);
    } else {
        fprintf(stderr, "Failed to create wave\n");
    }
    free(wave);
}

static int read_bh1750_lux(float *lux_out) {
    if (i2c_handle < 0) return -1;

    if (i2cWriteByte(i2c_handle, BH1750_CONT_HIGH_RES) < 0) {
        fprintf(stderr, "Error writing to BH1750\n");
        return -1;
    }

    gpioDelay(BH1750_MEASUREMENT_DELAY_US);

    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from BH1750\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static uint8_t map_lux_to_brightness(float lux) {
    if (lux < 0.0f) lux = 0.0f;
    if (lux > MAX_LUX) lux = MAX_LUX;

    float normalized = lux / MAX_LUX;
    float log_val = log10f(normalized + 1.0f);
    float mapped = log_val * (PWM_RANGE / log10f(2.0f));
    if (mapped < 0.0f) mapped = 0.0f;
    if (mapped > PWM_RANGE) mapped = PWM_RANGE;
    return (uint8_t)mapped;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint8_t led_data[NUM_LEDS * 3];
    for (int i = 0; i < NUM_LEDS * 3; i++) led_data[i] = 0;

    while (running) {
        float lux = 0.0f;
        int retries = 3;
        int success = 0;

        while (retries > 0 && running) {
            if (read_bh1750_lux(&lux) == 0) {
                success = 1;
                break;
            }
            retries--;
            gpioDelay(100000);
        }

        if (!success) {
            fprintf(stderr, "Failed to read lux after retries. Setting brightness to 0.\n");
            set_led_brightness(0);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        uint8_t brightness = map_lux_to_brightness(lux);
        for (int i = 0; i < NUM_LEDS; i++) {
            led_data[i * 3 + 0] = brightness;
            led_data[i * 3 + 1] = brightness;
            led_data[i * 3 + 2] = brightness;
        }

        generate_ws2812b_data(led_data, NUM_LEDS);
        send_ws2812b_data(led_data, NUM_LEDS);

        gpioDelay(LOOP_DELAY_US);
    }

    for (int i = 0; i < NUM_LEDS * 3; i++) led_data[i] = 0;
    generate_ws2812b_data(led_data, NUM_LEDS);
    send_ws2812b_data(led_data, NUM_LEDS);

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

