#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR             0x23
#define BH1750_CMD_OT_HRES      0x20
#define BH1750_CONV_TIME_MS     120

#define SPI_DEVICE              "/dev/spidev0.0"
#define SPI_SPEED_HZ            1000000
#define SPI_BITS_PER_WORD       8

#define NUM_LEDS                10
#define MIN_LUX                 10.0f
#define MAX_LUX                 300.0f
#define MAX_BRIGHTNESS          31

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_CMD_OT_HRES) < 0) {
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) {
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int spi_transfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int apa102_send_frame(int fd, uint8_t brightness) {
    uint8_t start[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t end[4]   = {0xFF, 0xFF, 0xFF, 0xFF};

    uint8_t led_frame[4];
    led_frame[0] = 0xE0 | (brightness & 0x1F);
    led_frame[1] = 0x00;
    led_frame[2] = 0x00;
    led_frame[3] = 0x00;

    uint8_t rx[4];

    if (spi_transfer(fd, start, rx, 4) < 0) return -1;
    for (int i = 0; i < NUM_LEDS; i++) {
        if (spi_transfer(fd, led_frame, rx, 4) < 0) return -1;
    }
    if (spi_transfer(fd, end, rx, 4) < 0) return -1;

    return 0;
}

static int map_lux_to_brightness(float lux) {
    if (lux < MIN_LUX) lux = MIN_LUX;
    if (lux > MAX_LUX) lux = MAX_LUX;
    float norm = (lux - MIN_LUX) / (MAX_LUX - MIN_LUX);
    return (int)(norm * MAX_BRIGHTNESS);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (bh1750_init(g_i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed (sensor absent or bus error).\n");
        close(g_i2c_fd);
        return 1;
    }

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED_HZ;

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Starting light-responsive APA102 control. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (bh1750_init(g_i2c_fd) < 0) {
            fprintf(stderr, "BH1750 re-init failed; retrying...\n");
            usleep(1000000);
            continue;
        }

        usleep(BH1750_CONV_TIME_MS * 1000);

        float lux;
        if (bh1750_read_lux(g_i2c_fd, &lux) < 0) {
            fprintf(stderr, "Failed to read lux; retrying...\n");
            usleep(1000000);
            continue;
        }

        int brightness = map_lux_to_brightness(lux);
        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        if (apa102_send_frame(g_spi_fd, (uint8_t)brightness) < 0) {
            fprintf(stderr, "Failed to send APA102 frame; retrying...\n");
            usleep(1000000);
            continue;
        }

        usleep(100000);
    }

cleanup:
    printf("\nShutting down...\n");
    if (g_spi_fd >= 0) {
        apa102_send_frame(g_spi_fd, 0);
        close(g_spi_fd);
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    return 0;
}

