    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (bh1750_init(g_i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed (sensor absent or bus error).\n");
        close(g_i2c_fd);
        return 1;
    }

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED_HZ;

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Starting light-responsive APA102 control. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (bh1750_init(g_i2c_fd) < 0) {
            fprintf(stderr, "BH1750 re-init failed; retrying...\n");
            usleep(1000000);
            continue;
        }

        usleep(BH1750_CONV_TIME_MS * 1000);

        float lux;
        if (bh1750_read_lux(g_i2c_fd, &lux) < 0) {
            fprintf(stderr, "Failed to read lux; retrying...\n");
            usleep(1000000);
            continue;
        }

        int brightness = map_lux_to_brightness(lux);
        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        if (apa102_send_frame(g_spi_fd, (uint8_t)brightness) < 0) {
            fprintf(stderr, "Failed to send APA102 frame; retrying...\n");
            usleep(1000000);
            continue;
        }

        usleep(100000);
    }

cleanup:
    printf("\nShutting down...\n");
    if (g_spi_fd >= 0) {
        apa102_send_frame(g_spi_fd, 0);
        close(g_spi_fd);
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    return 0;
}

