#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_SENSORS 2
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define FADE_DURATION_MS 500
#define FADE_STEPS 50
#define LOOP_DELAY_MS 100
#define BH1750_CONV_TIME_MS 180
#define NUM_LEDS 10

static const int i2c_addresses[NUM_SENSORS] = {0x23, 0x5C};
static int i2c_handles[NUM_SENSORS];
static int spi_handle;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c_sensors(void) {
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = i2cOpen(1, i2c_addresses[i], 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Warning: I2C sensor at 0x%02X not found (handle=%d)\n",
                    i2c_addresses[i], i2c_handles[i]);
            i2c_handles[i] = -1;
        } else {
            if (i2cWriteByte(i2c_handles[i], 0x21) < 0) {
                fprintf(stderr, "Warning: Failed to set BH1750 mode for 0x%02X\n",
                        i2c_addresses[i]);
                i2cClose(i2c_handles[i]);
                i2c_handles[i] = -1;
            }
        }
    }
    return 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialization failed (handle=%d)\n", spi_handle);
        return -1;
    }
    return 0;
}

static int read_bh1750(int handle) {
    if (handle < 0) return -1;
    char buf[2];
    int bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Warning: I2C read error (handle=%d, bytes=%d)\n", handle, bytes);
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

static float calculate_average_lux(void) {
    float sum = 0.0f;
    int count = 0;
    for (int i = 0; i < NUM_SENSORS; i++) {
        int lux = read_bh1750(i2c_handles[i]);
        if (lux >= 0) {
            sum += (float)lux;
            count++;
        }
    }
    return (count > 0) ? (sum / count) : -1.0f;
}

static int map_lux_to_brightness(float lux) {
    if (lux < 0.0f) return 0;
    if (lux < 10.0f) return 31;
    if (lux < 50.0f) return 24;
    if (lux < 100.0f) return 16;
    if (lux < 200.0f) return 8;
    return 0;
}

static void send_apa102_data(const uint8_t *data, int len) {
    if (spiWrite(spi_handle, (char *)data, len) < 0) {
        fprintf(stderr, "Error: SPI write failed\n");
    }
}

static void set_led_brightness(uint8_t brightness) {
    uint8_t start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t end_frame[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    uint8_t led_data[NUM_LEDS * 4];

    for (int i = 0; i < NUM_LEDS; i++) {
        led_data[i * 4 + 0] = 0xE0 | (brightness & 0x1F);
        led_data[i * 4 + 1] = 0x00;
        led_data[i * 4 + 2] = 0x00;
        led_data[i * 4 + 3] = 0xFF;
    }

    uint8_t frame[4 + NUM_LEDS * 4 + 4];
    int idx = 0;
    for (int i = 0; i < 4; i++) frame[idx++] = start_frame[i];
    for (int i = 0; i < NUM_LEDS * 4; i++) frame[idx++] = led_data[i];
    for (int i = 0; i < 4; i++) frame[idx++] = end_frame[i];

    send_apa102_data(frame, idx);
}

static void fade_brightness(int target_brightness) {
    static int current_brightness = 0;
    if (target_brightness == current_brightness) return;

    int step_size = (target_brightness - current_brightness) / FADE_STEPS;
    if (step_size == 0) step_size = (target_brightness > current_brightness) ? 1 : -1;

    for (int i = 0; i < FADE_STEPS; i++) {
        current_brightness += step_size;
        if ((step_size > 0 && current_brightness > target_brightness) ||
            (step_size < 0 && current_brightness < target_brightness)) {
            current_brightness = target_brightness;
        }
        set_led_brightness((uint8_t)current_brightness);
        gpioDelay(FADE_DURATION_MS * 1000 / FADE_STEPS);
    }
}

static void cleanup(void) {
    set_led_brightness(0);
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) i2cClose(i2c_handles[i]);
    }
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    if (init_i2c_sensors() != 0) {
        fprintf(stderr, "Error: I2C sensor initialization failed\n");
        gpioTerminate();
        return 1;
    }

    if (init_spi() != 0) {
        fprintf(stderr, "Error: SPI initialization failed\n");
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] >= 0) i2cClose(i2c_handles[i]);
        }
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Ambient light-based APA102 brightness control started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] >= 0) {
                if (i2cWriteByte(i2c_handles[i], 0x21) < 0) {
                    fprintf(stderr, "Warning: Failed to reset BH1750 mode for 0x%02X\n",
                            i2c_addresses[i]);
                }
            }
        }
        gpioDelay(BH1750_CONV_TIME_MS * 1000);

        float avg_lux = calculate_average_lux();
        int target = map_lux_to_brightness(avg_lux);
        fade_brightness(target);

        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

