#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <math.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_ALS_REG 0x04
#define WS2812B_GPIO 18
#define NUM_LEDS 10
#define MAX_LUX 120000.0
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200
#define BIT_BANG_FREQ_HZ 800000
#define BIT_BANG_T0_NS 1
#define BIT_BANG_T1_NS 1
#define GAMMA 2.2

// Global variables for cleanup
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static int i2c_fd = -1;
static volatile sig_atomic_t keep_running = 1;

// Function prototypes
int init_i2c(void);
int init_veml7700(void);
int read_veml7700(uint16_t *als_raw);
float calculate_lux(uint16_t als_raw);
int map_lux_to_brightness(float lux);
void set_led_brightness(int brightness);
void cleanup(void);
void signal_handler(int sig);

// Initialize I2C bus
int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

// Initialize VEML7700 sensor
int init_veml7700(void) {
    uint8_t config[3];
    // Configuration register 0x00: 0x0000 = 100ms integration time, gain 1/8
    config[0] = VEML7700_CONFIG_REG;
    config[1] = 0x00;
    config[2] = 0x00;
    if (write(i2c_fd, config, 3) != 3) {
        fprintf(stderr, "Failed to write VEML7700 config: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000); // Wait for sensor to stabilize
    return 0;
}

// Read ALS data from VEML7700
int read_veml7700(uint16_t *als_raw) {
    uint8_t reg = VEML7700_ALS_REG;
    uint8_t data[2];
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to write ALS register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(i2c_fd, data, 2) != 2) {
        fprintf(stderr, "Failed to read ALS data: %s\n", strerror(errno));
        return -1;
    }
    *als_raw = (data[1] << 8) | data[0];
    return 0;
}

// Calculate lux from raw ALS value
float calculate_lux(uint16_t als_raw) {
    // For gain 1/8, integration time 100ms: lux = raw * 0.0288
    return (float)als_raw * 0.0288f;
}

// Map lux to brightness with gamma correction
int map_lux_to_brightness(float lux) {
    if (lux < 0) lux = 0;
    if (lux > MAX_LUX) lux = MAX_LUX;
    float normalized = lux / MAX_LUX;
    float gamma_corrected = powf(normalized, 1.0f / GAMMA);
    int brightness = (int)(gamma_corrected * 255.0f);
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;
    return brightness;
}

// Set LED strip brightness using bit-banging via libgpiod
void set_led_brightness(int brightness) {
    // For simplicity, use threshold: if brightness > 128, turn on all LEDs; else off
    // Full bit-banging requires precise timing; this is a simplified fallback
    if (brightness > 128) {
        gpiod_line_set_value(line, 1);
        usleep(100000); // 100ms on
        gpiod_line_set_value(line, 0);
        usleep(100000); // 100ms off
    } else {
        gpiod_line_set_value(line, 0);
        usleep(200000); // 200ms off
    }
}

// Cleanup resources
void cleanup(void) {
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

// Signal handler
void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    // Initialize GPIO
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }
    line = gpiod_chip_get_line(chip, WS2812B_GPIO);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", WS2812B_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line, "ws2812b", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    // Initialize VEML7700
    if (init_veml7700() < 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("VEML7700 and WS2812B control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        uint16_t als_raw = 0;
        int retries = 0;
        int success = 0;

        // Retry loop for I2C read
        while (retries < I2C_RETRIES && !success) {
            if (read_veml7700(&als_raw) == 0) {
                success = 1;
            } else {
                retries++;
                if (retries < I2C_RETRIES) {
                    fprintf(stderr, "I2C read failed, retrying (%d/%d)...\n", retries, I2C_RETRIES);
                    usleep(I2C_RETRY_DELAY_MS * 1000);
                }
            }
        }

        if (!success) {
            fprintf(stderr, "I2C read failed after %d retries. Skipping this iteration.\n", I2C_RETRIES);
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }

        float lux = calculate_lux(als_raw);
        int brightness = map_lux_to_brightness(lux);

        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        set_led_brightness(brightness);

        usleep(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

