#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18
#define CONSUMER "flame_sensor"

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static struct gpiod_line *led_line = NULL;

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

static void cleanup(void) {
    if (flame_line) { gpiod_line_release(flame_line); flame_line = NULL; }
    if (buzzer_line) { gpiod_line_release(buzzer_line); buzzer_line = NULL; }
    if (led_line) { gpiod_line_release(led_line); led_line = NULL; }
    if (chip) { gpiod_chip_close(chip); chip = NULL; }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_output(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static int read_input(struct gpiod_line *line) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        perror("gpiod_line_get_value");
    }
    return val;
}

static int self_test(void) {
    log_event("Starting self-test...");

    if (set_output(led_line, 0) < 0) return -1;
    if (set_output(buzzer_line, 0) < 0) return -1;

    for (int i = 0; i < 2; i++) {
        if (set_output(led_line, 1) < 0) return -1;
        usleep(500000);
        if (set_output(led_line, 0) < 0) return -1;
        usleep(500000);
    }

    int flame_count = 0;
    for (int i = 0; i < 5; i++) {
        int val = read_input(flame_line);
        if (val < 0) {
            log_event("Error reading flame sensor during self-test");
            return -1;
        }
        if (val == 0) flame_count++;
        usleep(100000);
    }

    if (flame_count == 5) {
        log_event("Self-test failed: flame sensor consistently detected flame");
        for (int i = 0; i < 5; i++) {
            if (set_output(led_line, 1) < 0) return -1;
            usleep(100000);
            if (set_output(led_line, 0) < 0) return -1;
            usleep(100000);
        }
        for (int rep = 0; rep < 3; rep++) {
            if (set_output(buzzer_line, 1) < 0) return -1;
            usleep(200000);
            if (set_output(buzzer_line, 0) < 0) return -1;
            usleep(200000);
            if (set_output(buzzer_line, 1) < 0) return -1;
            usleep(600000);
            if (set_output(buzzer_line, 0) < 0) return -1;
            usleep(200000);
        }
        return -1;
    }

    log_event("Self-test passed");
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!flame_line || !buzzer_line || !led_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(flame_line, CONSUMER) < 0) {
        perror("gpiod_line_request_input (flame)");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(buzzer_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (buzzer)");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(led_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (led)");
        cleanup();
        return 1;
    }

    if (self_test() < 0) {
        log_event("Exiting due to self-test failure");
        cleanup();
        return 1;
    }

    log_event("Flame sensor monitoring started");

    int flame_active = 0;
    while (running) {
        int val = read_input(flame_line);
        if (val < 0) {
            log_event("Error reading flame sensor");
            usleep(500000);
            continue;
        }

        if (val == 0 && !flame_active) {
            log_event("Flame detected!");
            if (set_output(buzzer_line, 1) < 0 || set_output(led_line, 1) < 0) {
                log_event("Error activating buzzer/LED");
            }
            flame_active = 1;
        } else if (val == 1 && flame_active) {
            log_event("Flame gone");
            if (set_output(buzzer_line, 0) < 0 || set_output(led_line, 0) < 0) {
                log_event("Error deactivating buzzer/LED");
            }
            flame_active = 0;
        }

        usleep(50000);
    }

    log_event("Shutting down...");
    set_output(buzzer_line, 0);
    set_output(led_line, 0);
    cleanup();
    return 0;
}

