#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>

#define DATA_PIN  17
#define CLOCK_PIN 18
#define LATCH_PIN 27
#define CHIP_NAME "gpiochip0"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *data_line = NULL;
static struct gpiod_line *clock_line = NULL;
static struct gpiod_line *latch_line = NULL;
static volatile int keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

void release_resources(void) {
    if (data_line)  gpiod_line_release(data_line);
    if (clock_line) gpiod_line_release(clock_line);
    if (latch_line) gpiod_line_release(latch_line);
    if (chip)       gpiod_chip_close(chip);
}

int shift_out(unsigned char data) {
    for (int i = 7; i >= 0; i--) {
        int bit = (data >> i) & 0x01;
        if (gpiod_line_set_value(data_line, bit) < 0) {
            fprintf(stderr, "Error setting data line\n");
            return -1;
        }
        if (gpiod_line_set_value(clock_line, 1) < 0) {
            fprintf(stderr, "Error setting clock high\n");
            return -1;
        }
        usleep(1);
        if (gpiod_line_set_value(clock_line, 0) < 0) {
            fprintf(stderr, "Error setting clock low\n");
            return -1;
        }
        usleep(1);
    }
    if (gpiod_line_set_value(latch_line, 1) < 0) {
        fprintf(stderr, "Error setting latch high\n");
        return -1;
    }
    usleep(1);
    if (gpiod_line_set_value(latch_line, 0) < 0) {
        fprintf(stderr, "Error setting latch low\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);
    if (!data_line || !clock_line || !latch_line) {
        perror("gpiod_chip_get_line");
        release_resources();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(data_line, "74hc595_data", 0) < 0 ||
        gpiod_line_request_output(clock_line, "74hc595_clock", 0) < 0 ||
        gpiod_line_request_output(latch_line, "74hc595_latch", 0) < 0) {
        perror("gpiod_line_request_output");
        release_resources();
        return EXIT_FAILURE;
    }

    // Digit '5' pattern: a,b,d,f,g (Q0,Q1,Q3,Q5,Q6)
    unsigned char digit_5 = 0b01101100;

    while (keep_running) {
        if (shift_out(digit_5) < 0) {
            fprintf(stderr, "Shift out failed\n");
            break;
        }
        usleep(500000);
        if (!keep_running) break;
        if (shift_out(0x00) < 0) {
            fprintf(stderr, "Shift out failed\n");
            break;
        }
        usleep(500000);
    }

    release_resources();
    return EXIT_SUCCESS;
}

