#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN 17
#define BUTTON_PIN 18
#define CHIP_NAME "gpiochip0"
#define BLINK_INTERVAL_MS 1000

static volatile sig_atomic_t keep_running = 1;

static void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    struct gpiod_line_event event;
    int ret;

    /* Set up signal handler for graceful termination */
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get LED line */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request LED line as output, initially low */
    ret = gpiod_line_request_output(led_line, "blink_led", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (LED)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get button line */
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line (button)");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request button line as input with pull-up and falling-edge events */
    ret = gpiod_line_request_falling_edge_events_flags(button_line, "button_event",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("gpiod_line_request_falling_edge_events_flags");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Blinking LED on GPIO%d, monitoring button on GPIO%d. Press button to exit.\n",
           LED_PIN, BUTTON_PIN);

    while (keep_running) {
        /* Turn LED on */
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (on)");
            break;
        }
        usleep(BLINK_INTERVAL_MS * 1000);

        /* Check for button press with 1-second timeout */
        ret = gpiod_line_event_wait(button_line, &(struct timespec){1, 0});
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret > 0) {
            /* Event detected, read it to clear */
            ret = gpiod_line_event_read(button_line, &event);
            if (ret < 0) {
                perror("gpiod_line_event_read");
                break;
            }
            printf("Button pressed! Exiting.\n");
            break;
        }

        /* Turn LED off */
        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (off)");
            break;
        }
        usleep(BLINK_INTERVAL_MS * 1000);

        /* Check for button press again */
        ret = gpiod_line_event_wait(button_line, &(struct timespec){1, 0});
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret > 0) {
            ret = gpiod_line_event_read(button_line, &event);
            if (ret < 0) {
                perror("gpiod_line_event_read");
                break;
            }
            printf("Button pressed! Exiting.\n");
            break;
        }
    }

    /* Cleanup: turn off LED, release lines, close chip */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

