#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

#define PWM_PERIOD_NS 10000000L  /* 10 ms = 100 Hz */
#define LOOP_DELAY_NS 10000000L  /* 10 ms between color changes */

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ns(long ns) {
    struct timespec ts;
    ts.tv_sec = ns / 1000000000L;
    ts.tv_nsec = ns % 1000000000L;
    clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);
}

static int set_pwm(struct gpiod_line *line, int duty_percent) {
    if (duty_percent < 0 || duty_percent > 100) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_percent);
        return -1;
    }
    long on_ns = (PWM_PERIOD_NS * duty_percent) / 100;
    long off_ns = PWM_PERIOD_NS - on_ns;
    int ret = gpiod_line_set_value(line, 1);
    if (ret < 0) return ret;
    if (on_ns > 0) sleep_ns(on_ns);
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) return ret;
    if (off_ns > 0) sleep_ns(off_ns);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL, *green_line = NULL, *blue_line = NULL;
    int ret = 1;

    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return 1;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(red_line, "rgb_led", 0) < 0) {
        perror("request_output red");
        goto cleanup;
    }
    if (gpiod_line_request_output(green_line, "rgb_led", 0) < 0) {
        perror("request_output green");
        goto cleanup;
    }
    if (gpiod_line_request_output(blue_line, "rgb_led", 0) < 0) {
        perror("request_output blue");
        goto cleanup;
    }

    printf("RGB LED control started. Press Ctrl+C to exit.\n");

    while (running) {
        int r = rand() % 101;
        int g = rand() % 101;
        int b = rand() % 101;

        if (set_pwm(red_line, r) < 0) {
            fprintf(stderr, "PWM error on red: %s\n", strerror(errno));
            goto cleanup;
        }
        if (set_pwm(green_line, g) < 0) {
            fprintf(stderr, "PWM error on green: %s\n", strerror(errno));
            goto cleanup;
        }
        if (set_pwm(blue_line, b) < 0) {
            fprintf(stderr, "PWM error on blue: %s\n", strerror(errno));
            goto cleanup;
        }

        sleep_ns(LOOP_DELAY_NS);
    }

    ret = 0;

cleanup:
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    printf("\nCleanup complete. Exiting.\n");
    return ret;
}

