    fprintf(fp, "%s, X: %.3f, Y: %.3f, Z: %.3f, Mag: %.3f\n", ts, x, y, z, mag);
    fclose(fp);
}

static void pulse_gpio(void) {
    gpioWrite(GPIO_PIN, 1);
    gpioDelay(PULSE_DURATION_US);
    gpioWrite(GPIO_PIN, 0);
}

int main(int argc, char *argv[]) {
    float threshold = 2.0f;
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Threshold must be positive\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_g]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_lsm303() < 0) {
        fprintf(stderr, "LSM303 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detection started. Threshold: %.2f G\n", threshold);

    while (!terminate) {
        float x, y, z;
        if (read_accel(&x, &y, &z) < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }
        float mag = calc_magnitude(x, y, z);
        if (mag > threshold) {
            printf("Impact detected! Mag: %.3f G\n", mag);
            pulse_gpio();
            log_impact(x, y, z, mag);
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(GPIO_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

