static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, pigpio_error(i2cWriteDevice(handle, buf, 2)));
        return -1;
    }
    return 0;
