        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, pigpio_error(i2cReadDevice(handle, (char *)value, 1)));
        return -1;
    }
    return 0;
}

static int read_als(int handle, uint16_t *als) {
