    if (read_register(handle, ALS_LSB_REG, &lsb) != 0) return -1;
    if (read_register(handle, ALS_MSB_REG, &msb) != 0) return -1;
    *als = ((uint16_t)msb << 8) | lsb;
    return 0;
}

static int read_color(int handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t r_lsb, r_msb, g_lsb, g_msb, b_lsb, b_msb;
    if (read_register(handle, RED_REG, &r_lsb) != 0) return -1;
    if (read_register(handle, RED_REG + 1, &r_msb) != 0) return -1;
    if (read_register(handle, GREEN_REG, &g_lsb) != 0) return -1;
    if (read_register(handle, GREEN_REG + 1, &g_msb) != 0) return -1;
    if (read_register(handle, BLUE_REG, &b_lsb) != 0) return -1;
    if (read_register(handle, BLUE_REG + 1, &b_msb) != 0) return -1;
