    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    if (write_register(i2c_handle, MODE_REG, 0x01) != 0) {
        fprintf(stderr, "Failed to set sensor to normal mode\n");
        cleanup();
        return 1;
    }

