    gpioSetPWMfrequency(LED_GPIO, 1000);
    gpioPWM(LED_GPIO, 0);

    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }
    fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    fflush(log_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t als, red, green, blue;

    while (!terminate) {
        if (read_als(i2c_handle, &als) == 0 && read_color(i2c_handle, &red, &green, &blue) == 0) {
            log_data(log_file, als, red, green, blue);
            adjust_led_brightness(als);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

