    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadByteData(reg=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte register; returns 0 on success, -1 on error     */
/* ------------------------------------------------------------------ */
static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data (X/Y/Z, 14-bit left-justified)    */
/* Returns 0 on success, -1 on error                                  */
/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, float *x, float *y, float *z)
{
    char buffer[6];
    int rc = i2cReadI2CBlockData(handle, FXOS8700_REG_OUT_X_MSB, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "Error: i2cReadI2CBlockData failed: %d\n", rc);
        return -1;
    }

    /* 14-bit left-justified: shift right by 2 to get 14-bit value */
    int16_t raw_x = (int16_t)(((uint16_t)buffer[0] << 8) | (uint8_t)buffer[1]) >> 2;
    int16_t raw_y = (int16_t)(((uint16_t)buffer[2] << 8) | (uint8_t)buffer[3]) >> 2;
    int16_t raw_z = (int16_t)(((uint16_t)buffer[4] << 8) | (uint8_t)buffer[5]) >> 2;

    /* Convert to m/s^2: counts -> g -> m/s^2 */
    *x = (float)raw_x / ACCEL_SENSITIVITY * GRAVITY_MPS2;
    *y = (float)raw_y / ACCEL_SENSITIVITY * GRAVITY_MPS2;
    *z = (float)raw_z / ACCEL_SENSITIVITY * GRAVITY_MPS2;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log an impact event to file                                         */
/* ------------------------------------------------------------------ */
static void log_impact(float x, float y, float z, float magnitude)
{
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening impact_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x1F */
    g_i2c_handle = i2cOpen(1, FXOS8700_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                FXOS8700_ADDRESS, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    uint8_t who_am_i = 0;
    if (read_register(g_i2c_handle, FXOS8700_REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error: cannot read WHO_AM_I register\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        cleanup();
        return EXIT_FAILURE;
    }
    printf("FXOS8700CQ detected (WHO_AM_I = 0x%02X)\n", who_am_i);

    /* Configure: ±2g range (XYZ_DATA_CFG = 0x00) */
    if (write_register(g_i2c_handle, FXOS8700_REG_XYZ_DATA_CFG, 0x00) != 0) {
        fprintf(stderr, "Error: failed to configure ±2g range\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Activate: active mode, 200 Hz ODR (CTRL_REG1 = 0x01) */
    if (write_register(g_i2c_handle, FXOS8700_REG_CTRL_REG1, 0x01) != 0) {
        fprintf(stderr, "Error: failed to activate sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle after activation */
    gpioDelay(10000); /* 10 ms */

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: sigaction(SIGINT) failed");
    }

    printf("Monitoring for impacts (threshold: %.2f m/s^2). Press Ctrl+C to exit.\n",
           IMPACT_THRESHOLD);

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (read_acceleration(g_i2c_handle, &x, &y, &z) != 0) {
            /* I2C read error: log and continue */
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float magnitude = sqrtf(x * x + y * y + z * z);

        if (magnitude > IMPACT_THRESHOLD) {
            log_impact(x, y, z, magnitude);
            printf("Impact detected! Magnitude: %.3f m/s^2 (x=%.3f, y=%.3f, z=%.3f)\n",
                   magnitude, x, y, z);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

