#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define GYRO_ADDR      0x69
#define WHO_AM_I_REG   0x0F
#define WHO_AM_I_VAL   0xD3
#define CTRL_REG1      0x20
#define CTRL_REG4      0x23
#define OUT_X_L        0x28
#define NUM_CAL_SAMPLES 100
#define THRESHOLD_DPS  50.0f
#define SENSITIVITY    0.00875f
#define LOG_FILE       "gyro_log.txt"
#define SAMPLE_PERIOD_US 50000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_gyro(int fd) {
    uint8_t who;
    if (i2c_read_reg8(fd, WHO_AM_I_REG, &who) < 0) return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, CTRL_REG1, 0x0F) < 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG4, 0x00) < 0) return -1;
    return 0;
}

static int read_gyro(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_L | 0x80, buf, 6) < 0) return -1;
    int16_t rx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t ry = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t rz = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)rx * SENSITIVITY;
    *y = (float)ry * SENSITIVITY;
    *z = (float)rz * SENSITIVITY;
    return 0;
}

static int calibrate_gyro(int fd, float *off_x, float *off_y, float *off_z) {
    float sx = 0, sy = 0, sz = 0;
    float x, y, z;
    for (int i = 0; i < NUM_CAL_SAMPLES; i++) {
        if (read_gyro(fd, &x, &y, &z) < 0) return -1;
        sx += x; sy += y; sz += z;
        usleep(10000);
    }
    *off_x = sx / NUM_CAL_SAMPLES;
    *off_y = sy / NUM_CAL_SAMPLES;
    *off_z = sz / NUM_CAL_SAMPLES;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fflush(fp);
}

static void check_threshold(float x, float y, float z) {
    if (x > THRESHOLD_DPS || y > THRESHOLD_DPS || z > THRESHOLD_DPS) {
        time_t t = time(NULL);
        struct tm tm;
        localtime_r(&t, &tm);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(stderr, "ALERT: Threshold exceeded at %s (X=%.2f, Y=%.2f, Z=%.2f)\n", ts, x, y, z);
        fprintf(g_log_fp, "%s,ALERT,Threshold exceeded,X=%.2f,Y=%.2f,Z=%.2f\n", ts, x, y, z);
        fflush(g_log_fp);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", GYRO_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    if (init_gyro(g_i2c_fd) < 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    float off_x = 0, off_y = 0, off_z = 0;
    if (calibrate_gyro(g_i2c_fd, &off_x, &off_y, &off_z) < 0) {
        fprintf(stderr, "Calibration failed\n");
        close(g_i2c_fd);
        return 1;
    }
    printf("Calibration complete: X=%.3f Y=%.3f Z=%.3f\n", off_x, off_y, off_z);

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    while (g_running) {
        float x, y, z;
        if (read_gyro(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        x -= off_x; y -= off_y; z -= off_z;
        log_data(g_log_fp, x, y, z);
        check_threshold(x, y, z);
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

