#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ACCEL_ADDR 0x19
#define MAG_ADDR 0x1E

#define CTRL_REG1_A 0x20
#define OUT_X_L_A 0x28
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03

#define ACCEL_SCALE 0.000061f
#define MAG_SCALE 0.00014f

static int accel_handle = -1;
static int mag_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_sensors(void) {
    accel_handle = i2cOpen(I2C_BUS, ACCEL_ADDR, 0);
    if (accel_handle < 0) {
        fprintf(stderr, "Error opening accelerometer I2C: %d\n", accel_handle);
        return -1;
    }
    if (i2cWriteByteData(accel_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing accelerometer CTRL_REG1_A\n");
        i2cClose(accel_handle); accel_handle = -1;
        return -1;
    }

    mag_handle = i2cOpen(I2C_BUS, MAG_ADDR, 0);
    if (mag_handle < 0) {
        fprintf(stderr, "Error opening magnetometer I2C: %d\n", mag_handle);
        i2cClose(accel_handle); accel_handle = -1;
        return -1;
    }
    if (i2cWriteByteData(mag_handle, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing magnetometer MR_REG_M\n");
        i2cClose(accel_handle); accel_handle = -1;
        i2cClose(mag_handle); mag_handle = -1;
        return -1;
    }
    return 0;
}

static int read_accel(float *ax, float *ay, float *az) {
    char buf[6];
    if (i2cReadI2CBlockData(accel_handle, OUT_X_L_A | 0x80, buf, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *ax = raw_x * ACCEL_SCALE;
    *ay = raw_y * ACCEL_SCALE;
    *az = raw_z * ACCEL_SCALE;
    return 0;
}

static int read_mag(float *mx, float *my, float *mz) {
    char buf[6];
    if (i2cReadI2CBlockData(mag_handle, OUT_X_H_M, buf, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_z = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_y = (int16_t)((buf[4] << 8) | buf[5]);
    *mx = raw_x * MAG_SCALE;
    *my = raw_y * MAG_SCALE;
    *mz = raw_z * MAG_SCALE;
    return 0;
}

static float calculate_heading(float ax, float ay, float az, float mx, float my, float mz) {
    float roll = atan2f(ay, az);
    float pitch = atan2f(-ax, sqrtf(ay * ay + az * az));
    float cos_roll = cosf(roll);
    float sin_roll = sinf(roll);
    float cos_pitch = cosf(pitch);
    float sin_pitch = sinf(pitch);
    float xh = mx * cos_pitch + mz * sin_pitch;
    float yh = mx * sin_roll * sin_pitch + my * cos_roll - mz * sin_roll * cos_pitch;
    float heading = atan2f(yh, xh) * 180.0f / M_PI;
    if (heading < 0) heading += 360.0f;
    return heading;
}

static void log_data(float heading, float ax, float ay, float az, float mx, float my, float mz) {
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,Heading_deg,Accel_X_g,Accel_Y_g,Accel_Z_g,Mag_X_g,Mag_Y_g,Mag_Z_g\n");
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n", ts, heading, ax, ay, az, mx, my, mz);
    fclose(fp);
}

static void cleanup(void) {
    if (accel_handle >= 0) {
        i2cClose(accel_handle);
        accel_handle = -1;
    }
    if (mag_handle >= 0) {
        i2cClose(mag_handle);
        mag_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_sensors() != 0) {
        cleanup();
        return 1;
    }

    while (running) {
        float ax, ay, az, mx, my, mz;
        if (read_accel(&ax, &ay, &az) == 0 && read_mag(&mx, &my, &mz) == 0) {
            float heading = calculate_heading(ax, ay, az, mx, my, mz);
            log_data(heading, ax, ay, az, mx, my, mz);
        }
        gpioDelay(100000);
    }

    cleanup();
    return 0;
}

