#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL6180X_ADDR 0x29
#define I2C_BUS 1
#define DISTANCE_THRESHOLD 100
#define LOG_FILE "distance_log.txt"
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg8(int handle, uint16_t reg, uint8_t value) {
    char buf[3] = { (char)(reg >> 8), (char)(reg & 0xFF), (char)value };
    return i2cWriteDevice(handle, buf, 3);
}

static int read_reg8(int handle, uint16_t reg, uint8_t *value) {
    char buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, (char *)value, 1) != 1) return -1;
    return 0;
}

static int init_vl6180x(int handle) {
    if (write_reg8(handle, 0x0207, 0x01) < 0) return -1;
    if (write_reg8(handle, 0x0208, 0x01) < 0) return -1;
    if (write_reg8(handle, 0x0096, 0x00) < 0) return -1;
    if (write_reg8(handle, 0x0097, 0xfd) < 0) return -1;
    if (write_reg8(handle, 0x00e3, 0x00) < 0) return -1;
    if (write_reg8(handle, 0x00e4, 0x04) < 0) return -1;
    if (write_reg8(handle, 0x00e5, 0x02) < 0) return -1;
    if (write_reg8(handle, 0x00e6, 0x01) < 0) return -1;
    if (write_reg8(handle, 0x00e7, 0x03) < 0) return -1;
    if (write_reg8(handle, 0x00f5, 0x02) < 0) return -1;
    if (write_reg8(handle, 0x00d9, 0x05) < 0) return -1;
    if (write_reg8(handle, 0x00db, 0xce) < 0) return -1;
    if (write_reg8(handle, 0x00dc, 0x03) < 0) return -1;
    if (write_reg8(handle, 0x00dd, 0xf8) < 0) return -1;
    if (write_reg8(handle, 0x009f, 0x00) < 0) return -1;
    if (write_reg8(handle, 0x00a3, 0x3c) < 0) return -1;
    if (write_reg8(handle, 0x00b7, 0x00) < 0) return -1;
    if (write_reg8(handle, 0x00bb, 0x3c) < 0) return -1;
    if (write_reg8(handle, 0x00b2, 0x09) < 0) return -1;
    if (write_reg8(handle, 0x00ca, 0x09) < 0) return -1;
    if (write_reg8(handle, 0x0198, 0x01) < 0) return -1;
    if (write_reg8(handle, 0x01b0, 0x17) < 0) return -1;
    if (write_reg8(handle, 0x01ad, 0x00) < 0) return -1;
    if (write_reg8(handle, 0x00ff, 0x05) < 0) return -1;
    if (write_reg8(handle, 0x0100, 0x05) < 0) return -1;
    if (write_reg8(handle, 0x0199, 0x05) < 0) return -1;
    if (write_reg8(handle, 0x01a6, 0x1b) < 0) return -1;
    if (write_reg8(handle, 0x01ac, 0x3e) < 0) return -1;
    if (write_reg8(handle, 0x01a7, 0x1f) < 0) return -1;
    if (write_reg8(handle, 0x0030, 0x00) < 0) return -1;
    return 0;
}

static int read_distance(int handle, int *distance) {
    uint8_t status = 0;
    if (read_reg8(handle, 0x04d, &status) < 0) return -1;
    if (status & 0x01) return 1;
    if (status & 0x02) return 2;
    if (status & 0x04) return 3;
    if (status & 0x08) return 4;
    if (status & 0x10) return 5;
    if (status & 0x20) return 6;
    if (status & 0x40) return 7;
    if (status & 0x80) return 8;

    uint8_t reg = 0x062;
    if (i2cWriteDevice(handle, (char *)&reg, 1) < 0) return -1;
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

static void log_data(const char *status) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
