#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

/* Sensor I2C addresses (7-bit) */
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

/* Register addresses */
#define CTRL_REG 0x00
#define DATA_REG 0x01

/* Control register value to enable continuous measurement */
#define CTRL_VAL 0x80

/* Sampling interval in microseconds (10 ms) */
#define SAMPLE_INTERVAL_US 10000

/* Global resources for signal handler cleanup */
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Initialize a single sensor: write control register to enable measurement */
static int init_sensor(int handle, int addr) {
    if (i2cWriteByteData(handle, CTRL_REG, CTRL_VAL) < 0) {
        fprintf(stderr, "Error: Failed to write control register 0x%02X on I2C 0x%02X: %s\n",
                CTRL_REG, addr, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit signed sample from the sensor's data register */
static int read_sensor_data(int handle, int addr) {
    int data = i2cReadWordData(handle, DATA_REG);
    if (data < 0) {
        fprintf(stderr, "Error: Failed to read data register 0x%02X on I2C 0x%02X: %s\n",
                DATA_REG, addr, strerror(errno));
        return -1;
    }
    /* pigpio returns data as (high_byte << 8) | low_byte; convert to signed 16-bit */
    int16_t signed_data = (int16_t)data;
    return (int)signed_data;
}

/* Log a sample row to the CSV file */
static void log_data(FILE *fp, struct timespec ts, int s1, int s2, int tdoa) {
    fprintf(fp, "%ld,%ld,%d,%d,%d\n",
            (long)ts.tv_sec, (long)ts.tv_nsec, s1, s2, tdoa);
    fflush(fp);
}

int main(void) {
    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 for both sensors */
    i2c_handle1 = i2cOpen(1, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error: Failed to open I2C 0x%02X: %s\n", SENSOR1_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(1, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error: Failed to open I2C 0x%02X: %s\n", SENSOR2_ADDR, strerror(errno));
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    /* Initialize sensors: enable continuous measurement */
    if (init_sensor(i2c_handle1, SENSOR1_ADDR) != 0) {
        fprintf(stderr, "Error: Sensor 1 initialization failed\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle2, SENSOR2_ADDR) != 0) {
        fprintf(stderr, "Error: Sensor 2 initialization failed\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    /* Open log file in append mode */
    log_file = fopen("audio_log.dat", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "sec,nsec,sensor1,sensor2,tdoa\n");
        fflush(log_file);
    }

    printf("Echolocation analysis started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
            break;
        }

        int s1 = read_sensor_data(i2c_handle1, SENSOR1_ADDR);
        int s2 = read_sensor_data(i2c_handle2, SENSOR2_ADDR);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Warning: Sensor read error at %ld.%09ld, skipping sample\n",
                    (long)ts.tv_sec, (long)ts.tv_nsec);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int tdoa = s1 - s2;
        log_data(log_file, ts, s1, s2, tdoa);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    gpioTerminate();

    printf("Echolocation analysis stopped.\n");
    return 0;
}

