#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16488A register addresses */
#define X_GYRO   0x04
#define Y_GYRO   0x06
#define Z_GYRO   0x08
#define X_ACCEL  0x0A
#define Y_ACCEL  0x0C
#define Z_ACCEL  0x0E

/* Sensitivities (from ADIS16488A datasheet) */
#define GYRO_SENSITIVITY  0.005f   /* deg/sec/LSB */
#define ACCEL_SENSITIVITY 0.00025f /* g/LSB */

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 /* 1 MHz */
#define SPI_FLAGS   0b11000000000 /* CPHA=1, CPOL=1, aux SPI off */

/* Timing */
#define SAMPLE_PERIOD_US 100000 /* 100 ms */
#define READ_DELAY_US    40     /* ADIS16488A read protocol stall */

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

/*
 * ADIS16488A read protocol: send a 16-bit request word (MSB=0, bits 6-0 =
 * register address) then stall for ~40 us before issuing a dummy read to
 * retrieve the register's data on the next 16-bit word.
 */
static int read_register(uint8_t reg, int16_t *out) {
    char tx_req[2], rx_req[2];
    char tx_dummy[2], rx_dummy[2];

    /* Request phase: MSB=0, address in bits 6-0 */
    tx_req[0] = (char)(reg & 0x7F);
    tx_req[1] = 0x00;

    if (spiXfer(spi_handle, tx_req, rx_req, 2) != 2) {
        fprintf(stderr, "SPI request transfer failed for reg 0x%02X\n", reg);
        return -1;
    }

    gpioDelay(READ_DELAY_US);

    /* Dummy phase: send any 16-bit word, read the response */
    tx_dummy[0] = 0x00;
    tx_dummy[1] = 0x00;

    if (spiXfer(spi_handle, tx_dummy, rx_dummy, 2) != 2) {
        fprintf(stderr, "SPI data transfer failed for reg 0x%02X\n", reg);
        return -1;
    }

    *out = (int16_t)(((uint8_t)rx_dummy[0] << 8) | (uint8_t)rx_dummy[1]);
    return 0;
}

static int read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z,
                         float *accel_x, float *accel_y, float *accel_z) {
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    int16_t raw_accel_x, raw_accel_y, raw_accel_z;

    if (read_register(X_GYRO, &raw_gyro_x) != 0) return -1;
    if (read_register(Y_GYRO, &raw_gyro_y) != 0) return -1;
