#define SAMPLE_PERIOD_US 100000 /* 100 ms */
#define READ_DELAY_US    40     /* ADIS16488A read protocol stall */

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

/*
 * ADIS16488A read protocol: send a 16-bit request word (MSB=0, bits 6-0 =
 * register address) then stall for ~40 us before issuing a dummy read to
 * retrieve the register's data on the next 16-bit word.
