static int read_register(uint8_t reg, int16_t *out) {
    char tx_req[2], rx_req[2];
    char tx_dummy[2], rx_dummy[2];

    /* Request phase: MSB=0, address in bits 6-0 */
    tx_req[0] = (char)(reg & 0x7F);
    tx_req[1] = 0x00;

    if (spiXfer(spi_handle, tx_req, rx_req, 2) != 2) {
        fprintf(stderr, "SPI request transfer failed for reg 0x%02X\n", reg);
        return -1;
    }

    gpioDelay(READ_DELAY_US);

    /* Dummy phase: send any 16-bit word, read the response */
    tx_dummy[0] = 0x00;
    tx_dummy[1] = 0x00;

    if (spiXfer(spi_handle, tx_dummy, rx_dummy, 2) != 2) {
        fprintf(stderr, "SPI data transfer failed for reg 0x%02X\n", reg);
        return -1;
