#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8

#define CS_GPIO_LINE    8
#define CS_CHIP_NAME    "gpiochip4"

#define GYRO_X_OUT  0x04
#define GYRO_Y_OUT  0x06
#define GYRO_Z_OUT  0x08
#define ACCL_X_OUT  0x0A
#define ACCL_Y_OUT  0x0C
#define ACCL_Z_OUT  0x0E

#define GYRO_SCALE  0.02f
#define ACCL_SCALE  0.00025f

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_register(int fd, struct gpiod_line *cs, uint8_t reg, int16_t *out) {
    uint8_t tx[2], rx[2];

    /* ADIS16448 single-register read: send address with bit 7 set */
    tx[0] = reg | 0x80;
    tx[1] = 0x00;

    if (gpiod_line_set_value(cs, 0) < 0) {
        fprintf(stderr, "CS low failed: %s\n", strerror(errno));
        return -1;
    }

    if (spi_transfer(fd, tx, rx, 2) < 0) {
        gpiod_line_set_value(cs, 1);
        return -1;
    }

    /* Dummy read to clock out the data */
    tx[0] = 0x00;
    tx[1] = 0x00;
    if (spi_transfer(fd, tx, rx, 2) < 0) {
        gpiod_line_set_value(cs, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs, 1) < 0) {
        fprintf(stderr, "CS high failed: %s\n", strerror(errno));
        return -1;
    }

    *out = (int16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

int main(void) {
    int fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CS_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CS_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    cs = gpiod_chip_get_line(chip, CS_GPIO_LINE);
    if (!cs) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(cs, "adis16448-cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("ADIS16448 IMU Reader (spidev + libgpiod)\n");
    printf("Gyroscope scale: %.4f dps/LSB, Accelerometer scale: %.6f g/LSB\n",
           GYRO_SCALE, ACCL_SCALE);

    while (running) {
        int16_t gx, gy, gz, ax, ay, az;

        if (read_register(fd, cs, GYRO_X_OUT, &gx) < 0 ||
            read_register(fd, cs, GYRO_Y_OUT, &gy) < 0 ||
            read_register(fd, cs, GYRO_Z_OUT, &gz) < 0 ||
            read_register(fd, cs, ACCL_X_OUT, &ax) < 0 ||
            read_register(fd, cs, ACCL_Y_OUT, &ay) < 0 ||
            read_register(fd, cs, ACCL_Z_OUT, &az) < 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            usleep(100000);
            continue;
        }

        float gx_dps = gx * GYRO_SCALE;
        float gy_dps = gy * GYRO_SCALE;
        float gz_dps = gz * GYRO_SCALE;
        float ax_g = ax * ACCL_SCALE;
        float ay_g = ay * ACCL_SCALE;
        float az_g = az * ACCL_SCALE;

        printf("Gyro X: %7.2f dps, Y: %7.2f dps, Z: %7.2f dps | "
               "Accel X: %7.4f g, Y: %7.4f g, Z: %7.4f g\n",
               gx_dps, gy_dps, gz_dps, ax_g, ay_g, az_g);

        usleep(100000);
    }

    printf("\nExiting cleanly...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) close(fd);
    if (cs) gpiod_line_release(cs);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

