#include <pigpio.h>

/* ADIS16448 Register Addresses */
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

/* Scaling factors */
#define GYRO_SCALE 0.05f   /* deg/sec/LSB */
#define ACCL_SCALE 0.00025f /* g/LSB */

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 /* 1 MHz */
#define SPI_FLAGS   0       /* Mode 0, active-low CE */

/* Stall time for ADIS16448 (min 40 us) */
#define STALL_US 40

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * ADIS16448 two-cycle SPI read.
 * Cycle 1: send (reg | 0x8000) as 16-bit, stall 40 us.
 * Cycle 2: send 0x0000 as 16-bit, read 16-bit data.
