#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6886_ADDR 0x68
#define I2C_BUS "/dev/i2c-1"

#define WHO_AM_I 0x75
#define WHO_AM_I_VAL 0x86
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (burst reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int16_t combine(uint8_t high, uint8_t low) {
    return (int16_t)((high << 8) | low);
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6886_ADDR, strerror(errno));
        goto cleanup;
    }

    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Sensor not responding on bus.\n");
        goto cleanup;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        goto cleanup;
    }

    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU-6886.\n");
        goto cleanup;
    }
    usleep(100000);

    if (i2c_write_reg8(fd, ACCEL_CONFIG, 0x00) < 0 || i2c_write_reg8(fd, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure MPU-6886.\n");
        goto cleanup;
    }

    printf("MPU-6886 initialized. Reading every 50 ms. Press Ctrl+C to exit.\n");

    while (running) {
        uint8_t accel_buf[6], gyro_buf[6];
        int accel_ok = 0, gyro_ok = 0;

        for (int attempt = 0; attempt < 3 && running; attempt++) {
            if (i2c_read_burst(fd, ACCEL_XOUT_H, accel_buf, 6) == 0) {
                accel_ok = 1;
                break;
            }
            usleep(10000);
        }
        if (!accel_ok) {
            fprintf(stderr, "Failed to read accelerometer data after retries.\n");
            goto cleanup;
        }

        for (int attempt = 0; attempt < 3 && running; attempt++) {
            if (i2c_read_burst(fd, GYRO_XOUT_H, gyro_buf, 6) == 0) {
                gyro_ok = 1;
                break;
            }
            usleep(10000);
        }
        if (!gyro_ok) {
            fprintf(stderr, "Failed to read gyroscope data after retries.\n");
            goto cleanup;
        }

        int16_t ax = combine(accel_buf[0], accel_buf[1]);
        int16_t ay = combine(accel_buf[2], accel_buf[3]);
        int16_t az = combine(accel_buf[4], accel_buf[5]);
        int16_t gx = combine(gyro_buf[0], gyro_buf[1]);
        int16_t gy = combine(gyro_buf[2], gyro_buf[3]);
        int16_t gz = combine(gyro_buf[4], gyro_buf[5]);

        printf("Accel: X=%6d Y=%6d Z=%6d  Gyro: X=%6d Y=%6d Z=%6d\n", ax, ay, az, gx, gy, gz);
        usleep(50000);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

