#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ICM-20602 I2C address (AD0 tied to GND) */
#define ICM20602_ADDR 0x68

/* ICM-20602 register addresses */
#define WHO_AM_I     0x75
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG  0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

/* Expected WHO_AM_I value for ICM-20602 */
#define ICM20602_WHO_AM_I 0x12

/* Global variables for signal handling */
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

/* Signal handler for Ctrl+C */
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Function to initialize the ICM-20602 */
int init_icm20602(int handle) {
    /* Wake up the device (clear SLEEP bit) */
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100000); /* 100 ms delay for oscillator to stabilize */

    /* Set accelerometer range to +/- 2g (AFS_SEL = 0) */
    if (i2cWriteByteData(handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to ACCEL_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    /* Set gyroscope range to +/- 250 dps (FS_SEL = 0) */
    if (i2cWriteByteData(handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    /* Verify sensor presence */
    int who_am_i = i2cReadByteData(handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != ICM20602_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n",
                ICM20602_WHO_AM_I, who_am_i);
        return -1;
    }

    return 0;
}

/* Function to read accelerometer data */
int read_accel_data(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* Function to read gyroscope data */
int read_gyro_data(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data: %s\n", strerror(errno));
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* Function to log data to a CSV file */
int log_data(FILE *fp, int16_t ax, int16_t ay, int16_t az,
             int16_t gx, int16_t gy, int16_t gz) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%ld.%09ld,%d,%d,%d,%d,%d,%d\n",
                (long)ts.tv_sec, ts.tv_nsec,
                ax, ay, az, gx, gy, gz) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 */
    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    /* Initialize the ICM-20602 */
    if (init_icm20602(i2c_handle) != 0) {
        fprintf(stderr, "ICM-20602 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Open the log file */
    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Write the CSV header */
    if (fprintf(log_file, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z\n") < 0) {
        fprintf(stderr, "Error writing CSV header: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Set up signal handling for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int16_t ax, ay, az, gx, gy, gz;

    /* Main loop */
    while (running) {
        /* Read accelerometer and gyroscope data */
        if (read_accel_data(i2c_handle, &ax, &ay, &az) != 0) {
            fprintf(stderr, "Error reading accelerometer data, continuing...\n");
        }
        if (read_gyro_data(i2c_handle, &gx, &gy, &gz) != 0) {
            fprintf(stderr, "Error reading gyroscope data, continuing...\n");
        }

        /* Log the data */
        if (log_data(log_file, ax, ay, az, gx, gy, gz) != 0) {
            fprintf(stderr, "Error logging data, continuing...\n");
        }

        /* Delay for 100 ms (10 Hz) */
        gpioDelay(100000);
    }

    /* Clean up and exit */
    printf("\nExiting gracefully...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

