#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define LSM6DSR_ADDR 0x6A
#define I2C_BUS 1

#define WHO_AM_I 0x0F
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

#define ACCEL_SCALE 0.061f
#define GYRO_SCALE 0.00875f

#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define FREEFALL_WINDOW 1.0

#define LOG_FILE "motion_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef enum {
    IDLE,
    FREEFALL,
    IMPACT
} FallState;

static FallState current_state = IDLE;
static time_t freefall_start_time = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(i2c_handle, reg, val) < 0) {
        fprintf(stderr, "I2C write error: reg=0x%02X, val=0x%02X\n", reg, val);
        return -1;
    }
    return 0;
}

static int i2c_read_regs(uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len) != (int)len) {
        fprintf(stderr, "I2C read error: reg=0x%02X, len=%u\n", reg, len);
        return -1;
    }
    return 0;
}

static int init_lsm6dsr(void) {
    uint8_t who_am_i = 0;
    if (i2c_read_regs(WHO_AM_I, &who_am_i, 1) < 0) return -1;
    if (who_am_i != 0x6C) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%02X (expected 0x6C)\n", who_am_i);
        return -1;
    }

    if (i2c_write_reg(CTRL1_XL, 0x80) < 0) return -1;
    if (i2c_write_reg(CTRL2_G, 0x80) < 0) return -1;
    return 0;
}

static int read_accel(float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_regs(OUTX_L_XL, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = raw_x * ACCEL_SCALE;
    *y = raw_y * ACCEL_SCALE;
    *z = raw_z * ACCEL_SCALE;
    return 0;
}

static int read_gyro(float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_regs(OUTX_L_G, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = raw_x * GYRO_SCALE;
    *y = raw_y * GYRO_SCALE;
    *z = raw_z * GYRO_SCALE;
    return 0;
}

static void log_data(float ax, float ay, float az, float gx, float gy, float gz) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n", ts, ax, ay, az, gx, gy, gz);
    fflush(log_file);
}

static void fall_state_machine(float ax, float ay, float az) {
    float mag = sqrtf(ax * ax + ay * ay + az * az);
    time_t now = time(NULL);

    switch (current_state) {
        case IDLE:
            if (mag < FREEFALL_THRESHOLD) {
                current_state = FREEFALL;
                freefall_start_time = now;
                printf("Freefall detected!\n");
            }
            break;
        case FREEFALL:
            if (mag > IMPACT_THRESHOLD) {
                current_state = IMPACT;
                printf("Impact detected!\n");
            } else if (difftime(now, freefall_start_time) > FREEFALL_WINDOW) {
                current_state = IDLE;
            }
            break;
        case IMPACT:
            current_state = IDLE;
            break;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR init failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float ax, ay, az, gx, gy, gz;
    while (!terminate) {
        if (read_accel(&ax, &ay, &az) == 0 && read_gyro(&gx, &gy, &gz) == 0) {
            log_data(ax, ay, az, gx, gy, gz);
            fall_state_machine(ax, ay, az);
        } else {
            fprintf(stderr, "Sensor read error, retrying...\n");
        }
        gpioDelay(100000);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

