#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0x0003   /* mode 3: CPOL=1, CPHA=1, active-low CE */

/* Scaling factor: 0.0305 deg/sec per LSB (from datasheet) */
#define GYRO_SCALE 0.0305f

/* Sampling interval */
#define SAMPLE_INTERVAL_US 10000  /* 10 ms */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16266 via SPI                   */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *value)
{
    char tx[2];
    char rx[2];

    /* Bit 7 = 1 -> read command */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    /* ADIS16266 returns data big-endian */
    *value = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an ADIS16266 register via SPI               */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int write_register(uint8_t reg, int16_t value)
{
    char tx[2];
    char rx[2];

    /* Bit 7 = 0 -> write command */
    tx[0] = (char)(reg & 0x7F);
    tx[1] = (char)(value & 0xFF);  /* low byte of 16-bit value */

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write transfer failed for register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Verify device identity                                              */
/* ------------------------------------------------------------------ */
static int verify_device(void)
{
    int16_t who_am_i = 0;
    if (read_register(ADIS16266_REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if ((uint16_t)who_am_i != ADIS16266_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                (uint16_t)who_am_i, ADIS16266_WHO_AM_I_VAL);
        return -1;
    }
    printf("ADIS16266 detected (WHO_AM_I = 0x%04X)\n", (uint16_t)who_am_i);
    return 0;
}

