    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0 at 1 MHz, mode 3 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify device identity */
    if (verify_device() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file once; write header */
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        perror("Failed to open gyro_log.csv");
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp,AngularRate_deg_sec\n");
    fflush(log_file);

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM) failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging gyroscope data to gyro_log.csv (Ctrl+C to stop)\n");

    /* Main sampling loop */
    while (!terminate) {
        int16_t raw_gyro = 0;
        if (read_register(ADIS16266_REG_XGYRO_OUT, &raw_gyro) != 0) {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float angular_rate = (float)raw_gyro * GYRO_SCALE;

        /* Timestamp */
        time_t now = time(NULL);
        struct tm tm_info;
        char timestamp[32];
        if (localtime_r(&now, &tm_info) != NULL) {
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
        } else {
            snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
        }

        /* Log to file */
        fprintf(log_file, "%s,%.4f\n", timestamp, angular_rate);
        fflush(log_file);

        /* 10 ms delay */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

