#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* L3G4200D I2C address (SA0 tied to VDD -> 0x69) */
#define L3G4200D_ADDR 0x69

/* L3G4200D register addresses */
#define WHO_AM_I     0x0F
#define CTRL_REG1    0x20
#define CTRL_REG4    0x23
#define OUT_X_L      0x28

/* Expected device ID */
#define WHO_AM_I_VAL 0xD3

/* Sensitivity for +-250 dps full-scale: 8.75 mdps/LSB = 1/114.285 dps/LSB */
#define SENSITIVITY 114.285f

/* Sampling interval in microseconds (10 ms) */
#define SAMPLE_INTERVAL_US 10000

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Retry count for I2C operations */
#define I2C_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a byte to an L3G4200D register with retries */
static int write_register(int handle, uint8_t reg, uint8_t value) {
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed (rc=%d), attempt %d/%d\n",
                reg, value, rc, attempt + 1, I2C_RETRIES);
        gpioDelay(1000); /* 1 ms backoff */
    }
    return -1;
}

/* Read a block of bytes starting at reg with retries */
static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
        if (rc == (int)len) {
            return 0;
        }
        fprintf(stderr, "Warning: i2cReadI2CBlockData(reg=0x%02X, len=%u) returned %d (expected %u), attempt %d/%d\n",
                reg, len, rc, len, attempt + 1, I2C_RETRIES);
        gpioDelay(1000);
    }
    return -1;
}

/* Initialize the L3G4200D gyroscope */
static int init_gyro(int handle) {
    /* Verify device identity */
    int who = i2cReadByteData(handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register (rc=%d)\n", who);
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X). Sensor not present or wrong address.\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: 0x0F = normal mode, all axes enabled, ODR = 100 Hz */
    if (write_register(handle, CTRL_REG1, 0x0F) != 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG1\n");
        return -1;
    }

    /* CTRL_REG4: 0x00 = +-250 dps full-scale, continuous update, little-endian */
    if (write_register(handle, CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG4\n");
        return -1;
    }

    return 0;
}

/* Read angular velocities from the gyroscope */
static int read_gyro_data(int handle, float *x, float *y, float *z) {
    uint8_t buf[6];

    if (read_block(handle, OUT_X_L | 0x80, buf, 6) != 0) {
        fprintf(stderr, "Error: Failed to read gyro data block\n");
        return -1;
    }

    /* L3G4200D outputs are left-justified 16-bit; combine high and low bytes */
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    /* Convert to degrees per second */
    *x = (float)raw_x / SENSITIVITY;
    *y = (float)raw_y / SENSITIVITY;
    *z = (float)raw_z / SENSITIVITY;

    return 0;
}

/* Log data to CSV file with nanosecond precision */
static void log_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, L3G4200D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed (rc=%d)\n", I2C_BUS, L3G4200D_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the gyroscope */
    if (init_gyro(i2c_handle) != 0) {
        fprintf(stderr, "Error: Gyroscope initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open the log file */
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open gyro_log.csv: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write the header row */
    fprintf(log_file, "Timestamp,X,Y,Z\n");
    fflush(log_file);

    /* Set up signal handling for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to set SIGINT handler: %s\n", strerror(errno));
    }

    float x, y, z;

    /* Main loop */
    while (!terminate) {
        if (read_gyro_data(i2c_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Warning: Skipping sample due to read error\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean up */
    fprintf(stderr, "\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

