#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* Signal handler for Ctrl+C */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Get current timestamp as a static string "YYYY-MM-DD HH:MM:SS" */
static const char *get_timestamp(void) {
    static char timestamp[20];
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        strncpy(timestamp, "1970-01-01 00:00:00", sizeof(timestamp));
        return timestamp;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

/* Log a flame event line and flush immediately */
static void log_flame_event(int flame_detected) {
    if (log_file == NULL) {
        return;
    }
    fprintf(log_file, "%s - Flame detected: %s\n",
            get_timestamp(), flame_detected ? "YES" : "NO");
    fflush(log_file);
}

/* Print a fire-alarm-style message to stdout */
static void trigger_alarm(void) {
    printf("FLAME DETECTED!\n");
    fflush(stdout);
}

int main(void) {
    int ret;

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", ret);
        return EXIT_FAILURE;
    }

    /* Set GPIO17 as input with internal pull-up so the sensor's
       open-collector output is deterministic when the sensor is off. */
    ret = gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %d\n",
                FLAME_SENSOR_GPIO, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);
    if (ret != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d: %d\n",
                FLAME_SENSOR_GPIO, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           FLAME_SENSOR_GPIO);
    fflush(stdout);

    /* Main polling loop */
    while (program_running) {
        int sensor_value = gpioRead(FLAME_SENSOR_GPIO);

        if (sensor_value == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO%d\n", FLAME_SENSOR_GPIO);
            log_flame_event(-1);  /* -1 indicates read error */
        } else {
            /* KY-026 DO is active-LOW: 0 = flame detected, 1 = no flame */
            int flame_detected = (sensor_value == 0);
            log_flame_event(flame_detected);
            if (flame_detected) {
                trigger_alarm();
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nExiting gracefully...\n");
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

