#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 27
#define LOG_FILE "conveyor_log.txt"
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_data(FILE *fp, int sensor1_state, int sensor2_state) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s.%03ld, Sensor1: %d, Sensor2: %d\n",
                timestamp, ts.tv_nsec / 1000000,
                sensor1_state, sensor2_state) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) == EOF) {
        perror("fflush");
        return -1;
    }

    return 0;
}

