#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define LOG_FILE "vibration_log.txt"
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3

#define ADXL354B_REG_DEVID_AD 0x00
#define ADXL354B_REG_XDATA_L 0x08
#define ADXL354B_REG_YDATA_L 0x0B
#define ADXL354B_REG_ZDATA_L 0x0E
#define ADXL354B_REG_STATUS 0x04
#define ADXL354B_REG_POWER_CTL 0x2D
#define ADXL354B_REG_RESET 0x1F

#define ADXL354B_PARTID 0x1D
#define ADXL354B_RESET_KEY 0x52
#define ADXL354B_STATUS_STABLE 0x01
#define ADXL354B_POWER_CTL_RUN 0x02

#define G_PER_LSB 0.0000039f

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx[3] = { (char)(reg | 0x80 | 0x40), 0x00, 0x00 };
    char rx[3] = { 0 };
    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) return -1;
    *value = (uint8_t)rx[2];
    return 0;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[3] = { (char)(reg & 0x7F), (char)value, 0x00 };
    char rx[3] = { 0 };
    int ret = spiXfer(spi_handle, tx, rx, 3);
    return (ret == 3) ? 0 : -1;
}

static int spi_read_burst(uint8_t reg, uint8_t *buf, int len) {
    char tx[32] = { 0 };
    char rx[32] = { 0 };
    if (len > 30) return -1;
    tx[0] = (char)(reg | 0x80 | 0x40);
    int ret = spiXfer(spi_handle, tx, rx, len + 1);
    if (ret != len + 1) return -1;
    memcpy(buf, rx + 1, len);
    return 0;
}

static int adxl354b_init(void) {
    uint8_t partid = 0;
    if (spi_read_register(ADXL354B_REG_DEVID_AD, &partid) != 0) {
        fprintf(stderr, "Error: Failed to read PARTID\n");
        return -1;
    }
    if (partid != ADXL354B_PARTID) {
        fprintf(stderr, "Error: Unexpected PARTID 0x%02X (expected 0x%02X)\n", partid, ADXL354B_PARTID);
        return -1;
    }

    if (spi_write_register(ADXL354B_REG_RESET, ADXL354B_RESET_KEY) != 0) {
        fprintf(stderr, "Error: Failed to reset ADXL354B\n");
        return -1;
    }
    gpioDelay(1000);

    uint8_t power = 0;
    if (spi_read_register(ADXL354B_REG_POWER_CTL, &power) != 0) {
        fprintf(stderr, "Error: Failed to read POWER_CTL\n");
        return -1;
    }
    power |= ADXL354B_POWER_CTL_RUN;
    if (spi_write_register(ADXL354B_REG_POWER_CTL, power) != 0) {
        fprintf(stderr, "Error: Failed to set RUN bit\n");
        return -1;
    }

    for (int i = 0; i < 100; i++) {
        uint8_t status = 0;
        if (spi_read_register(ADXL354B_REG_STATUS, &status) != 0) {
            fprintf(stderr, "Error: Failed to read STATUS\n");
            return -1;
        }
        if (status & ADXL354B_STATUS_STABLE) break;
        gpioDelay(1000);
    }

    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    uint8_t data[6];
    if (spi_read_burst(ADXL354B_REG_XDATA_L, data, 6) != 0) {
        fprintf(stderr, "Error: SPI burst read failed\n");
        return -1;
    }

    int32_t raw_x = (int32_t)((data[2] << 12) | (data[1] << 4) | (data[0] >> 4));
    int32_t raw_y = (int32_t)((data[5] << 12) | (data[4] << 4) | (data[3] >> 4));
    int32_t raw_z = (int32_t)((data[8] << 12) | (data[7] << 4) | (data[6] >> 4));

    if (raw_x & 0x80000) raw_x |= 0xFFF00000;
    if (raw_y & 0x80000) raw_y |= 0xFFF00000;
    if (raw_z & 0x80000) raw_z |= 0xFFF00000;

    *x = (float)raw_x * G_PER_LSB;
    *y = (float)raw_y * G_PER_LSB;
    *z = (float)raw_z * G_PER_LSB;
    return 0;
}

static void log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, X: %.6f g, Y: %.6f g, Z: %.6f g\n", ts, x, y, z);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 8) | SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    if (adxl354b_init() != 0) {
        fprintf(stderr, "Error: ADXL354B initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Logging ADXL354B data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (!terminate) {
        float x, y, z;
        int retries = 0;
        int success = 0;
        while (retries < MAX_RETRIES && !terminate) {
            if (read_acceleration(&x, &y, &z) == 0) {
                success = 1;
                break;
            }
            retries++;
            gpioDelay(10000);
        }
        if (success) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Warning: Max retries reached, skipping sample\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

