    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, X: %.6f g, Y: %.6f g, Z: %.6f g\n", ts, x, y, z);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 8) | SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    if (adxl354b_init() != 0) {
        fprintf(stderr, "Error: ADXL354B initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Logging ADXL354B data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (!terminate) {
        float x, y, z;
        int retries = 0;
        int success = 0;
        while (retries < MAX_RETRIES && !terminate) {
            if (read_acceleration(&x, &y, &z) == 0) {
                success = 1;
                break;
            }
            retries++;
            gpioDelay(10000);
        }
        if (success) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Warning: Max retries reached, skipping sample\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

