/* ADIS16362 Register Addresses */
#define X_GYRO_REG 0x04
#define Y_GYRO_REG 0x06
#define Z_GYRO_REG 0x08
#define X_ACCL_REG 0x0A
#define Y_ACCL_REG 0x0C
#define Z_ACCL_REG 0x0E

/* Scaling factors (from ADIS16362 datasheet) */
#define GYRO_SCALE 0.05f   /* deg/sec per LSB */
#define ACCL_SCALE 0.0025f /* g per LSB */

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000   /* 1 MHz */
#define SPI_FLAGS 0x03     /* Mode 3: active-high clock, sampled on trailing edge */

/* Timing */
#define SAMPLE_DELAY_US 10000 /* 10 ms -> ~100 Hz */
#define CONVERSION_DELAY_US 100 /* 100 us conversion wait */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/*
 * Read a 16-bit register from the ADIS16362.
 * Protocol: send (reg_addr | 0x80, 0x00), wait, then send (0x00, 0x00) to read data.
 * Returns 0 on success, -1 on SPI transfer failure.
 */
static int read_register(uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];
    int ret;

    /* Phase 1: send address with MSB set, dummy byte */
    tx_buf[0] = (char)(reg_addr | 0x80);
    tx_buf[1] = 0x00;
    ret = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer failed for address 0x%02X (phase 1): ret=%d\n", reg_addr, ret);
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);

    /* Phase 2: send dummy bytes to clock out the data */
    tx_buf[0] = 0x00;
    tx_buf[1] = 0x00;
    ret = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer failed for address 0x%02X (phase 2): ret=%d\n", reg_addr, ret);
        return -1;
    }

    *data = (int16_t)(((uint8_t)rx_buf[0] << 8) | (uint8_t)rx_buf[1]);
    return 0;
}

/* Read all 6 axes and apply scaling */
static int read_imu_data(float *x_gyro, float *y_gyro, float *z_gyro,
                         float *x_accl, float *y_accl, float *z_accl) {
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    int16_t raw_accl_x, raw_accl_y, raw_accl_z;

    if (read_register(X_GYRO_REG, &raw_gyro_x) != 0) return -1;
    if (read_register(Y_GYRO_REG, &raw_gyro_y) != 0) return -1;
    if (read_register(Z_GYRO_REG, &raw_gyro_z) != 0) return -1;
    if (read_register(X_ACCL_REG, &raw_accl_x) != 0) return -1;
    if (read_register(Y_ACCL_REG, &raw_accl_y) != 0) return -1;
    if (read_register(Z_ACCL_REG, &raw_accl_z) != 0) return -1;

