            timestamp, x_gyro, y_gyro, z_gyro, x_accl, y_accl, z_accl);
    fflush(log_file);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed on channel %d: %d\n", SPI_CHANNEL, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open imu_log.csv: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header */
    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    fflush(log_file);

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADIS16362 IMU logging started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        float x_gyro, y_gyro, z_gyro;
        float x_accl, y_accl, z_accl;

        if (read_imu_data(&x_gyro, &y_gyro, &z_gyro,
                          &x_accl, &y_accl, &z_accl) == 0) {
            log_data(x_gyro, y_gyro, z_gyro, x_accl, y_accl, z_accl);
        } else {
            fprintf(stderr, "Error reading IMU data, skipping sample\n");
