/*
 * KY-032 IR Obstacle Avoidance - libgpiod v2 bulk-read
 * Board:  Raspberry Pi 3 Model B+
 * Sensors: Keyes KY-032 on GPIO17 (BCM) and GPIO27 (BCM)
 *   Active-low output: 0 = obstacle detected, 1 = clear
 * Build:  gcc -O2 -Wall -Wextra -o ky032_avoidance ky032_avoidance.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_PIN_17     17
#define GPIO_PIN_27     27
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];

    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", buf);
    } else {
        printf("[unknown] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *req = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct timespec poll_ts = { 0, POLL_INTERVAL_MS * 1000000L };
    unsigned int offsets[2] = { GPIO_PIN_17, GPIO_PIN_27 };
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the gpiochip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure both lines as inputs */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "gpiod_line_settings_new failed: %s\n", strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "gpiod_line_config_new failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_config_add_line_settings(line_cfg, offsets, 2, settings) != 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings failed: %s\n", strerror(errno));
        goto cleanup;
    }

    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "gpiod_request_config_new failed: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ky032-avoidance");

    req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (req == NULL) {
