#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 3
#define SPI_BITS 8

#define CS_GPIO_CHIP "gpiochip4"
#define CS_GPIO_LINE 8

#define ADIS16266_REG_XGYRO_OUT 0x04
#define ADIS16266_REG_YGYRO_OUT 0x06
#define ADIS16266_REG_ZGYRO_OUT 0x08
#define ADIS16266_REG_MSC_CTRL 0x24

#define ADIS16266_SCALE_FACTOR 0.02f
#define SAMPLE_PERIOD_MS 100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int adis16266_write_reg(int fd, struct gpiod_line *cs, uint8_t reg, uint16_t value) {
    uint8_t tx[3] = { (uint8_t)(reg & 0x7F), (uint8_t)(value >> 8), (uint8_t)(value & 0xFF) };
    uint8_t rx[3] = {0};

    if (gpiod_line_set_value(cs, 0) < 0) {
        perror("Failed to assert CS");
        return -1;
    }
    usleep(10);

    if (spi_transfer(fd, tx, rx, 3) < 0) {
        gpiod_line_set_value(cs, 1);
        return -1;
    }
    usleep(10);

    if (gpiod_line_set_value(cs, 1) < 0) {
        perror("Failed to deassert CS");
        return -1;
    }
    return 0;
}

static int adis16266_read_reg(int fd, struct gpiod_line *cs, uint8_t reg, uint16_t *value) {
    uint8_t tx[3] = { (uint8_t)(reg | 0x80), 0x00, 0x00 };
    uint8_t rx[3] = {0};

    if (gpiod_line_set_value(cs, 0) < 0) {
        perror("Failed to assert CS");
        return -1;
    }
    usleep(10);

    if (spi_transfer(fd, tx, rx, 3) < 0) {
        gpiod_line_set_value(cs, 1);
        return -1;
    }
    usleep(10);

    if (gpiod_line_set_value(cs, 1) < 0) {
        perror("Failed to deassert CS");
        return -1;
    }

    *value = ((uint16_t)rx[1] << 8) | rx[2];
    return 0;
}

static int adis16266_read_axis(int fd, struct gpiod_line *cs, uint8_t reg, float *rate) {
    uint16_t raw;
    if (adis16266_read_reg(fd, cs, reg, &raw) < 0) {
        return -1;
    }
    int16_t signed_val = (int16_t)raw;
    *rate = (float)signed_val * ADIS16266_SCALE_FACTOR;
    return 0;
}

int main(void) {
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(CS_GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, CS_GPIO_LINE);
    if (!cs_line) {
        perror("Failed to get CS GPIO line");
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "adis16266_cs", 1) < 0) {
        perror("Failed to request CS line as output");
        goto cleanup;
    }

    if (adis16266_write_reg(spi_fd, cs_line, ADIS16266_REG_MSC_CTRL, 0x0004) < 0) {
        fprintf(stderr, "Failed to configure MSC_CTRL register\n");
        goto cleanup;
    }

    printf("ADIS16266 initialized. Reading gyro data every %d ms...\n", SAMPLE_PERIOD_MS);

    while (running) {
        float x_rate, y_rate, z_rate;

        if (adis16266_read_axis(spi_fd, cs_line, ADIS16266_REG_XGYRO_OUT, &x_rate) < 0) {
            fprintf(stderr, "Error reading X axis\n");
        } else if (adis16266_read_axis(spi_fd, cs_line, ADIS16266_REG_YGYRO_OUT, &y_rate) < 0) {
            fprintf(stderr, "Error reading Y axis\n");
        } else if (adis16266_read_axis(spi_fd, cs_line, ADIS16266_REG_ZGYRO_OUT, &z_rate) < 0) {
            fprintf(stderr, "Error reading Z axis\n");
        } else {
            printf("X: %.2f deg/sec, Y: %.2f deg/sec, Z: %.2f deg/sec\n", x_rate, y_rate, z_rate);
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return ret;
}

