#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C 7-bit address */
#define LSM6DSR_ADDR 0x6B

/* LSM6DSR register addresses */
#define WHO_AM_I       0x0F
#define CTRL1_XL       0x10
#define CTRL2_G        0x11
#define OUTX_L_G       0x22
#define OUTX_L_XL      0x28

/* Expected WHO_AM_I value for LSM6DSR */
#define LSM6DSR_WHO_AM_I 0x6B

/* Sensitivities for default ranges */
#define GYRO_SENSITIVITY_MDPS  8.75f   /* mdps/LSB at +/-250 dps */
#define ACCEL_SENSITIVITY_MG   0.061f  /* mg/LSB at +/-2g */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int16_t combine_bytes(uint8_t low, uint8_t high)
{
    return (int16_t)((uint16_t)high << 8 | (uint16_t)low);
}

static int init_lsm6dsr(int handle)
{
    /* Verify device identity */
    int who = i2cReadByteData(handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register (pigpio error %d)\n", who);
        return -1;
    }
    if (who != LSM6DSR_WHO_AM_I) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, LSM6DSR_WHO_AM_I);
        return -1;
    }

    /* Accelerometer: +-2g, 104 Hz, anti-aliasing filter bandwidth 400 Hz */
    if (i2cWriteByteData(handle, CTRL1_XL, 0x42) < 0) {
        fprintf(stderr, "Error: failed to write CTRL1_XL\n");
        return -1;
    }

    /* Gyroscope: +-250 dps, 104 Hz, anti-aliasing filter bandwidth 400 Hz */
    if (i2cWriteByteData(handle, CTRL2_G, 0x42) < 0) {
        fprintf(stderr, "Error: failed to write CTRL2_G\n");
        return -1;
    }

    return 0;
}

static int read_sensor_data(int handle,
                            float *gyro_x, float *gyro_y, float *gyro_z,
                            float *accel_x, float *accel_y, float *accel_z)
{
    uint8_t buf[12];

    /* Burst read 12 bytes: gyro X/Y/Z (6) + accel X/Y/Z (6) starting at OUTX_L_G */
    int n = i2cReadI2CBlockData(handle, OUTX_L_G, (char *)buf, 12);
    if (n != 12) {
        fprintf(stderr, "Error: burst read returned %d bytes (expected 12)\n", n);
        return -1;
    }

    int16_t gx = combine_bytes(buf[0], buf[1]);
    int16_t gy = combine_bytes(buf[2], buf[3]);
    int16_t gz = combine_bytes(buf[4], buf[5]);
    int16_t ax = combine_bytes(buf[6], buf[7]);
    int16_t ay = combine_bytes(buf[8], buf[9]);
    int16_t az = combine_bytes(buf[10], buf[11]);

    *gyro_x  = (float)gx * GYRO_SENSITIVITY_MDPS  / 1000.0f;  /* dps -> deg/s */
    *gyro_y  = (float)gy * GYRO_SENSITIVITY_MDPS  / 1000.0f;
    *gyro_z  = (float)gz * GYRO_SENSITIVITY_MDPS  / 1000.0f;
    *accel_x = (float)ax * ACCEL_SENSITIVITY_MG;              /* mg -> g */
    *accel_y = (float)ay * ACCEL_SENSITIVITY_MG;
    *accel_z = (float)az * ACCEL_SENSITIVITY_MG;

    return 0;
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at LSM6DSR address */
    g_i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio error %d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_lsm6dsr(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: LSM6DSR initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Main loop: 100 ms cadence */
    while (g_running) {
        float gx, gy, gz, ax, ay, az;

        if (read_sensor_data(g_i2c_handle, &gx, &gy, &gz, &ax, &ay, &az) == 0) {
            printf("Gyro: X=%.3f Y=%.3f Z=%.3f  Accel: X=%.3f Y=%.3f Z=%.3f\n",
                   gx, gy, gz, ax, ay, az);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: sensor read failed, continuing\n");
        }

        /* 100 ms delay (microseconds) */
        gpioDelay(100000);
    }

    /* Clean shutdown */
    fprintf(stderr, "\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
