#include <pigpio.h>

/* FXOS8700 I2C address (SA0 tied to GND on Adafruit breakout) */
#define FXOS8700_ADDR 0x1D

/* FXOS8700 register addresses */
#define FXOS8700_REG_STATUS      0x00
#define FXOS8700_REG_OUT_X_MSB   0x01
#define FXOS8700_REG_WHO_AM_I    0x0D
#define FXOS8700_REG_CTRL_REG1   0x2A
#define FXOS8700_REG_CTRL_REG2   0x2B
#define FXOS8700_REG_M_CTRL_REG1 0x5B
#define FXOS8700_REG_M_CTRL_REG2 0x5C

#define FXOS8700_WHO_AM_I_VAL    0xC7

/* CTRL_REG1: ACTIVE=1, DR=0x00 (100 Hz), LNOISE=0, F_READ=0 */
#define CTRL_REG1_VAL 0x00
/* CTRL_REG2: MODS=0x00 (hybrid mode), HPOFSET=0x00 */
#define CTRL_REG2_VAL 0x00
/* M_CTRL_REG1: M_HMS=0x03 (hybrid mode) */
#define M_CTRL_REG1_VAL 0x03
/* M_CTRL_REG2: M_HR=0x02 (80 Hz ODR) */
#define M_CTRL_REG2_VAL 0x02

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_checked(int handle, uint8_t reg, uint8_t val, const char *desc)
{
    if (i2cWriteByteData(handle, reg, val) < 0) {
        fprintf(stderr, "Error writing %s (reg 0x%02X, val 0x%02X): %s\n",
                desc, reg, val, pigpio_error(i2cWriteByteData(handle, reg, val)));
        return -1;
    }
    return 0;
}

static int init_fxos8700(int handle)
{
    int who = i2cReadByteData(handle, FXOS8700_REG_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error reading WHO_AM_I: %s\n", pigpio_error(who));
        return -1;
    }
    if (who != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_checked(handle, FXOS8700_REG_CTRL_REG1, CTRL_REG1_VAL,
                          "CTRL_REG1") < 0)
        return -1;
    if (i2c_write_checked(handle, FXOS8700_REG_CTRL_REG2, CTRL_REG2_VAL,
                          "CTRL_REG2") < 0)
        return -1;
    if (i2c_write_checked(handle, FXOS8700_REG_M_CTRL_REG1, M_CTRL_REG1_VAL,
                          "M_CTRL_REG1") < 0)
        return -1;
    if (i2c_write_checked(handle, FXOS8700_REG_M_CTRL_REG2, M_CTRL_REG2_VAL,
                          "M_CTRL_REG2") < 0)
        return -1;

    return 0;
}

static int read_sensor_data(int handle,
                            int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *mx, int16_t *my, int16_t *mz)
{
    char buf[12];
    int n = i2cReadI2CBlockData(handle, FXOS8700_REG_OUT_X_MSB, buf, 12);
    if (n != 12) {
        fprintf(stderr, "Error reading sensor data block: %s\n",
                (n < 0) ? pigpio_error(n) : "short read");
        return -1;
    }

    /* Accelerometer: 14-bit left-aligned, shift right 2 to get 16-bit */
    *ax = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1]) >> 2;
    *ay = (int16_t)(((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3]) >> 2;
    *az = (int16_t)(((uint16_t)(uint8_t)buf[4] << 8) | (uint8_t)buf[5]) >> 2;

    /* Magnetometer: 16-bit */
    *mx = (int16_t)(((uint16_t)(uint8_t)buf[6]  << 8) | (uint8_t)buf[7]);
    *my = (int16_t)(((uint16_t)(uint8_t)buf[8]  << 8) | (uint8_t)buf[9]);
    *mz = (int16_t)(((uint16_t)(uint8_t)buf[10] << 8) | (uint8_t)buf[11]);

    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %s\n",
                FXOS8700_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_fxos8700(g_i2c_handle) < 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("FXOS8700 initialized. Logging every 100 ms (Ctrl+C to stop).\n");

    while (g_running) {
        int16_t ax, ay, az, mx, my, mz;

        if (read_sensor_data(g_i2c_handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  Mag: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Read failed; will retry next cycle.\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

