#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0 0x32

// Tilt threshold in degrees
#define TILT_THRESHOLD 30.0

// Global variables
static int i2c_fd = -1;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_reg8(int fd, uint8_t reg);
int i2c_write_reg8(int fd, uint8_t reg, uint8_t value);
int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len);
int adxl345_init(int fd);
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
void calculate_tilt_angles(int16_t x, int16_t y, int16_t z, float *tilt_x, float *tilt_y);
bool is_tilt_event(float tilt_x, float tilt_y, float threshold);
void log_tilt_event(float tilt_x, float tilt_y);
void signal_handler(int signal);

// I2C read 8-bit register
int i2c_read_reg8(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        return -1;
    }
    return value;
}

// I2C write 8-bit register
int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

// I2C burst read
int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        return -1;
    }
    return 0;
}

// Initialize ADXL345
int adxl345_init(int fd) {
    // Set data format: full resolution, +/- 2g range
    if (i2c_write_reg8(fd, ADXL345_REG_DATA_FORMAT, 0x0B) < 0) {
        return -1;
    }
    // Enable measurement mode
    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ADXL345_REG_DATAX0, buf, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

// Calculate tilt angles in degrees
void calculate_tilt_angles(int16_t x, int16_t y, int16_t z, float *tilt_x, float *tilt_y) {
    *tilt_x = atan2((float)y, sqrt((float)x * x + (float)z * z)) * 180.0 / M_PI;
    *tilt_y = atan2((float)x, sqrt((float)y * y + (float)z * z)) * 180.0 / M_PI;
}

// Check if tilt event occurred
bool is_tilt_event(float tilt_x, float tilt_y, float threshold) {
    return (fabs(tilt_x) > threshold || fabs(tilt_y) > threshold);
}

// Log tilt event to file
void log_tilt_event(float tilt_x, float tilt_y) {
    FILE *fp = fopen("/var/log/tilt_events.log", "a");
    if (fp == NULL) {
