void calculate_tilt_angles(int16_t x, int16_t y, int16_t z, float *tilt_x, float *tilt_y) {
    *tilt_x = atan2((float)y, sqrt((float)x * x + (float)z * z)) * 180.0 / M_PI;
    *tilt_y = atan2((float)x, sqrt((float)y * y + (float)z * z)) * 180.0 / M_PI;
}

