    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing ADXL345. Check wiring and address.\n");
        close(i2c_fd);
        return 1;
    }

    printf("ADXL345 initialized. Monitoring tilt events...\n");

    // Main loop
    while (program_running) {
        int16_t x, y, z;
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
            usleep(100000); // Wait before retrying
            continue;
        }

        float tilt_x, tilt_y;
