#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_GPIO 17
#define SAMPLE_INTERVAL_US 1000
#define WINDOW_SECONDS 5
#define WINDOW_SAMPLES (WINDOW_SECONDS * 1000000 / SAMPLE_INTERVAL_US)

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int parse_threshold(int argc, char *argv[], int *threshold) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return -1;
    }

    char *endptr = NULL;
    long val = strtol(argv[1], &endptr, 10);

    if (endptr == argv[1] || *endptr != '\0') {
        fprintf(stderr, "Error: threshold must be an integer.\n");
        return -1;
    }

    if (val <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer.\n");
        return -1;
    }

    *threshold = (int)val;
    return 0;
}

static void print_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] ", buffer);
    }
}

int main(int argc, char *argv[]) {
    int threshold = 0;

    if (parse_threshold(argc, argv, &threshold) != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler.\n");
    }

    printf("Monitoring sound levels on GPIO%d. Threshold: %d high-readings/%d seconds.\n",
           SOUND_SENSOR_GPIO, threshold, WINDOW_SECONDS);
    fflush(stdout);

    while (program_running) {
        int high_count = 0;
        int sample_count = 0;
        int error_flag = 0;

        for (int i = 0; i < WINDOW_SAMPLES && program_running; i++) {
            int level = gpioRead(SOUND_SENSOR_GPIO);
            if (level < 0) {
                fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", SOUND_SENSOR_GPIO);
                error_flag = 1;
                break;
            }
            if (level == 1) {
                high_count++;
            }
            sample_count++;
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        if (error_flag) {
            break;
        }

        print_timestamp();

        if (high_count > threshold) {
            printf("ALERT: Sound level exceeded threshold (%d/%d high-readings)\n",
                   high_count, sample_count);
        } else {
            printf("Status: Sound level within acceptable range (%d/%d high-readings)\n",
                   high_count, sample_count);
        }
        fflush(stdout);

        if (program_running) {
            sleep(1);
        }
    }

    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

