/*
 * door_access.c — Raspberry Pi 4 Model B
 * libgpiod-based door-lock controller for two doors via 5V active-HIGH
 * relay modules (TIP120 transistors) on GPIO17 (Door A) and GPIO27 (Door B).
 *
 * Build:  gcc -Wall -o door_access door_access.c -lgpiod
 * Run:    ./door_access
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define DOOR_A_PIN  17
#define DOOR_B_PIN  27
#define UNLOCK_SEC  5
#define LOG_FILE    "access_log.txt"
#define CHIP_NAME   "gpiochip4"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int generate_security_code(void)
{
    return (rand() % 900000) + 100000;
}

/* ------------------------------------------------------------------ */
static int unlock_door(struct gpiod_line *line, int pin, int code)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("Unlocking Door %d (GPIO%d) with code %d...\n",
           (pin == DOOR_A_PIN) ? 1 : 2, pin, code);

    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value(HIGH)");
        return -1;
    }

    sleep(UNLOCK_SEC);

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value(LOW)");
        return -1;
    }

    printf("Door %d locked.\n", (pin == DOOR_A_PIN) ? 1 : 2);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    fprintf(fp, "%s,%d\n", timestamp, code);
    fclose(fp);

    return 0;
}

/* ------------------------------------------------------------------ */
static int get_user_input(int *code)
{
    char input[16];

    printf("Enter the 6-digit security code: ");
    fflush(stdout);

    if (fgets(input, sizeof(input), stdin) == NULL) {
        if (feof(stdin)) {
            fprintf(stderr, "EOF received; exiting.\n");
            return -1;
        }
        perror("fgets");
        return -1;
    }

    /* Strip trailing newline / carriage return */
    input[strcspn(input, "\r\n")] = '\0';

    if (strlen(input) != 6) {
        fprintf(stderr, "Invalid input length. Please enter exactly 6 digits.\n");
        return -1;
    }

    for (int i = 0; i < 6; i++) {
        if (input[i] < '0' || input[i] > '9') {
            fprintf(stderr, "Invalid character '%c' at position %d.\n",
                    input[i], i + 1);
            return -1;
        }
    }

    *code = atoi(input);
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL;
    struct gpiod_line *line_b = NULL;
    int security_code = 0;
    int ret = EXIT_FAILURE;

    srand((unsigned int)time(NULL));

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(" CHIP_NAME ")");
        return EXIT_FAILURE;
    }

    line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (line_a == NULL) {
        perror("gpiod_chip_get_line(GPIO17)");
        goto cleanup;
    }

    line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (line_b == NULL) {
        perror("gpiod_chip_get_line(GPIO27)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line_a, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(GPIO17)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line_b, "door_access", 0) < 0) {
        perror("gpiod_line_request_output(GPIO27)");
        goto cleanup;
    }

    security_code = generate_security_code();
    printf("Security code generated: %d\n", security_code);

    while (g_running) {
        int user_code = 0;

        if (get_user_input(&user_code) != 0) {
            if (!g_running) {
                break;
            }
            continue;
        }

        if (user_code == security_code) {
            printf("Access granted!\n");
            if (unlock_door(line_a, DOOR_A_PIN, security_code) != 0) {
                fprintf(stderr, "Failed to unlock Door A.\n");
            }
            security_code = generate_security_code();
            printf("New security code generated: %d\n", security_code);
        } else {
            printf("Access denied!\n");
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure both relays are de-energized (doors locked) */
    if (line_a != NULL) {
        gpiod_line_set_value(line_a, 0);
        gpiod_line_release(line_a);
    }
    if (line_b != NULL) {
        gpiod_line_set_value(line_b, 0);
        gpiod_line_release(line_b);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("Exiting cleanly.\n");
    return ret;
}

