#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BH1750_ADDR 0x23
#define BH1750_ONE_TIME_HIGH_RES_MODE_2 0x21
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "light_log.txt"
#define CONVERSION_DELAY_MS 180
#define POLL_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t bytes = read(fd, buf, len);
    if (bytes < 0 || (size_t)bytes != len) {
        return -1;
    }
    return 0;
}

static int read_illuminance(int fd, float *lux) {
    uint8_t buf[2];

    if (i2c_write_byte(fd, BH1750_ONE_TIME_HIGH_RES_MODE_2) < 0) {
        return -1;
    }

    usleep(CONVERSION_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, buf, 2) < 0) {
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static void log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus " I2C_BUS);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to acquire I2C bus access / talk to slave");
        close(i2c_fd);
        return 1;
    }

    printf("Starting light sensor readings. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (read_illuminance(i2c_fd, &lux) == 0) {
            log_data(lux);
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Error reading illuminance from sensor.\n");
        }

        for (int i = 0; i < POLL_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully.\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

