}

static int read_touch_data(uint8_t *data) {
    return mpr121_read(0x00, data, 12);
}

static int calculate_frequency(const uint8_t *touch_data) {
    int max_val = 0;
    for (int i = 0; i < 12; i++) {
        if (touch_data[i] > max_val) max_val = touch_data[i];
    }
    if (max_val == 0) return 220;
    double log_val = log((double)max_val + 1.0);
    double norm = log_val / log(255.0);
    int freq = (int)(220.0 + norm * 660.0);
    if (freq < 220) freq = 220;
    if (freq > 880) freq = 880;
    return freq;
}

static void set_pwm_frequency(int freq) {
    gpioSetPWMfrequency(PWM_PIN, freq);
    gpioPWM(PWM_PIN, PWM_RANGE / 2);
}

static void log_frequency(int freq) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char s[64];
        strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(fp, "%s, Frequency: %d Hz\n", s, freq);
        fclose(fp);
    }
}

static void handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes > 0) {
        buffer[bytes] = '\0';
        if (strncmp(buffer, MOTION_DETECTED_PREFIX, strlen(MOTION_DETECTED_PREFIX)) == 0) {
            char *secret = strstr(buffer, SHARED_SECRET);
            if (secret) {
                printf("Motion detected! Playing theremin for %d seconds.\n", PLAYBACK_DURATION);
                uint8_t touch_data[12];
                int elapsed = 0;
                while (elapsed < PLAYBACK_DURATION && running) {
                    if (read_touch_data(touch_data) == 12) {
                        int freq = calculate_frequency(touch_data);
                        set_pwm_frequency(freq);
                        log_frequency(freq);
                    }
                    gpioDelay(SAMPLE_INTERVAL_US);
                    elapsed++;
                }
                gpioPWM(PWM_PIN, 0);
            }
        }
    }
    close(client_socket);
    client_fd = -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_mpr121() < 0) {
        fprintf(stderr, "Failed to initialize MPR121\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d...\n", PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (running) perror("accept");
            continue;
        }
        handle_client(client_fd);
    }

    printf("\nShutting down...\n");
    gpioPWM(PWM_PIN, 0);
    if (client_fd >= 0) close(client_fd);
    if (server_fd >= 0) close(server_fd);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

