#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define LSM303DLHC_ADDR 0x1E

#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08

#define LED_PIN 17
#define PWM_PERIOD_NS 10000000
#define PWM_DUTY_MAX 1000000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s (errno: %s)\n", ts, msg, strerror(errno));
    if (log_file) {
        fprintf(log_file, "[%s] ERROR: %s (errno: %s)\n", ts, msg, strerror(errno));
        fflush(log_file);
    }
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int init_magnetometer(int fd) {
    if (i2c_write_reg8(fd, CTRL_REG1_M, 0x18) < 0) {
        log_error("Failed to write CTRL_REG1_M");
        return -1;
    }
    return 0;
}

static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_L_M, buf, 6) < 0) {
        log_error("Failed to read magnetometer data");
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 100) brightness = 100;
    int duty = (int)((long)brightness * PWM_DUTY_MAX / 100);
    if (gpiod_line_set_value(led_line, 1) < 0) return;
    usleep(duty);
    if (gpiod_line_set_value(led_line, 0) < 0) return;
    usleep(PWM_PERIOD_NS - duty);
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_file) fclose(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen("magnetometer.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        fclose(log_file);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303DLHC_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        cleanup();
        return 1;
    }

    if (init_magnetometer(i2c_fd) < 0) {
        log_error("Magnetometer initialization failed");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_error("Failed to open gpiochip0");
        cleanup();
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        log_error("Failed to get GPIO17 line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "magnetometer_led", 0) < 0) {
        log_error("Failed to request GPIO17 as output");
        cleanup();
        return 1;
    }

    printf("Magnetometer and LED initialized. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t x, y, z;
        if (read_magnetometer(i2c_fd, &x, &y, &z) == 0) {
            float magnitude = sqrtf((float)x * x + (float)y * y + (float)z * z);
            int brightness = (int)(magnitude / 100.0f * 100.0f);
            if (brightness > 100) brightness = 100;
            if (brightness < 0) brightness = 0;
            set_led_brightness(brightness);
        }
        usleep(100000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

