#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define REG_CONFIG_A  0x00
#define REG_CONFIG_B  0x01
#define REG_MODE      0x02
#define REG_DATA_X_MSB 0x03
#define REG_DATA_Z_MSB 0x05
#define REG_DATA_Y_MSB 0x07

#define NUM_SAMPLES 100
#define SAMPLE_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %d\n", value, reg, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int rc = i2cReadI2CBlockData(i2c_handle, REG_DATA_X_MSB, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading magnetometer data block: %d\n", rc);
        return -1;
    }
    *x = (int16_t)(((uint8_t)buffer[0] << 8) | (uint8_t)buffer[1]);
    *z = (int16_t)(((uint8_t)buffer[2] << 8) | (uint8_t)buffer[3]);
    *y = (int16_t)(((uint8_t)buffer[4] << 8) | (uint8_t)buffer[5]);
    return 0;
}

static int init_hmc5883l(void) {
    if (write_reg(REG_CONFIG_A, 0x70) < 0) return -1;
    if (write_reg(REG_CONFIG_B, 0x20) < 0) return -1;
    if (write_reg(REG_MODE, 0x00) < 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n", HMC5883L_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int16_t x_raw, y_raw, z_raw;
    int16_t x_offset = 0, y_offset = 0, z_offset = 0;
    int sample_count = 0;

    while (running) {
        if (read_magnetometer(&x_raw, &y_raw, &z_raw) == 0) {
            x_offset += x_raw;
            y_offset += y_raw;
            z_offset += z_raw;
            sample_count++;

            if (sample_count > NUM_SAMPLES) {
                x_offset -= x_raw;
                y_offset -= y_raw;
                z_offset -= z_raw;
                sample_count = NUM_SAMPLES;
            }

            int16_t x_corr = x_raw - (sample_count > 0 ? x_offset / sample_count : 0);
            int16_t y_corr = y_raw - (sample_count > 0 ? y_offset / sample_count : 0);
            int16_t z_corr = z_raw - (sample_count > 0 ? z_offset / sample_count : 0);

            printf("X: %d, Y: %d, Z: %d\n", x_corr, y_corr, z_corr);
            fflush(stdout);
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

