/*
 * LSM303D accelerometer monitor with GPIO interrupt trigger dump.
 *
 * Board:  Raspberry Pi Zero W
 * I2C:    /dev/i2c-1, LSM303D at 0x1D (SA0 high)
 * INT1:   GPIO23 (BCM 23, physical pin 16) via libgpiod
 *
 * Build:  gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- LSM303D constants (verified against datasheet) ---- */
#define LSM303D_ADDR        0x1D
#define LSM303D_WHO_AM_I    0x0F
#define LSM303D_WHO_AM_I_VAL 0x49

#define LSM303D_CTRL_REG1   0x20
#define LSM303D_CTRL_REG4   0x23
#define LSM303D_INT1_CFG    0x30
#define LSM303D_INT1_THS    0x32
#define LSM303D_INT1_DURATION 0x33
#define LSM303D_INT1_SRC    0x34
#define LSM303D_OUT_X_L_A   0x28

/* CTRL_REG1: 50 Hz ODR, XYZ axes enabled -> 0x57 */
#define CTRL_REG1_VAL       0x57
/* CTRL_REG4: full-scale +-2g, high-resolution off -> 0x00 */
#define CTRL_REG4_VAL       0x00
/* INT1_CFG: any-axis-high event (0x2A) */
#define INT1_CFG_VAL        0x2A
/* INT1_THS: 2000 mg -> 2000 / 16 = 125 -> 0x7D */
#define INT1_THS_VAL        0x7D
/* INT1_DURATION: immediate */
#define INT1_DURATION_VAL   0x00

/* ---- GPIO / libgpiod constants ---- */
#define GPIO_CHIP_NAME      "gpiochip4"   /* BCM GPIO on Pi Zero W */
#define INT1_LINE_OFFSET    23            /* BCM 23 */

/* ---- Circular buffer ---- */
#define BUF_SIZE 64
typedef struct {
    int16_t x, y, z;
} accel_sample_t;

static accel_sample_t accel_buf[BUF_SIZE];
static volatile int   buf_head = 0;   /* next write slot */
static volatile int   buf_count = 0; /* valid entries */

/* ---- Globals for cleanup ---- */
static int            i2c_fd = -1;
static struct gpiod_chip  *gpio_chip = NULL;
static struct gpiod_line  *int1_line = NULL;
static volatile sig_atomic_t running = 1;

/* ---- I2C helpers ---- */
static int i2c_read_byte(int fd, uint8_t reg)
{
    int v = i2c_smbus_read_byte_data(fd, reg);
    if (v < 0)
        fprintf(stderr, "I2C read 0x%02X failed: %s\n", reg, strerror(errno));
    return v;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    if (i2c_smbus_write_byte_data(fd, reg, val) < 0) {
        fprintf(stderr, "I2C write 0x%02X <- 0x%02X failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len)
{
    /* Set MSB of register address for auto-increment */
    uint8_t reg_addr = reg | 0x80;
    if (i2c_smbus_read_i2c_block_data(fd, reg_addr, len, buf) != len) {
        fprintf(stderr, "I2C block read 0x%02X (%d bytes) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Accelerometer ---- */
static int accel_init(int fd)
{
    int who = i2c_read_byte(fd, LSM303D_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Cannot read WHO_AM_I\n");
        return -1;
    }
    if (who != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LSM303D_WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_byte(fd, LSM303D_CTRL_REG1, CTRL_REG1_VAL) < 0)
        return -1;
    if (i2c_write_byte(fd, LSM303D_CTRL_REG4, CTRL_REG4_VAL) < 0)
        return -1;
    if (i2c_write_byte(fd, LSM303D_INT1_CFG, INT1_CFG_VAL) < 0)
        return -1;
    if (i2c_write_byte(fd, LSM303D_INT1_THS, INT1_THS_VAL) < 0)
        return -1;
    if (i2c_write_byte(fd, LSM303D_INT1_DURATION, INT1_DURATION_VAL) < 0)
        return -1;

    return 0;
}

static int accel_read(int fd, accel_sample_t *s)
{
    uint8_t raw[6];
    if (i2c_read_block(fd, LSM303D_OUT_X_L_A, raw, 6) < 0)
        return -1;

    s->x = (int16_t)((raw[1] << 8) | raw[0]);
    s->y = (int16_t)((raw[3] << 8) | raw[2]);
    s->z = (int16_t)((raw[5] << 8) | raw[4]);
    return 0;
}

static void accel_disable(int fd)
{
    (void)i2c_write_byte(fd, LSM303D_CTRL_REG1, 0x00);
}

/* ---- Circular buffer ---- */
static void buf_push(accel_sample_t s)
{
    accel_buf[buf_head] = s;
    buf_head = (buf_head + 1) % BUF_SIZE;
    if (buf_count < BUF_SIZE)
        buf_count++;
}

static void buf_dump_last_n(int n)
{
    if (n > buf_count)
        n = buf_count;
    int start = (buf_head - n + BUF_SIZE) % BUF_SIZE;
    printf("--- Last %d samples ---\n", n);
    for (int i = 0; i < n; i++) {
        int idx = (start + i) % BUF_SIZE;
        printf("  [%3d] X=%6d Y=%6d Z=%6d\n",
               idx, accel_buf[idx].x, accel_buf[idx].y, accel_buf[idx].z);
    }
    fflush(stdout);
}

/* ---- GPIO interrupt (libgpiod) ---- */
static void int1_isr(struct gpiod_line *line, void *userdata)
{
    (void)line;
    (void)userdata;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    printf("INT1 rising edge at %ld.%09ld\n",
           (long)ts.tv_sec, (long)ts.tv_nsec);
    buf_dump_last_n(10);
}

/* ---- Signal handler ---- */
static void on_sigint(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (i2c_fd >= 0) {
        accel_disable(i2c_fd);
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (int1_line) {
        gpiod_line_release(int1_line);
        int1_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
}

/* ---- Main ---- */
int main(void)
{
    /* Open I2C bus */
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open /dev/i2c-1 failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                LSM303D_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize accelerometer */
    if (accel_init(i2c_fd) < 0) {
        fprintf(stderr, "Accelerometer init failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request INT1 line */
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!gpio_chip) {
        fprintf(stderr, "gpiod_chip_open(%s) failed: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    int1_line = gpiod_chip_get_line(gpio_chip, INT1_LINE_OFFSET);
    if (!int1_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                INT1_LINE_OFFSET, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_rising_edge_events(int1_line, "lsm303d_mon") < 0) {
        fprintf(stderr, "gpiod_line_request_rising_edge_events failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM303D monitor running. Press Ctrl-C to exit.\n");
    fflush(stdout);

    /* Main loop */
    while (running) {
        accel_sample_t s;
        if (accel_read(i2c_fd, &s) == 0) {
            buf_push(s);
        } else {
            fprintf(stderr, "Accelerometer read failed; skipping sample\n");
        }

        /* Poll for GPIO events with 10 ms timeout */
        struct timespec ts = { 0, 10 * 1000 * 1000 }; /* 10 ms */
        int ev = gpiod_line_event_wait(int1_line, &ts);
        if (ev < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n",
                    strerror(errno));
        } else if (ev > 0) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(int1_line, &event) == 0) {
                if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE)
                    int1_isr(int1_line, NULL);
            }
        }

        usleep(10 * 1000); /* 10 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

