#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define SERIAL_PORT1 "/dev/serial0"
#define SERIAL_PORT2 "/dev/serial1"
#define BAUD_RATE 9600
#define EXPECTED_CODE "123456"
#define CODE_LENGTH 6
#define UNLOCK_DURATION_MS 2000
#define TIMEOUT_MS 5000
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int serial_handle1 = -1;
static int serial_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_code(int serial_handle, char *code, int max_len) {
    char ch;
    int idx = 0;
    uint32_t start_tick = gpioTick();

    while (idx < max_len) {
        int avail = serDataAvailable(serial_handle);
        if (avail < 0) {
            fprintf(stderr, "Error checking serial data availability: %s\n", strerror(errno));
            return -1;
        }
        if (avail > 0) {
            int n = serRead(serial_handle, &ch, 1);
            if (n < 0) {
                fprintf(stderr, "Error reading from serial port: %s\n", strerror(errno));
                return -1;
            }
            if (ch >= '0' && ch <= '9') {
                code[idx++] = ch;
            } else {
                idx = 0;
            }
            start_tick = gpioTick();
        } else {
            if ((gpioTick() - start_tick) / 1000 >= TIMEOUT_MS) {
                return 0;
            }
            gpioDelay(POLL_DELAY_US);
        }
    }
    code[idx] = '\0';
    return 1;
}

static int unlock_doors(void) {
    if (gpioWrite(LOCK1_GPIO, 1) < 0) {
        fprintf(stderr, "Error unlocking door 1 (GPIO %d): %s\n", LOCK1_GPIO, strerror(errno));
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 1) < 0) {
        fprintf(stderr, "Error unlocking door 2 (GPIO %d): %s\n", LOCK2_GPIO, strerror(errno));
        gpioWrite(LOCK1_GPIO, 0);
        return -1;
    }
    printf("Doors unlocked for %d ms\n", UNLOCK_DURATION_MS);
    gpioDelay(UNLOCK_DURATION_MS * 1000);
    if (gpioWrite(LOCK1_GPIO, 0) < 0) {
        fprintf(stderr, "Error locking door 1 (GPIO %d): %s\n", LOCK1_GPIO, strerror(errno));
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 0) < 0) {
        fprintf(stderr, "Error locking door 2 (GPIO %d): %s\n", LOCK2_GPIO, strerror(errno));
        return -1;
    }
    printf("Doors locked\n");
    return 0;
}

static int constant_time_compare(const char *a, const char *b, size_t len) {
    unsigned char result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= (unsigned char)(a[i] ^ b[i]);
    }
    return (result == 0) ? 1 : 0;
}

static void cleanup(void) {
    if (serial_handle1 >= 0) {
        serClose(serial_handle1);
        serial_handle1 = -1;
    }
    if (serial_handle2 >= 0) {
        serClose(serial_handle2);
        serial_handle2 = -1;
    }
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LOCK1_GPIO, PI_OUTPUT) < 0 || gpioSetMode(LOCK2_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO modes: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(LOCK1_GPIO, 0) < 0 || gpioWrite(LOCK2_GPIO, 0) < 0) {
        fprintf(stderr, "Error initializing locks to locked state: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    serial_handle1 = serOpen(SERIAL_PORT1, BAUD_RATE, 0);
    if (serial_handle1 < 0) {
        fprintf(stderr, "Error opening serial port %s: %s\n", SERIAL_PORT1, strerror(errno));
        gpioTerminate();
        return 1;
    }

    serial_handle2 = serOpen(SERIAL_PORT2, BAUD_RATE, 0);
    if (serial_handle2 < 0) {
        fprintf(stderr, "Error opening serial port %s: %s\n", SERIAL_PORT2, strerror(errno));
        serClose(serial_handle1);
        gpioTerminate();
        return 1;
    }

    printf("Dual-factor authentication system started. Enter code on both serial ports.\n");

    while (running) {
        char code1[CODE_LENGTH + 1] = {0};
        char code2[CODE_LENGTH + 1] = {0};

        int rc1 = read_code(serial_handle1, code1, CODE_LENGTH);
        int rc2 = read_code(serial_handle2, code2, CODE_LENGTH);

        if (rc1 == 1 && rc2 == 1) {
            printf("Code received: %s (port 1), %s (port 2)\n", code1, code2);
            if (constant_time_compare(code1, code2, CODE_LENGTH) &&
                constant_time_compare(code1, EXPECTED_CODE, CODE_LENGTH)) {
                printf("Codes match. Unlocking doors...\n");
                if (unlock_doors() < 0) {
                    fprintf(stderr, "Error unlocking doors\n");
                }
            } else {
                printf("Codes do not match. Locks remain locked.\n");
            }
        } else if (rc1 == 0 || rc2 == 0) {
            if (rc1 == 0) {
                fprintf(stderr, "Timeout on port 1. Resetting input buffer.\n");
                serFlush(serial_handle1);
            }
            if (rc2 == 0) {
                fprintf(stderr, "Timeout on port 2. Resetting input buffer.\n");
                serFlush(serial_handle2);
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

