#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define RELAY_COUNT 4
#define ACTIVATION_DURATION 300   /* seconds */
#define PAUSE_DURATION      60    /* seconds */
#define TIMER_INTERVAL      60    /* seconds */

static const int relay_pins[RELAY_COUNT] = {
    RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN
};

/* Active-LOW relay module: LOW = ON, HIGH = OFF */
#define RELAY_ON  0
#define RELAY_OFF 1

/* State machine actions */
typedef enum {
    ACTION_NONE,
    ACTION_ACTIVATE,
    ACTION_DEACTIVATE,
    ACTION_PAUSE
} action_t;

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_timer_fired = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; no async-unsafe syslog calls here   */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timer callback — fires every TIMER_INTERVAL seconds                */
/* ------------------------------------------------------------------ */
static void timer_callback(int timer_id, void *user_data)
{
    (void)timer_id;
    (void)user_data;
    g_timer_fired = 1;
}

/* ------------------------------------------------------------------ */
/* Log a relay state change with a human-readable timestamp            */
/* ------------------------------------------------------------------ */
static void log_relay_state(int pin, int state)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }

    syslog(LOG_INFO, "Relay on GPIO %d %s (state=%d)",
           pin, state == RELAY_ON ? "activated" : "deactivated", state);
}

/* ------------------------------------------------------------------ */
/* Safely set a relay pin to the given state                           */
/* ------------------------------------------------------------------ */
static int safe_relay_write(int pin, int state)
{
    if (gpioWrite(pin, state) != 0) {
        syslog(LOG_ERR, "gpioWrite(pin=%d, state=%d) failed", pin, state);
        return -1;
    }
    log_relay_state(pin, state);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Deactivate all relays (set HIGH = OFF)                              */
/* ------------------------------------------------------------------ */
static void deactivate_all_relays(void)
{
    for (int i = 0; i < RELAY_COUNT; i++) {
        (void)safe_relay_write(relay_pins[i], RELAY_OFF);
    }
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure all relay pins as outputs           */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    for (int i = 0; i < RELAY_COUNT; i++) {
        int pin = relay_pins[i];
        if (gpioSetMode(pin, PI_OUTPUT) != 0) {
            syslog(LOG_ERR, "gpioSetMode(pin=%d, PI_OUTPUT) failed", pin);
            gpioTerminate();
            return -1;
        }
        /* Start with relay OFF (HIGH for active-LOW module) */
        if (safe_relay_write(pin, RELAY_OFF) != 0) {
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed; exiting");
        closelog();
        return EXIT_FAILURE;
    }

    /* Register a single timer that fires every TIMER_INTERVAL seconds */
    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL, timer_callback, NULL) != 0) {
        syslog(LOG_ERR, "gpioSetTimerFuncEx failed");
        deactivate_all_relays();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Irrigation system started (timer every %d s)",
           TIMER_INTERVAL);

    /*
     * State machine:
     *   0 = idle, waiting for first timer fire
     *   1 = activating relay N
     *   2 = deactivating relay N
     *   3 = pausing
     */
    int state = 0;
    int relay_index = 0;
    int elapsed = 0;

    while (g_running) {
        if (g_timer_fired) {
            g_timer_fired = 0;

            switch (state) {
            case 0:
                /* Start activation of relay 0 */
                state = ACTION_ACTIVATE;
                relay_index = 0;
                elapsed = 0;
                syslog(LOG_INFO, "Starting relay sequence: relay %d",
                       relay_index + 1);
                break;

            case ACTION_ACTIVATE:
                if (safe_relay_write(relay_pins[relay_index], RELAY_ON) != 0) {
                    syslog(LOG_ERR, "Activation failed for relay %d",
                           relay_index + 1);
                    state = 0;
                    break;
                }
                state = ACTION_DEACTIVATE;
                elapsed = 0;
                break;

            case ACTION_DEACTIVATE:
                if (safe_relay_write(relay_pins[relay_index], RELAY_OFF) != 0) {
                    syslog(LOG_ERR, "Deactivation failed for relay %d",
                           relay_index + 1);
                    state = 0;
                    break;
                }
                elapsed = 0;
                state = ACTION_PAUSE;
                break;

            case ACTION_PAUSE:
                relay_index = (relay_index + 1) % RELAY_COUNT;
                if (relay_index == 0) {
                    /* Full cycle complete — reset to idle */
                    state = 0;
                } else {
                    state = ACTION_ACTIVATE;
                }
                break;

            default:
                state = 0;
                break;
            }
        }

        /*
         * Track elapsed time for activation/deactivation phases so we
         * can enforce the 300 s / 60 s cycle without blocking the
         * timer callback thread.
         */
        if (state == ACTION_ACTIVATE || state == ACTION_DEACTIVATE) {
            elapsed += TIMER_INTERVAL;
            if (elapsed >= (state == ACTION_ACTIVATE
                            ? ACTIVATION_DURATION
                            : PAUSE_DURATION)) {
                state = (state == ACTION_ACTIVATE)
                    ? ACTION_DEACTIVATE
                    : ACTION_PAUSE;
                elapsed = 0;
            }
        }

        sleep(1);
    }

    /* ---- Cleanup ---- */
    syslog(LOG_INFO, "Shutting down irrigation system");
    deactivate_all_relays();
    gpioSetTimerFuncEx(0, TIMER_INTERVAL, NULL, NULL);   /* unregister timer */
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

