#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define I2C_BUS "/dev/i2c-1"

#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B

#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_NS (1000000000L / SAMPLE_RATE_HZ)

typedef struct {
    float x;
    float y;
    float z;
} accel_data_t;

static accel_data_t accel_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int i2c_fd = -1;
static int sysfs_fd = -1;
static timer_t timer_id;
static volatile sig_atomic_t running = 1;

static void cleanup(void) {
    if (sysfs_fd >= 0) {
        close(sysfs_fd);
        sysfs_fd = -1;
    }
    if (timer_id) {
        timer_delete(timer_id);
        timer_id = 0;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read burst from 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg8(fd, ACCEL_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_accel(int fd, accel_data_t *out) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    out->x = (float)raw_x / 16384.0f;
    out->y = (float)raw_y / 16384.0f;
    out->z = (float)raw_z / 16384.0f;
    return 0;
}

static void timer_handler(int sig, siginfo_t *si, void *uc) {
    (void)sig; (void)si; (void)uc;
    accel_data_t data;
    if (read_accel(i2c_fd, &data) == 0) {
        accel_buffer[buffer_index] = data;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE) buffer_count++;
    }
}

static int create_sysfs(void) {
    const char *path = "/sys/kernel/mpu6050_accel";
    if (mkdir(path, 0755) == -1 && errno != EEXIST) {
        fprintf(stderr, "mkdir %s failed: %s\n", path, strerror(errno));
        return -1;
    }
    const char *latest = "/sys/kernel/mpu6050_accel/latest";
    if (symlink("/sys/kernel/mpu6050_accel/data", latest) == -1 && errno != EEXIST) {
        fprintf(stderr, "symlink failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int create_data_file(void) {
    const char *path = "/sys/kernel/mpu6050_accel/data";
    FILE *fp = fopen(path, "w+");
    if (!fp) {
        fprintf(stderr, "fopen %s failed: %s\n", path, strerror(errno));
        return -1;
    }
    fclose(fp);
    return 0;
}

static int write_data_to_sysfs(const accel_data_t *data) {
    const char *path = "/sys/kernel/mpu6050_accel/data";
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "fopen %s for write failed: %s\n", path, strerror(errno));
        return -1;
    }
    fprintf(fp, "%.4f,%.4f,%.4f\n", data->x, data->y, data->z);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", MPU6050_ADDR, strerror(errno));
        cleanup();
        return 1;
    }
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 init failed (sensor absent or bus error)\n");
        cleanup();
        return 1;
    }

    if (create_sysfs() < 0 || create_data_file() < 0) {
        cleanup();
        return 1;
    }

    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    if (timer_create(CLOCK_MONOTONIC, &sev, &timer_id) < 0) {
        perror("timer_create");
        cleanup();
        return 1;
    }

    struct itimerspec its;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = SAMPLE_PERIOD_NS;
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = SAMPLE_PERIOD_NS;
    if (timer_settime(timer_id, 0, &its, NULL) < 0) {
        perror("timer_settime");
        cleanup();
        return 1;
    }

    struct sigaction sa_timer;
    memset(&sa_timer, 0, sizeof(sa_timer));
    sa_timer.sa_sigaction = (void (*)(int, siginfo_t *, void *))timer_handler;
    sigemptyset(&sa_timer.sa_mask);
    sa_timer.sa_flags = SA_SIGINFO;
    if (sigaction(SIGRTMIN, &sa_timer, NULL) < 0) {
        perror("sigaction SIGRTMIN");
        cleanup();
        return 1;
    }

    printf("MPU6050 logging started. Press Ctrl+C to exit.\n");

    while (running) {
        pause();
        if (!running) break;
        if (buffer_count > 0) {
            int idx = (buffer_index - 1 + BUFFER_SIZE) % BUFFER_SIZE;
            if (write_data_to_sysfs(&accel_buffer[idx]) < 0) {
                fprintf(stderr, "Failed to write to sysfs\n");
            }
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

