#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define GPIO_CHIP_NAME "gpiochip0"

static const int relay_pins[NUM_RELAYS] = {18, 23, 24, 25};
static const int prime_intervals[NUM_RELAYS] = {2, 3, 5, 7};

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS];
static int lines_requested = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < lines_requested; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 0);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", relay_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(relay_lines[i], "smart-lighting", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", relay_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        lines_requested++;
    }

    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        long elapsed_seconds = current_time.tv_sec - start_time.tv_sec;

        for (int i = 0; i < NUM_RELAYS; i++) {
            if (elapsed_seconds % prime_intervals[i] == 0) {
                int current_value = gpiod_line_get_value(relay_lines[i]);
                if (current_value < 0) {
                    fprintf(stderr, "Failed to read GPIO line %d: %s\n", relay_pins[i], strerror(errno));
                    running = 0;
                    break;
                }
                int new_value = current_value == 0 ? 1 : 0;
                if (gpiod_line_set_value(relay_lines[i], new_value) < 0) {
                    fprintf(stderr, "Failed to set GPIO line %d to %d: %s\n", relay_pins[i], new_value, strerror(errno));
                    running = 0;
                    break;
                }
                printf("Relay on GPIO %d toggled to %d\n", relay_pins[i], new_value);
            }
        }

        struct timespec sleep_time = {0, 100000000};
        nanosleep(&sleep_time, NULL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

