#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// MPU-6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define WHO_AM_I 0x75
#define GYRO_XOUT_H 0x43

// Sensitivity scale factor for default +-250 dps range
#define GYRO_SCALE 131.0

// Circular buffer size
#define BUFFER_SIZE 100

// Angular velocity threshold (degrees/second)
#define THRESHOLD 50.0

// I2C device path for Raspberry Pi 3 Model B+
#define I2C_DEVICE "/dev/i2c-1"

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
    struct timespec timestamp;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
static int i2c_fd = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(circular_buffer_t *buffer, float x, float y, float z);
void check_threshold(float x, float y, float z);
void signal_handler(int signal);
void callback_function(float x, float y, float z);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Initialize the MPU-6050
int init_mpu6050() {
    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return -1;
    }

    // Acquire I2C bus access and set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Verify device identity
    uint8_t who_am_i = 0;
    if (read_gyro_data(&who_am_i, &who_am_i, &who_am_i) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    if (who_am_i != 0x68) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x68, got 0x%02X\n", who_am_i);
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep bit)
    uint8_t buf[2] = {PWR_MGMT_1, 0x00};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Allow time for sensor to stabilize
    usleep(100000); // 100ms

    return 0;
}

// Read gyroscope data from the MPU-6050
int read_gyro_data(float *x, float *y, float *z) {
    uint8_t reg = GYRO_XOUT_H;
    uint8_t data[6];

    // Write the register address to read from
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }

    // Read 6 bytes of data
    if (read(i2c_fd, data, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes, convert to degrees/second
    int16_t raw_x = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_y = (int16_t)((data[2] << 8) | data[3]);
    int16_t raw_z = (int16_t)((data[4] << 8) | data[5]);

    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, float x, float y, float z) {
    clock_gettime(CLOCK_MONOTONIC, &buffer->buffer[buffer->head].timestamp);
    buffer->buffer[buffer->head].x = x;
    buffer->buffer[buffer->head].y = y;
    buffer->buffer[buffer->head].z = z;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Check if the angular velocity exceeds the threshold
void check_threshold(float x, float y, float z) {
    float magnitude = sqrtf(x * x + y * y + z * z);
    if (magnitude > THRESHOLD) {
        callback_function(x, y, z);
    }
}

// Callback function to be called when the threshold is exceeded
void callback_function(float x, float y, float z) {
    printf("Threshold exceeded! Angular velocity: X=%.2f, Y=%.2f, Z=%.2f deg/s\n", x, y, z);
}

int main() {
    // Initialize the circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    // Set up signal handling for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Initialize the MPU-6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "Failed to initialize MPU-6050. Exiting.\n");
        return 1;
    }

    printf("MPU-6050 initialized successfully. Reading gyroscope data...\n");

    // Main loop
    while (program_running) {
        float x, y, z;

        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Add data to the circular buffer
            add_to_buffer(&gyro_buffer, x, y, z);

            // Check if the threshold is exceeded
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data. Retrying...\n");
        }

        // Delay for 10 milliseconds
        usleep(10000);
    }

    // Clean up and exit
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    printf("\nExiting gracefully.\n");
    return 0;
}

