#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define READ_INTERVAL_SEC 5
#define READ_TIMEOUT_SEC 1
#define READ_RETRY_DELAY_US 100000
#define READ_RESPONSE_LEN 9
#define READ_CMD_LEN 9

static int uart_handle = -1;
static FILE *log_file = NULL;
static FILE *error_file = NULL;
static volatile sig_atomic_t terminate = 0;

static const unsigned char read_cmd[READ_CMD_LEN] = {
    0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79
};

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_error(const char *message) {
    if (!error_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(error_file, "%s: %s\n", ts, message);
    fflush(error_file);
}

static int init_uart(void) {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        log_error("Failed to open UART");
        return -1;
    }
    return 0;
}

static int read_co2(int *co2_ppm, int *error_flag) {
    unsigned char response[READ_RESPONSE_LEN];
    int bytes_read = 0;
    int elapsed = 0;

    *co2_ppm = -1;
    *error_flag = 0;

    if (serWrite(uart_handle, (char *)read_cmd, READ_CMD_LEN) != READ_CMD_LEN) {
        log_error("Failed to write read command to UART");
        *error_flag = 1;
        return -1;
    }

    gpioDelay(READ_RETRY_DELAY_US);

    while (bytes_read < READ_RESPONSE_LEN && elapsed < READ_TIMEOUT_SEC) {
        int available = serDataAvailable(uart_handle);
        if (available < 0) {
            log_error("serDataAvailable failed");
            *error_flag = 1;
            return -1;
        }
        if (available > 0) {
            int to_read = (available < (READ_RESPONSE_LEN - bytes_read))
                          ? available : (READ_RESPONSE_LEN - bytes_read);
            int n = serRead(uart_handle, (char *)(response + bytes_read), to_read);
            if (n < 0) {
                log_error("serRead failed");
                *error_flag = 1;
                return -1;
