#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define REG_CONFIG_A 0x00
#define REG_CONFIG_B 0x01
#define REG_MODE 0x02
#define REG_DATA 0x03
#define GPIO_PIN 17
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_US 100000
#define I2C_BUS 1

#define TARGET_HEADING 90.0
#define HEADING_THRESHOLD 10.0

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x;
    float y;
} HeadingData;

static HeadingData heading_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int16_t x_offset = 100;
static int16_t y_offset = -50;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_hmc5883l(void) {
    if (i2cWriteByteData(i2c_handle, REG_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing CONFIG_A\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing CONFIG_B\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing MODE\n");
        return -1;
    }
    return 0;
}

static int read_hmc5883l(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, REG_DATA, buf, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2f((float)y, (float)x) * 180.0f / M_PI;
    if (heading < 0.0f) heading += 360.0f;
    return heading;
}

static void add_to_buffer(float heading) {
    heading_buffer[buffer_index].x = heading;
    heading_buffer[buffer_index].y = 0.0f;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void control_gpio(float heading) {
    float deviation = fabsf(heading - TARGET_HEADING);
    if (deviation > 180.0f) deviation = 360.0f - deviation;
    gpioWrite(GPIO_PIN, (deviation > HEADING_THRESHOLD) ? 1 : 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_hmc5883l() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int16_t x, y, z;
    float heading;

    while (!terminate) {
        if (read_hmc5883l(&x, &y, &z) == 0) {
            x -= x_offset;
            y -= y_offset;
            heading = calculate_heading(x, y);
            add_to_buffer(heading);
            control_gpio(heading);
        } else {
            fprintf(stderr, "I2C read error, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(GPIO_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

