#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define RED_RELAY_PIN   17
#define GREEN_RELAY_PIN 27
#define BLUE_RELAY_PIN  22
#define BH1750_ADDR     0x23
#define I2C_BUS         "/dev/i2c-1"
#define LOG_FILE        "lighting_log.txt"
#define BH1750_CONV_MS  120
#define POLL_INTERVAL_S 1

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bh1750_write(int fd, unsigned char cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "BH1750 write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_read(int fd, unsigned short *lux) {
    unsigned char buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "BH1750 read failed: %s\n", strerror(errno));
        return -1;
    }
    *lux = ((unsigned short)buf[0] << 8) | buf[1];
    return 0;
}

static void log_data(FILE *fp, int lux, int r, int g, int b) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Lux: %d, Red: %d, Green: %d, Blue: %d\n", ts, lux, r, g, b);
    fflush(fp);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red = NULL, *green = NULL, *blue = NULL;
    int i2c_fd = -1;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    red = gpiod_chip_get_line(chip, RED_RELAY_PIN);
    green = gpiod_chip_get_line(chip, GREEN_RELAY_PIN);
    blue = gpiod_chip_get_line(chip, BLUE_RELAY_PIN);
    if (!red || !green || !blue) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(red, "smart_light", 0) < 0 ||
        gpiod_line_request_output(green, "smart_light", 0) < 0 ||
        gpiod_line_request_output(blue, "smart_light", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c bus");
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        goto cleanup;
    }

    if (bh1750_write(i2c_fd, 0x10) < 0) {
        fprintf(stderr, "Failed to set BH1750 continuous high-res mode\n");
        goto cleanup;
    }
    usleep(BH1750_CONV_MS * 1000);

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        goto cleanup;
    }

    printf("Smart lighting system started. Press Ctrl+C to exit.\n");

    while (running) {
        unsigned short lux = 0;
        if (bh1750_read(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            sleep(POLL_INTERVAL_S);
            continue;
        }

        int r_val = 0, g_val = 0, b_val = 0;
        if (lux < 50) {
            r_val = 1;
        } else if (lux < 150) {
            g_val = 1;
        } else if (lux < 300) {
            b_val = 1;
        } else {
            r_val = g_val = b_val = 1;
        }

        if (gpiod_line_set_value(red, r_val) < 0 ||
            gpiod_line_set_value(green, g_val) < 0 ||
            gpiod_line_set_value(blue, b_val) < 0) {
            perror("gpiod_line_set_value");
        }

        log_data(log_fp, (int)lux, r_val, g_val, b_val);
        sleep(POLL_INTERVAL_S);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (red) gpiod_line_release(red);
    if (green) gpiod_line_release(green);
    if (blue) gpiod_line_release(blue);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_fp) fclose(log_fp);
    return ret;
}

