#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255

#define DISTANCE_THRESHOLD 50
#define MIN_DISTANCE 10
#define MAX_DISTANCE 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor_direction(int in1, int in2, int in3, int in4, int distance) {
    int duty = 0;
    if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
        duty = (int)(((float)(MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE)) * PWM_RANGE);
        if (duty < 0) duty = 0;
        if (duty > PWM_RANGE) duty = PWM_RANGE;
    }

    if (distance < DISTANCE_THRESHOLD) {
        if (gpioWrite(in1, 1) < 0) return -1;
        if (gpioWrite(in3, 1) < 0) return -1;
        if (gpioPWM(in2, duty) < 0) return -1;
        if (gpioPWM(in4, duty) < 0) return -1;
    } else {
        if (gpioWrite(in1, 0) < 0) return -1;
        if (gpioWrite(in3, 0) < 0) return -1;
        if (gpioPWM(in2, duty) < 0) return -1;
        if (gpioPWM(in4, duty) < 0) return -1;
    }
    return 0;
}

static int control_motors(int distance_a, int distance_b) {
    if (set_motor_direction(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, distance_a) < 0) {
        fprintf(stderr, "Error setting motor A direction\n");
        return -1;
    }
    if (set_motor_direction(MOTOR_B_IN3, MOTOR_B_IN4, MOTOR_A_IN1, MOTOR_A_IN2, distance_b) < 0) {
        fprintf(stderr, "Error setting motor B direction\n");
        return -1;
    }
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_A_IN1);
        return -1;
    }
    if (gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_A_IN2);
        return -1;
    }
    if (gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_B_IN3);
        return -1;
    }
    if (gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_B_IN4);
        return -1;
    }

    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", MOTOR_A_IN2);
        return -1;
    }
    if (gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", MOTOR_B_IN4);
        return -1;
    }

    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", MOTOR_A_IN2);
        return -1;
    }
    if (gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", MOTOR_B_IN4);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);
    gpioPWM(MOTOR_A_IN2, 0);
    gpioPWM(MOTOR_B_IN4, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (initialize_gpio() < 0) {
        return 1;
    }

    int distance_a = 50;
    int distance_b = 50;

    while (running) {
        if (control_motors(distance_a, distance_b) < 0) {
            fprintf(stderr, "Motor control failed, exiting\n");
            break;
        }
        usleep(100000);
    }

    cleanup_gpio();
    return 0;
}

