#define IN1 17
#define IN2 18
#define IN3 27
#define IN4 22
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23
#define STEPS_PER_REV 512
#define STEP_DELAY_US 2000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void deenergize(void) {
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
}

static void step_cw(void) {
    gpioWrite(IN1, 1); gpioWrite(IN2, 0); gpioWrite(IN3, 0); gpioWrite(IN4, 0);
    gpioDelay(STEP_DELAY_US);
    gpioWrite(IN1, 0); gpioWrite(IN2, 1); gpioWrite(IN3, 0); gpioWrite(IN4, 0);
    gpioDelay(STEP_DELAY_US);
    gpioWrite(IN1, 0); gpioWrite(IN2, 0); gpioWrite(IN3, 1); gpioWrite(IN4, 0);
    gpioDelay(STEP_DELAY_US);
    gpioWrite(IN1, 0); gpioWrite(IN2, 0); gpioWrite(IN3, 0); gpioWrite(IN4, 1);
    gpioDelay(STEP_DELAY_US);
}

static void step_ccw(void) {
    gpioWrite(IN1, 0); gpioWrite(IN2, 0); gpioWrite(IN3, 0); gpioWrite(IN4, 1);
    gpioDelay(STEP_DELAY_US);
    gpioWrite(IN1, 0); gpioWrite(IN2, 0); gpioWrite(IN3, 1); gpioWrite(IN4, 0);
    gpioDelay(STEP_DELAY_US);
    gpioWrite(IN1, 0); gpioWrite(IN2, 1); gpioWrite(IN3, 0); gpioWrite(IN4, 0);
    gpioDelay(STEP_DELAY_US);
    gpioWrite(IN1, 1); gpioWrite(IN2, 0); gpioWrite(IN3, 0); gpioWrite(IN4, 0);
    gpioDelay(STEP_DELAY_US);
}

static void rotate(int steps, void (*dir)(void)) {
    for (int i = 0; i < steps && running; i++) {
        dir();
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int pins[] = {IN1, IN2, IN3, IN4, LOCK_BUTTON, UNLOCK_BUTTON};
    for (int i = 0; i < 6; i++) {
        if (gpioSetMode(pins[i], i < 4 ? PI_OUTPUT : PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set mode for GPIO %d\n", pins[i]);
            deenergize();
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on buttons\n");
        deenergize();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    deenergize();

    printf("Automatic door lock simulation started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            printf("Locking...\n");
            rotate(STEPS_PER_REV, step_cw);
            if (running) printf("Locked.\n");
            while (gpioRead(LOCK_BUTTON) == 0 && running) {
                gpioDelay(10000);
            }
        }
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            printf("Unlocking...\n");
            rotate(STEPS_PER_REV, step_ccw);
            if (running) printf("Unlocked.\n");
            while (gpioRead(UNLOCK_BUTTON) == 0 && running) {
                gpioDelay(10000);
            }
        }
        gpioDelay(10000);
    }

    deenergize();
    gpioTerminate();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

