#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define FADE_DURATION 1800
#define SCHEDULE_FILE "lighting_schedule.txt"

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};
static volatile sig_atomic_t running = 1;

typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int state;
} schedule_entry;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_schedule(const char *filename, schedule_entry *entries, int max_entries) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening schedule file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    int count = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp) && count < max_entries) {
        int hour, minute, second, relay_number, state;
        if (sscanf(line, "%d:%d:%d,%d,%d", &hour, &minute, &second, &relay_number, &state) == 5) {
            if (hour < 0 || hour > 23 || minute < 0 || minute > 59 || second < 0 || second > 59 ||
                relay_number < 1 || relay_number > NUM_RELAYS || (state != 0 && state != 1)) {
                fprintf(stderr, "Invalid schedule entry (line %d): %s", count + 1, line);
                continue;
            }
            entries[count].hour = hour;
            entries[count].minute = minute;
            entries[count].second = second;
            entries[count].relay_number = relay_number;
            entries[count].state = state;
            count++;
        } else {
            fprintf(stderr, "Invalid format (line %d): %s", count + 1, line);
        }
    }

    fclose(fp);
    return count;
}

static int set_relay_state(int relay_number, int state) {
    if (relay_number < 1 || relay_number > NUM_RELAYS) {
        fprintf(stderr, "Invalid relay number: %d\n", relay_number);
        return -1;
    }
    if (gpioWrite(relay_pins[relay_number - 1], state) != 0) {
        fprintf(stderr, "Failed to write to relay %d (GPIO %d)\n", relay_number, relay_pins[relay_number - 1]);
        return -1;
    }
    return 0;
}

static int fade_lamp(int relay_number, int target_brightness, int duration_seconds) {
    int current_brightness = gpioGetPWMdutycycle(relay_pins[relay_number - 1]);
    if (current_brightness < 0) {
        fprintf(stderr, "Failed to read PWM duty cycle for relay %d\n", relay_number);
        return -1;
    }

    int step_delay_ms = 1000 / (duration_seconds * 10);
    if (step_delay_ms < 1) step_delay_ms = 1;

    int step_size = (target_brightness - current_brightness) / (duration_seconds * 10);
    if (step_size == 0) step_size = (target_brightness > current_brightness) ? 1 : -1;

    for (int i = 0; i < duration_seconds * 10 && running; i++) {
        current_brightness += step_size;
        if (current_brightness < 0) current_brightness = 0;
        if (current_brightness > PWM_RANGE) current_brightness = PWM_RANGE;

        if (gpioPWM(relay_pins[relay_number - 1], current_brightness) != 0) {
            fprintf(stderr, "Failed to set PWM for relay %d\n", relay_number);
            return -1;
        }
        gpioDelay(step_delay_ms * 1000);
    }

    if (gpioPWM(relay_pins[relay_number - 1], target_brightness) != 0) {
        fprintf(stderr, "Failed to set final PWM for relay %d\n", relay_number);
        return -1;
    }
    return 0;
}

static void cleanup_relays(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 0);
        gpioPWM(relay_pins[i], 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY) != 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(relay_pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        gpioPWM(relay_pins[i], 0);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        cleanup_relays();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    schedule_entry schedule[100];
    int num_entries = read_schedule(SCHEDULE_FILE, schedule, sizeof(schedule) / sizeof(schedule[0]));
    if (num_entries < 0) {
        cleanup_relays();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (num_entries == 0) {
        fprintf(stderr, "No valid schedule entries found. Exiting.\n");
        cleanup_relays();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Home Lighting System started. Press Ctrl+C to exit.\n");

    while (running) {
        time_t now = time(NULL);
        if (now == (time_t)-1) {
            fprintf(stderr, "Failed to get current time: %s\n", strerror(errno));
            gpioDelay(1000000);
            continue;
        }

        struct tm *local_time = localtime(&now);
        if (!local_time) {
            fprintf(stderr, "Failed to convert time: %s\n", strerror(errno));
            gpioDelay(1000000);
            continue;
        }

        for (int i = 0; i < num_entries; i++) {
            if (local_time->tm_hour == schedule[i].hour &&
                local_time->tm_min == schedule[i].minute &&
                local_time->tm_sec == schedule[i].second) {

                if (set_relay_state(schedule[i].relay_number, schedule[i].state) != 0) {
                    fprintf(stderr, "Failed to set relay %d to state %d\n",
                            schedule[i].relay_number, schedule[i].state);
                } else {
                    int target = (schedule[i].state == 1) ? PWM_RANGE : 0;
                    if (fade_lamp(schedule[i].relay_number, target, FADE_DURATION) != 0) {
                        fprintf(stderr, "Fade failed for relay %d\n", schedule[i].relay_number);
                    }
                }
            }
        }

        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    cleanup_relays();
    gpioTerminate();
    return EXIT_SUCCESS;
}

