#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  30.0f
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000   /* 30 ms */
#define LOOP_DELAY_US    20000   /* 20 ms -> ~50 Hz */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Read distance from HC-SR04 in centimetres.
 * Returns >= 0 on success, -1.0 on timeout, -2.0 on read error.
 */
static float read_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -2.0f;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -2.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -2.0f;
    }

    uint32_t start_tick = gpioTick();
    uint32_t timeout = start_tick + ECHO_TIMEOUT_US;

    /* Wait for echo rising edge */
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout) >= 0) {
            fprintf(stderr, "Error: Echo pin stuck low (sensor absent or not responding)\n");
            return -1.0f;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout) >= 0) {
            fprintf(stderr, "Error: Echo pin stuck high (timeout)\n");
            return -1.0f;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_us = echo_end - echo_start;
    /* speed of sound 343 m/s -> 0.0343 cm/us; round trip -> /2 */
    return (float)pulse_us * 0.0343f / 2.0f;
}

static int map_distance_to_frequency(float distance)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    float ratio = (distance - MIN_DISTANCE_CM) /
                  (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    int freq = (int)(MIN_FREQUENCY_HZ +
                     ratio * (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ));
    return freq;
}

static void set_buzzer_frequency(int frequency)
{
    if (frequency < MIN_FREQUENCY_HZ) frequency = MIN_FREQUENCY_HZ;
    if (frequency > MAX_FREQUENCY_HZ) frequency = MAX_FREQUENCY_HZ;

    /* pigpio hardware PWM: 50 Hz base, 0-1000 duty cycle range */
    int duty = (int)((float)frequency / MAX_FREQUENCY_HZ * 1000.0f);
    if (gpioHardwarePWM(BUZZER_PIN, frequency, duty) < 0) {
        fprintf(stderr, "Error: gpioHardwarePWM failed for %d Hz\n", frequency);
    }
}

static void silence_buzzer(void)
{
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(buzzer) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = read_distance();

        if (distance < 0.0f) {
            /* Timeout or read error: silence buzzer for safety */
            silence_buzzer();
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int frequency = map_distance_to_frequency(distance);
        set_buzzer_frequency(frequency);

        printf("Distance: %.2f cm, Frequency: %d Hz\n", distance, frequency);

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    silence_buzzer();
    gpioTerminate();
    return EXIT_SUCCESS;
}

