#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_FREQ  1000
#define PWM_RANGE 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_led_color(int r, int g, int b) {
    if (gpioPWM(RED_PIN, r) < 0) return -1;
    if (gpioPWM(GREEN_PIN, g) < 0) return -1;
    if (gpioPWM(BLUE_PIN, b) < 0) return -1;
    return 0;
}

static void cleanup(void) {
    set_led_color(0, 0, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    double phase = 0.0;
    while (running) {
        double proximity = 0.5 * (1.0 + sin(phase));
        if (proximity < 0.0) proximity = 0.0;
        if (proximity > 1.0) proximity = 1.0;

        int red   = (int)(proximity * PWM_RANGE);
        int green = (int)((1.0 - proximity) * PWM_RANGE);
        int blue  = 0;

        if (set_led_color(red, green, blue) < 0) {
            fprintf(stderr, "PWM write failed\n");
            break;
        }

        phase += 0.1;
        usleep(50000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

