#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define PWR_MGMT_1     0x6B
#define GYRO_XOUT_H    0x43
#define GYRO_SCALE     131.0f   /* LSB per deg/s at ±250 deg/s */
#define LOG_FILE       "gyro_log.txt"
#define SAMPLE_US      100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_byte(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_block: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_block: read %zu bytes failed (got %zd): %s\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd)
{
    /* Wake the device: clear SLEEP bit in PWR_MGMT_1 */
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000);  /* allow oscillator to stabilize */
    return 0;
}

static int read_gyro(int fd, float *gx, float *gy, float *gz)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, GYRO_XOUT_H, buf, sizeof(buf)) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    *gx = (float)raw_x / GYRO_SCALE;
    *gy = (float)raw_y / GYRO_SCALE;
    *gz = (float)raw_z / GYRO_SCALE;
    return 0;
}

static void log_data(FILE *fp, float gx, float gy, float gz)
