#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_US 50000  /* 50 ms */
#define PWM_DUTY 500000     /* 50% of 1,000,000 */

/* Melody: {frequency in Hz, duration in ms} */
static const int melody[][2] = {
    {440, 500}, {494, 500}, {523, 500}, {587, 500},
    {659, 500}, {698, 500}, {784, 500}, {880, 500}
};
static const int melody_len = sizeof(melody) / sizeof(melody[0]);

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t button_pressed = 0;
static volatile uint32_t last_interrupt_tick = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * ISR — runs in a pigpio thread, must be async-signal-safe.
 * Just set a flag; real work is done in the main loop.
 */
static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)level;
    (void)userdata;

    uint32_t elapsed;
    if (tick >= last_interrupt_tick) {
        elapsed = tick - last_interrupt_tick;
    } else {
        elapsed = (0xFFFFFFFFu - last_interrupt_tick) + tick + 1u;
    }

    if (elapsed >= DEBOUNCE_US) {
        button_pressed = 1;
        last_interrupt_tick = tick;
    }
}

static int play_tone(int freq, int duration_ms) {
    if (freq <= 0) {
        fprintf(stderr, "Invalid frequency: %d\n", freq);
        return -1;
    }
    if (duration_ms <= 0) {
        fprintf(stderr, "Invalid duration: %d\n", duration_ms);
        return -1;
    }

    /*
     * gpioHardwarePWM(pin, freq, duty)
     * freq — frequency in Hz (1-300,000)
     * duty — 0-1,000,000 (500,000 = 50%)
     */
    if (gpioHardwarePWM(BUZZER_PIN, freq, PWM_DUTY) != 0) {
        fprintf(stderr, "Failed to start PWM at %d Hz\n", freq);
        return -1;
    }

    /*
     * Use gpioDelay for microsecond delays.
     * gpioDelay is a busy-wait but is acceptable here because the
     * ISR flag is checked in the main loop, so we don't block the
     * pigpio callback thread.
     */
    uint32_t start = gpioTick();
    uint32_t target = start + (uint32_t)duration_ms * 1000u;
    while (running && (gpioTick() < target)) {
        gpioDelay(1000);  /* 1 ms slices */
    }

    if (gpioHardwarePWM(BUZZER_PIN, 0, 0) != 0) {
        fprintf(stderr, "Failed to stop PWM\n");
        return -1;
    }
    return 0;
}

static int play_melody(void) {
    for (int i = 0; i < melody_len && running; i++) {
        if (play_tone(melody[i][0], melody[i][1]) != 0) {
            return -1;
        }
        /* Brief gap between notes */
        if (i < melody_len - 1) {
            gpioDelay(100000);  /* 100 ms */
        }
    }
    return 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure button pin as input with pull-up */
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure buzzer pin as output */
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register interrupt handler for button press (rising edge) */
    if (gpioSetISRFuncEx(BUTTON_PIN, RISING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR on GPIO%d\n", BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Musical doorbell ready. Press the button (GPIO%d) to play the melody.\n", BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        if (button_pressed) {
            button_pressed = 0;
            printf("Button pressed — playing melody...\n");
            if (play_melody() != 0) {
                fprintf(stderr, "Melody playback failed\n");
            }
        }
        gpioDelay(10000);  /* 10 ms poll interval */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioHardwarePWM(BUZZER_PIN, 0, 0);  /* Ensure buzzer is off */
    gpioSetISRFuncEx(BUTTON_PIN, RISING_EDGE, 0, NULL, NULL);  /* Unregister ISR */
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

