#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <poll.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE         "vibration_events.log"
#define WINDOW_SIZE      5
#define EARTHQUAKE_THRESHOLD 3
#define DEFAULT_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL)
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo);
    else
        snprintf(buf, len, "UNKNOWN");
}

static void log_event(FILE *log_fp, int value)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (fprintf(log_fp, "%s, GPIO%d, %d\n", ts, GPIO_LINE_OFFSET, value) < 0)
        perror("fprintf to log file failed");
    else if (fflush(log_fp) != 0)
        perror("fflush of log file failed");
}

static void check_earthquake(int value, int *window, int *idx)
{
    window[*idx] = value;
    *idx = (*idx + 1) % WINDOW_SIZE;

    int high_count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++)
        if (window[i] == 1)
            high_count++;

    if (high_count >= EARTHQUAKE_THRESHOLD) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        printf("EARTHQUAKE ALERT: %s - %d high readings in window\n", ts, high_count);
        fflush(stdout);
    }
}

int main(int argc, char *argv[])
{
    int timeout_ms = DEFAULT_TIMEOUT_MS;

    if (argc > 1) {
        long val = strtol(argv[1], NULL, 10);
        if (val > 0)
            timeout_ms = (int)val;
        else
            fprintf(stderr, "Invalid timeout '%s', using default %d ms\n", argv[1], DEFAULT_TIMEOUT_MS);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "sw420-vibration") < 0) {
        perror("gpiod_line_request_input");
