        return EXIT_FAILURE;
    }

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int window[WINDOW_SIZE] = {0};
    int widx = 0;

    printf("Monitoring SW-420 vibration sensor on GPIO%d (timeout %d ms). Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET, timeout_ms);
    fflush(stdout);

    while (program_running) {
        struct pollfd pfd;
        pfd.fd = gpiod_line_event_get_fd(line);
        if (pfd.fd < 0) {
            perror("gpiod_line_event_get_fd");
            break;
        }
        pfd.events = POLLIN;
        pfd.revents = 0;

        int pr = poll(&pfd, 1, timeout_ms);
        if (pr < 0) {
            if (errno == EINTR)
                continue;
            perror("poll");
            break;
        }
        if (pr == 0)
            continue;

        if (pfd.revents & POLLIN) {
            struct gpiod_line_event ev;
            if (gpiod_line_event_read(line, &ev) < 0) {
                perror("gpiod_line_event_read");
                continue;
            }

            int value = gpiod_line_get_value(line);
            if (value < 0) {
                perror("gpiod_line_get_value");
                continue;
            }

            log_event(log_fp, value);
            check_earthquake(value, window, &widx);
        }
    }

    printf("\nShutting down...\n");
    fflush(stdout);

    if (fclose(log_fp) != 0)
        perror("fclose log file");

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

