#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

/* LSM303DLHC Magnetometer I2C address (SA0 tied to VDD -> 0x1E) */
#define LSM303_ADDRESS_MAG 0x1E

/* Magnetometer registers */
#define CRA_REG_M 0x00
#define MR_REG_M  0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

/* Calibration offsets (adjust after calibration) */
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

/* Compass directions */
#define NUM_DIRECTIONS 8
static const char *DIRECTIONS[NUM_DIRECTIONS] = {
    "N", "NE", "E", "SE", "S", "SW", "W", "NW"
};

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* SMBus-style read of a single register via ioctl(I2C_RDWR) */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data data;
    uint8_t tx = reg;
    uint8_t rx;

    msgs[0].addr  = LSM303_ADDRESS_MAG;
    msgs[0].flags = 0;            /* write */
    msgs[0].len   = 1;
    msgs[0].buf   = &tx;

    msgs[1].addr  = LSM303_ADDRESS_MAG;
    msgs[1].flags = I2C_M_RD;     /* read */
    msgs[1].len   = 1;
    msgs[1].buf   = &rx;

    data.msgs  = msgs;
    data.nmsgs = 2;

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        return -1;
    }
    *val = rx;
    return 0;
}

/* SMBus-style write of a single register via ioctl(I2C_RDWR) */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    struct i2c_msg msg;
    struct i2c_rdwr_ioctl_data data;
    uint8_t buf[2] = { reg, val };

    msg.addr  = LSM303_ADDRESS_MAG;
    msg.flags = 0;
    msg.len   = 2;
    msg.buf   = buf;

    data.msgs  = &msg;
    data.nmsgs = 1;

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        return -1;
    }
    return 0;
}

static int init_magnetometer(int fd) {
    /* Data rate = 15 Hz (CRA_REG_M = 0x14) */
    if (i2c_write_reg8(fd, CRA_REG_M, 0x14) < 0) {
        fprintf(stderr, "Error writing CRA_REG_M: %s\n", strerror(errno));
        return -1;
    }
    /* Continuous-conversion mode (MR_REG_M = 0x00) */
    if (i2c_write_reg8(fd, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing MR_REG_M: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t xh, xl, zh, zl, yh, yl;

    if (i2c_read_reg8(fd, OUT_X_H_M, &xh) < 0) return -1;
    if (i2c_read_reg8(fd, OUT_X_L_M, &xl) < 0) return -1;
    if (i2c_read_reg8(fd, OUT_Z_H_M, &zh) < 0) return -1;
    if (i2c_read_reg8(fd, OUT_Z_L_M, &zl) < 0) return -1;
    if (i2c_read_reg8(fd, OUT_Y_H_M, &yh) < 0) return -1;
    if (i2c_read_reg8(fd, OUT_Y_L_M, &yl) < 0) return -1;

    *x = (int16_t)((xh << 8) | xl);
    *z = (int16_t)((zh << 8) | zl);
    *y = (int16_t)((yh << 8) | yl);
    return 0;
}

static void calibrate_data(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                           float *cal_x, float *cal_y, float *cal_z) {
    *cal_x = (float)raw_x - X_OFFSET;
    *cal_y = (float)raw_y - Y_OFFSET;
    *cal_z = (float)raw_z - Z_OFFSET;
}

static float calculate_heading(float cal_x, float cal_y) {
    float heading = atan2f(cal_y, cal_x) * 180.0f / (float)M_PI;
    if (heading < 0.0f) {
        heading += 360.0f;
    }
    return heading;
}

static const char *determine_direction(float heading) {
    int index = (int)(heading / 45.0f) % NUM_DIRECTIONS;
    if (index < 0) index += NUM_DIRECTIONS;
    return DIRECTIONS[index];
}

static int log_data(FILE *fp, float cal_x, float cal_y, float cal_z, float heading) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f\n",
                timestamp, cal_x, cal_y, cal_z, heading) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_ADDRESS_MAG) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                LSM303_ADDRESS_MAG, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    if (init_magnetometer(g_i2c_fd) < 0) {
        fprintf(stderr, "Magnetometer initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    int file_exists = (access("mag_log.csv", F_OK) == 0);
    g_csv = fopen("mag_log.csv", "a");
    if (g_csv == NULL) {
        fprintf(stderr, "Error opening mag_log.csv: %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }
    if (!file_exists) {
        fprintf(g_csv, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
        fflush(g_csv);
    }

    printf("LSM303DLHC Compass Logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        float cal_x, cal_y, cal_z, heading;

        if (read_magnetometer(g_i2c_fd, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        calibrate_data(raw_x, raw_y, raw_z, &cal_x, &cal_y, &cal_z);
        heading = calculate_heading(cal_x, cal_y);
        const char *direction = determine_direction(heading);

        printf("Heading: %.2f degrees (%s)\n", heading, direction);

        if (log_data(g_csv, cal_x, cal_y, cal_z, heading) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    if (g_csv != NULL) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

