        calibrate_data(raw_x, raw_y, raw_z, &cal_x, &cal_y, &cal_z);
        heading = calculate_heading(cal_x, cal_y);
        const char *direction = determine_direction(heading);

        printf("Heading: %.2f degrees (%s)\n", heading, direction);

        if (log_data(g_csv, cal_x, cal_y, cal_z, heading) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    if (g_csv != NULL) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

