#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17
#define DEBOUNCE_MS      200
#define LOG_FILE         "relay_log.json"

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_last_tick = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * pigpio ISRs run in a dedicated thread, so we keep the work minimal.
 * We only record the tick of the most recent valid touch so the main
 * loop can decide whether to toggle the relay.
 */
static void touch_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 1)            /* only act on rising edge (touch) */
        return;

    uint32_t elapsed = tick - g_last_tick; /* pigpio tick wraps every ~72 min */
    if (elapsed < DEBOUNCE_MS * 1000)      /* debounce: ignore within 200 ms */
        return;

    g_last_tick = tick;
}

static int log_relay_state(int state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n",
            ts, state ? "ON" : "OFF");

    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
        return -1;
    }
    return 0;
}

int main(void)
{
    /* --- signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- configure relay pin --- */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(RELAY_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- configure touch sensor pin with pull-down --- */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(TOUCH_SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(TOUCH_SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- register ISR on rising edge --- */
    if (gpioSetISRFunc(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_isr) != 0) {
        fprintf(stderr, "gpioSetISRFunc(TOUCH_SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Relay control started. Touch GPIO%d to toggle GPIO%d. Ctrl+C to exit.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);

    int relay_state = 0;

    while (g_running) {
        /*
         * Check whether a valid touch occurred since the last iteration.
         * We read g_last_tick and the current tick atomically enough for
         * a 32-bit counter that wraps every ~72 minutes.
         */
        uint32_t last = g_last_tick;
        if (last != 0) {
            g_last_tick = 0;                 /* consume the event */

            relay_state = !relay_state;
            if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                fprintf(stderr, "gpioWrite(RELAY_PIN) failed\n");
                break;
            }

            if (log_relay_state(relay_state) != 0) {
                fprintf(stderr, "log_relay_state() failed\n");
                break;
            }

            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
        }

        gpioDelay(50 * 1000);                 /* 50 ms poll interval */
    }

    /* --- clean shutdown --- */
    printf("\nShutting down...\n");

    if (gpioWrite(RELAY_PIN, 0) != 0)
        fprintf(stderr, "Warning: failed to turn relay OFF on exit\n");

    if (log_relay_state(0) != 0)
        fprintf(stderr, "Warning: failed to log final OFF state\n");

    gpioTerminate();
    return EXIT_SUCCESS;
}

