#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define MOISTURE_THRESHOLD 30
#define IRRIGATION_DURATION 5
#define RELAY_DELAY 1
#define POLL_INTERVAL 10

static const unsigned int relay_pins[NUM_RELAYS] = {17, 23, 24, 25};
static const char *relay_names[NUM_RELAYS] = {"Relay1", "Relay2", "Relay3", "Relay4"};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS];
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get line %u: %s\n", relay_pins[i], strerror(errno));
            return -1;
        }
        if (gpiod_line_request_output(relay_lines[i], "irrigation", 1) < 0) {
            fprintf(stderr, "Failed to request line %u as output: %s\n", relay_pins[i], strerror(errno));
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 1);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int read_soil_moisture(void) {
    return rand() % 101;
}

static void activate_relay(int relay_index) {
    if (gpiod_line_set_value(relay_lines[relay_index], 0) < 0) {
        fprintf(stderr, "Failed to activate relay %s (line %u): %s\n",
                relay_names[relay_index], relay_pins[relay_index], strerror(errno));
        return;
    }
    printf("%s activated\n", relay_names[relay_index]);

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s - %s activated. Moisture level: %d\n",
                timestamp, relay_names[relay_index], read_soil_moisture());
        fflush(log_file);
    }

    sleep(IRRIGATION_DURATION);

    if (gpiod_line_set_value(relay_lines[relay_index], 1) < 0) {
        fprintf(stderr, "Failed to deactivate relay %s (line %u): %s\n",
                relay_names[relay_index], relay_pins[relay_index], strerror(errno));
    }
    printf("%s deactivated\n", relay_names[relay_index]);
    sleep(RELAY_DELAY);
}

int main(void) {
    srand((unsigned int)time(NULL));

    log_file = fopen("irrigation_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        fclose(log_file);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        cleanup_gpio();
        fclose(log_file);
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int moisture = read_soil_moisture();
        printf("Soil Moisture: %d\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold. Activating relays.\n");
            for (int i = 0; i < NUM_RELAYS && program_running; i++) {
                activate_relay(i);
            }
        }

        if (program_running) {
            sleep(POLL_INTERVAL);
        }
    }

    printf("\nShutting down...\n");
    cleanup_gpio();
    if (log_file) {
        fclose(log_file);
    }
    printf("Smart Irrigation System stopped.\n");
    return 0;
}

