/*
 * Automated plant watering system for Raspberry Pi Zero W
 * Library: pigpio (C API)
 *
 * Wiring:
 *   SG90 valve servo  -> GPIO17 (physical pin 11)
 *   SG90 nozzle servo -> GPIO18 (physical pin 12)
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 * Run:
 *   sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_GPIO      17
#define NOZZLE_GPIO     18

#define MOISTURE_THRESHOLD 50

#define SERVO_MIN_PULSE  500   /* ~0 degrees   */
#define SERVO_MID_PULSE  1500  /* ~90 degrees  */
#define SERVO_MAX_PULSE  2500  /* ~180 degrees */

#define WATERING_STEP_DELAY_US  2000000  /* 2 s between nozzle angles */
#define WATERING_HOLD_US        5000000  /* 5 s holding at each angle */
#define CYCLE_DELAY_US          5000000  /* 5 s between moisture readings */
#define SERVO_RETRY_COUNT       3
#define SERVO_RETRY_DELAY_US    100000   /* 100 ms backoff */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Set a servo to a given pulse width with retry logic.
 * Returns 0 on success, -1 on failure.
 */
static int set_servo(int gpio, int pulse_width)
{
    for (int attempt = 0; attempt < SERVO_RETRY_COUNT; ++attempt) {
        if (gpioServo(gpio, pulse_width) == 0)
            return 0;
        fprintf(stderr,
                "Warning: gpioServo(%d, %d) failed (attempt %d/%d)\n",
                gpio, pulse_width, attempt + 1, SERVO_RETRY_COUNT);
        if (attempt < SERVO_RETRY_COUNT - 1)
            gpioDelay(SERVO_RETRY_DELAY_US);
    }
    return -1;
}

/*
 * Open the water valve to 90 degrees (full open).
 * Returns 0 on success, -1 on failure.
 */
static int open_valve(void)
{
    if (set_servo(VALVE_GPIO, SERVO_MID_PULSE) != 0) {
        fprintf(stderr, "Error: failed to open water valve\n");
        return -1;
    }
    gpioDelay(300000); /* 300 ms to reach position */
    return 0;
}

/*
 * Close the water valve to 0 degrees (full close).
 * Returns 0 on success, -1 on failure.
 */
static int close_valve(void)
{
    if (set_servo(VALVE_GPIO, SERVO_MIN_PULSE) != 0) {
        fprintf(stderr, "Error: failed to close water valve\n");
        return -1;
    }
    gpioDelay(300000); /* 300 ms to reach position */
    return 0;
}

/*
 * Move the nozzle to a given angle (0-180).
 * Returns 0 on success, -1 on failure.
 */
static int move_nozzle(int angle)
{
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: invalid nozzle angle %d\n", angle);
        return -1;
    }
    int pulse = SERVO_MIN_PULSE +
                (int)((long)angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) / 180);
    if (set_servo(NOZZLE_GPIO, pulse) != 0) {
        fprintf(stderr, "Error: failed to move nozzle to %d degrees\n", angle);
        return -1;
    }
