 * Returns 0 on success, -1 on failure.
 */
static int move_nozzle(int angle)
{
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: invalid nozzle angle %d\n", angle);
        return -1;
    }
    int pulse = SERVO_MIN_PULSE +
                (int)((long)angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) / 180);
    if (set_servo(NOZZLE_GPIO, pulse) != 0) {
        fprintf(stderr, "Error: failed to move nozzle to %d degrees\n", angle);
        return -1;
    }
    gpioDelay(300000); /* 300 ms to reach position */
    return 0;
}

/*
 * Watering cycle: open valve, sweep nozzle, hold, close valve.
 * Returns 0 on success, -1 on failure.
 */
static int water_plant(void)
{
    if (open_valve() != 0)
        return -1;

    const int nozzle_angles[] = {0, 45, 90, 135, 180};
    const int num_angles =
        sizeof(nozzle_angles) / sizeof(nozzle_angles[0]);

    for (int i = 0; i < num_angles; ++i) {
        if (move_nozzle(nozzle_angles[i]) != 0) {
            fprintf(stderr,
                    "Warning: nozzle step %d/%d failed, continuing\n",
                    i + 1, num_angles);
            continue;
        }
        gpioDelay(WATERING_STEP_DELAY_US);
    }

    gpioDelay(WATERING_HOLD_US);

    if (close_valve() != 0)
        return -1;

    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Ensure servos are stopped before entering main loop */
    gpioServo(VALVE_GPIO, 0);
    gpioServo(NOZZLE_GPIO, 0);
    gpioDelay(500000); /* 500 ms settle */

    /* Simulated soil-moisture readings (0-100) */
    const int moisture_readings[] = {20, 40, 60, 80, 100};
    const int num_readings =
        sizeof(moisture_readings) / sizeof(moisture_readings[0]);
    int reading_index = 0;

    printf("Automated Plant Watering System started.\n");
    printf("Moisture threshold: %d%%\n", MOISTURE_THRESHOLD);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int moisture = moisture_readings[reading_index];
        printf("Moisture: %d%%\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture below threshold. Watering plant...\n");
            if (water_plant() != 0) {
                fprintf(stderr, "Error: watering cycle failed\n");
            } else {
                printf("Watering complete.\n");
            }
        } else {
            printf("Moisture above threshold. No watering needed.\n");
        }

        reading_index = (reading_index + 1) % num_readings;

        /* Wait before next moisture reading (interruptible) */
        for (int i = 0; i < 50 && g_running; ++i)
