#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22

#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

#define STEPS_PER_ROTATION 512
#define STEP_DELAY_US 3000
#define DEBOUNCE_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_write(unsigned gpio, int level) {
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %d) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_set_pull(unsigned gpio, unsigned pud) {
    if (gpioSetPullUpDown(gpio, pud) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%u, %u) failed\n", gpio, pud);
        return -1;
    }
    return 0;
}

static int deenergize(void) {
    int rc = 0;
    rc |= safe_write(IN1, 0);
    rc |= safe_write(IN2, 0);
    rc |= safe_write(IN3, 0);
    rc |= safe_write(IN4, 0);
    return rc;
}

static int step_cw(void) {
    if (safe_write(IN1, 1) < 0) return -1;
    gpioDelay(STEP_DELAY_US);
    if (safe_write(IN1, 0) < 0) return -1;
    if (safe_write(IN2, 1) < 0) return -1;
    gpioDelay(STEP_DELAY_US);
    if (safe_write(IN2, 0) < 0) return -1;
    if (safe_write(IN3, 1) < 0) return -1;
    gpioDelay(STEP_DELAY_US);
    if (safe_write(IN3, 0) < 0) return -1;
    if (safe_write(IN4, 1) < 0) return -1;
    gpioDelay(STEP_DELAY_US);
    if (safe_write(IN4, 0) < 0) return -1;
    return 0;
}

static int step_ccw(void) {
    if (safe_write(IN4, 1) < 0) return -1;
    gpioDelay(STEP_DELAY_US);
    if (safe_write(IN4, 0) < 0) return -1;
    if (safe_write(IN3, 1) < 0) return -1;
    gpioDelay(STEP_DELAY_US);
    if (safe_write(IN3, 0) < 0) return -1;
    if (safe_write(IN2, 1) < 0) return -1;
    gpioDelay(STEP_DELAY_US);
    if (safe_write(IN2, 0) < 0) return -1;
    if (safe_write(IN1, 1) < 0) return -1;
    gpioDelay(STEP_DELAY_US);
    if (safe_write(IN1, 0) < 0) return -1;
    return 0;
}

static int rotate(int steps, int (*step_fn)(void)) {
    for (int i = 0; i < steps && running; i++) {
        if (step_fn() < 0) {
            fprintf(stderr, "Error during step %d\n", i);
            return -1;
        }
    }
    return deenergize();
}

static int init_gpio(void) {
    if (safe_set_mode(IN1, PI_OUTPUT) < 0) return -1;
    if (safe_set_mode(IN2, PI_OUTPUT) < 0) return -1;
    if (safe_set_mode(IN3, PI_OUTPUT) < 0) return -1;
    if (safe_set_mode(IN4, PI_OUTPUT) < 0) return -1;
    if (safe_set_mode(LOCK_BUTTON, PI_INPUT) < 0) return -1;
    if (safe_set_mode(UNLOCK_BUTTON, PI_INPUT) < 0) return -1;
    if (safe_set_pull(LOCK_BUTTON, PI_PUD_UP) < 0) return -1;
    if (safe_set_pull(UNLOCK_BUTTON, PI_PUD_UP) < 0) return -1;
    return deenergize();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock simulation started. Press LOCK (GPIO24) or UNLOCK (GPIO23) to rotate.\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            printf("Locking door...\n");
            if (rotate(STEPS_PER_ROTATION, step_cw) < 0) {
                fprintf(stderr, "Lock failed\n");
            } else {
                printf("Door locked.\n");
            }
            gpioDelay(DEBOUNCE_US);
        } else if (gpioRead(UNLOCK_BUTTON) == 0) {
            printf("Unlocking door...\n");
            if (rotate(STEPS_PER_ROTATION, step_ccw) < 0) {
                fprintf(stderr, "Unlock failed\n");
            } else {
                printf("Door unlocked.\n");
            }
            gpioDelay(DEBOUNCE_US);
        }
        gpioDelay(10000);
    }

    deenergize();
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

