#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define TIMEOUT_US  50000   /* 50 ms timeout for echo edges */
#define GUARD_US    60000   /* 60 ms guard between measurements */
#define SAMPLE_US   1000000 /* 1 s between readings */

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* Busy-wait for a line to reach the requested value, with timeout. */
static int wait_for_line(struct gpiod_line *line, int value, int timeout_us)
{
    struct timespec t0, now;
    clock_gettime(CLOCK_MONOTONIC, &t0);

    for (;;) {
        int v = gpiod_line_get_value(line);
        if (v < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
            return -1;
        }
        if (v == value)
            return 0;

        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_us = (now.tv_sec - t0.tv_sec) * 1000000L
                        + (now.tv_nsec - t0.tv_nsec) / 1000L;
        if (elapsed_us >= timeout_us)
            return -1; /* timeout */
    }
}

static float measure_distance(struct gpiod_line *trig, struct gpiod_line *echo)
{
    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(2);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1.0f;
    }

    /* Wait for echo rising edge */
    if (wait_for_line(echo, 1, TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo rising edge\n");
        return -1.0f;
    }

    struct timespec t_rise;
    clock_gettime(CLOCK_MONOTONIC, &t_rise);

    /* Wait for echo falling edge */
    if (wait_for_line(echo, 0, TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo falling edge\n");
        return -1.0f;
    }

    struct timespec t_fall;
    clock_gettime(CLOCK_MONOTONIC, &t_fall);

    long duration_us = (t_fall.tv_sec - t_rise.tv_sec) * 1000000L
                     + (t_fall.tv_nsec - t_rise.tv_nsec) / 1000L;

    /* distance_cm = duration_us * 0.01715  (speed of sound 343 m/s) */
    return (float)duration_us * 0.01715f;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    /* Open log file once */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open gpiochip4 (BCM GPIO bank on Pi 4/5) */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        goto cleanup;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request trigger as output, initial value low */
    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request echo as input */
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance logger started. Press Ctrl+C to stop.\n");

    while (running) {
        float dist = measure_distance(trig, echo);

        if (dist < 0.0f) {
            fprintf(log_fp, "-1\n");
        } else {
            fprintf(log_fp, "%.2f\n", dist);
        }
        fflush(log_fp);

        /* Sleep 1 s, but wake early on signal */
        for (int i = 0; i < 10 && running; i++)
            usleep(100000);

        /* 60 ms guard to avoid false echoes */
        usleep(GUARD_US);
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (trig)
        gpiod_line_release(trig);
    if (echo)
        gpiod_line_release(echo);
    if (chip)
        gpiod_chip_close(chip);
    if (log_fp)
        fclose(log_fp);

    return ret;
}

