#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define RELAY_GPIO     18
#define PROXIMITY_THRESHOLD 50
#define POLL_DELAY_US  100000

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET            0x0000
#define REG_SYSTEM_MODE_START     0x0080
#define REG_RESULT_INT_STATUS     0x0044
#define REG_RESULT_DISTANCE_MSB   0x0096
#define REG_RESULT_DISTANCE_LSB   0x0097

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to a 16-bit VL53L1X register address */
static int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error: I2C write to reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

/* Read one byte from a 16-bit VL53L1X register address */
static int vl53l1x_read_byte(int handle, uint16_t reg, uint8_t *value)
{
    char reg_buf[2];
    char data_buf[1];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "Error: I2C write (reg select) for 0x%04X failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "Error: I2C read from reg 0x%04X failed\n", reg);
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

/* Read a 16-bit big-endian value from two consecutive 16-bit registers */
static int vl53l1x_read_word(int handle, uint16_t reg_msb, uint16_t reg_lsb, uint16_t *value)
{
    uint8_t msb, lsb;
    if (vl53l1x_read_byte(handle, reg_msb, &msb) != 0)
        return -1;
    if (vl53l1x_read_byte(handle, reg_lsb, &lsb) != 0)
        return -1;
    *value = ((uint16_t)msb << 8) | lsb;
    return 0;
}

static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;

    /* Software reset */
    if (vl53l1x_write_byte(handle, REG_SOFT_RESET, 0x00) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    /* Verify sensor identity (optional but good practice) */
    if (vl53l1x_read_byte(handle, 0x010F, &model_id) != 0) {
        fprintf(stderr, "Error: Cannot read VL53L1X model ID (sensor absent?)\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Unexpected model ID 0x%02X (expected 0xEA)\n", model_id);
        return -1;
    }

    /* Start continuous ranging mode */
    if (vl53l1x_write_byte(handle, REG_SYSTEM_MODE_START, 0x01) != 0)
        return -1;

    return 0;
}

static int read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t int_status = 0;

    /* Poll data-ready interrupt status */
    if (vl53l1x_read_byte(handle, REG_RESULT_INT_STATUS, &int_status) != 0)
        return -1;

    if ((int_status & 0x01) == 0) {
        /* Data not ready yet */
        return 1;
    }

    /* Read 16-bit distance result */
    if (vl53l1x_read_word(handle, REG_RESULT_DISTANCE_MSB,
                          REG_RESULT_DISTANCE_LSB, distance_mm) != 0)
        return -1;

    /* Clear interrupt by writing 0x01 to status register */
    if (vl53l1x_write_byte(handle, REG_RESULT_INT_STATUS, 0x01) != 0)
        return -1;

    return 0;
}

static void control_relay(int gpio_pin, int distance_mm)
{
    int level = (distance_mm <= PROXIMITY_THRESHOLD * 10) ? 1 : 0;
    if (gpioWrite(gpio_pin, level) != 0) {
        fprintf(stderr, "Error: Failed to write GPIO %d\n", gpio_pin);
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", RELAY_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity-based door system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance_mm = 0;
        int rc = read_distance(g_i2c_handle, &distance_mm);

        if (rc == 0) {
            int distance_cm = distance_mm / 10;
            printf("Distance: %d cm\n", distance_cm);
            control_relay(RELAY_GPIO, distance_mm);
        } else if (rc < 0) {
            fprintf(stderr, "Error: Failed to read distance\n");
        }
        /* rc == 1: data not ready, just skip this cycle */

        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    gpioWrite(RELAY_GPIO, 0);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
