#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68

#define PWR_MGMT_1     0x6B
#define GYRO_CONFIG    0x1B
#define GYRO_XOUT_H    0x43

#define GYRO_SENSITIVITY 131.0f

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU-6050\n");
        return -1;
    }
    usleep(100000);
    if (i2c_write_reg8(fd, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure gyroscope range\n");
        return -1;
    }
    return 0;
}

static int read_gyro_data(int fd, float *gx, float *gy, float *gz) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, GYRO_XOUT_H, buf, 6) < 0) {
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    *gx = (float)raw_x / GYRO_SENSITIVITY;
    *gy = (float)raw_y / GYRO_SENSITIVITY;
    *gz = (float)raw_z / GYRO_SENSITIVITY;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (init_mpu6050(fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialized. Reading gyroscope data...\n");

    while (g_running) {
        float gx, gy, gz;
        if (read_gyro_data(fd, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
            usleep(100000);
            continue;
        }
        printf("X: %.2f dps, Y: %.2f dps, Z: %.2f dps\n", gx, gy, gz);
        usleep(100000);
    }

    printf("\nExiting gracefully...\n");
    close(fd);
    return EXIT_SUCCESS;
}

