/*
 * Automated Plant Watering System - Raspberry Pi 4 Model B
 * Uses libgpiod v1 API (modern GPIO character-device interface).
 *
 * Relays (BCM numbering): GPIO17, GPIO18, GPIO27, GPIO22
 * Active-low relay modules: HIGH = inactive, LOW = active.
 *
 * Watering cycle: 4x 5 s pulses every 86400 s (24 h).
 * Logs start times to watering_log.txt.
 *
 * Build: gcc -o watering watering.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS      4
#define WATERING_SEC    86400   /* 24 hours */
#define POLL_SEC        60      /* 1-minute loop */
#define RELAY_PULSE_SEC 5       /* 5 s per relay pulse */
#define LOG_FILE        "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped line to the log file. Returns 0 on success,
 * -1 on error (message printed to stderr). */
static int log_watering(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Watering cycle started\n", ts) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() on log failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Activate one relay for RELAY_PULSE_SEC seconds.
 * Active-low relay: LOW = active, HIGH = inactive. */
static int activate_relay(struct gpiod_line *line, unsigned int pin)
{
    if (gpiod_line_set_value(line, 0) < 0) {   /* active */
        fprintf(stderr, "Failed to set GPIO%u LOW: %s\n", pin, strerror(errno));
        return -1;
    }
    sleep(RELAY_PULSE_SEC);
    if (gpiod_line_set_value(line, 1) < 0) {   /* inactive */
        fprintf(stderr, "Failed to set GPIO%u HIGH: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Run one full watering cycle: 4x 5 s pulses. */
static int run_watering_cycle(struct gpiod_line **lines)
{
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (activate_relay(lines[i], relay_pins[i]) < 0)
            return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int lines_acquired = 0;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open gpiochip0 ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Acquire all four lines ---- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* ---- Request all lines as outputs, initial value HIGH (inactive) ---- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_output(lines[i], "plant-watering", 1) < 0) {
            fprintf(stderr, "Failed to request GPIO%u as output: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
        lines_acquired++;
    }

    printf("Automated Plant Watering System started.\n");
    printf("Relays: GPIO17, GPIO18, GPIO27, GPIO22 (active-low, 5 s pulse)\n");
    printf("Watering cycle every %d s. Press Ctrl+C to exit.\n", WATERING_SEC);

    /* ---- Main loop ---- */
    time_t last_water = time(NULL);
    if (last_water == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        time_t now = time(NULL);
        if (now == (time_t)-1) {
            fprintf(stderr, "time() failed: %s\n", strerror(errno));
            goto cleanup;
        }

        if (difftime(now, last_water) >= (double)WATERING_SEC) {
            printf("Starting watering cycle...\n");
            if (run_watering_cycle(lines) < 0) {
                fprintf(stderr, "Watering cycle failed; continuing.\n");
            } else {
                if (log_watering() < 0)
                    fprintf(stderr, "Warning: failed to log watering event.\n");
                last_water = now;
            }
        }

        sleep(POLL_SEC);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* ---- Release lines and close chip ---- */
    for (int i = 0; i < lines_acquired; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

