#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define WHO_AM_I     0x75
#define PWR_MGMT_1   0x6B
#define SMPLRT_DIV   0x19
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43

/* Expected WHO_AM_I value for MPU-6050 */
#define MPU6050_WHO_AM_I 0x68

/* Gyroscope sensitivity for ±250 deg/s range (131 LSB/deg/s) */
#define GYRO_SENSITIVITY 131.0f

/* Circular buffer size */
#define BUFFER_SIZE 100

/* LED GPIO pin */
#define LED_PIN 17

/* Sample period in microseconds (50 ms = 20 Hz) */
#define SAMPLE_PERIOD_US 50000

/* Maximum consecutive read failures before re-initialisation */
#define MAX_READ_FAILURES 3

/* Structure to hold gyroscope data with timestamp */
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

/* Circular buffer */
static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;

/* I2C handle */
static int i2c_handle = -1;

/* Flag to indicate program termination */
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Function to initialize the MPU-6050 */
static int init_mpu6050(void) {
    /* Wake up the MPU-6050 (clear sleep bit, use internal 8 MHz oscillator) */
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not write to PWR_MGMT_1 register\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms delay for oscillator to stabilize */

    /* Set sample rate divider to 7 (1 kHz / (1 + 7) = 125 Hz internal sample rate) */
    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: Could not write to SMPLRT_DIV register\n");
        return -1;
    }

    /* Set gyroscope full-scale range to ±250 deg/s (FS_SEL = 0) */
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not write to GYRO_CONFIG register\n");
        return -1;
    }

    /* Verify sensor identity */
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Could not read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who_am_i, MPU6050_WHO_AM_I);
        return -1;
    }

    return 0;
}

/* Function to read raw gyroscope data from the MPU-6050 */
static int read_raw_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];

    /* Read 6 bytes starting from GYRO_XOUT_H (0x43) */
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    /* Combine high and low bytes (big-endian) */
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

/* Function to convert raw gyroscope data to degrees per second */
static void convert_gyro_data(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                              float *x, float *y, float *z) {
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;
}

/* Function to add data to the circular buffer */
static void add_to_buffer(float x, float y, float z) {
    clock_gettime(CLOCK_MONOTONIC, &gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

/* Function to check if any axis exceeds the threshold */
static bool check_threshold(float x, float y, float z, float threshold) {
    return (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold);
}

/* Function to control the LED */
static void control_led(bool on) {
    gpioWrite(LED_PIN, on ? 1 : 0);
}

/* Function to handle I2C errors */
static void handle_i2c_error(void) {
    fprintf(stderr, "I2C error detected. Attempting to re-initialize...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioDelay(1000000); /* 1 second delay before re-initialization */

    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not re-open I2C device: %d\n", i2c_handle);
        terminate = 1;
    } else {
        if (init_mpu6050() < 0) {
            fprintf(stderr, "Error: Could not re-initialize MPU-6050\n");
            terminate = 1;
        }
    }
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Set LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open I2C device on bus 1 */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: Could not initialize MPU-6050\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Set up signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    float x, y, z;
    bool led_on = false;
    int read_failures = 0;

    /* Main loop */
    while (!terminate) {
        if (read_raw_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            read_failures = 0;
            convert_gyro_data(raw_x, raw_y, raw_z, &x, &y, &z);
            add_to_buffer(x, y, z);

            bool threshold_exceeded = check_threshold(x, y, z, 250.0f);
            if (threshold_exceeded && !led_on) {
                control_led(true);
                led_on = true;
            } else if (!threshold_exceeded && led_on) {
                control_led(false);
                led_on = false;
            }
        } else {
            read_failures++;
            if (read_failures >= MAX_READ_FAILURES) {
                fprintf(stderr, "Error: Max read failures reached. Exiting.\n");
                terminate = 1;
            } else {
                handle_i2c_error();
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();

    return 0;
}

