#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    3900000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8

#define GYRO_XOUT_H     0x43
#define GYRO_YOUT_H     0x45
#define GYRO_ZOUT_H     0x47
#define GYRO_SENSITIVITY 131.0f

#define LED_GPIO_LINE   17
#define LED_CHIP        "gpiochip0"

#define BUFFER_SIZE     64
#define THRESHOLD       200.0f
#define BLINK_MS        500

typedef struct {
    struct timespec timestamp;
    float x, y, z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *led_chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(spi_fd); spi_fd = -1; return -1;
    }

    return 0;
}

static int gpio_init(void) {
    led_chip = gpiod_chip_open_by_name(LED_CHIP);
    if (!led_chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    led_line = gpiod_chip_get_line(led_chip, LED_GPIO_LINE);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(led_chip); led_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(led_line, "mpu6050_stability", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(led_chip); led_chip = NULL; led_line = NULL;
        return -1;
    }

    return 0;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
