#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B

/* LED GPIO pin */
#define LED_PIN 21

/* Tilt threshold (degrees) */
#define TILT_THRESHOLD 45.0

/* I2C bus on Raspberry Pi 4 Model B */
#define I2C_BUS 1

/* Global variables for cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Function to initialize the MPU-6050 */
static int init_mpu6050(int handle) {
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050 (write PWR_MGMT_1).\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms delay for oscillator to stabilize */

    /* Set accelerometer full-scale range to +/- 2g (default) */
    if (i2cWriteByteData(handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set accelerometer config (ACCEL_CONFIG).\n");
        return -1;
    }

    return 0;
}

/* Function to read raw accelerometer data from the MPU-6050 */
static int read_raw_accel(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];

    /* Read 6 bytes starting from ACCEL_XOUT_H (0x3B) */
    if (i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data.\n");
        return -1;
    }

    /* Combine high and low bytes (big-endian) */
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

/* Function to calculate roll and pitch angles from raw accelerometer data */
static void calculate_tilt(int16_t x, int16_t y, int16_t z, float *roll, float *pitch) {
    *roll  = atan2((float)y, (float)z) * 180.0 / M_PI;
    *pitch = atan2(-(float)x, sqrt((float)y * (float)y + (float)z * (float)z)) * 180.0 / M_PI;
}

/* Function to control the LED based on tilt angles */
static void control_led(float roll, float pitch) {
    if (fabs(roll) > TILT_THRESHOLD || fabs(pitch) > TILT_THRESHOLD) {
        gpioWrite(LED_PIN, 1); /* Turn LED on */
    } else {
        gpioWrite(LED_PIN, 0); /* Turn LED off */
    }
}

/* Function to log tilt data to a file */
static void log_tilt_data(float roll, float pitch) {
    FILE *fp = fopen("tilt_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open tilt_log.txt for appending.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, roll, pitch);

    fclose(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Set LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); /* Ensure LED is off initially */

    /* Open I2C connection to MPU-6050 */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C connection to MPU-6050 (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: Could not set SIGINT handler.\n");
    }

    printf("Tilt detection started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (program_running) {
        int16_t x, y, z;

        /* Read raw accelerometer data */
        if (read_raw_accel(i2c_handle, &x, &y, &z) == 0) {
            float roll, pitch;

            /* Calculate roll and pitch angles */
            calculate_tilt(x, y, z, &roll, &pitch);

            /* Control the LED based on tilt angles */
            control_led(roll, pitch);

            /* Log tilt data */
            log_tilt_data(roll, pitch);

            /* Print roll and pitch to the console */
            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, continuing...\n");
        }

        /* Delay for 100 milliseconds */
        gpioDelay(100000);
    }

    /* Cleanup */
    printf("\nCleaning up...\n");
    gpioWrite(LED_PIN, 0); /* Turn LED off */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

