#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1145_ADDR    0x5A
#define REG_ALS        0x20
#define REG_PS1        0x22
#define GPIO_CHIP      "gpiochip0"
#define GPIO_LED       17
#define PROX_THRESHOLD 100
#define LOG_FILE       "biometric_log.txt"
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 10
#define POLL_DELAY_MS  100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int read_sensor_data(int fd, uint16_t *ambient, uint16_t *proximity) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_reg16(fd, REG_ALS, ambient) == 0 &&
            i2c_read_reg16(fd, REG_PS1, proximity) == 0) {
            return 0;
        }
        if (attempt < MAX_RETRIES - 1) {
            usleep(RETRY_DELAY_MS * 1000);
        }
    }
    return -1;
}

static void log_data(FILE *fp, uint16_t ambient, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,AmbientLight:%u,Proximity:%u\n", ts, ambient, proximity);
    fflush(fp);
}

static void control_led(struct gpiod_line *line, uint16_t proximity) {
    int val = (proximity > PROX_THRESHOLD) ? 1 : 0;
    if (gpiod_line_set_value(line, val) < 0) {
        fprintf(stderr, "Failed to set LED GPIO value: %s\n", strerror(errno));
    }
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1145_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }
    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LED, strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(led_line, "si1145-led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_LED, strerror(errno));
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Si1145 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t ambient = 0, proximity = 0;
        if (read_sensor_data(i2c_fd, &ambient, &proximity) == 0) {
            log_data(log_fp, ambient, proximity);
            control_led(led_line, proximity);
        } else {
            fprintf(stderr, "Sensor read failed after %d retries.\n", MAX_RETRIES);
        }
        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

