#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADXRS290 register addresses (7-bit, read bit = 0x80) */
#define ADXRS290_REG_XGYRO_OUT 0x02
#define ADXRS290_REG_YGYRO_OUT 0x04
#define ADXRS290_READ_BIT      0x80

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* mode 0, active-low CE */

/* Sampling */
#define SAMPLE_DELAY_US 10000  /* 10 ms -> ~100 Hz */
#define MAX_REINIT_ATTEMPTS 3

/* Sensitivity: 200 LSB/deg/s */
#define SENSITIVITY 200.0f

static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/*
 * Read a 16-bit register from the ADXRS290.
 * Returns 0 on success and stores the value in *out; -1 on error.
 */
static int read_gyro_axis(uint8_t reg, int16_t *out)
{
    char tx[2], rx[2];

    tx[0] = (char)(reg | ADXRS290_READ_BIT);
    tx[1] = 0x00;  /* dummy byte to clock out data */

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    /* rx[0] is the echo of the command byte; rx[1] is the data byte */
    *out = (int16_t)((uint8_t)rx[1]);
    return 0;
}

static int initialize_spi(void)
{
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening gyro_data.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(fp, "timestamp,X_rate,Y_rate\n");

    int reinit_attempts = 0;

    while (!terminate) {
        int16_t x_rate = 0, y_rate = 0;
        int x_ok = read_gyro_axis(ADXRS290_REG_XGYRO_OUT, &x_rate);
        int y_ok = read_gyro_axis(ADXRS290_REG_YGYRO_OUT, &y_rate);

        if (x_ok != 0 || y_ok != 0) {
            fprintf(stderr, "Error reading gyro data. Attempting reinitialization...\n");
            spiClose(spi_handle);
            spi_handle = -1;

            reinit_attempts++;
            if (reinit_attempts > MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max reinit attempts (%d) reached. Exiting.\n",
                        MAX_REINIT_ATTEMPTS);
                break;
            }

            gpioDelay(100000);  /* 100 ms backoff */
            if (initialize_spi() != 0) {
                fprintf(stderr, "SPI reinitialization failed.\n");
                break;
            }
            continue;
        }

        reinit_attempts = 0;

        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            perror("clock_gettime");
            ts.tv_sec = 0;
            ts.tv_nsec = 0;
        }

        double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

        fprintf(fp, "%.6f,%d,%d\n", timestamp, x_rate, y_rate);
        fflush(fp);

        gpioDelay(SAMPLE_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

