#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <string.h>
#include <pthread.h>

/* ADXRS290 Register Addresses */
#define ADXRS290_REG_RATE_XL 0x02
#define ADXRS290_REG_RATE_XH 0x03

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CE */

/* GPIO Configuration */
#define LED_GPIO 17

/* Threshold for angular velocity (degrees/second) */
#define ANGULAR_VELOCITY_THRESHOLD 20.0

/* Circular Buffer Configuration */
#define BUFFER_SIZE 100

/* Sensitivity: 200 LSB/deg/s for ADXRS290 */
#define SENSITIVITY 200.0

/* Structure to hold gyroscope data with timestamp */
typedef struct {
    struct timespec timestamp;
    int16_t rate_x;
} gyro_data_t;

/* Circular buffer structure */
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

/* Global variables */
static int spi_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int init_spi(void);
static int read_gyro_data(int16_t *rate_x);
static void add_to_buffer(circular_buffer_t *cb, gyro_data_t data);
static gyro_data_t get_from_buffer(circular_buffer_t *cb, int index);
static void *buffer_thread(void *arg);
static void signal_handler(int signal);
static void cleanup(void);

/* Initialize SPI interface */
static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

/* Read gyroscope data from ADXRS290 */
static int read_gyro_data(int16_t *rate_x) {
    char tx_buf[3];
    char rx_buf[3];

    /* Read RATE_XL (0x02) */
    tx_buf[0] = ADXRS290_REG_RATE_XL | 0x80; /* MSB=1 for read */
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "Error reading RATE_XL\n");
        return -1;
    }
    *rate_x = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);

    /* Read RATE_XH (0x03) */
    tx_buf[0] = ADXRS290_REG_RATE_XH | 0x80;
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "Error reading RATE_XH\n");
        return -1;
    }
    *rate_x |= (int16_t)((rx_buf[1] << 8) | rx_buf[2]);

    return 0;
}

/* Add data to the circular buffer */
static void add_to_buffer(circular_buffer_t *cb, gyro_data_t data) {
    pthread_mutex_lock(&cb->mutex);
    cb->buffer[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
    pthread_mutex_unlock(&cb->mutex);
}

/* Get data from the circular buffer */
static gyro_data_t get_from_buffer(circular_buffer_t *cb, int index) {
    gyro_data_t data = {0};
    pthread_mutex_lock(&cb->mutex);
    if (index >= 0 && index < cb->count) {
        int actual_index = (cb->tail + index) % BUFFER_SIZE;
        data = cb->buffer[actual_index];
    }
    pthread_mutex_unlock(&cb->mutex);
    return data;
}

/* Thread function to handle the circular buffer */
static void *buffer_thread(void *arg) {
    (void)arg;
    while (program_running) {
        int16_t rate_x;
        if (read_gyro_data(&rate_x) == 0) {
            gyro_data_t data;
            clock_gettime(CLOCK_MONOTONIC, &data.timestamp);
            data.rate_x = rate_x;
            add_to_buffer(&gyro_buffer, data);

            double angular_velocity = (double)rate_x / SENSITIVITY;
            if (fabs(angular_velocity) > ANGULAR_VELOCITY_THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        }
        gpioDelay(10000); /* 10 ms delay */
    }
    return NULL;
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Initialize SPI */
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    /* Set LED GPIO as output */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Initialize circular buffer */
    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;
    gyro_buffer.count = 0;
    pthread_mutex_init(&gyro_buffer.mutex, NULL);

    /* Set up signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Create buffer thread */
    pthread_t buffer_thread_id;
    if (pthread_create(&buffer_thread_id, NULL, buffer_thread, NULL) != 0) {
        fprintf(stderr, "Error creating buffer thread\n");
        cleanup();
        return 1;
    }

    /* Main loop */
    while (program_running) {
        gpioDelay(100000); /* 100 ms delay */
    }

    /* Wait for buffer thread to finish */
    pthread_join(buffer_thread_id, NULL);

    /* Cleanup */
    pthread_mutex_destroy(&gyro_buffer.mutex);
    cleanup();

    return 0;
}

