#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27
#define PWM_RANGE 255
#define PWM_FREQ 100

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    int pins[] = {LAMP1_PIN, LAMP2_PIN, LAMP3_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d as output.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) != 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to initialise PWM to 0 on GPIO%d.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    int pins[] = {LAMP1_PIN, LAMP2_PIN, LAMP3_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
}

static void fade_lamp(int pin, int duration_sec) {
    printf("Fading lamp on GPIO%d from 100%% to 0%% over %d seconds...\n", pin, duration_sec);
    fflush(stdout);

    int steps = 100;
    int delay_ms = (duration_sec * 1000) / steps;
    if (delay_ms < 1) delay_ms = 1;

    for (int i = 0; i <= steps && g_running; i++) {
        int duty = (steps - i) * (PWM_RANGE / steps);
        if (gpioPWM(pin, duty) != 0) {
            fprintf(stderr, "Warning: gpioPWM failed on GPIO%d at step %d.\n", pin, i);
            break;
        }
        printf("  GPIO%d: %d%%\n", pin, (steps - i) * 100 / steps);
        fflush(stdout);
        if (i < steps) {
            gpioDelay(delay_ms * 1000);
        }
    }

    if (gpioPWM(pin, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off GPIO%d.\n", pin);
    }
    printf("Lamp on GPIO%d is off.\n", pin);
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        fprintf(stderr, "  fade_duration_seconds: integer between 1 and 3600\n");
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long duration = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: fade duration must be an integer between 1 and 3600.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator started.\n");
    printf("Fade duration: %ld seconds\n", duration);
    printf("Lamps: GPIO%d, GPIO%d, GPIO%d\n", LAMP1_PIN, LAMP2_PIN, LAMP3_PIN);
    printf("Press Ctrl+C to stop early.\n");
    fflush(stdout);

    fade_lamp(LAMP1_PIN, (int)duration);
    if (!g_running) {
        printf("\nInterrupted by signal. Shutting down...\n");
        cleanup_gpio();
        return EXIT_SUCCESS;
    }

    fade_lamp(LAMP2_PIN, (int)duration);
    if (!g_running) {
        printf("\nInterrupted by signal. Shutting down...\n");
        cleanup_gpio();
        return EXIT_SUCCESS;
    }

    fade_lamp(LAMP3_PIN, (int)duration);
    if (!g_running) {
        printf("\nInterrupted by signal. Shutting down...\n");
        cleanup_gpio();
        return EXIT_SUCCESS;
    }

    printf("Smart Sunset Simulator complete.\n");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

