#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RED_PIN    17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define BLUE_PIN   24

#define RED_DURATION    10
#define YELLOW_DURATION 2
#define GREEN_DURATION  10
#define BLUE_DURATION   3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(struct gpiod_line *line, int state) {
    /* Active-low relay: LOW = ON, HIGH = OFF */
    int val = state ? 0 : 1;
    if (gpiod_line_set_value(line, val) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static void all_off(struct gpiod_line *r, struct gpiod_line *y,
                    struct gpiod_line *g, struct gpiod_line *b) {
    set_relay(r, 0);
    set_relay(y, 0);
    set_relay(g, 0);
    set_relay(b, 0);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red = NULL, *yellow = NULL, *green = NULL, *blue = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        return EXIT_FAILURE;
    }

    red = gpiod_chip_get_line(chip, RED_PIN);
    yellow = gpiod_chip_get_line(chip, YELLOW_PIN);
    green = gpiod_chip_get_line(chip, GREEN_PIN);
    blue = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red || !yellow || !green || !blue) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(red, "traffic-light", 1) < 0) {
        perror("gpiod_line_request_output(red)");
        goto cleanup;
    }
    if (gpiod_line_request_output(yellow, "traffic-light", 1) < 0) {
        perror("gpiod_line_request_output(yellow)");
        goto cleanup;
    }
    if (gpiod_line_request_output(green, "traffic-light", 1) < 0) {
        perror("gpiod_line_request_output(green)");
        goto cleanup;
    }
    if (gpiod_line_request_output(blue, "traffic-light", 1) < 0) {
        perror("gpiod_line_request_output(blue)");
        goto cleanup;
    }

    all_off(red, yellow, green, blue);

    while (running) {
        printf("Red\n");
        fflush(stdout);
        if (set_relay(red, 1) < 0) goto cleanup;
        for (int i = 0; i < RED_DURATION && running; i++)
            sleep(1);
        all_off(red, yellow, green, blue);

        printf("Red + Yellow\n");
        fflush(stdout);
        if (set_relay(yellow, 1) < 0) goto cleanup;
        for (int i = 0; i < YELLOW_DURATION && running; i++)
            sleep(1);
        all_off(red, yellow, green, blue);

        printf("Green\n");
        fflush(stdout);
        if (set_relay(green, 1) < 0) goto cleanup;
        for (int i = 0; i < GREEN_DURATION && running; i++)
            sleep(1);
        all_off(red, yellow, green, blue);

        printf("Yellow\n");
        fflush(stdout);
        if (set_relay(blue, 1) < 0) goto cleanup;
        for (int i = 0; i < BLUE_DURATION && running; i++)
            sleep(1);
        all_off(red, yellow, green, blue);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (red) gpiod_line_release(red);
    if (yellow) gpiod_line_release(yellow);
    if (green) gpiod_line_release(green);
    if (blue) gpiod_line_release(blue);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

