#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define I2C_BUS 1
#define MPR121_ADDR 0x5A

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE0_T 0x41
#define MPR121_ELECTRODE0_R 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E
#define MPR121_SOFTRESET 0x80

#define DEBOUNCE_DELAY_MS 100
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d", reg, value, rc);
        log_message(msg);
    }
    return rc;
}

static int mpr121_init(void) {
    if (mpr121_write(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(1000);

    if (mpr121_write(MPR121_ECR, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_DEBOUNCE, 0x21) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG1, 0x0D) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG2, 0x0D) < 0) return -1;
    if (mpr121_write(MPR121_ELECTRODE0_T, 0x0A) < 0) return -1;
    if (mpr121_write(MPR121_ELECTRODE0_R, 0x08) < 0) return -1;
    if (mpr121_write(MPR121_ECR, 0x01) < 0) return -1;

    return 0;
}

static int read_touch_status(void) {
    int lsb = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (lsb < 0) {
        log_message("Failed to read touch status LSB");
        return -1;
    }
    int msb = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (msb < 0) {
        log_message("Failed to read touch status MSB");
        return -1;
    }
    return (msb << 8) | lsb;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    if (log_file) {
        log_message("Program terminated cleanly.");
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen("touch_relay.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    log_message("Program started.");

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to open I2C device: %d", i2c_handle);
        log_message(msg);
        fclose(log_file);
        log_file = NULL;
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() < 0) {
        log_message("MPR121 initialisation failed.");
        cleanup();
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int relay_state = 0;
    int last_touch = 0;

    while (running) {
        int touch_status = read_touch_status();
        if (touch_status < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int electrode0_touched = (touch_status & 0x01) ? 1 : 0;

        if (electrode0_touched && !last_touch) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            touch_status = read_touch_status();
            if (touch_status < 0) continue;
            electrode0_touched = (touch_status & 0x01) ? 1 : 0;

            if (electrode0_touched) {
                relay_state = !relay_state;
                gpioWrite(RELAY_GPIO, relay_state);
                char msg[64];
                snprintf(msg, sizeof(msg), "Relay toggled to %s", relay_state ? "ON" : "OFF");
                log_message(msg);
            }
        }
        last_touch = electrode0_touched;

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

