    int relay_state = 0;
    int last_touch = 0;

    while (running) {
        int touch_status = read_touch_status();
        if (touch_status < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int electrode0_touched = (touch_status & 0x01) ? 1 : 0;

        if (electrode0_touched && !last_touch) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            touch_status = read_touch_status();
            if (touch_status < 0) continue;
            electrode0_touched = (touch_status & 0x01) ? 1 : 0;

            if (electrode0_touched) {
                relay_state = !relay_state;
                gpioWrite(RELAY_GPIO, relay_state);
                char msg[64];
                snprintf(msg, sizeof(msg), "Relay toggled to %s", relay_state ? "ON" : "OFF");
                log_message(msg);
            }
        }
        last_touch = electrode0_touched;

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

