        if (flame_detected < 0) {
            log_event("Error reading flame sensor");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (flame_detected) {
            if (gpiod_line_set_value(buzzer_line, 1) < 0 ||
                gpiod_line_set_value(led_line, 1) < 0) {
                perror("gpiod_line_set_value");
                log_event("Error activating buzzer or LED");
            } else {
                log_event("Flame Detected");
            }
        } else {
            if (gpiod_line_set_value(buzzer_line, 0) < 0 ||
                gpiod_line_set_value(led_line, 0) < 0) {
                perror("gpiod_line_set_value");
                log_event("Error deactivating buzzer or LED");
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nCleaning up and exiting...\n");
    cleanup();
    return 0;
}

