#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DISPENSE_DURATION_MS 1000
#define DISPENSE_INTERVAL_MS 5000
#define HALF_DURATION_US (DISPENSE_DURATION_MS * 1000 / 2)
#define INTERVAL_US (DISPENSE_INTERVAL_MS * 1000)

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int activate_solenoid(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: failed to activate solenoid on GPIO%d\n", pin);
        return -1;
    }
    return 0;
}

static int deactivate_solenoid(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate solenoid on GPIO%d\n", pin);
        return -1;
    }
    return 0;
}

static int dispense(void) {
    if (activate_solenoid(SOLENOID_1_PIN) != 0) return -1;
    gpioDelay(HALF_DURATION_US);
    if (deactivate_solenoid(SOLENOID_1_PIN) != 0) return -1;
    if (activate_solenoid(SOLENOID_2_PIN) != 0) return -1;
    gpioDelay(HALF_DURATION_US);
    if (deactivate_solenoid(SOLENOID_2_PIN) != 0) return -1;
    return 0;
}

static int log_dispense(int pin1, int pin2, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: failed to open dispense_log.txt: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Dispensed on GPIO%d and GPIO%d for %d ms\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            pin1, pin2, duration_ms);
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: failed to close dispense_log.txt: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Pneumatic dispensing system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (dispense() != 0) {
            fprintf(stderr, "Error: dispense cycle failed\n");
        } else {
            if (log_dispense(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION_MS) != 0) {
                fprintf(stderr, "Warning: failed to log dispense event\n");
            }
        }
        gpioDelay(INTERVAL_US);
    }

    printf("\nShutting down...\n");
    deactivate_solenoid(SOLENOID_1_PIN);
    deactivate_solenoid(SOLENOID_2_PIN);
    gpioTerminate();
    printf("Pneumatic dispensing system stopped.\n");
    return 0;
}

