#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_FORWARD  17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD  22
#define MOTOR_B_BACKWARD 23
#define MOTOR_A_ENABLE   24
#define MOTOR_B_ENABLE   25

#define PWM_RANGE 255
#define PWM_FREQ  1000
#define LOOP_DELAY_US 50000
#define OBSTACLE_THRESHOLD_CM 20.0f
#define MAX_TILT_ERROR 10.0f

#define KP 1.0f
#define KI 0.01f
#define KD 0.1f

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void stop_motors(void) {
    gpioPWM(MOTOR_A_ENABLE, 0);
    gpioPWM(MOTOR_B_ENABLE, 0);
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);
}

static void set_motor_speed(int motor, int speed) {
    int fwd_pin, bwd_pin, en_pin;
    if (motor == 0) {
        fwd_pin = MOTOR_A_FORWARD;
        bwd_pin = MOTOR_A_BACKWARD;
        en_pin  = MOTOR_A_ENABLE;
    } else {
        fwd_pin = MOTOR_B_FORWARD;
        bwd_pin = MOTOR_B_BACKWARD;
        en_pin  = MOTOR_B_ENABLE;
    }

    if (speed > 0) {
        gpioWrite(bwd_pin, 0);
        gpioWrite(fwd_pin, 1);
        gpioPWM(en_pin, speed);
    } else if (speed < 0) {
        gpioWrite(fwd_pin, 0);
        gpioWrite(bwd_pin, 1);
        gpioPWM(en_pin, -speed);
    } else {
        gpioWrite(fwd_pin, 0);
        gpioWrite(bwd_pin, 0);
        gpioPWM(en_pin, 0);
    }
}

static float simulate_tilt_error(void) {
    return ((float)rand() / (float)RAND_MAX) * 2.0f * MAX_TILT_ERROR - MAX_TILT_ERROR;
}

static float simulate_distance(void) {
    return ((float)rand() / (float)RAND_MAX) * 398.0f + 2.0f;
}

static void avoid_obstacle(void) {
    set_motor_speed(0, -128);
    set_motor_speed(1, -128);
    gpioDelay(200000);
    set_motor_speed(0, 0);
    set_motor_speed(1, 0);
}

static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n",
            timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

int main(void) {
    float integral = 0.0f;
    float prev_error = 0.0f;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: could not open balance_log.txt for appending.\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
