#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int light_state = 0;
    int ret;

    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure touch sensor pin as input with internal pull-down */
    ret = gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input (ret=%d).\n", TOUCH_SENSOR_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    ret = gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d (ret=%d).\n", TOUCH_SENSOR_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output and ensure it starts OFF */
    ret = gpioSetMode(RELAY_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output (ret=%d).\n", RELAY_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    ret = gpioWrite(RELAY_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to initialise relay state on GPIO%d (ret=%d).\n", RELAY_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Light Switch ready. Touch sensor on GPIO%d toggles relay on GPIO%d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        /* TTP223 outputs HIGH when touched */
        int touch_detected = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_detected < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d (ret=%d).\n", TOUCH_SENSOR_PIN, touch_detected);
            break;
        }

        if (touch_detected == 1) {
            /* Debounce delay */
            gpioDelay(DEBOUNCE_DELAY_US);

            /* Re-read to confirm touch */
            touch_detected = gpioRead(TOUCH_SENSOR_PIN);
            if (touch_detected < 0) {
                fprintf(stderr, "Error: failed to read GPIO%d (ret=%d).\n", TOUCH_SENSOR_PIN, touch_detected);
                break;
            }

            if (touch_detected == 1) {
                /* Toggle the light state */
                light_state = !light_state;
                ret = gpioWrite(RELAY_PIN, light_state);
                if (ret != 0) {
                    fprintf(stderr, "Error: failed to write GPIO%d (ret=%d).\n", RELAY_PIN, ret);
                    break;
                }
                printf("Touch detected! Light %s.\n", light_state ? "ON" : "OFF");

                /* Wait for touch release to avoid repeated toggles */
                while (running) {
                    touch_detected = gpioRead(TOUCH_SENSOR_PIN);
                    if (touch_detected < 0) {
                        fprintf(stderr, "Error: failed to read GPIO%d (ret=%d).\n", TOUCH_SENSOR_PIN, touch_detected);
                        running = 0;
                        break;
                    }
                    if (touch_detected == 0) {
                        break;
                    }
                    gpioDelay(10000); /* 10 ms poll */
                }
            }
        }

        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* Clean shutdown: turn off relay and terminate pigpio */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

