/*
 * Mood light for Raspberry Pi 3 Model B+ using pigpio and ALSA.
 *
 * Build:
 *   gcc -O2 -Wall -o mood_light mood_light.c -lpigpio -lasound -lm
 *
 * Wiring (common-cathode RGB LED, current-limiting resistors):
 *   Red   -> GPIO17 (physical pin 11)
 *   Green -> GPIO18 (physical pin 12)
 *   Blue  -> GPIO27 (physical pin 13)
 *   Common cathode -> GND
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#if defined(ALSA_AVAILABLE)
#include <alsa/asoundlib.h>
#endif

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define PWM_RANGE 255
#define PWM_FREQ  1000  /* Hz */

#define SAMPLE_RATE 8000
#define PERIOD_SIZE 1024
#define CHANNELS    1
#define BITS_PER_SAMPLE 16

#define UPDATE_DELAY_US 10000  /* 10 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Map RMS amplitude (0.0 .. 1.0) to RGB PWM values.
 * Low amplitude -> cool (blue, green, red), high amplitude -> warm (red, green, blue).
 */
static void amplitude_to_rgb(float amplitude, int *r, int *g, int *b)
{
    float s = amplitude;
    if (s < 0.0f) s = 0.0f;
    if (s > 1.0f) s = 1.0f;

    *r = (int)(s * 255.0f);
    *g = (int)(s * 255.0f);
    *b = (int)((1.0f - s) * 255.0f);
}

static int set_led_color(int r, int g, int b)
{
    if (gpioPWM(RED_PIN, r) < 0) {
        fprintf(stderr, "gpioPWM(RED) failed\n");
        return -1;
    }
    if (gpioPWM(GREEN_PIN, g) < 0) {
        fprintf(stderr, "gpioPWM(GREEN) failed\n");
        return -1;
    }
    if (gpioPWM(BLUE_PIN, b) < 0) {
        fprintf(stderr, "gpioPWM(BLUE) failed\n");
        return -1;
    }
    return 0;
}

#if defined(ALSA_AVAILABLE)

static int init_alsa(snd_pcm_t **pcm)
{
    int err;

    err = snd_pcm_open(pcm, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_open failed: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_set_params(*pcm,
                             SND_PCM_FORMAT_S16_LE,
                             SND_PCM_ACCESS_RW_INTERLEAVED,
                             CHANNELS,
                             SAMPLE_RATE,
                             1,
                             PERIOD_SIZE);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_set_params failed: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm);
        *pcm = NULL;
        return -1;
    }

    err = snd_pcm_prepare(*pcm);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_prepare failed: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm);
        *pcm = NULL;
        return -1;
    }

    return 0;
}

static int read_audio(snd_pcm_t *pcm, short *buffer, int frames)
{
    int err = snd_pcm_readi(pcm, buffer, frames);
    if (err == -EPIPE) {
        fprintf(stderr, "ALSA underrun: resynchronizing\n");
        snd_pcm_prepare(pcm);
        return -1;
    } else if (err < 0) {
        if (err == -ESTRPIPE) {
            fprintf(stderr, "ALSA suspend: resuming\n");
            while (err == -ESTRPIPE) {
                err = snd_pcm_resume(pcm);
                if (err < 0)
                    err = snd_pcm_prepare(pcm);
            }
            return -1;
        }
        fprintf(stderr, "snd_pcm_readi failed: %s\n", snd_strerror(err));
        return -1;
    }
    return err;
}

static float calculate_rms(const short *buffer, int frames)
{
    double sum_sq = 0.0;
    for (int i = 0; i < frames; i++) {
        double s = (double)buffer[i];
        sum_sq += s * s;
    }
    return (float)sqrt(sum_sq / (double)frames);
}

#else

/*
 * ALSA unavailable: simulate audio with a sine wave so the mood light
 * still cycles through colors.
 */
static int init_alsa(snd_pcm_t **pcm)
{
    (void)pcm;
    return 0;
}

static int read_audio(snd_pcm_t *pcm, short *buffer, int frames)
{
    static double phase = 0.0;
    double freq = 440.0;
    double amplitude = 32000.0;

    for (int i = 0; i < frames; i++) {
        buffer[i] = (short)(amplitude * sin(2.0 * M_PI * freq * phase / SAMPLE_RATE));
        phase += 1.0;
    }
    return frames;
}

static float calculate_rms(const short *buffer, int frames)
{
    double sum_sq = 0.0;
    for (int i = 0; i < frames; i++) {
        double s = (double)buffer[i];
        sum_sq += s * s;
    }
    return (float)sqrt(sum_sq / (double)frames);
}

#endif

int main(int argc, char *argv[])
{
    float sensitivity = 1.0f;

    if (argc > 1) {
        sensitivity = (float)atof(argv[1]);
        if (sensitivity <= 0.0f) {
            fprintf(stderr, "Sensitivity must be positive. Using default 1.0.\n");
            sensitivity = 1.0f;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(RED) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(GREEN) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(BLUE) failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange(RED) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange(GREEN) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange(BLUE) failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency(RED) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency(GREEN) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency(BLUE) failed\n");
        gpioTerminate();
        return 1;
    }

    /* Start with the LED off */
    if (set_led_color(0, 0, 0) < 0) {
        gpioTerminate();
        return 1;
    }

    snd_pcm_t *pcm = NULL;
    short *audio_buffer = NULL;
    int ret_code = 0;

#if defined(ALSA_AVAILABLE)
    if (init_alsa(&pcm) < 0) {
        fprintf(stderr, "Failed to initialize ALSA. Continuing with simulated audio.\n");
    }
#endif

    audio_buffer = (short *)malloc((size_t)PERIOD_SIZE * sizeof(short));
    if (audio_buffer == NULL) {
        fprintf(stderr, "Failed to allocate audio buffer\n");
        ret_code = 1;
        goto cleanup;
    }

    printf("Mood light started. Sensitivity: %.2f\n", sensitivity);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int frames_read = read_audio(pcm, audio_buffer, PERIOD_SIZE);
        if (frames_read < 0) {
            /* Error already reported; continue or exit depending on mode */
            if (pcm == NULL) {
