                continue;
            }
            /* ALSA mode: error already handled in read_audio */
            gpioDelay(UPDATE_DELAY_US);
            continue;
        }

        if (frames_read == 0) {
            gpioDelay(UPDATE_DELAY_US);
            continue;
        }

        float rms = calculate_rms(audio_buffer, frames_read);
        float amplitude = (float)rms / 32768.0f;
        amplitude *= sensitivity;

        if (amplitude > 1.0f) amplitude = 1.0f;
        if (amplitude < 0.0f) amplitude = 0.0f;

        int r, g, b;
        amplitude_to_rgb(amplitude, &r, &g, &b);

        if (set_led_color(r, g, b) < 0) {
            fprintf(stderr, "Failed to set LED color\n");
            ret_code = 1;
            break;
        }

        gpioDelay(UPDATE_DELAY_US);
    }

cleanup:
    printf("\nShutting down...\n");
    set_led_color(0, 0, 0);

    if (audio_buffer != NULL) {
        free(audio_buffer);
    }

    if (pcm != NULL) {
        snd_pcm_drain(pcm);
        snd_pcm_close(pcm);
    }

    gpioTerminate();
    return ret_code;
}

