#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = { (char)(TCS34725_COMMAND_BIT | reg), (char)value };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, pigpio_error(i2c_handle));
        return -1;
    }
    return 0;
}

static int read_block(uint8_t reg, uint8_t *data, uint32_t len) {
    char cmd = (char)(TCS34725_COMMAND_BIT | reg);
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error setting read reg 0x%02X: %s\n", reg, pigpio_error(i2c_handle));
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)data, len) != (int)len) {
        fprintf(stderr, "Error reading %u bytes from reg 0x%02X\n", len, reg);
        return -1;
    }
    return 0;
}

static int init_sensor(void) {
    if (write_reg(TCS34725_ENABLE, 0x03) != 0) return -1;
    if (write_reg(TCS34725_ATIME, 0xD5) != 0) return -1;
    return 0;
}

static int read_sensor(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t data[8];
    if (read_block(TCS34725_CDATA, data, 8) != 0) return -1;
    *clear = (uint16_t)data[1] << 8 | data[0];
    *red   = (uint16_t)data[3] << 8 | data[2];
    *green = (uint16_t)data[5] << 8 | data[4];
    *blue  = (uint16_t)data[7] << 8 | data[6];
    return 0;
}

static void log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t now = time(NULL);
    fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)now, clear, red, green, blue);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fp = fopen("color_data.csv", "a");
    if (!fp) {
        perror("Error opening color_data.csv");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,clear,red,green,blue\n");
        fflush(fp);
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        uint16_t clear, red, green, blue;
        if (read_sensor(&clear, &red, &green, &blue) == 0) {
            log_data(clear, red, green, blue);
        } else {
            fprintf(stderr, "Read failed; logging zeros\n");
            log_data(0, 0, 0, 0);
        }
        gpioDelay(500000);
    }

    if (fp) fclose(fp);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

