#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define NUM_LAMPS 4
#define CHIP_NAME "gpiochip0"

/* BCM GPIO pin numbers for the four relay modules */
static const unsigned int lamp_pins[NUM_LAMPS] = {17, 27, 22, 23};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_LAMPS];
static volatile sig_atomic_t running = 1;

static void cleanup(void) {
    for (int i = 0; i < NUM_LAMPS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1); /* relay OFF (active-low) */
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    for (int i = 0; i < NUM_LAMPS; i++) {
        lines[i] = gpiod_chip_get_line(chip, lamp_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %u\n", lamp_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(lines[i], "sunrise-sim", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %u\n", lamp_pins[i]);
            return -1;
        }
    }
    return 0;
}

static void set_all_lamps(int value) {
    for (int i = 0; i < NUM_LAMPS; i++) {
        gpiod_line_set_value(lines[i], value);
    }
}

static void sunrise_phase(int duration_sec) {
    int steps = 100;
    int delay_ms = (duration_sec * 1000) / steps;
    for (int i = 0; i < steps && running; i++) {
        int duty = (i * 100) / steps; /* 0..100 */
        for (int j = 0; j < NUM_LAMPS; j++) {
            int val = (duty > 0) ? 0 : 1; /* active-low: 0 = ON */
            gpiod_line_set_value(lines[j], val);
        }
