#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTION_SENSOR_GPIO 17
#define VIDEO_DURATION 5
#define DEBOUNCE_DELAY_MS 200
#define LOG_FILE_PATH "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    gpioSetMode(MOTION_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(MOTION_SENSOR_GPIO, PI_PUD_UP);
    return 0;
}

static int log_motion_event(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE_PATH, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    if (fprintf(log_file, "%s - Motion detected on GPIO %d\n", timestamp, MOTION_SENSOR_GPIO) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int record_video(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];
    char command[512];
    char filepath[256];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", &timeinfo);

    snprintf(filepath, sizeof(filepath), "%s%s.h264", VIDEO_DIR, timestamp);

    snprintf(command, sizeof(command),
             "raspivid -o %s -t %d -w 640 -h 480 -fps 30",
             filepath, VIDEO_DURATION * 1000);

    int result = system(command);
    if (result == -1) {
        perror("Error executing raspivid command");
        return -1;
    } else if (result != 0) {
        fprintf(stderr, "Error: raspivid exited with status %d\n", result);
        return -1;
    }

    printf("Video saved to %s\n", filepath);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting up SIGINT handler");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", MOTION_SENSOR_GPIO);

    while (running) {
        int motion_detected = (gpioRead(MOTION_SENSOR_GPIO) == 0);

        if (motion_detected) {
            printf("Motion detected!\n");

            if (log_motion_event() != 0) {
                fprintf(stderr, "Warning: Failed to log motion event.\n");
            }

            if (record_video() != 0) {
                fprintf(stderr, "Warning: Failed to record video.\n");
            }

            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
    return 0;
}

