        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (init_mpu6050() < 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
        fflush(log_file);
    }

    gyro_data_t gyro_data;
    int reinit_attempts = 0;

    while (!terminate) {
        if (read_gyro_data(&gyro_data) == 0) {
            log_data(&gyro_data);
            reinit_attempts = 0;
        } else {
            fprintf(stderr, "Read failure, re-initializing...\n");
            if (reinit_attempts < MAX_REINIT_RETRIES) {
                if (init_mpu6050() == 0) {
                    reinit_attempts = 0;
                } else {
                    reinit_attempts++;
                }
            } else {
                fprintf(stderr, "Max re-init retries reached, continuing...\n");
                reinit_attempts = 0;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "Shutting down...\n");
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

