#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_gpio_write(unsigned pin, int level) {
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %d) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_gpio_read(unsigned pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%u) failed\n", pin);
    }
    return v;
}

static int simulate_moisture_sensor(void) {
    return rand() % 101;
}

static void control_relay(unsigned pin, int moisture_level) {
    int level = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1;
    if (safe_gpio_write(pin, level) == 0) {
        printf("Relay on BCM %u set to %s (moisture=%d)\n",
               pin, level ? "OFF" : "ON", moisture_level);
    }
}

static void log_data(int moisture1, int moisture2, int moisture3,
                     int moisture4, int relay1_state, int relay2_state,
                     int relay3_state, int relay4_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Z1:%d, Z2:%d, Z3:%d, Z4:%d, R1:%d, R2:%d, R3:%d, R4:%d\n",
                timestamp, moisture1, moisture2, moisture3, moisture4,
                relay1_state, relay2_state, relay3_state, relay4_state);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    unsigned pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int moisture_levels[4];
    int relay_states[4];

    srand((unsigned)time(NULL));

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode(%u, PI_OUTPUT) failed\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (safe_gpio_write(pins[i], 1) < 0) {
            fprintf(stderr, "Error: failed to deactivate relay on BCM %u\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot install SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart Greenhouse Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < 4; i++) {
            moisture_levels[i] = simulate_moisture_sensor();
            control_relay(pins[i], moisture_levels[i]);
            relay_states[i] = safe_gpio_read(pins[i]);
        }

        log_data(moisture_levels[0], moisture_levels[1], moisture_levels[2],
                 moisture_levels[3], relay_states[0], relay_states[1],
                 relay_states[2], relay_states[3]);

        gpioDelay(POLL_INTERVAL_SEC * 1000000);
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < 4; i++) {
        safe_gpio_write(pins[i], 1);
    }
    cleanup();
    return EXIT_SUCCESS;
}

