#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <unistd.h>

#define ADXL345_ADDRESS 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define ALARM_GPIO 27
#define FREEFALL_THRESHOLD 0.2
#define FREEFALL_DURATION 0.5
#define SAMPLE_INTERVAL 0.1
#define SCALE_FACTOR 256.0

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_adxl345(int handle) {
    if (i2cWriteByteData(handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing DATA_FORMAT register\n");
        return -1;
    }
    if (i2cWriteByteData(handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing POWER_CTL register\n");
        return -1;
    }
    return 0;
}

static int read_accelerometer(int handle, float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *x = (float)raw_x / SCALE_FACTOR;
    *y = (float)raw_y / SCALE_FACTOR;
    *z = (float)raw_z / SCALE_FACTOR;
    return 0;
}

static int is_freefall(float x, float y, float z) {
    return (fabs(x) < FREEFALL_THRESHOLD &&
            fabs(y) < FREEFALL_THRESHOLD &&
            fabs(z) < FREEFALL_THRESHOLD);
}

static void trigger_alarm(int gpio_pin) {
    gpioWrite(gpio_pin, 1);
    gpioDelay(5000000);
    gpioWrite(gpio_pin, 0);
}

static void log_freefall_event(float x, float y, float z) {
    FILE *fp = fopen("freefall.log", "a");
    if (!fp) {
        fprintf(stderr, "Error opening freefall.log\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_adxl345(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Freefall detection started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float x, y, z;
        if (read_accelerometer(i2c_handle, &x, &y, &z) < 0) {
            gpioDelay(100000);
            continue;
        }

        if (is_freefall(x, y, z)) {
            time_t start_time = time(NULL);
            while (is_freefall(x, y, z) && !terminate) {
                if (read_accelerometer(i2c_handle, &x, &y, &z) < 0) break;
                if (difftime(time(NULL), start_time) >= FREEFALL_DURATION) {
                    trigger_alarm(ALARM_GPIO);
                    log_freefall_event(x, y, z);
                    break;
                }
                gpioDelay(100000);
            }
        }
        gpioDelay(100000);
    }

    gpioWrite(ALARM_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

