#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 18
#define TRIGGER_PULSE_US 10
#define MEASUREMENT_INTERVAL_US 200000
#define ECHO_TIMEOUT_US 100000
#define MAX_PULSE_WIDTH_US 23200
#define LOG_FILE "distance_log.txt"

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick = 0;
static volatile int g_echo_received = 0;
static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *g_log_file = NULL;
static volatile sig_atomic_t g_running = 1;

static void echo_rising_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    if (level == 1) {
        pthread_mutex_lock(&g_mutex);
        g_start_tick = tick;
        g_echo_received = 0;
        pthread_mutex_unlock(&g_mutex);
    }
}

static void echo_falling_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    if (level == 0) {
        pthread_mutex_lock(&g_mutex);
        g_end_tick = tick;
        g_echo_received = 1;
        pthread_mutex_unlock(&g_mutex);
    }
}

static void trigger_pulse(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static int read_distance(float *distance_cm)
{
    pthread_mutex_lock(&g_mutex);
    g_start_tick = 0;
    g_end_tick = 0;
    g_echo_received = 0;
    pthread_mutex_unlock(&g_mutex);

    trigger_pulse();

    uint32_t start_wait = gpioTick();
    while (!g_echo_received) {
        if ((int32_t)(gpioTick() - start_wait) > ECHO_TIMEOUT_US) {
            return -1;
        }
        gpioDelay(100);
    }

    uint32_t start, end;
    pthread_mutex_lock(&g_mutex);
    start = g_start_tick;
    end = g_end_tick;
    pthread_mutex_unlock(&g_mutex);

    uint32_t pulse_width = end - start;
    if (pulse_width > MAX_PULSE_WIDTH_US) {
        return -2;
    }

    *distance_cm = (float)pulse_width / 58.0f;
    return 0;
}

static void log_distance(float distance_cm)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

    if (fprintf(g_log_file, "%lld,%.2f\n", timestamp_ns, distance_cm) < 0) {
        perror("fprintf");
    }
    fflush(g_log_file);
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    if (gpioSetAlertFunc(0, NULL) != 0) {
        fprintf(stderr, "Failed to clear alert functions\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFunc(ECHO_PIN, echo_rising_callback) != 0) {
        fprintf(stderr, "Failed to set rising-edge alert\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFunc(ECHO_PIN, echo_falling_callback) != 0) {
        fprintf(stderr, "Failed to set falling-edge alert\n");
        gpioSetAlertFunc(ECHO_PIN, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
