#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define BUZZER_GPIO 17
#define SENSITIVITY 16384.0f
#define DEFAULT_FREEFALL_THRESHOLD 0.2f
#define DEFAULT_IMPACT_THRESHOLD 1.5f
#define MAX_RETRIES 3

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByteData(i2c_handle, reg, val);
        if (rc == 0) return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d): %d\n", reg, attempt + 1, rc);
        gpioDelay(10000);
    }
    return -1;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
        if (rc == (int)len) return 0;
        fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d): got %d, expected %u\n", reg, attempt + 1, rc, len);
        gpioDelay(10000);
    }
    return -1;
}

static int init_lis3dh(void) {
    if (i2c_write_reg(CTRL_REG1, 0x77) != 0) {
        fprintf(stderr, "Failed to configure CTRL_REG1\n");
        return -1;
    }
    if (i2c_write_reg(CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Failed to configure CTRL_REG4\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(OUT_X_L, buf, 6) != 0) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x / SENSITIVITY;
    *y = (float)raw_y / SENSITIVITY;
    *z = (float)raw_z / SENSITIVITY;
    return 0;
}

static bool detect_freefall(float x, float y, float z, float threshold) {
    float mag = sqrtf(x * x + y * y + z * z);
    return mag < threshold;
}

static bool detect_impact(float x, float y, float z, float threshold) {
    float mag = sqrtf(x * x + y * y + z * z);
    return mag > threshold;
}

static void activate_buzzer(int gpio, int duration_ms) {
    gpioWrite(gpio, 1);
    gpioDelay(duration_ms * 1000);
    gpioWrite(gpio, 0);
}

int main(int argc, char *argv[]) {
    float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    float impact_threshold = DEFAULT_IMPACT_THRESHOLD;

    if (argc > 1) freefall_threshold = strtof(argv[1], NULL);
    if (argc > 2) impact_threshold = strtof(argv[2], NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %d\n", I2C_BUS, LIS3DH_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_lis3dh() != 0) {
        fprintf(stderr, "LIS3DH initialization failed (sensor absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Freefall threshold: %.3fg, Impact threshold: %.3fg\n", freefall_threshold, impact_threshold);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;
        if (read_acceleration(&x, &y, &z) != 0) {
            fprintf(stderr, "Read error, continuing...\n");
            gpioDelay(100000);
            continue;
        }

        if (detect_freefall(x, y, z, freefall_threshold)) {
            printf("Freefall detected!\n");
        }

        if (detect_impact(x, y, z, impact_threshold)) {
            printf("Impact detected!\n");
            activate_buzzer(BUZZER_GPIO, 1000);
        }

        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    gpioWrite(BUZZER_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

