#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* LIS3DH register addresses */
#define LIS3DH_REG_CTRL1      0x20
#define LIS3DH_REG_CTRL4      0x23
#define LIS3DH_REG_OUT_X_L    0x28
#define LIS3DH_REG_WHO_AM_I   0x0F
#define LIS3DH_WHO_AM_I_VAL   0x33

/* Configuration values */
#define CTRL1_VAL 0x57  /* 100 Hz, all axes enabled, normal mode */
#define CTRL4_VAL 0x88  /* High-resolution mode, ±2g range */

/* Sensitivity for ±2g, high-resolution: 0.0009765625 g/LSB */
#define SENSITIVITY 0.0009765625f

/* Default values */
#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD   2.0f
#define LOG_FILE            "/var/log/high_acceleration.log"
#define SAMPLE_INTERVAL_US  100000  /* 100 ms */

/* Globals for cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

/* Read a single byte from a register; returns -1 on error */
static int read_register(int handle, uint8_t reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

/* Write a single byte to a register; returns 0 on success, -1 on error */
static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %d\n",
                value, reg, result);
        return -1;
    }
    return 0;
}

/* Initialize the LIS3DH accelerometer */
static int init_accelerometer(int handle) {
    int who_am_i = read_register(handle, LIS3DH_REG_WHO_AM_I);
    if (who_am_i < 0) {
        return -1;
    }
    if (who_am_i != LIS3DH_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, LIS3DH_WHO_AM_I_VAL);
        return -1;
    }

    if (write_register(handle, LIS3DH_REG_CTRL1, CTRL1_VAL) < 0) {
        return -1;
    }
    if (write_register(handle, LIS3DH_REG_CTRL4, CTRL4_VAL) < 0) {
        return -1;
    }
    return 0;
}

/* Read acceleration data from the LIS3DH */
static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(handle, LIS3DH_REG_OUT_X_L | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        *x = *y = *z = 0.0f;
        return -1;
    }

    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    /* High-resolution mode: 12-bit left-justified, shift right 4 */
    *x = (float)(raw_x >> 4) * SENSITIVITY;
    *y = (float)(raw_y >> 4) * SENSITIVITY;
    *z = (float)(raw_z >> 4) * SENSITIVITY;

    return 0;
}

/* Log a high-acceleration event to the log file */
static void log_high_acceleration(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - High acceleration detected: X=%.3f g, Y=%.3f g, Z=%.3f g\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fclose(fp);
}

/* Trigger a system shutdown */
static void trigger_shutdown(void) {
    printf("High acceleration threshold exceeded! Shutting down system...\n");
    int result = system("sudo shutdown -h now");
    if (result != 0) {
        fprintf(stderr, "Error triggering shutdown: %d\n", result);
    }
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    float threshold = DEFAULT_THRESHOLD;
    int opt;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 16);
                if (i2c_address < 0x08 || i2c_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address: 0x%02X (must be 0x08-0x77)\n", i2c_address);
                    return 1;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Threshold must be greater than 0\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold_g]\n", argv[0]);
                return 1;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 (default for Raspberry Pi 5) */
    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n",
                i2c_address, i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize the accelerometer */
    if (init_accelerometer(i2c_handle) < 0) {
        fprintf(stderr, "Error initializing accelerometer at address 0x%02X\n", i2c_address);
        cleanup();
        return 1;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error setting up SIGINT handler");
        cleanup();
        return 1;
    }

    printf("Monitoring accelerometer at address 0x%02X. Threshold: %.2f g. Press Ctrl+C to exit.\n",
           i2c_address, threshold);

    /* Main loop */
    while (program_running) {
        float x, y, z;

        if (read_acceleration(i2c_handle, &x, &y, &z) < 0) {
            /* Sensor read error: log and continue */
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold) {
            printf("High acceleration detected: X=%.3f g, Y=%.3f g, Z=%.3f g\n", x, y, z);
            log_high_acceleration(x, y, z);
            trigger_shutdown();
            break;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

