#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define SI7210_REG_FIELD 0xC0
#define SI7210_REG_CTRL 0xC1
#define SI7210_CTRL_START 0x01
#define SI7210_CTRL_READY 0x00
#define RELAY_GPIO 17
#define THRESHOLD_MT 5.0f
#define SAMPLE_INTERVAL_US 100000
#define MAX_POLL_ATTEMPTS 50
#define LOG_FILE "magnetic_events.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s %s\n", ts, msg);
    } else {
        fprintf(fp, "(no-time) %s\n", msg);
    }
    fclose(fp);
}

static int read_field_mT_x100(int handle, int16_t *out) {
    if (i2cWriteByteData(handle, SI7210_REG_CTRL, SI7210_CTRL_START) < 0) {
        log_event("ERROR: failed to start measurement");
        return -1;
    }
    for (int i = 0; i < MAX_POLL_ATTEMPTS; i++) {
        int ready = i2cReadByteData(handle, SI7210_REG_CTRL);
        if (ready < 0) {
            log_event("ERROR: failed to read control register");
            return -1;
        }
        if ((ready & 0x01) == SI7210_CTRL_READY) break;
        gpioDelay(1000);
        if (i == MAX_POLL_ATTEMPTS - 1) {
            log_event("ERROR: measurement timeout");
            return -1;
        }
    }
    int lsb = i2cReadByteData(handle, SI7210_REG_FIELD);
    if (lsb < 0) {
        log_event("ERROR: failed to read LSB");
        return -1;
    }
    int msb = i2cReadByteData(handle, SI7210_REG_FIELD + 1);
    if (msb < 0) {
        log_event("ERROR: failed to read MSB");
        return -1;
    }
    int16_t raw = (int16_t)((msb << 8) | lsb);
    *out = (int16_t)((raw * 25) / 1000);
    return 0;
}

static void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) < 0) {
        log_event("ERROR: gpioWrite failed");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        log_event("ERROR: gpioSetMode failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_relay(0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    log_event("INFO: Si7210 monitor started");
    int relay_state = 0;
    while (running) {
        int16_t field_mT_x100 = 0;
        if (read_field_mT_x100(i2c_handle, &field_mT_x100) == 0) {
            float field_mT = field_mT_x100 / 100.0f;
            char msg[128];
            snprintf(msg, sizeof(msg), "Field: %.2f mT", field_mT);
            log_event(msg);
            int new_state = (field_mT > THRESHOLD_MT) ? 1 : 0;
            if (new_state != relay_state) {
                control_relay(new_state);
                relay_state = new_state;
                snprintf(msg, sizeof(msg), "Relay %s", relay_state ? "ON" : "OFF");
                log_event(msg);
            }
        } else {
            control_relay(0);
            relay_state = 0;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    log_event("INFO: shutting down");
    control_relay(0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

