#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define RELAY_GPIO   18
#define FLOW_THRESHOLD 5.0f
#define SCALE_FACTOR  (1.0f / 1500.0f)
#define POLL_DELAY_US 100000
#define LOG_FILE "flow_log.txt"

static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int initialize_sensor(int handle) {
    uint8_t cmd[2] = {0x36, 0x08};
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to start measurement on handle %d\n", handle);
        return -1;
    }
    return 0;
}

static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t buf[3];
    int bytes = i2cReadDevice(handle, (char *)buf, 3);
    if (bytes != 3) {
        fprintf(stderr, "Error: I2C read failed on handle %d (got %d bytes)\n", handle, bytes);
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on handle %d\n", handle);
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw * SCALE_FACTOR;
    return 0;
}

static int control_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error: Failed to write GPIO %d to %d\n", gpio, state);
        return -1;
    }
    return 0;
}

static int log_flow_rates(float f1, float f2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Cannot open %s for appending\n", LOG_FILE);
        return -1;
    }
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error: clock_gettime failed\n");
        fclose(fp);
        return -1;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld, Sensor1: %.2f, Sensor2: %.2f\n",
            timestamp, ts.tv_nsec / 1000000, f1, f2);
    fflush(fp);
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle1 = i2cOpen(1, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error: Could not open I2C for sensor 1 (addr 0x%02X): %d\n",
                SENSOR1_ADDR, i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle2 = i2cOpen(1, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error: Could not open I2C for sensor 2 (addr 0x%02X): %d\n",
                SENSOR2_ADDR, i2c_handle2);
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor(i2c_handle1) != 0 || initialize_sensor(i2c_handle2) != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO %d low\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to install signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int r1 = read_flow_rate(i2c_handle1, &f1);
        int r2 = read_flow_rate(i2c_handle2, &f2);

        if (r1 == 0 && r2 == 0) {
            if (f1 < FLOW_THRESHOLD || f2 < FLOW_THRESHOLD) {
                if (control_relay(RELAY_GPIO, 1) != 0) {
                    fprintf(stderr, "Warning: Relay energize failed\n");
                }
            } else {
                if (control_relay(RELAY_GPIO, 0) != 0) {
                    fprintf(stderr, "Warning: Relay de-energize failed\n");
                }
            }
            if (log_flow_rates(f1, f2) != 0) {
                fprintf(stderr, "Warning: Logging failed\n");
            }
        } else {
            fprintf(stderr, "Warning: Skipping cycle due to read error\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

