#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

#define POLL_INTERVAL_US  200000   /* 200 ms */
#define MOTOR_RUN_US      5000000  /* 5 s   */
#define SUPPRESS_POLLS    3        /* 3 x 200 ms = 600 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_write(unsigned pin, unsigned level, const char *label)
{
    if (gpioWrite(pin, level) < 0) {
        syslog(LOG_ERR, "gpioWrite(%s=%u, %u) failed", label, pin, level);
        return -1;
    }
    return 0;
}

static int motor_stop(void)
{
    int rc = 0;
    rc |= safe_write(MOTOR_ENABLE_PIN, 0, "ENA");
    rc |= safe_write(MOTOR_IN1_PIN, 0, "IN1");
    rc |= safe_write(MOTOR_IN2_PIN, 0, "IN2");
    return rc;
}

static int motor_close_window(void)
{
    syslog(LOG_INFO, "Closing window: ENA=1 IN1=1 IN2=0");
    if (safe_write(MOTOR_ENABLE_PIN, 1, "ENA") < 0) return -1;
    if (safe_write(MOTOR_IN1_PIN, 1, "IN1") < 0) return -1;
    if (safe_write(MOTOR_IN2_PIN, 0, "IN2") < 0) return -1;
    syslog(LOG_INFO, "Window closing motor started (5 s)");
    return 0;
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(RAIN, INPUT) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(RAIN, UP) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_ENABLE_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(motor pins) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Ensure motor is stopped at startup */
    if (motor_stop() < 0) {
        syslog(LOG_ERR, "Initial motor_stop failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Rain window controller started (rain=GPIO%d, ENA=GPIO%d, IN1=GPIO%d, IN2=GPIO%d)",
           RAIN_SENSOR_PIN, MOTOR_ENABLE_PIN, MOTOR_IN1_PIN, MOTOR_IN2_PIN);

    int last_rain = gpioRead(RAIN_SENSOR_PIN);
    if (last_rain < 0) {
        syslog(LOG_ERR, "Initial gpioRead(RAIN) failed");
        motor_stop();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    int suppress_count = 0;

    while (g_running) {
        int rain = gpioRead(RAIN_SENSOR_PIN);
        if (rain < 0) {
            syslog(LOG_ERR, "gpioRead(RAIN) failed");
            usleep(POLL_INTERVAL_US);
            continue;
        }

        /* Dry (HIGH) -> wet (LOW) transition: trigger close */
        if (rain == 0 && last_rain == 1) {
            if (motor_close_window() == 0) {
                suppress_count = SUPPRESS_POLLS;
            } else {
                syslog(LOG_ERR, "motor_close_window failed; stopping motor");
                motor_stop();
            }
        }

        last_rain = rain;

        /* During suppression, only count HIGH polls to re-enable */
        if (suppress_count > 0) {
            if (rain == 1) {
                suppress_count--;
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down: stopping motor");
    motor_stop();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

