#include <pigpio.h>

#define SERVO_PIN        18
#define LOCK_BUTTON_PIN  21
#define UNLOCK_BUTTON_PIN 22

#define LOCK_PULSE_WIDTH   2000   /* microseconds -> locked   */
#define UNLOCK_PULSE_WIDTH 1000   /* microseconds -> unlocked */
#define DEBOUNCE_DELAY_US  50000  /* 50 ms debounce after press */
#define POLL_DELAY_US      10000  /* 10 ms poll interval        */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_pulse(int pulse_width)
{
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo(%d, %d) failed\n", SERVO_PIN, pulse_width);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Stop the servo (pulse width 0) and release pigpio resources. */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d)\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- Configure servo pin as output (gpioServo sets it, but be explicit) --- */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure button pins as inputs with internal pull-ups --- */
    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n", LOCK_BUTTON_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n", UNLOCK_BUTTON_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", LOCK_BUTTON_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", UNLOCK_BUTTON_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door lock control started.\n");
    printf("  Servo : GPIO %d (BCM)\n", SERVO_PIN);
    printf("  Lock  : GPIO %d (BCM, press to drive %d us)\n", LOCK_BUTTON_PIN, LOCK_PULSE_WIDTH);
    printf("  Unlock: GPIO %d (BCM, press to drive %d us)\n", UNLOCK_BUTTON_PIN, UNLOCK_PULSE_WIDTH);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        /* Lock button pressed (active-low, pull-up reads HIGH when released) */
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            if (set_servo_pulse(LOCK_PULSE_WIDTH) == 0) {
                printf("Door locked (pulse %d us)\n", LOCK_PULSE_WIDTH);
            }
            usleep(DEBOUNCE_DELAY_US);
        }

        /* Unlock button pressed */
        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            if (set_servo_pulse(UNLOCK_PULSE_WIDTH) == 0) {
                printf("Door unlocked (pulse %d us)\n", UNLOCK_PULSE_WIDTH);
            }
            usleep(DEBOUNCE_DELAY_US);
        }

        usleep(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Door lock control stopped.\n");
    return EXIT_SUCCESS;
}

