#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN        4
#define FAN_PIN        17
#define LOG_FILE       "security_log.txt"
#define FAN_ON_TIME_S  60
#define POLL_DELAY_US  100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Return a heap-allocated ISO-8601 timestamp string; caller frees. */
static char *get_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char *buf = malloc(32);
    if (!buf) {
        perror("malloc");
        return NULL;
    }
    time(&rawtime);
    if (!localtime_r(&rawtime, &timeinfo)) {
        perror("localtime_r");
        free(buf);
        return NULL;
    }
    if (strftime(buf, 32, "%Y-%m-%dT%H:%M:%S%z", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        free(buf);
        return NULL;
    }
    return buf;
}

/* Append a line to the log file. Returns 0 on success, -1 on error. */
static int log_event(const char *event_type, double duration)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    char *ts = get_timestamp();
    if (!ts) {
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s - %s - Duration: %.2f seconds\n",
                ts, event_type, duration) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", LOG_FILE, strerror(errno));
        free(ts);
        fclose(fp);
        return -1;
    }
    free(ts);
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* Turn the floodlight on. Returns 0 on success, -1 on error. */
static int turn_on_floodlight(void)
{
    if (gpioWrite(FAN_PIN, 1) != 0) {
        fprintf(stderr, "Error turning floodlight ON (gpioWrite failed)\n");
        return -1;
    }
    return 0;
}

/* Turn the floodlight off. Returns 0 on success, -1 on error. */
static int turn_off_floodlight(void)
{
    if (gpioWrite(FAN_PIN, 0) != 0) {
        fprintf(stderr, "Error turning floodlight OFF (gpioWrite failed)\n");
        return -1;
    }
    return 0;
}

/* Ensure the floodlight is off and release pigpio resources. */
static void cleanup(void)
{
    turn_off_floodlight();
    gpioTerminate();
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR pin %d as input\n", PIR_PIN);
        cleanup();
        return 1;
    }
    if (gpioSetMode(FAN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set fan pin %d as output\n", FAN_PIN);
        cleanup();
        return 1;
    }

    /* Start with the floodlight off */
    if (turn_off_floodlight() != 0) {
        cleanup();
        return 1;
    }

    printf("Smart Security Light started. Monitoring PIR on GPIO %d, "
           "floodlight on GPIO %d. Press Ctrl+C to exit.\n",
           PIR_PIN, FAN_PIN);

    int last_pir = gpioRead(PIR_PIN);
    if (last_pir < 0) {
        fprintf(stderr, "Initial PIR read failed\n");
        cleanup();
        return 1;
    }

    while (g_running) {
        int pir = gpioRead(PIR_PIN);
        if (pir < 0) {
            fprintf(stderr, "PIR read error\n");
            break;
        }

        if (pir == 1 && last_pir == 0) {
            /* Rising edge: motion detected */
            printf("Motion detected! Activating floodlight for %d seconds.\n",
                   FAN_ON_TIME_S);

            char *ts_on = get_timestamp();
            if (!ts_on) {
                break;
            }
            printf("%s - Floodlight activated\n", ts_on);
            free(ts_on);

            if (turn_on_floodlight() != 0) {
                break;
            }

            /* Keep the floodlight on for the configured duration */
            for (int i = 0; i < FAN_ON_TIME_S * 10 && g_running; i++) {
                gpioDelay(POLL_DELAY_US);
            }

            if (turn_off_floodlight() != 0) {
                break;
            }

            char *ts_off = get_timestamp();
            if (!ts_off) {
                break;
            }
            printf("%s - Floodlight deactivated\n", ts_off);
            free(ts_off);

            if (log_event("Activation", (double)FAN_ON_TIME_S) != 0) {
                fprintf(stderr, "Warning: failed to log activation event\n");
            }
        }

        last_pir = pir;
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    printf("Smart Security Light stopped.\n");
    return 0;
}

