#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define I2C_BUS 1
#define MPR121_ADDR 0x5A

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHD_RISING 0x2B
#define MPR121_NHD_RISING 0x2C
#define MPR121_NCL_RISING 0x2D
#define MPR121_FDL_RISING 0x2E
#define MPR121_MHD_FALLING 0x2F
#define MPR121_NHD_FALLING 0x30
#define MPR121_NCL_FALLING 0x31
#define MPR121_FDL_FALLING 0x32
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_AUTOCONFIG0 0x7B
#define MPR121_AUTOCONFIG1 0x7C
#define MPR121_USL 0x7D
#define MPR121_LSL 0x7E
#define MPR121_TL 0x7F

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int mpr121_read(uint8_t reg) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
    }
    return rc;
}

static int mpr121_init(void) {
    if (mpr121_write(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write(MPR121_MHD_RISING, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHD_RISING, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCL_RISING, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDL_RISING, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_MHD_FALLING, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHD_FALLING, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCL_FALLING, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDL_FALLING, 0x00) < 0) return -1;

    if (mpr121_write(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG2, 0x20) < 0) return -1;

    if (mpr121_write(MPR121_AUTOCONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write(MPR121_AUTOCONFIG1, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_USL, 200) < 0) return -1;
    if (mpr121_write(MPR121_LSL, 130) < 0) return -1;
    if (mpr121_write(MPR121_TL, 180) < 0) return -1;

    if (mpr121_write(MPR121_ELECTRODE_CONFIG, 0x0C) < 0) return -1;
    return 0;
}

static int read_touch_status(uint16_t *status) {
    int lo = mpr121_read(MPR121_TOUCHSTATUS_L);
    if (lo < 0) return -1;
    int hi = mpr121_read(MPR121_TOUCHSTATUS_H);
    if (hi < 0) return -1;
    *status = (uint16_t)((hi << 8) | lo);
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    int relay_state = 0;
    uint16_t prev_touch = 0;
    uint32_t last_toggle_ms = 0;

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        uint16_t new_touches = touch_status & ~prev_touch;
        uint32_t now = gpioTick();

        if (new_touches & 0x0001) {
            if (now - last_toggle_ms > 200000) {
                relay_state = !relay_state;
                gpioWrite(RELAY_GPIO, relay_state);
                last_toggle_ms = now;
                printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
            }
        }

        prev_touch = touch_status;
        gpioDelay(10000);
    }

    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

