static volatile int pwm_running = 0;
static volatile int current_angle = 90;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;

static void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(priority, format, args);
    va_end(args);
    if (log_file) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
        fprintf(log_file, "%s ", ts);
        vfprintf(log_file, format, args);
        fputc('\n', log_file);
        fflush(log_file);
    }
}

static void *pwm_thread_func(void *arg) {
    (void)arg;
    while (running && pwm_running) {
        int pw = SERVO_MIN_PULSE_WIDTH +
                 (int)((long)current_angle * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / SERVO_RANGE);
        int on_us = pw;
        int off_us = PWM_PERIOD_US - pw;
        int steps = PWM_STEPS;
        int on_per_step = on_us / steps;
        int off_per_step = off_us / steps;
        for (int i = 0; i < steps && running && pwm_running; i++) {
            if (gpiod_line_set_value(servo_line, 1) < 0) {
                log_message(LOG_ERR, "PWM: failed to set servo high: %s", strerror(errno));
                return NULL;
            }
            usleep(on_per_step);
            if (gpiod_line_set_value(servo_line, 0) < 0) {
                log_message(LOG_ERR, "PWM: failed to set servo low: %s", strerror(errno));
                return NULL;
            }
            usleep(off_per_step);
        }
    }
    if (servo_line) gpiod_line_set_value(servo_line, 0);
    return NULL;
}

static void cleanup(void) {
    pwm_running = 0;
    if (pwm_thread) {
        pthread_join(pwm_thread, NULL);
    }
    if (servo_line) {
        gpiod_line_release(servo_line);
        servo_line = NULL;
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    closelog();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }
    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        log_message(LOG_ERR, "Failed to get servo line (GPIO%d): %s", SERVO_PIN, strerror(errno));
        return -1;
    }
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_message(LOG_ERR, "Failed to get PIR line (GPIO%d): %s", PIR_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(servo_line, "servo_pwm", 0) < 0) {
        log_message(LOG_ERR, "Failed to request servo line as output: %s", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        log_message(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int init_socket(void) {
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message(LOG_ERR, "setsockopt failed: %s", strerror(errno));
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed: %s", strerror(errno));
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed: %s", strerror(errno));
        close(server_fd);
        server_fd = -1;
        return -1;
    }
    return 0;
}

static void handle_client(int client_fd) {
    char buffer[1024];
    ssize_t bytes = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (bytes < 0) {
        log_message(LOG_ERR, "recv failed: %s", strerror(errno));
        close(client_fd);
        return;
    }
    if (bytes == 0) {
        log_message(LOG_INFO, "Client disconnected");
        close(client_fd);
        return;
    }
    buffer[bytes] = '\0';
    buffer[strcspn(buffer, "\r\n")] = '\0';
    log_message(LOG_INFO, "Received command: %s", buffer);
    if (strncmp(buffer, "SERVO", 5) == 0) {
        int angle = atoi(buffer + 5);
        if (angle >= 0 && angle <= 180) {
            current_angle = angle;
            log_message(LOG_INFO, "Setting servo angle to %d", angle);
            if (pwm_running == 0) {
                pwm_running = 1;
                if (pthread_create(&pwm_thread, NULL, pwm_thread_func, NULL) != 0) {
                    log_message(LOG_ERR, "Failed to create PWM thread: %s", strerror(errno));
                    pwm_running = 0;
                }
            }
        } else {
            log_message(LOG_ERR, "Invalid servo angle: %s", buffer + 5);
            const char *err = "ERROR: Invalid servo angle\n";
            send(client_fd, err, strlen(err), 0);
        }
    } else if (strcmp(buffer, "PIR") == 0) {
        int val = gpiod_line_get_value(pir_line);
        if (val < 0) {
            log_message(LOG_ERR, "Failed to read PIR: %s", strerror(errno));
            const char *err = "ERROR: PIR read failed\n";
            send(client_fd, err, strlen(err), 0);
        } else {
            char response[64];
            snprintf(response, sizeof(response), "PIR:%d\n", val);
            send(client_fd, response, strlen(response), 0);
        }
    } else {
        log_message(LOG_ERR, "Unknown command: %s", buffer);
        const char *err = "ERROR: Unknown command\n";
        send(client_fd, err, strlen(err), 0);
    }
    close(client_fd);
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
    }
    log_message(LOG_INFO, "Starting security system");
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        cleanup();
        return 1;
    }
    if (init_gpio() < 0) {
        log_message(LOG_ERR, "GPIO initialization failed, exiting");
        cleanup();
        return 1;
    }
    if (init_socket() < 0) {
        log_message(LOG_ERR, "Socket initialization failed, exiting");
        cleanup();
        return 1;
    }
    log_message(LOG_INFO, "Listening on port %d", PORT);
    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_fd < 0) {
            if (running) {
                log_message(LOG_ERR, "Accept failed: %s", strerror(errno));
            }
            continue;
        }
        char ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, ip, sizeof(ip));
        log_message(LOG_INFO, "Connection from %s:%d", ip, ntohs(client_addr.sin_port));
        handle_client(client_fd);
    }
    log_message(LOG_INFO, "Shutting down");
    cleanup();
    return 0;
}

