#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <getopt.h>
#include <time.h>
#include <gpiod.h>

#define HX711_DOUT_PIN 23
#define HX711_SCK_PIN  24
#define SOLENOID_PIN   25

#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE     1.0
#define DEFAULT_DURATION  200
#define NUM_READINGS      5
#define TARE_READINGS     10
#define MAX_RETRIES       3
#define POLL_INTERVAL_MS  500
#define DOUT_TIMEOUT_MS   1000

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *dout_line = NULL;
static struct gpiod_line *sck_line = NULL;
static struct gpiod_line *solenoid_line = NULL;

static double threshold = DEFAULT_THRESHOLD;
static double scale     = DEFAULT_SCALE;
static int    duration  = DEFAULT_DURATION;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (solenoid_line) {
        gpiod_line_set_value(solenoid_line, 0);
        gpiod_line_release(solenoid_line);
        solenoid_line = NULL;
    }
    if (sck_line) {
        gpiod_line_release(sck_line);
        sck_line = NULL;
    }
    if (dout_line) {
        gpiod_line_release(dout_line);
        dout_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    closelog();
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        return -1;
    }

    dout_line = gpiod_chip_get_line(chip, HX711_DOUT_PIN);
    if (!dout_line) {
        syslog(LOG_ERR, "Failed to get DOUT line %d: %s", HX711_DOUT_PIN, strerror(errno));
        return -1;
    }

    sck_line = gpiod_chip_get_line(chip, HX711_SCK_PIN);
    if (!sck_line) {
        syslog(LOG_ERR, "Failed to get SCK line %d: %s", HX711_SCK_PIN, strerror(errno));
        return -1;
    }

    solenoid_line = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!solenoid_line) {
        syslog(LOG_ERR, "Failed to get solenoid line %d: %s", SOLENOID_PIN, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(dout_line, "hx711_dout") < 0) {
        syslog(LOG_ERR, "Failed to request DOUT as input: %s", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(sck_line, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK as output: %s", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(solenoid_line, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request solenoid as output: %s", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_hx711_raw(int *raw_out) {
    int value = 0;
    int timeout = DOUT_TIMEOUT_MS;

    while (gpiod_line_get_value(dout_line) == 1) {
        usleep(1000);
        timeout--;
        if (timeout <= 0) {
            syslog(LOG_ERR, "HX711 timeout waiting for DOUT LOW");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck_line, 1) < 0) {
            syslog(LOG_ERR, "Failed to set SCK HIGH: %s", strerror(errno));
            return -1;
        }
        usleep(1);
        value <<= 1;
        if (gpiod_line_get_value(dout_line) == 1) {
            value |= 1;
        }
        if (gpiod_line_set_value(sck_line, 0) < 0) {
            syslog(LOG_ERR, "Failed to set SCK LOW: %s", strerror(errno));
            return -1;
        }
        usleep(1);
    }

    if (gpiod_line_set_value(sck_line, 1) < 0) {
        syslog(LOG_ERR, "Failed to set SCK HIGH (25th pulse): %s", strerror(errno));
        return -1;
    }
    usleep(1);
    if (gpiod_line_set_value(sck_line, 0) < 0) {
        syslog(LOG_ERR, "Failed to set SCK LOW (25th pulse): %s", strerror(errno));
        return -1;
    }
    usleep(1);

    if (value & 0x800000) {
        value |= ~0xFFFFFF;
    }

    *raw_out = value;
    return 0;
}

static double read_hx711_average(int num_readings) {
    long sum = 0;
    int valid = 0;

    for (int i = 0; i < num_readings; i++) {
        int raw;
        if (read_hx711_raw(&raw) == 0) {
            sum += raw;
            valid++;
        } else {
            syslog(LOG_ERR, "HX711 read failed in cycle %d", i);
        }
        usleep(1000);
    }

    if (valid == 0) {
        syslog(LOG_ERR, "All HX711 readings failed");
        return 0.0;
    }

    return (double)sum / (double)valid;
}

static double calculate_weight(double raw_value, double scale_factor) {
    return (raw_value - 0.0) / scale_factor;
}

static void activate_solenoid(int duration_ms) {
    if (gpiod_line_set_value(solenoid_line, 1) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid HIGH: %s", strerror(errno));
        return;
    }
    usleep(duration_ms * 1000);
