            case 's':
                scale = atof(optarg);
                if (scale == 0.0) {
                    fprintf(stderr, "Scale factor must be non-zero\n");
                    exit(EXIT_FAILURE);
                }
                break;
            case 'd':
                duration = atoi(optarg);
                if (duration <= 0) {
                    fprintf(stderr, "Duration must be positive\n");
                    exit(EXIT_FAILURE);
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration_ms]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[]) {
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    parse_arguments(argc, argv);

    if (init_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Taring system...");
    double tare_offset = read_hx711_average(TARE_READINGS);
    syslog(LOG_INFO, "Tare offset: %.2f", tare_offset);

    while (running) {
        double raw_value = read_hx711_average(NUM_READINGS);
        double weight = calculate_weight(raw_value, scale);
        syslog(LOG_INFO, "Weight: %.2f grams", weight);

        if (weight > threshold) {
            syslog(LOG_INFO, "Threshold exceeded! Activating solenoid.");
            activate_solenoid(duration);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

