/*
 * relay_controller.c — Raspberry Pi 4 Model B
 *
 * Subscribes to home/lights/control via MQTT and toggles a relay on
 * GPIO17 (BCM) using pigpio.  Logs every event to syslog.
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c \
 *              -lmosquitto -lpigpio -lrt
 * Run:    sudo ./relay_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_HOST      "localhost"
#define MQTT_PORT      1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC     "home/lights/control"
#define MQTT_KEEPALIVE 60

#define GPIO_RELAY     17          /* BCM 17, physical pin 11 */

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata, int result)
{
    (void)userdata;

    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_HOST, MQTT_PORT);

        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "subscribe failed: %s", mosquitto_strerror(rc));
        } else {
            syslog(LOG_INFO, "subscribed to %s", MQTT_TOPIC);
        }
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_connack_string(result));
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)mosq;
    (void)userdata;

    if (rc == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT disconnected cleanly");
    } else {
        syslog(LOG_ERR, "MQTT unexpected disconnect: %s", mosquitto_strerror(rc));
    }
}

static void on_message(struct mosquitto *mosq, void *userdata,
                       const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (message->payloadlen <= 0) {
        syslog(LOG_ERR, "empty MQTT message on %s", message->topic);
        return;
    }

    /* NUL-terminate the payload for safe string comparison */
    char payload[32];
    size_t len = (size_t)message->payloadlen;
    if (len >= sizeof(payload)) {
        len = sizeof(payload) - 1;
    }
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    syslog(LOG_INFO, "MQTT %s: %s", message->topic, payload);

    if (strcmp(payload, "ON") == 0) {
        if (gpioWrite(GPIO_RELAY, 1) != 0) {
            syslog(LOG_ERR, "gpioWrite(ON) failed on GPIO%d", GPIO_RELAY);
        } else {
            syslog(LOG_INFO, "relay ON (GPIO%d HIGH)", GPIO_RELAY);
        }
    } else if (strcmp(payload, "OFF") == 0) {
        if (gpioWrite(GPIO_RELAY, 0) != 0) {
            syslog(LOG_ERR, "gpioWrite(OFF) failed on GPIO%d", GPIO_RELAY);
        } else {
            syslog(LOG_INFO, "relay OFF (GPIO%d LOW)", GPIO_RELAY);
        }
    } else {
        syslog(LOG_ERR, "unknown payload '%s' on %s — relay state unchanged",
               payload, message->topic);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();

    /* Ensure relay is OFF before releasing pigpio */
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();

    closelog();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode failed for GPIO%d", GPIO_RELAY);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Relay OFF at startup */
    if (gpioWrite(GPIO_RELAY, 0) != 0) {
        syslog(LOG_ERR, "gpioWrite(init) failed for GPIO%d", GPIO_RELAY);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* ---- mosquitto init ---- */
    mosquitto_lib_init();

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);

    /* ---- signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- main loop ---- */
    int rc = mosquitto_connect(g_mosq, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect failed: %s", mosquitto_strerror(rc));
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "MQTT connecting to %s:%d (client %s)",
           MQTT_HOST, MQTT_PORT, MQTT_CLIENT_ID);

    while (g_running) {
        rc = mosquitto_loop(g_mosq, 1000, 1);  /* 1 s timeout, 1 msg max */
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_loop error: %s — reconnecting in 5 s",
                   mosquitto_strerror(rc));
            sleep(5);
            if (!g_running) {
                break;
            }
            rc = mosquitto_reconnect(g_mosq);
            if (rc != MOSQ_ERR_SUCCESS) {
                syslog(LOG_ERR, "reconnect failed: %s", mosquitto_strerror(rc));
            }
        }
    }

    /* ---- graceful shutdown ---- */
    syslog(LOG_INFO, "shutdown requested — cleaning up");
    cleanup();
    return EXIT_SUCCESS;
}

