#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>

/* ---- Pin assignments (Raspberry Pi 3 Model B+) ---- */
#define MOTOR_A_PWM_PIN  17   /* DRV8833 IN1 (PWM)  */
#define MOTOR_A_DIR_PIN  18   /* DRV8833 IN2 (dir)  */
#define MOTOR_B_PWM_PIN  22   /* DRV8833 IN3 (PWM)  */
#define MOTOR_B_DIR_PIN  23   /* DRV8833 IN4 (dir)  */

#define ENCODER_A_A_PIN  4    /* Encoder A phase A  */
#define ENCODER_A_B_PIN  5    /* Encoder A phase B  */
#define ENCODER_B_A_PIN  6    /* Encoder B phase A  */
#define ENCODER_B_B_PIN 12    /* Encoder B phase B  */

/* ---- Motor parameters ---- */
#define TICKS_PER_REV  64.0
#define TARGET_RPM     50.0
#define PWM_FREQ_HZ    10000
#define PWM_RANGE      255

/* ---- PI controller ---- */
#define KP  0.5
#define KI  0.05
#define DT  0.1   /* seconds between control iterations */

/* ---- Stall detection ---- */
#define STALL_TIMEOUT_S 2.0

/* ---- Globals ---- */
static volatile int32_t encoder_a_count = 0;
static volatile int32_t encoder_b_count = 0;
static volatile uint32_t last_tick_a = 0;
static volatile uint32_t last_tick_b = 0;
static volatile bool stall_flag_a = false;
static volatile bool stall_flag_b = false;
static volatile bool running = true;

/* ---- Forward declarations ---- */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata);
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata);
static void stop_motors(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------------------------------------------ */
/* ISRs: count rising edges on A-phase; B-phase is used for direction  */
/* ------------------------------------------------------------------ */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)userdata;
    if (level == 1) {
        int32_t b = gpioRead(ENCODER_A_B_PIN);
        if (b == 1) {
            encoder_a_count++;
            last_tick_a = tick;
            stall_flag_a = false;
        } else {
            encoder_a_count--;
            last_tick_a = tick;
            stall_flag_a = false;
        }
    }
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)userdata;
    if (level == 1) {
        int32_t b = gpioRead(ENCODER_B_B_PIN);
        if (b == 1) {
            encoder_b_count++;
            last_tick_b = tick;
            stall_flag_b = false;
        } else {
            encoder_b_count--;
            last_tick_b = tick;
            stall_flag_b = false;
        }
    }
}

/* ------------------------------------------------------------------ */
/* Motor helpers                                                       */
/* ------------------------------------------------------------------ */
static void stop_motors(void)
{
    gpioPWM(MOTOR_A_PWM_PIN, 0);
    gpioWrite(MOTOR_A_DIR_PIN, 0);
    gpioPWM(MOTOR_B_PWM_PIN, 0);
    gpioWrite(MOTOR_B_DIR_PIN, 0);
}

static void cleanup(void)
{
    stop_motors();
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    running = false;
}

/* ------------------------------------------------------------------ */
/* PI controller                                                       */
/* ------------------------------------------------------------------ */
static int pi_control(double target_rpm, double current_rpm,
                      double *integral, double dt)
{
    double error = target_rpm - current_rpm;
    *integral += error * dt;

    double output = KP * error + KI * (*integral);

    if (output > PWM_RANGE) output = PWM_RANGE;
    if (output < -PWM_RANGE) output = -PWM_RANGE;

    return (int)(output + 0.5);  /* round to nearest int */
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Motor pins ---- */
    if (gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR_A_PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR_A_DIR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR_B_PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR_B_DIR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- PWM frequency ---- */
    if (gpioSetPWMfrequency(MOTOR_A_PWM_PIN, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", MOTOR_A_PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR_B_PWM_PIN, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", MOTOR_B_PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- PWM range ---- */
    if (gpioSetPWMrange(MOTOR_A_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", MOTOR_A_PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_B_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", MOTOR_B_PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Encoder pins ---- */
    if (gpioSetMode(ENCODER_A_A_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", ENCODER_A_A_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ENCODER_A_B_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", ENCODER_A_B_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ENCODER_B_A_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", ENCODER_B_A_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ENCODER_B_B_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", ENCODER_B_B_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Enable internal pull-ups on encoder B-phase pins ---- */
    gpioSetPullUpDown(ENCODER_A_B_PIN, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_B_PIN, PI_PUD_UP);

    /* ---- Register ISRs ---- */
    if (gpioSetISRFuncEx(ENCODER_A_A_PIN, RISING_EDGE, 0,
                         encoder_a_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO %d.\n", ENCODER_A_A_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ENCODER_B_A_PIN, RISING_EDGE, 0,
                         encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO %d.\n", ENCODER_B_A_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initial state: stop motors ---- */
    stop_motors();

    /* ---- Initialise controller state ---- */
    double integral_a = 0.0;
    double integral_b = 0.0;
    uint32_t last_tick = gpioTick();

    printf("Closed-loop speed control started. Target RPM: %.1f\n", TARGET_RPM);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main control loop ---- */
    while (running) {
        uint32_t now = gpioTick();
        double dt_sec = (double)(now - last_tick) / 1000000.0;
        last_tick = now;

        if (dt_sec < DT) {
            gpioDelay((uint32_t)((DT - dt_sec) * 1000000.0));
            continue;
        }

        /* ---- Read encoder counts atomically ---- */
        int32_t count_a = encoder_a_count;
        int32_t count_b = encoder_b_count;
        encoder_a_count = 0;
        encoder_b_count = 0;

        /* ---- Stall detection ---- */
        uint32_t now_u = gpioTick();
        if (now_u - last_tick_a > (uint32_t)(STALL_TIMEOUT_S * 1000000.0)) {
            stall_flag_a = true;
        }
        if (now_u - last_tick_b > (uint32_t)(STALL_TIMEOUT_S * 1000000.0)) {
            stall_flag_b = true;
        }

        if (stall_flag_a) {
            fprintf(stderr, "Warning: Encoder A stall detected (no ticks for > %.0f s).\n",
                    STALL_TIMEOUT_S);
        }
        if (stall_flag_b) {
            fprintf(stderr, "Warning: Encoder B stall detected (no ticks for > %.0f s).\n",
                    STALL_TIMEOUT_S);
        }

        /* ---- Compute RPM ---- */
        double rpm_a = ((double)count_a / TICKS_PER_REV) / dt_sec * 60.0;
        double rpm_b = ((double)count_b / TICKS_PER_REV) / dt_sec * 60.0;

        /* ---- PI control ---- */
        int pwm_a = pi_control(TARGET_RPM, rpm_a, &integral_a, dt_sec);
        int pwm_b = pi_control(TARGET_RPM, rpm_b, &integral_b, dt_sec);

        /* ---- Drive motor A (forward) ---- */
        if (pwm_a > 0) {
            gpioWrite(MOTOR_A_DIR_PIN, 1);
            gpioPWM(MOTOR_A_PWM_PIN, pwm_a);
        } else if (pwm_a < 0) {
            gpioWrite(MOTOR_A_DIR_PIN, 0);
            gpioPWM(MOTOR_A_PWM_PIN, -pwm_a);
        } else {
            gpioPWM(MOTOR_A_PWM_PIN, 0);
        }

        /* ---- Drive motor B (forward) ---- */
        if (pwm_b > 0) {
            gpioWrite(MOTOR_B_DIR_PIN, 1);
            gpioPWM(MOTOR_B_PWM_PIN, pwm_b);
        } else if (pwm_b < 0) {
            gpioWrite(MOTOR_B_DIR_PIN, 0);
            gpioPWM(MOTOR_B_PWM_PIN, -pwm_b);
        } else {
            gpioPWM(MOTOR_B_PWM_PIN, 0);
        }

        /* ---- Status print ---- */
        printf("RPM: A=%.1f B=%.1f  PWM: A=%d B=%d\n", rpm_a, rpm_b, pwm_a, pwm_b);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

