    if (gpioSetISRFuncEx(ENCODER_B_A_PIN, RISING_EDGE, 0,
                         encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO %d.\n", ENCODER_B_A_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initial state: stop motors ---- */
    stop_motors();

    /* ---- Initialise controller state ---- */
    double integral_a = 0.0;
    double integral_b = 0.0;
    uint32_t last_tick = gpioTick();

    printf("Closed-loop speed control started. Target RPM: %.1f\n", TARGET_RPM);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main control loop ---- */
    while (running) {
        uint32_t now = gpioTick();
        double dt_sec = (double)(now - last_tick) / 1000000.0;
        last_tick = now;

        if (dt_sec < DT) {
            gpioDelay((uint32_t)((DT - dt_sec) * 1000000.0));
            continue;
        }

        /* ---- Read encoder counts atomically ---- */
        int32_t count_a = encoder_a_count;
        int32_t count_b = encoder_b_count;
        encoder_a_count = 0;
        encoder_b_count = 0;

        /* ---- Stall detection ---- */
        uint32_t now_u = gpioTick();
        if (now_u - last_tick_a > (uint32_t)(STALL_TIMEOUT_S * 1000000.0)) {
            stall_flag_a = true;
        }
        if (now_u - last_tick_b > (uint32_t)(STALL_TIMEOUT_S * 1000000.0)) {
            stall_flag_b = true;
        }

        if (stall_flag_a) {
            fprintf(stderr, "Warning: Encoder A stall detected (no ticks for > %.0f s).\n",
                    STALL_TIMEOUT_S);
        }
        if (stall_flag_b) {
            fprintf(stderr, "Warning: Encoder B stall detected (no ticks for > %.0f s).\n",
                    STALL_TIMEOUT_S);
        }

        /* ---- Compute RPM ---- */
        double rpm_a = ((double)count_a / TICKS_PER_REV) / dt_sec * 60.0;
        double rpm_b = ((double)count_b / TICKS_PER_REV) / dt_sec * 60.0;

        /* ---- PI control ---- */
        int pwm_a = pi_control(TARGET_RPM, rpm_a, &integral_a, dt_sec);
        int pwm_b = pi_control(TARGET_RPM, rpm_b, &integral_b, dt_sec);

        /* ---- Drive motor A (forward) ---- */
        if (pwm_a > 0) {
            gpioWrite(MOTOR_A_DIR_PIN, 1);
            gpioPWM(MOTOR_A_PWM_PIN, pwm_a);
        } else if (pwm_a < 0) {
            gpioWrite(MOTOR_A_DIR_PIN, 0);
            gpioPWM(MOTOR_A_PWM_PIN, -pwm_a);
        } else {
            gpioPWM(MOTOR_A_PWM_PIN, 0);
        }

        /* ---- Drive motor B (forward) ---- */
        if (pwm_b > 0) {
            gpioWrite(MOTOR_B_DIR_PIN, 1);
            gpioPWM(MOTOR_B_PWM_PIN, pwm_b);
        } else if (pwm_b < 0) {
            gpioWrite(MOTOR_B_DIR_PIN, 0);
            gpioPWM(MOTOR_B_PWM_PIN, -pwm_b);
        } else {
            gpioPWM(MOTOR_B_PWM_PIN, 0);
        }

        /* ---- Status print ---- */
        printf("RPM: A=%.1f B=%.1f  PWM: A=%d B=%d\n", rpm_a, rpm_b, pwm_a, pwm_b);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

