#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000   /* 50 ms */
#define MAIN_LOOP_DELAY_US 10000  /* 10 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void log_relay_state(int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }
    printf("[%s] Relay is now %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(void)
{
    int relay_state = 0;
    int prev_touch = 0;
    int init_result;

    /* Install signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    init_result = gpioInitialise();
    if (init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", init_result);
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure relay starts in OFF state */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    relay_state = 0;
    log_relay_state(relay_state);

    /* Main loop */
    while (running) {
        int touch_value = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", TOUCH_SENSOR_PIN);
            break;
        }

        /* Detect rising edge: touch just pressed */
        if (touch_value == 1 && prev_touch == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);

            int post_debounce = gpioRead(TOUCH_SENSOR_PIN);
            if (post_debounce < 0) {
                fprintf(stderr, "Failed to read GPIO %d during debounce\n", TOUCH_SENSOR_PIN);
                break;
            }

            if (post_debounce == 1) {
                /* Valid touch detected — toggle relay */
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Failed to write GPIO %d\n", RELAY_PIN);
                    break;
                }
                log_relay_state(relay_state);
            }
        }

        prev_touch = touch_value;
        gpioDelay(MAIN_LOOP_DELAY_US);
    }

    /* Graceful shutdown: turn relay OFF and release pigpio */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn relay OFF during shutdown\n");
    }
    gpioTerminate();
    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

