#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO    27
#define PULSES_PER_LITER 450.0
#define FLOW_THRESHOLD   5.0
#define FLOW_HYSTERESIS  4.5
#define LOG_FILE         "water_flow.log"
#define SAMPLE_INTERVAL  1.0

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void pulse_counter(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio; (void)level; (void)tick; (void)user;
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

static void log_message(const char *msg)
{
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", ts, msg);
    fflush(log_file);
}

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void cleanup(void)
{
    if (log_file) {
        log_message("Shutting down: reopening solenoid to safe state.");
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(SOLENOID_GPIO, 1);
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flow sensor GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SOLENOID_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to initialise solenoid state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 1000, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for flow sensor\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("System started: flow monitoring active.");

    int solenoid_state = 1;

    while (running) {
        time_sleep(SAMPLE_INTERVAL);

        int pulses;
        pthread_mutex_lock(&pulse_mutex);
        pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double lpm = (pulses / PULSES_PER_LITER) * 60.0;

        char msg[128];
        snprintf(msg, sizeof(msg), "Flow rate: %.2f LPM (pulses: %d)", lpm, pulses);
        log_message(msg);

        if (lpm > FLOW_THRESHOLD && solenoid_state == 1) {
            if (gpioWrite(SOLENOID_GPIO, 0) == 0) {
                solenoid_state = 0;
                log_message("Solenoid CLOSED (flow exceeded threshold).");
            } else {
                log_message("ERROR: failed to close solenoid.");
            }
        } else if (lpm < FLOW_HYSTERESIS && solenoid_state == 0) {
            if (gpioWrite(SOLENOID_GPIO, 1) == 0) {
                solenoid_state = 1;
                log_message("Solenoid OPENED (flow below hysteresis).");
            } else {
                log_message("ERROR: failed to open solenoid.");
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

