#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define CONFIG_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"
#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18
#define DEFAULT_CALIBRATION_FACTOR 100.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define HX711_TIMEOUT 1000
#define HX711_SETTLE_DELAY_US 1000000

static volatile sig_atomic_t running = 1;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static char server_ip[32] = DEFAULT_SERVER_IP;
static int server_port = DEFAULT_SERVER_PORT;
static int server_socket = -1;
static int client_socket = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file '%s': %s\n", CONFIG_FILE, strerror(errno));
        return -1;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        line[strcspn(line, "\n")] = 0;
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");
        if (key && value) {
            if (strcmp(key, "calibration_factor") == 0) {
                calibration_factor = atof(value);
            } else if (strcmp(key, "server_ip") == 0) {
                strncpy(server_ip, value, sizeof(server_ip) - 1);
                server_ip[sizeof(server_ip) - 1] = '\0';
            } else if (strcmp(key, "server_port") == 0) {
                server_port = atoi(value);
            }
        }
    }
    fclose(fp);
    printf("Config loaded: calibration_factor=%.2f, server_ip=%s, server_port=%d\n", calibration_factor, server_ip, server_port);
    return 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return -1;
    }
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioWrite(SERVO_PIN, 0);
    return 0;
}

static int read_hx711_raw(void) {
    int32_t data = 0;
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > HX711_TIMEOUT) {
            fprintf(stderr, "Error: HX711 timeout (DATA stuck HIGH)\n");
            return -1;
        }
    }
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data |= 1;
        }
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1);
    }
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);
    if (data & 0x800000) {
        data |= 0xFF000000;
    }
    return (int)data;
}

static double read_hx711_weight(void) {
    int raw = read_hx711_raw();
    if (raw == -1) {
        return -1.0;
    }
    return (double)raw / calibration_factor;
}

static int set_servo_pulse(int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Servo pulse width %d out of range [%d, %d]\n", pulse_width, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH);
        return -1;
    }
    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

static int dispense_ingredient(double target_weight) {
    int pulse_width = (int)(target_weight * 10.0) + SERVO_MIN_PULSE_WIDTH;
    if (pulse_width > SERVO_MAX_PULSE_WIDTH) pulse_width = SERVO_MAX_PULSE_WIDTH;
    if (set_servo_pulse(pulse_width) != 0) {
        return -1;
    }
    gpioDelay(HX711_SETTLE_DELAY_US);
    double actual_weight = read_hx711_weight();
    if (actual_weight < 0) {
        return -1;
    }
    if (set_servo_pulse(1500) != 0) {
        return -1;
    }
    return 0;
}

static int log_dispensing_event(double target_weight, double actual_weight, const char *error_message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "{\"timestamp\":\"%s\",\"target_weight\":%.2f,\"actual_weight\":%.2f,\"error_message\":\"%s\"}\n",
            timestamp, target_weight, actual_weight, error_message ? error_message : "");
    fclose(fp);
    return 0;
}

static int handle_client(int client_fd) {
    char buffer[1024];
    ssize_t bytes = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (bytes <= 0) {
        if (bytes < 0) perror("recv");
        return -1;
    }
    buffer[bytes] = '\0';
    double target_weight = atof(buffer);
    printf("Received target weight: %.2f grams\n", target_weight);
    if (dispense_ingredient(target_weight) != 0) {
        const char *err = "Dispense failed";
        send(client_fd, err, strlen(err), 0);
        log_dispensing_event(target_weight, -1.0, err);
        return -1;
    }
    double actual_weight = read_hx711_weight();
    if (actual_weight < 0) {
        const char *err = "Weight read failed";
        send(client_fd, err, strlen(err), 0);
        log_dispensing_event(target_weight, -1.0, err);
        return -1;
    }
    char response[128];
    snprintf(response, sizeof(response), "%.2f", actual_weight);
    send(client_fd, response, strlen(response), 0);
    log_dispensing_event(target_weight, actual_weight, NULL);
    return 0;
}

static int start_server(void) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(server_ip);
    addr.sin_port = htons(server_port);
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("socket");
        return -1;
    }
    int opt = 1;
    if (setsockopt(server_socket, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(server_socket);
        return -1;
    }
    if (bind(server_socket, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(server_socket);
        return -1;
    }
    if (listen(server_socket, 3) < 0) {
        perror("listen");
        close(server_socket);
        return -1;
    }
    printf("Server listening on %s:%d\n", server_ip, server_port);
    return 0;
}

static void cleanup(void) {
    if (client_socket >= 0) {
        close(client_socket);
        client_socket = -1;
    }
    if (server_socket >= 0) {
        close(server_socket);
        server_socket = -1;
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    read_config();
    if (init_gpio() != 0) {
        return 1;
    }
    if (start_server() != 0) {
        cleanup();
        return 1;
    }
    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        client_socket = accept(server_socket, (struct sockaddr *)&client_addr, &client_len);
        if (client_socket < 0) {
            if (running) perror("accept");
            continue;
        }
        printf("Client connected: %s:%d\n", inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port));
        if (handle_client(client_socket) != 0) {
            fprintf(stderr, "Error handling client\n");
        }
        close(client_socket);
        client_socket = -1;
    }
    cleanup();
    return 0;
}

