#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEFAULT_DEBOUNCE_MS 50
#define POLL_INTERVAL_US 10000

static volatile sig_atomic_t running = 1;
static int debounce_ms = DEFAULT_DEBOUNCE_MS;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_state(int state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char buf[32];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", t);
    printf("%s Relay: %s\n", buf, state ? "ON" : "OFF");
    fflush(stdout);
}

static int safe_write(int pin, int level) {
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", pin, level);
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_ms = atoi(optarg);
                if (debounce_ms <= 0) {
                    fprintf(stderr, "Invalid debounce value, using default %d ms\n", DEFAULT_DEBOUNCE_MS);
                    debounce_ms = DEFAULT_DEBOUNCE_MS;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d debounce_ms]\n", argv[0]);
                return EXIT_FAILURE;
