#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define MIN_PULSE_US 500
#define MAX_PULSE_US 2500
#define ANGLE_MIN 0
#define ANGLE_MAX 180
#define STEP_DEG 10
#define PWM_FREQ 50
#define PWM_RANGE 2000000  /* 20 ms period in microseconds */

static volatile sig_atomic_t g_running = 1;
static struct termios g_orig_termios;
static int g_termios_restored = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_raw_mode(void) {
    struct termios raw;
    if (tcgetattr(STDIN_FILENO, &g_orig_termios) != 0) {
        perror("tcgetattr");
        return -1;
    }
    g_termios_restored = 1;
    raw = g_orig_termios;
    raw.c_lflag &= ~(ICANON | ECHO);
    raw.c_cc[VMIN] = 0;
    raw.c_cc[VTIME] = 1;
    if (tcsetattr(STDIN_FILENO, TCSANOW, &raw) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static void restore_termios(void) {
    if (g_termios_restored) {
        tcsetattr(STDIN_FILENO, TCSANOW, &g_orig_termios);
    }
}

static int angle_to_pulse_us(int angle) {
    if (angle < ANGLE_MIN) angle = ANGLE_MIN;
    if (angle > ANGLE_MAX) angle = ANGLE_MAX;
    return MIN_PULSE_US + (int)((long)(angle - ANGLE_MIN) *
                                (MAX_PULSE_US - MIN_PULSE_US) /
                                (ANGLE_MAX - ANGLE_MIN));
}

int main(void) {
    int angle = 90;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (set_raw_mode() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        restore_termios();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(SERVO_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d: %d\n", SERVO_PIN, ret);
        restore_termios();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPWMfrequency(SERVO_PIN, PWM_FREQ);
    if (ret != 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed for pin %d: %d\n", SERVO_PIN, ret);
        restore_termios();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPWMrange(SERVO_PIN, PWM_RANGE);
    if (ret != 0) {
        fprintf(stderr, "gpioSetPWMrange failed for pin %d: %d\n", SERVO_PIN, ret);
        restore_termios();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioServo(SERVO_PIN, angle_to_pulse_us(angle));
    if (ret != 0) {
        fprintf(stderr, "gpioServo initial set failed for pin %d: %d\n", SERVO_PIN, ret);
        restore_termios();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Servo control started. GPIO%d, angle %d, step %d. '+' / '-' / 'q':\n",
           SERVO_PIN, angle, STEP_DEG);
    fflush(stdout);

    while (g_running) {
        int c = getchar();
        if (c == 'q' || c == 'Q') {
            break;
        } else if (c == '+') {
            angle += STEP_DEG;
            if (angle > ANGLE_MAX) angle = ANGLE_MAX;
        } else if (c == '-') {
            angle -= STEP_DEG;
            if (angle < ANGLE_MIN) angle = ANGLE_MIN;
        } else {
            continue;
        }

        int pw = angle_to_pulse_us(angle);
        ret = gpioServo(SERVO_PIN, pw);
        if (ret != 0) {
            fprintf(stderr, "gpioServo update failed: %d\n", ret);
            break;
        }
        printf("Angle: %d deg  Pulse: %d us\n", angle, pw);
        fflush(stdout);
    }

    /* Stop PWM pulses on the pin */
    gpioServo(SERVO_PIN, 0);
    restore_termios();
    gpioTerminate();
    printf("\nServo stopped. Exiting.\n");
    return EXIT_SUCCESS;
}

