#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME      "gpiochip0"
#define GPIO_LINE_OFFSET    17
#define LOG_FILE            "motor_rpm.log"
#define SAMPLE_INTERVAL_SEC 5
#define DEBOUNCE_MS         2
#define DEBOUNCE_NS         (DEBOUNCE_MS * 1000000L)

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void get_iso8601_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo);
    } else {
        snprintf(buf, len, "1970-01-01T00:00:00");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;
    unsigned long pulse_count = 0;
    struct timespec last_event = {0, 0};
    struct timespec sample_start, sample_end;
    struct timespec now;
    double rpm;
    char timestamp[32];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    /* Request the line as input with internal pull-up bias (A3144 open-collector output). */
    if (gpiod_line_request_input_flags(line, "conveyor-monitor",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input with pull-up: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup_line;
    }

    printf("Monitoring conveyor belt motor on GPIO %d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    if (clock_gettime(CLOCK_MONOTONIC, &sample_start) == -1) {
        perror("clock_gettime");
        goto cleanup_log;
    }

    while (program_running) {
        struct timespec ts = {0, 10000000}; /* 10 ms poll interval */
        int ev = gpiod_line_event_wait(line, &ts);

        if (ev < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "gpiod_line_event_wait error: %s\n", strerror(errno));
            goto cleanup_log;
        }

        if (ev == 0) {
            /* Timeout — no event, loop back to check program_running. */
            continue;
        }

        /* Event detected — read it to confirm and clear the edge. */
        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            fprintf(stderr, "gpiod_line_event_read error: %s\n", strerror(errno));
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
            continue;
        }

        /* Debounce: ignore events within DEBOUNCE_MS of the last accepted one. */
        clock_gettime(CLOCK_MONOTONIC, &now);
        long delta_ns = (now.tv_sec - last_event.tv_sec) * 1000000000L
                      + (now.tv_nsec - last_event.tv_nsec);
        if (delta_ns < DEBOUNCE_NS) {
            continue;
        }
        last_event = now;

        pulse_count++;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &sample_end) == -1) {
        perror("clock_gettime");
        goto cleanup_log;
    }

    double elapsed = (double)(sample_end.tv_sec - sample_start.tv_sec)
                   + (double)(sample_end.tv_nsec - sample_start.tv_nsec) / 1e9;

    if (elapsed > 0.0) {
        rpm = ((double)pulse_count / elapsed) * 60.0;
    } else {
        rpm = 0.0;
    }

    get_iso8601_timestamp(timestamp, sizeof(timestamp));

    if (fprintf(log_file, "%s,%.2f\n", timestamp, rpm) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
    } else {
        fflush(log_file);
    }

    printf("RPM: %.2f\n", rpm);

    ret = EXIT_SUCCESS;

cleanup_log:
    if (log_file != NULL) {
        fclose(log_file);
    }
cleanup_line:
    if (line != NULL) {
        gpiod_line_release(line);
    }
cleanup_chip:
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

