        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            fprintf(stderr, "gpiod_line_event_read error: %s\n", strerror(errno));
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
            continue;
        }

        /* Debounce: ignore events within DEBOUNCE_MS of the last accepted one. */
        clock_gettime(CLOCK_MONOTONIC, &now);
        long delta_ns = (now.tv_sec - last_event.tv_sec) * 1000000000L
                      + (now.tv_nsec - last_event.tv_nsec);
        if (delta_ns < DEBOUNCE_NS) {
            continue;
        }
        last_event = now;

        pulse_count++;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &sample_end) == -1) {
        perror("clock_gettime");
        goto cleanup_log;
    }

    double elapsed = (double)(sample_end.tv_sec - sample_start.tv_sec)
                   + (double)(sample_end.tv_nsec - sample_start.tv_nsec) / 1e9;

    if (elapsed > 0.0) {
        rpm = ((double)pulse_count / elapsed) * 60.0;
    } else {
        rpm = 0.0;
    }

    get_iso8601_timestamp(timestamp, sizeof(timestamp));

    if (fprintf(log_file, "%s,%.2f\n", timestamp, rpm) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
    } else {
        fflush(log_file);
    }

    printf("RPM: %.2f\n", rpm);

    ret = EXIT_SUCCESS;

cleanup_log:
    if (log_file != NULL) {
        fclose(log_file);
    }
cleanup_line:
    if (line != NULL) {
        gpiod_line_release(line);
    }
cleanup_chip:
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

