#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17
#define POLL_DELAY_US    50000   /* 50 ms */
#define FAILSAFE_TIMEOUT 10      /* seconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin)
{
    int v = gpioRead(pin);
    if (v == PI_BAD_GPIO) {
        fprintf(stderr, "Error: gpioRead(%u) returned PI_BAD_GPIO\n", pin);
    }
    return v;
}

int main(void)
{
    /* --- Install signal handlers first so cleanup always works --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pins --- */
    if (safe_set_mode(TOUCH_SENSOR_PIN, PI_INPUT) != 0 ||
        safe_set_mode(RELAY_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure relay starts OFF */
    if (safe_write(RELAY_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int touch_active = 0;
    uint32_t touch_start_tick = 0;

    printf("Touch sensor relay control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int touch = safe_read(TOUCH_SENSOR_PIN);
        if (touch == PI_BAD_GPIO) {
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (touch == 1) {
            if (!touch_active) {
                touch_active = 1;
                touch_start_tick = gpioTick();
                printf("Touch detected!\n");
            }

            /* Failsafe: force relay OFF if touch held > 10 s */
            if (touch_start_tick != 0 &&
                (gpioTick() - touch_start_tick) / 1000000 > FAILSAFE_TIMEOUT) {
                if (relay_state != 0) {
                    printf("Failsafe: touch held > %d s, forcing relay OFF\n",
                           FAILSAFE_TIMEOUT);
                    if (safe_write(RELAY_PIN, 0) == 0) {
                        relay_state = 0;
                    }
                }
            } else {
                /* Toggle relay on rising edge */
                relay_state = !relay_state;
                if (safe_write(RELAY_PIN, relay_state) != 0) {
                    gpioTerminate();
                    return EXIT_FAILURE;
                }
                printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
                usleep(200000); /* 200 ms debounce */
            }
        } else {
            touch_active = 0;
            touch_start_tick = 0;
        }

        usleep(POLL_DELAY_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    safe_write(RELAY_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

