#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_PWM_PIN      18
#define VALVE_ENABLE_PIN   23
#define FLOW_SENSOR_PIN    24

#define PWM_FREQUENCY      1000
#define PWM_RANGE          255
#define PULSES_PER_LITER   450.0
#define SAMPLE_INTERVAL_US 100000
#define KP                 1.0

static volatile int pulse_count = 0;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void pulse_counter(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    pulse_count++;
}

static int set_valve_position(int position) {
    if (position < 0 || position > 255) {
        fprintf(stderr, "Error: Invalid valve position: %d (must be 0-255)\n", position);
        return -1;
    }
    if (gpioPWM(VALVE_PWM_PIN, position) != 0) {
        fprintf(stderr, "Error: gpioPWM failed for pin %d\n", VALVE_PWM_PIN);
        return -1;
    }
    return 0;
}

static int enable_valve(int enable) {
    if (gpioWrite(VALVE_ENABLE_PIN, enable ? 1 : 0) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for enable pin %d\n", VALVE_ENABLE_PIN);
        return -1;
    }
    return 0;
}

static double calculate_flow_rate(int pulses, double interval_sec) {
    if (interval_sec <= 0.0) return 0.0;
    return ((double)pulses / PULSES_PER_LITER) / interval_sec * 60.0;
}

static int log_data(double flow_rate, int valve_position) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    long timestamp_ms = (long)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
    if (fprintf(log_file, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    enable_valve(0);
    set_valve_position(0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    double target_flow_rate = 0.0;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = atof(optarg);
                if (target_flow_rate < 0.0) {
                    fprintf(stderr, "Error: Target flow rate must be non-negative.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
                return 1;
        }
    }

    if (target_flow_rate == 0.0) {
        fprintf(stderr, "Error: Target flow rate must be specified (e.g., -t 5.0).\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for PWM pin %d\n", VALVE_PWM_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for enable pin %d\n", VALVE_ENABLE_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for flow sensor pin %d\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for pin %d\n", VALVE_PWM_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d\n", VALVE_PWM_PIN);
        gpioTerminate();
        return 1;
    }

    if (enable_valve(1) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_valve_position(0) != 0) {
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed for flow sensor pin %d\n", FLOW_SENSOR_PIN);
        cleanup();
        return 1;
    }

    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        cleanup();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        cleanup();
        return 1;
    }

    printf("Flow control system started. Target flow rate: %.2f L/min\n", target_flow_rate);
    printf("Press Ctrl+C to exit.\n");

    struct timespec start_time, current_time;
    if (clock_gettime(CLOCK_MONOTONIC, &start_time) != 0) {
        perror("clock_gettime");
        cleanup();
        return 1;
    }

    while (!terminate) {
        int local_pulse_count = 0;
        {
            int prev = pulse_count;
            gpioDelay(SAMPLE_INTERVAL_US);
            local_pulse_count = pulse_count - prev;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &current_time) != 0) {
            perror("clock_gettime");
            break;
        }
        double elapsed = (current_time.tv_sec - start_time.tv_sec) +
                         (current_time.tv_nsec - start_time.tv_nsec) / 1e9;
        if (elapsed <= 0.0) elapsed = 0.001;

        double flow_rate = calculate_flow_rate(local_pulse_count, elapsed);
        double error = target_flow_rate - flow_rate;
        int valve_position = (int)(KP * error);
        if (valve_position < 0) valve_position = 0;
        if (valve_position > 255) valve_position = 255;

        if (set_valve_position(valve_position) != 0) {
            fprintf(stderr, "Error: Failed to set valve position.\n");
            break;
        }

        if (log_data(flow_rate, valve_position) != 0) {
            fprintf(stderr, "Error: Failed to log data.\n");
            break;
        }

        printf("Flow Rate: %.2f L/min, Valve Position: %d\n", flow_rate, valve_position);

        start_time = current_time;
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

