        if (log_data(flow_rate, valve_position) != 0) {
            fprintf(stderr, "Error: Failed to log data.\n");
            break;
        }

        printf("Flow Rate: %.2f L/min, Valve Position: %d\n", flow_rate, valve_position);

        start_time = current_time;
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

