        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LOCK_1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK_2_GPIO, PI_OUTPUT);
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("System started");

    while (running) {
        if (authenticate_rfid()) {
            if (authenticate_button()) {
                log_event("Access granted");
                disengage_locks();
                gpioDelay(LOCK_DELAY_US);
                engage_locks();
            } else {
                log_event("Button authentication failed");
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    log_event("System shutting down");
    cleanup();
    return 0;
}

