    if (m2_in3) gpiod_line_release(m2_in3);
    if (m2_in4) gpiod_line_release(m2_in4);
    if (enc1_a) gpiod_line_release(enc1_a);
    if (enc1_b) gpiod_line_release(enc1_b);
    if (enc2_a) gpiod_line_release(enc2_a);
    if (enc2_b) gpiod_line_release(enc2_b);
    if (chip) gpiod_chip_close(chip);
}

static void *encoder_thread(void *arg) {
    struct gpiod_line *a = (struct gpiod_line *)arg;
    struct gpiod_line *b = (struct gpiod_line *)((uintptr_t)arg + sizeof(void *));
    int motor_num = (int)(uintptr_t)arg >> 32;
    int32_t *count = (motor_num == 1) ? &enc1_count : &enc2_count;
    pthread_mutex_t *mtx = (motor_num == 1) ? &enc1_mtx : &enc2_mtx;

    while (running) {
        struct gpiod_line_event ev;
        int ret = gpiod_line_event_wait(a, NULL);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Encoder %d event wait error: %s\n", motor_num, strerror(errno));
            break;
        }
        if (ret == 0) continue;

        if (gpiod_line_event_read(a, &ev) < 0) {
            fprintf(stderr, "Encoder %d event read error: %s\n", motor_num, strerror(errno));
            continue;
        }

        int a_val = gpiod_line_get_value(a);
        int b_val = gpiod_line_get_value(b);
        if (a_val < 0 || b_val < 0) {
            fprintf(stderr, "Encoder %d read error: %s\n", motor_num, strerror(errno));
            continue;
        }

        if (ev.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            if (a_val == 1 && b_val == 0) {
                pthread_mutex_lock(mtx);
                (*count)++;
                pthread_mutex_unlock(mtx);
            } else if (a_val == 0 && b_val == 1) {
                pthread_mutex_lock(mtx);
                (*count)--;
                pthread_mutex_unlock(mtx);
            }
        } else if (ev.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            if (a_val == 0 && b_val == 0) {
                pthread_mutex_lock(mtx);
                (*count)++;
                pthread_mutex_unlock(mtx);
            } else if (a_val == 1 && b_val == 1) {
                pthread_mutex_lock(mtx);
                (*count)--;
                pthread_mutex_unlock(mtx);
            }
        }
    }
    return NULL;
}

static void set_motor_speed(int motor_num, double speed) {
    struct gpiod_line *ena = NULL, *in1 = NULL, *in2 = NULL;
    if (motor_num == 1) { ena = m1_ena; in1 = m1_in1; in2 = m1_in2; }
    else { ena = m2_enb; in1 = m2_in3; in2 = m2_in4; }
    if (!ena || !in1 || !in2) return;

    if (speed > 0) {
        gpiod_line_set_value(ena, 1);
        int duty_us = (int)((speed / 100.0) * PWM_PERIOD_US);
        if (duty_us < 0) duty_us = 0;
        if (duty_us > PWM_PERIOD_US) duty_us = PWM_PERIOD_US;

        int half_period = duty_us / 2;
        if (half_period > 0) {
            gpiod_line_set_value(in1, 1);
            gpiod_line_set_value(in2, 0);
            struct timespec ts = {0, half_period * 1000};
            nanosleep(&ts, NULL);
            gpiod_line_set_value(in1, 0);
            gpiod_line_set_value(in2, 1);
            ts.tv_nsec = (PWM_PERIOD_US - half_period) * 1000;
            nanosleep(&ts, NULL);
        } else {
            gpiod_line_set_value(in1, 0);
            gpiod_line_set_value(in2, 0);
        }
    } else {
        gpiod_line_set_value(ena, 0);
        gpiod_line_set_value(in1, 0);
        gpiod_line_set_value(in2, 0);
    }
}

static double calculate_pid(double setpoint, double actual, double *integral, double *prev_error) {
    double error = setpoint - actual;
    *integral += error;
    double derivative = error - *prev_error;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *prev_error = error;
    return output;
}

static double calculate_rpm(int32_t count, double dt) {
    double rev_per_sec = (double)count / PULSES_PER_REV / dt;
    return rev_per_sec * 60.0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }

    m1_ena = gpiod_chip_get_line(chip, MOTOR1_ENA);
    m1_in1 = gpiod_chip_get_line(chip, MOTOR1_IN1);
    m1_in2 = gpiod_chip_get_line(chip, MOTOR1_IN2);
    m2_enb = gpiod_chip_get_line(chip, MOTOR2_ENB);
    m2_in3 = gpiod_chip_get_line(chip, MOTOR2_IN3);
    m2_in4 = gpiod_chip_get_line(chip, MOTOR2_IN4);
    enc1_a = gpiod_chip_get_line(chip, ENCODER1_A);
    enc1_b = gpiod_chip_get_line(chip, ENCODER1_B);
    enc2_a = gpiod_chip_get_line(chip, ENCODER2_A);
    enc2_b = gpiod_chip_get_line(chip, ENCODER2_B);

    if (!m1_ena || !m1_in1 || !m1_in2 || !m2_enb || !m2_in3 || !m2_in4 ||
        !enc1_a || !enc1_b || !enc2_a || !enc2_b) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        release_gpio();
        return 1;
    }

    if (gpiod_line_request_output(m1_ena, "motor1_ena", 0) < 0 ||
        gpiod_line_request_output(m1_in1, "motor1_in1", 0) < 0 ||
        gpiod_line_request_output(m1_in2, "motor1_in2", 0) < 0 ||
        gpiod_line_request_output(m2_enb, "motor2_enb", 0) < 0 ||
        gpiod_line_request_output(m2_in3, "motor2_in3", 0) < 0 ||
        gpiod_line_request_output(m2_in4, "motor2_in4", 0) < 0) {
        fprintf(stderr, "Failed to request motor output lines: %s\n", strerror(errno));
        release_gpio();
        return 1;
    }

    if (gpiod_line_request_both_edges_events(enc1_a, "enc1_a") < 0 ||
        gpiod_line_request_both_edges_events(enc1_b, "enc1_b") < 0 ||
        gpiod_line_request_both_edges_events(enc2_a, "enc2_a") < 0 ||
        gpiod_line_request_both_edges_events(enc2_b, "enc2_b") < 0) {
        fprintf(stderr, "Failed to request encoder event lines: %s\n", strerror(errno));
        release_gpio();
        return 1;
    }

    pthread_t enc1_tid, enc2_tid;
    if (pthread_create(&enc1_tid, NULL, encoder_thread, (void *)(uintptr_t)ENCODER1_A | ((uintptr_t)ENCODER1_B << 8) | ((uintptr_t)1 << 32)) != 0 ||
        pthread_create(&enc2_tid, NULL, encoder_thread, (void *)(uintptr_t)ENCODER2_A | ((uintptr_t)ENCODER2_B << 8) | ((uintptr_t)2 << 32)) != 0) {
        fprintf(stderr, "Failed to create encoder threads: %s\n", strerror(errno));
        release_gpio();
        return 1;
    }

    log_file = fopen("motor_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        release_gpio();
        pthread_join(enc1_tid, NULL);
        pthread_join(enc2_tid, NULL);
        return 1;
    }
    fprintf(log_file, "Motor1_RPM,Motor2_RPM,PID_Output,PID_Proportional,PID_Integral,PID_Derivative\n");
    fflush(log_file);

    double integral1 = 0.0, integral2 = 0.0;
    double prev_err1 = 0.0, prev_err2 = 0.0;

    while (running) {
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);

        int32_t c1, c2;
        pthread_mutex_lock(&enc1_mtx);
        c1 = enc1_count;
        pthread_mutex_unlock(&enc1_mtx);
        pthread_mutex_lock(&enc2_mtx);
        c2 = enc2_count;
        pthread_mutex_unlock(&enc2_mtx);

        double dt = (double)SAMPLE_TIME_MS / 1000.0;
        double rpm1 = calculate_rpm(c1, dt);
        double rpm2 = calculate_rpm(c2, dt);

        double pid1 = calculate_pid(TARGET_RPM, rpm1, &integral1, &prev_err1);
        double pid2 = calculate_pid(TARGET_RPM, rpm2, &integral2, &prev_err2);

        set_motor_speed(1, pid1);
        set_motor_speed(2, pid2);

        clock_gettime(CLOCK_MONOTONIC, &end);
        double elapsed = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
        if (elapsed < dt) {
            struct timespec ts = {0, (long)((dt - elapsed) * 1e9)};
            nanosleep(&ts, NULL);
        }

        fprintf(log_file, "%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", rpm1, rpm2, pid1, integral1, prev_err1, prev_err2);
        fflush(log_file);
    }

    stop_motors();
    release_gpio();
    pthread_join(enc1_tid, NULL);
    pthread_join(enc2_tid, NULL);
    if (log_file) fclose(log_file);
    return 0;
}

