#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1
#define POLL_DELAY_US 50000
#define LOG_FILE "relay_log.txt"

/* MPR121 Register Addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E
#define MPR121_SOFTRESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int relay_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int mpr121_read_reg(uint8_t reg) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, strerror(errno));
    }
    return rc;
}

static int mpr121_init(void) {
    /* Soft reset */
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000); /* 10 ms settle */

    /* Stop mode (ECR = 0) before configuration */
    if (mpr121_write_reg(MPR121_ECR, 0x00) < 0) return -1;

    /* Filtering configuration */
    if (mpr121_write_reg(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDF, 0x05) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLT, 0x00) < 0) return -1;

    /* Touch / release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(MPR121_E0TTH + (i * 2), 0x0F) < 0) return -1;
        if (mpr121_write_reg(MPR121_E0RTH + (i * 2), 0x0A) < 0) return -1;
    }

    /* Debounce: 3 samples for touch, 3 for release */
    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI=6 samples, CDC=16 µA */
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;

    /* CDT=0.5 µs, SFI=4 samples, ESI=4 ms */
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking, run mode */
    if (mpr121_write_reg(MPR121_ECR, 0x8C) < 0) return -1;

    return 0;
}

static int mpr121_read_touch_status(void) {
    int low = mpr121_read_reg(MPR121_TOUCHSTATUS_L);
    if (low < 0) return -1;
    int high = mpr121_read_reg(MPR121_TOUCHSTATUS_H);
    if (high < 0) return -1;
    return (high << 8) | low;
}

static void log_relay_state(int new_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Relay: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                new_state ? "ON" : "OFF");
    }
    fclose(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, MPR121_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed - sensor may be absent or bus error\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    printf("MPR121 touch sensor ready. Polling every %d ms. Press Ctrl+C to exit.\n",
           POLL_DELAY_US / 1000);

    while (running) {
        int touch_status = mpr121_read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int any_touched = (touch_status & 0x0FFF) ? 1 : 0;

        if (any_touched && relay_state == 0) {
            gpioWrite(RELAY_GPIO, 1);
            relay_state = 1;
            log_relay_state(1);
            printf("Touch detected - relay ON\n");
        } else if (!any_touched && relay_state == 1) {
            gpioWrite(RELAY_GPIO, 0);
            relay_state = 0;
            log_relay_state(0);
            printf("No touch - relay OFF\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

