#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define VALVE1_PIN 17
#define VALVE2_PIN 18
#define LOG_FILE "valve_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *valve1_line = NULL;
static struct gpiod_line *valve2_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static int set_valve(struct gpiod_line *line, int pin, int duration_ms) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting GPIO %d HIGH: %s\n", pin, strerror(errno));
        return -1;
    }
    char msg[128];
    snprintf(msg, sizeof(msg), "Valve on GPIO %d activated for %d ms", pin, duration_ms);
    log_event(msg);
    usleep(duration_ms * 1000);
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO %d LOW: %s\n", pin, strerror(errno));
        return -1;
    }
    snprintf(msg, sizeof(msg), "Valve on GPIO %d deactivated", pin);
    log_event(msg);
    return 0;
}

static void cleanup(void) {
    if (valve1_line) {
        gpiod_line_set_value(valve1_line, 0);
        gpiod_line_release(valve1_line);
        valve1_line = NULL;
    }
    if (valve2_line) {
        gpiod_line_set_value(valve2_line, 0);
        gpiod_line_release(valve2_line);
        valve2_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        fclose(log_file);
        log_file = NULL;
        return EXIT_FAILURE;
    }

    valve1_line = gpiod_chip_get_line(chip, VALVE1_PIN);
    if (!valve1_line) {
        perror("gpiod_chip_get_line (valve1)");
        cleanup();
        return EXIT_FAILURE;
    }

    valve2_line = gpiod_chip_get_line(chip, VALVE2_PIN);
    if (!valve2_line) {
        perror("gpiod_chip_get_line (valve2)");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(valve1_line, "greenhouse-valve1", 0) < 0) {
        perror("gpiod_line_request_output (valve1)");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(valve2_line, "greenhouse-valve2", 0) < 0) {
        perror("gpiod_line_request_output (valve2)");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Greenhouse controller started");

    while (running) {
        if (set_valve(valve1_line, VALVE1_PIN, 500) < 0) {
            log_event("Error activating valve 1");
        }
        if (!running) break;
        sleep(5);
        if (set_valve(valve2_line, VALVE2_PIN, 1000) < 0) {
            log_event("Error activating valve 2");
        }
        if (!running) break;
        sleep(10);
    }

    log_event("Greenhouse controller stopped");
    cleanup();
    return EXIT_SUCCESS;
}

