#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define RELAY_PIN 17
#define I2C_BUS 1

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_MHD_RISING 0x2B
#define MPR121_NHD_RISING 0x2C
#define MPR121_NCL_RISING 0x2D
#define MPR121_FDL_RISING 0x2E
#define MPR121_MHD_FALLING 0x2F
#define MPR121_NHD_FALLING 0x30
#define MPR121_NCL_FALLING 0x31
#define MPR121_FDL_FALLING 0x32
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int mpr121_init(int handle) {
    if (mpr121_write(handle, MPR121_ECR, 0x00) < 0) return -1;
    gpioDelay(1000);

    if (mpr121_write(handle, MPR121_MHD_RISING, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHD_RISING, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCL_RISING, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDL_RISING, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_MHD_FALLING, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHD_FALLING, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCL_FALLING, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDL_FALLING, 0x00) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (mpr121_write(handle, MPR121_E0TTH + 2 * i, 0x10) < 0) return -1;
        if (mpr121_write(handle, MPR121_E0RTH + 2 * i, 0x0A) < 0) return -1;
    }

    if (mpr121_write(handle, MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(handle, MPR121_CONFIG2, 0x20) < 0) return -1;
    if (mpr121_write(handle, MPR121_ECR, 0x8F) < 0) return -1;

    gpioDelay(100000);
    return 0;
}

static int read_touch_status(int handle) {
    int low = i2cReadByteData(handle, MPR121_TOUCHSTATUS_L);
    if (low < 0) {
        fprintf(stderr, "I2C read failed for low byte: %d\n", low);
        return -1;
    }
    int high = i2cReadByteData(handle, MPR121_TOUCHSTATUS_H);
    if (high < 0) {
        fprintf(stderr, "I2C read failed for high byte: %d\n", high);
        return -1;
    }
    return (high << 8) | low;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int relay_state = 0;
    printf("MPR121 touch sensor relay control started. Press Ctrl+C to exit.\n");

    while (running) {
        int touch_status = read_touch_status(i2c_handle);
        if (touch_status < 0) {
            gpioDelay(100000);
            continue;
        }

        if (touch_status > 0) {
            relay_state = !relay_state;
            if (gpioWrite(RELAY_PIN, relay_state) < 0) {
                fprintf(stderr, "Failed to write relay pin\n");
            } else {
                printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
            }
        }

        gpioDelay(100000);
    }

    gpioWrite(RELAY_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

