#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN 17
#define RELAY_PIN 18
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event_type) {
    if (!log_file) return;
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    long ms = ts.tv_nsec / 1000000;
    fprintf(log_file, "%s.%03ld: %s\n", timestamp, ms, event_type);
    fflush(log_file);
}

static void unlock_door(void) {
    if (gpioWrite(RELAY_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set relay ON\n");
        return;
    }
    log_event("Door Unlocked");
    gpioDelay(UNLOCK_DURATION_MS * 1000);
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to set relay OFF\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    log_file = fopen("door_events.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR pin mode\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set PIR pull-down\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
