#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255
#define MIN_DURATION_MS 50
#define MAX_DURATION_MS 200
#define MIN_STEPS 5
#define MAX_STEPS 15

typedef struct {
    int motor1_duty_cycle;
    int motor2_duty_cycle;
    int duration_ms;
} HapticStep;

typedef struct {
    HapticStep *steps;
    int num_steps;
} HapticPattern;

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

HapticPattern generate_haptic_pattern() {
    HapticPattern pattern;
    pattern.num_steps = (rand() % (MAX_STEPS - MIN_STEPS + 1)) + MIN_STEPS;
    pattern.steps = (HapticStep *)malloc(pattern.num_steps * sizeof(HapticStep));
    if (pattern.steps == NULL) {
        fprintf(stderr, "Error: Memory allocation failed for haptic pattern\n");
        pattern.num_steps = 0;
        return pattern;
    }
    for (int i = 0; i < pattern.num_steps; i++) {
        pattern.steps[i].motor1_duty_cycle = rand() % (MAX_DUTY_CYCLE + 1);
        pattern.steps[i].motor2_duty_cycle = rand() % (MAX_DUTY_CYCLE + 1);
        pattern.steps[i].duration_ms = (rand() % (MAX_DURATION_MS - MIN_DURATION_MS + 1)) + MIN_DURATION_MS;
    }
    return pattern;
}

void play_haptic_pattern(HapticPattern pattern) {
    for (int i = 0; i < pattern.num_steps; i++) {
        if (!program_running) break;
        gpioPWM(MOTOR1_PIN, pattern.steps[i].motor1_duty_cycle);
        gpioPWM(MOTOR2_PIN, pattern.steps[i].motor2_duty_cycle);
        gpioDelay(pattern.steps[i].duration_ms * 1000);
    }
}

void cleanup(HapticPattern pattern) {
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
    gpioTerminate();
    if (pattern.steps != NULL) {
        free(pattern.steps);
    }
}

int main() {
    srand(time(NULL));
    signal(SIGINT, signal_handler);
    if (initialize_gpio() != 0) {
        return 1;
    }
    HapticPattern pattern;
    while (program_running) {
        pattern = generate_haptic_pattern();
        if (pattern.num_steps > 0) {
            play_haptic_pattern(pattern);
            free(pattern.steps);
        }
    }
    cleanup(pattern);
    return 0;
}

