#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define NUM_CALIBRATION_READINGS 100
#define WEIGHT_THRESHOLD 10.0
#define HX711_TIMEOUT_US 500000
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static double scale_factor = 1.0;
static double offset = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin) {
    int value = 0;
    int i;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);
    gpioWrite(clock_pin, 0);

    for (i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        value = value << 1;
        if (gpioRead(data_pin)) {
            value++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    if (value & 0x800000) {
        value |= ~0xffffff;
    }

    return value;
}

static int calibrate_hx711(int data_pin, int clock_pin, double *scale, double *offset) {
    double sum = 0.0;
    int i;
    int raw;

    printf("Starting calibration...\n");
    for (i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        raw = read_hx711(data_pin, clock_pin);
        if (raw == 0) {
            fprintf(stderr, "Calibration read timeout at sample %d\n", i);
            return -1;
        }
        sum += raw;
        gpioDelay(10000);
    }

    *offset = sum / NUM_CALIBRATION_READINGS;
    printf("Calibration complete. Offset: %.2f\n", *offset);
    return 0;
}

static int load_calibration_data(const char *filename, double *scale, double *offset) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        return -1;
    }

    if (fscanf(fp, "%lf %lf", scale, offset) != 2) {
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int save_calibration_data(const char *filename, double scale, double offset) {
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        return -1;
    }

    fprintf(fp, "%lf %lf\n", scale, offset);
    fclose(fp);
    return 0;
}

static double convert_to_weight(int raw_value, double scale, double offset) {
    return (raw_value - offset) / scale;
}

static void log_weight(double weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fclose(fp);
}

static void control_solenoid(int pin, int state) {
    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, state);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (load_calibration_data(CALIBRATION_FILE, &scale_factor, &offset) != 0) {
        fprintf(stderr, "Using default calibration values (scale=1.0, offset=0.0)\n");
    }

    if (calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &scale_factor, &offset) != 0) {
        fprintf(stderr, "Calibration failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    if (save_calibration_data(CALIBRATION_FILE, scale_factor, offset) != 0) {
        fprintf(stderr, "Warning: could not save calibration data\n");
    }

    printf("Starting weight monitoring...\n");

    while (running) {
        int raw_value = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw_value == 0) {
            fprintf(stderr, "HX711 read timeout, skipping iteration\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double weight = convert_to_weight(raw_value, scale_factor, offset);
        log_weight(weight);

        if (weight > WEIGHT_THRESHOLD) {
            control_solenoid(SOLENOID_PIN, 1);
            printf("Weight exceeded threshold. Lock engaged.\n");
        } else {
            control_solenoid(SOLENOID_PIN, 0);
            printf("Weight within threshold. Lock released.\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    control_solenoid(SOLENOID_PIN, 0);
    gpioTerminate();
    return 0;
}

