#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_US 50000
#define RAIN_THRESHOLD 3
#define MOTOR_RUN_TIME_S 5
#define LOOP_INTERVAL_S 60
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(priority, "%s: %s", timestamp, message);
}

static int read_rain_sensor(void) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        if (gpioRead(RAIN_SENSOR_PIN) == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_US);
    }
    return (low_count >= RAIN_THRESHOLD) ? 1 : 0;
}

static void close_window(void) {
