#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17
#define WEIGHT_THRESHOLD 100.0
#define SOLENOID_DURATION_MS 5000
#define LOG_FILE "stock_events.txt"
#define HX711_TIMEOUT_US 1000000
#define HX711_SETTLE_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int hx711_read(int dt_pin, int sck_pin) {
    if (gpioSetMode(dt_pin, PI_INPUT) < 0) return -1;
    if (gpioSetMode(sck_pin, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(sck_pin, 0) < 0) return -1;

    uint32_t start = gpioTick();
    while (gpioRead(dt_pin) == 1) {
        if (gpioTick() - start > HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout: DT stuck high\n");
            return -1;
        }
    }

    int32_t value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(sck_pin, 1) < 0) return -1;
        gpioDelay(1);
        value <<= 1;
        if (gpioWrite(sck_pin, 0) < 0) return -1;
        gpioDelay(1);
        if (gpioRead(dt_pin)) value |= 1;
    }

    if (gpioWrite(sck_pin, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(sck_pin, 0) < 0) return -1;
    gpioDelay(1);

    if (value & 0x800000) value |= 0xFF000000;
    return value;
}

static double read_weight(int dt_pin, int sck_pin) {
    int raw = hx711_read(dt_pin, sck_pin);
    if (raw == -1) return -1.0;
    return (double)raw / 100.0;
}

static int activate_solenoid(int pin, int duration_ms) {
    if (gpioSetMode(pin, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(pin, 1) < 0) return -1;
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(pin, 0) < 0) return -1;
    return 0;
}

static int log_event(const char *filename, double weight) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Weight: %.2f g\n", ts, weight);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Stock monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        double weight = read_weight(HX711_DT, HX711_SCK);
        if (weight < 0) {
            fprintf(stderr, "Error reading weight, retrying...\n");
            gpioDelay(1000000);
            continue;
        }

        printf("Weight: %.2f g\n", weight);

        if (weight < WEIGHT_THRESHOLD) {
            printf("Weight below threshold, activating solenoid.\n");
            if (activate_solenoid(SOLENOID_PIN, SOLENOID_DURATION_MS) == 0) {
                if (log_event(LOG_FILE, weight) != 0) {
                    fprintf(stderr, "Error logging event.\n");
                }
            } else {
                fprintf(stderr, "Error activating solenoid.\n");
            }
        }

        gpioDelay(1000000);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Stock monitoring stopped.\n");
    return 0;
}

