        gpioDelay(100);
        if (++timeout > HX711_TIMEOUT_US) {
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1);
        data = (data << 1) | (gpioRead(HX711_DATA_PIN) & 1);
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
    }

    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return (int)data;
}

static double read_weight_kg(void) {
    int raw = read_hx711_raw();
    if (raw == -1) {
        fprintf(stderr, "HX711 timeout: data line stuck high\n");
        return -1.0;
    }
    return (double)raw / calibration_factor;
}

static int calibrate_load_cell(void) {
    double known_weight;
    int raw;

    printf("Place a known weight on the load cell (kg): ");
    if (scanf("%lf", &known_weight) != 1 || known_weight <= 0.0) {
        fprintf(stderr, "Invalid weight input.\n");
        return -1;
    }

    raw = read_hx711_raw();
    if (raw == -1) {
        fprintf(stderr, "HX711 timeout during calibration.\n");
        return -1;
    }

    calibration_factor = (double)raw / known_weight;

    calibration_fp = fopen(CALIBRATION_FILE, "w");
    if (!calibration_fp) {
        perror("Error opening calibration file");
        return -1;
    }

    if (fprintf(calibration_fp, "%.6f", calibration_factor) < 0) {
        perror("Error writing calibration factor");
        fclose(calibration_fp);
        calibration_fp = NULL;
        return -1;
    }

    if (fclose(calibration_fp) != 0) {
        perror("Error closing calibration file");
        calibration_fp = NULL;
        return -1;
    }
    calibration_fp = NULL;

    printf("Calibration factor: %.6f\n", calibration_factor);
    return 0;
}

static int load_calibration(void) {
    calibration_fp = fopen(CALIBRATION_FILE, "r");
    if (!calibration_fp) {
        perror("Error opening calibration file");
        return -1;
    }

    if (fscanf(calibration_fp, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Error reading calibration factor.\n");
        fclose(calibration_fp);
        calibration_fp = NULL;
        return -1;
    }

    if (fclose(calibration_fp) != 0) {
        perror("Error closing calibration file");
        calibration_fp = NULL;
        return -1;
    }
    calibration_fp = NULL;

    printf("Loaded calibration factor: %.6f\n", calibration_factor);
    return 0;
}

static void log_event(double weight) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Error opening log file");
        return;
    }

    if (fprintf(log_fp, "%s - Weight: %.2f kg\n", timestamp, weight) < 0) {
        perror("Error writing to log file");
    }

    if (fclose(log_fp) != 0) {
        perror("Error closing log file");
    }
    log_fp = NULL;
}

static void control_solenoid(void) {
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 1);
    printf("Solenoid locked.\n");

    for (int i = 0; i < SOLENOID_UNLOCK_SEC * 10 && running; i++) {
        gpioDelay(100000);
    }

    gpioWrite(SOLENOID_PIN, 0);
    printf("Solenoid unlocked.\n");
}

static void cleanup(void) {
    if (calibration_fp) {
        fclose(calibration_fp);
        calibration_fp = NULL;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction failed");
        gpioTerminate();
        return 1;
    }

    if (load_calibration() != 0) {
        if (calibrate_load_cell() != 0) {
            fprintf(stderr, "Calibration failed. Exiting.\n");
            cleanup();
            return 1;
        }
    }

    printf("Entering weight monitoring loop. Press Ctrl+C to exit.\n");

    while (running) {
        double weight = read_weight_kg();
        if (weight < 0.0) {
            gpioDelay(100000);
            continue;
        }

        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            log_event(weight);
            control_solenoid();
        }

        gpioDelay(500000);
    }

    printf("\nExiting gracefully.\n");
    cleanup();
    return 0;
}

