#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* GPIO pin definitions */
#define LEFT_SENSOR_PIN  4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define MOTOR_A_PWM_PIN  22
#define MOTOR_A_DIR_PIN  23
#define MOTOR_B_PWM_PIN  24
#define MOTOR_B_DIR_PIN  25

/* Motor speed range (0-255) */
#define MOTOR_SPEED_MAX 255

/* Base speed when the line is straight */
#define BASE_SPEED 150

/* PWM frequency for L298N */
#define PWM_FREQUENCY 1000

/* Sampling interval in microseconds (10 ms) */
#define SAMPLE_INTERVAL_US 10000

/* Global flag for graceful shutdown */
static volatile sig_atomic_t running = 1;

/* Log file pointer */
static FILE *log_file = NULL;

/* Signal handler for Ctrl+C */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Read the state of an IR sensor (0 = line detected, 1 = no line) */
static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, pigpio_error(value));
        return -1;
    }
    return value;
}

/* Set motor speed and direction using L298N PWM inputs */
static int set_motor_speed(int pwm_pin, int dir_pin, int speed) {
    if (speed < 0 || speed > MOTOR_SPEED_MAX) {
        fprintf(stderr, "Invalid motor speed %d (must be 0-%d)\n", speed, MOTOR_SPEED_MAX);
        return -1;
    }

    int dir = (speed > 0) ? 1 : 0;
    if (gpioWrite(dir_pin, dir) < 0) {
        fprintf(stderr, "Error writing to direction pin %d\n", dir_pin);
        return -1;
    }

    if (gpioPWM(pwm_pin, speed) < 0) {
        fprintf(stderr, "Error setting PWM on pin %d\n", pwm_pin);
        return -1;
    }
    return 0;
}

/* Log sensor and motor data to file */
static void log_data(int left_sensor, int middle_sensor, int right_sensor,
                     int left_speed, int right_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, %d, %d, %d, %d, %d\n",
                timestamp, left_sensor, middle_sensor, right_sensor,
                left_speed, right_speed) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }
    fflush(log_file);
}

/* Cleanup resources before exiting */
static void cleanup(void) {
    /* Stop motors */
    set_motor_speed(MOTOR_A_PWM_PIN, MOTOR_A_DIR_PIN, 0);
    set_motor_speed(MOTOR_B_PWM_PIN, MOTOR_B_DIR_PIN, 0);

    /* Close log file */
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO modes */
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency for L298N */
    if (gpioSetPWMfrequency(MOTOR_A_PWM_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("trace_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp, Left Sensor, Middle Sensor, Right Sensor, Left Speed, Right Speed\n");
        fflush(log_file);
    }

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering signal handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    /* Main control loop */
    while (running) {
        int left_sensor = read_sensor(LEFT_SENSOR_PIN);
        int middle_sensor = read_sensor(MIDDLE_SENSOR_PIN);
        int right_sensor = read_sensor(RIGHT_SENSOR_PIN);

        if (left_sensor < 0 || middle_sensor < 0 || right_sensor < 0) {
            fprintf(stderr, "Error reading sensor data, stopping motors\n");
            set_motor_speed(MOTOR_A_PWM_PIN, MOTOR_A_DIR_PIN, 0);
            set_motor_speed(MOTOR_B_PWM_PIN, MOTOR_B_DIR_PIN, 0);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int left_speed = BASE_SPEED;
        int right_speed = BASE_SPEED;

        /* Line following logic */
        if (left_sensor == 0 && middle_sensor == 0 && right_sensor == 0) {
            /* All sensors on line: drive straight */
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (left_sensor == 0 && middle_sensor == 0 && right_sensor == 1) {
            /* Turn left: slow down right motor */
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        } else if (left_sensor == 1 && middle_sensor == 0 && right_sensor == 0) {
            /* Turn right: slow down left motor */
            left_speed = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else if (left_sensor == 1 && middle_sensor == 0 && right_sensor == 1) {
            /* Only left sensor on line: turn right */
            left_speed = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else if (left_sensor == 1 && middle_sensor == 1 && right_sensor == 0) {
            /* Only right sensor on line: turn left */
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        } else if (left_sensor == 0 && middle_sensor == 1 && right_sensor == 1) {
            /* Only middle sensor on line: drive straight */
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else {
            /* No line detected: stop */
            left_speed = 0;
            right_speed = 0;
        }

        /* Set motor speeds */
        if (set_motor_speed(MOTOR_A_PWM_PIN, MOTOR_A_DIR_PIN, left_speed) < 0 ||
            set_motor_speed(MOTOR_B_PWM_PIN, MOTOR_B_DIR_PIN, right_speed) < 0) {
            fprintf(stderr, "Error setting motor speeds\n");
        }

        /* Log data */
        log_data(left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        /* Wait for next sample */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup and exit */
    cleanup();
    printf("Line following robot stopped.\n");
    return EXIT_SUCCESS;
}

