            left_speed = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else if (left_sensor == 1 && middle_sensor == 1 && right_sensor == 0) {
            /* Only right sensor on line: turn left */
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        } else if (left_sensor == 0 && middle_sensor == 1 && right_sensor == 1) {
            /* Only middle sensor on line: drive straight */
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else {
            /* No line detected: stop */
            left_speed = 0;
            right_speed = 0;
        }

        /* Set motor speeds */
        if (set_motor_speed(MOTOR_A_PWM_PIN, MOTOR_A_DIR_PIN, left_speed) < 0 ||
            set_motor_speed(MOTOR_B_PWM_PIN, MOTOR_B_DIR_PIN, right_speed) < 0) {
            fprintf(stderr, "Error setting motor speeds\n");
        }

        /* Log data */
        log_data(left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        /* Wait for next sample */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup and exit */
    cleanup();
    printf("Line following robot stopped.\n");
    return EXIT_SUCCESS;
}

