#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0f
#define MEASUREMENT_DELAY_US 180000
#define LOG_FILE "grow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        struct tm tm_info;
        localtime_r(&ts.tv_sec, &tm_info);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(fp, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, message);
    } else {
        fprintf(fp, "[timestamp error]: %s\n", message);
    }
    fclose(fp);
}

static int read_bh1750(float *lux_out) {
    if (i2c_handle < 0) {
        log_event("Error: I2C handle invalid");
        return -1;
    }
    char cmd = 0x10;
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        log_event("Error: Failed to write BH1750 command");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_US);
    char buf[2];
    int bytes = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes != 2) {
        log_event("Error: Failed to read BH1750 data");
        return -1;
    }
    unsigned int raw = ((unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(float lux) {
    static int relay_state = 0;
    if (lux < LUX_THRESHOLD && relay_state == 0) {
        gpioWrite(RELAY_GPIO, 1);
        relay_state = 1;
        log_event("Relay ON");
    } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
        gpioWrite(RELAY_GPIO, 0);
        relay_state = 0;
        log_event("Relay OFF");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    log_event("Program started");
    while (running) {
        float lux = 0.0f;
        if (read_bh1750(&lux) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Lux: %.2f", lux);
            log_event(msg);
            control_relay(lux);
        } else {
            log_event("Error reading lux value");
        }
        gpioDelay(5000000);
    }
    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    log_event("Program terminated");
    return EXIT_SUCCESS;
}

