#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

#define SERVO_LOCK_PULSE 1000
#define SERVO_UNLOCK_PULSE 2000
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500

#define DEBOUNCE_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulse(int pulse) {
    if (pulse < SERVO_MIN_PULSE) pulse = SERVO_MIN_PULSE;
    if (pulse > SERVO_MAX_PULSE) pulse = SERVO_MAX_PULSE;
    if (gpioServo(SERVO_PIN, pulse) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse %d\n", pulse);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for SERVO_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for button pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            printf("Lock button pressed. Locking door.\n");
            if (set_servo_pulse(SERVO_LOCK_PULSE) < 0) {
                fprintf(stderr, "Error: failed to set lock position\n");
            }
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            printf("Unlock button pressed. Unlocking door.\n");
            if (set_servo_pulse(SERVO_UNLOCK_PULSE) < 0) {
                fprintf(stderr, "Error: failed to set unlock position\n");
            }
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

