#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define CONSUMER "haptic_feedback"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_value(struct gpiod_line *line, int value, const char *label) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror(label);
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *motor1_line = NULL;
    struct gpiod_line *motor2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    motor1_line = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (!motor1_line) {
        perror("gpiod_chip_get_line(MOTOR1_PIN)");
        goto cleanup;
    }

    motor2_line = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!motor2_line) {
        perror("gpiod_chip_get_line(MOTOR2_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_output(motor1_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(MOTOR1_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_output(motor2_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(MOTOR2_PIN)");
        goto cleanup;
    }

    while (running) {
        if (safe_set_value(motor1_line, 1, "set motor1 on") < 0)
            goto cleanup;
        usleep(200000);
        if (!running) break;
        if (safe_set_value(motor1_line, 0, "set motor1 off") < 0)
            goto cleanup;

        if (safe_set_value(motor2_line, 1, "set motor2 on") < 0)
            goto cleanup;
        usleep(300000);
        if (!running) break;
        if (safe_set_value(motor2_line, 0, "set motor2 off") < 0)
            goto cleanup;
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (motor1_line) {
        gpiod_line_set_value(motor1_line, 0);
        gpiod_line_release(motor1_line);
    }
    if (motor2_line) {
        gpiod_line_set_value(motor2_line, 0);
        gpiod_line_release(motor2_line);
    }
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

