/*
 * sound_alarm.c — Raspberry Pi 5 sound-triggered alarm using libgpiod + ZeroMQ
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o sound_alarm sound_alarm.c -lgpiod -lzmq -lpthread
 *
 * Usage:
 *   ./sound_alarm sound_sensor   # Poll LM393 DO on GPIO17, publish alerts
 *   ./sound_alarm alarm_node     # Subscribe to alerts, light LED on GPIO27
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <zmq.h>

#define SOUND_SENSOR_MODE "sound_sensor"
#define ALARM_NODE_MODE   "alarm_node"

#define GPIO_CHIP_NAME    "gpiochip4"   /* RP1 GPIO controller on Pi 5 */
#define SOUND_SENSOR_PIN  17            /* LM393 DO  (active-low) */
#define ALARM_LED_PIN     27            /* Alarm LED */

#define ZMQ_BIND_ADDRESS  "tcp://*:5555"
#define ZMQ_CONNECT_ADDR  "tcp://localhost:5555"
#define ZMQ_TOPIC         "SOUND_ALERTS"
#define POLL_INTERVAL_MS  10
#define ALARM_DURATION_S  1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
/* Sound sensor mode                                                   */
/* ------------------------------------------------------------------ */
static int sound_sensor_node(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    void *context = NULL;
    void *publisher = NULL;
    int rc = EXIT_FAILURE;

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get DO line */
    line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", SOUND_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request line as input */
    if (gpiod_line_request_input(line, "sound_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n", SOUND_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    /* Initialize ZeroMQ context */
    context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "Failed to create ZeroMQ context: %s\n", strerror(errno));
        goto cleanup;
    }

    publisher = zmq_socket(context, ZMQ_PUB);
    if (!publisher) {
        fprintf(stderr, "Failed to create publisher socket: %s\n", strerror(errno));
        goto cleanup;
    }

    if (zmq_bind(publisher, ZMQ_BIND_ADDRESS) < 0) {
        fprintf(stderr, "Failed to bind ZeroMQ socket: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Sound sensor node started. Polling GPIO%d every %d ms.\n",
           SOUND_SENSOR_PIN, POLL_INTERVAL_MS);

    while (g_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %s\n", SOUND_SENSOR_PIN, strerror(errno));
            break;
        }

        /* LM393 DO is active-low: 0 => sound above threshold detected */
        if (val == 0) {
            time_t now = time(NULL);
            char timestamp[32];
            char message[256];
            int msg_len;

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                     localtime(&now));

            msg_len = snprintf(message, sizeof(message),
                               "%s - Sound detected on GPIO%d", timestamp, SOUND_SENSOR_PIN);
            if (msg_len < 0 || (size_t)msg_len >= sizeof(message)) {
                fprintf(stderr, "Message formatting failed\n");
                break;
            }

            if (zmq_send(publisher, ZMQ_TOPIC, strlen(ZMQ_TOPIC), ZMQ_SNDMORE) < 0) {
                fprintf(stderr, "Failed to send topic: %s\n", strerror(errno));
                break;
            }
            if (zmq_send(publisher, message, msg_len, 0) < 0) {
                fprintf(stderr, "Failed to send message: %s\n", strerror(errno));
                break;
            }
            printf("Alert published: %s\n", message);
        }

        sleep_ms(POLL_INTERVAL_MS);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (publisher)
        zmq_close(publisher);
    if (context)
        zmq_ctx_destroy(context);
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);

    return rc;
}

/* ------------------------------------------------------------------ */
/* Alarm node mode                                                     */
/* ------------------------------------------------------------------ */
static int alarm_node(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    void *context = NULL;
    void *subscriber = NULL;
    int rc = EXIT_FAILURE;

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get LED line */
    line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", ALARM_LED_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request line as output, initial value 0 */
    if (gpiod_line_request_output(line, "alarm_node", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", ALARM_LED_PIN, strerror(errno));
        goto cleanup;
    }

    /* Initialize ZeroMQ context */
    context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "Failed to create ZeroMQ context: %s\n", strerror(errno));
        goto cleanup;
    }

    subscriber = zmq_socket(context, ZMQ_SUB);
    if (!subscriber) {
        fprintf(stderr, "Failed to create subscriber socket: %s\n", strerror(errno));
        goto cleanup;
    }

    if (zmq_connect(subscriber, ZMQ_CONNECT_ADDR) < 0) {
        fprintf(stderr, "Failed to connect to ZeroMQ: %s\n", strerror(errno));
        goto cleanup;
    }

    if (zmq_setsockopt(subscriber, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC)) < 0) {
        fprintf(stderr, "Failed to set subscription: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Alarm node started. Subscribing to %s on %s\n", ZMQ_TOPIC, ZMQ_CONNECT_ADDR);

    while (g_running) {
        zmq_msg_t topic_msg, content_msg;
        int more;
        size_t topic_len, content_len;

        zmq_msg_init(&topic_msg);
        zmq_msg_init(&content_msg);

        if (zmq_msg_recv(&topic_msg, subscriber, 0) < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "Failed to receive topic: %s\n", strerror(errno));
            break;
        }

        if (zmq_msg_recv(&content_msg, subscriber, 0) < 0) {
            fprintf(stderr, "Failed to receive content: %s\n", strerror(errno));
            zmq_msg_close(&topic_msg);
            break;
        }

        topic_len   = zmq_msg_size(&topic_msg);
        content_len = zmq_msg_size(&content_msg);

        char *topic   = malloc(topic_len + 1);
        char *content = malloc(content_len + 1);

        if (!topic || !content) {
            fprintf(stderr, "Out of memory\n");
            free(topic);
            free(content);
            zmq_msg_close(&topic_msg);
            zmq_msg_close(&content_msg);
            break;
        }

        memcpy(topic,   zmq_msg_data(&topic_msg),   topic_len);
        memcpy(content, zmq_msg_data(&content_msg), content_len);
        topic[topic_len]   = '\0';
        content[content_len] = '\0';

        if (strcmp(topic, ZMQ_TOPIC) == 0) {
            printf("Alert received: %s\n", content);

            if (gpiod_line_set_value(line, 1) < 0) {
                fprintf(stderr, "Failed to turn on LED: %s\n", strerror(errno));
            } else {
                sleep_ms(ALARM_DURATION_S * 1000);
                if (gpiod_line_set_value(line, 0) < 0) {
                    fprintf(stderr, "Failed to turn off LED: %s\n", strerror(errno));
                }
            }
        }

        free(topic);
        free(content);
        zmq_msg_close(&topic_msg);
        zmq_msg_close(&content_msg);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (subscriber)
        zmq_close(subscriber);
    if (context)
        zmq_ctx_destroy(context);
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);

    return rc;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return EXIT_FAILURE;
    }

    if (strcmp(argv[1], SOUND_SENSOR_MODE) == 0) {
        struct sigaction sa;
        memset(&sa, 0, sizeof(sa));
        sa.sa_handler = sig_handler;
        sigemptyset(&sa.sa_mask);
        sa.sa_flags = 0;
        if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
            fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }
        return sound_sensor_node();
    } else if (strcmp(argv[1], ALARM_NODE_MODE) == 0) {
        struct sigaction sa;
        memset(&sa, 0, sizeof(sa));
        sa.sa_handler = sig_handler;
        sigemptyset(&sa.sa_mask);
        sa.sa_flags = 0;
        if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
            fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }
        return alarm_node();
    } else {
        fprintf(stderr, "Invalid mode: %s\n", argv[1]);
        return EXIT_FAILURE;
    }
}

