#define MQTT_TOPIC "ir/decoded"
#define MQTT_CLIENT_ID "ir_decoder"
#define MAX_PULSES 100

static volatile sig_atomic_t running = 1;
static uint32_t pulses[MAX_PULSES];
static int pulse_count = 0;
static uint32_t last_tick = 0;
static MQTTClient mqtt_client;
static int mqtt_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void ir_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level != 0) return;

    uint32_t diff = tick - last_tick;
    last_tick = tick;

    if (pulse_count < MAX_PULSES) {
        pulses[pulse_count++] = diff;
    } else {
        syslog(LOG_ERR, "Pulse buffer overflow, resetting");
        pulse_count = 0;
    }
}

static int decode_nec(uint32_t *address, uint32_t *command) {
    if (pulse_count < 68) return -1;

    uint32_t header_mark = pulses[0];
    uint32_t header_space = pulses[1];

    if (header_mark < 7000 || header_mark > 8000) return -1;
    if (header_space < 4000 || header_space > 5000) return -1;

    uint32_t addr = 0, cmd = 0, inv_addr = 0, inv_cmd = 0;

    for (int i = 0; i < 32; i++) {
        uint32_t mark = pulses[2 + i * 2];
        uint32_t space = pulses[3 + i * 2];

        if (mark < 400 || mark > 700) return -1;

        if (space > 1400) {
            if (i < 16) addr |= (1 << i);
            else cmd |= (1 << (i - 16));
        } else if (space > 400) {
            if (i < 16) inv_addr |= (1 << i);
            else inv_cmd |= (1 << (i - 16));
        } else {
            return -1;
        }
    }

    if ((addr & 0xFF) != (~inv_addr & 0xFF)) return -1;
    if ((cmd & 0xFF) != (~inv_cmd & 0xFF)) return -1;

    *address = addr;
    *command = cmd;
    return 0;
}

static void publish_mqtt(uint32_t address, uint32_t command) {
    if (!mqtt_initialized) return;

    cJSON *root = cJSON_CreateObject();
    if (!root) {
        syslog(LOG_ERR, "Failed to create JSON object");
        return;
    }

    cJSON_AddNumberToObject(root, "address", (double)address);
    cJSON_AddNumberToObject(root, "command", (double)command);

    char *json_string = cJSON_PrintUnformatted(root);
    if (!json_string) {
        syslog(LOG_ERR, "Failed to print JSON");
        cJSON_Delete(root);
        return;
    }

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = json_string;
    pubmsg.payloadlen = (int)strlen(json_string);
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish MQTT message: %s", MQTTClient_strerror(rc));
    }

    free(json_string);
    cJSON_Delete(root);
}

int main() {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return 1;
    }

    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);

    if (gpioSetAlertFunc(IR_GPIO, ir_callback) != 0) {
        syslog(LOG_ERR, "Failed to set alert function");
        gpioTerminate();
        closelog();
        return 1;
    }

    int rc = MQTTClient_create(&mqtt_client, MQTT_BROKER, MQTT_CLIENT_ID,
                               MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "Failed to create MQTT client: %s", MQTTClient_strerror(rc));
    } else {
        MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
        conn_opts.keepAliveInterval = 20;
        conn_opts.cleansession = 1;

        rc = MQTTClient_connect(mqtt_client, &conn_opts);
        if (rc != MQTTCLIENT_SUCCESS) {
            syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", MQTTClient_strerror(rc));
        } else {
            mqtt_initialized = 1;
            syslog(LOG_INFO, "MQTT client connected to broker");
        }
    }

    syslog(LOG_INFO, "IR decoder started on GPIO %d", IR_GPIO);

    while (running) {
        if (pulse_count >= 68) {
            uint32_t address, command;
            if (decode_nec(&address, &command) == 0) {
                syslog(LOG_INFO, "Decoded NEC: Address=0x%08X, Command=0x%08X", address, command);
                publish_mqtt(address, command);
            }
            pulse_count = 0;
        }
        gpioDelay(10000);
        if (mqtt_initialized) {
            rc = MQTTClient_yield();
            if (rc != MQTTCLIENT_SUCCESS) {
                syslog(LOG_ERR, "MQTT yield error: %s", MQTTClient_strerror(rc));
            }
        }
    }

    syslog(LOG_INFO, "Shutting down...");

    if (mqtt_initialized) {
        MQTTClient_disconnect(mqtt_client, 1000);
        MQTTClient_destroy(&mqtt_client);
    }

    gpioTerminate();
    closelog();
    return 0;
}

