#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_CMD_OT_HRES 0x20
#define BH1750_CONV_MS 180
#define NUM_SENSORS    4
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define SAMPLE_MS     1000

static const int sensor_addrs[NUM_SENSORS] = {0x23, 0x24, 0x25, 0x26};

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    return fd;
}

static int i2c_set_slave(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int fd, int addr) {
    if (i2c_set_slave(fd, addr) < 0)
        return -1;

    unsigned char cmd = BH1750_CMD_OT_HRES;
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "write(0x%02X): %s\n", addr, w < 0 ? strerror(errno) : "short write");
        return -1;
    }

    usleep(BH1750_CONV_MS * 1000);

    unsigned char data[2];
    ssize_t r = read(fd, data, 2);
    if (r != 2) {
        fprintf(stderr, "read(0x%02X): %s\n", addr, r < 0 ? strerror(errno) : "short read");
        return -1;
    }

    int raw = ((data[0] << 8) | data[1]);
    return (int)(raw / 1.2);
}

static int send_multicast(int sockfd, const float lux[NUM_SENSORS]) {
    char buffer[256];
    int len = 0;
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (len > 0)
            len += snprintf(buffer + len, sizeof(buffer) - len, ";");
        len += snprintf(buffer + len, sizeof(buffer) - len, "%d,%.1f", i + 1, lux[i]);
    }
    if (len < 0 || (size_t)len >= sizeof(buffer)) {
        fprintf(stderr, "buffer overflow\n");
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(sockfd, buffer, len, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    int i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0)
        return 1;

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "socket: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int ttl = 1;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "setsockopt(IP_MULTICAST_TTL): %s\n", strerror(errno));
        close(sockfd);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float lux[NUM_SENSORS];
        for (int i = 0; i < NUM_SENSORS; i++) {
            int v = bh1750_read_lux(i2c_fd, sensor_addrs[i]);
            lux[i] = (v < 0) ? NAN : (float)v;
        }

        if (send_multicast(sockfd, lux) < 0)
            fprintf(stderr, "multicast send failed\n");

        usleep(SAMPLE_MS * 1000);
    }

    close(sockfd);
    close(i2c_fd);
    return 0;
}

