#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE      "/dev/i2c-1"
#define AWM7300V_ADDR   0x28
#define LOG_FILE        "airflow_log.txt"
#define SAMPLE_PERIOD_S 1
#define MAX_RETRIES     3
#define RETRY_DELAY_MS  100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void msleep(unsigned ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int i2c_write_zero(int fd)
{
    uint8_t buf[0];
    ssize_t n = write(fd, buf, 0);
    if (n < 0) {
        fprintf(stderr, "I2C write-zero failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int read_flow_rate(int fd, float *flow_out)
{
    uint8_t data[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_zero(fd) < 0) {
            retries++;
            msleep(RETRY_DELAY_MS);
            continue;
        }
        if (i2c_read_bytes(fd, data, sizeof(data)) < 0) {
            retries++;
            msleep(RETRY_DELAY_MS);
            continue;
        }

        uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
        raw &= 0x3FFF;

        if (raw == 0x3FFF) {
            fprintf(stderr, "Warning: sensor returned 0x3FFF (invalid/overflow)\n");
            return -1;
        }

        *flow_out = ((float)raw - 3277.0f) * 0.1f;
        return 0;
    }

    fprintf(stderr, "Failed to read flow rate after %d retries\n", MAX_RETRIES);
    return -1;
}

static void log_flow_rate(FILE *fp, float flow_rate)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f SLPM\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, flow_rate);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AWM7300V_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                AWM7300V_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float flow_rate;
        if (read_flow_rate(g_i2c_fd, &flow_rate) == 0) {
            log_flow_rate(log_fp, flow_rate);
            printf("Flow rate: %.2f SLPM\n", flow_rate);
        } else {
            fprintf(stderr, "Failed to read flow rate\n");
        }
        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down...\n");
    fflush(log_fp);
    fclose(log_fp);
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

