        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float flow_rate;
        if (read_flow_rate(g_i2c_fd, &flow_rate) == 0) {
            log_flow_rate(log_fp, flow_rate);
            printf("Flow rate: %.2f SLPM\n", flow_rate);
        } else {
            fprintf(stderr, "Failed to read flow rate\n");
        }
        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down...\n");
    fflush(log_fp);
    fclose(log_fp);
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

