#define RETRY_DELAY_MS 10
#define TIMESTAMP_LEN 32

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *data_file = NULL;
static FILE *error_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", t);
}

static void log_error(const char *msg) {
    char ts[TIMESTAMP_LEN];
    get_timestamp(ts, sizeof(ts));
    if (error_file) {
        fprintf(error_file, "%s: %s (errno: %d - %s)\n", ts, msg, errno, strerror(errno));
        fflush(error_file);
    }
    fprintf(stderr, "%s: %s (errno: %d - %s)\n", ts, msg, errno, strerror(errno));
}

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) return -1;
    return 0;
}

static int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t reg = D7S_REG_ACCEL;
    uint8_t buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_byte(fd, reg) < 0) {
            log_error("I2C write (register select) failed");
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (i2c_read_bytes(fd, buf, 6) < 0) {
            log_error("I2C read (acceleration data) failed");
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
        int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
        int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
        *x = (float)raw_x * D7S_ACCEL_SCALE;
        *y = (float)raw_y * D7S_ACCEL_SCALE;
        *z = (float)raw_z * D7S_ACCEL_SCALE;
        return 0;
    }
    return -1;
}

static int log_data(FILE *f, float x, float y, float z) {
    char ts[TIMESTAMP_LEN];
    get_timestamp(ts, sizeof(ts));
    if (fprintf(f, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z) < 0) return -1;
    fflush(f);
    return 0;
}

int main(int argc, char *argv[]) {
    int i2c_address = D7S_DEFAULT_ADDR;
    int interval = 1;
    const char *filename = "seismic_data.csv";
    int opt;

    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a': i2c_address = (int)strtol(optarg, NULL, 0); break;
            case 'i': interval = atoi(optarg); break;
            case 'f': filename = optarg; break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_addr] [-i interval_s] [-f filename]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    error_file = fopen("seismic_error.log", "a");
    if (!error_file) {
        perror("fopen(seismic_error.log)");
        return EXIT_FAILURE;
    }

    data_file = fopen(filename, "a");
    if (!data_file) {
        log_error("fopen(data_file)");
        fclose(error_file);
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("open(/dev/i2c-1)");
        fclose(data_file);
        fclose(error_file);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        log_error("ioctl(I2C_SLAVE)");
        close(i2c_fd);
        fclose(data_file);
        fclose(error_file);
        return EXIT_FAILURE;
    }

    printf("Seismic data logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float x, y, z;
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            if (log_data(data_file, x, y, z) < 0) {
                log_error("log_data failed");
            }
        } else {
            log_error("Failed to read acceleration after retries");
        }
        sleep(interval);
    }

    printf("\nShutting down gracefully...\n");
    if (i2c_fd >= 0) close(i2c_fd);
    if (data_file) fclose(data_file);
    if (error_file) fclose(error_file);
    return EXIT_SUCCESS;
}

