#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE      "/dev/i2c-1"
#define BH1750_ADDR     0x23
#define BH1750_PWR_ON   0x01
#define BH1750_CONT_HRES 0x10
#define BH1750_MEAS_MS  180
#define MULTICAST_ADDR  "239.255.255.250"
#define MULTICAST_PORT  5000
#define MULTICAST_TTL   1
#define SAMPLE_MS       1000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, unsigned char cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16_be(int fd, unsigned short *out) {
    unsigned char buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read failed: expected 2 bytes, got %zd (%s)\n", n, strerror(errno));
        return -1;
    }
    *out = ((unsigned short)buf[0] << 8) | buf[1];
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_cmd(fd, BH1750_PWR_ON) < 0) return -1;
    usleep(10000);
    if (i2c_write_cmd(fd, BH1750_CONT_HRES) < 0) return -1;
    return 0;
}

static float bh1750_read_lux(int fd) {
    unsigned short raw;
    if (i2c_read16_be(fd, &raw) < 0) return -1.0f;
    return (float)raw / 1.2f;
}

static int send_udp_multicast(float lux) {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }

    int ttl = MULTICAST_TTL;
    if (setsockopt(sock, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("setsockopt(IP_MULTICAST_TTL)");
        close(sock);
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(MULTICAST_PORT);
    if (inet_pton(AF_INET, MULTICAST_ADDR, &addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid multicast address: %s\n", MULTICAST_ADDR);
        close(sock);
        return -1;
    }

    char buffer[32];
    int len = snprintf(buffer, sizeof(buffer), "%.2f", lux);
    if (len < 0 || (size_t)len >= sizeof(buffer)) {
        fprintf(stderr, "Buffer formatting failed\n");
        close(sock);
        return -1;
    }

    if (sendto(sock, buffer, (size_t)len, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
        close(sock);
        return -1;
    }

    close(sock);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open(" I2C_DEVICE ")");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(fd);
        return EXIT_FAILURE;
    }

    if (bh1750_init(fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed (sensor may be absent at 0x%02X)\n", BH1750_ADDR);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("BH1750 initialized at 0x%02X. Broadcasting lux values to %s:%d\n",
           BH1750_ADDR, MULTICAST_ADDR, MULTICAST_PORT);

    while (g_running) {
        float lux = bh1750_read_lux(fd);
        if (lux < 0.0f) {
            fprintf(stderr, "Read error, retrying in 1 second...\n");
        } else {
            printf("Lux: %.2f\n", lux);
            if (send_udp_multicast(lux) < 0) {
                fprintf(stderr, "UDP send failed, continuing...\n");
            }
        }
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

