#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define CSV_FILE "radar_data.csv"
#define MAX_OBJECTS 100
#define MAX_FRAME_SIZE 8192
#define READ_CHUNK 512

/* TI mmWave TLV magic word: 0x0204 0x0306 0x0805 0x0709 (little-endian) */
static const uint8_t MAGIC_WORD[8] = {0x02, 0x04, 0x03, 0x06, 0x08, 0x05, 0x07, 0x09};

typedef struct {
    float range;
    float velocity;
} RadarObject;

static volatile sig_atomic_t terminate = 0;
static int uart_handle = -1;
static FILE *csv_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (uart_handle >= 0) {
        serClose(uart_handle);
        uart_handle = -1;
    }
    if (csv_file != NULL) {
        fflush(csv_file);
        fclose(csv_file);
        csv_file = NULL;
    }
    gpioTerminate();
}

/*
 * Synchronize on the 8-byte magic word.
 * Returns 0 on success, -1 if EOF or buffer exhausted without finding magic.
 */
static int sync_magic(uint8_t *buf, int len) {
    if (len < 8) return -1;
    for (int i = 0; i <= len - 8; i++) {
        if (memcmp(buf + i, MAGIC_WORD, 8) == 0) return 0;
    }
    return -1;
}

/*
 * Parse a complete TLV frame.
 * Frame layout (little-endian, all fields uint32_t):
 *   [8-byte magic] [4-byte version][4-byte total_packet_len]
 *   [4-byte platform][4-byte frame_number][4-byte time_cpt][4-byte num_detected_obj]
 *   [4-byte num_tlvs][4-byte subframe_num][4-byte chirp_processing_time][4-byte num_rx_enabled]
 *   [4-byte padding][4-byte padding][4-byte padding][4-byte padding]
 *   [num_detected_obj * 8 bytes: range(mm) + velocity(mm/s)]
 * Each TLV: [4-byte type][4-byte length][length bytes payload]
 */
static int parse_frame(const uint8_t *frame, int frame_len, RadarObject *objects, int *num_objects) {
    if (frame_len < 64) {
        fprintf(stderr, "Frame too short for header: %d bytes\n", frame_len);
        return -1;
    }

    uint32_t num_detected_obj = *(const uint32_t *)(frame + 32);
    if (num_detected_obj > MAX_OBJECTS) {
        fprintf(stderr, "Too many objects (%u), skipping frame\n", num_detected_obj);
        return -1;
    }

    int offset = 64;
    int tlv_count = *(const uint32_t *)(frame + 40);

