        ssize_t bytes_read = read(g_uart_fd, read_buf, sizeof(read_buf) - 1);
        if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            fprintf(stderr, "read() error: %s\n", strerror(errno));
            break;
        }
        if (bytes_read == 0) {
            fprintf(stderr, "UART closed by peer\n");
            break;
        }

        read_buf[bytes_read] = '\0';

        for (ssize_t i = 0; i < bytes_read; i++) {
            char c = read_buf[i];
            if (c == '\n') {
                line_buf[line_len] = '\0';
                if (line_len > 0) {
                    process_line(line_buf);
                }
                line_len = 0;
            } else if (c != '\r') {
                if (line_len < LINE_BUF_SIZE - 1) {
                    line_buf[line_len++] = c;
                } else {
                    fprintf(stderr, "Line buffer overflow, discarding\n");
                    line_len = 0;
                }
            }
        }
    }

    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }

    printf("\nExiting gracefully.\n");
    return 0;
}

