#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define LEFT_SENSOR   4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR  27
#define SERIAL_PORT   "/dev/ttyAMA0"
#define BAUD_RATE     115200
#define LOOP_DELAY_US 100000  /* 100 ms = 10 Hz */

static volatile sig_atomic_t running = 1;
static int serial_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

static void send_emergency_stop(void) {
    const char *message = "EMERGENCY STOP!\n";
    int result = serWrite(serial_handle, message, strlen(message));
    if (result < 0) {
        fprintf(stderr, "Error writing to serial port: %s\n", pigpio_error(result));
    } else {
        printf("Emergency stop signal sent.\n");
    }
}

int main(void) {
    int left, middle, right;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LEFT_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set LEFT_SENSOR mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MIDDLE_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set MIDDLE_SENSOR mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RIGHT_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set RIGHT_SENSOR mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(LEFT_SENSOR, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set LEFT_SENSOR pull-up\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(MIDDLE_SENSOR, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set MIDDLE_SENSOR pull-up\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set RIGHT_SENSOR pull-up\n");
        gpioTerminate();
        return 1;
    }

    serial_handle = serOpen(SERIAL_PORT, BAUD_RATE, 0);
    if (serial_handle < 0) {
        fprintf(stderr, "Error opening serial port %s: %s\n", SERIAL_PORT, pigpio_error(serial_handle));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        serClose(serial_handle);
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        serClose(serial_handle);
        gpioTerminate();
        return 1;
    }

    printf("KY-033 Tracking Sensor Monitoring Started. Press Ctrl+C to exit.\n");

    while (running) {
        left = read_sensor(LEFT_SENSOR);
        middle = read_sensor(MIDDLE_SENSOR);
        right = read_sensor(RIGHT_SENSOR);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Sensor read error, skipping cycle\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        log_sensor_data(left, middle, right);

        if (left == 0 && middle == 0 && right == 0) {
            send_emergency_stop();
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (serial_handle >= 0) {
        serClose(serial_handle);
    }
    gpioTerminate();
    return 0;
}

